private enum PhotoLibraryTransferError: LocalizedError {
    case noData

    var errorDescription: String? {
        "照片没有可读取的图片数据"
    }
}

private enum ImageTranslationManagedFileKind {
    case input
    case staging
    case stableExport
}

private struct ImageTranslationIgnoredBlockSnapshot {
    let block: ImageTranslationBlock
    let originalOrder: Int
    let visionOriginalBlock: ImageTranslationBlock?
    let wasManuallyCorrected: Bool
}

private struct ImageTranslationBatch {
    let startIndex: Int
    let blocks: [ImageTranslationBlock]
}

/// Transient identity-only plan for one Japanese image page. The block values
/// remain mutable (correction, scoped reread, ignore/restore), but the batch
/// boundaries used by read-only translation context stay anchored to the
/// original page until a structural edit deliberately invalidates the plan.
private struct ImageTranslationBatchPlan {
    let startIndex: Int
    let blockIDs: [UUID]
}

private struct ImageTranslationJapanesePrompt {
    let startIndex: Int
    let context: TranslationPromptContext
}

private enum ImageMangaBatchTranslationError: LocalizedError {
    case missingTags
    case unexpectedTags
    case emptyTranslation
    case qualityFailure([Int])

    var errorDescription: String? {
        switch self {
        case .missingTags:
            "漫画批翻译没有返回完整的编号文本块"
        case .unexpectedTags:
            "漫画批翻译返回了错误的编号顺序"
        case .emptyTranslation:
            "漫画批翻译返回了空文本块"
        case .qualityFailure(let ids):
            "漫画批翻译质量检查失败，待补译文本块：\(ids.map(String.init).joined(separator: ","))"
        }
    }

    var isQualityFailure: Bool {
        if case .qualityFailure = self { return true }
        return false
    }
}

