    var imageTranslationProgressTitle: String {
        switch imageTranslationState {
        case .idle: "待选择"
        case .loading: "载入中"
        case .recognizing: "OCR 中"
        case .translating: "翻译中"
        case .translated: "已完成"
        case .failed: "失败"
        }
