    var imageTranslationSummary: String {
        let summary = ImageOCRResultSummary(blocks: imageTranslationBlocks)
        guard summary.totalBlockCount > 0 else { return "0 个文本块" }

        var parts = ["\(summary.translatedBlockCount)/\(summary.totalBlockCount) 个文本块"]
        if let averageConfidence = summary.averageConfidence {
            parts.append("平均 \(averageConfidence.formatted(.percent.precision(.fractionLength(0))))")
        }
        if summary.lowConfidenceBlockCount > 0 {
            parts.append("低置信 \(summary.lowConfidenceBlockCount)")
        }
        if summary.horizontalBlockCount > 0 {
            parts.append("横排 \(summary.horizontalBlockCount)")
        }
        if summary.verticalBlockCount > 0 {
            parts.append("竖排 \(summary.verticalBlockCount)")
        }
        if summary.unknownDirectionBlockCount > 0 {
            parts.append("方向待定 \(summary.unknownDirectionBlockCount)")
        }
        if summary.reviewRequiredBlockCount > 0 {
            parts.append("待复查 \(summary.reviewRequiredBlockCount)")
        }
        return parts.joined(separator: " · ")
    }

    func toggleRecording() {
        isRecording.toggle()
        if isRecording {
            startTicker()
            Task { await injectMockLiveLine() }
        } else {
            ticker?.cancel()
            ticker = nil
            persist()
        }
    }

    func submitDraft() {
        let trimmed = draftText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, !isProcessing else { return }
        guard canUseLanguage(targetLanguage) else {
            dataTransferMessage = "\(targetLanguage.rawValue) 属于 Pro 翻译语言"
            return
        }

        isProcessing = true
        let timestamp = Self.timeFormatter.string(from: Date())

        Task { [weak self] in
            await self?.submit(trimmed, timestamp: timestamp)
        }
    }

    func recognizeAudioFileAndTranslate(from url: URL) {
        guard !isProcessing else { return }
        guard isProUnlocked else {
            audioRecognitionState = .failed
            audioRecognitionMessage = "音频离线识别测试需要 Pro"
            dataTransferMessage = audioRecognitionMessage
            return
        }
        audioRecognitionTask?.cancel()

        let capability = currentSpeechCapability
        let runID = beginSpeechRecognitionRun(
            mode: .audioFile,
            inputName: url.lastPathComponent,
            capability: capability
        )
        guard capability.supportsOnDeviceRecognition else {
            audioRecognitionState = .failed
            audioRecognitionMessage = "\(sourceLanguage.rawValue) 当前设备未报告支持 Apple 本机语音识别，断网测试不能保证成功"
            failSpeechRecognitionRun(audioRecognitionMessage)
            dataTransferMessage = audioRecognitionMessage
            return
        }

        let didAccess = url.startAccessingSecurityScopedResource()
        defer {
            if didAccess {
                url.stopAccessingSecurityScopedResource()
            }
        }

        let localAudioURL: URL
        do {
            localAudioURL = try copyAudioFileIntoSandbox(url)
        } catch {
            audioRecognitionState = .failed
            audioRecognitionMessage = "音频文件复制失败：\(error.localizedDescription)"
            failSpeechRecognitionRun(audioRecognitionMessage)
            dataTransferMessage = audioRecognitionMessage
            return
        }

        audioRecognitionState = .checking
        audioRecognitionMessage = "正在请求 Apple Speech 权限"

        SFSpeechRecognizer.requestAuthorization { [weak self] status in
            Task { @MainActor [weak self] in
                guard let self else { return }
                guard self.speechRecognitionRunID == runID else { return }

                guard status == .authorized else {
                    self.audioRecognitionState = .failed
                    self.audioRecognitionMessage = "Apple Speech 权限未授权，无法测试本机识别"
                    self.failSpeechRecognitionRun(self.audioRecognitionMessage)
                    self.dataTransferMessage = self.audioRecognitionMessage
                    return
                }

                self.startOnDeviceAudioRecognition(localAudioURL, capability: capability, runID: runID)
            }
        }
    }

    func beginProLiveSpeechCapture() {
        guard isProUnlocked else {
            audioRecognitionState = .failed
            audioRecognitionMessage = "同声传译需要 Pro"
            dataTransferMessage = audioRecognitionMessage
            return
        }
        guard !isCapturingProSpeech else { return }
        guard !isProcessing else {
            audioRecognitionMessage = "当前翻译任务完成后再开始语音识别"
            dataTransferMessage = audioRecognitionMessage
            return
        }

        let capability = currentSpeechCapability
        let runID = beginSpeechRecognitionRun(
            mode: .liveMicrophone,
            inputName: "实时麦克风",
            capability: capability
        )
        guard capability.supportsOnDeviceRecognition else {
            audioRecognitionState = .failed
            audioRecognitionMessage = "\(sourceLanguage.rawValue) 当前设备未报告支持 Apple 本机语音识别"
            failSpeechRecognitionRun(audioRecognitionMessage)
            dataTransferMessage = audioRecognitionMessage
            return
        }

        isProLiveSpeechCaptureRequested = true
        audioRecognitionState = .checking
        audioRecognitionMessage = "正在请求麦克风和 Speech 权限"

        SFSpeechRecognizer.requestAuthorization { [weak self] speechStatus in
            Task { @MainActor [weak self] in
                guard let self else { return }
                guard self.speechRecognitionRunID == runID else { return }
                guard speechStatus == .authorized else {
                    self.isProLiveSpeechCaptureRequested = false
                    self.audioRecognitionState = .failed
                    self.audioRecognitionMessage = "Apple Speech 权限未授权"
                    self.failSpeechRecognitionRun(self.audioRecognitionMessage)
                    self.dataTransferMessage = self.audioRecognitionMessage
                    return
                }

                let microphoneGranted = await self.requestMicrophoneAccess()
                guard self.speechRecognitionRunID == runID,
                      self.isProLiveSpeechCaptureRequested else { return }
                guard microphoneGranted else {
                    self.isProLiveSpeechCaptureRequested = false
                    self.audioRecognitionState = .failed
                    self.audioRecognitionMessage = "麦克风权限未授权"
                    self.failSpeechRecognitionRun(self.audioRecognitionMessage)
                    self.dataTransferMessage = self.audioRecognitionMessage
                    return
                }

                self.startProLiveSpeechRecognition(capability: capability, runID: runID)
            }
        }
    }

    func endProLiveSpeechCapture() {
        isProLiveSpeechCaptureRequested = false
        guard isCapturingProSpeech || liveAudioEngine != nil || liveSpeechRecognitionRequest != nil else {
            if audioRecognitionState == .checking {
                audioRecognitionState = .idle
                audioRecognitionMessage = "语音识别已取消"
                invalidateSpeechRecognitionRun()
                failSpeechRecognitionRun("用户取消")
                dataTransferMessage = audioRecognitionMessage
            }
            return
        }
        liveAudioEngine?.stop()
        liveAudioEngine?.inputNode.removeTap(onBus: 0)
        liveSpeechRecognitionRequest?.endAudio()
        liveAudioEngine = nil
        liveSpeechRecognitionRequest = nil
        audioRecognitionTask?.cancel()
        audioRecognitionTask = nil
        speechTranslationTask?.cancel()
        speechTranslationTask = nil
        isCapturingProSpeech = false
        audioRecognitionState = proLiveTranscriptText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? .idle : .translated
        audioRecognitionMessage = proLiveTranscriptText.isEmpty ? "未识别到语音" : "识别完成，可点击翻译"
        finishSpeechRecognitionRun(
            finalText: proLiveTranscriptText,
            failureMessage: proLiveTranscriptText.isEmpty ? "未识别到语音" : nil
        )
        invalidateSpeechRecognitionRun()
    }

    func translateProLiveTranscript() {
        let text = proLiveTranscriptText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty, !isProcessing else { return }
        guard isProUnlocked else {
            audioRecognitionMessage = "同声传译需要 Pro"
            dataTransferMessage = audioRecognitionMessage
            return
        }

        let runID = beginSpeechTranslationRun()
        isProcessing = true
        audioRecognitionState = .translating
        audioRecognitionMessage = "正在翻译识别文本"
        speechTranslationTask = Task { @MainActor [weak self] in
            guard let self else { return }

            do {
                let translation = try await self.translate(text)
                guard !Task.isCancelled, self.speechRecognitionRunID == runID else { return }
                self.proLiveTranslationText = translation
                self.draftText = text
                self.transcript.insert(
                    TranscriptLine(
                        speaker: "Pro Live",
                        original: text,
                        translation: translation,
                        time: Self.timeFormatter.string(from: Date()),
                        isFinal: true
                    ),
                    at: 0
                )
                self.audioRecognitionState = .translated
                self.audioRecognitionMessage = "同声传译已完成"
                self.finishSpeechRecognitionRun(finalText: text)
                self.dataTransferMessage = self.audioRecognitionMessage
            } catch {
                guard !Task.isCancelled, self.speechRecognitionRunID == runID else { return }
                self.audioRecognitionState = .failed
                self.audioRecognitionMessage = "翻译失败：\(error.localizedDescription)"
                self.failSpeechRecognitionRun(self.audioRecognitionMessage)
                self.dataTransferMessage = self.audioRecognitionMessage
            }
            guard self.speechRecognitionRunID == runID else { return }
            self.speechTranslationTask = nil
            self.isProcessing = false
            self.persist()
            self.invalidateSpeechRecognitionRun()
        }
    }

    private func requestMicrophoneAccess() async -> Bool {
        await withCheckedContinuation { continuation in
            if #available(iOS 17.0, *) {
                AVAudioApplication.requestRecordPermission { granted in
                    continuation.resume(returning: granted)
                }
            } else {
                AVAudioSession.sharedInstance().requestRecordPermission { granted in
                    continuation.resume(returning: granted)
                }
            }
        }
    }

    private func startProLiveSpeechRecognition(capability: SpeechRecognitionCapability, runID: UUID) {
        guard isProLiveSpeechCaptureRequested, speechRecognitionRunID == runID else {
            audioRecognitionState = .idle
            audioRecognitionMessage = "语音识别已取消"
            failSpeechRecognitionRun("用户取消")
            dataTransferMessage = audioRecognitionMessage
            return
        }
        guard let recognizer = SFSpeechRecognizer(locale: Locale(identifier: capability.localeIdentifier)) else {
            isProLiveSpeechCaptureRequested = false
            audioRecognitionState = .failed
            audioRecognitionMessage = "无法创建 \(capability.localeIdentifier) 语音识别器"
            failSpeechRecognitionRun(audioRecognitionMessage)
            dataTransferMessage = audioRecognitionMessage
            return
        }

        audioRecognitionTask?.cancel()

        let audioEngine = AVAudioEngine()
        let request = SFSpeechAudioBufferRecognitionRequest()
        request.requiresOnDeviceRecognition = true
        request.shouldReportPartialResults = true

        let inputNode = audioEngine.inputNode
        let format = inputNode.outputFormat(forBus: 0)
        inputNode.installTap(onBus: 0, bufferSize: 1_024, format: format) { buffer, _ in
            request.append(buffer)
        }

        do {
            let session = AVAudioSession.sharedInstance()
            try session.setCategory(.record, mode: .measurement, options: [.duckOthers])
            try session.setActive(true, options: .notifyOthersOnDeactivation)
            audioEngine.prepare()
            try audioEngine.start()
        } catch {
            inputNode.removeTap(onBus: 0)
            isProLiveSpeechCaptureRequested = false
            audioRecognitionState = .failed
            audioRecognitionMessage = "麦克风启动失败：\(error.localizedDescription)"
            failSpeechRecognitionRun(audioRecognitionMessage)
            dataTransferMessage = audioRecognitionMessage
            return
        }

        liveAudioEngine = audioEngine
        liveSpeechRecognitionRequest = request
        isCapturingProSpeech = true
        proLiveTranscriptText = ""
        proLiveTranslationText = ""
        audioRecognitionState = .recognizing
        audioRecognitionMessage = "按住说话，松手结束"

        audioRecognitionTask = recognizer.recognitionTask(with: request) { [weak self] result, error in
            Task { @MainActor [weak self] in
                guard let self else { return }
                guard self.speechRecognitionRunID == runID else { return }

                if let result {
                    self.proLiveTranscriptText = result.bestTranscription.formattedString
                    self.updateSpeechRecognitionRun(from: result.bestTranscription, isFinal: result.isFinal)
                }

                if let error {
                    guard self.isCapturingProSpeech else { return }
                    self.endProLiveSpeechCapture()
                    self.audioRecognitionState = .failed
                    self.audioRecognitionMessage = "语音识别失败：\(error.localizedDescription)"
                    self.failSpeechRecognitionRun(self.audioRecognitionMessage)
                    self.dataTransferMessage = self.audioRecognitionMessage
                }
            }
        }
    }

    private func startOnDeviceAudioRecognition(
        _ url: URL,
        capability: SpeechRecognitionCapability,
        runID: UUID
    ) {
        guard speechRecognitionRunID == runID else { return }
        guard let recognizer = SFSpeechRecognizer(locale: Locale(identifier: capability.localeIdentifier)) else {
            audioRecognitionState = .failed
            audioRecognitionMessage = "无法创建 \(capability.localeIdentifier) 语音识别器"
            failSpeechRecognitionRun(audioRecognitionMessage)
            invalidateSpeechRecognitionRun()
            dataTransferMessage = audioRecognitionMessage
            return
        }

        isProcessing = true
        audioRecognitionState = .recognizing
        audioRecognitionMessage = "正在用 requiresOnDeviceRecognition 识别 \(url.lastPathComponent)"

        let request = SFSpeechURLRecognitionRequest(url: url)
        request.requiresOnDeviceRecognition = true
        request.shouldReportPartialResults = false

        audioRecognitionTask = recognizer.recognitionTask(with: request) { [weak self] result, error in
            Task { @MainActor [weak self] in
                guard let self else { return }
                guard self.speechRecognitionRunID == runID else { return }

                if let error {
                    self.audioRecognitionTask = nil
                    self.isProcessing = false
                    self.audioRecognitionState = .failed
                    self.audioRecognitionMessage = "本机语音识别失败：\(error.localizedDescription)"
                    self.failSpeechRecognitionRun(self.audioRecognitionMessage)
                    self.invalidateSpeechRecognitionRun()
                    self.dataTransferMessage = self.audioRecognitionMessage
                    return
                }

                guard let result, result.isFinal else { return }
                self.audioRecognitionTask = nil
                self.updateSpeechRecognitionRun(from: result.bestTranscription, isFinal: true, completedAt: Date())

                let text = result.bestTranscription.formattedString.trimmingCharacters(in: .whitespacesAndNewlines)
                guard !text.isEmpty else {
                    self.isProcessing = false
                    self.audioRecognitionState = .failed
                    self.audioRecognitionMessage = "语音识别完成，但没有得到文本"
                    self.failSpeechRecognitionRun(self.audioRecognitionMessage)
                    self.invalidateSpeechRecognitionRun()
                    self.dataTransferMessage = self.audioRecognitionMessage
                    return
                }

                self.lastRecognizedSpeechText = text
                self.draftText = text
                self.audioRecognitionState = .translating
                self.audioRecognitionMessage = "识别成功，正在交给翻译模型"

                let timestamp = Self.timeFormatter.string(from: Date())
                self.startAudioFileTranslation(text, timestamp: timestamp, runID: runID)
            }
        }
    }

    private func startAudioFileTranslation(_ text: String, timestamp: String, runID: UUID) {
        speechTranslationTask?.cancel()
        speechTranslationTask = Task { @MainActor [weak self] in
            guard let self, self.speechRecognitionRunID == runID else { return }
            let didTranslate = await self.submit(
                text,
                timestamp: timestamp,
                expectedSpeechRunID: runID
            )
            guard !Task.isCancelled, self.speechRecognitionRunID == runID else { return }

            if didTranslate {
                self.audioRecognitionState = .translated
                self.audioRecognitionMessage = "已离线识别并完成翻译"
                self.finishSpeechRecognitionRun(finalText: text)
            } else {
                self.audioRecognitionState = .failed
                self.audioRecognitionMessage = "已离线识别出文字，但翻译模型处理失败"
                self.failSpeechRecognitionRun(self.audioRecognitionMessage)
            }
            self.speechTranslationTask = nil
            self.dataTransferMessage = self.audioRecognitionMessage
            self.invalidateSpeechRecognitionRun()
        }
    }

    func cancelAudioRecognition() {
        invalidateSpeechRecognitionRun()
        isProLiveSpeechCaptureRequested = false
        liveAudioEngine?.stop()
        liveAudioEngine?.inputNode.removeTap(onBus: 0)
        liveSpeechRecognitionRequest?.endAudio()
        liveAudioEngine = nil
        liveSpeechRecognitionRequest = nil
        audioRecognitionTask?.cancel()
        audioRecognitionTask = nil
        speechTranslationTask?.cancel()
        speechTranslationTask = nil
        isCapturingProSpeech = false
        isProcessing = false
        audioRecognitionState = .idle
        audioRecognitionMessage = "语音识别已取消"
        failSpeechRecognitionRun("用户取消")
        dataTransferMessage = audioRecognitionMessage
    }

    func runSpeechQualityProbe() {
        guard !isRunningSpeechQualityProbe else { return }

        speechQualityProbeTask?.cancel()
        speechQualityProbeService.cancel()
        let runID = UUID()
        speechQualityProbeRunID = runID
        isRunningSpeechQualityProbe = true
        speechQualityProbeReport = nil
        speechQualityProbeState = .loadingManifest
        speechQualityProbeMessage = "正在准备 Speech 质量语料"

        speechQualityProbeTask = Task { @MainActor [weak self] in
            guard let self else { return }
            let report = await self.speechQualityProbeService.run(
                corpusDirectory: self.speechQualityCorpusDirectory,
                outputDirectory: self.mangaOverlayOutputDirectory
            ) { [weak self] state, message in
                guard let self, self.speechQualityProbeRunID == runID else { return }
                self.speechQualityProbeState = state
                self.speechQualityProbeMessage = message
            }
            guard !Task.isCancelled, self.speechQualityProbeRunID == runID else { return }
            self.speechQualityProbeReport = report
            self.isRunningSpeechQualityProbe = false
            self.speechQualityProbeTask = nil
        }
    }

    func cancelSpeechQualityProbe() {
        guard isRunningSpeechQualityProbe else { return }
        speechQualityProbeRunID = UUID()
        speechQualityProbeTask?.cancel()
        speechQualityProbeTask = nil
        speechQualityProbeService.cancel()
        isRunningSpeechQualityProbe = false
        speechQualityProbeState = .cancelled
        speechQualityProbeMessage = "Speech 质量探针已取消"
    }

    private func beginSpeechRecognitionRun(
        mode: SpeechRecognitionRunMode,
        inputName: String,
        capability: SpeechRecognitionCapability
    ) -> UUID {
        speechTranslationTask?.cancel()
        speechTranslationTask = nil
        let runID = UUID()
        speechRecognitionRunID = runID
        speechRecognitionRunSummary = SpeechRecognitionRunSummary(
            mode: mode,
            inputName: inputName.isEmpty ? mode.displayName : inputName,
            localeIdentifier: capability.localeIdentifier,
            requiresOnDeviceRecognition: true,
            supportsOnDeviceRecognition: capability.supportsOnDeviceRecognition,
            runToken: String(runID.uuidString.prefix(8)),
            startedAt: Date(),
            completedAt: nil,
            transcriptPreview: "",
            wordCount: 0,
            segmentCount: 0,
            averageConfidence: nil,
            isFinal: false,
            failureMessage: nil
        )
        return runID
    }

    private func beginSpeechTranslationRun() -> UUID {
        speechTranslationTask?.cancel()
        let runID = UUID()
        speechRecognitionRunID = runID
        speechRecognitionRunSummary.runToken = String(runID.uuidString.prefix(8))
        speechRecognitionRunSummary.completedAt = nil
        speechRecognitionRunSummary.failureMessage = nil
        return runID
    }

    private func invalidateSpeechRecognitionRun() {
        speechRecognitionRunID = UUID()
    }

    private func updateSpeechRecognitionRun(
        from transcription: SFTranscription,
        isFinal: Bool,
        completedAt: Date? = nil
    ) {
        let text = transcription.formattedString.trimmingCharacters(in: .whitespacesAndNewlines)
        let segments = transcription.segments
        speechRecognitionRunSummary.transcriptPreview = text
        speechRecognitionRunSummary.wordCount = Self.speechTokenCount(in: text)
        speechRecognitionRunSummary.segmentCount = segments.count
        speechRecognitionRunSummary.averageConfidence = Self.averageConfidence(for: segments)
        speechRecognitionRunSummary.isFinal = isFinal
        speechRecognitionRunSummary.completedAt = completedAt
        speechRecognitionRunSummary.failureMessage = nil
    }

    private func finishSpeechRecognitionRun(finalText: String, failureMessage: String? = nil) {
        let text = finalText.trimmingCharacters(in: .whitespacesAndNewlines)
        if !text.isEmpty {
            speechRecognitionRunSummary.transcriptPreview = text
            speechRecognitionRunSummary.wordCount = Self.speechTokenCount(in: text)
        }
        speechRecognitionRunSummary.isFinal = failureMessage == nil
        speechRecognitionRunSummary.completedAt = Date()
        speechRecognitionRunSummary.failureMessage = failureMessage
    }

    private func failSpeechRecognitionRun(_ message: String) {
        speechRecognitionRunSummary.completedAt = Date()
        speechRecognitionRunSummary.isFinal = false
        speechRecognitionRunSummary.failureMessage = message
    }

    private static func averageConfidence(for segments: [SFTranscriptionSegment]) -> Double? {
        guard !segments.isEmpty else { return nil }
        let total = segments.reduce(0.0) { partialResult, segment in
            partialResult + min(max(Double(segment.confidence), 0), 1)
        }
        return total / Double(segments.count)
    }

    private static func speechTokenCount(in text: String) -> Int {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return 0 }

        let whitespaceTokens = trimmed.split { character in
            character.isWhitespace
        }
        if whitespaceTokens.count > 1 {
            return whitespaceTokens.count
        }

        if trimmed.range(of: "\\p{Han}", options: .regularExpression) != nil {
            return trimmed.unicodeScalars.filter { scalar in
                !CharacterSet.whitespacesAndNewlines.contains(scalar) &&
                !CharacterSet.punctuationCharacters.contains(scalar)
            }.count
        }

        return 1
    }

    private func copyAudioFileIntoSandbox(_ url: URL) throws -> URL {
        try FileManager.default.createDirectory(at: audioTestDirectory, withIntermediateDirectories: true)

        let cleanName = url.lastPathComponent.isEmpty ? "audio-input.m4a" : url.lastPathComponent
        let destination = audioTestDirectory.appendingPathComponent(cleanName)

        if FileManager.default.fileExists(atPath: destination.path) {
            try FileManager.default.removeItem(at: destination)
        }

        try FileManager.default.copyItem(at: url, to: destination)
        return destination
    }

    private func copyImageFileIntoSandbox(_ url: URL, taskID: UUID) async throws -> URL {
        let directory = imageTranslationDirectory
        let destinationName = "\(taskID.uuidString)-\(Self.sanitizedImageFilename(from: url))"

        let copiedURL = try await Task.detached(priority: .userInitiated) {
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)

            let destination = directory.appendingPathComponent(destinationName)
            let didAccess = url.startAccessingSecurityScopedResource()
            defer {
                if didAccess {
                    url.stopAccessingSecurityScopedResource()
                }
            }

            if FileManager.default.fileExists(atPath: destination.path) {
                try FileManager.default.removeItem(at: destination)
            }

            try FileManager.default.copyItem(at: url, to: destination)
            return destination
        }.value

        return copiedURL
    }

    private func writeImageDataIntoSandbox(
        _ data: Data,
        filename: String,
        taskID: UUID
    ) async throws -> URL {
        let directory = imageTranslationDirectory
        let cleanName = Self.sanitizedImageFilename(
            filename.isEmpty ? "photo-library-image.png" : filename
        )
        let destinationName = "\(taskID.uuidString)-\(cleanName)"

        return try await Task.detached(priority: .userInitiated) {
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            let destination = directory.appendingPathComponent(destinationName)
            if FileManager.default.fileExists(atPath: destination.path) {
                try FileManager.default.removeItem(at: destination)
            }
            try data.write(to: destination, options: .atomic)
            return destination
        }.value
    }

    private func beginImageTranslationTask(
        filename: String,
        sourceLanguage: SupportedLanguage,
        targetLanguage: SupportedLanguage,
        preservingSourceURL: URL? = nil
    ) -> UUID {
        imageTranslationTask?.cancel()
        imageTranslationBlockRetryTask?.cancel()
        imageTranslationBlockRetryTask = nil
        invalidateImageTranslationBlockRetry()
        imageTranslationBlockRerecognitionTask?.cancel()
        imageTranslationBlockRerecognitionTask = nil
        invalidateImageTranslationBlockRerecognition()
        invalidateImageTranslationCorrection()
        imageTranslationFileSelectionID = nil
        invalidateImageOverlayRender()
        if imageTranslationSourceURL != preservingSourceURL {
            removeImageTranslationInputFile(
                imageTranslationSourceURL,
                directory: imageTranslationDirectory
            )
        }
        discardImageTranslationExport()
        let taskID = UUID()
        imageTranslationTaskID = taskID
        imageTranslationContentSourceLanguage = sourceLanguage
        imageTranslationContentTargetLanguage = targetLanguage
        imageTranslationRetrySourceLanguage = nil
        imageTranslationRetryTargetLanguage = nil
        imageTranslationBlockRerecognitionCompletedBlockID = nil
        imageTranslationState = .loading
        imageTranslationMessage = "正在载入图片"
        imageTranslationBlocks = []
        imageTranslationCorrectedBlockIDs = []
        imageTranslationReviewedBlockIDs = []
        imageTranslationIgnoredBlocks = []
        imageTranslationVisionOriginalBlocks = [:]
        imageTranslationIgnoredBlockSnapshots = [:]
        imageTranslationOriginalBlockOrder = [:]
        imageTranslationJapaneseBatchPlan = []
        imageTranslationTranscriptLineID = nil
        imageTranslationData = nil
        imageTranslationSourceURL = nil
        imageTranslationRevision += 1
        imageTranslationFilename = filename
        isProcessing = true
        persist()
        return taskID
    }

    private func isCurrentImageTranslationTask(_ taskID: UUID) -> Bool {
        imageTranslationTaskID == taskID && !Task.isCancelled
    }

    private func imageOCRRecognitionMessage(for sourceLanguage: SupportedLanguage) -> String {
        if sourceLanguage == .japanese {
            return "正在用本机 Manga OCR 与 Vision 识别日语文字，复查竖排方向与文字块位置"
        }
        return "正在用 Vision 本机 OCR 识别文字和位置"
    }

    private func runImageTranslationPipeline(
        with data: Data,
        taskID: UUID,
        sourceLanguage: SupportedLanguage,
        targetLanguage: SupportedLanguage
    ) async throws {
        guard isCurrentImageTranslationTask(taskID) else { throw CancellationError() }
        imageTranslationData = data
        imageTranslationRevision += 1
        imageTranslationState = .recognizing
        imageTranslationMessage = imageOCRRecognitionMessage(for: sourceLanguage)

        let recognizedBlocks = try await visionOCRService.recognizeTextBlocks(
            in: data,
            sourceLanguage: sourceLanguage
        )
        try Task.checkCancellation()
        guard isCurrentImageTranslationTask(taskID) else { throw CancellationError() }

        guard !recognizedBlocks.isEmpty else {
            imageTranslationState = .failed
            imageTranslationMessage = "本机 OCR 没有识别到可翻译文字"
            dataTransferMessage = imageTranslationMessage
            isProcessing = false
            return
        }

        imageTranslationOriginalBlockOrder = Dictionary(
            uniqueKeysWithValues: recognizedBlocks.enumerated().map { index, block in
                (block.id, index)
            }
        )
        imageTranslationBlocks = recognizedBlocks
        imageTranslationState = .translating
        imageTranslationMessage = sourceLanguage == .japanese
            ? "已识别 \(recognizedBlocks.count) 个日语文本块，正在按漫画文本组翻译为\(targetLanguage.rawValue)"
            : "已识别 \(recognizedBlocks.count) 个文本块，正在翻译为\(targetLanguage.rawValue)"

        var translatedBlocks = recognizedBlocks
        if sourceLanguage == .japanese {
            let batches = Self.imageTranslationBatches(recognizedBlocks)
            imageTranslationJapaneseBatchPlan = Self.imageTranslationBatchPlans(from: batches)
            var translatedCount = 0
            var previousBatchSummary: TranslationReadOnlyBatchSummary?
            for batch in batches {
                try Task.checkCancellation()
                guard isCurrentImageTranslationTask(taskID) else { throw CancellationError() }
                let batchTextKinds = batch.blocks.map { $0.textKind ?? .dialogue }
                let translations = try await translateJapaneseImageBatch(
                    batch.blocks,
                    startIndex: batch.startIndex,
                    sourceLanguage: sourceLanguage,
                    targetLanguage: targetLanguage,
                    translationContext: TranslationPromptContext(
                        confirmedTerms: translationTermMemory,
                        previousBatchSummary: previousBatchSummary,
                        textKind: batchTextKinds.first ?? .dialogue,
                        batchTextKinds: batchTextKinds,
                        batchStartIndex: batch.startIndex
                    )
                )
                guard translations.count == batch.blocks.count else {
                    throw ImageMangaBatchTranslationError.missingTags
                }
                for (offset, translation) in translations.enumerated() {
                    translatedBlocks[batch.startIndex + offset].translation = translation
                }
                previousBatchSummary = TranslationReadOnlyBatchSummary(
                    batchID: "image-\(taskID.uuidString)-\(batch.startIndex)",
                    sourceLanguage: sourceLanguage,
                    targetLanguage: targetLanguage,
                    items: batch.blocks.enumerated().map { offset, block in
                        TranslationReadOnlyBatchItem(
                            ordinal: batch.startIndex + offset + 1,
                            sourceExcerpt: block.original,
                            targetExcerpt: translations[offset],
                            kind: block.textKind ?? .dialogue
                        )
                    }
                )
                translatedCount += translations.count
                guard isCurrentImageTranslationTask(taskID) else { throw CancellationError() }
                imageTranslationBlocks = translatedBlocks
                imageTranslationMessage = "正在按漫画文本组翻译 \(translatedCount)/\(recognizedBlocks.count) 个日语文本块"
            }
        } else {
            for (index, block) in recognizedBlocks.enumerated() {
                try Task.checkCancellation()
                guard isCurrentImageTranslationTask(taskID) else { throw CancellationError() }
                translatedBlocks[index].translation = try await translateImageBlockWithQA(
                    block,
                    sourceLanguage: sourceLanguage,
                    targetLanguage: targetLanguage,
                    translationContext: TranslationPromptContext(
                        confirmedTerms: translationTermMemory,
                        textKind: block.textKind ?? .dialogue
                    )
                )
                guard isCurrentImageTranslationTask(taskID) else { throw CancellationError() }
                imageTranslationBlocks = Array(translatedBlocks.prefix(index + 1))
                    + Array(recognizedBlocks.dropFirst(index + 1))
                imageTranslationMessage = "正在翻译 \(index + 1)/\(recognizedBlocks.count) 个文本块"
            }
        }

        imageTranslationBlocks = translatedBlocks
        let renderedMode = imageOverlayMode
        let renderID = UUID()
        imageOverlayRenderID = renderID
        let stagedExportURL = try? await Self.renderImageTranslationOverlay(
            imageData: data,
            blocks: translatedBlocks,
            filename: imageTranslationFilename,
            directory: imageTranslationDirectory,
            mode: renderedMode,
            renderID: renderID
        )
        guard isCurrentImageTranslationTask(taskID) else {
            removeImageTranslationStagingFile(
                stagedExportURL,
                directory: imageTranslationDirectory
            )
            throw CancellationError()
        }
        if imageOverlayRenderID == renderID,
           imageOverlayMode == renderedMode,
           let stagedExportURL {
            defer {
                removeImageTranslationStagingFile(
                    stagedExportURL,
                    directory: imageTranslationDirectory
                )
            }
            if let outputURL = try? Self.publishImageTranslationOverlay(
                stagedURL: stagedExportURL,
                filename: imageTranslationFilename,
                directory: imageTranslationDirectory,
                renderID: renderID
            ) {
                publishImageTranslationExport(outputURL)
            }
        } else {
            removeImageTranslationStagingFile(
                stagedExportURL,
                directory: imageTranslationDirectory
            )
            discardImageTranslationExport()
        }
        imageTranslationState = .translated
        imageTranslationMessage = imageTranslationExportURL == nil
            ? "已完成本机 OCR、\(targetLanguage.rawValue)翻译和定位覆盖"
            : "已完成本机 OCR、\(targetLanguage.rawValue)翻译和覆盖图导出"
        dataTransferMessage = imageTranslationMessage
        appendImageTranslationTranscript(blocks: translatedBlocks)
        isProcessing = false
        imageTranslationTask = nil
        if imageOverlayMode != renderedMode {
            rerenderImageTranslationExport()
        }
        persist()
    }

    private func finishImageTranslation(taskID: UUID, with error: Error) {
        guard imageTranslationTaskID == taskID else { return }

        if error is CancellationError {
            imageTranslationState = .idle
            imageTranslationMessage = "图片翻译已取消"
            dataTransferMessage = imageTranslationMessage
            isProcessing = false
            imageTranslationTask = nil
            persist()
            return
        }

        imageTranslationState = .failed
        imageTranslationMessage = "图片翻译失败：\(error.localizedDescription)"
        dataTransferMessage = imageTranslationMessage
        isProcessing = false
        imageTranslationTask = nil
        persist()
    }

    private func finishPhotoLibraryTransfer(taskID: UUID, with error: Error) {
        guard imageTranslationTaskID == taskID else { return }

        if error is CancellationError {
            imageTranslationState = .idle
            imageTranslationMessage = "照片读取已取消"
        } else {
            imageTranslationState = .failed
            imageTranslationMessage = "照片读取失败：\(error.localizedDescription)"
        }
        dataTransferMessage = imageTranslationMessage
        isProcessing = false
        imageTranslationTask = nil
        persist()
    }

    private func runImageTranslation(
        fromSandboxURL url: URL,
        taskID: UUID,
        sourceLanguage: SupportedLanguage,
        targetLanguage: SupportedLanguage
    ) {
        imageTranslationTask = Task { [weak self] in
            guard let self else { return }

            do {
                guard self.isCurrentImageTranslationTask(taskID) else { throw CancellationError() }
                let data = try await Self.loadSecurityScopedData(from: url)
                try await self.runImageTranslationPipeline(
                    with: data,
                    taskID: taskID,
                    sourceLanguage: sourceLanguage,
                    targetLanguage: targetLanguage
                )
            } catch {
                self.finishImageTranslation(taskID: taskID, with: error)
            }
        }
    }

    @discardableResult
    func requestImageTranslationAccess() -> Bool {
        guard isProUnlocked else {
            dataTransferMessage = "图片翻译需要 Pro"
            return false
        }
        return true
    }

    func translateImage(from url: URL) {
        guard isProUnlocked else {
            imageTranslationState = .failed
            imageTranslationMessage = "图片翻译需要 Pro"
            dataTransferMessage = imageTranslationMessage
            return
        }
        guard canUseLanguage(targetLanguage) else {
            imageTranslationState = .failed
            imageTranslationMessage = "\(targetLanguage.rawValue) 图片翻译需要 Pro"
            dataTransferMessage = imageTranslationMessage
            return
        }

        let cleanFilename = Self.sanitizedImageFilename(from: url)
        let selectedSourceLanguage = sourceLanguage
        let selectedTargetLanguage = targetLanguage
        let taskID = beginImageTranslationTask(
            filename: cleanFilename,
            sourceLanguage: selectedSourceLanguage,
            targetLanguage: selectedTargetLanguage
        )

        imageTranslationTask = Task { [weak self] in
            guard let self else { return }

            var unclaimedSandboxURL: URL?
            do {
                guard self.isCurrentImageTranslationTask(taskID) else { throw CancellationError() }
                let sandboxURL = try await self.copyImageFileIntoSandbox(url, taskID: taskID)
                unclaimedSandboxURL = sandboxURL
                try Task.checkCancellation()
                guard self.isCurrentImageTranslationTask(taskID) else {
                    self.removeImageTranslationInputFile(
                        sandboxURL,
                        directory: self.imageTranslationDirectory
                    )
                    unclaimedSandboxURL = nil
                    throw CancellationError()
                }
                self.imageTranslationSourceURL = sandboxURL
                unclaimedSandboxURL = nil

                let data = try await Self.loadSecurityScopedData(from: sandboxURL)
                try await self.runImageTranslationPipeline(
                    with: data,
                    taskID: taskID,
                    sourceLanguage: selectedSourceLanguage,
                    targetLanguage: selectedTargetLanguage
                )
            } catch {
                self.removeImageTranslationInputFile(
                    unclaimedSandboxURL,
                    directory: self.imageTranslationDirectory
                )
                self.finishImageTranslation(taskID: taskID, with: error)
            }
        }
    }

    func translateImageTransfer(
        filename: String,
        loadData: @escaping @Sendable () async throws -> Data?
    ) {
        guard isProUnlocked else {
            imageTranslationState = .failed
            imageTranslationMessage = "图片翻译需要 Pro"
            dataTransferMessage = imageTranslationMessage
            return
        }
        guard canUseLanguage(targetLanguage) else {
            imageTranslationState = .failed
            imageTranslationMessage = "\(targetLanguage.rawValue) 图片翻译需要 Pro"
            dataTransferMessage = imageTranslationMessage
            return
        }

        let cleanFilename = Self.sanitizedImageFilename(
            filename.isEmpty ? "photo-library-image.png" : filename
        )
        let selectedSourceLanguage = sourceLanguage
        let selectedTargetLanguage = targetLanguage
        let taskID = beginImageTranslationTask(
            filename: cleanFilename,
            sourceLanguage: selectedSourceLanguage,
            targetLanguage: selectedTargetLanguage
        )

        imageTranslationTask = Task { [weak self] in
            guard let self else { return }

            let data: Data
            do {
                guard self.isCurrentImageTranslationTask(taskID) else { throw CancellationError() }
                guard let loadedData = try await loadData() else {
                    throw PhotoLibraryTransferError.noData
                }
                data = loadedData
            } catch {
                self.finishPhotoLibraryTransfer(taskID: taskID, with: error)
                return
            }

            var unclaimedSandboxURL: URL?
            do {
                try Task.checkCancellation()
                guard self.isCurrentImageTranslationTask(taskID) else { throw CancellationError() }
                let sandboxURL = try await self.writeImageDataIntoSandbox(
                    data,
                    filename: cleanFilename,
                    taskID: taskID
                )
                unclaimedSandboxURL = sandboxURL
                try Task.checkCancellation()
                guard self.isCurrentImageTranslationTask(taskID) else {
                    self.removeImageTranslationInputFile(
                        sandboxURL,
                        directory: self.imageTranslationDirectory
                    )
                    unclaimedSandboxURL = nil
                    throw CancellationError()
                }
                self.imageTranslationSourceURL = sandboxURL
                unclaimedSandboxURL = nil
                try await self.runImageTranslationPipeline(
                    with: data,
                    taskID: taskID,
                    sourceLanguage: selectedSourceLanguage,
                    targetLanguage: selectedTargetLanguage
                )
            } catch {
                self.removeImageTranslationInputFile(
                    unclaimedSandboxURL,
                    directory: self.imageTranslationDirectory
                )
                self.finishImageTranslation(taskID: taskID, with: error)
            }
        }
    }

    func translateImageData(_ data: Data, filename: String) {
        translateImageTransfer(filename: filename) { data }
    }

    func beginImageFileSelection() -> UUID {
        let selectionID = UUID()
        imageTranslationFileSelectionID = selectionID
        return selectionID
    }

    func handleSelectedImageFile(_ result: Result<URL, Error>, selectionID: UUID) {
        guard imageTranslationFileSelectionID == selectionID else { return }
        imageTranslationFileSelectionID = nil

        switch result {
        case .success(let url):
            translateImage(from: url)
        case .failure(let error):
            if let cocoaError = error as? CocoaError,
               cocoaError.code == .userCancelled {
                return
            }
            let message = "图片文件选择失败：\(error.localizedDescription)"
            dataTransferMessage = message
            guard imageTranslationState == .idle,
                  imageTranslationData == nil else {
                return
            }
            imageTranslationState = .failed
            imageTranslationMessage = message
        }
    }

    func clearImageTranslation() {
        imageTranslationTask?.cancel()
        imageTranslationTask = nil
        imageTranslationBlockRetryTask?.cancel()
        imageTranslationBlockRetryTask = nil
        invalidateImageTranslationBlockRetry()
        imageTranslationBlockRerecognitionTask?.cancel()
        imageTranslationBlockRerecognitionTask = nil
        invalidateImageTranslationBlockRerecognition()
        invalidateImageTranslationCorrection()
        imageTranslationFileSelectionID = nil
        invalidateImageOverlayRender()
        removeImageTranslationInputFile(
            imageTranslationSourceURL,
            directory: imageTranslationDirectory
        )
        discardImageTranslationExport()
        imageTranslationTaskID = UUID()
        imageTranslationState = .idle
        imageTranslationMessage = "选择图片后，会用本机 OCR 识别文字并定位"
        imageTranslationBlocks = []
        imageTranslationCorrectedBlockIDs = []
        imageTranslationReviewedBlockIDs = []
        imageTranslationIgnoredBlocks = []
        imageTranslationVisionOriginalBlocks = [:]
        imageTranslationIgnoredBlockSnapshots = [:]
        imageTranslationOriginalBlockOrder = [:]
        imageTranslationJapaneseBatchPlan = []
        imageTranslationTranscriptLineID = nil
        imageTranslationData = nil
        imageTranslationFilename = ""
        imageTranslationSourceURL = nil
        imageTranslationContentSourceLanguage = nil
        imageTranslationContentTargetLanguage = nil
        imageTranslationRetrySourceLanguage = nil
        imageTranslationRetryTargetLanguage = nil
        imageTranslationBlockRerecognitionCompletedBlockID = nil
        imageTranslationRevision += 1
        isProcessing = false
        persist()
    }

    func prepareImageTranslationShareURL() async -> URL? {
        guard imageTranslationShareState != .preparing else { return nil }
        discardImageTranslationShareCopies()
        guard let sourceURL = imageTranslationExportURL?.standardizedFileURL else {
            let message = "没有可分享的图片导出"
            imageTranslationShareState = .failed(message)
            dataTransferMessage = message
            return nil
        }

        let requestID = UUID()
        imageTranslationShareRequestID = requestID
        imageTranslationShareState = .preparing
        let shareRoot = imageTranslationShareDirectory.standardizedFileURL
        let shareDirectory = shareRoot.appendingPathComponent(requestID.uuidString, isDirectory: true)
        let baseName = imageTranslationFilename.isEmpty
            ? "image-translation"
            : (imageTranslationFilename as NSString).deletingPathExtension
        let shareURL = shareDirectory.appendingPathComponent("\(baseName)-translated.png")

        do {
            try await Task.detached(priority: .userInitiated) {
                let fileManager = FileManager.default
                try fileManager.createDirectory(at: shareRoot, withIntermediateDirectories: true)
                try fileManager.createDirectory(at: shareDirectory, withIntermediateDirectories: false)
                do {
                    try fileManager.linkItem(at: sourceURL, to: shareURL)
                } catch {
                    try fileManager.copyItem(at: sourceURL, to: shareURL)
                }
            }.value

            guard imageTranslationShareRequestID == requestID,
                  imageTranslationExportURL?.standardizedFileURL == sourceURL else {
                retainImageTranslationShareDirectoryIfCleanupFails(
                    shareDirectory,
                    root: shareRoot
                )
                return nil
            }
            imageTranslationOwnedShareDirectories.insert(shareDirectory)
            imageTranslationShareState = .idle
            return shareURL
        } catch {
            retainImageTranslationShareDirectoryIfCleanupFails(shareDirectory, root: shareRoot)
            guard imageTranslationShareRequestID == requestID else { return nil }
            let message = "导出图准备失败：\(error.localizedDescription)"
            imageTranslationShareState = .failed(message)
            dataTransferMessage = message
            return nil
        }
    }

    func finishImageTranslationSharing() {
        discardImageTranslationShareCopies()
    }

    func setImageOverlayMode(_ mode: ImageTranslationOverlayMode) {
        guard imageTranslationExportRenderState != .rendering,
              imageOverlayMode != mode else { return }
        imageOverlayMode = mode
        rerenderImageTranslationExport()
        persist()
    }

    /// Structural review edits are terminal-session mutations. They never
    /// start OCR or translation work and are unavailable while a scoped task
    /// or export render could still commit an older block snapshot.
    var canEditImageTranslationStructure: Bool {
        imageTranslationState == .translated
            && imageTranslationExportRenderState != .rendering
            && imageTranslationTask == nil
            && imageTranslationCorrectionBlockID == nil
            && imageTranslationRetryingBlockID == nil
            && imageTranslationRerecognizingBlockID == nil
            && !imageTranslationBlocks.isEmpty
    }

    /// Report-only preflight for the current rectangular overlay. It is
    /// intentionally absent outside a completed session and never gates or
    /// rewrites the existing export renderer.
    var imageTranslationRenderSafetyReport: ImageTranslationRenderSafety.Report? {
        guard imageTranslationState == .translated else { return nil }
        return ImageTranslationRenderSafety.analyze(
            blocks: imageTranslationBlocks,
            overlayMode: imageOverlayMode
        )
    }

    /// Split one completed block at a user-supplied Character offset. The
    /// resulting blocks deliberately receive fresh identities and no
    /// automatic OCR baseline/provenance: their text and geometry are now
    /// reviewer-authored structure, not fresh OCR evidence. Existing
    /// translations are cleared so a stale sentence cannot be presented as a
    /// correct translation of either child.
    @discardableResult
    func splitImageTranslationBlock(_ blockID: UUID, atCharacterOffset offset: Int) -> Bool {
        guard canEditImageTranslationStructure,
              let blockIndex = imageTranslationBlocks.firstIndex(where: { $0.id == blockID }),
              let blockRect = imageTranslationBlocks[blockIndex].boundingBox.normalizedToUnit() else {
            imageTranslationCorrectionMessage = "当前文字块暂时无法拆分，请等待图片翻译完成"
            return false
        }

        let block = imageTranslationBlocks[blockIndex]
        let characters = Array(block.original)
        guard offset > 0, offset < characters.count else {
            imageTranslationCorrectionMessage = "拆分位置必须位于文字块中间"
            return false
        }

        let firstOriginal = String(characters.prefix(offset))
        let secondOriginal = String(characters.dropFirst(offset))
        guard !firstOriginal.isEmpty, !secondOriginal.isEmpty else {
            imageTranslationCorrectionMessage = "拆分后的文字块不能为空"
            return false
        }

        let ratio = Double(offset) / Double(characters.count)
        let splitDirection: ImageTextDirection = block.effectiveSourceDirection == .vertical
            ? .vertical
            : .horizontal
        let firstRect: NormalizedImageRect
        let secondRect: NormalizedImageRect
        if splitDirection == .vertical {
            let firstHeight = blockRect.height * ratio
            firstRect = NormalizedImageRect(
                x: blockRect.x,
                y: blockRect.y,
                width: blockRect.width,
                height: firstHeight
            )
            secondRect = NormalizedImageRect(
                x: blockRect.x,
                y: blockRect.y + firstHeight,
                width: blockRect.width,
                height: blockRect.height - firstHeight
            )
        } else {
            let firstWidth = blockRect.width * ratio
            firstRect = NormalizedImageRect(
                x: blockRect.x,
                y: blockRect.y,
                width: firstWidth,
                height: blockRect.height
            )
            secondRect = NormalizedImageRect(
                x: blockRect.x + firstWidth,
                y: blockRect.y,
                width: blockRect.width - firstWidth,
                height: blockRect.height
            )
        }
        guard firstRect.normalizedToUnit() != nil,
              secondRect.normalizedToUnit() != nil else {
            imageTranslationCorrectionMessage = "拆分后的文字框无效"
            return false
        }

        let firstBlock = Self.makeStructureMutationBlock(
            from: block,
            original: firstOriginal,
            boundingBox: firstRect,
            sourceDirection: block.sourceDirection,
            sourceDirectionOverride: block.sourceDirectionOverride,
            directionConfidence: block.directionConfidence,
            directionReason: "手动拆分文字块",
            textKind: block.textKind
        )
        let secondBlock = Self.makeStructureMutationBlock(
            from: block,
            original: secondOriginal,
            boundingBox: secondRect,
            sourceDirection: block.sourceDirection,
            sourceDirectionOverride: block.sourceDirectionOverride,
            directionConfidence: block.directionConfidence,
            directionReason: "手动拆分文字块",
            textKind: block.textKind
        )

        imageTranslationBlocks.replaceSubrange(
            blockIndex...blockIndex,
            with: [firstBlock, secondBlock]
        )
        imageTranslationReviewedBlockIDs.remove(blockID)
        imageTranslationCorrectedBlockIDs.remove(blockID)
        imageTranslationVisionOriginalBlocks.removeValue(forKey: blockID)
        rebuildImageTranslationOriginalBlockOrder()
        finalizeImageTranslationStructureMutation(
            message: "已拆分文字块；两个新块的译文需分别重新翻译"
        )
        return true
    }

    /// Merge two adjacent completed blocks in their current reading order.
    /// The merged block gets a fresh identity, conservative confidence, an
    /// axis-aligned union rect, and no stale translation/baseline/provenance.
    @discardableResult
    func mergeImageTranslationBlocks(_ firstBlockID: UUID, _ secondBlockID: UUID) -> Bool {
        guard canEditImageTranslationStructure,
              let firstIndex = imageTranslationBlocks.firstIndex(where: { $0.id == firstBlockID }),
              let secondIndex = imageTranslationBlocks.firstIndex(where: { $0.id == secondBlockID }),
              abs(firstIndex - secondIndex) == 1 else {
            imageTranslationCorrectionMessage = "只能合并当前阅读顺序中相邻的两个文字块"
            return false
        }

        let lowerIndex = min(firstIndex, secondIndex)
        let upperIndex = max(firstIndex, secondIndex)
        let firstBlock = imageTranslationBlocks[lowerIndex]
        let secondBlock = imageTranslationBlocks[upperIndex]
        guard let firstRect = firstBlock.boundingBox.normalizedToUnit(),
              let secondRect = secondBlock.boundingBox.normalizedToUnit() else {
            imageTranslationCorrectionMessage = "文字框无效，无法合并"
            return false
        }

        let left = min(firstRect.x, secondRect.x)
        let top = min(firstRect.y, secondRect.y)
        let right = max(firstRect.x + firstRect.width, secondRect.x + secondRect.width)
        let bottom = max(firstRect.y + firstRect.height, secondRect.y + secondRect.height)
        guard let unionRect = NormalizedImageRect(
            x: left,
            y: top,
            width: right - left,
            height: bottom - top
        ).normalizedToUnit() else {
            imageTranslationCorrectionMessage = "合并后的文字框无效"
            return false
        }

        let mergedDirection: ImageTextDirection?
        if firstBlock.effectiveSourceDirection == secondBlock.effectiveSourceDirection {
            mergedDirection = firstBlock.effectiveSourceDirection
        } else {
            mergedDirection = .unknown
        }
        let mergedOverride: ImageTextDirection? =
            firstBlock.sourceDirectionOverride == secondBlock.sourceDirectionOverride
            ? firstBlock.sourceDirectionOverride
            : nil
        let mergedConfidence = min(
            ImageOCRResultSummary.normalizedConfidence(firstBlock.confidence),
            ImageOCRResultSummary.normalizedConfidence(secondBlock.confidence)
        )
        let mergedTextKind: TranslationTextKind? =
            firstBlock.textKind?.rawValue == secondBlock.textKind?.rawValue
            ? firstBlock.textKind
            : nil
        let mergedBlock = Self.makeStructureMutationBlock(
            from: firstBlock,
            original: firstBlock.original + secondBlock.original,
            boundingBox: unionRect,
            confidence: mergedConfidence,
            sourceDirection: mergedDirection,
            sourceDirectionOverride: mergedOverride,
            directionConfidence: mergedDirection == .unknown ? nil : min(
                firstBlock.directionConfidence ?? 0,
                secondBlock.directionConfidence ?? 0
            ),
            directionReason: "手动合并文字块",
            textKind: mergedTextKind
        )

        imageTranslationBlocks.replaceSubrange(
            lowerIndex...upperIndex,
            with: [mergedBlock]
        )
        imageTranslationReviewedBlockIDs.remove(firstBlockID)
        imageTranslationReviewedBlockIDs.remove(secondBlockID)
        imageTranslationCorrectedBlockIDs.remove(firstBlockID)
        imageTranslationCorrectedBlockIDs.remove(secondBlockID)
        imageTranslationVisionOriginalBlocks.removeValue(forKey: firstBlockID)
        imageTranslationVisionOriginalBlocks.removeValue(forKey: secondBlockID)
        rebuildImageTranslationOriginalBlockOrder()
        finalizeImageTranslationStructureMutation(
            message: "已合并相邻文字块；合并块的译文需重新翻译"
        )
        return true
    }

    /// Move one active block to a final array index. This mutation preserves
    /// text, translations, OCR provenance, automatic baselines, and review
    /// IDs; only the current reading order and transcript/export order change.
    @discardableResult
    func moveImageTranslationBlock(_ blockID: UUID, to index: Int) -> Bool {
        guard canEditImageTranslationStructure,
              let currentIndex = imageTranslationBlocks.firstIndex(where: { $0.id == blockID }) else {
            imageTranslationCorrectionMessage = "当前文字块暂时无法调整顺序，请等待图片翻译完成"
            return false
        }

        var reorderedBlocks = imageTranslationBlocks
        let movedBlock = reorderedBlocks.remove(at: currentIndex)
        let destination = min(max(index, 0), reorderedBlocks.count)
        guard destination != currentIndex else { return true }
        reorderedBlocks.insert(movedBlock, at: destination)
        imageTranslationBlocks = reorderedBlocks
        rebuildImageTranslationOriginalBlockOrder()
        finalizeImageTranslationStructureMutation(
            message: "已调整图片文字块阅读顺序；现有 OCR、译文和复查进度已保留"
        )
        return true
    }

    /// Applies a reviewer-only writing-mode correction to one completed block.
    /// The detector/Vision direction remains available as provenance; only the
    /// effective direction consumed by review, preview, and export changes.
    @discardableResult
    func setImageTranslationBlockDirectionOverride(
        _ blockID: UUID,
        direction: ImageTextDirection?
    ) -> Bool {
        guard direction == nil || direction == .horizontal || direction == .vertical,
              imageTranslationCorrectionBlockID == nil,
              imageTranslationState == .translated,
              imageTranslationExportRenderState != .rendering,
              let blockIndex = imageTranslationBlocks.firstIndex(where: { $0.id == blockID }) else {
            imageTranslationCorrectionMessage = "当前文字块暂时无法设置方向，请等待图片翻译完成"
            return false
        }

        guard imageTranslationBlocks[blockIndex].sourceDirectionOverride != direction else {
            return true
        }

        var updatedBlock = imageTranslationBlocks[blockIndex]
        updatedBlock.sourceDirectionOverride = direction
        imageTranslationBlocks[blockIndex] = updatedBlock
        imageTranslationReviewedBlockIDs.remove(blockID)
        imageTranslationCorrectionMessage = nil
        imageTranslationMessage = direction == nil
            ? "已恢复 OCR 文字方向，正在更新导出图"
            : "已手动设置文字方向，正在更新导出图"
        updateImageTranslationTranscript(blocks: imageTranslationBlocks)
        invalidateImageOverlayRender()
        discardImageTranslationExport()
        rerenderImageTranslationExport()
        persist()
        return true
    }

    func retryImageTranslationExportRender() {
        guard case .failed = imageTranslationExportRenderState else { return }
        rerenderImageTranslationExport()
    }

    func cancelImageTranslation() {
        imageTranslationTask?.cancel()
        imageTranslationTask = nil
        imageTranslationBlockRetryTask?.cancel()
        imageTranslationBlockRetryTask = nil
        invalidateImageTranslationBlockRetry()
        imageTranslationBlockRerecognitionTask?.cancel()
        imageTranslationBlockRerecognitionTask = nil
        invalidateImageTranslationBlockRerecognition()
        invalidateImageTranslationCorrection()
        imageTranslationFileSelectionID = nil
        invalidateImageOverlayRender()
        imageTranslationReviewedBlockIDs = []
        imageTranslationBlockRerecognitionCompletedBlockID = nil
        imageTranslationTaskID = UUID()
        imageTranslationState = .idle
        imageTranslationMessage = "图片翻译已取消"
        dataTransferMessage = imageTranslationMessage
        isProcessing = false
        persist()
    }

    /// Cancel only the in-place OCR retry for one completed image block.
    /// Keep the image task identity, review progress, and translated session
    /// alive so the scoped cancellation catch can restore the previous state
    /// and publish its accessibility failure generation.
    func cancelImageTranslationBlockRerecognition() {
        guard imageTranslationRerecognizingBlockID != nil else { return }
        imageTranslationBlockRerecognitionTask?.cancel()
    }

    /// Cancel only the in-place translation retry for one image block. The
    /// scoped task catch restores the previous terminal state and leaves the
    /// other translations, OCR geometry, and review progress untouched.
    func cancelImageTranslationBlockRetry() {
        guard imageTranslationRetryingBlockID != nil else { return }
        imageTranslationBlockRetryTask?.cancel()
    }

    @discardableResult
    func markImageTranslationBlockReviewed(_ blockID: UUID) -> Bool {
        guard imageTranslationState == .translated,
              let block = imageTranslationBlocks.first(where: { $0.id == blockID }),
              ImageOCRResultSummary.requiresReview(block) else {
            return false
        }
        imageTranslationReviewedBlockIDs.insert(blockID)
        persist()
        return true
    }

    @discardableResult
    func reopenImageTranslationBlockReview(_ blockID: UUID) -> Bool {
        guard imageTranslationState == .translated,
              let block = imageTranslationBlocks.first(where: { $0.id == blockID }),
              ImageOCRResultSummary.requiresReview(block),
              imageTranslationReviewedBlockIDs.remove(blockID) != nil else {
            return false
        }
        persist()
        return true
    }

    func resetImageTranslationReviewProgress() {
        guard imageTranslationState == .translated else { return }
        imageTranslationReviewedBlockIDs = []
        persist()
    }

    @discardableResult
    func ignoreImageTranslationBlock(_ blockID: UUID) -> Bool {
        guard imageTranslationCorrectionBlockID == nil,
              imageTranslationState == .translated,
              imageTranslationIgnoredBlockSnapshots[blockID] == nil,
              let blockIndex = imageTranslationBlocks.firstIndex(where: { $0.id == blockID }) else {
            imageTranslationCorrectionMessage = "当前文字块无法忽略，请等待图片翻译完成"
            return false
        }

        let block = imageTranslationBlocks.remove(at: blockIndex)
        let wasManuallyCorrected = imageTranslationCorrectedBlockIDs.remove(blockID) != nil
        let visionOriginalBlock = imageTranslationVisionOriginalBlocks.removeValue(forKey: blockID)
        let snapshot = ImageTranslationIgnoredBlockSnapshot(
            block: block,
            originalOrder: imageTranslationOriginalBlockOrder[blockID] ?? blockIndex,
            visionOriginalBlock: visionOriginalBlock,
            wasManuallyCorrected: wasManuallyCorrected
        )
        imageTranslationIgnoredBlockSnapshots[blockID] = snapshot
        refreshImageTranslationIgnoredBlocks()
        imageTranslationReviewedBlockIDs.remove(blockID)
        imageTranslationCorrectionMessage = nil
        imageTranslationMessage = "已忽略此 OCR 文字块，正在更新导出图"
        synchronizeImageTranslationTranscript(blocks: imageTranslationBlocks)
        invalidateImageOverlayRender()
        discardImageTranslationExport()
        rerenderImageTranslationExport()
        persist()
        return true
    }

    @discardableResult
    func restoreIgnoredImageTranslationBlock(_ blockID: UUID) -> Bool {
        guard imageTranslationCorrectionBlockID == nil,
              imageTranslationState == .translated,
              let snapshot = imageTranslationIgnoredBlockSnapshots.removeValue(forKey: blockID) else {
            imageTranslationCorrectionMessage = "当前文字块无法恢复，请等待图片翻译完成"
            return false
        }

        let insertionIndex = imageTranslationBlocks.firstIndex { block in
            (imageTranslationOriginalBlockOrder[block.id] ?? Int.max) > snapshot.originalOrder
        } ?? imageTranslationBlocks.endIndex
        imageTranslationBlocks.insert(snapshot.block, at: insertionIndex)
        if snapshot.wasManuallyCorrected {
            imageTranslationCorrectedBlockIDs.insert(blockID)
        }
        if let visionOriginalBlock = snapshot.visionOriginalBlock {
            imageTranslationVisionOriginalBlocks[blockID] = visionOriginalBlock
        }
        imageTranslationReviewedBlockIDs.remove(blockID)
        refreshImageTranslationIgnoredBlocks()
        imageTranslationCorrectionMessage = nil
        imageTranslationMessage = "已恢复此 OCR 文字块，正在更新导出图"
        synchronizeImageTranslationTranscript(blocks: imageTranslationBlocks)
        invalidateImageOverlayRender()
        discardImageTranslationExport()
        rerenderImageTranslationExport()
        persist()
        return true
    }

    @discardableResult
    func restoreAllIgnoredImageTranslationBlocks() -> [UUID] {
        guard imageTranslationCorrectionBlockID == nil,
              imageTranslationState == .translated else {
            imageTranslationCorrectionMessage = "当前文字块无法恢复，请等待图片翻译完成"
            return []
        }

        let snapshots = imageTranslationIgnoredBlockSnapshots.values.sorted { lhs, rhs in
            if lhs.originalOrder == rhs.originalOrder {
                return lhs.block.id.uuidString < rhs.block.id.uuidString
            }
            return lhs.originalOrder < rhs.originalOrder
        }
        guard !snapshots.isEmpty else { return [] }

        for snapshot in snapshots {
            let insertionIndex = imageTranslationBlocks.firstIndex { block in
                (imageTranslationOriginalBlockOrder[block.id] ?? Int.max) > snapshot.originalOrder
            } ?? imageTranslationBlocks.endIndex
            imageTranslationBlocks.insert(snapshot.block, at: insertionIndex)
            if snapshot.wasManuallyCorrected {
                imageTranslationCorrectedBlockIDs.insert(snapshot.block.id)
            }
            if let visionOriginalBlock = snapshot.visionOriginalBlock {
                imageTranslationVisionOriginalBlocks[snapshot.block.id] = visionOriginalBlock
            }
            imageTranslationReviewedBlockIDs.remove(snapshot.block.id)
        }

        imageTranslationIgnoredBlockSnapshots.removeAll(keepingCapacity: true)
        refreshImageTranslationIgnoredBlocks()
        imageTranslationCorrectionMessage = nil
        imageTranslationMessage = "已恢复 \(snapshots.count) 个 OCR 文字块，正在更新导出图"
        synchronizeImageTranslationTranscript(blocks: imageTranslationBlocks)
        invalidateImageOverlayRender()
        discardImageTranslationExport()
        rerenderImageTranslationExport()
        persist()
        return snapshots.map(\.block.id)
    }

    func correctImageTranslationBlock(_ blockID: UUID, original correctedOriginal: String) async -> Bool {
        let correctedOriginal = correctedOriginal.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !correctedOriginal.isEmpty else {
            imageTranslationCorrectionMessage = "修正文字不能为空"
            return false
        }
        guard imageTranslationCorrectionBlockID == nil,
              imageTranslationState == .translated,
              let sourceLanguage = imageTranslationContentSourceLanguage,
              let targetLanguage = imageTranslationContentTargetLanguage,
              let blockIndex = imageTranslationBlocks.firstIndex(where: { $0.id == blockID }) else {
            imageTranslationCorrectionMessage = "当前文字块不可编辑，请等待图片翻译完成"
            return false
        }

        let currentBlock = imageTranslationBlocks[blockIndex]
        guard correctedOriginal != currentBlock.original else {
            imageTranslationCorrectionMessage = nil
            markImageTranslationBlockReviewed(blockID)
            return true
        }

        let correctionID = UUID()
        let contentTaskID = imageTranslationTaskID
        imageTranslationCorrectionID = correctionID
        imageTranslationCorrectionBlockID = blockID
        imageTranslationCorrectionMessage = nil
        imageTranslationState = .translating
        imageTranslationMessage = "正在重新翻译修正后的文字"

        do {
            let correctedTranslation: String
            if sourceLanguage == .japanese {
                var correctedBlock = currentBlock
                correctedBlock.original = correctedOriginal
                correctedBlock.translation = ""
                let prompt = japaneseImageTranslationPrompt(
                    for: blockID,
                    textKindOverride: correctedBlock.textKind
                )
                correctedTranslation = try await translateJapaneseImageBlockWithQA(
                    correctedBlock,
                    expectedID: prompt.startIndex + 1,
                    sourceLanguage: sourceLanguage,
                    targetLanguage: targetLanguage,
                    translationContext: prompt.context
                )
            } else {
                var correctedBlock = currentBlock
                correctedBlock.original = correctedOriginal
                correctedBlock.translation = ""
                correctedTranslation = try await translateImageBlockWithQA(
                    correctedBlock,
                    sourceLanguage: sourceLanguage,
                    targetLanguage: targetLanguage,
                    translationContext: TranslationPromptContext(
                        confirmedTerms: translationTermMemory,
                        textKind: correctedBlock.textKind ?? .dialogue
                    )
                )
            }
            guard imageTranslationCorrectionID == correctionID,
                  imageTranslationTaskID == contentTaskID,
                  let currentIndex = imageTranslationBlocks.firstIndex(where: { $0.id == blockID }),
                  imageTranslationBlocks[currentIndex].original == currentBlock.original else {
                return false
            }

            var correctedBlock = imageTranslationBlocks[currentIndex]
            if imageTranslationVisionOriginalBlocks[blockID] == nil {
                imageTranslationVisionOriginalBlocks[blockID] = currentBlock
            }
            correctedBlock.original = correctedOriginal
            correctedBlock.translation = correctedTranslation
            imageTranslationBlocks[currentIndex] = correctedBlock
            imageTranslationCorrectedBlockIDs.insert(blockID)
            imageTranslationCorrectionBlockID = nil
            imageTranslationCorrectionMessage = nil
            imageTranslationState = .translated
            markImageTranslationBlockReviewed(blockID)
            imageTranslationMessage = "文字已修正，正在更新导出图"
            updateImageTranslationTranscript(blocks: imageTranslationBlocks)
            invalidateImageOverlayRender()
            discardImageTranslationExport()
            rerenderImageTranslationExport()
            persist()
            return true
        } catch {
            guard imageTranslationCorrectionID == correctionID,
                  imageTranslationTaskID == contentTaskID else {
                return false
            }
            let message = "修正文字翻译失败：\(error.localizedDescription)"
            imageTranslationCorrectionBlockID = nil
            imageTranslationCorrectionMessage = message
            imageTranslationState = .translated
            imageTranslationMessage = message
            dataTransferMessage = message
            return false
        }
    }

    func restoreImageTranslationBlockToVisionOCR(_ blockID: UUID) -> Bool {
        guard imageTranslationCorrectionBlockID == nil,
              imageTranslationState == .translated,
              let originalBlock = imageTranslationVisionOriginalBlocks[blockID],
              let blockIndex = imageTranslationBlocks.firstIndex(where: { $0.id == blockID }) else {
            imageTranslationCorrectionMessage = "当前文字块无法恢复 Vision OCR 结果"
            return false
        }

        // OCR restoration should not erase a writing-mode decision made after
        // the correction snapshot was captured.
        var restoredBlock = originalBlock
        restoredBlock.sourceDirectionOverride = imageTranslationBlocks[blockIndex].sourceDirectionOverride
        imageTranslationBlocks[blockIndex] = restoredBlock
        imageTranslationVisionOriginalBlocks.removeValue(forKey: blockID)
        imageTranslationCorrectedBlockIDs.remove(blockID)
        imageTranslationReviewedBlockIDs.remove(blockID)
        imageTranslationCorrectionMessage = nil
        imageTranslationMessage = "已恢复 Vision OCR 结果，正在更新导出图"
        updateImageTranslationTranscript(blocks: imageTranslationBlocks)
        invalidateImageOverlayRender()
        discardImageTranslationExport()
        rerenderImageTranslationExport()
        persist()
        return true
    }

    private func invalidateImageTranslationCorrection() {
        imageTranslationCorrectionID = UUID()
        imageTranslationCorrectionBlockID = nil
        imageTranslationCorrectionMessage = nil
    }

    private func invalidateImageTranslationBlockRetry() {
        imageTranslationBlockRetryID = UUID()
        imageTranslationBlockRetryPreviousState = nil
        imageTranslationRetryingBlockID = nil
    }

    private func invalidateImageTranslationBlockRerecognition() {
        imageTranslationBlockRerecognitionID = UUID()
        imageTranslationRerecognizingBlockID = nil
    }

    private func invalidateImageOverlayRender() {
        imageOverlayRenderTask?.cancel()
        imageOverlayRenderTask = nil
        imageOverlayRenderID = UUID()
        imageTranslationExportRenderState = .idle
    }

    private func rerenderImageTranslationExport() {
        guard imageTranslationExportRenderState != .rendering,
              imageTranslationState == .translated,
              let data = imageTranslationData else {
            return
        }

        imageOverlayRenderTask?.cancel()
        let renderID = UUID()
        let contentTaskID = imageTranslationTaskID
        let mode = imageOverlayMode
        let blocks = imageTranslationBlocks
        let filename = imageTranslationFilename
        let directory = imageTranslationDirectory
        imageOverlayRenderID = renderID
        imageTranslationExportRenderState = .rendering
        discardImageTranslationExport()
        imageTranslationMessage = blocks.isEmpty
            ? "已忽略全部 OCR 文字块，正在生成原图导出"
            : "正在生成\(mode.rawValue)导出图"

        imageOverlayRenderTask = Task { [weak self] in
            guard let self else { return }
            var stagedURL: URL?
            do {
                stagedURL = try await Self.renderImageTranslationOverlay(
                    imageData: data,
                    blocks: blocks,
                    filename: filename,
                    directory: directory,
                    mode: mode,
                    renderID: renderID
                )
                try Task.checkCancellation()
                guard self.imageOverlayRenderID == renderID,
                      self.imageTranslationTaskID == contentTaskID,
                      self.imageOverlayMode == mode else {
                    self.removeImageTranslationStagingFile(stagedURL, directory: directory)
                    return
                }
                guard let stagedURL else {
                    let message = "\(mode.rawValue)导出图生成失败：没有可发布的暂存文件"
                    self.imageTranslationExportRenderState = .failed(message)
                    self.imageTranslationMessage = message
                    self.dataTransferMessage = message
                    self.imageOverlayRenderTask = nil
                    return
                }
                let outputURL = try Self.publishImageTranslationOverlay(
                    stagedURL: stagedURL,
                    filename: filename,
                    directory: directory,
                    renderID: renderID
                )
                self.publishImageTranslationExport(outputURL)
                self.imageTranslationExportRenderState = .idle
                self.imageTranslationMessage = "已更新\(mode.rawValue)预览和导出图"
                self.dataTransferMessage = self.imageTranslationMessage
                self.imageOverlayRenderTask = nil
            } catch is CancellationError {
                self.removeImageTranslationStagingFile(stagedURL, directory: directory)
                guard self.imageOverlayRenderID == renderID,
                      self.imageTranslationTaskID == contentTaskID else {
                    return
                }
                self.imageTranslationExportRenderState = .idle
                self.imageOverlayRenderTask = nil
                return
            } catch {
                self.removeImageTranslationStagingFile(stagedURL, directory: directory)
                guard self.imageOverlayRenderID == renderID,
                      self.imageTranslationTaskID == contentTaskID else {
                    return
                }
                let message = "\(mode.rawValue)预览已更新，导出图生成失败：\(error.localizedDescription)"
                self.imageTranslationExportRenderState = .failed(message)
                self.imageTranslationMessage = message
                self.dataTransferMessage = message
                self.imageOverlayRenderTask = nil
            }
        }
    }

    func retryImageTranslation() {
        guard let url = imageTranslationSourceURL,
              FileManager.default.fileExists(atPath: url.path) else {
            imageTranslationMessage = "没有可重试的图片文件"
            dataTransferMessage = imageTranslationMessage
            return
        }

        let sourceFilename = imageTranslationFilename.isEmpty
            ? Self.sanitizedImageFilename(from: url)
            : imageTranslationFilename
        let selectedSourceLanguage = imageTranslationRetrySourceLanguage
            ?? imageTranslationContentSourceLanguage
            ?? sourceLanguage
        let selectedTargetLanguage = imageTranslationRetryTargetLanguage
            ?? imageTranslationContentTargetLanguage
            ?? targetLanguage
        let taskID = beginImageTranslationTask(
            filename: sourceFilename,
            sourceLanguage: selectedSourceLanguage,
            targetLanguage: selectedTargetLanguage,
            preservingSourceURL: url
        )
        imageTranslationSourceURL = url
        runImageTranslation(
            fromSandboxURL: url,
            taskID: taskID,
            sourceLanguage: selectedSourceLanguage,
            targetLanguage: selectedTargetLanguage
        )
    }

    /// Retry one already-recognized image block. This deliberately never calls
    /// Vision OCR; successful blocks and their geometry stay untouched.
    func retryImageTranslationBlock(_ blockID: UUID) {
        guard canRetryImageTranslationBlock(blockID),
              let block = imageTranslationBlocks.first(where: { $0.id == blockID }),
              let sourceLanguage = imageTranslationContentSourceLanguage,
              let targetLanguage = imageTranslationContentTargetLanguage else {
            return
        }

        imageTranslationBlockRetryTask?.cancel()
        let retryID = UUID()
        let contentTaskID = imageTranslationTaskID
        let previousState = imageTranslationState
        imageTranslationBlockRetryID = retryID
        imageTranslationBlockRetryPreviousState = previousState
        imageTranslationRetryingBlockID = blockID
        imageTranslationState = .translating
        imageTranslationMessage = "正在重新翻译此文字块"
        isProcessing = true

        imageTranslationBlockRetryTask = Task { [weak self] in
            guard let self else { return }
            do {
                let translation: String
                if sourceLanguage == .japanese {
                    let prompt = self.japaneseImageTranslationPrompt(for: blockID)
                    translation = try await self.translateJapaneseImageBatch(
                        [block],
                        startIndex: prompt.startIndex,
                        sourceLanguage: sourceLanguage,
                        targetLanguage: targetLanguage,
                        translationContext: prompt.context
                    ).first ?? ""
                } else {
                    translation = try await self.translateImageBlockWithQA(
                        block,
                        sourceLanguage: sourceLanguage,
                        targetLanguage: targetLanguage,
                        translationContext: TranslationPromptContext(
                            confirmedTerms: self.translationTermMemory,
                            textKind: block.textKind ?? .dialogue
                        )
                    )
                }
                try Task.checkCancellation()
                let cleanTranslation = translation.trimmingCharacters(in: .whitespacesAndNewlines)
                guard !cleanTranslation.isEmpty else {
                    throw ImageMangaBatchTranslationError.emptyTranslation
                }
                guard self.imageTranslationBlockRetryID == retryID,
                      self.imageTranslationTaskID == contentTaskID,
                      self.imageTranslationRetryingBlockID == blockID,
                      let blockIndex = self.imageTranslationBlocks.firstIndex(where: { $0.id == blockID }),
                      self.imageTranslationBlocks[blockIndex].original == block.original else {
                    return
                }

                self.imageTranslationBlocks[blockIndex].translation = cleanTranslation
                self.imageTranslationRetryingBlockID = nil
                self.imageTranslationBlockRetryPreviousState = nil
                self.imageTranslationBlockRetryTask = nil
                self.isProcessing = false
                let remainingCount = self.imageTranslationBlocks.count(where: {
                    $0.translation.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                })
                self.updateImageTranslationTranscript(blocks: self.imageTranslationBlocks)
                if remainingCount == 0 {
                    self.imageTranslationState = .translated
                    self.imageTranslationMessage = "已完成全部图片文字块翻译，正在更新导出图"
                    self.imageTranslationBlockRetryCompletionGeneration &+= 1
                    self.invalidateImageOverlayRender()
                    self.discardImageTranslationExport()
                    self.rerenderImageTranslationExport()
                } else {
                    self.imageTranslationState = .failed
                    self.imageTranslationMessage = "已重新翻译此文字块，仍有 \(remainingCount) 个文字块等待翻译"
                    self.dataTransferMessage = self.imageTranslationMessage
                }
                self.persist()
            } catch is CancellationError {
                guard self.imageTranslationBlockRetryID == retryID,
                      self.imageTranslationTaskID == contentTaskID else { return }
                let restoredState = self.imageTranslationBlockRetryPreviousState ?? .failed
                self.imageTranslationRetryingBlockID = nil
                self.imageTranslationBlockRetryPreviousState = nil
                self.imageTranslationBlockRetryTask = nil
                self.imageTranslationState = restoredState
                self.imageTranslationMessage = "已取消此文字块翻译重试，保留其它译文和复查进度"
                self.dataTransferMessage = self.imageTranslationMessage
                self.isProcessing = false
                self.persist()
            } catch {
                guard self.imageTranslationBlockRetryID == retryID,
                      self.imageTranslationTaskID == contentTaskID else { return }
                self.imageTranslationRetryingBlockID = nil
                self.imageTranslationBlockRetryPreviousState = nil
                self.imageTranslationBlockRetryTask = nil
                self.isProcessing = false
                self.imageTranslationState = .failed
                self.imageTranslationMessage = "此文字块翻译失败：\(error.localizedDescription)"
                self.dataTransferMessage = self.imageTranslationMessage
                self.persist()
            }
        }
    }

    /// Re-recognize one existing OCR block in place using its current geometry,
    /// or an optional reviewer-provided normalized bbox. The old block is kept
    /// as the commit candidate until both crop OCR and its replacement
    /// translation succeed, so a weak model result, cancellation, or stale task
    /// cannot damage the completed image session.
    func rerecognizeImageTranslationBlock(
        _ blockID: UUID,
        boundingBox: NormalizedImageRect? = nil
    ) {
        guard canRerecognizeImageTranslationBlock(blockID),
              let data = imageTranslationData,
              let sourceLanguage = imageTranslationContentSourceLanguage,
              let targetLanguage = imageTranslationContentTargetLanguage,
              let block = imageTranslationBlocks.first(where: { $0.id == blockID }) else {
            return
        }

        let editedBoundingBox: NormalizedImageRect?
        if let boundingBox {
            guard let normalizedBoundingBox = boundingBox.normalizedToUnit() else {
                imageTranslationMessage = "文字框无效，未开始重新识别"
                dataTransferMessage = imageTranslationMessage
                return
            }
            editedBoundingBox = normalizedBoundingBox
        } else {
            editedBoundingBox = nil
        }

        var recognitionBlock = block
        if let editedBoundingBox {
            recognitionBlock.boundingBox = editedBoundingBox
        }

        imageTranslationBlockRerecognitionTask?.cancel()
        let requestID = UUID()
        let contentTaskID = imageTranslationTaskID
        let previousState = imageTranslationState
        imageTranslationBlockRerecognitionID = requestID
        imageTranslationRerecognizingBlockID = blockID
        imageTranslationState = .recognizing
        imageTranslationMessage = editedBoundingBox == nil
            ? "正在重新识别此图片文字块"
            : "正在按调整后的文字框重新识别此图片文字块"
        isProcessing = true

        imageTranslationBlockRerecognitionTask = Task { [weak self] in
            guard let self else { return }
            do {
                guard let recognized = try await self.visionOCRService.recognizeTextBlock(
                    in: data,
                    sourceLanguage: sourceLanguage,
                    block: recognitionBlock
                ) else {
                    throw VisionOCRServiceError.blockRecognitionFailed
                }
                try Task.checkCancellation()
                guard self.imageTranslationBlockRerecognitionID == requestID,
                      self.imageTranslationTaskID == contentTaskID,
                      self.imageTranslationRerecognizingBlockID == blockID,
                      let blockIndex = self.imageTranslationBlocks.firstIndex(where: { $0.id == blockID }),
                      self.imageTranslationBlocks[blockIndex] == block else {
                    return
                }

                let recognizedOriginal = recognized.original.trimmingCharacters(
                    in: .whitespacesAndNewlines
                )
                guard !recognizedOriginal.isEmpty else {
                    throw VisionOCRServiceError.blockRecognitionFailed
                }

                let cleanTranslation: String
                if recognizedOriginal == block.original
                    && !block.translation.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    cleanTranslation = block.translation.trimmingCharacters(in: .whitespacesAndNewlines)
                } else {
                    var translationBlock = recognized
                    translationBlock.original = recognizedOriginal
                    translationBlock.translation = ""
                    let translation: String
                    if sourceLanguage == .japanese {
                        let prompt = self.japaneseImageTranslationPrompt(
                            for: blockID,
                            textKindOverride: translationBlock.textKind
                        )
                        translation = try await self.translateJapaneseImageBlockWithQA(
                            translationBlock,
                            expectedID: prompt.startIndex + 1,
                            sourceLanguage: sourceLanguage,
                            targetLanguage: targetLanguage,
                            translationContext: prompt.context
                        )
                    } else {
                        translation = try await self.translateImageBlockWithQA(
                            translationBlock,
                            sourceLanguage: sourceLanguage,
                            targetLanguage: targetLanguage,
                            translationContext: TranslationPromptContext(
                                confirmedTerms: self.translationTermMemory,
                                textKind: translationBlock.textKind ?? .dialogue
                            )
                        )
                    }
                    cleanTranslation = translation.trimmingCharacters(in: .whitespacesAndNewlines)
                }
                guard !cleanTranslation.isEmpty else {
                    throw ImageMangaBatchTranslationError.emptyTranslation
                }
                try Task.checkCancellation()
                guard self.imageTranslationBlockRerecognitionID == requestID,
                      self.imageTranslationTaskID == contentTaskID,
                      self.imageTranslationRerecognizingBlockID == blockID,
                      let currentIndex = self.imageTranslationBlocks.firstIndex(where: { $0.id == blockID }),
                      self.imageTranslationBlocks[currentIndex] == block else {
                    return
                }

                var replacement = block
                replacement.original = recognizedOriginal
                replacement.translation = cleanTranslation
                replacement.confidence = recognized.confidence
                // The accepted scoped candidate owns the diagnostic OCR
                // provenance as well as the replacement text. Keeping the
                // old provenance would disclose the previous engine/crop or
                // rotation after a successful reread.
                replacement.ocrProvenance = recognized.ocrProvenance
                // Scoped OCR can change the Japanese text shape. Carry the
                // reconciled automatic SFX hint with the accepted OCR result;
                // otherwise this block would still be translated with its
                // stale pre-reread dialogue metadata.
                replacement.textKind = recognized.textKind
                applyEditedImageTranslationBoundingBox(
                    editedBoundingBox,
                    to: &replacement
                )
                self.imageTranslationBlocks[currentIndex] = replacement
                self.imageTranslationCorrectedBlockIDs.remove(blockID)
                self.imageTranslationVisionOriginalBlocks.removeValue(forKey: blockID)
                self.imageTranslationReviewedBlockIDs.remove(blockID)
                self.imageTranslationRerecognizingBlockID = nil
                self.imageTranslationBlockRerecognitionTask = nil
                self.isProcessing = false

                let remainingCount = self.imageTranslationBlocks.count(where: {
                    $0.translation.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                })
                self.updateImageTranslationTranscript(blocks: self.imageTranslationBlocks)
                if remainingCount == 0 {
                    self.imageTranslationState = .translated
                    self.imageTranslationMessage = editedBoundingBox == nil
                        ? "已重新识别此文字块，正在更新导出图"
                        : "已按调整后的文字框重新识别此文字块，正在更新导出图"
                    self.invalidateImageOverlayRender()
                    self.discardImageTranslationExport()
                    self.rerenderImageTranslationExport()
                } else {
                    self.imageTranslationState = .failed
                    self.imageTranslationMessage = editedBoundingBox == nil
                        ? "已重新识别此文字块，仍有 \(remainingCount) 个文字块等待翻译"
                        : "已按调整后的文字框重新识别此文字块，仍有 \(remainingCount) 个文字块等待翻译"
                    self.dataTransferMessage = self.imageTranslationMessage
                }
                self.imageTranslationBlockRerecognitionCompletedBlockID = blockID
                self.imageTranslationBlockRerecognitionCompletionGeneration &+= 1
                self.persist()
            } catch is CancellationError {
                guard self.imageTranslationBlockRerecognitionID == requestID,
                      self.imageTranslationTaskID == contentTaskID else { return }
                self.imageTranslationRerecognizingBlockID = nil
                self.imageTranslationBlockRerecognitionTask = nil
                self.imageTranslationState = previousState
                self.isProcessing = false
                self.imageTranslationMessage = "此图片文字块重新识别已取消"
                self.dataTransferMessage = self.imageTranslationMessage
                self.imageTranslationBlockRerecognitionFailureGeneration &+= 1
                self.persist()
            } catch {
                guard self.imageTranslationBlockRerecognitionID == requestID,
                      self.imageTranslationTaskID == contentTaskID else { return }
                self.imageTranslationRerecognizingBlockID = nil
                self.imageTranslationBlockRerecognitionTask = nil
                self.imageTranslationState = previousState
                self.isProcessing = false
                self.imageTranslationMessage = "此图片文字块重新识别失败：\(error.localizedDescription)"
                self.dataTransferMessage = self.imageTranslationMessage
                self.imageTranslationBlockRerecognitionFailureGeneration &+= 1
                self.persist()
            }
        }
    }

    private func applyEditedImageTranslationBoundingBox(
        _ boundingBox: NormalizedImageRect?,
        to block: inout ImageTranslationBlock
    ) {
        guard let boundingBox else { return }
        block.boundingBox = boundingBox
    }

    func rerunImageRecognition() {
        guard canRerunImageRecognition else { return }
        retryImageTranslation()
    }

    func refreshSummary() async throws {
        summary = try await summarize()
    }

    func canUseLanguage(_ language: SupportedLanguage) -> Bool {
        language.isFreeTranslationTarget || isProUnlocked
    }

    func unlockDeveloperMode(password: String) -> Bool {
        guard password == "114514" else {
            developerModeMessage = "密码错误"
            return false
        }

        isDeveloperModeEnabled = true
        developerModeMessage = "开发者模式已开启"
        return true
    }

    func disableDeveloperMode() {
        isDeveloperModeEnabled = false
        developerModeMessage = "开发者模式已关闭"
    }

    func runDeveloperRawProbe() {
        let input = developerProbeInput.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !input.isEmpty, !isRunningDeveloperProbe else { return }

        isRunningDeveloperProbe = true
        developerProbePrompt = ""
        developerProbeOutput = ""
        developerProbeError = ""

        let request = makeRequest(task: .translation, inputText: input)

        Task { [weak self] in
            guard let self else { return }
            defer { self.isRunningDeveloperProbe = false }

            if self.selectedEngine == .local {
                let probe = self.localService.rawTranslationProbe(for: request)
                self.developerProbePrompt = probe.prompt
                self.developerProbeOutput = probe.output
                self.developerProbeError = probe.errorCode ?? ""
            } else {
                do {
                    try await self.mockService.prepare()
                    let result = try await self.mockService.generate(request)
                    self.developerProbePrompt = self.debugPromptPreview(for: request)
                    self.developerProbeOutput = result.text
                    self.developerProbeError = ""
                } catch {
                    self.developerProbePrompt = self.debugPromptPreview(for: request)
                    self.developerProbeOutput = ""
                    self.developerProbeError = "\(type(of: error)): \(error.localizedDescription)"
                }
            }
        }
    }

    func runDeveloperRawProbeSuite() {
        guard !isRunningDeveloperProbe else { return }

        isRunningDeveloperProbe = true
        developerProbePrompt = ""
        developerProbeOutput = ""
        developerProbeError = ""
        developerProbeCases = Self.defaultDeveloperProbeCases.map {
            DeveloperRawProbeCase(
                id: $0.id,
                sourceLanguage: $0.sourceLanguage,
                targetLanguage: $0.targetLanguage,
                input: $0.input,
                verdict: "运行中"
            )
        }

        Task { [weak self] in
            guard let self else { return }
            defer { self.isRunningDeveloperProbe = false }

            let pendingCases = self.developerProbeCases
            var completedCases: [DeveloperRawProbeCase] = []
            for probeCase in pendingCases {
                let request = self.makeProbeRequest(
                    source: probeCase.sourceLanguage,
                    target: probeCase.targetLanguage,
                    input: probeCase.input
                )
                let completed = await self.runDeveloperProbeCase(probeCase, request: request)
                completedCases.append(completed)
                self.developerProbeCases = completedCases + Array(pendingCases.dropFirst(completedCases.count))
            }

            self.developerProbePrompt = completedCases.map { $0.prompt }.joined(separator: "\n\n---\n\n")
            self.developerProbeOutput = completedCases.map { probeCase in
                let body = probeCase.errorCode ?? probeCase.output
                return "[\(probeCase.sourceLanguage.shortName)->\(probeCase.targetLanguage.shortName)] \(probeCase.verdict)\n\(body)"
            }.joined(separator: "\n\n---\n\n")
            self.developerProbeError = completedCases.compactMap(\.errorCode).joined(separator: "\n\n")
        }
    }

    private func runDeveloperProbeCase(
        _ probeCase: DeveloperRawProbeCase,
        request: ModelGenerationRequest
    ) async -> DeveloperRawProbeCase {
        if selectedEngine == .local {
            let probe = localService.rawTranslationProbe(for: request)
            let verdict = probe.errorCode == nil
                ? translationProbeVerdict(source: request.sourceLanguage, target: request.targetLanguage, input: request.inputText, output: probe.output)
                : "Local 真实 raw 探针失败"
            return DeveloperRawProbeCase(
                id: probeCase.id,
                sourceLanguage: probeCase.sourceLanguage,
                targetLanguage: probeCase.targetLanguage,
                input: probeCase.input,
                prompt: probe.prompt,
                output: probe.output,
                errorCode: probe.errorCode,
                verdict: verdict,
                isRealLocalModelOutput: true
            )
        }

        do {
            try await mockService.prepare()
            let result = try await mockService.generate(request)
            return DeveloperRawProbeCase(
                id: probeCase.id,
                sourceLanguage: probeCase.sourceLanguage,
                targetLanguage: probeCase.targetLanguage,
                input: probeCase.input,
                prompt: debugPromptPreview(for: request) + "\n\n注意：Mock 模式为模拟输出，不是真实模型 raw prompt。",
                output: result.text,
                errorCode: nil,
                verdict: "Mock 模拟输出，非真实模型",
                isRealLocalModelOutput: false
            )
        } catch {
            return DeveloperRawProbeCase(
                id: probeCase.id,
                sourceLanguage: probeCase.sourceLanguage,
                targetLanguage: probeCase.targetLanguage,
                input: probeCase.input,
                prompt: debugPromptPreview(for: request) + "\n\n注意：Mock 模式为模拟输出，不是真实模型 raw prompt。",
                output: "",
                errorCode: "\(type(of: error)): \(error.localizedDescription)",
                verdict: "Mock 探针失败",
                isRealLocalModelOutput: false
            )
        }
    }

    func loadProSubscriptionProduct() {
        Task { [weak self] in
            guard let self else { return }

            do {
                let products = try await Product.products(for: [self.proPlan.productID])
                self.proSubscriptionProduct = products.first
                if let product = products.first {
                    self.proPurchaseMessage = "App Store 产品已就绪：\(product.displayName) · \(product.displayPrice)/月"
                } else {
                    self.proPurchaseMessage = "未在 App Store Connect 找到 \(self.proPlan.productID)，发布前需创建自动续期订阅。"
                }
            } catch {
                self.proPurchaseMessage = "读取 StoreKit 产品失败：\(error.localizedDescription)"
            }
        }
    }

    func purchaseProSubscription() {
        Task { [weak self] in
            guard let self else { return }

            do {
                if self.proSubscriptionProduct == nil {
                    let products = try await Product.products(for: [self.proPlan.productID])
                    self.proSubscriptionProduct = products.first
                }

                guard let product = self.proSubscriptionProduct else {
                    self.proPurchaseMessage = "订阅产品未配置：\(self.proPlan.productID)"
                    return
                }

                let result = try await product.purchase()
                switch result {
                case .success(let verification):
                    let transaction = try self.verifiedTransaction(from: verification)
                    self.isProUnlocked = true
                    self.proPurchaseMessage = "Pro 已开通：\(transaction.productID)"
                    await transaction.finish()
                case .userCancelled:
                    self.proPurchaseMessage = "已取消购买"
                case .pending:
                    self.proPurchaseMessage = "购买待处理"
                @unknown default:
                    self.proPurchaseMessage = "未知购买状态"
                }
            } catch {
                self.proPurchaseMessage = "购买失败：\(error.localizedDescription)"
            }
        }
    }

    private func verifiedTransaction(from result: VerificationResult<Transaction>) throws -> Transaction {
        switch result {
        case .verified(let transaction):
            transaction
        case .unverified(_, let error):
            throw error
        }
    }

    func refreshProEntitlements() {
        Task { [weak self] in
            guard let self else { return }

            do {
                var hasEntitlement = false
                for await result in Transaction.currentEntitlements {
                    let transaction = try self.verifiedTransaction(from: result)
                    if transaction.productID == self.proPlan.productID {
                        hasEntitlement = true
                    }
                }
                self.isProUnlocked = hasEntitlement
                self.proPurchaseMessage = hasEntitlement ? "App Store 订阅有效" : "未发现有效订阅"
            } catch {
                self.proPurchaseMessage = "校验订阅失败：\(error.localizedDescription)"
            }
        }
    }

    func selectTargetLanguage(_ language: SupportedLanguage) {
        guard canUseLanguage(language) else {
            dataTransferMessage = "\(language.rawValue) 翻译需要 Pro"
            return
        }

        targetLanguage = language
    }

    func selectImageTargetLanguage(_ language: SupportedLanguage) {
        let displayedLanguage = imageTranslationDisplayedTargetLanguage
        if language != targetLanguage {
            selectTargetLanguage(language)
        }
        guard targetLanguage == language,
              imageTranslationSelectedTargetLanguage != language else {
            return
        }

        switch imageTranslationState {
        case .translated:
            guard let url = imageTranslationSourceURL,
                  FileManager.default.fileExists(atPath: url.path) else {
                return
            }
            imageTranslationContentTargetLanguage = language
            imageTranslationRetryTargetLanguage = nil
            retryImageTranslation()
        case .idle, .failed:
            guard canRetryImageTranslation else { return }
            imageTranslationRetryTargetLanguage = language == displayedLanguage ? nil : language
        case .loading, .recognizing, .translating:
            return
        }
    }

    func selectImageSourceLanguage(_ language: SupportedLanguage) {
        guard isProUnlocked else {
            dataTransferMessage = "图片输入语言设置需要 Pro"
            return
        }
        let displayedLanguage = imageTranslationDisplayedSourceLanguage
        if language != sourceLanguage {
            sourceLanguage = language
        }
        guard imageTranslationSelectedSourceLanguage != language else {
            return
        }

        switch imageTranslationState {
        case .translated:
            guard let url = imageTranslationSourceURL,
                  FileManager.default.fileExists(atPath: url.path) else {
                return
            }
            imageTranslationContentSourceLanguage = language
            imageTranslationRetrySourceLanguage = nil
            retryImageTranslation()
        case .idle, .failed:
            guard canRetryImageTranslation else { return }
            imageTranslationRetrySourceLanguage = language == displayedLanguage ? nil : language
        case .loading, .recognizing, .translating:
            return
        }
    }

    func activateProForDevelopment() {
        isProUnlocked = true
        dataTransferMessage = "Pro 已开通：同声传译、日语/法语和图片翻译入口已解锁"
    }

    func restoreFreeModeForDevelopment() {
        isProUnlocked = false
        if !targetLanguage.isFreeTranslationTarget {
            targetLanguage = .simplifiedChinese
        }
        dataTransferMessage = "已切回免费模式：保留中文和英语翻译"
    }

    func swapLanguages() {
        let oldSource = sourceLanguage
        let oldTarget = targetLanguage
        guard canUseLanguage(oldSource) else {
            dataTransferMessage = "\(oldSource.rawValue) 作为目标语言需要 Pro"
            return
        }

        sourceLanguage = oldTarget
        targetLanguage = oldSource
    }

    func startNewSession(archiveCurrent: Bool = true) {
        ticker?.cancel()
        ticker = nil
        isRecording = false

        if archiveCurrent, shouldArchiveCurrentSession {
            upsertHistory(currentSessionRecord())
        }

        activeSessionID = UUID()
        activeCreatedAt = Date()
        elapsedSeconds = 0
        transcript = []
        summary = .empty
        draftText = ""
        lastGenerationLabel = "等待生成"
        persist()
    }

    func resetSession() {
        startNewSession(archiveCurrent: true)
    }

    func archiveCurrentSession() {
        guard shouldArchiveCurrentSession else { return }
        upsertHistory(currentSessionRecord())
        persist()
    }

    func loadSession(_ record: TranslationSessionRecord) {
        ticker?.cancel()
        ticker = nil
        isRecording = false

        isRestoring = true
        activeSessionID = record.id
        activeCreatedAt = record.createdAt
        mode = record.mode
        sourceLanguage = record.sourceLanguage
        targetLanguage = record.targetLanguage
        selectedPromptID = prompts.contains(where: { $0.id == record.selectedPromptID })
            ? record.selectedPromptID
            : PromptTemplate.translatorID
        selectedEngine = record.selectedEngine
        elapsedSeconds = record.durationSeconds
        transcript = record.transcript
        summary = record.summary
        draftText = ""
        isRestoring = false

        refreshModelStatus()
        persist()
    }

    func deleteSession(_ record: TranslationSessionRecord) {
        history.removeAll { $0.id == record.id }
        if activeSessionID == record.id {
            startNewSession(archiveCurrent: false)
        } else {
            persist()
        }
    }

    func clearHistory(keepCurrentSession: Bool = true) {
        history.removeAll()
        if !keepCurrentSession {
            startNewSession(archiveCurrent: false)
        } else {
            persist()
        }
    }

    @discardableResult
    func exportSnapshot() -> URL? {
        let snapshot = AppPersistenceSnapshot(
            activeSession: shouldArchiveCurrentSession ? currentSessionRecord() : nil,
            history: history,
            prompts: prompts,
            settings: AppSettings(
                mode: mode,
                sourceLanguage: sourceLanguage,
                targetLanguage: targetLanguage,
                selectedPromptID: selectedPromptID,
                selectedEngine: selectedEngine,
                sampling: sampling,
                isProUnlocked: isProUnlocked,
                isDeveloperModeEnabled: isDeveloperModeEnabled
            ),
            translationTerms: translationTermMemory,
            imageTranslationSession: makeImageTranslationPersistenceSnapshot()
        )

        do {
            try Self.write(snapshot, to: exportURL)
            dataTransferMessage = "已导出到 \(exportURL.lastPathComponent)"
            return exportURL
        } catch {
            dataTransferMessage = "导出失败：\(error.localizedDescription)"
            modelStatus = ModelStatus(
                title: "Export Failed",
                detail: error.localizedDescription,
                isReady: false
            )
            return nil
        }
    }

    @discardableResult
    func importSnapshot(from url: URL) -> Bool {
        let didAccess = url.startAccessingSecurityScopedResource()
        defer {
            if didAccess {
                url.stopAccessingSecurityScopedResource()
            }
        }

        guard let snapshot = Self.loadSnapshot(from: url) else {
            dataTransferMessage = "导入失败：无法解码 JSON"
            return false
        }

        if shouldArchiveCurrentSession {
            upsertHistory(currentSessionRecord())
        }

        let importedPrompts = Self.mergeDefaultPrompts(with: snapshot.prompts)
        translationTermMemory = snapshot.translationTerms
        for prompt in importedPrompts where !prompts.contains(where: { $0.id == prompt.id }) {
            prompts.append(prompt)
        }

        for record in snapshot.history {
            upsertHistory(record)
        }

        applySettings(snapshot.settings)
        if !prompts.contains(where: { $0.id == selectedPromptID }) {
            selectedPromptID = PromptTemplate.translatorID
        }

        if let importedActive = snapshot.activeSession {
            upsertHistory(importedActive)
            loadSession(importedActive)
        }

        history.sort { $0.updatedAt > $1.updatedAt }
        if history.count > 60 {
            history = Array(history.prefix(60))
        }
        dataTransferMessage = "已导入 \(snapshot.history.count + (snapshot.activeSession == nil ? 0 : 1)) 个会话，\(snapshot.prompts.count) 个提示词"
        refreshModelStatus()
        persist()
        return true
    }

    func selectEngine(_ engine: ModelEngine) {
        selectedEngine = engine
    }

    func selectPrompt(_ prompt: PromptTemplate) {
        selectedPromptID = prompt.id
    }

    func upsertTranslationTerm(
        source: String,
        target: String,
        kind: TranslationTermKind,
        note: String? = nil
    ) {
        let cleanSource = source.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanTarget = target.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleanSource.isEmpty, !cleanTarget.isEmpty else { return }
        let key = Self.translationTermKey(cleanSource)
        let entry = TranslationTermMemoryEntry(
            id: key,
            source: cleanSource,
            target: cleanTarget,
            kind: kind,
            status: .confirmed,
            note: note?.trimmingCharacters(in: .whitespacesAndNewlines)
        )
        if let index = translationTermMemory.firstIndex(where: { Self.translationTermKey($0.source) == key }) {
            translationTermMemory[index] = entry
        } else {
            translationTermMemory.append(entry)
        }
    }

    func revokeTranslationTerm(source: String) {
        let key = Self.translationTermKey(source)
        guard let index = translationTermMemory.firstIndex(where: { Self.translationTermKey($0.source) == key }) else {
            return
        }
        translationTermMemory[index].status = .revoked
    }

    func createPrompt(
        title: String,
        englishToChineseInstruction: String,
        chineseToEnglishInstruction: String,
        tone: String
    ) {
        let cleanTitle = title.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanEnglishToChinese = englishToChineseInstruction.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanChineseToEnglish = chineseToEnglishInstruction.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanTone = tone.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleanTitle.isEmpty else { return }

        let prompt = PromptTemplate(
            title: cleanTitle,
            instruction: cleanEnglishToChinese.isEmpty
                ? PromptLanguageDirection.englishToChinese.fallbackInstruction
                : cleanEnglishToChinese,
            englishToChineseInstruction: cleanEnglishToChinese.isEmpty
                ? PromptLanguageDirection.englishToChinese.fallbackInstruction
                : cleanEnglishToChinese,
            chineseToEnglishInstruction: cleanChineseToEnglish.isEmpty
                ? PromptLanguageDirection.chineseToEnglish.fallbackInstruction
                : cleanChineseToEnglish,
            tone: cleanTone.isEmpty ? "自然、准确" : cleanTone
        )
        prompts.insert(prompt, at: 0)
        selectedPromptID = prompt.id
    }

    func updatePrompt(
        _ prompt: PromptTemplate,
        title: String,
        englishToChineseInstruction: String,
        chineseToEnglishInstruction: String,
        tone: String
    ) {
        guard let index = prompts.firstIndex(where: { $0.id == prompt.id }), !prompts[index].isBuiltIn else { return }
        let cleanTitle = title.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanEnglishToChinese = englishToChineseInstruction.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanChineseToEnglish = chineseToEnglishInstruction.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanTone = tone.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleanTitle.isEmpty else { return }

        prompts[index].title = cleanTitle
        prompts[index].instruction = cleanEnglishToChinese.isEmpty
            ? PromptLanguageDirection.englishToChinese.fallbackInstruction
            : cleanEnglishToChinese
        prompts[index].englishToChineseInstruction = cleanEnglishToChinese.isEmpty
            ? PromptLanguageDirection.englishToChinese.fallbackInstruction
            : cleanEnglishToChinese
        prompts[index].chineseToEnglishInstruction = cleanChineseToEnglish.isEmpty
            ? PromptLanguageDirection.chineseToEnglish.fallbackInstruction
            : cleanChineseToEnglish
        prompts[index].tone = cleanTone.isEmpty ? "自然、准确" : cleanTone
        prompts[index].updatedAt = Date()
    }

    func duplicatePrompt(_ prompt: PromptTemplate) {
        let copy = PromptTemplate(
            title: "\(prompt.title) 副本",
            instruction: prompt.instruction,
            englishToChineseInstruction: prompt.englishToChineseInstruction,
            chineseToEnglishInstruction: prompt.chineseToEnglishInstruction,
            tone: prompt.tone
        )
        prompts.insert(copy, at: 0)
        selectedPromptID = copy.id
    }

