    private static func makeExternalArtifactReadinessReport(
        blocks: [MangaOverlayProbeBlock],
        imageWidth: Int,
        imageHeight: Int,
        bundledTestDirectory: URL?,
        bubbleMaskReport: MangaOverlayBubbleMaskReport?,
        segmentMaskReport: MangaOverlaySegmentMaskReport?
    ) -> MangaOverlayExternalArtifactReadinessReport {
        let artifactsDirectory = bundledTestDirectory?.appendingPathComponent("koharu_artifacts", isDirectory: true)
        let manifestURL = artifactsDirectory?.appendingPathComponent("1.manifest.json")
        var isDirectory: ObjCBool = false
        let activeArtifactsDirectory = artifactsDirectory.map {
            FileManager.default.fileExists(atPath: $0.path, isDirectory: &isDirectory) && isDirectory.boolValue
        } ?? false
        var parseErrors: [String] = []
        var notes = [
            "shadowOnly=true",
            "groundTruthNotUsed=true",
            "doesNotChangeFinalTextUsedForTranslation=true",
            "doesNotChangeTextRegionCropAdoptedCount=true",
            "doesNotAttachExternalDetectorRuntime=true",
            "activeInputDirectory=test/koharu_artifacts",
            "contractExamplesDirectory=md/koharu研究/artifact_contract/examples",
            "contract examples are non-active fixtures and must not be copied into the App bundle as detector output"
        ]
        let manifest: MangaOverlayExternalArtifactManifest? = Self.decodeExternalArtifact(
            MangaOverlayExternalArtifactManifest.self,
            from: manifestURL,
            label: "manifest",
            parseErrors: &parseErrors
        )
        if artifactsDirectory == nil {
            notes.append("bundled test directory is unavailable")
        } else if let artifactsDirectory, !FileManager.default.fileExists(atPath: artifactsDirectory.path) {
            notes.append("test/koharu_artifacts directory not found")
        }

        let textBoxesURL = Self.externalArtifactURL(
            named: manifest?.textBoxesPath,
            fallback: "1.textboxes.json",
            artifactsDirectory: artifactsDirectory,
            label: "textBoxesPath",
            parseErrors: &parseErrors
        )
        let bubbleMaskURL = Self.externalArtifactURL(
            named: manifest?.bubbleMaskPath,
            fallback: "1.bubbles.json",
            artifactsDirectory: artifactsDirectory,
            label: "bubbleMaskPath",
            parseErrors: &parseErrors
        )
        let segmentMaskURL = Self.externalArtifactURL(
            named: manifest?.segmentMaskPath,
            fallback: "1.segment_mask.json",
            artifactsDirectory: artifactsDirectory,
            label: "segmentMaskPath",
            parseErrors: &parseErrors
        )
        let artifactIdentityReceipt = Self.externalArtifactIdentityReceipt(
            sourceImageURL: bundledTestDirectory?.appendingPathComponent("1.png"),
            manifestURL: manifestURL,
            textBoxesURL: textBoxesURL,
            bubbleMaskURL: bubbleMaskURL,
            segmentMaskURL: segmentMaskURL,
            manifest: manifest,
            activeArtifactsDirectory: activeArtifactsDirectory
        )
        let expectedSourceImageSHA256 = artifactIdentityReceipt.files.first {
            $0.artifactKind.lowercased() == "sourceimage"
        }?.sha256
        let textBoxes = Self.decodeExternalArtifactList(
            MangaOverlayExternalTextBox.self,
            from: textBoxesURL,
            keys: ["textBoxes", "textboxes", "items"],
            label: "textBoxes",
            parseErrors: &parseErrors
        )
        let decodedBubbleMask = Self.decodeExternalBubbleMaskPayload(
            from: bubbleMaskURL,
            parseErrors: &parseErrors
        )
        let bubbleMaskPayload = decodedBubbleMask.payload
        let bubbleInstances = decodedBubbleMask.instances
        let segmentMask = Self.decodeExternalArtifact(
            MangaOverlayExternalSegmentMaskSummary.self,
            from: segmentMaskURL,
            label: "segmentMask",
            parseErrors: &parseErrors
        )
        let missingArtifacts = Self.externalMissingArtifacts(
            manifestURL: manifestURL,
            textBoxesURL: textBoxesURL,
            bubbleMaskURL: bubbleMaskURL,
            segmentMaskURL: segmentMaskURL
        )
        let coordinateValidation = Self.validateExternalArtifactCoordinates(
            manifest: manifest,
            textBoxes: textBoxes,
            bubbleInstances: bubbleInstances,
            segmentMask: segmentMask,
            expectedSourceImageSHA256: expectedSourceImageSHA256,
            imageWidth: imageWidth,
            imageHeight: imageHeight
        )
        let maximumDecodedPixelCount: Int
        let (sourcePixelCount, sourcePixelCountOverflow) = imageWidth.multipliedReportingOverflow(by: imageHeight)
        if sourcePixelCountOverflow || sourcePixelCount <= 0 {
            maximumDecodedPixelCount = 0
            parseErrors.append("maskPayload: invalid source image dimensions")
        } else {
            maximumDecodedPixelCount = sourcePixelCount
        }
        var validatedBubbleMask: KoharuValidatedBubbleMask?
        var validatedSegmentMask: KoharuValidatedSegmentMask?
        let bubbleMaskPayloadVerdict: String
        do {
            let evaluation = try KoharuMaskPayloadEvaluator.evaluateBubble(
                width: bubbleMaskPayload?.width,
                height: bubbleMaskPayload?.height,
                encoding: bubbleMaskPayload?.encoding,
                runs: bubbleMaskPayload?.runs,
                instances: bubbleInstances.map {
                    KoharuBubbleMaskInstanceSummary(
                        id: $0.id,
                        bbox: $0.bbox,
                        pixelCount: $0.pixelCount,
                        maskValue: $0.maskValue
                    )
                },
                maxPixelCount: maximumDecodedPixelCount
            )
            switch evaluation {
            case .summaryOnly:
                bubbleMaskPayloadVerdict = "legacySummaryOnly"
            case let .validated(payload):
                bubbleMaskPayloadVerdict = "validated"
                validatedBubbleMask = payload
            }
        } catch {
            bubbleMaskPayloadVerdict = "validationFailed"
            parseErrors.append("bubbleMaskPayload: \(error)")
        }
        let segmentMaskPayloadVerdict: String
        do {
            let evaluation = try KoharuMaskPayloadEvaluator.evaluateSegment(
                width: segmentMask?.width,
                height: segmentMask?.height,
                encoding: segmentMask?.encoding,
                runs: segmentMask?.runs,
                glyphPixelCount: segmentMask?.glyphPixelCount,
                connectedComponentCount: segmentMask?.connectedComponentCount,
                maxPixelCount: maximumDecodedPixelCount
            )
            switch evaluation {
            case .summaryOnly:
                segmentMaskPayloadVerdict = "legacySummaryOnly"
            case let .validated(payload):
                segmentMaskPayloadVerdict = "validated"
                validatedSegmentMask = payload
            }
        } catch {
            segmentMaskPayloadVerdict = "validationFailed"
            parseErrors.append("segmentMaskPayload: \(error)")
        }
        let maskPayloadRequired = manifest?.schemaVersion == "aitrans.koharu_artifact_contract.v2"
        let maskPayloadGateReady = maskPayloadRequired
            && validatedBubbleMask != nil
            && validatedSegmentMask != nil
        let stableMatching = Self.stableOneToOneExternalTextBoxShadowMatching(
            blocks: blocks,
            textBoxes: textBoxes,
            bubbleInstances: bubbleInstances,
            imageWidth: imageWidth,
            imageHeight: imageHeight
        )
        let maskTopologyReport = Self.externalMaskTopologyReport(
            blocks: blocks,
            matching: stableMatching,
            validatedBubbleMask: validatedBubbleMask,
            validatedSegmentMask: validatedSegmentMask
        )
        let maskTopologyGateReady = maskPayloadGateReady
            && maskTopologyReport.topologyVerdict == "complete"
        let blockAlignment = Self.externalArtifactBlockAlignment(
            blocks: blocks,
            textBoxes: textBoxes,
            bubbleInstances: bubbleInstances,
            segmentMask: segmentMask,
            segmentMaskReport: segmentMaskReport,
            validatedBubbleMask: validatedBubbleMask,
            validatedSegmentMask: validatedSegmentMask,
            matching: stableMatching
        )
        let readinessVerdict = Self.externalArtifactReadinessVerdict(
            manifestFound: manifest != nil,
            textBoxes: textBoxes,
            bubbleInstances: bubbleInstances,
            segmentMask: segmentMask,
            missingArtifacts: missingArtifacts,
            parseErrors: parseErrors,
            coordinateValidation: coordinateValidation,
            maskPayloadRequired: maskPayloadRequired,
            maskPayloadGateReady: maskPayloadGateReady
        )
        let nextAction = Self.externalArtifactNextAction(
            verdict: readinessVerdict,
            textBoxes: textBoxes,
            bubbleInstances: bubbleInstances,
            segmentMask: segmentMask
        )
        if let bubbleMaskReport {
            notes.append("internalBubbleMaskInstances=\(bubbleMaskReport.instanceCount)")
        }
        if let segmentMaskReport {
            notes.append("internalSegmentGlyphBlocks=\(segmentMaskReport.glyphMaskBlocks)")
        }
        if manifest?.contractExampleOnly == true {
            notes.append("contractExampleOnly=true; active readiness is blocked because this is not real detector output")
        }
        if readinessVerdict != "readyForShadowOCR" {
            notes.append("external detector artifact evidence is insufficient; stop before shadow OCR")
        }
        notes.append("artifactIdentityReceipt=\(artifactIdentityReceipt.identityVerdict)")
        notes.append("sourceImageSHA256Matches=\(artifactIdentityReceipt.sourceImageSHA256Matches)")
        notes.append("bubbleMaskPayloadVerdict=\(bubbleMaskPayloadVerdict)")
        notes.append("segmentMaskPayloadVerdict=\(segmentMaskPayloadVerdict)")
        notes.append("maskPayloadRequired=\(maskPayloadRequired)")
        notes.append("maskPayloadGateReady=\(maskPayloadGateReady)")
        notes.append("maskTopologyGateReady=\(maskTopologyGateReady)")
        notes.append("maskTopologyVerdict=\(maskTopologyReport.topologyVerdict)")
        let shadowAllowed = readinessVerdict == "readyForShadowOCR"
            && activeArtifactsDirectory
            && manifest?.contractExampleOnly != true
        return MangaOverlayExternalArtifactReadinessReport(
            enabled: true,
            sourceImage: "test/1.png",
            activeArtifactsDirectory: activeArtifactsDirectory,
            contractExampleOnly: manifest?.contractExampleOnly ?? false,
            generatedBy: manifest?.generatedBy,
            manifestPath: manifestURL?.path,
            textBoxesPath: textBoxesURL?.path,
            bubbleMaskPath: bubbleMaskURL?.path,
            segmentMaskPath: segmentMaskURL?.path,
            externalTextBoxesShadowOCRAllowed: shadowAllowed,
            manifestFound: manifest != nil,
            textBoxesFound: Self.fileExists(textBoxesURL),
            bubbleMaskFound: Self.fileExists(bubbleMaskURL),
            segmentMaskFound: Self.fileExists(segmentMaskURL),
            textBoxCount: textBoxes.count,
            bubbleInstanceCount: bubbleInstances.count,
            segmentGlyphPixelCount: segmentMask?.glyphPixelCount,
            parsedTextBoxCount: textBoxes.count,
            parsedBubbleInstanceCount: bubbleInstances.count,
            bubbleMaskPayloadVerdict: bubbleMaskPayloadVerdict,
            segmentMaskPayloadVerdict: segmentMaskPayloadVerdict,
            maskPayloadGateReady: maskPayloadGateReady,
            maskTopologyGateReady: maskTopologyGateReady,
            maskTopologyReport: maskTopologyReport,
            parseErrors: parseErrors,
            missingArtifacts: missingArtifacts,
            coordinateValidation: coordinateValidation,
            artifactIdentityReceipt: artifactIdentityReceipt,
            blockAlignment: blockAlignment,
            readinessVerdict: readinessVerdict,
            nextAction: nextAction,
            notes: notes
        )
    }

    private static func externalArtifactIdentityReceipt(
        sourceImageURL: URL?,
        manifestURL: URL?,
        textBoxesURL: URL?,
        bubbleMaskURL: URL?,
        segmentMaskURL: URL?,
        manifest: MangaOverlayExternalArtifactManifest?,
        activeArtifactsDirectory: Bool
    ) -> MangaOverlayExternalArtifactIdentityReceipt {
        let files = [
            externalArtifactFileIdentityReceipt(kind: "SourceImage", url: sourceImageURL, required: true),
            externalArtifactFileIdentityReceipt(kind: "Manifest", url: manifestURL, required: true),
            externalArtifactFileIdentityReceipt(kind: "TextBoxes", url: textBoxesURL, required: true),
            externalArtifactFileIdentityReceipt(kind: "BubbleMask", url: bubbleMaskURL, required: true),
            externalArtifactFileIdentityReceipt(kind: "SegmentMask", url: segmentMaskURL, required: true)
        ]
        let requiredFiles = files.filter(\.required)
        let sourceImageSHA256Expected = files.first { $0.artifactKind.lowercased() == "sourceimage" }?.sha256
        let sourceImageSHA256Declared = manifest?.sourceImageSHA256
        let sourceImageSHA256Normalized = Self.normalizedExternalArtifactSHA256(sourceImageSHA256Declared)
        let sourceImageSHA256Matches = sourceImageSHA256Normalized != nil
            && sourceImageSHA256Expected != nil
            && sourceImageSHA256Normalized == sourceImageSHA256Expected
        let allRequiredFilesPresent = requiredFiles.allSatisfy(\.exists)
        let allRequiredFilesHaveSHA256 = requiredFiles.allSatisfy { $0.sha256?.isEmpty == false }
        let identityVerdict: String
        if !activeArtifactsDirectory {
            identityVerdict = "activeDirectoryMissing"
        } else if !allRequiredFilesPresent {
            identityVerdict = "requiredIdentityFilesMissing"
        } else if !allRequiredFilesHaveSHA256 {
            identityVerdict = "requiredIdentityHashMissing"
        } else if manifest?.contractExampleOnly == true {
            identityVerdict = "blockedContractExampleOnly"
        } else if manifest?.sourceImageFieldPresent != true || manifest?.sourceImage.isEmpty == true {
            identityVerdict = "manifestSourceImageMissing"
        } else if manifest?.sourceImageSHA256FieldPresent != true {
            identityVerdict = "manifestSourceImageSHA256Missing"
        } else if manifest?.sourceImageSHA256TypeValid != true || sourceImageSHA256Normalized == nil {
            identityVerdict = "manifestSourceImageSHA256Invalid"
        } else if !sourceImageSHA256Matches {
            identityVerdict = "manifestSourceImageSHA256Mismatch"
        } else if manifest?.contractExampleOnlyFieldPresent != true {
            identityVerdict = "manifestContractExampleOnlyMissing"
        } else if manifest?.contractExampleOnlyTypeValid != true {
            identityVerdict = "manifestContractExampleOnlyInvalid"
        } else {
            identityVerdict = "activeArtifactIdentityRecorded"
        }
        return MangaOverlayExternalArtifactIdentityReceipt(
            sourceImage: manifest?.sourceImage ?? "test/1.png",
            sourceImageSHA256Declared: sourceImageSHA256Declared,
            sourceImageSHA256Expected: sourceImageSHA256Expected,
            sourceImageSHA256Matches: sourceImageSHA256Matches,
            schemaVersion: manifest?.schemaVersion,
            coordinateSpace: manifest?.coordinateSpace,
            contractExampleOnly: manifest?.contractExampleOnly ?? false,
            generatedBy: manifest?.generatedBy,
            generatedAt: manifest?.generatedAt,
            activeArtifactsDirectory: activeArtifactsDirectory,
            allRequiredFilesPresent: allRequiredFilesPresent,
            allRequiredFilesHaveSHA256: allRequiredFilesHaveSHA256,
            identityVerdict: identityVerdict,
            files: files,
            notes: [
                "App-side receipt records the active bundle files actually visible to the probe runtime.",
                "Manifest sourceImageSHA256 must match the runtime-visible bundle test/1.png SHA256 before active artifacts can be treated as ready.",
                "Compare these SHA256 values with ci-artifact-manifest.koharuArtifactValidationIdentitySummary before treating injected artifacts as consumed by the App.",
                "This receipt is report-only and does not create, copy, modify, or promote active artifacts."
            ]
        )
    }

    private static func externalArtifactFileIdentityReceipt(
        kind: String,
        url: URL?,
        required: Bool
    ) -> MangaOverlayExternalArtifactFileIdentityReceipt {
        guard let url else {
            return MangaOverlayExternalArtifactFileIdentityReceipt(
                artifactKind: kind,
                path: nil,
                required: required,
                exists: false,
                sizeBytes: nil,
                sha256: nil
            )
        }
        let exists = FileManager.default.fileExists(atPath: url.path)
        var sizeBytes: Int?
        var sha256: String?
        if exists {
            if let attributes = try? FileManager.default.attributesOfItem(atPath: url.path),
               let size = attributes[.size] as? NSNumber {
                sizeBytes = size.intValue
            }
            if let data = try? Data(contentsOf: url) {
                let digest = SHA256.hash(data: data)
                sha256 = digest.map { String(format: "%02x", $0) }.joined()
            }
        }
        return MangaOverlayExternalArtifactFileIdentityReceipt(
            artifactKind: kind,
            path: url.path,
            required: required,
            exists: exists,
            sizeBytes: sizeBytes,
            sha256: sha256
        )
    }

    private static func normalizedExternalArtifactSHA256(_ value: String?) -> String? {
        guard let value else { return nil }
        let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let hexCharacters = Set("0123456789abcdef")
        guard normalized.count == 64,
              normalized.allSatisfy({ hexCharacters.contains($0) }) else {
            return nil
        }
        return normalized
    }

    private func makeExternalTextBoxShadowOCRReport(
        blocks: [MangaOverlayProbeBlock],
        image: CGImage,
        readinessReport: MangaOverlayExternalArtifactReadinessReport?,
        bundledTestDirectory: URL?,
        preprocessing: MangaOverlayPreprocessingOptions
    ) async throws -> MangaOverlayExternalTextBoxShadowOCRReport {
        let gateVerdict = readinessReport?.readinessVerdict ?? "readinessReportMissing"
        let activeDirectory = readinessReport?.activeArtifactsDirectory ?? false
        let contractExampleOnly = readinessReport?.contractExampleOnly ?? false
        let shadowAllowed = readinessReport?.externalTextBoxesShadowOCRAllowed ?? false
        var notes = [
            "shadowOnly=true",
            "groundTruthNotUsed=true",
            "doesNotChangeFinalTextUsedForTranslation=true",
            "doesNotChangeMainOverlay=true",
            "doesNotChangeBlockPassed=true",
            "doesNotChangeTextRegionCropAdoptedCount=true",
            "candidateSelectionSignals=IoU,centerContainment,confidence,bubbleAlignment,bboxAreaRatio"
        ]

        guard shadowAllowed, activeDirectory, !contractExampleOnly else {
            if contractExampleOnly {
                notes.append("blockedBecauseContractExampleOnly")
            }
            notes.append("external TextBoxes shadow OCR did not execute because readiness gate is \(gateVerdict)")
            let summaries = blocks.map { block in
                MangaOverlayExternalTextBoxShadowOCRBlockSummary(
                    blockIndex: block.index,
                    selectedCandidateID: nil,
                    selectedTextBoxID: nil,
                    candidateBBox: nil,
                    selectedSourceDirection: nil,
                    selectedOrientationCategory: nil,
                    selectedLinePolygonsPresent: false,
                    selectedRotationDegrees: nil,
                    spatialGeometryVerdict: nil,
                    bubbleAlignmentVerdict: nil,
                    assignmentGeometryTrusted: nil,
                    orientationShadowPathNeeded: false,
                    orientationShadowPathExecuted: false,
                    orientationAttemptedRotations: [],
                    orientationSelectedRotation: nil,
                    orientationRecognitionLanguages: [],
                    orientationUnsupportedReason: nil,
                    orientationReadinessVerdict: "blockedByReadinessGate",
                    ocrExecuted: false,
                    ocrSucceeded: false,
                    ocrText: nil,
                    qualityDelta: nil,
                    wordPreservationRatio: nil,
                    promotionVerdict: "blockedByReadinessGate",
                    blockers: [gateVerdict],
                    notes: ["no externalArtifact.* candidate generated"]
                )
            }
            return MangaOverlayExternalTextBoxShadowOCRReport(
                enabled: true,
                executed: false,
                gateVerdict: gateVerdict,
                activeArtifactsDirectory: activeDirectory,
                contractExampleOnly: contractExampleOnly,
                externalTextBoxesShadowOCRAllowed: shadowAllowed,
                shadowOnly: true,
                groundTruthNotUsed: true,
                doesNotChangeFinalTextUsedForTranslation: true,
                doesNotChangeMainOverlay: true,
                evaluatedBlockCount: Set(blocks.map(\.index)).count,
                candidateCount: 0,
                ocrExecutedCount: 0,
                ocrSucceededCount: 0,
                betterThanControlCount: 0,
                matchedBlockIndexes: [],
                succeededBlockIndexes: [],
                failedBlockIndexes: [],
                promotedExternalShadowBlocks: [],
                wouldPromoteByExistingGateBlocks: [],
                skippedBlocks: Array(Set(blocks.map(\.index))).sorted(),
                uniqueMatchedTextBoxCount: 0,
                duplicateAssignmentLedgers: [],
                duplicateAssignedTextBoxIDs: [],
                matchedCoverageRatio: 0,
                successfulCoverageRatio: 0,
                matchedOCRSuccessRatio: 0,
                coverageVerdict: "notExecuted",
                minimumTrustedIoU: MangaOverlayExternalTextBoxGeometryEvaluator.minimumTrustedIoU,
                geometryTrustedBlockIndexes: [],
                geometryWeakBlockIndexes: [],
                geometryUnknownBubbleBlockIndexes: [],
                geometryCoverageRatio: 0,
                geometryCoverageVerdict: "notExecuted",
                sourceDirectionBreakdown: [:],
                orientationCategoryBreakdown: [:],
                linePolygonCandidateBlocks: [],
                rotationCandidateBlocks: [],
                verticalCandidateBlocks: [],
                orientationShadowPathNeededBlocks: [],
                orientationShadowPathExecutedBlocks: [],
                orientationShadowPathPartialBlocks: [],
                orientationShadowPathNotExecutedBlocks: [],
                orientationUnsupportedBlocks: [],
                orientationUnsupportedReasonBreakdown: [:],
                orientationReadinessVerdict: "blockedByReadinessGate",
                blockSummaries: summaries,
                candidates: [],
                notes: notes
            )
        }

        let artifactsDirectory = bundledTestDirectory?.appendingPathComponent("koharu_artifacts", isDirectory: true)
        let manifestURL = artifactsDirectory?.appendingPathComponent("1.manifest.json")
        var parseErrors: [String] = []
        let manifest = Self.decodeExternalArtifact(
            MangaOverlayExternalArtifactManifest.self,
            from: manifestURL,
            label: "manifest",
            parseErrors: &parseErrors
        )
        let textBoxesURL = Self.externalArtifactURL(
            named: manifest?.textBoxesPath,
            fallback: "1.textboxes.json",
            artifactsDirectory: artifactsDirectory,
            label: "textBoxesPath",
            parseErrors: &parseErrors
        )
        let bubbleMaskURL = Self.externalArtifactURL(
            named: manifest?.bubbleMaskPath,
            fallback: "1.bubbles.json",
            artifactsDirectory: artifactsDirectory,
            label: "bubbleMaskPath",
            parseErrors: &parseErrors
        )
        let textBoxes = Self.decodeExternalArtifactList(
            MangaOverlayExternalTextBox.self,
            from: textBoxesURL,
            keys: ["textBoxes", "textboxes", "items"],
            label: "textBoxes",
            parseErrors: &parseErrors
        )
        let bubbleInstances = Self.decodeExternalArtifactList(
            MangaOverlayExternalBubbleInstance.self,
            from: bubbleMaskURL,
            keys: ["bubbleInstances", "bubbles", "instances", "items"],
            label: "bubbleMask",
            parseErrors: &parseErrors
        )
        if !parseErrors.isEmpty {
            notes.append("parseErrors=\(parseErrors.joined(separator: ","))")
        }

        var nextCandidateID = 0
        var candidates: [MangaOverlayExternalTextBoxShadowOCRCandidate] = []
        var summaries: [MangaOverlayExternalTextBoxShadowOCRBlockSummary] = []
        var skippedBlocks: [Int] = []
        let matching = Self.stableOneToOneExternalTextBoxShadowMatching(
            blocks: blocks,
            textBoxes: textBoxes,
            bubbleInstances: bubbleInstances,
            imageWidth: image.width,
            imageHeight: image.height
        )

        for block in blocks.sorted(by: { $0.index < $1.index }) {
            let selected = matching.assignmentsByBlockIndex[block.index]
            guard let selected else {
                skippedBlocks.append(block.index)
                let lostContention = matching.eligibleBlockIndexesByTextBoxID.values.contains { $0.contains(block.index) }
                let skipVerdict = lostContention
                    ? "skippedLostOneToOneAssignmentContention"
                    : "skippedNoMatchingExternalTextBox"
                let skipBlocker = lostContention
                    ? "lostOneToOneAssignmentContention"
                    : "noMatchingExternalTextBox"
                summaries.append(
                    MangaOverlayExternalTextBoxShadowOCRBlockSummary(
                        blockIndex: block.index,
                        selectedCandidateID: nil,
                        selectedTextBoxID: nil,
                        candidateBBox: nil,
                        selectedSourceDirection: nil,
                        selectedOrientationCategory: nil,
                        selectedLinePolygonsPresent: false,
                        selectedRotationDegrees: nil,
                        spatialGeometryVerdict: nil,
                        bubbleAlignmentVerdict: nil,
                        assignmentGeometryTrusted: nil,
                        orientationShadowPathNeeded: false,
                        orientationShadowPathExecuted: false,
                        orientationAttemptedRotations: [],
                        orientationSelectedRotation: nil,
                        orientationRecognitionLanguages: [],
                        orientationUnsupportedReason: nil,
                        orientationReadinessVerdict: skipVerdict,
                        ocrExecuted: false,
                        ocrSucceeded: false,
                        ocrText: nil,
                        qualityDelta: nil,
                        wordPreservationRatio: nil,
                        promotionVerdict: skipVerdict,
                        blockers: [skipBlocker],
                        notes: [lostContention
                            ? "eligible external TextBox was assigned to another block by stable one-to-one matching"
                            : "external TextBox candidate rejected before OCR"]
                    )
                )
                continue
            }

            let controlText = block.finalTextUsedForTranslation
            let controlQuality = Self.ocrCandidateQualityScore(controlText)
            let controlWords = Self.ocrCandidateWords(controlText)
            let normalizedSourceDirection = selected.textBox.sourceDirection.map(Self.normalizedExternalSourceDirection)
            let orientationCategory = Self.externalTextBoxOrientationCategory(selected.textBox)
            let linePolygonCount = selected.textBox.linePolygons?.count ?? 0
            let orientationShadowPathNeeded = Self.externalTextBoxNeedsOrientationShadowPath(selected.textBox)
            let orientationPlan = Self.externalTextBoxOrientationShadowOCRPlan(selected.textBox)
            var attempts: [(
                text: String?,
                cropBBox: [Double],
                paddingX: Double,
                paddingY: Double,
                rotationApplied: Double,
                linePolygonWarpAttempted: Bool,
                linePolygonWarpExecuted: Bool,
                linePolygonWarpedLineCount: Int,
                linePolygonWarpFailureReasons: [String],
                ocrPath: String,
                bboxFallbackReason: String?,
                bboxFallbackError: String?,
                errorCode: String?
            )] = []
            for rotationAngle in orientationPlan.rotationAngles {
                do {
                    let crop = try await mangaOverlayProbeService.recognizeExternalTextBoxCrop(
                        in: image,
                        textBoxBBox: selected.textBox.bbox,
                        options: preprocessing,
                        rotationAngle: rotationAngle,
                        recognitionLanguages: orientationPlan.recognitionLanguages,
                        linePolygons: selected.textBox.linePolygons
                    )
                    attempts.append((
                        crop.text,
                        crop.cropBBox,
                        crop.paddingX,
                        crop.paddingY,
                        crop.rotationApplied,
                        crop.linePolygonWarpAttempted,
                        crop.linePolygonWarpExecuted,
                        crop.linePolygonWarpedLineCount,
                        crop.linePolygonWarpFailureReasons,
                        crop.ocrPath,
                        crop.bboxFallbackReason,
                        crop.bboxFallbackError,
                        crop.bboxFallbackError
                    ))
                } catch {
                    let preciseError = error.localizedDescription
                    let warpError = error as? MangaOverlayLinePolygonWarpError
                    let warpReason = warpError?.reason ?? preciseError
                    let fallbackError = warpError?.fallbackError ?? preciseError
                    let warpFailureReasons = warpError?.lineFailureReasons.isEmpty == false
                        ? (warpError?.lineFailureReasons ?? [])
                        : [warpReason]
                    attempts.append((
                        nil,
                        selected.textBox.bbox,
                        0,
                        0,
                        Double(rotationAngle),
                        selected.textBox.linePolygons?.isEmpty == false,
                        false,
                        0,
                        warpFailureReasons,
                        "linePolygonWarpAndBBoxFallbackFailed",
                        warpReason,
                        fallbackError,
                        preciseError
                    ))
                }
            }
            let crop = attempts.max { lhs, rhs in
                let lhsText = (lhs.text ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
                let rhsText = (rhs.text ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
                if (lhs.errorCode == nil) != (rhs.errorCode == nil) {
                    return lhs.errorCode != nil
                }
                if lhsText.isEmpty != rhsText.isEmpty {
                    return lhsText.isEmpty
                }
                let lhsQuality = Self.ocrCandidateQualityScore(lhsText)
                let rhsQuality = Self.ocrCandidateQualityScore(rhsText)
                if abs(lhsQuality - rhsQuality) > 0.0001 {
                    return lhsQuality < rhsQuality
                }
                let lhsPreservation = Self.wordPreservationRatio(
                    sourceWords: controlWords,
                    candidateWords: Self.ocrCandidateWords(lhsText)
                )
                let rhsPreservation = Self.wordPreservationRatio(
                    sourceWords: controlWords,
                    candidateWords: Self.ocrCandidateWords(rhsText)
                )
                if abs(lhsPreservation - rhsPreservation) > 0.0001 {
                    return lhsPreservation < rhsPreservation
                }
                if lhs.linePolygonWarpExecuted != rhs.linePolygonWarpExecuted {
                    return !lhs.linePolygonWarpExecuted
                }
                return lhs.rotationApplied > rhs.rotationApplied
            } ?? (
                nil,
                selected.textBox.bbox,
                0,
                0,
                0,
                selected.textBox.linePolygons?.isEmpty == false,
                false,
                0,
                ["linePolygonWarpNoAttempt"],
                "noExternalTextBoxShadowOCRAttempt",
                nil,
                nil,
                "noExternalTextBoxShadowOCRAttempt"
            )
            let ocrText = crop.text?.trimmingCharacters(in: .whitespacesAndNewlines)
            let ocrTextValue = ocrText ?? ""
            let candidateQuality = Self.ocrCandidateQualityScore(ocrTextValue)
            let preservation = Self.wordPreservationRatio(
                sourceWords: controlWords,
                candidateWords: Self.ocrCandidateWords(ocrTextValue)
            )
            let qualityDelta = candidateQuality - controlQuality
            var blockers = selected.rejectionReasons
            if crop.errorCode != nil {
                blockers.append("ocrExecutionFailed")
            }
            if crop.bboxFallbackError != nil {
                blockers.append("linePolygonBBoxFallbackFailed")
            }
            if ocrTextValue.isEmpty {
                blockers.append("emptyLocalOCR")
            }
            if controlWords.count >= 3, preservation < 0.55 {
                blockers.append("rawWordsLost")
            }
            if controlWords.count >= 2,
               Self.ocrCandidateWords(ocrTextValue).count < max(2, Int(ceil(Double(controlWords.count) * 0.55))) {
                blockers.append("wordCountRegression")
            }
            if Self.ocrCandidateWords(ocrTextValue).joined(separator: " ") == controlWords.joined(separator: " ") {
                blockers.append("sameAsFusedText")
            }
            if Self.containsLikelyOCRError(in: ocrTextValue), !Self.containsLikelyOCRError(in: controlText), candidateQuality <= controlQuality + 0.08 {
                blockers.append("introducedLikelyOCRError")
            }
            let orientationRotationExecuted = attempts.contains { attempt in
                attempt.errorCode == nil && abs(attempt.rotationApplied) > 0.001
            }
            let linePolygonWarpExecuted = attempts.contains { attempt in
                attempt.errorCode == nil && attempt.linePolygonWarpExecuted
            }
            let linePolygonWarpOutputSelected = crop.linePolygonWarpExecuted
                && ["linePolygonPerspectiveWarp", "linePolygonPerspectiveWarpPartial"].contains(crop.ocrPath)
            let linePolygonWarpPartialOutputSelected = linePolygonWarpOutputSelected
                && crop.ocrPath == "linePolygonPerspectiveWarpPartial"
            let linePolygonWarpFailureReasons = Array(Set(crop.linePolygonWarpFailureReasons)).sorted()
            var orientationUnsupportedReasons = orientationPlan.unsupportedReasons
            if linePolygonCount > 0, !linePolygonWarpExecuted {
                orientationUnsupportedReasons.append("linePolygonWarpFailed")
                orientationUnsupportedReasons.append(contentsOf: linePolygonWarpFailureReasons)
            } else if linePolygonCount > 0, !linePolygonWarpFailureReasons.isEmpty {
                orientationUnsupportedReasons.append("linePolygonWarpPartialFailure")
                orientationUnsupportedReasons.append(contentsOf: linePolygonWarpFailureReasons)
            } else if linePolygonCount > 0, !linePolygonWarpOutputSelected {
                orientationUnsupportedReasons.append("linePolygonWarpOutputNotSelected")
                if let fallbackReason = crop.bboxFallbackReason {
                    orientationUnsupportedReasons.append(fallbackReason)
                }
            }
            orientationUnsupportedReasons = Array(Set(orientationUnsupportedReasons)).sorted()
            let orientationShadowPathExecuted = orientationShadowPathNeeded
                && (orientationRotationExecuted || linePolygonWarpExecuted)
            let orientationUnsupportedReason = orientationUnsupportedReasons.isEmpty
                ? nil
                : orientationUnsupportedReasons.joined(separator: ",")
            let orientationReadinessVerdict: String
            if !orientationShadowPathNeeded {
                orientationReadinessVerdict = "orientationMetadataCaptured"
            } else if orientationShadowPathExecuted && orientationUnsupportedReasons.isEmpty {
                orientationReadinessVerdict = "orientationShadowPathExecuted"
            } else if orientationShadowPathExecuted {
                orientationReadinessVerdict = "orientationShadowPathPartiallyExecuted"
            } else {
                orientationReadinessVerdict = "orientationShadowPathNeededNotExecuted"
            }
            if orientationShadowPathNeeded && !orientationShadowPathExecuted {
                blockers.append("orientationShadowPathNeededNotExecuted")
            }
            blockers.append(contentsOf: orientationUnsupportedReasons)
            let betterThanControl = candidateQuality > controlQuality + 0.03
            let wouldPromote = !ocrTextValue.isEmpty
                && preservation >= 0.80
                && qualityDelta > 0.08
                && !blockers.contains("rawWordsLost")
                && !blockers.contains("introducedLikelyOCRError")
                && !blockers.contains("sameAsFusedText")
                && !blockers.contains("bubbleAlignmentMismatch")
                && !blockers.contains("textBoxAreaTooLarge")
                && !blockers.contains("orientationShadowPathNeededNotExecuted")
                && !blockers.contains("linePolygonWarpFailed")
                && !blockers.contains("linePolygonWarpPartialFailure")
                && !blockers.contains("linePolygonWarpOutputNotSelected")
                && !blockers.contains("arbitraryRotationUnsupported")
            let verdict = wouldPromote ? "wouldPromoteByExistingGateReportOnly" : (betterThanControl ? "betterThanControlButBlocked" : "controlStillBest")
            let candidateID = nextCandidateID
            nextCandidateID += 1
            var riskFlags = selected.riskFlags
            if orientationCategory == "vertical" && orientationShadowPathExecuted {
                riskFlags.append("verticalSourceDirectionShadowExecuted")
            } else if orientationCategory == "vertical" {
                riskFlags.append("verticalSourceDirectionShadowNotExecuted")
            }
            if orientationShadowPathNeeded && !orientationShadowPathExecuted {
                riskFlags.append("orientationShadowPathNeededNotExecuted")
            }
            riskFlags.append(contentsOf: orientationUnsupportedReasons)
            candidates.append(
                MangaOverlayExternalTextBoxShadowOCRCandidate(
                    candidateID: candidateID,
                    blockIndex: block.index,
                    selectedTextBoxID: selected.textBox.id,
                    variantName: linePolygonWarpOutputSelected
                        ? (linePolygonWarpPartialOutputSelected
                            ? "externalArtifact.linePolygonWarpPartial"
                            : "externalArtifact.linePolygonWarp")
                        : (crop.linePolygonWarpAttempted
                            ? "externalArtifact.textBoxCropFallback"
                            : "externalArtifact.textBoxCrop"),
                    textBoxBBox: selected.textBox.bbox,
                    cropBBox: crop.cropBBox,
                    textBoxConfidence: selected.textBox.confidence,
                    textBoxIoU: selected.iou,
                    blockCenterContained: selected.centerContained,
                    bubbleInstanceID: selected.bubbleInstance?.id,
                    bubbleAlignmentMatched: selected.bubbleAlignmentMatched,
                    spatialGeometryVerdict: selected.spatialGeometryVerdict,
                    bubbleAlignmentVerdict: selected.bubbleAlignmentVerdict,
                    assignmentGeometryTrusted: selected.assignmentGeometryTrusted,
                    areaRatioToBlock: selected.areaRatio,
                    linePolygonsPresent: selected.textBox.linePolygons?.isEmpty == false,
                    linePolygonCount: linePolygonCount,
                    sourceDirection: selected.textBox.sourceDirection,
                    normalizedSourceDirection: normalizedSourceDirection,
                    orientationCategory: orientationCategory,
                    rotationDegrees: selected.textBox.rotationDegrees,
                    deskewExecuted: linePolygonWarpOutputSelected,
                    orientationShadowPathNeeded: orientationShadowPathNeeded,
                    orientationShadowPathExecuted: orientationShadowPathExecuted,
                    orientationAttemptedRotations: orientationPlan.rotationAngles.map(Double.init),
                    orientationSelectedRotation: crop.rotationApplied,
                    orientationRecognitionLanguages: orientationPlan.recognitionLanguages ?? [],
                    orientationUnsupportedReason: orientationUnsupportedReason,
                    ocrExecuted: true,
                    ocrSucceeded: !ocrTextValue.isEmpty,
                    controlText: controlText,
                    ocrText: ocrText,
                    wordPreservationRatio: preservation,
                    qualityScoreBefore: controlQuality,
                    qualityScoreAfter: candidateQuality,
                    qualityDelta: qualityDelta,
                    betterThanControl: betterThanControl,
                    promotionVerdict: verdict,
                    blockers: Array(Set(blockers)).sorted(),
                    riskFlags: Array(Set(riskFlags)).sorted(),
                    notes: [
                        "shadowOnly=true",
                        "variantName=\(linePolygonWarpOutputSelected ? (linePolygonWarpPartialOutputSelected ? "externalArtifact.linePolygonWarpPartial" : "externalArtifact.linePolygonWarp") : (crop.linePolygonWarpAttempted ? "externalArtifact.textBoxCropFallback" : "externalArtifact.textBoxCrop"))",
                        "linePolygonWarpAttempted=\(crop.linePolygonWarpAttempted)",
                        "linePolygonWarpExecuted=\(crop.linePolygonWarpExecuted)",
                        "linePolygonWarpOutputSelected=\(linePolygonWarpOutputSelected)",
                        "linePolygonWarpedLineCount=\(crop.linePolygonWarpedLineCount)",
                        "linePolygonWarpFailureReasons=\(crop.linePolygonWarpFailureReasons.joined(separator: ","))",
                        "ocrPath=\(crop.ocrPath)",
                        "bboxFallbackReason=\(crop.bboxFallbackReason ?? "none")",
                        "bboxFallbackError=\(crop.bboxFallbackError ?? "none")",
                        "linePolygonWarpAttempts=\(attempts.map { "rotation:\(Int($0.rotationApplied)),path:\($0.ocrPath),executed:\($0.linePolygonWarpExecuted),lines:\($0.linePolygonWarpedLineCount),warpFailures:\($0.linePolygonWarpFailureReasons.joined(separator: "+")),fallbackReason:\($0.bboxFallbackReason ?? "none"),fallbackError:\($0.bboxFallbackError ?? "none")" }.joined(separator: " | "))",
                        "deskewExecuted=\(linePolygonWarpOutputSelected)",
                        "orientationShadowPathExecuted=\(orientationShadowPathExecuted)",
                        "orientationReadinessVerdict=\(orientationReadinessVerdict)",
                        "orientationAttemptedRotations=\(orientationPlan.rotationAngles.map(String.init).joined(separator: ","))",
                        "orientationSelectedRotation=\(crop.rotationApplied.formatted(.number.precision(.fractionLength(1))))",
                        "orientationRecognitionLanguages=\(orientationPlan.recognitionLanguages?.joined(separator: ",") ?? "default")",
                        "orientationUnsupportedReason=\(orientationUnsupportedReason ?? "none")",
                        "paddingX=\(crop.paddingX.formatted(.number.precision(.fractionLength(1))))",
                        "paddingY=\(crop.paddingY.formatted(.number.precision(.fractionLength(1))))",
                        "groundTruthUsedForSelection=false",
                        "groundTruthUsedForPromotion=false"
                    ]
                )
            )
            summaries.append(
                MangaOverlayExternalTextBoxShadowOCRBlockSummary(
                    blockIndex: block.index,
                    selectedCandidateID: candidateID,
                    selectedTextBoxID: selected.textBox.id,
                    candidateBBox: crop.cropBBox,
                    selectedSourceDirection: selected.textBox.sourceDirection,
                    selectedOrientationCategory: orientationCategory,
                    selectedLinePolygonsPresent: linePolygonCount > 0,
                    selectedRotationDegrees: selected.textBox.rotationDegrees,
                    spatialGeometryVerdict: selected.spatialGeometryVerdict,
                    bubbleAlignmentVerdict: selected.bubbleAlignmentVerdict,
                    assignmentGeometryTrusted: selected.assignmentGeometryTrusted,
                    orientationShadowPathNeeded: orientationShadowPathNeeded,
                    orientationShadowPathExecuted: orientationShadowPathExecuted,
                    orientationAttemptedRotations: orientationPlan.rotationAngles.map(Double.init),
                    orientationSelectedRotation: crop.rotationApplied,
                    orientationRecognitionLanguages: orientationPlan.recognitionLanguages ?? [],
                    orientationUnsupportedReason: orientationUnsupportedReason,
                    orientationReadinessVerdict: orientationReadinessVerdict,
                    ocrExecuted: true,
                    ocrSucceeded: !ocrTextValue.isEmpty,
                    ocrText: ocrText,
                    qualityDelta: qualityDelta,
                    wordPreservationRatio: preservation,
                    promotionVerdict: verdict,
                    blockers: Array(Set(blockers)).sorted(),
                    notes: [
                        "externalArtifact.textBoxCrop shadow candidate; not written to finalTextUsedForTranslation",
                        "linePolygonWarpAttempted=\(crop.linePolygonWarpAttempted)",
                        "linePolygonWarpExecuted=\(crop.linePolygonWarpExecuted)",
                        "linePolygonWarpedLineCount=\(crop.linePolygonWarpedLineCount)",
                        "linePolygonWarpFailureReasons=\(crop.linePolygonWarpFailureReasons.joined(separator: ","))",
                        "ocrPath=\(crop.ocrPath)",
                        "bboxFallbackReason=\(crop.bboxFallbackReason ?? "none")",
                        "bboxFallbackError=\(crop.bboxFallbackError ?? "none")",
                        "orientationShadowPathExecuted=\(orientationShadowPathExecuted)",
                        "orientationReadinessVerdict=\(orientationReadinessVerdict)",
                        "orientationAttemptedRotations=\(orientationPlan.rotationAngles.map(String.init).joined(separator: ","))",
                        "orientationSelectedRotation=\(crop.rotationApplied.formatted(.number.precision(.fractionLength(1))))",
                        "orientationUnsupportedReason=\(orientationUnsupportedReason ?? "none")"
                    ]
                )
            )
        }

        let wouldPromoteBlocks = candidates
            .filter { $0.promotionVerdict == "wouldPromoteByExistingGateReportOnly" }
            .map(\.blockIndex)
            .sorted()
        let linePolygonBlocks = candidates
            .filter { $0.linePolygonCount > 0 }
            .map(\.blockIndex)
            .sorted()
        let rotationBlocks = candidates
            .filter { ($0.rotationDegrees.map { abs($0) > 0.001 }) ?? false }
            .map(\.blockIndex)
            .sorted()
        let verticalBlocks = candidates
            .filter { $0.orientationCategory == "vertical" }
            .map(\.blockIndex)
            .sorted()
        let orientationNeededBlocks = candidates
            .filter(\.orientationShadowPathNeeded)
            .map(\.blockIndex)
            .sorted()
        let orientationExecutedBlocks = candidates
            .filter(\.orientationShadowPathExecuted)
            .map(\.blockIndex)
            .sorted()
        let orientationPartialBlocks = candidates
            .filter { $0.orientationShadowPathExecuted && $0.orientationUnsupportedReason != nil }
            .map(\.blockIndex)
            .sorted()
        let orientationNotExecutedBlocks = candidates
            .filter { $0.orientationShadowPathNeeded && !$0.orientationShadowPathExecuted }
            .map(\.blockIndex)
            .sorted()
        let orientationUnsupportedBlocks = candidates
            .filter { $0.orientationUnsupportedReason != nil }
            .map(\.blockIndex)
            .sorted()
        let orientationUnsupportedReasons = candidates
            .flatMap { candidate in
                (candidate.orientationUnsupportedReason ?? "")
                    .split(separator: ",")
                    .map { String($0) }
            }
        let evaluatedBlockIndexes = Array(Set(blocks.map(\.index))).sorted()
        let matchedBlockIndexes = Array(Set(candidates.map(\.blockIndex))).sorted()
        let succeededBlockIndexes = Array(Set(candidates.filter(\.ocrSucceeded).map(\.blockIndex))).sorted()
        let failedBlockIndexes = Array(Set(candidates.filter { !$0.ocrSucceeded }.map(\.blockIndex))).sorted()
        let geometryTrustedBlockIndexes = Array(Set(candidates.filter {
            $0.assignmentGeometryTrusted == true
        }.map(\.blockIndex))).sorted()
        let geometryUnknownBubbleBlockIndexes = Array(Set(candidates.filter {
            $0.bubbleAlignmentVerdict == "unknown"
        }.map(\.blockIndex))).sorted()
        skippedBlocks = Array(Set(skippedBlocks)).sorted()
        let matchedTextBoxIDs = candidates.compactMap(\.selectedTextBoxID)
        let coverage = MangaOverlayExternalTextBoxCoverageEvaluator.evaluate(
            evaluatedBlockIndexes: evaluatedBlockIndexes,
            matchedBlockIndexes: matchedBlockIndexes,
            succeededBlockIndexes: succeededBlockIndexes,
            failedBlockIndexes: failedBlockIndexes,
            skippedBlockIndexes: skippedBlocks,
            matchedTextBoxIDs: matchedTextBoxIDs,
            geometryTrustedBlockIndexes: geometryTrustedBlockIndexes,
            geometryUnknownBubbleBlockIndexes: geometryUnknownBubbleBlockIndexes
        )
        let reportOrientationVerdict: String
        if orientationNotExecutedBlocks.isEmpty,
           orientationUnsupportedBlocks.isEmpty,
           candidates.contains(where: { $0.orientationShadowPathExecuted }) {
            reportOrientationVerdict = "orientationShadowPathExecuted"
        } else if orientationNotExecutedBlocks.isEmpty,
                  candidates.contains(where: \.orientationShadowPathExecuted) {
            reportOrientationVerdict = "orientationShadowPathPartiallyExecuted"
        } else if orientationNotExecutedBlocks.isEmpty {
            reportOrientationVerdict = "orientationMetadataCaptured"
        } else {
            reportOrientationVerdict = "orientationShadowPathNeededNotExecuted"
        }
        notes.append("promotedExternalShadowBlocks intentionally remains empty; wouldPromoteByExistingGateBlocks is report-only")
        notes.append("orientation-aware shadow OCR runs bounded 90-degree rotation variants and four-point line-polygon warp; partial line failures stay blocked, and arbitrary-angle deskew remains unsupported")
        notes.append("stable one-to-one maximum-cardinality matching prevents a TextBox from being consumed by multiple OCR blocks")
        return MangaOverlayExternalTextBoxShadowOCRReport(
            enabled: true,
            executed: true,
            gateVerdict: gateVerdict,
            activeArtifactsDirectory: activeDirectory,
            contractExampleOnly: contractExampleOnly,
            externalTextBoxesShadowOCRAllowed: shadowAllowed,
            shadowOnly: true,
            groundTruthNotUsed: true,
            doesNotChangeFinalTextUsedForTranslation: true,
            doesNotChangeMainOverlay: true,
            evaluatedBlockCount: coverage.evaluatedBlockIndexes.count,
            candidateCount: candidates.count,
            ocrExecutedCount: candidates.filter(\.ocrExecuted).count,
            ocrSucceededCount: candidates.filter(\.ocrSucceeded).count,
            betterThanControlCount: candidates.filter(\.betterThanControl).count,
            matchedBlockIndexes: coverage.matchedBlockIndexes,
            succeededBlockIndexes: coverage.succeededBlockIndexes,
            failedBlockIndexes: coverage.failedBlockIndexes,
            promotedExternalShadowBlocks: [],
            wouldPromoteByExistingGateBlocks: wouldPromoteBlocks,
            skippedBlocks: coverage.skippedBlockIndexes,
            uniqueMatchedTextBoxCount: Set(matchedTextBoxIDs).count,
            duplicateAssignmentLedgers: matching.duplicateAssignmentLedgers,
            duplicateAssignedTextBoxIDs: coverage.duplicateAssignedTextBoxIDs,
            matchedCoverageRatio: coverage.matchedCoverageRatio,
            successfulCoverageRatio: coverage.successfulCoverageRatio,
            matchedOCRSuccessRatio: coverage.matchedOCRSuccessRatio,
            coverageVerdict: coverage.coverageVerdict,
            minimumTrustedIoU: coverage.minimumTrustedIoU,
            geometryTrustedBlockIndexes: coverage.geometryTrustedBlockIndexes,
            geometryWeakBlockIndexes: coverage.geometryWeakBlockIndexes,
            geometryUnknownBubbleBlockIndexes: coverage.geometryUnknownBubbleBlockIndexes,
            geometryCoverageRatio: coverage.geometryCoverageRatio,
            geometryCoverageVerdict: coverage.geometryCoverageVerdict,
            sourceDirectionBreakdown: Self.countStrings(candidates.map { $0.normalizedSourceDirection ?? "unspecified" }),
            orientationCategoryBreakdown: Self.countStrings(candidates.map(\.orientationCategory)),
            linePolygonCandidateBlocks: linePolygonBlocks,
            rotationCandidateBlocks: rotationBlocks,
            verticalCandidateBlocks: verticalBlocks,
            orientationShadowPathNeededBlocks: orientationNeededBlocks,
            orientationShadowPathExecutedBlocks: orientationExecutedBlocks,
            orientationShadowPathPartialBlocks: orientationPartialBlocks,
            orientationShadowPathNotExecutedBlocks: orientationNotExecutedBlocks,
            orientationUnsupportedBlocks: orientationUnsupportedBlocks,
            orientationUnsupportedReasonBreakdown: Self.countStrings(orientationUnsupportedReasons),
            orientationReadinessVerdict: reportOrientationVerdict,
            blockSummaries: summaries.sorted { $0.blockIndex < $1.blockIndex },
            candidates: candidates.sorted { $0.candidateID < $1.candidateID },
            notes: notes
        )
    }

    private func makeKoharuNativeTextBoxDetectorLiteShadowOCRReport(
        blocks: [MangaOverlayProbeBlock],
        image: CGImage,
        detectorLiteReport: MangaKoharuNativeTextBoxDetectorLiteReport?,
        groundTruth: [MangaGroundTruthEntry],
        preprocessing: MangaOverlayPreprocessingOptions,
        candidateLimitPerBlock: Int
    ) async throws -> MangaKoharuNativeTextBoxDetectorLiteShadowOCRReport {
        func uniqueSorted(_ values: [Int]) -> [Int] { Array(Set(values)).sorted() }
        func countBy(_ values: [String]) -> [String: Int] {
            values.reduce(into: [:]) { partial, value in partial[value, default: 0] += 1 }
        }
        func formatted(_ value: Double?) -> String {
            value?.formatted(.number.precision(.fractionLength(4))) ?? "nil"
        }
        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaKoharuNativeTextBoxDetectorLiteShadowOCRSignal {
            MangaKoharuNativeTextBoxDetectorLiteShadowOCRSignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }
        func gate(
            _ id: String,
            _ name: String,
            _ scope: String,
            _ status: String,
            _ threshold: String,
            _ affected: [Int],
            _ failure: String,
            _ action: String,
            _ signals: [MangaKoharuNativeTextBoxDetectorLiteShadowOCRSignal]
        ) -> MangaKoharuNativeTextBoxDetectorLiteShadowOCRGate {
            MangaKoharuNativeTextBoxDetectorLiteShadowOCRGate(
                gateID: id,
                gateName: name,
                scope: scope,
                status: status,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                decisionSignals: signals,
                failureMeans: failure,
                recommendedAction: action,
                groundTruthUsedForDecision: false
            )
        }
        func emptyBlockLedger(for block: MangaOverlayProbeBlock, outcome: String, bottleneck: String, nextAction: String, reasons: [String]) -> MangaKoharuNativeTextBoxDetectorLiteShadowOCRBlockLedger {
            let currentQuality = Self.ocrCandidateQualityScore(block.finalTextUsedForTranslation)
            return MangaKoharuNativeTextBoxDetectorLiteShadowOCRBlockLedger(
                blockIndex: block.index,
                bubbleID: block.bubbleID,
                blockPassed: block.blockPassed,
                failureCategory: block.failureCategory,
                finalTextUsedForTranslation: block.finalTextUsedForTranslation,
                selectedCandidateID: nil,
                selectedCandidateBBox: nil,
                shadowOCRText: nil,
                shadowOCRNormalizedText: nil,
                currentOCRQualityScore: currentQuality,
                shadowOCRQualityScore: nil,
                qualityDeltaVsCurrent: nil,
                ocrSimilarityDeltaForEvaluation: nil,
                shadowOutcome: outcome,
                wouldHaveImprovedOCRForEvaluation: false,
                whyNotPromoted: reasons,
                primaryBottleneck: bottleneck,
                nextAction: nextAction,
                decisionSignals: [
                    signal("shadowOutcome", outcome, source: "koharuNativeTextBoxDetectorLiteShadowOCRReport"),
                    signal("selectedCandidateID", "nil", source: "koharuNativeTextBoxDetectorLiteReport")
                ],
                evaluationSignals: [
                    signal("currentOCRQualityScore", formatted(currentQuality), source: "blocks.finalTextUsedForTranslation", decision: false, evaluation: true),
                    signal("groundTruthSimilarityCurrentForEvaluation", formatted(block.ocrGroundTruthSimilarity), source: "blocks.ocrGroundTruthSimilarity", decision: false, evaluation: true)
                ],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            )
        }

        let allBlockIndexes = blocks.map(\.index)
        let ciFastLimit = blocks.count
        let fullLimit = blocks.count * 2
        guard let detectorLiteReport, detectorLiteReport.enabled else {
            let ledgers = blocks.map {
                emptyBlockLedger(
                    for: $0,
                    outcome: "notSelected",
                    bottleneck: "nativeTextBoxShadowOCREmpty",
                    nextAction: "generateKoharuNativeTextBoxDetectorLiteReport",
                    reasons: ["detectorLiteReportMissing", "reportOnlyNoPromotionGate"]
                )
            }
            let gates = [
                gate("G-native-textbox-detector-lite-shadow-ocr-input-report", "Input detector-lite report", "TextBoxes", "blocked", "koharuNativeTextBoxDetectorLiteReport.enabled=true", allBlockIndexes, "shadow OCR has no detector-lite candidate source", "generateKoharuNativeTextBoxDetectorLiteReport", [signal("detectorLiteReportPresent", "false", source: "koharuNativeTextBoxDetectorLiteReport")]),
                gate("G-native-textbox-detector-lite-shadow-ocr-report-only", "Report only", "report", "passed", "wouldChangeMainFlow=false", [], "shadow OCR mutates OCR, translation, overlay, blockPassed, currentBlockSource, or crop adoption", "revertBehavioralChange", [signal("wouldChangeMainFlow", "false", source: "koharuNativeTextBoxDetectorLiteShadowOCRReport")])
            ]
            return MangaKoharuNativeTextBoxDetectorLiteShadowOCRReport(
                enabled: true,
                source: "AITRANSProbe",
                referencePipeline: "Koharu",
                referenceConcept: "TextBoxes.NativeDetectorLite.ShadowOCR",
                referenceWorkItemID: "WI-koharu-native-textbox-detector-lite-shadow-ocr",
                evaluatedBlockCount: blocks.count,
                inputCandidateCount: 0,
                selectedCandidateCount: 0,
                ocrExecutedCount: 0,
                ocrSucceededCount: 0,
                emptyOCRCount: 0,
                betterThanCurrentCount: 0,
                worseThanCurrentCount: 0,
                sameAsCurrentCount: 0,
                blockLedgerCount: ledgers.count,
                gateCount: gates.count,
                candidateSelectionLimitCIFast: ciFastLimit,
                candidateSelectionLimitFull: fullLimit,
                groundTruthUsedForDecision: false,
                groundTruthUsedForEvaluationOnly: true,
                wouldChangeMainFlow: false,
                diagnosticOnly: true,
                proxyNotRealKoharuTextBoxes: true,
                proxyNotRealKoharuOCR: true,
                externalArtifactsRequiredForThisReport: false,
                shadowOCRVerdict: "blockedByNoEligibleCandidates",
                ocrOutcomeBreakdown: ["notSelected": blocks.count],
                qualityDeltaBreakdown: [:],
                candidateSourceBreakdown: [:],
                directionHintBreakdown: [:],
                primaryBottleneckBreakdown: countBy(ledgers.map(\.primaryBottleneck)),
                nextActionBreakdown: countBy(ledgers.map(\.nextAction)),
                candidates: [],
                blockLedgers: ledgers,
                gateLedger: gates,
                notes: ["detector-lite shadow OCR report emitted without OCR because v1.39 detector-lite report was unavailable."]
            )
        }

        let limitPerBlock = max(1, candidateLimitPerBlock)
        let maxExecutions = blocks.count * limitPerBlock
        let blockRectByIndex = Dictionary(uniqueKeysWithValues: blocks.map { ($0.index, Self.rect(from: $0.bbox)) })
        func rectArea(_ rect: CGRect) -> Double {
            Double(max(0, rect.width) * max(0, rect.height))
        }
        func overlapRatio(_ lhs: CGRect, _ rhs: CGRect) -> Double {
            let intersection = lhs.intersection(rhs)
            guard !intersection.isNull else { return 0 }
            return rectArea(intersection) / max(1, min(rectArea(lhs), rectArea(rhs)))
        }
        func relationScore(candidate: MangaKoharuNativeTextBoxDetectorLiteCandidate, blockIndex: Int) -> Double {
            guard let blockRect = blockRectByIndex[blockIndex] else { return 0 }
            let candidateRect = Self.rect(from: candidate.bbox)
            let center = CGPoint(x: blockRect.midX, y: blockRect.midY)
            let containmentBonus = candidateRect.contains(center) ? 0.35 : 0
            return overlapRatio(blockRect, candidateRect) + containmentBonus
        }
        let eligibleByBlock = Dictionary(grouping: detectorLiteReport.candidates.flatMap { candidate in
            candidate.relatedCurrentBlockIndexes.map { (blockIndex: $0, candidate: candidate) }
        }) { $0.blockIndex }
            .mapValues { pairs in
                let blockIndex = pairs.first?.blockIndex ?? -1
                return pairs.map(\.candidate)
                    .filter(\.shadowOCREligible)
                    .sorted { lhs, rhs in
                        let lhsRelation = relationScore(candidate: lhs, blockIndex: blockIndex)
                        let rhsRelation = relationScore(candidate: rhs, blockIndex: blockIndex)
                        if abs(lhsRelation - rhsRelation) > 0.0001 { return lhsRelation > rhsRelation }
                        if lhs.score == rhs.score { return lhs.candidateID < rhs.candidateID }
                        return lhs.score > rhs.score
                    }
            }

        var shadowCandidates: [MangaKoharuNativeTextBoxDetectorLiteShadowOCRCandidate] = []
        var blockLedgers: [MangaKoharuNativeTextBoxDetectorLiteShadowOCRBlockLedger] = []
        var executedCount = 0

        for block in blocks.sorted(by: { $0.index < $1.index }) {
            let selectedCandidates = Array((eligibleByBlock[block.index] ?? []).prefix(limitPerBlock))
            guard !selectedCandidates.isEmpty else {
                blockLedgers.append(
                    emptyBlockLedger(
                        for: block,
                        outcome: "notSelected",
                        bottleneck: "nativeTextBoxShadowOCREmpty",
                        nextAction: "reviewDetectorLiteCandidateEligibility",
                        reasons: ["noEligibleDetectorLiteCandidate", "reportOnlyNoPromotionGate"]
                    )
                )
                continue
            }

            var firstCandidateID: String?
            var firstCandidateBBox: [Double]?
            var firstText: String?
            var firstNormalizedText: String?
            var firstQuality: Double?
            var firstDelta: Double?
            var firstSimilarityDelta: Double?
            var firstPreservation: Double?
            var firstSourceScore: Double?
            var firstOutcome = "notSelected"
            var firstBottleneck = "manualReviewOnly"
            var firstNextAction = "keepDetectorLiteShadowOCRReportOnly"
            var firstReasons: [String] = []

            for sourceCandidate in selectedCandidates where executedCount < maxExecutions {
                let currentText = block.finalTextUsedForTranslation
                let currentQuality = Self.ocrCandidateQualityScore(currentText)
                let currentWords = Self.ocrCandidateWords(currentText)
                let isVerticalCandidate = sourceCandidate.directionHint == "verticalCandidate"
                let rotationAngles = isVerticalCandidate ? [0, 90] : [0]
                let recognitionLanguages = isVerticalCandidate ? ["ja-JP", "ja", "en-US", "en"] : nil
                var attempts: [(text: String?, cropBBox: [Double], paddingX: Double, paddingY: Double, rotationApplied: Double, errorCode: String?)] = []
                for rotationAngle in rotationAngles {
                    do {
                        let crop = try await mangaOverlayProbeService.recognizeExternalTextBoxCrop(
                            in: image,
                            textBoxBBox: sourceCandidate.bbox,
                            options: preprocessing,
                            rotationAngle: rotationAngle,
                            recognitionLanguages: recognitionLanguages
                        )
                        attempts.append((crop.text, crop.cropBBox, crop.paddingX, crop.paddingY, crop.rotationApplied, nil))
                    } catch {
                        attempts.append((nil, sourceCandidate.bbox, 0, 0, Double(rotationAngle), "\(type(of: error))"))
                    }
                }
                let crop = attempts.max { lhs, rhs in
                    let lhsText = (lhs.text ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
                    let rhsText = (rhs.text ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
                    if (lhs.errorCode == nil) != (rhs.errorCode == nil) {
                        return lhs.errorCode != nil
                    }
                    if lhsText.isEmpty != rhsText.isEmpty {
                        return lhsText.isEmpty
                    }
                    let lhsQuality = Self.ocrCandidateQualityScore(lhsText)
                    let rhsQuality = Self.ocrCandidateQualityScore(rhsText)
                    if abs(lhsQuality - rhsQuality) > 0.0001 {
                        return lhsQuality < rhsQuality
                    }
                    let lhsPreservation = Self.wordPreservationRatio(
                        sourceWords: currentWords,
                        candidateWords: Self.ocrCandidateWords(lhsText)
                    )
                    let rhsPreservation = Self.wordPreservationRatio(
                        sourceWords: currentWords,
                        candidateWords: Self.ocrCandidateWords(rhsText)
                    )
                    if abs(lhsPreservation - rhsPreservation) > 0.0001 {
                        return lhsPreservation < rhsPreservation
                    }
                    return lhs.rotationApplied > rhs.rotationApplied
                } ?? (nil, sourceCandidate.bbox, 0, 0, 0, "noShadowOCRAttempt")
                let errorCode = crop.errorCode
                executedCount += 1
                let rawText = crop.text
                let normalizedText = (rawText ?? "")
                    .replacingOccurrences(of: "\r", with: "\n")
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                let shadowQuality = Self.ocrCandidateQualityScore(normalizedText)
                let qualityDelta = shadowQuality - currentQuality
                let preservation = Self.wordPreservationRatio(
                    sourceWords: currentWords,
                    candidateWords: Self.ocrCandidateWords(normalizedText)
                )
                let currentSimilarity = block.ocrGroundTruthSimilarity
                let shadowMatch = MangaOverlayProbeService.bestGroundTruthMatch(text: normalizedText, groundTruth: groundTruth)
                let shadowSimilarity = normalizedText.isEmpty ? nil : shadowMatch.similarity
                let similarityDelta = shadowSimilarity.flatMap { shadow in currentSimilarity.map { shadow - $0 } }
                var rejectionReasons = sourceCandidate.rejectionReasons
                if errorCode != nil {
                    rejectionReasons.append("ocrExecutionFailed")
                }
                if normalizedText.isEmpty {
                    rejectionReasons.append("emptyShadowOCR")
                }
                if currentWords.count >= 3, preservation < 0.55 {
                    rejectionReasons.append("wordPreservationGuardrailFailed")
                }
                if qualityDelta <= 0.03 {
                    rejectionReasons.append("qualityDeltaInsufficient")
                }
                let outcome: String
                if errorCode != nil {
                    outcome = "ocrFailed"
                } else if normalizedText.isEmpty {
                    outcome = "emptyOCR"
                } else if qualityDelta > 0.03 {
                    outcome = "betterThanCurrent"
                } else if qualityDelta < -0.03 {
                    outcome = "worseThanCurrent"
                } else {
                    outcome = "sameAsCurrent"
                }
                let candidateID = "NTBDL-SOCR-\(block.index)-\(sourceCandidate.candidateID)"
                shadowCandidates.append(
                    MangaKoharuNativeTextBoxDetectorLiteShadowOCRCandidate(
                        candidateID: candidateID,
                        sourceCandidateID: sourceCandidate.candidateID,
                        source: "nativeDetectorLite.shadowOCR",
                        sourceBubbleID: sourceCandidate.sourceBubbleID,
                        relatedBlockIndex: block.index,
                        bbox: crop.cropBBox,
                        directionHint: sourceCandidate.directionHint,
                        cropPadding: [crop.paddingX, crop.paddingY],
                        scaleFactor: preprocessing.cropUpscaleEnabled ? preprocessing.cropScale : 1,
                        rotationApplied: crop.rotationApplied,
                        ocrRawText: rawText,
                        ocrNormalizedText: normalizedText,
                        ocrSucceeded: errorCode == nil && !normalizedText.isEmpty,
                        ocrEmpty: normalizedText.isEmpty,
                        ocrErrorCode: errorCode,
                        wordPreservationVsCurrent: preservation,
                        qualityScoreCurrent: currentQuality,
                        qualityScoreShadow: shadowQuality,
                        qualityDeltaVsCurrent: qualityDelta,
                        groundTruthSimilarityCurrentForEvaluation: currentSimilarity,
                        groundTruthSimilarityShadowForEvaluation: shadowSimilarity,
                        groundTruthSimilarityDeltaForEvaluation: similarityDelta,
                        outcome: outcome,
                        promotionVerdict: "reportOnlyNoPromotion",
                        decisionSignals: [
                            signal("sourceCandidateID", sourceCandidate.candidateID, source: "koharuNativeTextBoxDetectorLiteReport"),
                            signal("sourceCandidateScore", formatted(sourceCandidate.score), source: "koharuNativeTextBoxDetectorLiteReport"),
                            signal("shadowOCREligible", String(sourceCandidate.shadowOCREligible), source: "koharuNativeTextBoxDetectorLiteReport"),
                            signal("candidateLimitPerBlock", String(limitPerBlock), source: "probeRunMode"),
                            signal("rotationAttempts", rotationAngles.map(String.init).joined(separator: ","), source: "koharuNativeTextBoxDetectorLiteShadowOCRReport"),
                            signal("rotationApplied", formatted(crop.rotationApplied), source: "koharuNativeTextBoxDetectorLiteShadowOCRReport"),
                            signal("recognitionLanguages", recognitionLanguages?.joined(separator: ",") ?? "default", source: "koharuNativeTextBoxDetectorLiteShadowOCRReport")
                        ],
                        evaluationSignals: [
                            signal("qualityDeltaVsCurrent", formatted(qualityDelta), source: "shadowOCRQuality", decision: false, evaluation: true),
                            signal("groundTruthSimilarityDeltaForEvaluation", formatted(similarityDelta), source: "test/1.ground_truth.json", decision: false, evaluation: true),
                            signal("wordPreservationVsCurrent", formatted(preservation), source: "blocks.finalTextUsedForTranslation", decision: false, evaluation: true)
                        ],
                        rejectionReasons: Array(Set(rejectionReasons)).sorted(),
                        groundTruthUsedForDecision: false,
                        wouldChangeMainFlow: false,
                        diagnosticOnly: true
                    )
                )
                func outcomeRank(_ outcome: String) -> Int {
                    switch outcome {
                    case "betterThanCurrent": return 4
                    case "sameAsCurrent": return 3
                    case "worseThanCurrent": return 2
                    case "emptyOCR": return 1
                    default: return 0
                    }
                }
                let shouldReplaceBest: Bool
                if firstCandidateID == nil {
                    shouldReplaceBest = true
                } else if outcomeRank(outcome) != outcomeRank(firstOutcome) {
                    shouldReplaceBest = outcomeRank(outcome) > outcomeRank(firstOutcome)
                } else if abs(qualityDelta - (firstDelta ?? -Double.infinity)) > 0.0001 {
                    shouldReplaceBest = qualityDelta > (firstDelta ?? -Double.infinity)
                } else if abs(preservation - (firstPreservation ?? -Double.infinity)) > 0.0001 {
                    shouldReplaceBest = preservation > (firstPreservation ?? -Double.infinity)
                } else if abs(sourceCandidate.score - (firstSourceScore ?? -Double.infinity)) > 0.0001 {
                    shouldReplaceBest = sourceCandidate.score > (firstSourceScore ?? -Double.infinity)
                } else {
                    shouldReplaceBest = candidateID < (firstCandidateID ?? candidateID)
                }
                if shouldReplaceBest {
                    firstCandidateID = candidateID
                    firstCandidateBBox = crop.cropBBox
                    firstText = rawText
                    firstNormalizedText = normalizedText
                    firstQuality = shadowQuality
                    firstDelta = qualityDelta
                    firstSimilarityDelta = similarityDelta
                    firstPreservation = preservation
                    firstSourceScore = sourceCandidate.score
                    firstOutcome = outcome
                    firstBottleneck = {
                        switch outcome {
                        case "betterThanCurrent": return "nativeTextBoxShadowOCRPromising"
                        case "emptyOCR": return "nativeTextBoxShadowOCREmpty"
                        case "worseThanCurrent": return "nativeTextBoxShadowOCRWorse"
                        case "ocrFailed": return "manualReviewOnly"
                        default:
                            if block.failureCategory == "ocrInputSuspect" { return "ocrInputDamageStillOpen" }
                            if block.failureCategory == "modelOutputFailure" || block.failureCategory == "translationLanguageQualityFailure" { return "modelTranslationFloor" }
                            if block.renderCollisionResolved { return "renderLocked" }
                            return "manualReviewOnly"
                        }
                    }()
                    firstNextAction = {
                        switch firstBottleneck {
                        case "nativeTextBoxShadowOCRPromising": return "reviewDetectorLiteShadowOCRInFullProbe"
                        case "nativeTextBoxShadowOCREmpty": return "inspectDetectorLiteCropBounds"
                        case "nativeTextBoxShadowOCRWorse": return "keepCurrentFusedOCRAndCollectRealTextBoxes"
                        case "ocrInputDamageStillOpen": return "collectRealTextBoxesOrSegmentMask"
                        case "modelTranslationFloor": return "keepModelFloorSeparate"
                        case "renderLocked": return "keepRenderLockReportOnly"
                        default: return "manualReviewOnly"
                        }
                    }()
                    firstReasons = Array(Set(rejectionReasons + [
                        "reportOnlyNoPromotionGate",
                        "mainFlowMutationForbidden",
                        "groundTruthEvaluationOnly",
                        "candidateFromProxyTextBox"
                    ])).sorted()
                }
            }

            let currentQuality = Self.ocrCandidateQualityScore(block.finalTextUsedForTranslation)
            blockLedgers.append(
                MangaKoharuNativeTextBoxDetectorLiteShadowOCRBlockLedger(
                    blockIndex: block.index,
                    bubbleID: block.bubbleID,
                    blockPassed: block.blockPassed,
                    failureCategory: block.failureCategory,
                    finalTextUsedForTranslation: block.finalTextUsedForTranslation,
                    selectedCandidateID: firstCandidateID,
                    selectedCandidateBBox: firstCandidateBBox,
                    shadowOCRText: firstText,
                    shadowOCRNormalizedText: firstNormalizedText,
                    currentOCRQualityScore: currentQuality,
                    shadowOCRQualityScore: firstQuality,
                    qualityDeltaVsCurrent: firstDelta,
                    ocrSimilarityDeltaForEvaluation: firstSimilarityDelta,
                    shadowOutcome: firstOutcome,
                    wouldHaveImprovedOCRForEvaluation: (firstSimilarityDelta ?? 0) > 0.03 || firstOutcome == "betterThanCurrent",
                    whyNotPromoted: firstReasons,
                    primaryBottleneck: firstBottleneck,
                    nextAction: firstNextAction,
                    decisionSignals: [
                        signal("selectedCandidateID", firstCandidateID ?? "nil", source: "koharuNativeTextBoxDetectorLiteReport"),
                        signal("shadowOutcome", firstOutcome, source: "koharuNativeTextBoxDetectorLiteShadowOCRReport")
                    ],
                    evaluationSignals: [
                        signal("qualityDeltaVsCurrent", formatted(firstDelta), source: "shadowOCRQuality", decision: false, evaluation: true),
                        signal("ocrSimilarityDeltaForEvaluation", formatted(firstSimilarityDelta), source: "test/1.ground_truth.json", decision: false, evaluation: true)
                    ],
                    groundTruthUsedForDecision: false,
                    wouldChangeMainFlow: false,
                    diagnosticOnly: true
                )
            )
        }

        let better = shadowCandidates.filter { $0.outcome == "betterThanCurrent" }.count
        let worse = shadowCandidates.filter { $0.outcome == "worseThanCurrent" }.count
        let same = shadowCandidates.filter { $0.outcome == "sameAsCurrent" }.count
        let empty = shadowCandidates.filter { $0.outcome == "emptyOCR" }.count
        let succeeded = shadowCandidates.filter(\.ocrSucceeded).count
        let selected = shadowCandidates.count
        let verticalCandidateCount = shadowCandidates.filter { $0.directionHint == "verticalCandidate" }.count
        let rotatedAppliedCount = shadowCandidates.filter { abs($0.rotationApplied) > 0.0001 }.count
        let rotationBreakdown = countBy(shadowCandidates.map { formatted($0.rotationApplied) })
        let qualityDeltaBreakdown = countBy(shadowCandidates.map {
            if $0.outcome == "emptyOCR" || $0.outcome == "ocrFailed" { return $0.outcome }
            if $0.qualityDeltaVsCurrent > 0.03 { return "positive" }
            if $0.qualityDeltaVsCurrent < -0.03 { return "negative" }
            return "neutral"
        })
        let verdict: String
        if detectorLiteReport.shadowOCREligibleCandidateCount == 0 || selected == 0 {
            verdict = "blockedByNoEligibleCandidates"
        } else if better > 0 {
            verdict = "detectorLiteOCRImprovesSomeBlocksReportOnly"
        } else if empty + worse >= max(1, selected) {
            verdict = "detectorLiteOCREmptyOrWorse"
        } else if blockLedgers.filter({ $0.primaryBottleneck == "modelTranslationFloor" }).count >= max(1, blocks.count / 2) {
            verdict = "modelFloorDominates"
        } else {
            verdict = "detectorLiteOCRNoNetBenefit"
        }
        let gates = [
            gate("G-native-textbox-detector-lite-shadow-ocr-report-only", "Report only", "report", "passed", "wouldChangeMainFlow=false", [], "shadow OCR mutates main OCR, translation, overlay, blockPassed, failureCategory, currentBlockSource, or crop adoption", "revertBehavioralChange", [signal("wouldChangeMainFlow", "false", source: "koharuNativeTextBoxDetectorLiteShadowOCRReport")]),
            gate("G-native-textbox-detector-lite-shadow-ocr-no-ground-truth-decision", "No ground truth decision", "report", "passed", "groundTruthUsedForDecision=false", allBlockIndexes, "ground truth drives candidate selection, OCR execution, nextAction, or gate status", "moveGroundTruthToEvaluationSignalsOnly", [signal("groundTruthUsedForDecision", "false", source: "koharuNativeTextBoxDetectorLiteShadowOCRReport")]),
            gate("G-native-textbox-detector-lite-shadow-ocr-input-source", "Detector-lite source only", "TextBoxes", "passed", "source=nativeDetectorLite.shadowOCR", allBlockIndexes, "shadow OCR falls back to Vision OCR bbox, pre-crop plan, line plan, TextRegion crop, or ground truth box", "keepDetectorLiteCandidateSourceOnly", [signal("candidateSource", "nativeDetectorLite.shadowOCR", source: "koharuNativeTextBoxDetectorLiteShadowOCRReport")]),
            gate("G-native-textbox-detector-lite-shadow-ocr-ci-fast-budget", "CI fast budget", "ci-fast", selected <= ciFastLimit ? "passed" : "warning", "selectedCandidateCount<=totalBlocksDetected in ci-fast", allBlockIndexes, "ci-fast shadow OCR exceeds per-block budget", "reduceShadowOCRCandidateLimit", [signal("selectedCandidateCount", String(selected), source: "koharuNativeTextBoxDetectorLiteShadowOCRReport"), signal("ciFastLimit", String(ciFastLimit), source: "probeRunMode")]),
            gate("G-native-textbox-detector-lite-shadow-ocr-block-ledger-count", "Block ledger count", "blocks", blockLedgers.count == blocks.count ? "passed" : "warning", "blockLedgerCount==totalBlocksDetected", allBlockIndexes, "some final blocks lack shadow OCR ledger rows", "restoreBlockLedgerCoverage", [signal("blockLedgerCount", String(blockLedgers.count), source: "koharuNativeTextBoxDetectorLiteShadowOCRReport")]),
            gate("G-native-textbox-detector-lite-shadow-ocr-proxy-boundary", "Proxy boundary", "TextBoxes/OCR", "passed", "proxyNotRealKoharuTextBoxes=true and proxyNotRealKoharuOCR=true", allBlockIndexes, "detector-lite shadow OCR is promoted as real Koharu TextBoxes or OCR", "keepProxyBoundaryOrCollectRealArtifact", [signal("proxyNotRealKoharuTextBoxes", "true", source: "koharuNativeTextBoxDetectorLiteShadowOCRReport"), signal("proxyNotRealKoharuOCR", "true", source: "koharuNativeTextBoxDetectorLiteShadowOCRReport")]),
            gate("G-native-textbox-detector-lite-shadow-ocr-vertical-rotation-budget", "Vertical rotation budget", "OcrText", "passed", "verticalCandidate uses bounded [0,90] shadow OCR attempts only", allBlockIndexes, "vertical shadow OCR expands into unbounded rotation or candidate sweeps", "keepVerticalShadowOCRBounded", [signal("verticalCandidateCount", String(verticalCandidateCount), source: "koharuNativeTextBoxDetectorLiteShadowOCRReport"), signal("rotatedAppliedCount", String(rotatedAppliedCount), source: "koharuNativeTextBoxDetectorLiteShadowOCRReport"), signal("rotationBreakdown", rotationBreakdown.map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ","), source: "koharuNativeTextBoxDetectorLiteShadowOCRReport")]),
            gate("G-native-textbox-detector-lite-shadow-ocr-no-llm", "No LLM", "Translations", "passed", "no LLM calls added", [], "shadow OCR triggers translation model calls or prompt changes", "removeLLMFromShadowOCR", [signal("llmCalls", "0", source: "koharuNativeTextBoxDetectorLiteShadowOCRReport")]),
            gate("G-native-textbox-detector-lite-shadow-ocr-visible-failures", "Visible failures", "report", shadowCandidates.isEmpty || !countBy(shadowCandidates.map(\.outcome)).isEmpty ? "passed" : "warning", "empty/failed/worse outcomes recorded", allBlockIndexes, "shadow OCR failures are silently skipped", "writeFailureLedgers", [signal("ocrOutcomeBreakdown", countBy(shadowCandidates.map(\.outcome)).map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ","), source: "koharuNativeTextBoxDetectorLiteShadowOCRReport")])
        ]

        return MangaKoharuNativeTextBoxDetectorLiteShadowOCRReport(
            enabled: true,
            source: "AITRANSProbe",
            referencePipeline: "Koharu",
            referenceConcept: "TextBoxes.NativeDetectorLite.ShadowOCR",
            referenceWorkItemID: "WI-koharu-native-textbox-detector-lite-shadow-ocr",
            evaluatedBlockCount: blocks.count,
            inputCandidateCount: detectorLiteReport.candidateCount,
            selectedCandidateCount: selected,
            ocrExecutedCount: shadowCandidates.count,
            ocrSucceededCount: succeeded,
            emptyOCRCount: empty,
            betterThanCurrentCount: better,
            worseThanCurrentCount: worse,
            sameAsCurrentCount: same,
            blockLedgerCount: blockLedgers.count,
            gateCount: gates.count,
            candidateSelectionLimitCIFast: ciFastLimit,
            candidateSelectionLimitFull: fullLimit,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            proxyNotRealKoharuTextBoxes: true,
            proxyNotRealKoharuOCR: true,
            externalArtifactsRequiredForThisReport: false,
            shadowOCRVerdict: verdict,
            ocrOutcomeBreakdown: countBy(shadowCandidates.map(\.outcome) + blockLedgers.filter { $0.selectedCandidateID == nil }.map(\.shadowOutcome)),
            qualityDeltaBreakdown: qualityDeltaBreakdown,
            candidateSourceBreakdown: countBy(shadowCandidates.map(\.source)),
            directionHintBreakdown: countBy(shadowCandidates.map(\.directionHint)),
            primaryBottleneckBreakdown: countBy(blockLedgers.map(\.primaryBottleneck)),
            nextActionBreakdown: countBy(blockLedgers.map(\.nextAction)),
            candidates: shadowCandidates.sorted { $0.candidateID < $1.candidateID },
            blockLedgers: blockLedgers.sorted { $0.blockIndex < $1.blockIndex },
            gateLedger: gates,
            notes: [
                "koharuNativeTextBoxDetectorLiteShadowOCRReport runs report-only Vision OCR on v1.39 nativeDetectorLite candidates.",
                "Candidate selection uses detector-lite score, eligibility, bubble coverage, glyph overlap, block relation, and direction hint; ground truth is evaluation-only.",
                "verticalCandidate crops run a bounded report-only [0,90] rotation comparison with a ja-JP/ja/en-US/en Vision language profile and record rotationApplied; horizontal candidates keep the existing 0-degree default OCR path.",
                "Shadow OCR output is not written to finalTextUsedForTranslation and does not change translation, overlay, blockPassed, failureCategory, currentBlockSource, or textRegionCropReport.adoptedCount.",
                "proxyNotRealKoharuTextBoxes=true and proxyNotRealKoharuOCR=true: this is not a real Koharu TextBoxes/OcrText artifact."
            ]
        )
    }

    private func makeKoharuNativeTextBoxDetectorLiteRefinementReport(
        blocks: [MangaOverlayProbeBlock],
        image: CGImage,
        bubbleGeometry: MangaOverlayBubbleGeometryDiagnostics,
        detectorLiteReport: MangaKoharuNativeTextBoxDetectorLiteReport?,
        shadowOCRReport: MangaKoharuNativeTextBoxDetectorLiteShadowOCRReport?,
        groundTruth: [MangaGroundTruthEntry],
        preprocessing: MangaOverlayPreprocessingOptions,
        candidateLimitPerBlock: Int,
        totalCandidateLimit: Int
    ) async throws -> MangaKoharuNativeTextBoxDetectorLiteRefinementReport {
        func uniqueSorted(_ values: [Int]) -> [Int] { Array(Set(values)).sorted() }
        func countBy(_ values: [String]) -> [String: Int] {
            values.reduce(into: [:]) { partial, value in partial[value, default: 0] += 1 }
        }
        func formatted(_ value: Double?) -> String {
            value?.formatted(.number.precision(.fractionLength(4))) ?? "nil"
        }
        func area(_ rect: CGRect) -> Double {
            Double(max(0, rect.width) * max(0, rect.height))
        }
        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaKoharuNativeTextBoxDetectorLiteRefinementSignal {
            MangaKoharuNativeTextBoxDetectorLiteRefinementSignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }
        func gate(
            _ id: String,
            _ name: String,
            _ scope: String,
            _ status: String,
            _ threshold: String,
            _ affected: [Int],
            _ failure: String,
            _ action: String,
            _ signals: [MangaKoharuNativeTextBoxDetectorLiteRefinementSignal]
        ) -> MangaKoharuNativeTextBoxDetectorLiteRefinementGate {
            MangaKoharuNativeTextBoxDetectorLiteRefinementGate(
                gateID: id,
                gateName: name,
                scope: scope,
                status: status,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                decisionSignals: signals,
                failureMeans: failure,
                recommendedAction: action,
                groundTruthUsedForDecision: false
            )
        }
        func emptyLedger(
            for block: MangaOverlayProbeBlock,
            shadow: MangaKoharuNativeTextBoxDetectorLiteShadowOCRBlockLedger?,
            targetReason: String,
            outcome: String,
            bottleneck: String,
            nextAction: String,
            reasons: [String]
        ) -> MangaKoharuNativeTextBoxDetectorLiteRefinementBlockLedger {
            MangaKoharuNativeTextBoxDetectorLiteRefinementBlockLedger(
                blockIndex: block.index,
                bubbleID: block.bubbleID,
                blockPassed: block.blockPassed,
                failureCategory: block.failureCategory,
                finalTextUsedForTranslation: block.finalTextUsedForTranslation,
                detectorLiteShadowOutcome: shadow?.shadowOutcome,
                detectorLiteShadowText: shadow?.shadowOCRNormalizedText,
                selectedRefinedCandidateID: nil,
                baseCandidateID: shadow?.selectedCandidateID,
                baseBBox: shadow?.selectedCandidateBBox,
                refinedBBox: nil,
                refinementStrategy: nil,
                refinedOCRText: nil,
                refinedOCRNormalizedText: nil,
                currentOCRQualityScore: Self.ocrCandidateQualityScore(block.finalTextUsedForTranslation),
                detectorLiteShadowOCRQualityScore: shadow?.shadowOCRQualityScore,
                refinedOCRQualityScore: nil,
                qualityDeltaVsCurrent: nil,
                qualityDeltaVsDetectorLiteShadow: nil,
                ocrSimilarityDeltaForEvaluation: nil,
                targetReason: targetReason,
                refinementOutcome: outcome,
                wouldHaveImprovedOCRForEvaluation: false,
                primaryBottleneck: bottleneck,
                nextAction: nextAction,
                whyNotPromoted: reasons,
                decisionSignals: [
                    signal("targetReason", targetReason, source: "koharuNativeTextBoxDetectorLiteRefinementReport"),
                    signal("refinementOutcome", outcome, source: "koharuNativeTextBoxDetectorLiteRefinementReport")
                ],
                evaluationSignals: [
                    signal("groundTruthSimilarityCurrentForEvaluation", formatted(block.ocrGroundTruthSimilarity), source: "blocks.ocrGroundTruthSimilarity", decision: false, evaluation: true)
                ],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            )
        }

        let allBlockIndexes = blocks.map(\.index)
        let ciFastLimit = min(6, blocks.count)
        let fullLimit = max(1, blocks.count * 2)
        let limitPerBlock = max(1, candidateLimitPerBlock)
        let maxExecutions = max(0, totalCandidateLimit)
        let shadowByBlock = Dictionary(
            uniqueKeysWithValues: (shadowOCRReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )

        guard let detectorLiteReport, detectorLiteReport.enabled,
              let shadowOCRReport, shadowOCRReport.enabled else {
            let ledgers = blocks.map { block in
                emptyLedger(
                    for: block,
                    shadow: shadowByBlock[block.index],
                    targetReason: "missingUpstreamDetectorLiteShadowOCR",
                    outcome: "notEligible",
                    bottleneck: "needsRealTextBoxes",
                    nextAction: "generateDetectorLiteShadowOCRFirst",
                    reasons: ["detectorLiteOrShadowOCRReportMissing", "reportOnlyNoPromotionGate"]
                )
            }
            let gates = [
                gate("G-native-textbox-detector-lite-refinement-input-reports", "Input reports", "TextBoxes/OcrText", "blocked", "v1.39 and v1.40 reports enabled", allBlockIndexes, "refinement has no detector-lite parent candidate or shadow OCR baseline", "generateDetectorLiteAndShadowOCRReports", [signal("detectorLiteReportPresent", String(detectorLiteReport != nil), source: "koharuNativeTextBoxDetectorLiteReport"), signal("shadowOCRReportPresent", String(shadowOCRReport != nil), source: "koharuNativeTextBoxDetectorLiteShadowOCRReport")]),
                gate("G-native-textbox-detector-lite-refinement-report-only", "Report only", "report", "passed", "wouldChangeMainFlow=false", [], "refinement mutates main OCR, translation, overlay, blockPassed, failureCategory, currentBlockSource, or crop adoption", "revertBehavioralChange", [signal("wouldChangeMainFlow", "false", source: "koharuNativeTextBoxDetectorLiteRefinementReport")])
            ]
            return MangaKoharuNativeTextBoxDetectorLiteRefinementReport(
                enabled: true,
                source: "AITRANSProbe",
                referencePipeline: "Koharu",
                referenceConcept: "TextBoxes.NativeDetectorLite.ClosedLoopRefinement",
                referenceWorkItemID: "WI-koharu-native-textbox-detector-lite-refinement",
                evaluatedBlockCount: blocks.count,
                inputDetectorLiteCandidateCount: detectorLiteReport?.candidateCount ?? 0,
                inputShadowOCRCandidateCount: shadowOCRReport?.selectedCandidateCount ?? 0,
                targetBlockCount: 0,
                refinedCandidateCount: 0,
                ocrExecutedCount: 0,
                ocrSucceededCount: 0,
                emptyOCRCount: 0,
                refinedBetterThanDetectorLiteCount: 0,
                refinedBetterThanCurrentCount: 0,
                refinedWorseThanDetectorLiteCount: 0,
                sameAsDetectorLiteCount: 0,
                blockLedgerCount: ledgers.count,
                gateCount: gates.count,
                candidateSelectionLimitCIFast: ciFastLimit,
                candidateSelectionLimitFull: fullLimit,
                groundTruthUsedForDecision: false,
                groundTruthUsedForEvaluationOnly: true,
                wouldChangeMainFlow: false,
                diagnosticOnly: true,
                proxyNotRealKoharuTextBoxes: true,
                proxyNotRealKoharuOCR: true,
                externalArtifactsRequiredForThisReport: false,
                refinementVerdict: "blockedByMissingDetectorLiteShadowOCR",
                targetReasonBreakdown: countBy(ledgers.map(\.targetReason)),
                refinementStrategyBreakdown: [:],
                ocrOutcomeBreakdown: countBy(ledgers.map(\.refinementOutcome)),
                qualityDeltaBreakdown: [:],
                primaryBottleneckBreakdown: countBy(ledgers.map(\.primaryBottleneck)),
                nextActionBreakdown: countBy(ledgers.map(\.nextAction)),
                candidates: [],
                blockLedgers: ledgers,
                gateLedger: gates,
                notes: ["v1.41 refinement report emitted blocked ledger because v1.39/v1.40 upstream report was unavailable."]
            )
        }

        guard let providerData = image.dataProvider?.data,
              let bytes = CFDataGetBytePtr(providerData),
              image.bitsPerPixel == 32 else {
            let ledgers = blocks.map { block in
                emptyLedger(
                    for: block,
                    shadow: shadowByBlock[block.index],
                    targetReason: "sourceImagePixelsUnavailable",
                    outcome: "notEligible",
                    bottleneck: "manualReviewOnly",
                    nextAction: "restoreProbeImageByteAccess",
                    reasons: ["sourceImageBytesUnavailable", "reportOnlyNoPromotionGate"]
                )
            }
            let gates = [
                gate("G-native-textbox-detector-lite-refinement-image-bytes", "Image bytes available", "SourceImage", "blocked", "32-bit CGImage provider bytes readable", allBlockIndexes, "refinement cannot compute dark component envelope", "restoreProbeImageByteAccess", [signal("imageBytesAvailable", "false", source: "SourceImage")])
            ]
            return MangaKoharuNativeTextBoxDetectorLiteRefinementReport(
                enabled: true,
                source: "AITRANSProbe",
                referencePipeline: "Koharu",
                referenceConcept: "TextBoxes.NativeDetectorLite.ClosedLoopRefinement",
                referenceWorkItemID: "WI-koharu-native-textbox-detector-lite-refinement",
                evaluatedBlockCount: blocks.count,
                inputDetectorLiteCandidateCount: detectorLiteReport.candidateCount,
                inputShadowOCRCandidateCount: shadowOCRReport.selectedCandidateCount,
                targetBlockCount: 0,
                refinedCandidateCount: 0,
                ocrExecutedCount: 0,
                ocrSucceededCount: 0,
                emptyOCRCount: 0,
                refinedBetterThanDetectorLiteCount: 0,
                refinedBetterThanCurrentCount: 0,
                refinedWorseThanDetectorLiteCount: 0,
                sameAsDetectorLiteCount: 0,
                blockLedgerCount: ledgers.count,
                gateCount: gates.count,
                candidateSelectionLimitCIFast: ciFastLimit,
                candidateSelectionLimitFull: fullLimit,
                groundTruthUsedForDecision: false,
                groundTruthUsedForEvaluationOnly: true,
                wouldChangeMainFlow: false,
                diagnosticOnly: true,
                proxyNotRealKoharuTextBoxes: true,
                proxyNotRealKoharuOCR: true,
                externalArtifactsRequiredForThisReport: false,
                refinementVerdict: "manualReviewOnly",
                targetReasonBreakdown: countBy(ledgers.map(\.targetReason)),
                refinementStrategyBreakdown: [:],
                ocrOutcomeBreakdown: countBy(ledgers.map(\.refinementOutcome)),
                qualityDeltaBreakdown: [:],
                primaryBottleneckBreakdown: countBy(ledgers.map(\.primaryBottleneck)),
                nextActionBreakdown: countBy(ledgers.map(\.nextAction)),
                candidates: [],
                blockLedgers: ledgers,
                gateLedger: gates,
                notes: ["Source image pixels were unavailable; refinement did not execute OCR."]
            )
        }

        let imageBounds = CGRect(x: 0, y: 0, width: CGFloat(image.width), height: CGFloat(image.height))
        let bytesPerRow = image.bytesPerRow
        let bubbleRectByID = Dictionary(
            uniqueKeysWithValues: bubbleGeometry.bubbles.map { ($0.id, Self.rect(from: $0.bbox)) }
        )
        let detectorCandidateByID = Dictionary(
            uniqueKeysWithValues: detectorLiteReport.candidates.map { ($0.candidateID, $0) }
        )
        var detectorCandidatesByBlock: [Int: [MangaKoharuNativeTextBoxDetectorLiteCandidate]] = [:]
        for candidate in detectorLiteReport.candidates {
            for blockIndex in candidate.relatedCurrentBlockIndexes {
                detectorCandidatesByBlock[blockIndex, default: []].append(candidate)
            }
        }
        for blockIndex in detectorCandidatesByBlock.keys {
            detectorCandidatesByBlock[blockIndex]?.sort { lhs, rhs in
                if lhs.score == rhs.score {
                    return lhs.candidateID < rhs.candidateID
                }
                return lhs.score > rhs.score
            }
        }
        let shadowCandidateByBlock = Dictionary(grouping: shadowOCRReport.candidates) { $0.relatedBlockIndex }

        func projectionPeakCount(_ values: [Int], threshold: Int) -> Int {
            var peaks = 0
            var inPeak = false
            for value in values {
                if value >= threshold {
                    if !inPeak { peaks += 1 }
                    inPeak = true
                } else {
                    inPeak = false
                }
            }
            return peaks
        }

        func analyze(_ rect: CGRect) -> (envelope: CGRect?, density: Double, peaks: Int, components: Int) {
            let scanRect = Self.clamp(rect.integral, to: imageBounds)
            let width = Int(scanRect.width)
            let height = Int(scanRect.height)
            guard width > 0, height > 0 else { return (nil, 0, 0, 0) }
            var gray = [UInt8](repeating: 255, count: width * height)
            var sum = 0
            for localY in 0..<height {
                let y = Int(scanRect.minY) + localY
                for localX in 0..<width {
                    let x = Int(scanRect.minX) + localX
                    guard x >= 0, y >= 0, x < image.width, y < image.height else { continue }
                    let offset = y * bytesPerRow + x * 4
                    let luminance = (Int(bytes[offset]) * 299 + Int(bytes[offset + 1]) * 587 + Int(bytes[offset + 2]) * 114) / 1000
                    gray[localY * width + localX] = UInt8(max(0, min(255, luminance)))
                    sum += luminance
                }
            }
            let threshold = max(28, min(210, Int(Double(sum) / Double(max(1, width * height)) - 24)))
            var foreground = [Bool](repeating: false, count: width * height)
            var minX = width
            var minY = height
            var maxX = -1
            var maxY = -1
            var darkPixels = 0
            var horizontal = [Int](repeating: 0, count: height)
            var vertical = [Int](repeating: 0, count: width)
            for y in 0..<height {
                for x in 0..<width {
                    let index = y * width + x
                    if Int(gray[index]) <= threshold {
                        foreground[index] = true
                        minX = min(minX, x)
                        minY = min(minY, y)
                        maxX = max(maxX, x)
                        maxY = max(maxY, y)
                        darkPixels += 1
                        horizontal[y] += 1
                        vertical[x] += 1
                    }
                }
            }
            guard darkPixels > 0, maxX >= minX, maxY >= minY else { return (nil, 0, 0, 0) }
            var visited = [Bool](repeating: false, count: width * height)
            var componentCount = 0
            for startY in 0..<height {
                for startX in 0..<width {
                    let start = startY * width + startX
                    guard foreground[start], !visited[start] else { continue }
                    componentCount += 1
                    var queue = [start]
                    var cursor = 0
                    visited[start] = true
                    while cursor < queue.count {
                        let current = queue[cursor]
                        cursor += 1
                        let cy = current / width
                        let cx = current % width
                        for ny in max(0, cy - 1)...min(height - 1, cy + 1) {
                            for nx in max(0, cx - 1)...min(width - 1, cx + 1) {
                                let next = ny * width + nx
                                if foreground[next], !visited[next] {
                                    visited[next] = true
                                    queue.append(next)
                                }
                            }
                        }
                    }
                }
            }
            let envelope = CGRect(
                x: scanRect.minX + CGFloat(minX),
                y: scanRect.minY + CGFloat(minY),
                width: CGFloat(maxX - minX + 1),
                height: CGFloat(maxY - minY + 1)
            )
            let peakThresholdX = max(1, Int(Double(width) * 0.08))
            let peakThresholdY = max(1, Int(Double(height) * 0.08))
            let peaks = max(
                projectionPeakCount(horizontal, threshold: peakThresholdX),
                projectionPeakCount(vertical, threshold: peakThresholdY)
            )
            return (Self.clamp(envelope, to: scanRect), Double(darkPixels) / max(1, area(scanRect)), peaks, componentCount)
        }

        func targetReason(block: MangaOverlayProbeBlock, shadow: MangaKoharuNativeTextBoxDetectorLiteShadowOCRBlockLedger?) -> (reason: String, eligible: Bool, bottleneck: String, nextAction: String) {
            if block.blockPassed && block.renderCollisionResolved {
                return ("passedRenderLocked", false, "renderLocked", "keepRenderLockReportOnly")
            }
            if block.failureCategory == "modelOutputFailure" || block.failureCategory == "translationLanguageQualityFailure" {
                return ("modelFloorDominates", false, "modelTranslationFloor", "keepModelFloorSeparate")
            }
            guard let shadow else {
                return ("missingDetectorLiteShadowOCR", false, "needsRealTextBoxes", "generateDetectorLiteShadowOCRFirst")
            }
            switch shadow.shadowOutcome {
            case "emptyOCR", "ocrFailed":
                return (shadow.shadowOutcome, true, "nativeTextBoxRefinementEmpty", "inspectDetectorLiteBBoxGeometry")
            case "worseThanCurrent", "sameAsCurrent":
                return (shadow.shadowOutcome, true, "nativeTextBoxRefinementPromising", "reviewRefinedCandidateInFullProbe")
            case "betterThanCurrent":
                return ("keepDetectorLiteShadowOCRReportOnly", false, "nativeTextBoxRefinementNoNetBenefit", "keepDetectorLiteShadowOCRReportOnly")
            default:
                if block.failureCategory == "ocrInputSuspect" {
                    return ("ocrInputSuspect", true, "ocrInputDamageStillOpen", "collectRealTextBoxesOrSegmentMask")
                }
                return ("notEligible", false, "manualReviewOnly", "manualReviewOnly")
            }
        }

        func sourceCandidate(for block: MangaOverlayProbeBlock, shadow: MangaKoharuNativeTextBoxDetectorLiteShadowOCRBlockLedger?) -> MangaKoharuNativeTextBoxDetectorLiteCandidate? {
            if let selectedID = shadow?.selectedCandidateID,
               let shadowCandidate = shadowOCRReport.candidates.first(where: { $0.candidateID == selectedID }),
               let source = detectorCandidateByID[shadowCandidate.sourceCandidateID] {
                return source
            }
            return detectorCandidatesByBlock[block.index]?.first { $0.shadowOCREligible }
        }

        func refinedRect(from source: MangaKoharuNativeTextBoxDetectorLiteCandidate, for block: MangaOverlayProbeBlock) -> (rect: CGRect, strategy: String, before: (CGRect?, Double, Int, Int), after: (CGRect?, Double, Int, Int), reasons: [String]) {
            let baseRect = Self.clamp(Self.rect(from: source.bbox), to: imageBounds).integral
            let before = analyze(baseRect)
            var reasons: [String] = []
            guard let envelope = before.envelope else {
                reasons.append("noDarkComponentEnvelope")
                return (baseRect, "directionalPaddingByHint", before, analyze(baseRect), reasons)
            }
            var candidate = envelope
            var strategy = "trimToDarkComponentEnvelope"
            if source.directionHint == "horizontal" {
                candidate = CGRect(x: baseRect.minX, y: envelope.minY, width: baseRect.width, height: envelope.height)
                strategy = "projectionBandTighten"
            } else if source.directionHint == "verticalCandidate" {
                candidate = CGRect(x: envelope.minX, y: baseRect.minY, width: envelope.width, height: baseRect.height)
                strategy = "projectionBandTighten"
            }
            let paddingX = source.directionHint == "verticalCandidate" ? max(3, candidate.width * 0.14) : max(3, candidate.width * 0.08)
            let paddingY = source.directionHint == "horizontal" ? max(3, candidate.height * 0.14) : max(3, candidate.height * 0.08)
            candidate = Self.clamp(candidate.insetBy(dx: -paddingX, dy: -paddingY).integral, to: baseRect)
            if let bubbleID = block.bubbleID,
               bubbleID == source.sourceBubbleID,
               let bubbleRect = bubbleRectByID[bubbleID] {
                let clipped = candidate.intersection(Self.clamp(bubbleRect, to: imageBounds))
                if !clipped.isNull, clipped.width >= 4, clipped.height >= 4 {
                    candidate = clipped.integral
                    strategy += "+bubbleSafeClip"
                }
            } else if block.bubbleID != source.sourceBubbleID {
                reasons.append("bubbleClipConflict")
            }
            let after = analyze(candidate)
            return (candidate, strategy, before, after, reasons)
        }

        var candidates: [MangaKoharuNativeTextBoxDetectorLiteRefinementCandidate] = []
        var ledgers: [MangaKoharuNativeTextBoxDetectorLiteRefinementBlockLedger] = []
        var executedCount = 0
        var targetCount = 0

        for block in blocks.sorted(by: { $0.index < $1.index }) {
            let shadow = shadowByBlock[block.index]
            let target = targetReason(block: block, shadow: shadow)
            guard target.eligible else {
                ledgers.append(
                    emptyLedger(
                        for: block,
                        shadow: shadow,
                        targetReason: target.reason,
                        outcome: "notEligible",
                        bottleneck: target.bottleneck,
                        nextAction: target.nextAction,
                        reasons: ["notSelectedForRefinement", "reportOnlyNoPromotionGate"]
                    )
                )
                continue
            }
            targetCount += 1
            guard executedCount < maxExecutions else {
                ledgers.append(
                    emptyLedger(
                        for: block,
                        shadow: shadow,
                        targetReason: target.reason,
                        outcome: "notExecutedBudget",
                        bottleneck: target.bottleneck,
                        nextAction: "reviewRefinedCandidateInFullProbe",
                        reasons: ["ciFastRefinementBudgetExhausted", "reportOnlyNoPromotionGate"]
                    )
                )
                continue
            }
            guard let source = sourceCandidate(for: block, shadow: shadow) else {
                ledgers.append(
                    emptyLedger(
                        for: block,
                        shadow: shadow,
                        targetReason: target.reason,
                        outcome: "notEligible",
                        bottleneck: "needsRealTextBoxes",
                        nextAction: "inspectDetectorLiteBBoxGeometry",
                        reasons: ["noDetectorLiteParentCandidate", "reportOnlyNoPromotionGate"]
                    )
                )
                continue
            }

            let currentText = block.finalTextUsedForTranslation
            let currentQuality = Self.ocrCandidateQualityScore(currentText)
            let detectorText = shadow?.shadowOCRNormalizedText ?? ""
            let detectorQuality = shadow?.shadowOCRQualityScore
            let refined = refinedRect(from: source, for: block)
            let refinedBBox = Self.bboxArray(from: refined.rect)
            let sourceShadowCandidateID = shadowCandidateByBlock[block.index]?.first?.candidateID
            var errorCode: String?
            let crop: (text: String?, cropBBox: [Double], paddingX: Double, paddingY: Double)
            do {
                crop = try await mangaOverlayProbeService.recognizeExternalTextBoxCrop(
                    in: image,
                    textBoxBBox: refinedBBox,
                    options: preprocessing
                )
            } catch {
                errorCode = "\(type(of: error))"
                crop = (nil, refinedBBox, 0, 0)
            }
            executedCount += 1
            let rawText = crop.text
            let normalizedText = (rawText ?? "")
                .replacingOccurrences(of: "\r", with: "\n")
                .trimmingCharacters(in: .whitespacesAndNewlines)
            let refinedQuality = Self.ocrCandidateQualityScore(normalizedText)
            let deltaCurrent = refinedQuality - currentQuality
            let deltaDetector = detectorQuality.map { refinedQuality - $0 }
            let preservationCurrent = Self.wordPreservationRatio(
                sourceWords: Self.ocrCandidateWords(currentText),
                candidateWords: Self.ocrCandidateWords(normalizedText)
            )
            let preservationDetector = detectorText.isEmpty ? nil : Self.wordPreservationRatio(
                sourceWords: Self.ocrCandidateWords(detectorText),
                candidateWords: Self.ocrCandidateWords(normalizedText)
            )
            let refinedMatch = MangaOverlayProbeService.bestGroundTruthMatch(text: normalizedText, groundTruth: groundTruth)
            let refinedSimilarity = normalizedText.isEmpty ? nil : refinedMatch.similarity
            let detectorSimilarity = shadowCandidateByBlock[block.index]?.first?.groundTruthSimilarityShadowForEvaluation
            let similarityDelta = refinedSimilarity.flatMap { refined in block.ocrGroundTruthSimilarity.map { refined - $0 } }
            var reasons = refined.reasons
            if errorCode != nil { reasons.append("refinedOCRFailed") }
            if normalizedText.isEmpty { reasons.append("emptyRefinedOCR") }
            if preservationCurrent < 0.55 { reasons.append("wordPreservationVsCurrentLow") }
            if let deltaDetector, deltaDetector <= 0.03 { reasons.append("qualityDeltaVsDetectorLiteInsufficient") }
            if deltaCurrent <= 0.03 { reasons.append("qualityDeltaVsCurrentInsufficient") }
            reasons.append(contentsOf: ["reportOnlyNoPromotionGate", "mainFlowMutationForbidden", "groundTruthEvaluationOnly"])
            let outcome: String
            if errorCode != nil {
                outcome = "refinedOCRFailed"
            } else if normalizedText.isEmpty {
                outcome = "emptyRefinedOCR"
            } else if deltaCurrent > 0.03 {
                outcome = "refinedBetterThanCurrent"
            } else if let deltaDetector, deltaDetector > 0.03 {
                outcome = "refinedBetterThanDetectorLite"
            } else if let deltaDetector, deltaDetector < -0.03 {
                outcome = "worseThanDetectorLite"
            } else {
                outcome = "sameAsDetectorLite"
            }
            let primary: String
            let nextAction: String
            switch outcome {
            case "refinedBetterThanCurrent", "refinedBetterThanDetectorLite":
                primary = "nativeTextBoxRefinementPromising"
                nextAction = "reviewRefinedCandidateInFullProbe"
            case "emptyRefinedOCR":
                primary = "nativeTextBoxRefinementEmpty"
                nextAction = "inspectDetectorLiteBBoxGeometry"
            case "worseThanDetectorLite":
                primary = "nativeTextBoxRefinementWorse"
                nextAction = "keepCurrentFusedOCR"
            default:
                primary = target.bottleneck
                nextAction = target.nextAction
            }
            let candidateID = "NTBDL-REF-\(block.index)-\(source.candidateID)"
            let bboxRatio = area(Self.rect(from: refinedBBox)) / max(1, area(Self.rect(from: source.bbox)))
            let candidate = MangaKoharuNativeTextBoxDetectorLiteRefinementCandidate(
                candidateID: candidateID,
                sourceCandidateID: source.candidateID,
                sourceShadowOCRCandidateID: sourceShadowCandidateID,
                source: "nativeDetectorLite.refinementShadowOCR",
                blockIndex: block.index,
                sourceBubbleID: source.sourceBubbleID,
                baseBBox: source.bbox,
                refinedBBox: refinedBBox,
                refinementStrategy: refined.strategy,
                directionHint: source.directionHint,
                targetReason: target.reason,
                bboxAreaRatioVsBase: bboxRatio,
                bubbleCoverageBefore: source.bubbleCoverageRatio,
                bubbleCoverageAfter: source.bubbleCoverageRatio,
                glyphOverlapBefore: source.segmentGlyphOverlapRatio,
                glyphOverlapAfter: nil,
                darkPixelDensityBefore: refined.before.1,
                darkPixelDensityAfter: refined.after.1,
                projectionPeakCount: refined.after.2,
                connectedComponentCount: refined.after.3,
                cropPadding: [crop.paddingX, crop.paddingY],
                scaleFactor: preprocessing.cropUpscaleEnabled ? preprocessing.cropScale : 1,
                rotationApplied: 0,
                ocrRawText: rawText,
                ocrNormalizedText: normalizedText,
                ocrSucceeded: errorCode == nil && !normalizedText.isEmpty,
                ocrEmpty: normalizedText.isEmpty,
                ocrErrorCode: errorCode,
                qualityScoreCurrent: currentQuality,
                qualityScoreDetectorLiteShadow: detectorQuality,
                qualityScoreRefined: refinedQuality,
                qualityDeltaVsCurrent: deltaCurrent,
                qualityDeltaVsDetectorLiteShadow: deltaDetector,
                wordPreservationVsCurrent: preservationCurrent,
                wordPreservationVsDetectorLiteShadow: preservationDetector,
                groundTruthSimilarityCurrentForEvaluation: block.ocrGroundTruthSimilarity,
                groundTruthSimilarityDetectorLiteForEvaluation: detectorSimilarity,
                groundTruthSimilarityRefinedForEvaluation: refinedSimilarity,
                groundTruthSimilarityDeltaForEvaluation: similarityDelta,
                outcome: outcome,
                promotionVerdict: "reportOnlyNoPromotion",
                decisionSignals: [
                    signal("sourceCandidateID", source.candidateID, source: "koharuNativeTextBoxDetectorLiteReport"),
                    signal("detectorLiteShadowOutcome", shadow?.shadowOutcome ?? "nil", source: "koharuNativeTextBoxDetectorLiteShadowOCRReport"),
                    signal("targetReason", target.reason, source: "koharuNativeTextBoxDetectorLiteRefinementReport"),
                    signal("candidateLimitPerBlock", String(limitPerBlock), source: "probeRunMode")
                ],
                evaluationSignals: [
                    signal("qualityDeltaVsCurrent", formatted(deltaCurrent), source: "refinementOCRQuality", decision: false, evaluation: true),
                    signal("qualityDeltaVsDetectorLiteShadow", formatted(deltaDetector), source: "refinementOCRQuality", decision: false, evaluation: true),
                    signal("groundTruthSimilarityDeltaForEvaluation", formatted(similarityDelta), source: "test/1.ground_truth.json", decision: false, evaluation: true)
                ],
                rejectionReasons: Array(Set(reasons)).sorted(),
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            )
            candidates.append(candidate)
            ledgers.append(
                MangaKoharuNativeTextBoxDetectorLiteRefinementBlockLedger(
                    blockIndex: block.index,
                    bubbleID: block.bubbleID,
                    blockPassed: block.blockPassed,
                    failureCategory: block.failureCategory,
                    finalTextUsedForTranslation: block.finalTextUsedForTranslation,
                    detectorLiteShadowOutcome: shadow?.shadowOutcome,
                    detectorLiteShadowText: shadow?.shadowOCRNormalizedText,
                    selectedRefinedCandidateID: candidateID,
                    baseCandidateID: source.candidateID,
                    baseBBox: source.bbox,
                    refinedBBox: refinedBBox,
                    refinementStrategy: refined.strategy,
                    refinedOCRText: rawText,
                    refinedOCRNormalizedText: normalizedText,
                    currentOCRQualityScore: currentQuality,
                    detectorLiteShadowOCRQualityScore: detectorQuality,
                    refinedOCRQualityScore: refinedQuality,
                    qualityDeltaVsCurrent: deltaCurrent,
                    qualityDeltaVsDetectorLiteShadow: deltaDetector,
                    ocrSimilarityDeltaForEvaluation: similarityDelta,
                    targetReason: target.reason,
                    refinementOutcome: outcome,
                    wouldHaveImprovedOCRForEvaluation: (similarityDelta ?? 0) > 0.03 || deltaCurrent > 0.03 || (deltaDetector ?? 0) > 0.03,
                    primaryBottleneck: primary,
                    nextAction: nextAction,
                    whyNotPromoted: candidate.rejectionReasons,
                    decisionSignals: [
                        signal("sourceCandidateID", source.candidateID, source: "koharuNativeTextBoxDetectorLiteReport"),
                        signal("refinementOutcome", outcome, source: "koharuNativeTextBoxDetectorLiteRefinementReport")
                    ],
                    evaluationSignals: [
                        signal("ocrSimilarityDeltaForEvaluation", formatted(similarityDelta), source: "test/1.ground_truth.json", decision: false, evaluation: true)
                    ],
                    groundTruthUsedForDecision: false,
                    wouldChangeMainFlow: false,
                    diagnosticOnly: true
                )
            )
        }

        let betterDetector = candidates.filter { ($0.qualityDeltaVsDetectorLiteShadow ?? 0) > 0.03 }.count
        let betterCurrent = candidates.filter { $0.qualityDeltaVsCurrent > 0.03 }.count
        let worseDetector = candidates.filter { ($0.qualityDeltaVsDetectorLiteShadow ?? 0) < -0.03 }.count
        let sameDetector = candidates.filter { candidate in
            guard let delta = candidate.qualityDeltaVsDetectorLiteShadow else { return false }
            return abs(delta) <= 0.03 && !candidate.ocrEmpty && candidate.ocrErrorCode == nil
        }.count
        let empty = candidates.filter(\.ocrEmpty).count
        let succeeded = candidates.filter(\.ocrSucceeded).count
        let gates = [
            gate("G-native-textbox-detector-lite-refinement-report-only", "Report only", "report", "passed", "wouldChangeMainFlow=false", [], "refinement mutates main OCR, translation, overlay, blockPassed, failureCategory, currentBlockSource, or crop adoption", "revertBehavioralChange", [signal("wouldChangeMainFlow", "false", source: "koharuNativeTextBoxDetectorLiteRefinementReport")]),
            gate("G-native-textbox-detector-lite-refinement-no-ground-truth-decision", "No ground truth decision", "report", "passed", "groundTruthUsedForDecision=false", allBlockIndexes, "ground truth drives target selection, bbox generation, OCR execution, nextAction, or gate status", "moveGroundTruthToEvaluationSignalsOnly", [signal("groundTruthUsedForDecision", "false", source: "koharuNativeTextBoxDetectorLiteRefinementReport")]),
            gate("G-native-textbox-detector-lite-refinement-parent-source", "Detector-lite parent source", "TextBoxes", "passed", "source=nativeDetectorLite.refinementShadowOCR", allBlockIndexes, "refinement falls back to Vision bbox, crop plan, line plan, external artifact, or ground truth box", "keepDetectorLiteParentBBoxOnly", [signal("candidateSource", "nativeDetectorLite.refinementShadowOCR", source: "koharuNativeTextBoxDetectorLiteRefinementReport")]),
            gate("G-native-textbox-detector-lite-refinement-ci-fast-budget", "CI fast budget", "ci-fast", candidates.count <= ciFastLimit ? "passed" : "warning", "ocrExecutedCount<=min(6,totalBlocksDetected) in ci-fast", allBlockIndexes, "ci-fast refinement OCR exceeds budget", "reduceRefinementCandidateLimit", [signal("ocrExecutedCount", String(candidates.count), source: "koharuNativeTextBoxDetectorLiteRefinementReport"), signal("ciFastLimit", String(ciFastLimit), source: "probeRunMode")]),
            gate("G-native-textbox-detector-lite-refinement-block-ledger-count", "Block ledger count", "blocks", ledgers.count == blocks.count ? "passed" : "warning", "blockLedgerCount==totalBlocksDetected", allBlockIndexes, "some final blocks lack refinement ledger rows", "restoreBlockLedgerCoverage", [signal("blockLedgerCount", String(ledgers.count), source: "koharuNativeTextBoxDetectorLiteRefinementReport")]),
            gate("G-native-textbox-detector-lite-refinement-proxy-boundary", "Proxy boundary", "TextBoxes/OCR", "passed", "proxyNotRealKoharuTextBoxes=true and proxyNotRealKoharuOCR=true", allBlockIndexes, "refinement is promoted as real Koharu TextBoxes or OCR", "keepProxyBoundaryOrCollectRealArtifact", [signal("proxyNotRealKoharuTextBoxes", "true", source: "koharuNativeTextBoxDetectorLiteRefinementReport"), signal("proxyNotRealKoharuOCR", "true", source: "koharuNativeTextBoxDetectorLiteRefinementReport")]),
            gate("G-native-textbox-detector-lite-refinement-no-llm", "No LLM", "Translations", "passed", "no LLM calls added", [], "refinement triggers translation model calls or prompt changes", "removeLLMFromRefinementOCR", [signal("llmCalls", "0", source: "koharuNativeTextBoxDetectorLiteRefinementReport")]),
            gate("G-native-textbox-detector-lite-refinement-visible-failures", "Visible failures", "report", candidates.isEmpty || !countBy(candidates.map(\.outcome)).isEmpty ? "passed" : "warning", "empty/failed/worse outcomes recorded", allBlockIndexes, "refinement OCR failures are silently skipped", "writeFailureLedgers", [signal("ocrOutcomeBreakdown", countBy(candidates.map(\.outcome)).map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ","), source: "koharuNativeTextBoxDetectorLiteRefinementReport")])
        ]
        let verdict: String
        if targetCount == 0 {
            verdict = "blockedByNoEligibleTargets"
        } else if betterCurrent > 0 || betterDetector > 0 {
            verdict = "refinementImprovesSomeBlocksReportOnly"
        } else if empty + worseDetector >= max(1, candidates.count) {
            verdict = "refinementEmptyOrWorse"
        } else if ledgers.filter({ $0.primaryBottleneck == "modelTranslationFloor" }).count >= max(1, blocks.count / 2) {
            verdict = "modelFloorDominates"
        } else {
            verdict = "refinementNoNetBenefit"
        }
        return MangaKoharuNativeTextBoxDetectorLiteRefinementReport(
            enabled: true,
            source: "AITRANSProbe",
            referencePipeline: "Koharu",
            referenceConcept: "TextBoxes.NativeDetectorLite.ClosedLoopRefinement",
            referenceWorkItemID: "WI-koharu-native-textbox-detector-lite-refinement",
            evaluatedBlockCount: blocks.count,
            inputDetectorLiteCandidateCount: detectorLiteReport.candidateCount,
            inputShadowOCRCandidateCount: shadowOCRReport.selectedCandidateCount,
            targetBlockCount: targetCount,
            refinedCandidateCount: candidates.count,
            ocrExecutedCount: candidates.count,
            ocrSucceededCount: succeeded,
            emptyOCRCount: empty,
            refinedBetterThanDetectorLiteCount: betterDetector,
            refinedBetterThanCurrentCount: betterCurrent,
            refinedWorseThanDetectorLiteCount: worseDetector,
            sameAsDetectorLiteCount: sameDetector,
            blockLedgerCount: ledgers.count,
            gateCount: gates.count,
            candidateSelectionLimitCIFast: ciFastLimit,
            candidateSelectionLimitFull: fullLimit,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            proxyNotRealKoharuTextBoxes: true,
            proxyNotRealKoharuOCR: true,
            externalArtifactsRequiredForThisReport: false,
            refinementVerdict: verdict,
            targetReasonBreakdown: countBy(ledgers.map(\.targetReason)),
            refinementStrategyBreakdown: countBy(candidates.map(\.refinementStrategy)),
            ocrOutcomeBreakdown: countBy(candidates.map(\.outcome) + ledgers.filter { $0.selectedRefinedCandidateID == nil }.map(\.refinementOutcome)),
            qualityDeltaBreakdown: countBy(candidates.map {
                if $0.ocrEmpty || $0.ocrErrorCode != nil { return $0.outcome }
                if $0.qualityDeltaVsCurrent > 0.03 { return "positiveVsCurrent" }
                if let delta = $0.qualityDeltaVsDetectorLiteShadow, delta > 0.03 { return "positiveVsDetectorLite" }
                if let delta = $0.qualityDeltaVsDetectorLiteShadow, delta < -0.03 { return "negativeVsDetectorLite" }
                return "neutral"
            }),
            primaryBottleneckBreakdown: countBy(ledgers.map(\.primaryBottleneck)),
            nextActionBreakdown: countBy(ledgers.map(\.nextAction)),
            candidates: candidates.sorted { $0.candidateID < $1.candidateID },
            blockLedgers: ledgers.sorted { $0.blockIndex < $1.blockIndex },
            gateLedger: gates,
            notes: [
                "koharuNativeTextBoxDetectorLiteRefinementReport is a shadow-only detector-lite closed-loop refinement path.",
                "Target selection uses v1.40 shadow OCR outcome, block failure category, model-floor routing, render lock, and detector-lite relation signals only; ground truth is evaluation-only.",
                "Refined bboxes start from v1.39 nativeDetectorLite parent bboxes and are tightened with source image dark component envelope, projection bands, directional padding, and conservative bubble clipping when bubble IDs agree.",
                "Refined OCR output is not written to finalTextUsedForTranslation and does not change translation, overlay, blockPassed, failureCategory, currentBlockSource, textRegionCropReport.adoptedCount, active artifacts, prompt, or model.",
                "proxyNotRealKoharuTextBoxes=true and proxyNotRealKoharuOCR=true: v1.41 is not a real Koharu TextBoxes/OcrText artifact."
            ]
        )
    }

    private static func makeKoharuNativeTextBoxDetectorLiteClosedLoopReport(
        blocks: [MangaOverlayProbeBlock],
        diagnostics: MangaOverlayProbeDiagnostics,
        detectorLiteReport: MangaKoharuNativeTextBoxDetectorLiteReport?,
        shadowOCRReport: MangaKoharuNativeTextBoxDetectorLiteShadowOCRReport?,
        refinementReport: MangaKoharuNativeTextBoxDetectorLiteRefinementReport?,
        bubbleMaskAssignmentSplitScoreboardReport: MangaBubbleMaskAssignmentSplitScoreboardReport?,
        segmentMaskProxyCoverageScoreboardReport: MangaSegmentMaskProxyCoverageScoreboardReport?,
        translationModelFloorComparisonReport: MangaTranslationModelFloorComparisonReport?,
        koharuRenderRegressionLockReport: MangaKoharuRenderRegressionLockReport?,
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?
    ) -> MangaKoharuNativeTextBoxDetectorLiteClosedLoopReport {
        func uniqueSorted(_ values: [Int]) -> [Int] { Array(Set(values)).sorted() }
        func sortedUniqueStrings(_ values: [String]) -> [String] { Array(Set(values)).sorted() }
        func countBy(_ values: [String]) -> [String: Int] {
            values.reduce(into: [:]) { partial, value in partial[value, default: 0] += 1 }
        }
        func formatted(_ value: Double?) -> String {
            value?.formatted(.number.precision(.fractionLength(4))) ?? "nil"
        }
        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaKoharuNativeTextBoxDetectorLiteClosedLoopSignal {
            MangaKoharuNativeTextBoxDetectorLiteClosedLoopSignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }
        func gate(
            _ id: String,
            _ name: String,
            _ scope: String,
            _ status: String,
            _ threshold: String,
            _ affected: [Int],
            _ failure: String,
            _ action: String,
            _ signals: [MangaKoharuNativeTextBoxDetectorLiteClosedLoopSignal]
        ) -> MangaKoharuNativeTextBoxDetectorLiteClosedLoopGate {
            MangaKoharuNativeTextBoxDetectorLiteClosedLoopGate(
                gateID: id,
                gateName: name,
                scope: scope,
                status: status,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                decisionSignals: signals,
                failureMeans: failure,
                recommendedAction: action,
                groundTruthUsedForDecision: false
            )
        }

        let allBlocks = blocks.map(\.index)
        let detectorByBlock = Dictionary(
            uniqueKeysWithValues: (detectorLiteReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let shadowByBlock = Dictionary(
            uniqueKeysWithValues: (shadowOCRReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let refinementByBlock = Dictionary(
            uniqueKeysWithValues: (refinementReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let bubbleByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleMaskAssignmentSplitScoreboardReport?.blockScorecards ?? []).map { ($0.blockIndex, $0) }
        )
        let segmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentMaskProxyCoverageScoreboardReport?.blockScorecards ?? []).map { ($0.blockIndex, $0) }
        )
        let modelFloorByBlock = Dictionary(
            uniqueKeysWithValues: (translationModelFloorComparisonReport?.noisyBlockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let renderByBlock = Dictionary(
            uniqueKeysWithValues: (koharuRenderRegressionLockReport?.blockLocks ?? []).map { ($0.blockIndex, $0) }
        )
        let shadowCandidatesByBlock = Dictionary(grouping: shadowOCRReport?.candidates ?? []) { $0.relatedBlockIndex }
        let refinementCandidatesByBlock = Dictionary(grouping: refinementReport?.candidates ?? []) { $0.blockIndex }

        func translationRoute(for block: MangaOverlayProbeBlock, floor: MangaTranslationModelFloorNoisyBlockSummary?) -> String {
            if block.blockPassed { return "notTranslationFailure" }
            if block.failureCategory == "ocrInputSuspect" || floor?.ocrInputSuspect == true {
                return "ocrInputSuspectRouteToTextBoxes"
            }
            if block.failureCategory == "modelOutputFailure" {
                return "modelOutputFailureRouteToModelFloor"
            }
            if block.failureCategory == "translationLanguageQualityFailure" || floor?.translationLanguageQualityFailure == true {
                return "translationLanguageQualityRouteToModelFloor"
            }
            if diagnostics.likelyRuleFalseFailureBlocks.contains(block.index) {
                return "ruleFalseFailureSuspectedRouteToQualityGateReview"
            }
            return "unknownFailureManualReview"
        }

        func renderStatus(for block: MangaOverlayProbeBlock, lock: MangaKoharuRenderBlockLock?) -> String {
            if block.renderTextTruncated || lock?.renderTextTruncated == true {
                return "renderTextTruncated"
            }
            if block.renderMaskOverflowPixelCount > 0 || (lock?.renderMaskOverflowPixelCount ?? 0) > 0 {
                return "renderMaskOverflow"
            }
            if lock?.failureOverlayLocked == true {
                return "failureOverlayLocked"
            }
            if block.renderCollisionChecked && block.renderCollisionResolved {
                return "renderStableLocked"
            }
            if block.safeLayoutRect != nil {
                return "safeLayoutAvailable"
            }
            return "notChecked"
        }

        func structuralRoute(
            block: MangaOverlayProbeBlock,
            bubble: MangaBubbleMaskAssignmentSplitBlockScorecard?,
            segment: MangaSegmentMaskProxyBlockScorecard?
        ) -> (bubbleStatus: String, splitRisk: String, siblingRisk: String, segmentStatus: String, externalNeed: String?) {
            let bubbleStatus = bubble?.assignmentStatus ?? "missingBubbleScoreboard"
            let splitRisk = bubble?.splitRisk ?? "unknownSplitRisk"
            let siblingRisk = bubble?.siblingLayoutStatus ?? "unknownSiblingRisk"
            let segmentStatus = segment?.coverageStatus ?? "missingSegmentScoreboard"
            if bubbleMaskAssignmentSplitScoreboardReport?.needsRealBubbleMaskBlocks.contains(block.index) == true
                || bubbleStatus == "maskConflict"
                || splitRisk.contains("risk")
                || siblingRisk.contains("risk") {
                return (bubbleStatus, splitRisk, siblingRisk, segmentStatus, "BubbleMask")
            }
            if segmentMaskProxyCoverageScoreboardReport?.needsRealSegmentMaskBlocks.contains(block.index) == true
                || segmentStatus.contains("needsReal")
                || segmentStatus.contains("weak")
                || segment?.glyphEscapesBubble == true {
                return (bubbleStatus, splitRisk, siblingRisk, segmentStatus, "SegmentMask")
            }
            if detectorLiteReport?.needsRealTextBoxesBlocks.contains(block.index) == true {
                return (bubbleStatus, splitRisk, siblingRisk, segmentStatus, "TextBoxes")
            }
            return (bubbleStatus, splitRisk, siblingRisk, segmentStatus, nil)
        }

        func bestCandidate(
            currentQuality: Double,
            shadow: MangaKoharuNativeTextBoxDetectorLiteShadowOCRBlockLedger?,
            refinement: MangaKoharuNativeTextBoxDetectorLiteRefinementBlockLedger?
        ) -> (id: String?, source: String?, text: String?, quality: Double?, delta: Double?, preservation: Double?, similarityDelta: Double?) {
            let shadowDelta = shadow?.qualityDeltaVsCurrent ?? -.infinity
            let refinedDelta = refinement?.qualityDeltaVsCurrent ?? -.infinity
            if let refinement, let candidateID = refinement.selectedRefinedCandidateID, refinedDelta >= shadowDelta {
                return (
                    candidateID,
                    "nativeDetectorLite.refinementShadowOCR",
                    refinement.refinedOCRNormalizedText,
                    refinement.refinedOCRQualityScore,
                    refinement.qualityDeltaVsCurrent,
                    nil,
                    refinement.ocrSimilarityDeltaForEvaluation
                )
            }
            if let shadow, let candidateID = shadow.selectedCandidateID {
                return (
                    candidateID,
                    "nativeDetectorLite.shadowOCR",
                    shadow.shadowOCRNormalizedText,
                    shadow.shadowOCRQualityScore,
                    shadow.qualityDeltaVsCurrent,
                    nil,
                    shadow.ocrSimilarityDeltaForEvaluation
                )
            }
            return (nil, nil, nil, nil, nil, nil, nil)
        }

        var familyLedgers: [MangaKoharuNativeTextBoxDetectorLiteCandidateFamilyLedger] = []
        var blockLedgers: [MangaKoharuNativeTextBoxDetectorLiteClosedLoopBlockLedger] = []

        for block in blocks.sorted(by: { $0.index < $1.index }) {
            let detector = detectorByBlock[block.index]
            let shadow = shadowByBlock[block.index]
            let refinement = refinementByBlock[block.index]
            let bubble = bubbleByBlock[block.index]
            let segment = segmentByBlock[block.index]
            let floor = modelFloorByBlock[block.index]
            let render = renderByBlock[block.index]
            let currentQuality = Self.ocrCandidateQualityScore(block.finalTextUsedForTranslation)
            let best = bestCandidate(currentQuality: currentQuality, shadow: shadow, refinement: refinement)
            let structural = structuralRoute(block: block, bubble: bubble, segment: segment)
            let translation = translationRoute(for: block, floor: floor)
            let renderRoute = renderStatus(for: block, lock: render)

            var stopReasons: [String] = []
            var fullReviewReasons: [String] = []
            var whyNotPromoted = [
                "reportOnlyNoPromotion",
                "mainFlowMutationForbidden",
                "groundTruthEvaluationOnly",
                "proxyNotRealKoharuTextBoxes",
                "proxyNotRealKoharuOCR"
            ]
            let positiveShadow = (shadow?.qualityDeltaVsCurrent ?? 0) > 0.03
            let positiveRefinement = (refinement?.qualityDeltaVsCurrent ?? 0) > 0.03
            let shadowOutcome = shadow?.shadowOutcome ?? "missingShadowOCRLedger"
            let refinementOutcome = refinement?.refinementOutcome ?? "missingRefinementLedger"
            let noNetBenefit = ["emptyOCR", "worseThanCurrent", "sameAsCurrent", "notSelected", "ocrFailed"].contains(shadowOutcome)
                && ["emptyOCR", "worseThanCurrent", "sameAsCurrent", "notEligible", "ocrFailed"].contains(refinementOutcome)

            let primaryBottleneck: String
            let route: String
            let nextAction: String
            if translation == "modelOutputFailureRouteToModelFloor"
                || translation == "translationLanguageQualityRouteToModelFloor"
                || floor?.modelFloorLimited == true {
                primaryBottleneck = "modelTranslationFloor"
                route = "routeToModelFloor"
                nextAction = "keepModelFloorSeparate"
                stopReasons.append("modelFloorDominates")
            } else if renderRoute == "renderTextTruncated" || renderRoute == "renderMaskOverflow" {
                primaryBottleneck = "renderLocked"
                route = "routeToRenderLock"
                nextAction = "routeToRenderRegressionLock"
                stopReasons.append("renderLockDominates")
            } else if structural.externalNeed == "BubbleMask" {
                primaryBottleneck = "bubbleSplitRisk"
                route = "routeToRealBubbleMaskArtifact"
                nextAction = "collectRealBubbleMaskArtifact"
                stopReasons.append("proxyBubbleMaskInsufficient")
            } else if structural.externalNeed == "SegmentMask" {
                primaryBottleneck = "needsRealSegmentMask"
                route = "routeToRealSegmentMaskArtifact"
                nextAction = "collectRealSegmentMaskArtifact"
                stopReasons.append("proxySegmentMaskInsufficient")
            } else if positiveRefinement || positiveShadow {
                primaryBottleneck = positiveRefinement ? "detectorLiteRefinementPromisingReportOnly" : "detectorLiteShadowPromisingReportOnly"
                route = "reviewPromisingCandidateInFullProbe"
                nextAction = "openFullProbeReview"
                fullReviewReasons.append(positiveRefinement ? "refinementPositiveQualityDelta" : "shadowOCRPositiveQualityDelta")
                whyNotPromoted.append("requiresFullProbeReview")
            } else if structural.externalNeed == "TextBoxes" || translation == "ocrInputSuspectRouteToTextBoxes" {
                primaryBottleneck = "needsRealTextBoxes"
                route = "routeToRealTextBoxesArtifact"
                nextAction = "collectRealTextBoxesArtifact"
                stopReasons.append("currentOCRInputDamageStillOpen")
            } else if noNetBenefit {
                primaryBottleneck = refinementOutcome == "worseThanCurrent" ? "detectorLiteRefinementNoNetBenefit" : "detectorLiteNoNetBenefit"
                route = "stopDetectorLiteLocalTuning"
                nextAction = "stopLocalDetectorLiteTuning"
                stopReasons.append("shadowAndRefinementNoNetBenefit")
            } else {
                primaryBottleneck = "manualReviewOnly"
                route = block.blockPassed ? "keepCurrentFusedOCR" : "manualReviewOnly"
                nextAction = block.blockPassed ? "keepCurrentFusedOCR" : "manualReviewOnly"
                if !block.blockPassed { fullReviewReasons.append("unclassifiedClosedLoopRoute") }
            }

            if !fullReviewReasons.isEmpty {
                whyNotPromoted.append("fullProbeReviewRequiredBeforePromotion")
            }
            if externalArtifactReadinessReport?.externalTextBoxesShadowOCRAllowed != true {
                whyNotPromoted.append("activeKoharuArtifactsNotReady")
            }

            let detectorIDs = detector?.candidateIDs ?? []
            let shadowIDs = (shadowCandidatesByBlock[block.index] ?? []).map(\.candidateID).sorted()
            let refinementIDs = (refinementCandidatesByBlock[block.index] ?? []).map(\.candidateID).sorted()
            let familyVerdict: String
            if route == "reviewPromisingCandidateInFullProbe" {
                familyVerdict = positiveRefinement ? "refinementCandidatePromisingReportOnly" : "shadowCandidatePromisingReportOnly"
            } else if route == "stopDetectorLiteLocalTuning" {
                familyVerdict = refinementOutcome == "worseThanCurrent" ? "refinementNoNetBenefit" : "shadowCandidateNoNetBenefit"
            } else if route == "routeToRealBubbleMaskArtifact" {
                familyVerdict = "requiresRealBubbleMask"
            } else if route == "routeToRealSegmentMaskArtifact" {
                familyVerdict = "requiresRealSegmentMask"
            } else if route == "routeToRealTextBoxesArtifact" {
                familyVerdict = "requiresRealKoharuTextBoxes"
            } else if route == "routeToModelFloor" {
                familyVerdict = "blockedByModelFloor"
            } else if route == "routeToRenderLock" {
                familyVerdict = "blockedByRenderLock"
            } else {
                familyVerdict = route == "keepCurrentFusedOCR" ? "keepCurrentFusedOCR" : "manualReviewOnly"
            }

            let decisionSignals = [
                signal("detectorLiteVerdict", detector?.candidateCoverageVerdict ?? "missing", source: "koharuNativeTextBoxDetectorLiteReport"),
                signal("shadowOutcome", shadowOutcome, source: "koharuNativeTextBoxDetectorLiteShadowOCRReport"),
                signal("refinementOutcome", refinementOutcome, source: "koharuNativeTextBoxDetectorLiteRefinementReport"),
                signal("bubbleAssignmentStatus", structural.bubbleStatus, source: "bubbleMaskAssignmentSplitScoreboardReport"),
                signal("segmentGlyphEvidenceStatus", structural.segmentStatus, source: "segmentMaskProxyCoverageScoreboardReport"),
                signal("translationFailureRoute", translation, source: "blocks.failureCategory"),
                signal("renderLockStatus", renderRoute, source: "koharuRenderRegressionLockReport")
            ]
            let evaluationSignals = [
                signal("groundTruthSimilarityCurrentForEvaluation", formatted(block.ocrGroundTruthSimilarity), source: "blocks.ocrGroundTruthSimilarity", decision: false, evaluation: true),
                signal("groundTruthSimilarityBestForEvaluation", formatted(best.similarityDelta.flatMap { delta in block.ocrGroundTruthSimilarity.map { $0 + delta } }), source: "test/1.ground_truth.json", decision: false, evaluation: true),
                signal("groundTruthSimilarityDeltaForEvaluation", formatted(best.similarityDelta), source: "test/1.ground_truth.json", decision: false, evaluation: true),
                signal("currentOCRQualityScore", formatted(currentQuality), source: "blocks.finalTextUsedForTranslation", decision: false, evaluation: true),
                signal("bestShadowQualityScore", formatted(best.quality), source: "detector-lite shadow reports", decision: false, evaluation: true)
            ]

            familyLedgers.append(
                MangaKoharuNativeTextBoxDetectorLiteCandidateFamilyLedger(
                    familyID: "NTBDL-CL-\(block.index)",
                    blockIndex: block.index,
                    bubbleID: block.bubbleID,
                    currentFinalText: block.finalTextUsedForTranslation,
                    detectorLiteCandidateIDs: detectorIDs,
                    shadowOCRCandidateIDs: shadowIDs,
                    refinementCandidateIDs: refinementIDs,
                    bestReportOnlyCandidateID: best.id,
                    bestReportOnlyCandidateSource: best.source,
                    bestReportOnlyText: best.text,
                    currentQualityScore: currentQuality,
                    bestShadowQualityScore: best.quality,
                    qualityDeltaVsCurrent: best.delta,
                    wordPreservationBest: best.preservation,
                    groundTruthSimilarityCurrentForEvaluation: block.ocrGroundTruthSimilarity,
                    groundTruthSimilarityBestForEvaluation: best.similarityDelta.flatMap { delta in block.ocrGroundTruthSimilarity.map { $0 + delta } },
                    groundTruthSimilarityDeltaForEvaluation: best.similarityDelta,
                    candidateFamilyVerdict: familyVerdict,
                    whyNotPromoted: sortedUniqueStrings(whyNotPromoted),
                    decisionSignals: decisionSignals,
                    evaluationSignals: evaluationSignals,
                    groundTruthUsedForDecision: false,
                    wouldChangeMainFlow: false,
                    diagnosticOnly: true
                )
            )
            blockLedgers.append(
                MangaKoharuNativeTextBoxDetectorLiteClosedLoopBlockLedger(
                    blockIndex: block.index,
                    bubbleID: block.bubbleID,
                    blockPassed: block.blockPassed,
                    failureCategory: block.failureCategory,
                    finalTextUsedForTranslation: block.finalTextUsedForTranslation,
                    currentOCRQualityScore: currentQuality,
                    detectorLiteVerdict: detector?.candidateCoverageVerdict ?? "missingDetectorLiteLedger",
                    detectorLiteShadowOutcome: shadowOutcome,
                    refinementOutcome: refinementOutcome,
                    bestReportOnlyCandidateID: best.id,
                    bestReportOnlyCandidateSource: best.source,
                    bestReportOnlyOCRText: best.text,
                    qualityDeltaVsCurrent: best.delta,
                    ocrSimilarityDeltaForEvaluation: best.similarityDelta,
                    bubbleAssignmentStatus: structural.bubbleStatus,
                    bubbleSplitRisk: structural.splitRisk,
                    sameBubbleSiblingRisk: structural.siblingRisk,
                    segmentGlyphEvidenceStatus: structural.segmentStatus,
                    translationFailureRoute: translation,
                    renderLockStatus: renderRoute,
                    externalArtifactNeed: structural.externalNeed ?? "none",
                    primaryBottleneck: primaryBottleneck,
                    closedLoopRoute: route,
                    nextAction: nextAction,
                    stopReasons: sortedUniqueStrings(stopReasons),
                    fullProbeReviewReasons: sortedUniqueStrings(fullReviewReasons),
                    whyNotPromoted: sortedUniqueStrings(whyNotPromoted),
                    decisionSignals: decisionSignals,
                    evaluationSignals: evaluationSignals,
                    groundTruthUsedForDecision: false,
                    wouldChangeMainFlow: false,
                    diagnosticOnly: true
                )
            )
        }

        let missingUpstream = [
            detectorLiteReport?.enabled == true ? nil : "koharuNativeTextBoxDetectorLiteReport",
            shadowOCRReport?.enabled == true ? nil : "koharuNativeTextBoxDetectorLiteShadowOCRReport",
            refinementReport?.enabled == true ? nil : "koharuNativeTextBoxDetectorLiteRefinementReport"
        ].compactMap { $0 }
        let stopBlocks = uniqueSorted(blockLedgers.filter { !$0.stopReasons.isEmpty || $0.closedLoopRoute == "stopDetectorLiteLocalTuning" }.map(\.blockIndex))
        let fullReviewBlocks = uniqueSorted(blockLedgers.filter { !$0.fullProbeReviewReasons.isEmpty || $0.closedLoopRoute == "reviewPromisingCandidateInFullProbe" }.map(\.blockIndex))
        let realTextBoxesBlocks = uniqueSorted(blockLedgers.filter { $0.closedLoopRoute == "routeToRealTextBoxesArtifact" }.map(\.blockIndex))
        let realBubbleBlocks = uniqueSorted(blockLedgers.filter { $0.closedLoopRoute == "routeToRealBubbleMaskArtifact" }.map(\.blockIndex))
        let realSegmentBlocks = uniqueSorted(blockLedgers.filter { $0.closedLoopRoute == "routeToRealSegmentMaskArtifact" }.map(\.blockIndex))
        let modelFloorBlocks = uniqueSorted(blockLedgers.filter { $0.closedLoopRoute == "routeToModelFloor" }.map(\.blockIndex))
        let renderLockBlocks = uniqueSorted(blockLedgers.filter { $0.closedLoopRoute == "routeToRenderLock" }.map(\.blockIndex))
        let gates = [
            gate("G-native-textbox-detector-lite-closed-loop-input-reports", "Input reports", "TextBoxes/OcrText", missingUpstream.isEmpty ? "passed" : "blocked", "v1.39-v1.41 reports enabled", allBlocks, "closed-loop router cannot compare detector-lite, shadow OCR, and refinement ledgers", "restoreDetectorLiteClosedLoopInputs", [signal("missingUpstreamReports", missingUpstream.joined(separator: ","), source: "koharuNativeTextBoxDetectorLiteClosedLoopReport")]),
            gate("G-native-textbox-detector-lite-closed-loop-report-only", "Report only", "report", "passed", "wouldChangeMainFlow=false", [], "closed-loop route mutates main OCR, translation, overlay, blockPassed, failureCategory, or currentBlockSource", "revertBehavioralChange", [signal("wouldChangeMainFlow", "false", source: "koharuNativeTextBoxDetectorLiteClosedLoopReport")]),
            gate("G-native-textbox-detector-lite-closed-loop-no-ground-truth-decision", "No ground truth decision", "report", "passed", "groundTruthUsedForDecision=false", allBlocks, "ground truth influences route, nextAction, gate, or candidate family verdict", "moveGroundTruthToEvaluationSignalsOnly", [signal("groundTruthUsedForDecision", "false", source: "koharuNativeTextBoxDetectorLiteClosedLoopReport")]),
            gate("G-native-textbox-detector-lite-closed-loop-block-ledger-count", "Block ledger count", "blocks", blockLedgers.count == blocks.count ? "passed" : "warning", "blockLedgerCount==totalBlocksDetected", allBlocks, "some final blocks lack closed-loop route rows", "restoreClosedLoopBlockCoverage", [signal("blockLedgerCount", String(blockLedgers.count), source: "koharuNativeTextBoxDetectorLiteClosedLoopReport")]),
            gate("G-native-textbox-detector-lite-closed-loop-family-ledger-count", "Candidate family ledger count", "TextBoxes/OcrText", familyLedgers.count == blocks.count ? "passed" : "warning", "candidateFamilyCount==totalBlocksDetected", allBlocks, "some final blocks lack candidate family rollup", "restoreCandidateFamilyRollup", [signal("candidateFamilyCount", String(familyLedgers.count), source: "koharuNativeTextBoxDetectorLiteClosedLoopReport")]),
            gate("G-native-textbox-detector-lite-closed-loop-proxy-boundary", "Proxy boundary", "TextBoxes/OcrText", "passed", "proxyNotRealKoharuTextBoxes=true and proxyNotRealKoharuOCR=true", allBlocks, "detector-lite route is promoted as real Koharu TextBoxes/OcrText", "keepProxyBoundaryOrCollectRealArtifact", [signal("proxyNotRealKoharuTextBoxes", "true", source: "koharuNativeTextBoxDetectorLiteClosedLoopReport"), signal("proxyNotRealKoharuOCR", "true", source: "koharuNativeTextBoxDetectorLiteClosedLoopReport")]),
            gate("G-native-textbox-detector-lite-closed-loop-stoplist-preserved", "Stoplist preserved", "TextRegionCrop/LineDeskew", "passed", "v17-v20 crop/line/deskew stoplist remains closed", stopBlocks, "closed-loop router reopens local crop, line, or deskew tuning", "keepStoplistAndRouteToArtifacts", [signal("stopBlockIndexes", stopBlocks.map(String.init).joined(separator: ","), source: "koharuNativeTextBoxDetectorLiteClosedLoopReport")]),
            gate("G-native-textbox-detector-lite-closed-loop-full-review-report-only", "Full review report-only", "full-probe", "passed", "promising candidates require full probe review and no promotion", fullReviewBlocks, "promising shadow OCR is written into finalTextUsedForTranslation", "keepFullReviewReportOnly", [signal("fullProbeReviewBlockIndexes", fullReviewBlocks.map(String.init).joined(separator: ","), source: "koharuNativeTextBoxDetectorLiteClosedLoopReport")])
        ]
        let verdict: String
        if !missingUpstream.isEmpty {
            verdict = "blockedByMissingUpstreamReports"
        } else if !fullReviewBlocks.isEmpty {
            verdict = "detectorLiteSomePromisingNeedsFullProbe"
        } else if !realBubbleBlocks.isEmpty || !realSegmentBlocks.isEmpty {
            verdict = "needsRealBubbleMaskOrSegmentMask"
        } else if !realTextBoxesBlocks.isEmpty {
            verdict = "needsRealKoharuTextBoxes"
        } else if !modelFloorBlocks.isEmpty {
            verdict = "detectorLiteBlockedByModelFloor"
        } else if !renderLockBlocks.isEmpty {
            verdict = "detectorLiteBlockedByRenderLock"
        } else if stopBlocks.count >= max(1, blocks.count / 2) {
            verdict = "detectorLiteNoNetBenefitStopLocalTuning"
        } else {
            verdict = "detectorLiteClosedLoopReportOnly"
        }

        return MangaKoharuNativeTextBoxDetectorLiteClosedLoopReport(
            enabled: true,
            source: "AITRANSProbe",
            referencePipeline: "Koharu",
            referenceConcept: "TextBoxes.NativeDetectorLite.ClosedLoopRouter",
            referenceWorkItemID: "WI-koharu-native-textbox-detector-lite-closed-loop-router",
            evaluatedBlockCount: blocks.count,
            detectorLiteCandidateCount: detectorLiteReport?.candidateCount ?? 0,
            detectorLiteShadowOCRCandidateCount: shadowOCRReport?.selectedCandidateCount ?? 0,
            refinementCandidateCount: refinementReport?.refinedCandidateCount ?? 0,
            candidateFamilyCount: familyLedgers.count,
            blockLedgerCount: blockLedgers.count,
            gateCount: gates.count,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            proxyNotRealKoharuTextBoxes: true,
            proxyNotRealKoharuOCR: true,
            externalArtifactsRequiredForThisReport: false,
            closedLoopVerdict: verdict,
            routeBreakdown: countBy(blockLedgers.map(\.closedLoopRoute)),
            candidateFamilyVerdictBreakdown: countBy(familyLedgers.map(\.candidateFamilyVerdict)),
            ocrOutcomeRollup: countBy(blockLedgers.flatMap { [$0.detectorLiteShadowOutcome, $0.refinementOutcome] }),
            bubbleStructureBreakdown: countBy(blockLedgers.map(\.bubbleAssignmentStatus) + blockLedgers.map(\.bubbleSplitRisk) + blockLedgers.map(\.sameBubbleSiblingRisk)),
            segmentGlyphEvidenceBreakdown: countBy(blockLedgers.map(\.segmentGlyphEvidenceStatus)),
            translationFailureRouteBreakdown: countBy(blockLedgers.map(\.translationFailureRoute)),
            renderLockRouteBreakdown: countBy(blockLedgers.map(\.renderLockStatus)),
            primaryBottleneckBreakdown: countBy(blockLedgers.map(\.primaryBottleneck)),
            nextActionBreakdown: countBy(blockLedgers.map(\.nextAction)),
            stopReasonBreakdown: countBy(blockLedgers.flatMap(\.stopReasons)),
            fullProbeReviewReasonBreakdown: countBy(blockLedgers.flatMap(\.fullProbeReviewReasons)),
            stopBlockIndexes: stopBlocks,
            fullProbeReviewBlockIndexes: fullReviewBlocks,
            realTextBoxesNeededBlocks: realTextBoxesBlocks,
            realBubbleMaskNeededBlocks: realBubbleBlocks,
            realSegmentMaskNeededBlocks: realSegmentBlocks,
            modelFloorRoutedBlocks: modelFloorBlocks,
            renderLockRoutedBlocks: renderLockBlocks,
            candidateFamilyLedgers: familyLedgers.sorted { $0.blockIndex < $1.blockIndex },
            blockLedgers: blockLedgers.sorted { $0.blockIndex < $1.blockIndex },
            gateLedger: gates,
            notes: [
                "koharuNativeTextBoxDetectorLiteClosedLoopReport consumes v1.39 detector-lite, v1.40 shadow OCR, v1.41 refinement, final blocks, diagnostics, BubbleMask, SegmentMask, translation floor, render lock, and external artifact readiness.",
                "It is a report-only router: no OCR, LLM, PNG rendering, prompt, model, finalTextUsedForTranslation, blockPassed, failureCategory, currentBlockSource, or textRegionCropReport.adoptedCount changes.",
                "Ground truth similarity appears only in evaluationSignals and never drives route, nextAction, gate, or candidate family verdict.",
                "Missing active test/koharu_artifacts remains readiness=\(externalArtifactReadinessReport?.readinessVerdict ?? "manifestMissing"); detector-lite proxy output is not real Koharu TextBoxes/OcrText.",
                "v17-v20 TextRegion crop / line / deskew local tuning remains stoplisted unless a separate full-probe promotion task proves benefit."
            ]
        )
    }

    private static func makeKoharuNativeArtifactBundleLiteReport(
        blocks: [MangaOverlayProbeBlock],
        detectorLiteReport: MangaKoharuNativeTextBoxDetectorLiteReport?,
        shadowOCRReport: MangaKoharuNativeTextBoxDetectorLiteShadowOCRReport?,
        refinementReport: MangaKoharuNativeTextBoxDetectorLiteRefinementReport?,
        closedLoopReport: MangaKoharuNativeTextBoxDetectorLiteClosedLoopReport?,
        bubbleInstanceLiteReport: MangaKoharuNativeBubbleMaskInstanceLiteReport?,
        segmentRefinementLiteReport: MangaKoharuNativeSegmentMaskRefinementLiteReport?,
        renderSpriteFitPlannerReport: MangaKoharuRenderSpriteFitPlannerReport?,
        koharuRenderRegressionLockReport: MangaKoharuRenderRegressionLockReport?,
        translationModelFloorComparisonReport: MangaTranslationModelFloorComparisonReport?,
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?
    ) -> MangaKoharuNativeArtifactBundleLiteReport {
        func uniqueSorted(_ values: [Int]) -> [Int] { Array(Set(values)).sorted() }
        func countBy(_ values: [String]) -> [String: Int] {
            values.reduce(into: [:]) { partial, value in partial[value, default: 0] += 1 }
        }
        func formatted(_ value: Double?) -> String {
            value?.formatted(.number.precision(.fractionLength(4))) ?? "nil"
        }
        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaKoharuNativeArtifactBundleLiteSignal {
            MangaKoharuNativeArtifactBundleLiteSignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }
        func rectContains(_ outer: [Double]?, _ inner: [Double]?, tolerance: CGFloat = 2) -> Bool {
            guard let outer, let inner else { return false }
            let outerRect = Self.rect(from: outer).insetBy(dx: -tolerance, dy: -tolerance)
            let innerRect = Self.rect(from: inner)
            return innerRect.minX >= outerRect.minX
                && innerRect.minY >= outerRect.minY
                && innerRect.maxX <= outerRect.maxX
                && innerRect.maxY <= outerRect.maxY
        }
        func rectAligned(_ lhs: [Double]?, _ rhs: [Double]?) -> Bool {
            guard let lhs, let rhs else { return false }
            return Self.rectIoU(Self.rect(from: lhs), Self.rect(from: rhs)) >= 0.18
        }
        func component(
            id: String,
            stage: String,
            source: String,
            sourceReport: String,
            bbox: [Double]?,
            confidence: Double?,
            readiness: String,
            fallback: Bool,
            evidence: [String],
            decisions: [MangaKoharuNativeArtifactBundleLiteSignal],
            evaluations: [MangaKoharuNativeArtifactBundleLiteSignal] = []
        ) -> MangaKoharuNativeArtifactBundleLiteComponent {
            MangaKoharuNativeArtifactBundleLiteComponent(
                componentID: id,
                artifactStage: stage,
                componentSource: source,
                sourceReport: sourceReport,
                bbox: bbox,
                confidence: confidence,
                readinessStatus: readiness,
                proxyOnly: true,
                fallbackUsed: fallback,
                evidence: evidence,
                decisionSignals: decisions,
                evaluationSignals: evaluations,
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            )
        }
        func edge(
            blockIndex: Int,
            type: String,
            status: String,
            severity: String,
            evidence: [String],
            decisions: [MangaKoharuNativeArtifactBundleLiteSignal],
            evaluations: [MangaKoharuNativeArtifactBundleLiteSignal] = []
        ) -> MangaKoharuNativeArtifactBundleLiteConsistencyEdge {
            MangaKoharuNativeArtifactBundleLiteConsistencyEdge(
                edgeID: "NABL.block\(blockIndex).\(type)",
                edgeType: type,
                status: status,
                severity: severity,
                evidence: evidence,
                affectedBlocks: [blockIndex],
                decisionSignals: decisions,
                evaluationSignals: evaluations,
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            )
        }
        func gate(
            _ id: String,
            _ name: String,
            _ scope: String,
            _ status: String,
            _ threshold: String,
            _ affected: [Int],
            _ failure: String,
            _ action: String,
            _ signals: [MangaKoharuNativeArtifactBundleLiteSignal]
        ) -> MangaKoharuNativeArtifactBundleLiteGate {
            MangaKoharuNativeArtifactBundleLiteGate(
                gateID: id,
                gateName: name,
                scope: scope,
                status: status,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                decisionSignals: signals,
                failureMeans: failure,
                recommendedAction: action,
                groundTruthUsedForDecision: false
            )
        }
        func textBoxSegmentLinkStatus(_ verdict: String) -> (status: String, severity: String, risk: Bool, promotionBlocked: Bool) {
            switch verdict {
            case "acceptedTextBoxCandidate":
                return ("passed", "info", false, false)
            case "weakAcceptedTextBoxRelation", "manualReviewTextBoxCandidate", "fallbackFinalBlockBBox":
                return ("warning", "medium", true, true)
            case "rejectedTextBoxCandidate", "sourceTextBoxBubbleMismatch":
                return ("blocked", "high", true, true)
            default:
                return ("warning", "medium", true, true)
            }
        }

        let allBlockIndexes = blocks.map(\.index)
        let detectorByBlock = Dictionary(
            uniqueKeysWithValues: (detectorLiteReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let closedLoopByBlock = Dictionary(
            uniqueKeysWithValues: (closedLoopReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let shadowByBlock = Dictionary(
            uniqueKeysWithValues: (shadowOCRReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let refinementByBlock = Dictionary(
            uniqueKeysWithValues: (refinementReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let bubbleByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleInstanceLiteReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let segmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentRefinementLiteReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let renderFitByBlock = Dictionary(
            uniqueKeysWithValues: (renderSpriteFitPlannerReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let renderLockByBlock = Dictionary(
            uniqueKeysWithValues: (koharuRenderRegressionLockReport?.blockLocks ?? []).map { ($0.blockIndex, $0) }
        )
        let modelFloorByBlock = Dictionary(
            uniqueKeysWithValues: (translationModelFloorComparisonReport?.noisyBlockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let segmentSiblings = segmentRefinementLiteReport?.siblingLedgers ?? []
        let bubbleSiblings = bubbleInstanceLiteReport?.siblingLedgers ?? []
        let seamLedgers = renderSpriteFitPlannerReport?.siblingLedgers ?? []

        var blockLedgers: [MangaKoharuNativeArtifactBundleLiteBlockLedger] = []
        var edges: [MangaKoharuNativeArtifactBundleLiteConsistencyEdge] = []

        for block in blocks.sorted(by: { $0.index < $1.index }) {
            let detector = detectorByBlock[block.index]
            let closedLoop = closedLoopByBlock[block.index]
            let shadow = shadowByBlock[block.index]
            let refinement = refinementByBlock[block.index]
            let bubble = bubbleByBlock[block.index]
            let segment = segmentByBlock[block.index]
            let renderFit = renderFitByBlock[block.index]
            let renderLock = renderLockByBlock[block.index]
            let modelFloor = modelFloorByBlock[block.index]
            let textBoxSegmentLinkVerdict = segment?.selectedSourceTextBoxLinkVerdict ?? "fallbackFinalBlockBBox"
            let textBoxSegmentLink = textBoxSegmentLinkStatus(textBoxSegmentLinkVerdict)
            let textBoxBBox = segment?.selectedCandidateID.flatMap { selectedID in
                segmentRefinementLiteReport?.candidateLedgers.first { $0.candidateID == selectedID }?.bbox
            } ?? detector?.bestCandidateBBox ?? block.bbox
            let textBoxSource = segment?.selectedCandidateID != nil
                ? "nativeSegmentMaskRefinementLiteSelectedTextBox"
                : (detector?.bestCandidateBBox != nil ? "nativeDetectorLiteCandidate" : "fallbackFinalBlockBBox")
            let textBoxReady = textBoxSource == "fallbackFinalBlockBBox" ? "fallbackProxyReady" : "nativeLiteReady"
            let bubbleBBox = bubble?.instanceLiteSafeRect
                ?? bubble?.distanceFieldSafeRectFromInstanceLite
                ?? block.safeLayoutRect
                ?? block.bbox
            let bubbleSource = bubble?.instanceLiteMajorityID != nil
                ? "nativeBubbleMaskInstanceLiteMajority"
                : "fallbackCurrentBubbleGeometry"
            let bubbleReady = bubble?.instanceLiteMajorityID != nil ? "nativeLiteReady" : "fallbackProxyReady"
            let segmentBBox = segment?.maskBBox ?? block.glyphMaskRect
            let segmentSource = segment?.selectedCandidateID != nil
                ? "nativeSegmentMaskRefinementLiteSelectedCandidate"
                : (block.glyphMaskRect != nil ? "fallbackGlyphMaskProxy" : "fallbackMissingSegmentMaskProxy")
            let segmentReady: String
            if segment?.wouldBeUsableForClearTextMask == true {
                segmentReady = "nativeLiteReady"
            } else if segmentBBox != nil {
                segmentReady = "fallbackProxyReady"
            } else {
                segmentReady = "blockedMissingSegmentMaskLite"
            }
            let renderLocked = renderLock?.renderCollisionResolved == false
                || renderLock?.renderTextTruncated == true
                || renderFit?.fitVerdict == "renderLockedNoPromotion"
                || block.renderTextTruncated
            let modelBlocked = modelFloor?.modelFloorLimited == true
                || block.failureCategory == "modelOutputFailure"
                || block.failureCategory == "translationLanguageQualityFailure"

            let selectedTextBox = component(
                id: detector?.bestCandidateID ?? "block\(block.index).finalBBox",
                stage: "TextBoxes",
                source: textBoxSource,
                sourceReport: textBoxSource == "nativeDetectorLiteCandidate" ? "koharuNativeTextBoxDetectorLiteReport" : "koharuNativeSegmentMaskRefinementLiteReport",
                bbox: textBoxBBox,
                confidence: detector?.bestCandidateScore,
                readiness: textBoxReady,
                fallback: textBoxSource == "fallbackFinalBlockBBox",
                evidence: [
                    "detectorLiteBest=\(detector?.bestCandidateID ?? "nil")",
                    "segmentSelectedCandidate=\(segment?.selectedCandidateID ?? "nil")",
                    "segmentSelectedSourceTextBox=\(segment?.selectedSourceTextBoxCandidateID ?? "nil")",
                    "segmentTextBoxLinkVerdict=\(textBoxSegmentLinkVerdict)",
                    "closedLoopRoute=\(closedLoop?.closedLoopRoute ?? "nil")"
                ],
                decisions: [
                    signal("componentSource", textBoxSource, source: "koharuNativeArtifactBundleLiteReport"),
                    signal("detectorLiteBestCandidateID", detector?.bestCandidateID ?? "nil", source: "koharuNativeTextBoxDetectorLiteReport"),
                    signal("segmentSelectedSourceTextBoxCandidateID", segment?.selectedSourceTextBoxCandidateID ?? "nil", source: "koharuNativeSegmentMaskRefinementLiteReport"),
                    signal("selectedTextBoxSegmentLinkVerdict", textBoxSegmentLinkVerdict, source: "koharuNativeSegmentMaskRefinementLiteReport")
                ],
                evaluations: [
                    signal("ocrGroundTruthSimilarity", formatted(block.ocrGroundTruthSimilarity), source: "blocks", decision: false, evaluation: true),
                    signal("bestGroundTruthType", block.bestGroundTruthType ?? "nil", source: "blocks", decision: false, evaluation: true)
                ]
            )
            let bubbleSafeRectComparison = bubble?.decisionSignals.first { $0.name == "safeRectComparison" }?.value ?? "nil"
            let selectedBubble = component(
                id: bubble?.instanceLiteMajorityID.map { "instanceLite.\($0)" } ?? "block\(block.index).currentBubble.\(block.bubbleID.map(String.init) ?? "nil")",
                stage: "BubbleMask",
                source: bubbleSource,
                sourceReport: bubble?.instanceLiteMajorityID != nil ? "koharuNativeBubbleMaskInstanceLiteReport" : "bubbleGeometry",
                bbox: bubbleBBox,
                confidence: bubble?.instanceLiteMajorityCoverage,
                readiness: bubbleReady,
                fallback: bubble?.instanceLiteMajorityID == nil,
                evidence: [
                    "instanceLiteMajorityID=\(bubble?.instanceLiteMajorityID.map(String.init) ?? "nil")",
                    "assignmentAgreement=\(bubble?.assignmentAgreement ?? "nil")",
                    "safeRectComparison=\(bubbleSafeRectComparison)"
                ],
                decisions: [
                    signal("componentSource", bubbleSource, source: "koharuNativeArtifactBundleLiteReport"),
                    signal("assignmentAgreement", bubble?.assignmentAgreement ?? "nil", source: "koharuNativeBubbleMaskInstanceLiteReport")
                ]
            )
            let selectedSegment = component(
                id: segment?.selectedCandidateID ?? "block\(block.index).glyphMaskProxy",
                stage: "SegmentMask",
                source: segmentSource,
                sourceReport: segment?.selectedCandidateID != nil ? "koharuNativeSegmentMaskRefinementLiteReport" : "segmentMaskReport/blocks",
                bbox: segmentBBox,
                confidence: segment?.segmentProxyAgreement,
                readiness: segmentReady,
                fallback: segment?.selectedCandidateID == nil,
                evidence: [
                    "selectedCandidateID=\(segment?.selectedCandidateID ?? "nil")",
                    "selectedSourceTextBoxCandidateID=\(segment?.selectedSourceTextBoxCandidateID ?? "nil")",
                    "selectedSourceTextBoxLinkVerdict=\(textBoxSegmentLinkVerdict)",
                    "maskContainedByTextBox=\(segment.map { String($0.maskContainedByTextBox) } ?? "nil")",
                    "maskContainedByBubble=\(segment.map { String($0.maskContainedByBubble) } ?? "nil")"
                ],
                decisions: [
                    signal("componentSource", segmentSource, source: "koharuNativeArtifactBundleLiteReport"),
                    signal("segmentMaskReady", segmentReady, source: "koharuNativeSegmentMaskRefinementLiteReport"),
                    signal("selectedTextBoxSegmentLinkVerdict", textBoxSegmentLinkVerdict, source: "koharuNativeSegmentMaskRefinementLiteReport"),
                    signal("textBoxSegmentLinkageStatus", textBoxSegmentLink.status, source: "koharuNativeArtifactBundleLiteReport")
                ]
            )

            let textBoxWithinBubble = rectContains(bubbleBBox, textBoxBBox)
            let segmentWithinTextBox = rectContains(textBoxBBox, segmentBBox)
            let segmentWithinBubble = rectContains(bubbleBBox, segmentBBox)
            let ocrAligned = rectAligned(block.bbox, textBoxBBox)
            let segmentSibling = segmentSiblings.first { $0.blockIndexes.contains(block.index) }
            let bubbleSibling = bubbleSiblings.first { $0.blockIndexes.contains(block.index) }
            let sameBubbleSiblingOK = (segmentSibling?.maskBBoxOverlapCount ?? 0) == 0
                && (bubbleSibling?.instanceLiteSafeRectOverlapCount ?? 0) == 0
            let seamExplains = segmentSibling?.seamRisk == "needsSeamPartitionEvidence"
                || bubbleSibling?.siblingPartitionStatus.contains("Risk") == true
                || seamLedgers.contains { $0.blockIndexes.contains(block.index) && !$0.relatedSeamCandidateIDs.isEmpty }
            let spriteContained = renderFit?.spriteContainedByDistanceFieldSafeRect
                ?? renderFit?.spriteContainedByCurrentSafeRect
                ?? (renderLock?.renderCollisionResolved == true ? true : nil)
            let modelSeparates = modelBlocked
                || modelFloor?.modelFloorLimited == true
                || closedLoop?.translationFailureRoute.contains("ModelFloor") == true
                || closedLoop?.closedLoopRoute == "routeToModelFloor"
            let finalOCRTextBoxIoU = Self.rectIoU(Self.rect(from: block.bbox), Self.rect(from: textBoxBBox))

            let blockEdges = [
                edge(blockIndex: block.index, type: "TextBoxWithinBubble", status: textBoxWithinBubble ? "passed" : "warning", severity: textBoxWithinBubble ? "info" : "medium", evidence: ["textBoxSource=\(textBoxSource)", "bubbleSource=\(bubbleSource)"], decisions: [signal("textBoxWithinBubble", String(textBoxWithinBubble), source: "koharuNativeArtifactBundleLiteReport")]),
                edge(blockIndex: block.index, type: "TextBoxSegmentMaskLinkage", status: textBoxSegmentLink.status, severity: textBoxSegmentLink.severity, evidence: ["selectedSourceTextBoxCandidateID=\(segment?.selectedSourceTextBoxCandidateID ?? "nil")", "selectedSourceTextBoxLinkVerdict=\(textBoxSegmentLinkVerdict)", "selectedSegmentCandidateID=\(segment?.selectedCandidateID ?? "nil")"], decisions: [signal("selectedTextBoxSegmentLinkVerdict", textBoxSegmentLinkVerdict, source: "koharuNativeSegmentMaskRefinementLiteReport"), signal("textBoxSegmentLinkageStatus", textBoxSegmentLink.status, source: "koharuNativeArtifactBundleLiteReport")]),
                edge(blockIndex: block.index, type: "SegmentMaskWithinTextBox", status: segmentWithinTextBox ? "passed" : "warning", severity: segmentWithinTextBox ? "info" : "medium", evidence: ["segmentSource=\(segmentSource)", "textBoxSource=\(textBoxSource)"], decisions: [signal("segmentMaskWithinTextBox", String(segmentWithinTextBox), source: "koharuNativeArtifactBundleLiteReport")]),
                edge(blockIndex: block.index, type: "SegmentMaskWithinBubble", status: segmentWithinBubble ? "passed" : "warning", severity: segmentWithinBubble ? "info" : "medium", evidence: ["segmentSource=\(segmentSource)", "bubbleSource=\(bubbleSource)"], decisions: [signal("segmentMaskWithinBubble", String(segmentWithinBubble), source: "koharuNativeArtifactBundleLiteReport")]),
                edge(blockIndex: block.index, type: "FinalOCRBBoxAlignedWithTextBox", status: ocrAligned ? "passed" : "warning", severity: ocrAligned ? "info" : "low", evidence: ["finalBlockBBoxVsTextBoxIoU=\(formatted(finalOCRTextBoxIoU))"], decisions: [signal("finalOCRBBoxAlignedWithTextBox", String(ocrAligned), source: "koharuNativeArtifactBundleLiteReport")]),
                edge(blockIndex: block.index, type: "SameBubbleSiblingMaskNonOverlap", status: sameBubbleSiblingOK ? "passed" : "warning", severity: sameBubbleSiblingOK ? "info" : "medium", evidence: ["segmentSiblingOverlap=\(segmentSibling?.maskBBoxOverlapCount ?? 0)", "bubbleSafeRectOverlap=\(bubbleSibling?.instanceLiteSafeRectOverlapCount ?? 0)"], decisions: [signal("sameBubbleSiblingMaskNonOverlap", String(sameBubbleSiblingOK), source: "koharuNativeArtifactBundleLiteReport")]),
                edge(blockIndex: block.index, type: "SeamOrSplitRiskExplainsConflict", status: seamExplains || sameBubbleSiblingOK ? "passed" : "warning", severity: seamExplains || sameBubbleSiblingOK ? "info" : "medium", evidence: ["seamRisk=\(segmentSibling?.seamRisk ?? "nil")", "siblingPartition=\(bubbleSibling?.siblingPartitionStatus ?? "nil")"], decisions: [signal("seamOrSplitRiskExplainsConflict", String(seamExplains), source: "koharuNativeArtifactBundleLiteReport")]),
                edge(blockIndex: block.index, type: "RenderSpriteContainedByBundleSafeArea", status: spriteContained == true ? "passed" : (renderLocked ? "blocked" : "warning"), severity: spriteContained == true ? "info" : "medium", evidence: ["fitVerdict=\(renderFit?.fitVerdict ?? "nil")", "renderStatus=\(renderLock?.renderStatus ?? "nil")"], decisions: [signal("renderSpriteContainedByBundleSafeArea", spriteContained.map(String.init) ?? "nil", source: "koharuRenderSpriteFitPlannerReport")]),
                edge(blockIndex: block.index, type: "ModelFloorSeparatesGeometryFromTranslation", status: "passed", severity: "info", evidence: ["failureCategory=\(block.failureCategory)", "modelFloorLimited=\((modelFloor?.modelFloorLimited).map(String.init) ?? "nil")"], decisions: [signal("modelFloorSeparated", String(modelSeparates), source: "translationModelFloorComparisonReport,blocks")])
            ]
            edges.append(contentsOf: blockEdges)

            let consistencyVerdict: String
            if blockEdges.contains(where: { $0.status == "blocked" }) {
                consistencyVerdict = "blockedByCrossArtifactConflict"
            } else if blockEdges.contains(where: { $0.status == "warning" }) {
                consistencyVerdict = "nativeArtifactBundleLiteInconsistent"
            } else {
                consistencyVerdict = "nativeArtifactBundleLiteConsistent"
            }
            let primaryBlockingArtifact: String
            let nextAction: String
            if modelBlocked {
                primaryBlockingArtifact = "Translations"
                nextAction = "modelFloorNoGeometryAction"
            } else if renderLocked {
                primaryBlockingArtifact = "RenderedSprites"
                nextAction = "renderLockNoOCRAction"
            } else if textBoxSegmentLink.risk {
                primaryBlockingArtifact = "TextBoxes"
                nextAction = "auditTextBoxSegmentLinkageBeforeBundleReadiness"
            } else if selectedTextBox.fallbackUsed || closedLoop?.closedLoopRoute == "routeToRealTextBoxesArtifact" {
                primaryBlockingArtifact = "TextBoxes"
                nextAction = "collectRealTextBoxesArtifact"
            } else if selectedBubble.fallbackUsed || !textBoxWithinBubble || closedLoop?.closedLoopRoute == "routeToRealBubbleMaskArtifact" {
                primaryBlockingArtifact = "BubbleMask"
                nextAction = "collectRealBubbleMaskArtifact"
            } else if selectedSegment.fallbackUsed || !segmentWithinTextBox || !segmentWithinBubble || closedLoop?.closedLoopRoute == "routeToRealSegmentMaskArtifact" {
                primaryBlockingArtifact = "SegmentMask"
                nextAction = "collectRealSegmentMaskArtifact"
            } else if closedLoop?.closedLoopRoute == "reviewPromisingCandidateInFullProbe" {
                primaryBlockingArtifact = "OcrText"
                nextAction = "readyForFullProbeShadowReview"
            } else if consistencyVerdict == "nativeArtifactBundleLiteConsistent" {
                primaryBlockingArtifact = "NoneReportOnlyConsistent"
                nextAction = "keepMainFusedOCR"
            } else {
                primaryBlockingArtifact = "ManualReview"
                nextAction = "manualReviewOnly"
            }
            let readyForFullProbe = nextAction == "readyForFullProbeShadowReview"
            let needsRealTextBoxes = nextAction == "collectRealTextBoxesArtifact" || nextAction == "auditTextBoxSegmentLinkageBeforeBundleReadiness"
            let needsRealBubble = nextAction == "collectRealBubbleMaskArtifact"
            let needsRealSegment = nextAction == "collectRealSegmentMaskArtifact"
            let manual = nextAction == "manualReviewOnly"

            blockLedgers.append(
                MangaKoharuNativeArtifactBundleLiteBlockLedger(
                    blockIndex: block.index,
                    bubbleID: block.bubbleID,
                    blockPassed: block.blockPassed,
                    failureCategory: block.failureCategory,
                    finalTextUsedForTranslation: block.finalTextUsedForTranslation,
                    selectedTextBoxLite: selectedTextBox,
                    selectedBubbleInstanceLite: selectedBubble,
                    selectedSegmentMaskLite: selectedSegment,
                    selectedTextBoxSegmentLinkVerdict: textBoxSegmentLinkVerdict,
                    textBoxSegmentLinkageStatus: textBoxSegmentLink.status,
                    textBoxSegmentLinkageRisk: textBoxSegmentLink.risk,
                    ocrEvidence: [
                        signal("finalOCRTextLength", String(block.finalTextUsedForTranslation.count), source: "blocks"),
                        signal("shadowOutcome", shadow?.shadowOutcome ?? "nil", source: "koharuNativeTextBoxDetectorLiteShadowOCRReport"),
                        signal("refinementOutcome", refinement?.refinementOutcome ?? "nil", source: "koharuNativeTextBoxDetectorLiteRefinementReport"),
                        signal("closedLoopRoute", closedLoop?.closedLoopRoute ?? "nil", source: "koharuNativeTextBoxDetectorLiteClosedLoopReport")
                    ],
                    translationFailureRoute: closedLoop?.translationFailureRoute ?? (modelBlocked ? "modelFloorRoute" : "notModelFloor"),
                    renderFitEvidence: [
                        signal("fitVerdict", renderFit?.fitVerdict ?? "nil", source: "koharuRenderSpriteFitPlannerReport"),
                        signal("renderStatus", renderLock?.renderStatus ?? "nil", source: "koharuRenderRegressionLockReport"),
                        signal("spriteContainedByDistanceFieldSafeRect", renderFit?.spriteContainedByDistanceFieldSafeRect.map(String.init) ?? "nil", source: "koharuRenderSpriteFitPlannerReport")
                    ],
                    artifactConsistencyVerdict: consistencyVerdict,
                    primaryBlockingArtifact: primaryBlockingArtifact,
                    nextAction: nextAction,
                    readyForFullProbeShadowReview: readyForFullProbe,
                    needsRealTextBoxes: needsRealTextBoxes,
                    needsRealBubbleMask: needsRealBubble,
                    needsRealSegmentMask: needsRealSegment,
                    modelFloorBlocked: modelBlocked,
                    renderLocked: renderLocked,
                    manualReviewRequired: manual,
                    decisionSignals: [
                        signal("artifactConsistencyVerdict", consistencyVerdict, source: "koharuNativeArtifactBundleLiteReport"),
                        signal("primaryBlockingArtifact", primaryBlockingArtifact, source: "koharuNativeArtifactBundleLiteReport"),
                        signal("nextAction", nextAction, source: "koharuNativeArtifactBundleLiteReport"),
                        signal("selectedTextBoxSegmentLinkVerdict", textBoxSegmentLinkVerdict, source: "koharuNativeSegmentMaskRefinementLiteReport"),
                        signal("textBoxSegmentLinkageStatus", textBoxSegmentLink.status, source: "koharuNativeArtifactBundleLiteReport")
                    ],
                    evaluationSignals: [
                        signal("groundTruthMatch", block.groundTruthMatch, source: "blocks", decision: false, evaluation: true),
                        signal("bestGroundTruthType", block.bestGroundTruthType ?? "nil", source: "blocks", decision: false, evaluation: true),
                        signal("ocrGroundTruthSimilarity", formatted(block.ocrGroundTruthSimilarity), source: "blocks", decision: false, evaluation: true)
                    ],
                    groundTruthUsedForDecision: false,
                    wouldChangeMainFlow: false,
                    diagnosticOnly: true
                )
            )
        }

        func affected(_ nextAction: String) -> [Int] {
            uniqueSorted(blockLedgers.filter { $0.nextAction == nextAction }.map(\.blockIndex))
        }
        let readyForFullProbeReviewBlocks = uniqueSorted(blockLedgers.filter(\.readyForFullProbeShadowReview).map(\.blockIndex))
        let textBoxSegmentLinkageReviewBlocks = uniqueSorted(blockLedgers.filter(\.textBoxSegmentLinkageRisk).map(\.blockIndex))
        let needsRealTextBoxesBlocks = uniqueSorted(blockLedgers.filter(\.needsRealTextBoxes).map(\.blockIndex))
        let needsRealBubbleMaskBlocks = uniqueSorted(blockLedgers.filter(\.needsRealBubbleMask).map(\.blockIndex))
        let needsRealSegmentMaskBlocks = uniqueSorted(blockLedgers.filter(\.needsRealSegmentMask).map(\.blockIndex))
        let modelFloorBlockedBlocks = uniqueSorted(blockLedgers.filter(\.modelFloorBlocked).map(\.blockIndex))
        let renderLockedBlocks = uniqueSorted(blockLedgers.filter(\.renderLocked).map(\.blockIndex))
        let manualReviewBlocks = uniqueSorted(blockLedgers.filter(\.manualReviewRequired).map(\.blockIndex))
        let workItems = [
            MangaKoharuNativeArtifactBundleLiteWorkItem(
                workItemID: "WI-koharu-native-artifact-bundle-lite-full-probe-review",
                title: "Full-probe review for promising native-lite bundles",
                targetArtifact: "OcrText",
                status: readyForFullProbeReviewBlocks.isEmpty ? "notRequired" : "openReportOnly",
                priority: readyForFullProbeReviewBlocks.isEmpty ? "low" : "medium",
                affectedBlocks: readyForFullProbeReviewBlocks,
                nextAction: "readyForFullProbeShadowReview",
                decisionSignals: [signal("readyForFullProbeReviewBlocks", readyForFullProbeReviewBlocks.map(String.init).joined(separator: ","), source: "koharuNativeArtifactBundleLiteReport")],
                evaluationSignals: [],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            ),
            MangaKoharuNativeArtifactBundleLiteWorkItem(
                workItemID: "WI-koharu-native-artifact-bundle-lite-textbox-segment-linkage",
                title: "Audit TextBox to SegmentMask linkage before bundle readiness",
                targetArtifact: "TextBoxes/SegmentMask",
                status: textBoxSegmentLinkageReviewBlocks.isEmpty ? "notRequired" : "blockedByWeakTextBoxSegmentLinkage",
                priority: textBoxSegmentLinkageReviewBlocks.isEmpty ? "low" : "high",
                affectedBlocks: textBoxSegmentLinkageReviewBlocks,
                nextAction: "auditTextBoxSegmentLinkageBeforeBundleReadiness",
                decisionSignals: [
                    signal("textBoxSegmentLinkageReviewBlocks", textBoxSegmentLinkageReviewBlocks.map(String.init).joined(separator: ","), source: "koharuNativeArtifactBundleLiteReport"),
                    signal("textBoxSegmentLinkBreakdown", countBy(blockLedgers.map(\.selectedTextBoxSegmentLinkVerdict)).map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ","), source: "koharuNativeArtifactBundleLiteReport")
                ],
                evaluationSignals: [],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            ),
            MangaKoharuNativeArtifactBundleLiteWorkItem(
                workItemID: "WI-koharu-native-artifact-bundle-lite-real-textboxes",
                title: "Collect real TextBoxes for fallback bundles",
                targetArtifact: "TextBoxes",
                status: needsRealTextBoxesBlocks.isEmpty ? "notRequired" : "blockedByMissingRealArtifact",
                priority: needsRealTextBoxesBlocks.isEmpty ? "low" : "high",
                affectedBlocks: needsRealTextBoxesBlocks,
                nextAction: "collectRealTextBoxesArtifact",
                decisionSignals: [signal("needsRealTextBoxesBlocks", needsRealTextBoxesBlocks.map(String.init).joined(separator: ","), source: "koharuNativeArtifactBundleLiteReport")],
                evaluationSignals: [],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            ),
            MangaKoharuNativeArtifactBundleLiteWorkItem(
                workItemID: "WI-koharu-native-artifact-bundle-lite-real-bubblemask",
                title: "Collect real BubbleMask for bundle conflicts",
                targetArtifact: "BubbleMask",
                status: needsRealBubbleMaskBlocks.isEmpty ? "notRequired" : "blockedByMissingRealArtifact",
                priority: needsRealBubbleMaskBlocks.isEmpty ? "low" : "high",
                affectedBlocks: needsRealBubbleMaskBlocks,
                nextAction: "collectRealBubbleMaskArtifact",
                decisionSignals: [signal("needsRealBubbleMaskBlocks", needsRealBubbleMaskBlocks.map(String.init).joined(separator: ","), source: "koharuNativeArtifactBundleLiteReport")],
                evaluationSignals: [],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            ),
            MangaKoharuNativeArtifactBundleLiteWorkItem(
                workItemID: "WI-koharu-native-artifact-bundle-lite-real-segmentmask",
                title: "Collect real SegmentMask for bundle conflicts",
                targetArtifact: "SegmentMask",
                status: needsRealSegmentMaskBlocks.isEmpty ? "notRequired" : "blockedByMissingRealArtifact",
                priority: needsRealSegmentMaskBlocks.isEmpty ? "low" : "high",
                affectedBlocks: needsRealSegmentMaskBlocks,
                nextAction: "collectRealSegmentMaskArtifact",
                decisionSignals: [signal("needsRealSegmentMaskBlocks", needsRealSegmentMaskBlocks.map(String.init).joined(separator: ","), source: "koharuNativeArtifactBundleLiteReport")],
                evaluationSignals: [],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            ),
            MangaKoharuNativeArtifactBundleLiteWorkItem(
                workItemID: "WI-koharu-native-artifact-bundle-lite-model-render-stop",
                title: "Stop geometry tuning for model floor or render lock",
                targetArtifact: "Translations/RenderedSprites",
                status: modelFloorBlockedBlocks.isEmpty && renderLockedBlocks.isEmpty ? "notRequired" : "closedReportOnly",
                priority: modelFloorBlockedBlocks.isEmpty && renderLockedBlocks.isEmpty ? "low" : "medium",
                affectedBlocks: uniqueSorted(modelFloorBlockedBlocks + renderLockedBlocks),
                nextAction: "modelFloorNoGeometryAction/renderLockNoOCRAction",
                decisionSignals: [
                    signal("modelFloorBlockedBlocks", modelFloorBlockedBlocks.map(String.init).joined(separator: ","), source: "translationModelFloorComparisonReport"),
                    signal("renderLockedBlocks", renderLockedBlocks.map(String.init).joined(separator: ","), source: "koharuRenderRegressionLockReport")
                ],
                evaluationSignals: [],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            )
        ].filter { !$0.affectedBlocks.isEmpty || $0.workItemID == "WI-koharu-native-artifact-bundle-lite-full-probe-review" }
        let missingUpstream = [
            detectorLiteReport?.enabled == true ? nil : "koharuNativeTextBoxDetectorLiteReport",
            closedLoopReport?.enabled == true ? nil : "koharuNativeTextBoxDetectorLiteClosedLoopReport",
            bubbleInstanceLiteReport?.enabled == true ? nil : "koharuNativeBubbleMaskInstanceLiteReport",
            segmentRefinementLiteReport?.enabled == true ? nil : "koharuNativeSegmentMaskRefinementLiteReport"
        ].compactMap { $0 }
        let gates = [
            gate("G-native-artifact-bundle-lite-input-reports", "Input reports", "TextBoxes/BubbleMask/SegmentMask", missingUpstream.isEmpty ? "passed" : "warning", "v1.39-v1.44 native-lite reports available", allBlockIndexes, "bundle-lite cannot aggregate native-lite structures or silently emits an empty shell", "restoreNativeLiteUpstreamReports", [signal("missingUpstreamReports", missingUpstream.joined(separator: ","), source: "koharuNativeArtifactBundleLiteReport")]),
            gate("G-native-artifact-bundle-lite-report-only", "Report only", "report", "passed", "wouldChangeMainFlow=false", [], "bundle-lite mutates OCR, translation, overlay, renderer, blockPassed, failureCategory, safeLayoutRect, glyph masks, or currentBlockSource", "revertBehavioralChange", [signal("wouldChangeMainFlow", "false", source: "koharuNativeArtifactBundleLiteReport")]),
            gate("G-native-artifact-bundle-lite-no-ground-truth-decision", "No ground truth decision", "report", "passed", "groundTruthUsedForDecision=false", allBlockIndexes, "ground truth selects bundle components, edges, verdict, gate, worklist, or nextAction", "moveGroundTruthToEvaluationSignalsOnly", [signal("groundTruthUsedForDecision", "false", source: "koharuNativeArtifactBundleLiteReport")]),
            gate("G-native-artifact-bundle-lite-block-ledger-count", "Block ledger count", "blocks", blockLedgers.count == blocks.count ? "passed" : "warning", "bundleLedgerCount==totalBlocksDetected", allBlockIndexes, "some final blocks lack artifact bundle ledger rows", "restoreBundleLedgerCoverage", [signal("bundleLedgerCount", String(blockLedgers.count), source: "koharuNativeArtifactBundleLiteReport")]),
            gate("G-native-artifact-bundle-lite-edge-coverage", "Consistency edge coverage", "artifactEdges", edges.count >= blocks.count ? "passed" : "warning", "consistencyEdgeCount>=totalBlocksDetected", allBlockIndexes, "bundle report lacks per-block cross-artifact consistency edges", "restoreConsistencyEdges", [signal("consistencyEdgeCount", String(edges.count), source: "koharuNativeArtifactBundleLiteReport")]),
            gate("G-native-artifact-bundle-lite-textbox-segment-linkage", "TextBox SegmentMask linkage", "TextBoxes->SegmentMask", textBoxSegmentLinkageReviewBlocks.isEmpty ? "passed" : "warning", "selected SegmentMask should come from accepted same-bubble TextBox linkage; fallback, weak, rejected, or wrong-bubble linkage blocks bundle readiness", textBoxSegmentLinkageReviewBlocks, "bundle-lite treats SegmentMask as consistent while its source TextBox linkage is fallback, weak, rejected, or wrong-bubble", "auditTextBoxSegmentLinkageBeforeBundleReadiness", [signal("textBoxSegmentLinkBreakdown", countBy(blockLedgers.map(\.selectedTextBoxSegmentLinkVerdict)).map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ","), source: "koharuNativeArtifactBundleLiteReport")]),
            gate("G-native-artifact-bundle-lite-proxy-boundary", "Proxy boundary", "proxyBoundary", "passed", "proxyNotRealKoharuTextBoxes/BubbleMask/SegmentMask=true", allBlockIndexes, "bundle-lite is promoted as real Koharu artifact bundle", "keepProxyBoundaryOrCollectRealArtifacts", [signal("proxyNotRealKoharuTextBoxes", "true", source: "koharuNativeArtifactBundleLiteReport"), signal("proxyNotRealKoharuBubbleMask", "true", source: "koharuNativeArtifactBundleLiteReport"), signal("proxyNotRealKoharuSegmentMask", "true", source: "koharuNativeArtifactBundleLiteReport")]),
            gate("G-native-artifact-bundle-lite-worklist", "Worklist", "nextAction", workItems.isEmpty ? "warning" : "passed", "workItemCount>=1", allBlockIndexes, "bundle report repeats block rows without aggregated worklist", "restoreAggregatedWorkItems", [signal("workItemCount", String(workItems.count), source: "koharuNativeArtifactBundleLiteReport")]),
            gate("G-native-artifact-bundle-lite-no-ocr-llm-png", "No OCR LLM PNG", "budget", "passed", "no OCR/LLM calls and no PNG output", [], "bundle-lite adds OCR, LLM, model, prompt, or PNG work", "removeHeavyWorkFromBundleLite", [signal("ocrCalls", "0", source: "koharuNativeArtifactBundleLiteReport"), signal("llmCalls", "0", source: "koharuNativeArtifactBundleLiteReport"), signal("pngOutputs", "0", source: "koharuNativeArtifactBundleLiteReport")]),
            gate("G-native-artifact-bundle-lite-external-boundary", "External artifact boundary", "ExternalArtifacts", "passed", "externalArtifactsRequiredForThisReport=false", [], "bundle-lite creates, copies, edits, or requires active test/koharu_artifacts", "doNotCreateActiveArtifacts", [signal("externalArtifactsRequiredForThisReport", "false", source: "koharuNativeArtifactBundleLiteReport"), signal("readinessVerdict", externalArtifactReadinessReport?.readinessVerdict ?? "manifestMissing", source: "externalArtifactReadinessReport")])
        ]
        let verdict: String
        if !needsRealTextBoxesBlocks.isEmpty {
            verdict = "blockedByMissingTextBoxesLite"
        } else if !needsRealBubbleMaskBlocks.isEmpty {
            verdict = "blockedByMissingBubbleMaskLite"
        } else if !needsRealSegmentMaskBlocks.isEmpty {
            verdict = "blockedByMissingSegmentMaskLite"
        } else if !modelFloorBlockedBlocks.isEmpty {
            verdict = "modelFloorBlocked"
        } else if !renderLockedBlocks.isEmpty {
            verdict = "renderLockedNoPromotion"
        } else if !manualReviewBlocks.isEmpty {
            verdict = "manualReviewOnly"
        } else if blockLedgers.contains(where: { $0.artifactConsistencyVerdict == "nativeArtifactBundleLiteInconsistent" || $0.artifactConsistencyVerdict == "blockedByCrossArtifactConflict" }) {
            verdict = "nativeArtifactBundleLiteInconsistent"
        } else {
            verdict = "nativeArtifactBundleLiteReportOnly"
        }

        return MangaKoharuNativeArtifactBundleLiteReport(
            enabled: true,
            source: "AITRANSProbe",
            referencePipeline: "Koharu",
            referenceConcept: "ArtifactBundle.NativeLite.TextBoxesBubbleMaskSegmentMaskConsistency",
            referenceWorkItemID: "WI-koharu-native-artifact-bundle-lite",
            evaluatedBlockCount: blocks.count,
            bundleLedgerCount: blockLedgers.count,
            consistencyEdgeCount: edges.count,
            workItemCount: workItems.count,
            gateCount: gates.count,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            nativeBundleLite: true,
            proxyNotRealKoharuTextBoxes: true,
            proxyNotRealKoharuBubbleMask: true,
            proxyNotRealKoharuSegmentMask: true,
            externalArtifactsRequiredForThisReport: false,
            bundleLiteVerdict: verdict,
            componentReadinessBreakdown: countBy(blockLedgers.flatMap { [$0.selectedTextBoxLite.readinessStatus, $0.selectedBubbleInstanceLite.readinessStatus, $0.selectedSegmentMaskLite.readinessStatus] }),
            artifactConsistencyBreakdown: countBy(blockLedgers.map(\.artifactConsistencyVerdict)),
            primaryBlockingArtifactBreakdown: countBy(blockLedgers.map(\.primaryBlockingArtifact)),
            ocrRouteBreakdown: countBy(blockLedgers.map { $0.ocrEvidence.first { $0.name == "closedLoopRoute" }?.value ?? "nil" }),
            translationRouteBreakdown: countBy(blockLedgers.map(\.translationFailureRoute)),
            renderRouteBreakdown: countBy(blockLedgers.map { $0.renderFitEvidence.first { $0.name == "fitVerdict" }?.value ?? "nil" }),
            textBoxSegmentLinkBreakdown: countBy(blockLedgers.map(\.selectedTextBoxSegmentLinkVerdict)),
            nextActionBreakdown: countBy(blockLedgers.map(\.nextAction)),
            readyForFullProbeReviewBlocks: readyForFullProbeReviewBlocks,
            textBoxSegmentLinkageReviewBlocks: textBoxSegmentLinkageReviewBlocks,
            needsRealTextBoxesBlocks: needsRealTextBoxesBlocks,
            needsRealBubbleMaskBlocks: needsRealBubbleMaskBlocks,
            needsRealSegmentMaskBlocks: needsRealSegmentMaskBlocks,
            modelFloorBlockedBlocks: modelFloorBlockedBlocks,
            renderLockedBlocks: renderLockedBlocks,
            manualReviewBlocks: manualReviewBlocks,
            blockLedgers: blockLedgers,
            consistencyEdges: edges,
            workItems: workItems,
            gateLedger: gates,
            notes: [
                "koharuNativeArtifactBundleLiteReport aggregates v1.39-v1.44 native-lite TextBoxes, shadow OCR, closed-loop routes, BubbleMask instance-lite, SegmentMask refinement-lite, render fit, render lock, translation floor, and external readiness into a report-only artifact bundle ledger.",
                "Bundle components remain proxy/native-lite only and are never promoted as real Koharu TextBoxes, BubbleMask, SegmentMask, OcrText, RenderedSprites, or FinalRender artifacts.",
                "Ground truth is stored only in evaluationSignals; component choice, consistency edges, verdict, workItems, gates, and nextAction use ground-truth-free signals.",
                "This report does not add OCR, LLM, PNG output, prompt/model changes, active artifact changes, finalTextUsedForTranslation updates, blockPassed changes, failureCategory changes, safeLayoutRect writes, glyph mask writes, renderer changes, or currentBlockSource changes."
            ]
        )
    }

    private static func makeKoharuNativePromotionGateLiteReport(
        blocks: [MangaOverlayProbeBlock],
        diagnostics: MangaOverlayProbeDiagnostics,
        detectorLiteReport: MangaKoharuNativeTextBoxDetectorLiteReport?,
        closedLoopReport: MangaKoharuNativeTextBoxDetectorLiteClosedLoopReport?,
        bubbleInstanceLiteReport: MangaKoharuNativeBubbleMaskInstanceLiteReport?,
        segmentRefinementLiteReport: MangaKoharuNativeSegmentMaskRefinementLiteReport?,
        artifactBundleLiteReport: MangaKoharuNativeArtifactBundleLiteReport?,
        renderSpriteFitPlannerReport: MangaKoharuRenderSpriteFitPlannerReport?,
        koharuRenderRegressionLockReport: MangaKoharuRenderRegressionLockReport?,
        translationModelFloorComparisonReport: MangaTranslationModelFloorComparisonReport?,
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?,
        cleanTextDiagnostic: MangaCleanTextDiagnosticReport?
    ) -> MangaKoharuNativePromotionGateLiteReport {
        func uniqueSorted(_ values: [Int]) -> [Int] { Array(Set(values)).sorted() }
        func countBy(_ values: [String]) -> [String: Int] {
            values.reduce(into: [:]) { partial, value in partial[value, default: 0] += 1 }
        }
        func formatted(_ value: Double?) -> String {
            value?.formatted(.number.precision(.fractionLength(4))) ?? "nil"
        }
        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaKoharuNativePromotionGateLiteSignal {
            MangaKoharuNativePromotionGateLiteSignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }
        func gate(
            _ id: String,
            _ name: String,
            _ scope: String,
            _ status: String,
            _ threshold: String,
            _ affected: [Int],
            _ failure: String,
            _ action: String,
            _ signals: [MangaKoharuNativePromotionGateLiteSignal]
        ) -> MangaKoharuNativePromotionGate {
            MangaKoharuNativePromotionGate(
                gateID: id,
                gateName: name,
                scope: scope,
                status: status,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                decisionSignals: signals,
                failureMeans: failure,
                recommendedAction: action,
                groundTruthUsedForDecision: false
            )
        }
        func statusFor(
            fallbackUsed: Bool,
            needsRealArtifact: Bool,
            modelBlocked: Bool,
            renderLocked: Bool,
            readyForFullProbe: Bool,
            stopLocalTuning: Bool,
            stable: Bool
        ) -> String {
            if modelBlocked { return "blockedByModelFloor" }
            if renderLocked { return "blockedByRenderLock" }
            if needsRealArtifact { return "blockedByMissingRealArtifact" }
            if fallbackUsed { return "blockedByProxyEvidence" }
            if readyForFullProbe { return "shadowReviewEligible" }
            if stopLocalTuning { return "stopLocalTuning" }
            return stable ? "reportOnlyStable" : "manualReviewOnly"
        }
        func textBoxSegmentLinkPromotionStatus(_ verdict: String) -> String {
            switch verdict {
            case "acceptedTextBoxCandidate":
                return "reportOnlyStable"
            case "weakAcceptedTextBoxRelation", "manualReviewTextBoxCandidate", "fallbackFinalBlockBBox":
                return "blockedByWeakTextBoxSegmentLinkage"
            case "rejectedTextBoxCandidate", "sourceTextBoxBubbleMismatch":
                return "blockedByRejectedTextBoxSegmentLinkage"
            default:
                return "blockedByWeakTextBoxSegmentLinkage"
            }
        }
        func stageGate(
            stage: String,
            artifact: String,
            reports: [String],
            required: [String],
            ledgers: [MangaKoharuNativePromotionBlockLedger],
            status: (MangaKoharuNativePromotionBlockLedger) -> String
        ) -> MangaKoharuNativePromotionStageGate {
            let stageStatuses = ledgers.map(status)
            let eligible = uniqueSorted(ledgers.filter {
                let value = status($0)
                return value == "shadowReviewEligible" || value == "reportOnlyStable"
            }.map(\.blockIndex))
            let blocked = uniqueSorted(ledgers.filter {
                let value = status($0)
                return value.hasPrefix("blocked") || value == "manualReviewOnly"
            }.map(\.blockIndex))
            let stop = uniqueSorted(ledgers.filter { status($0) == "stopLocalTuning" }.map(\.blockIndex))
            let readiness: String
            if stage == "ExternalArtifacts" && externalArtifactReadinessReport?.readinessVerdict != "readyForShadowOCR" {
                readiness = "blockedByMissingRealArtifact"
            } else if !blocked.isEmpty {
                readiness = stageStatuses.contains("blockedByModelFloor") ? "blockedByModelFloor" :
                    (stageStatuses.contains("blockedByRenderLock") ? "blockedByRenderLock" : "blockedByProxyEvidence")
            } else if !stop.isEmpty {
                readiness = "stopLocalTuning"
            } else if stageStatuses.contains("shadowReviewEligible") {
                readiness = "shadowReviewEligible"
            } else {
                readiness = "reportOnlyStable"
            }
            let missingEvidence: [String]
            if stage == "ExternalArtifacts" && externalArtifactReadinessReport?.readinessVerdict != "readyForShadowOCR" {
                missingEvidence = externalArtifactReadinessReport?.missingArtifacts ?? ["manifest", "TextBoxes", "BubbleMask", "SegmentMask"]
            } else {
                missingEvidence = []
            }
            return MangaKoharuNativePromotionStageGate(
                stageName: stage,
                referenceKoharuArtifact: artifact,
                currentAITRANSSourceReports: reports,
                stageReadiness: readiness,
                eligibleBlocks: eligible,
                blockedBlocks: blocked,
                stopBlocks: stop,
                requiredEvidence: required,
                missingEvidence: missingEvidence,
                decisionSignals: [
                    signal("stageReadiness", readiness, source: "koharuNativePromotionGateLiteReport"),
                    signal("eligibleBlocks", eligible.map(String.init).joined(separator: ","), source: "koharuNativePromotionGateLiteReport"),
                    signal("blockedBlocks", blocked.map(String.init).joined(separator: ","), source: "koharuNativePromotionGateLiteReport")
                ],
                evaluationSignals: [
                    signal("averageCoreDialogueOCRSimilarity", formatted(diagnostics.averageCoreDialogueOCRSimilarity), source: "diagnostics", decision: false, evaluation: true),
                    signal("cleanTextPassRate", cleanTextDiagnostic?.passRate.formatted(.number.precision(.fractionLength(4))) ?? "nil", source: "cleanTextDiagnostic", decision: false, evaluation: true)
                ],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            )
        }

        let allBlockIndexes = blocks.map(\.index)
        let bundleByBlock = Dictionary(
            uniqueKeysWithValues: (artifactBundleLiteReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let closedLoopByBlock = Dictionary(
            uniqueKeysWithValues: (closedLoopReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let segmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentRefinementLiteReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let renderFitByBlock = Dictionary(
            uniqueKeysWithValues: (renderSpriteFitPlannerReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let renderLockByBlock = Dictionary(
            uniqueKeysWithValues: (koharuRenderRegressionLockReport?.blockLocks ?? []).map { ($0.blockIndex, $0) }
        )
        let modelFloorByBlock = Dictionary(
            uniqueKeysWithValues: (translationModelFloorComparisonReport?.noisyBlockSummaries ?? []).map { ($0.blockIndex, $0) }
        )

        var blockLedgers: [MangaKoharuNativePromotionBlockLedger] = []
        var candidatePreviews: [MangaKoharuNativeCandidateExportPreview] = []

        for block in blocks.sorted(by: { $0.index < $1.index }) {
            let bundle = bundleByBlock[block.index]
            let closedLoop = closedLoopByBlock[block.index]
            let renderLock = renderLockByBlock[block.index]
            let modelFloor = modelFloorByBlock[block.index]
            let renderFit = renderFitByBlock[block.index]
            let textBoxFallback = bundle?.selectedTextBoxLite.fallbackUsed ?? true
            let bubbleFallback = bundle?.selectedBubbleInstanceLite.fallbackUsed ?? true
            let segmentFallback = bundle?.selectedSegmentMaskLite.fallbackUsed ?? true
            let textBoxSegmentLinkVerdict = bundle?.selectedTextBoxSegmentLinkVerdict ?? segmentByBlock[block.index]?.selectedSourceTextBoxLinkVerdict ?? "fallbackFinalBlockBBox"
            let textBoxSegmentLinkStatus = textBoxSegmentLinkPromotionStatus(textBoxSegmentLinkVerdict)
            let textBoxSegmentLinkBlocked = textBoxSegmentLinkStatus.hasPrefix("blocked")
            let modelBlocked = bundle?.modelFloorBlocked == true
                || modelFloor?.modelFloorLimited == true
                || block.failureCategory == "modelOutputFailure"
                || block.failureCategory == "translationLanguageQualityFailure"
            let renderLocked = bundle?.renderLocked == true
                || renderLock?.renderCollisionResolved == false
                || renderLock?.renderTextTruncated == true
                || renderFit?.fitVerdict == "renderLockedNoPromotion"
                || block.renderTextTruncated
            let readyForFullProbe = bundle?.readyForFullProbeShadowReview == true
                || closedLoop?.closedLoopRoute == "reviewPromisingCandidateInFullProbe"
            let stopLocalTuning = closedLoop?.closedLoopRoute == "stopLocalDetectorTuning"
                || closedLoop?.closedLoopRoute == "routeToModelFloor"
                || modelBlocked
                || renderLocked
            let textBoxesStatus = statusFor(
                fallbackUsed: textBoxFallback,
                needsRealArtifact: bundle?.needsRealTextBoxes ?? false,
                modelBlocked: false,
                renderLocked: false,
                readyForFullProbe: readyForFullProbe,
                stopLocalTuning: false,
                stable: bundle != nil
            )
            let effectiveTextBoxesStatus = textBoxSegmentLinkBlocked ? textBoxSegmentLinkStatus : textBoxesStatus
            let bubbleMaskStatus = statusFor(
                fallbackUsed: bubbleFallback,
                needsRealArtifact: bundle?.needsRealBubbleMask ?? false,
                modelBlocked: false,
                renderLocked: false,
                readyForFullProbe: false,
                stopLocalTuning: false,
                stable: bundle != nil
            )
            let segmentMaskStatus = statusFor(
                fallbackUsed: segmentFallback,
                needsRealArtifact: bundle?.needsRealSegmentMask ?? false,
                modelBlocked: false,
                renderLocked: false,
                readyForFullProbe: false,
                stopLocalTuning: false,
                stable: bundle != nil
            )
            let effectiveSegmentMaskStatus = textBoxSegmentLinkBlocked ? textBoxSegmentLinkStatus : segmentMaskStatus
            let ocrStatus = statusFor(
                fallbackUsed: block.failureCategory == "ocrInputSuspect",
                needsRealArtifact: false,
                modelBlocked: false,
                renderLocked: false,
                readyForFullProbe: readyForFullProbe,
                stopLocalTuning: stopLocalTuning && block.failureCategory != "ocrInputSuspect",
                stable: block.blockPassed || bundle != nil
            )
            let translationStatus = statusFor(
                fallbackUsed: false,
                needsRealArtifact: false,
                modelBlocked: modelBlocked,
                renderLocked: false,
                readyForFullProbe: false,
                stopLocalTuning: stopLocalTuning && modelBlocked,
                stable: block.blockPassed
            )
            let renderStatus = statusFor(
                fallbackUsed: false,
                needsRealArtifact: false,
                modelBlocked: false,
                renderLocked: renderLocked,
                readyForFullProbe: false,
                stopLocalTuning: stopLocalTuning && renderLocked,
                stable: renderLock != nil || renderFit != nil || block.safeLayoutRect != nil
            )
            let primaryBlockingArtifact: String
            if modelBlocked {
                primaryBlockingArtifact = "Translations"
            } else if renderLocked {
                primaryBlockingArtifact = "RenderedSprites"
            } else if textBoxSegmentLinkBlocked || bundle?.needsRealTextBoxes == true || textBoxFallback {
                primaryBlockingArtifact = "TextBoxes"
            } else if bundle?.needsRealBubbleMask == true || bubbleFallback {
                primaryBlockingArtifact = "BubbleMask"
            } else if bundle?.needsRealSegmentMask == true || segmentFallback {
                primaryBlockingArtifact = "SegmentMask"
            } else if block.failureCategory == "ocrInputSuspect" {
                primaryBlockingArtifact = "OcrText"
            } else if bundle?.artifactConsistencyVerdict == "nativeArtifactBundleLiteInconsistent" || bundle?.artifactConsistencyVerdict == "blockedByCrossArtifactConflict" {
                primaryBlockingArtifact = "CrossArtifactConsistency"
            } else {
                primaryBlockingArtifact = bundle?.primaryBlockingArtifact ?? "NoneReportOnlyStable"
            }
            let bottleneck: String
            if modelBlocked {
                bottleneck = block.failureCategory == "translationLanguageQualityFailure" ? "translationFailure" : "modelFloor"
            } else if renderLocked {
                bottleneck = "renderContainment"
            } else if textBoxSegmentLinkBlocked {
                bottleneck = "textBoxSegmentMaskLinkage"
            } else if primaryBlockingArtifact == "BubbleMask" {
                bottleneck = "bubbleAssignmentSplit"
            } else if primaryBlockingArtifact == "SegmentMask" {
                bottleneck = "segmentMaskCoverage"
            } else if primaryBlockingArtifact == "TextBoxes" || primaryBlockingArtifact == "OcrText" {
                bottleneck = "ocrAccuracy"
            } else if primaryBlockingArtifact == "CrossArtifactConsistency" {
                bottleneck = "crossArtifactConsistency"
            } else if externalArtifactReadinessReport?.readinessVerdict != "readyForShadowOCR" {
                bottleneck = "externalArtifactMissing"
            } else {
                bottleneck = "manualReview"
            }
            let eligibility: String
            if modelBlocked {
                eligibility = "blockedByModelFloor"
            } else if renderLocked {
                eligibility = "blockedByRenderLock"
            } else if textBoxSegmentLinkBlocked {
                eligibility = "blockedByProxyEvidence"
            } else if bundle?.needsRealTextBoxes == true || bundle?.needsRealBubbleMask == true || bundle?.needsRealSegmentMask == true {
                eligibility = "blockedByMissingRealArtifact"
            } else if textBoxFallback || bubbleFallback || segmentFallback {
                eligibility = "blockedByProxyEvidence"
            } else if readyForFullProbe {
                eligibility = "shadowReviewEligible"
            } else if stopLocalTuning {
                eligibility = "stopLocalTuning"
            } else if bundle != nil {
                eligibility = "reportOnlyStable"
            } else {
                eligibility = "manualReviewOnly"
            }
            let nextAction: String
            switch eligibility {
            case "blockedByModelFloor":
                nextAction = "stopGeometryTuningAndTrackModelFloor"
            case "blockedByRenderLock":
                nextAction = "inspectRenderLockBeforePromotion"
            case "blockedByMissingRealArtifact":
                nextAction = "collectRealKoharuArtifactsBeforePromotion"
            case "blockedByProxyEvidence":
                nextAction = textBoxSegmentLinkBlocked ? "auditTextBoxSegmentLinkageBeforePromotion" : "keepReportOnlyUntilProxyEvidenceImproves"
            case "shadowReviewEligible":
                nextAction = "runFullProbeShadowReviewBeforeAnyPromotion"
            case "stopLocalTuning":
                nextAction = "stopLocalTuningForThisBlock"
            case "reportOnlyStable":
                nextAction = "keepReportOnlyStableNoPromotion"
            default:
                nextAction = "manualReviewOnly"
            }
            var mustNotPromote = [
                "nativePromotionPreviewOnly",
                "proxyArtifactsAreNotRealKoharuArtifacts",
                "groundTruthNotAllowedForPromotionDecision",
                "noMainFlowMutationInV146"
            ]
            if textBoxFallback || bubbleFallback || segmentFallback { mustNotPromote.append("fallbackProxyEvidencePresent") }
            if textBoxSegmentLinkBlocked {
                mustNotPromote.append("weakTextBoxSegmentMaskLinkage")
                if textBoxSegmentLinkVerdict == "rejectedTextBoxCandidate"
                    || textBoxSegmentLinkVerdict == "sourceTextBoxBubbleMismatch"
                    || textBoxSegmentLinkVerdict == "fallbackFinalBlockBBox" {
                    mustNotPromote.append("rejectedOrFallbackTextBoxDrivesSegmentMask")
                }
            }
            if modelBlocked { mustNotPromote.append("currentModelFloorBlocksPromotion") }
            if renderLocked { mustNotPromote.append("renderLockBlocksPromotion") }
            if externalArtifactReadinessReport?.readinessVerdict != "readyForShadowOCR" { mustNotPromote.append("realExternalArtifactsMissing") }

            blockLedgers.append(
                MangaKoharuNativePromotionBlockLedger(
                    blockIndex: block.index,
                    bubbleID: block.bubbleID,
                    blockPassed: block.blockPassed,
                    failureCategory: block.failureCategory,
                    finalTextUsedForTranslation: block.finalTextUsedForTranslation,
                    bundleLiteVerdict: artifactBundleLiteReport?.bundleLiteVerdict ?? "notGenerated",
                    artifactConsistencyVerdict: bundle?.artifactConsistencyVerdict ?? "missingBundleLiteLedger",
                    textBoxesPromotionStatus: effectiveTextBoxesStatus,
                    bubbleMaskPromotionStatus: bubbleMaskStatus,
                    segmentMaskPromotionStatus: effectiveSegmentMaskStatus,
                    textBoxSegmentLinkVerdict: textBoxSegmentLinkVerdict,
                    textBoxSegmentLinkagePromotionStatus: textBoxSegmentLinkStatus,
                    ocrTextPromotionStatus: ocrStatus,
                    translationPromotionStatus: translationStatus,
                    renderPromotionStatus: renderStatus,
                    primaryBlockingArtifact: primaryBlockingArtifact,
                    probeBottleneckCategory: bottleneck,
                    promotionEligibility: eligibility,
                    nextAction: nextAction,
                    mustNotPromoteReasons: mustNotPromote,
                    decisionSignals: [
                        signal("promotionEligibility", eligibility, source: "koharuNativePromotionGateLiteReport"),
                        signal("primaryBlockingArtifact", primaryBlockingArtifact, source: "koharuNativePromotionGateLiteReport"),
                        signal("probeBottleneckCategory", bottleneck, source: "koharuNativePromotionGateLiteReport"),
                        signal("textBoxSegmentLinkVerdict", textBoxSegmentLinkVerdict, source: "koharuNativeArtifactBundleLiteReport"),
                        signal("textBoxSegmentLinkagePromotionStatus", textBoxSegmentLinkStatus, source: "koharuNativePromotionGateLiteReport"),
                        signal("bundleNextAction", bundle?.nextAction ?? "nil", source: "koharuNativeArtifactBundleLiteReport")
                    ],
                    evaluationSignals: [
                        signal("groundTruthMatch", block.groundTruthMatch, source: "blocks", decision: false, evaluation: true),
                        signal("bestGroundTruthType", block.bestGroundTruthType ?? "nil", source: "blocks", decision: false, evaluation: true),
                        signal("ocrGroundTruthSimilarity", formatted(block.ocrGroundTruthSimilarity), source: "blocks", decision: false, evaluation: true),
                        signal("cleanTextPassRate", cleanTextDiagnostic?.passRate.formatted(.number.precision(.fractionLength(4))) ?? "nil", source: "cleanTextDiagnostic", decision: false, evaluation: true)
                    ],
                    groundTruthUsedForDecision: false,
                    wouldChangeMainFlow: false,
                    diagnosticOnly: true
                )
            )

            let bundleComponents = [
                bundle?.selectedTextBoxLite,
                bundle?.selectedBubbleInstanceLite,
                bundle?.selectedSegmentMaskLite
            ].compactMap { $0 }
            for component in bundleComponents {
                let target = component.artifactStage
                let requiredFields: [String]
                let validator: [String]
                switch target {
                case "TextBoxes":
                    requiredFields = ["bbox", "confidence", "sourceDirection", "detector", "coordinateSpace=originalImageTopLeftPixels"]
                    validator = ["1.textboxes.json bbox must be in 576x1280 original image pixels", "confidence must be 0...1", "must not be generated from ground truth"]
                case "BubbleMask":
                    requiredFields = ["id", "bbox", "maskValue", "pixelCount", "coordinateSpace=originalImageTopLeftPixels"]
                    validator = ["1.bubbles.json id and bbox required", "instance source must be real detector output before active export"]
                default:
                    requiredFields = ["width", "height", "glyphPixelCount", "connectedComponentCount", "sourceSummary"]
                    validator = ["1.segment_mask.json width=576 height=1280", "summary must come from real SegmentMask before active export"]
                }
                candidatePreviews.append(
                    MangaKoharuNativeCandidateExportPreview(
                        previewID: "NPG.block\(block.index).\(target)",
                        blockIndex: block.index,
                        targetArtifactStage: target,
                        candidateSource: component.componentSource,
                        sourceReport: component.sourceReport,
                        bbox: component.bbox,
                        confidence: component.confidence,
                        requiredFieldsForFutureExport: requiredFields,
                        knownRisks: component.evidence + mustNotPromote,
                        validatorRequirements: validator,
                        canBeExportedNow: false,
                        reasonNotExported: "v1.46 is report-only and must not create or modify active test/koharu_artifacts",
                        groundTruthUsedForDecision: false,
                        wouldCreateActiveArtifact: false
                    )
                )
            }
        }

        let shadowReviewEligibleBlocks = uniqueSorted(blockLedgers.filter { $0.promotionEligibility == "shadowReviewEligible" }.map(\.blockIndex))
        let textBoxSegmentLinkageBlockedBlocks = uniqueSorted(blockLedgers.filter { $0.textBoxSegmentLinkagePromotionStatus.hasPrefix("blocked") }.map(\.blockIndex))
        let stopLocalTuningBlocks = uniqueSorted(blockLedgers.filter { $0.promotionEligibility == "stopLocalTuning" || $0.promotionEligibility == "blockedByModelFloor" || $0.promotionEligibility == "blockedByRenderLock" }.map(\.blockIndex))
        let needsRealTextBoxesBlocks = uniqueSorted(blockLedgers.filter { $0.textBoxesPromotionStatus == "blockedByMissingRealArtifact" || $0.primaryBlockingArtifact == "TextBoxes" }.map(\.blockIndex))
        let needsRealBubbleMaskBlocks = uniqueSorted(blockLedgers.filter { $0.bubbleMaskPromotionStatus == "blockedByMissingRealArtifact" || $0.primaryBlockingArtifact == "BubbleMask" }.map(\.blockIndex))
        let needsRealSegmentMaskBlocks = uniqueSorted(blockLedgers.filter { $0.segmentMaskPromotionStatus == "blockedByMissingRealArtifact" || $0.primaryBlockingArtifact == "SegmentMask" }.map(\.blockIndex))
        let modelFloorBlockedBlocks = uniqueSorted(blockLedgers.filter { $0.promotionEligibility == "blockedByModelFloor" }.map(\.blockIndex))
        let renderLockedBlocks = uniqueSorted(blockLedgers.filter { $0.promotionEligibility == "blockedByRenderLock" }.map(\.blockIndex))
        let manualReviewBlocks = uniqueSorted(blockLedgers.filter { $0.promotionEligibility == "manualReviewOnly" }.map(\.blockIndex))

        let stageGates = [
            stageGate(stage: "TextBoxes", artifact: "TextBoxes", reports: ["koharuNativeTextBoxDetectorLiteReport", "koharuNativeTextBoxDetectorLiteClosedLoopReport", "koharuNativeArtifactBundleLiteReport"], required: ["detector-lite candidate", "closed-loop route", "bundle selected TextBox"], ledgers: blockLedgers) { $0.textBoxesPromotionStatus },
            stageGate(stage: "BubbleMask", artifact: "BubbleMask", reports: ["koharuNativeBubbleMaskInstanceLiteReport", "koharuBubbleIndexShadowLedgerReport", "koharuDistanceFieldSafeAreaReport", "koharuBubbleAdjacencySeamReport", "koharuNativeArtifactBundleLiteReport"], required: ["instance-lite majority", "safe rect evidence", "bundle selected BubbleMask"], ledgers: blockLedgers) { $0.bubbleMaskPromotionStatus },
            stageGate(stage: "SegmentMask", artifact: "SegmentMask", reports: ["koharuNativeSegmentMaskRefinementLiteReport", "segmentMaskProxyCoverageScoreboardReport", "koharuNativeArtifactBundleLiteReport"], required: ["refinement-lite candidate", "glyph evidence", "bundle selected SegmentMask"], ledgers: blockLedgers) { $0.segmentMaskPromotionStatus },
            stageGate(stage: "OcrText", artifact: "OcrText", reports: ["blocks", "koharuNativeTextBoxDetectorLiteShadowOCRReport", "koharuNativeTextBoxDetectorLiteRefinementReport", "ocrCharacterDamageAuditReport"], required: ["final OCR text", "shadow OCR outcome", "OCR damage route"], ledgers: blockLedgers) { $0.ocrTextPromotionStatus },
            stageGate(stage: "Translations", artifact: "Translations", reports: ["blocks", "translationModelFloorComparisonReport", "cleanTextDiagnostic"], required: ["failureCategory", "translation decision trace", "clean text diagnostic"], ledgers: blockLedgers) { $0.translationPromotionStatus },
            stageGate(stage: "RenderedSprites", artifact: "RenderedSprites", reports: ["koharuRenderSpriteFitPlannerReport", "koharuRenderRegressionLockReport"], required: ["sprite fit verdict", "render lock ledger", "safe layout evidence"], ledgers: blockLedgers) { $0.renderPromotionStatus },
            stageGate(stage: "FinalRender", artifact: "FinalRender", reports: ["koharuRenderRegressionLockReport", "outputFiles"], required: ["core PNG present", "render collision status", "failure overlay retained"], ledgers: blockLedgers) { $0.renderPromotionStatus },
            stageGate(stage: "ExternalArtifacts", artifact: "TextBoxes/BubbleMask/SegmentMask", reports: ["externalArtifactReadinessReport", "koharuExternalArtifactRequestPacketReport"], required: ["1.manifest.json", "1.textboxes.json", "1.bubbles.json", "1.segment_mask.json"], ledgers: blockLedgers) { _ in
                externalArtifactReadinessReport?.readinessVerdict == "readyForShadowOCR" ? "reportOnlyStable" : "blockedByMissingRealArtifact"
            }
        ]

        let workItems = [
            MangaKoharuNativePromotionWorkItem(
                workItemID: "WI-koharu-native-promotion-gate-lite-shadow-review",
                title: "Run full-probe shadow review before any native promotion",
                targetArtifact: "OcrText/TextBoxes",
                status: shadowReviewEligibleBlocks.isEmpty ? "notRequired" : "openReportOnly",
                priority: shadowReviewEligibleBlocks.isEmpty ? "low" : "medium",
                affectedBlocks: shadowReviewEligibleBlocks,
                nextAction: "runFullProbeShadowReviewBeforeAnyPromotion",
                decisionSignals: [signal("shadowReviewEligibleBlocks", shadowReviewEligibleBlocks.map(String.init).joined(separator: ","), source: "koharuNativePromotionGateLiteReport")],
                evaluationSignals: [],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            ),
            MangaKoharuNativePromotionWorkItem(
                workItemID: "WI-koharu-native-promotion-gate-lite-textbox-segment-linkage",
                title: "Block promotion until TextBox to SegmentMask linkage is accepted",
                targetArtifact: "TextBoxes/SegmentMask",
                status: textBoxSegmentLinkageBlockedBlocks.isEmpty ? "notRequired" : "blockedByWeakTextBoxSegmentLinkage",
                priority: textBoxSegmentLinkageBlockedBlocks.isEmpty ? "low" : "high",
                affectedBlocks: textBoxSegmentLinkageBlockedBlocks,
                nextAction: "auditTextBoxSegmentLinkageBeforePromotion",
                decisionSignals: [
                    signal("textBoxSegmentLinkageBlockedBlocks", textBoxSegmentLinkageBlockedBlocks.map(String.init).joined(separator: ","), source: "koharuNativePromotionGateLiteReport"),
                    signal("textBoxSegmentLinkBreakdown", countBy(blockLedgers.map(\.textBoxSegmentLinkVerdict)).map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ","), source: "koharuNativePromotionGateLiteReport")
                ],
                evaluationSignals: [],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            ),
            MangaKoharuNativePromotionWorkItem(
                workItemID: "WI-koharu-native-promotion-gate-lite-real-artifacts",
                title: "Collect real Koharu artifacts before active candidate export",
                targetArtifact: "TextBoxes/BubbleMask/SegmentMask",
                status: needsRealTextBoxesBlocks.isEmpty && needsRealBubbleMaskBlocks.isEmpty && needsRealSegmentMaskBlocks.isEmpty ? "notRequired" : "blockedByMissingRealArtifact",
                priority: "high",
                affectedBlocks: uniqueSorted(needsRealTextBoxesBlocks + needsRealBubbleMaskBlocks + needsRealSegmentMaskBlocks),
                nextAction: "collectRealKoharuArtifactsBeforePromotion",
                decisionSignals: [
                    signal("needsRealTextBoxesBlocks", needsRealTextBoxesBlocks.map(String.init).joined(separator: ","), source: "koharuNativePromotionGateLiteReport"),
                    signal("needsRealBubbleMaskBlocks", needsRealBubbleMaskBlocks.map(String.init).joined(separator: ","), source: "koharuNativePromotionGateLiteReport"),
                    signal("needsRealSegmentMaskBlocks", needsRealSegmentMaskBlocks.map(String.init).joined(separator: ","), source: "koharuNativePromotionGateLiteReport")
                ],
                evaluationSignals: [],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            ),
            MangaKoharuNativePromotionWorkItem(
                workItemID: "WI-koharu-native-promotion-gate-lite-stop-model-render",
                title: "Stop geometry tuning where model floor or render lock dominates",
                targetArtifact: "Translations/RenderedSprites",
                status: modelFloorBlockedBlocks.isEmpty && renderLockedBlocks.isEmpty ? "notRequired" : "closedReportOnly",
                priority: "medium",
                affectedBlocks: uniqueSorted(modelFloorBlockedBlocks + renderLockedBlocks),
                nextAction: "stopGeometryTuningAndTrackModelOrRenderGate",
                decisionSignals: [
                    signal("modelFloorBlockedBlocks", modelFloorBlockedBlocks.map(String.init).joined(separator: ","), source: "koharuNativePromotionGateLiteReport"),
                    signal("renderLockedBlocks", renderLockedBlocks.map(String.init).joined(separator: ","), source: "koharuNativePromotionGateLiteReport")
                ],
                evaluationSignals: [],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            )
        ].filter { !$0.affectedBlocks.isEmpty || $0.workItemID == "WI-koharu-native-promotion-gate-lite-shadow-review" }

        let missingUpstream = [
            detectorLiteReport?.enabled == true ? nil : "koharuNativeTextBoxDetectorLiteReport",
            closedLoopReport?.enabled == true ? nil : "koharuNativeTextBoxDetectorLiteClosedLoopReport",
            bubbleInstanceLiteReport?.enabled == true ? nil : "koharuNativeBubbleMaskInstanceLiteReport",
            segmentRefinementLiteReport?.enabled == true ? nil : "koharuNativeSegmentMaskRefinementLiteReport",
            artifactBundleLiteReport?.enabled == true ? nil : "koharuNativeArtifactBundleLiteReport"
        ].compactMap { $0 }
        let gates = [
            gate("G-native-promotion-gate-lite-input-reports", "Input reports", "v1.39-v1.45", missingUpstream.isEmpty ? "passed" : "warning", "native-lite upstream reports are available or explicitly warned", allBlockIndexes, "promotion gate silently runs without upstream native-lite evidence", "restoreNativeLiteUpstreamReports", [signal("missingUpstreamReports", missingUpstream.joined(separator: ","), source: "koharuNativePromotionGateLiteReport")]),
            gate("G-native-promotion-gate-lite-report-only", "Report only", "report", "passed", "wouldChangeMainFlow=false", [], "promotion gate mutates OCR, translation, overlay, renderer, blockPassed, failureCategory, active artifacts, or currentBlockSource", "revertBehavioralChange", [signal("wouldChangeMainFlow", "false", source: "koharuNativePromotionGateLiteReport")]),
            gate("G-native-promotion-gate-lite-no-ground-truth-decision", "No ground truth decision", "report", "passed", "groundTruthUsedForDecision=false", allBlockIndexes, "ground truth decides promotion status, stage gate, preview, route, nextAction, or worklist", "moveGroundTruthToEvaluationSignalsOnly", [signal("groundTruthUsedForDecision", "false", source: "koharuNativePromotionGateLiteReport")]),
            gate("G-native-promotion-gate-lite-block-ledger-count", "Block ledger count", "blocks", blockLedgers.count == blocks.count ? "passed" : "warning", "blockLedgerCount==totalBlocksDetected", allBlockIndexes, "some final blocks lack promotion ledger rows", "restorePromotionLedgerCoverage", [signal("blockLedgerCount", String(blockLedgers.count), source: "koharuNativePromotionGateLiteReport")]),
            gate("G-native-promotion-gate-lite-stage-gates", "Stage gates", "KoharuArtifacts", stageGates.count >= 8 ? "passed" : "warning", "stageGateCount>=8", allBlockIndexes, "promotion report does not cover canonical TextBoxes/BubbleMask/SegmentMask/OcrText/Translation/Render/External stages", "restoreCanonicalStageGates", [signal("stageGateCount", String(stageGates.count), source: "koharuNativePromotionGateLiteReport")]),
            gate("G-native-promotion-gate-lite-textbox-segment-linkage", "TextBox SegmentMask linkage", "TextBoxes->SegmentMask", textBoxSegmentLinkageBlockedBlocks.isEmpty ? "passed" : "warning", "promotion must not treat SegmentMask as ready when selected source TextBox linkage is fallback, weak, rejected, or wrong-bubble", textBoxSegmentLinkageBlockedBlocks, "promotion treats SegmentMask as ready while its source TextBox linkage is rejected, fallback, wrong-bubble, or weak", "auditTextBoxSegmentLinkageBeforePromotion", [signal("textBoxSegmentLinkBreakdown", countBy(blockLedgers.map(\.textBoxSegmentLinkVerdict)).map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ","), source: "koharuNativePromotionGateLiteReport")]),
            gate("G-native-promotion-gate-lite-preview-only", "Preview only", "candidateExportPreview", candidatePreviews.allSatisfy { !$0.canBeExportedNow && !$0.wouldCreateActiveArtifact } ? "passed" : "blocked", "candidate previews never create active artifacts", candidatePreviews.map(\.blockIndex), "candidate export preview creates or modifies active test/koharu_artifacts", "keepPreviewOnly", [signal("candidateExportPreviewCount", String(candidatePreviews.count), source: "koharuNativePromotionGateLiteReport")]),
            gate("G-native-promotion-gate-lite-proxy-boundary", "Proxy boundary", "proxyBoundary", "passed", "proxyNotRealKoharu* flags are true", allBlockIndexes, "native-lite proxy is promoted as real Koharu TextBoxes/BubbleMask/SegmentMask/OCR/Renderer", "collectRealArtifactsBeforePromotion", [signal("proxyNotRealKoharuTextBoxes", "true", source: "koharuNativePromotionGateLiteReport"), signal("proxyNotRealKoharuBubbleMask", "true", source: "koharuNativePromotionGateLiteReport"), signal("proxyNotRealKoharuSegmentMask", "true", source: "koharuNativePromotionGateLiteReport")]),
            gate("G-native-promotion-gate-lite-no-ocr-llm-png", "No OCR LLM PNG", "budget", "passed", "no OCR/LLM calls and no PNG output", [], "promotion gate adds OCR, LLM, prompt/model, PNG, or renderer work", "removeHeavyWorkFromPromotionGate", [signal("ocrCalls", "0", source: "koharuNativePromotionGateLiteReport"), signal("llmCalls", "0", source: "koharuNativePromotionGateLiteReport"), signal("pngOutputs", "0", source: "koharuNativePromotionGateLiteReport")]),
            gate("G-native-promotion-gate-lite-external-boundary", "External artifact boundary", "ExternalArtifacts", "passed", "externalArtifactsRequiredForThisReport=false", [], "promotion gate creates, copies, edits, or requires active test/koharu_artifacts", "doNotCreateActiveArtifacts", [signal("externalArtifactsRequiredForThisReport", "false", source: "koharuNativePromotionGateLiteReport"), signal("readinessVerdict", externalArtifactReadinessReport?.readinessVerdict ?? "manifestMissing", source: "externalArtifactReadinessReport")])
        ]

        let verdict: String
        if !modelFloorBlockedBlocks.isEmpty {
            verdict = "blockedByModelFloor"
        } else if !renderLockedBlocks.isEmpty {
            verdict = "blockedByRenderLock"
        } else if !needsRealTextBoxesBlocks.isEmpty || !needsRealBubbleMaskBlocks.isEmpty || !needsRealSegmentMaskBlocks.isEmpty {
            verdict = "blockedByMissingRealArtifact"
        } else if blockLedgers.contains(where: { $0.promotionEligibility == "blockedByProxyEvidence" }) {
            verdict = "blockedByProxyEvidence"
        } else if !shadowReviewEligibleBlocks.isEmpty {
            verdict = "shadowReviewEligible"
        } else if !stopLocalTuningBlocks.isEmpty {
            verdict = "stopLocalTuning"
        } else if !manualReviewBlocks.isEmpty {
            verdict = "manualReviewOnly"
        } else {
            verdict = "reportOnlyStable"
        }

        return MangaKoharuNativePromotionGateLiteReport(
            enabled: true,
            source: "AITRANSProbe",
            referencePipeline: "Koharu",
            referenceConcept: "NativePromotionGateLite.ProbeDrivenArtifactReadiness",
            referenceWorkItemID: "WI-koharu-native-promotion-gate-lite",
            evaluatedBlockCount: blocks.count,
            blockLedgerCount: blockLedgers.count,
            stageGateCount: stageGates.count,
            candidateExportPreviewCount: candidatePreviews.count,
            workItemCount: workItems.count,
            gateCount: gates.count,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            promotionGateLite: true,
            nativePromotionPreviewOnly: true,
            proxyNotRealKoharuTextBoxes: true,
            proxyNotRealKoharuBubbleMask: true,
            proxyNotRealKoharuSegmentMask: true,
            proxyNotRealKoharuOCR: true,
            proxyNotRealKoharuRenderer: true,
            externalArtifactsRequiredForThisReport: false,
            promotionVerdict: verdict,
            stageReadinessBreakdown: countBy(stageGates.map(\.stageReadiness)),
            promotionEligibilityBreakdown: countBy(blockLedgers.map(\.promotionEligibility)),
            primaryBlockingArtifactBreakdown: countBy(blockLedgers.map(\.primaryBlockingArtifact)),
            probeBottleneckBreakdown: countBy(blockLedgers.map(\.probeBottleneckCategory)),
            textBoxSegmentLinkBreakdown: countBy(blockLedgers.map(\.textBoxSegmentLinkVerdict)),
            nextActionBreakdown: countBy(blockLedgers.map(\.nextAction)),
            shadowReviewEligibleBlocks: shadowReviewEligibleBlocks,
            textBoxSegmentLinkageBlockedBlocks: textBoxSegmentLinkageBlockedBlocks,
            stopLocalTuningBlocks: stopLocalTuningBlocks,
            needsRealTextBoxesBlocks: needsRealTextBoxesBlocks,
            needsRealBubbleMaskBlocks: needsRealBubbleMaskBlocks,
            needsRealSegmentMaskBlocks: needsRealSegmentMaskBlocks,
            modelFloorBlockedBlocks: modelFloorBlockedBlocks,
            renderLockedBlocks: renderLockedBlocks,
            manualReviewBlocks: manualReviewBlocks,
            blockLedgers: blockLedgers,
            stageGates: stageGates,
            candidateExportPreviews: candidatePreviews,
            workItems: workItems,
            gateLedger: gates,
            notes: [
                "koharuNativePromotionGateLiteReport consumes AITRANS probe runtime evidence from final blocks, diagnostics, v1.39-v1.45 native-lite reports, render lock, translation floor, clean text, and external readiness.",
                "It defines report-only promotion gates and candidate export previews; it never creates active test/koharu_artifacts or promotes proxy evidence as real Koharu artifacts.",
                "Ground truth appears only in evaluationSignals and never drives promotionEligibility, stageReadiness, candidateExportPreviews, nextAction, workItems, or gate status.",
                "No OCR, LLM, PNG, prompt, model, renderer, safeLayoutRect, glyphMaskFillRects, finalTextUsedForTranslation, blockPassed, failureCategory, currentBlockSource, or textRegionCropReport.adoptedCount behavior changes are made by v1.46."
            ]
        )
    }

    private static func makeKoharuNativeArtifactContractDryRunReport(
        blocks: [MangaOverlayProbeBlock],
        promotionGateLiteReport: MangaKoharuNativePromotionGateLiteReport?,
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?
    ) -> MangaKoharuNativeArtifactContractDryRunReport {
        func uniqueSorted(_ values: [Int]) -> [Int] { Array(Set(values)).sorted() }
        func countBy(_ values: [String]) -> [String: Int] {
            values.reduce(into: [:]) { partial, value in partial[value, default: 0] += 1 }
        }
        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaKoharuNativeArtifactContractDryRunSignal {
            MangaKoharuNativeArtifactContractDryRunSignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }
        func gate(
            _ id: String,
            _ name: String,
            _ scope: String,
            _ status: String,
            _ threshold: String,
            _ affected: [Int],
            _ failure: String,
            _ action: String,
            _ signals: [MangaKoharuNativeArtifactContractDryRunSignal]
        ) -> MangaKoharuNativeArtifactContractDryRunGate {
            MangaKoharuNativeArtifactContractDryRunGate(
                gateID: id,
                gateName: name,
                scope: scope,
                status: status,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                failureMeans: failure,
                recommendedAction: action,
                decisionSignals: signals,
                groundTruthUsedForDecision: false
            )
        }

        let forbiddenActiveSources = [
            "contract examples",
            "Vision OCR blocks",
            "pre-crop plan",
            "line plan",
            "BubbleMask proxy",
            "SegmentMask proxy",
            "ground truth",
            "handwritten ideal boxes",
            "native-lite proxy"
        ]
        let requiredByStage: [String: [String]] = [
            "TextBoxes": ["id", "bbox", "confidence", "sourceDirection", "detector", "coordinateSpace=originalImageTopLeftPixels"],
            "BubbleMask": ["id", "bbox", "maskValue", "pixelCount", "coordinateSpace=originalImageTopLeftPixels"],
            "SegmentMask": ["width", "height", "glyphPixelCount", "connectedComponentCount", "coordinateSpace=originalImageTopLeftPixels"]
        ]
        let destinationByStage = [
            "TextBoxes": "test/koharu_artifacts/1.textboxes.json",
            "BubbleMask": "test/koharu_artifacts/1.bubbles.json",
            "SegmentMask": "test/koharu_artifacts/1.segment_mask.json"
        ]
        func missingFields(for preview: MangaKoharuNativeCandidateExportPreview) -> [String] {
            let required = requiredByStage[preview.targetArtifactStage] ?? preview.requiredFieldsForFutureExport
            return required.filter { field in
                switch field {
                case "id":
                    return preview.previewID.isEmpty
                case "bbox":
                    return preview.bbox == nil
                case "confidence":
                    return preview.confidence == nil
                case "sourceDirection", "detector", "maskValue", "pixelCount", "width", "height", "glyphPixelCount", "connectedComponentCount":
                    return true
                case "coordinateSpace=originalImageTopLeftPixels":
                    return false
                default:
                    return !preview.requiredFieldsForFutureExport.contains(field)
                }
            }
        }
        func forbiddenReasons(for preview: MangaKoharuNativeCandidateExportPreview) -> [String] {
            var reasons: [String] = []
            let joinedSource = "\(preview.candidateSource) \(preview.sourceReport)".lowercased()
            if joinedSource.contains("fallback") || joinedSource.contains("blocks") || joinedSource.contains("finalbbox") {
                reasons.append("Vision OCR blocks")
            }
            if joinedSource.contains("precrop") {
                reasons.append("pre-crop plan")
            }
            if joinedSource.contains("line") {
                reasons.append("line plan")
            }
            if preview.targetArtifactStage == "BubbleMask" || joinedSource.contains("bubble") {
                reasons.append("BubbleMask proxy")
            }
            if preview.targetArtifactStage == "SegmentMask" || joinedSource.contains("segment") || joinedSource.contains("glyph") {
                reasons.append("SegmentMask proxy")
            }
            if joinedSource.contains("groundtruth") {
                reasons.append("ground truth")
            }
            if joinedSource.contains("nativelite") || joinedSource.contains("native") {
                reasons.append("native-lite proxy")
            }
            return Array(Set(reasons)).sorted()
        }

        let previews = (promotionGateLiteReport?.candidateExportPreviews ?? []).map { preview in
            let missing = missingFields(for: preview)
            let forbidden = forbiddenReasons(for: preview)
            return MangaKoharuNativeArtifactContractDryRunPreview(
                previewID: preview.previewID,
                blockIndex: preview.blockIndex,
                targetArtifactStage: preview.targetArtifactStage,
                candidateSource: preview.candidateSource,
                sourceReport: preview.sourceReport,
                destinationPath: destinationByStage[preview.targetArtifactStage] ?? "test/koharu_artifacts/unknown.json",
                bbox: preview.bbox,
                confidence: preview.confidence,
                requiredFields: requiredByStage[preview.targetArtifactStage] ?? preview.requiredFieldsForFutureExport,
                missingRequiredFields: missing,
                forbiddenSourceReasons: forbidden,
                canSatisfyContractDryRun: missing.isEmpty && forbidden.isEmpty,
                activeExportAllowed: false,
                reasonNotExported: "dry-run only; native-lite/proxy previews must not create or modify active test/koharu_artifacts",
                decisionSignals: [
                    signal("targetArtifactStage", preview.targetArtifactStage, source: "koharuNativePromotionGateLiteReport"),
                    signal("candidateSource", preview.candidateSource, source: preview.sourceReport),
                    signal("missingRequiredFields", missing.joined(separator: ","), source: "koharuNativeArtifactContractDryRunReport"),
                    signal("forbiddenSourceReasons", forbidden.joined(separator: ","), source: "koharuNativeArtifactContractDryRunReport")
                ],
                groundTruthUsedForDecision: false,
                wouldCreateActiveArtifact: false
            )
        }
        let previewsByStage = Dictionary(grouping: previews, by: \.targetArtifactStage)
        let appSideArtifactIdentityReceipt = externalArtifactReadinessReport?.artifactIdentityReceipt
        let identityReceiptByKind = Dictionary(
            uniqueKeysWithValues: (appSideArtifactIdentityReceipt?.files ?? []).map { ($0.artifactKind.lowercased(), $0) }
        )
        let appSideArtifactIdentityVerdict = appSideArtifactIdentityReceipt?.identityVerdict ?? "notRecorded"
        let appSideArtifactIdentityFilesPresent = appSideArtifactIdentityReceipt?.allRequiredFilesPresent ?? false
        let appSideArtifactIdentityHashesPresent = appSideArtifactIdentityReceipt?.allRequiredFilesHaveSHA256 ?? false
        let appSideSourceImageSHA256Matches = appSideArtifactIdentityReceipt?.sourceImageSHA256Matches ?? false
        let appSideArtifactIdentityReady = appSideArtifactIdentityVerdict == "activeArtifactIdentityRecorded"
            && appSideArtifactIdentityFilesPresent
            && appSideArtifactIdentityHashesPresent
            && appSideSourceImageSHA256Matches

        func file(
            path: String,
            kind: String,
            found: Bool,
            fields: [String]
        ) -> MangaKoharuNativeArtifactContractDryRunFile {
            let stagePreviews = previewsByStage[kind] ?? []
            let missing = Array(Set(stagePreviews.flatMap(\.missingRequiredFields))).sorted()
            let forbiddenCount = stagePreviews.reduce(0) { $0 + $1.forbiddenSourceReasons.count }
            let identityKind = kind == "manifest" ? "manifest" : kind.lowercased()
            let identityReceipt = identityReceiptByKind[identityKind]
            let identityStatus: String
            if !found {
                identityStatus = "notApplicableMissingActiveFile"
            } else if identityReceipt == nil {
                identityStatus = "identityReceiptMissing"
            } else if identityReceipt?.exists != true {
                identityStatus = "identityReceiptFileMissing"
            } else if identityReceipt?.sha256?.isEmpty != false {
                identityStatus = "identityReceiptHashMissing"
            } else {
                identityStatus = "identityReceiptRecorded"
            }
            let status: String
            if found {
                status = "activeFileFound"
            } else if stagePreviews.isEmpty {
                status = "missingActiveFileNoDryRunPreview"
            } else if missing.isEmpty && forbiddenCount == 0 {
                status = "dryRunPreviewContractReadyButExportBlocked"
            } else {
                status = "dryRunPreviewBlocked"
            }
            return MangaKoharuNativeArtifactContractDryRunFile(
                path: path,
                artifactKind: kind,
                required: true,
                activeFileFound: found,
                fileSizeBytes: identityReceipt?.sizeBytes,
                sha256: identityReceipt?.sha256,
                identityStatus: identityStatus,
                dryRunPreviewCount: stagePreviews.count,
                status: status,
                requiredFields: fields,
                missingRequiredFields: missing,
                forbiddenSourceCount: forbiddenCount,
                nextAction: found ? "validateActiveArtifactWithContract" : "collectRealKoharu\(kind)Artifact",
                decisionSignals: [
                    signal("activeFileFound", String(found), source: "externalArtifactReadinessReport"),
                    signal("identityStatus", identityStatus, source: "externalArtifactReadinessReport.artifactIdentityReceipt"),
                    signal("sha256Present", String(identityReceipt?.sha256?.isEmpty == false), source: "externalArtifactReadinessReport.artifactIdentityReceipt"),
                    signal("dryRunPreviewCount", String(stagePreviews.count), source: "koharuNativeArtifactContractDryRunReport"),
                    signal("missingRequiredFields", missing.joined(separator: ","), source: "koharuNativeArtifactContractDryRunReport"),
                    signal("forbiddenSourceCount", String(forbiddenCount), source: "koharuNativeArtifactContractDryRunReport")
                ],
                groundTruthUsedForDecision: false,
                wouldCreateActiveArtifact: false
            )
        }
        let manifestFound = externalArtifactReadinessReport?.manifestFound ?? false
        let requiredFiles = [
            file(path: "test/koharu_artifacts/1.manifest.json", kind: "manifest", found: manifestFound, fields: ["schemaVersion", "sourceImage=test/1.png", "sourceImageSHA256=\(externalArtifactReadinessReport?.coordinateValidation.expectedSourceImageSHA256 ?? "unknown")", "coordinateSpace=originalImageTopLeftPixels", "contractExampleOnly=false"]),
            file(path: "test/koharu_artifacts/1.textboxes.json", kind: "TextBoxes", found: externalArtifactReadinessReport?.textBoxesFound ?? false, fields: requiredByStage["TextBoxes"] ?? []),
            file(path: "test/koharu_artifacts/1.bubbles.json", kind: "BubbleMask", found: externalArtifactReadinessReport?.bubbleMaskFound ?? false, fields: requiredByStage["BubbleMask"] ?? []),
            file(path: "test/koharu_artifacts/1.segment_mask.json", kind: "SegmentMask", found: externalArtifactReadinessReport?.segmentMaskFound ?? false, fields: requiredByStage["SegmentMask"] ?? [])
        ]
        let readyPreviewIDs = previews.filter(\.canSatisfyContractDryRun).map(\.previewID).sorted()
        let blockedPreviewIDs = previews.filter { !$0.canSatisfyContractDryRun }.map(\.previewID).sorted()
        let allBlockIndexes = blocks.map(\.index)
        let activeReady = externalArtifactReadinessReport?.readinessVerdict == "readyForShadowOCR"
            && externalArtifactReadinessReport?.externalTextBoxesShadowOCRAllowed == true
        let gates = [
            gate("G-native-artifact-contract-dry-run-report-only", "Report only", "report", "passed", "wouldChangeMainFlow=false", [], "dry-run mutates OCR, translation, renderer, output files, active artifacts, or currentBlockSource", "revertBehavioralChange", [signal("wouldChangeMainFlow", "false", source: "koharuNativeArtifactContractDryRunReport")]),
            gate("G-native-artifact-contract-dry-run-no-ground-truth", "No ground truth decision", "policy", "passed", "groundTruthUsedForDecision=false", allBlockIndexes, "ground truth selects export previews, file readiness, verdict, or next action", "moveGroundTruthToEvaluationSignalsOnly", [signal("groundTruthUsedForDecision", "false", source: "koharuNativeArtifactContractDryRunReport")]),
            gate("G-native-artifact-contract-dry-run-required-files", "Required files", "test/koharu_artifacts", requiredFiles.allSatisfy(\.activeFileFound) ? "passed" : "blocked", "manifest/TextBoxes/BubbleMask/SegmentMask active files are present", allBlockIndexes, "active four-file artifact contract is incomplete", "collectRealKoharuArtifactFourPack", [signal("missingArtifacts", (externalArtifactReadinessReport?.missingArtifacts ?? ["manifest", "TextBoxes", "BubbleMask", "SegmentMask"]).joined(separator: ","), source: "externalArtifactReadinessReport")]),
            gate("G-native-artifact-contract-dry-run-app-side-identity", "App-side identity receipt", "ExternalArtifacts", appSideArtifactIdentityReady ? "passed" : "blocked", "App runtime records source image and active four-file size/SHA256 identity, and manifest sourceImageSHA256 matches the runtime source image SHA256", allBlockIndexes, "CI validator identity cannot be matched to the files actually visible inside the App probe runtime", "compareAppReceiptWithCIManifestIdentity", [signal("appSideArtifactIdentityVerdict", appSideArtifactIdentityVerdict, source: "externalArtifactReadinessReport.artifactIdentityReceipt"), signal("appSideArtifactIdentityFilesPresent", String(appSideArtifactIdentityFilesPresent), source: "externalArtifactReadinessReport.artifactIdentityReceipt"), signal("appSideArtifactIdentityHashesPresent", String(appSideArtifactIdentityHashesPresent), source: "externalArtifactReadinessReport.artifactIdentityReceipt"), signal("sourceImageSHA256Matches", String(appSideSourceImageSHA256Matches), source: "externalArtifactReadinessReport.artifactIdentityReceipt")]),
            gate("G-native-artifact-contract-dry-run-preview-blocked", "Preview export blocked", "candidateExportPreview", previews.allSatisfy { !$0.activeExportAllowed && !$0.wouldCreateActiveArtifact } ? "passed" : "blocked", "native-lite previews never create active artifacts", previews.map(\.blockIndex), "candidate preview writes test/koharu_artifacts or marks proxy exportable", "keepDryRunOnly", [signal("dryRunPreviewCount", String(previews.count), source: "koharuNativeArtifactContractDryRunReport")]),
            gate("G-native-artifact-contract-dry-run-validator-command", "Validator command", "validator", "passed", "validator commands are explicit and non-mutating", [], "Agent C cannot reproduce artifact contract readiness", "keepValidatorCommandsInReport", [signal("validatorCommands", "2", source: "koharuNativeArtifactContractDryRunReport")]),
            gate("G-native-artifact-contract-dry-run-active-readiness", "Active readiness", "ExternalArtifacts", activeReady ? "passed" : "blocked", "readinessVerdict=readyForShadowOCR and externalTextBoxesShadowOCRAllowed=true", allBlockIndexes, "Swift readiness and validator contract are not ready for shadow OCR", "collectAndValidateRealArtifacts", [signal("readinessVerdict", externalArtifactReadinessReport?.readinessVerdict ?? "manifestMissing", source: "externalArtifactReadinessReport")])
        ]
        let verdict: String
        if !activeReady {
            verdict = "blockedByMissingActiveArtifacts"
        } else if !appSideArtifactIdentityReady {
            verdict = "blockedByMissingAppSideArtifactIdentity"
        } else if requiredFiles.allSatisfy(\.activeFileFound) {
            verdict = "activeArtifactsReadyForShadowOCR"
        } else if !blockedPreviewIDs.isEmpty {
            verdict = "dryRunPreviewsBlockedByContract"
        } else {
            verdict = "manualReviewOnly"
        }

        return MangaKoharuNativeArtifactContractDryRunReport(
            enabled: true,
            source: "AITRANSProbe",
            referencePipeline: "Koharu",
            referenceConcept: "NativeArtifactContractDryRun.FourFileReadiness",
            referenceWorkItemID: "WI-koharu-native-artifact-contract-dry-run",
            sourceImage: "test/1.png",
            coordinateSpace: "originalImageTopLeftPixels",
            imageWidth: externalArtifactReadinessReport?.coordinateValidation.imageWidth ?? 576,
            imageHeight: externalArtifactReadinessReport?.coordinateValidation.imageHeight ?? 1280,
            activeInputDirectory: "test/koharu_artifacts",
            examplesDirectory: "md/koharu研究/artifact_contract/examples",
            evaluatedBlockCount: blocks.count,
            requiredFileCount: requiredFiles.count,
            dryRunPreviewCount: previews.count,
            contractGateCount: gates.count,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            dryRunOnly: true,
            activeExportAllowed: false,
            externalArtifactsRequiredForThisReport: false,
            appSideArtifactIdentityVerdict: appSideArtifactIdentityVerdict,
            appSideArtifactIdentityFilesPresent: appSideArtifactIdentityFilesPresent,
            appSideArtifactIdentityHashesPresent: appSideArtifactIdentityHashesPresent,
            contractDryRunVerdict: verdict,
            readinessVerdict: externalArtifactReadinessReport?.readinessVerdict ?? "manifestMissing",
            activeArtifactsDirectory: externalArtifactReadinessReport?.activeArtifactsDirectory ?? false,
            contractExampleOnly: externalArtifactReadinessReport?.contractExampleOnly ?? false,
            externalTextBoxesShadowOCRAllowed: externalArtifactReadinessReport?.externalTextBoxesShadowOCRAllowed ?? false,
            requiredFileStatusBreakdown: countBy(requiredFiles.map(\.status)),
            targetArtifactBreakdown: countBy(previews.map(\.targetArtifactStage)),
            missingRequiredFieldBreakdown: countBy(previews.flatMap(\.missingRequiredFields)),
            forbiddenSourceBreakdown: countBy(previews.flatMap(\.forbiddenSourceReasons)),
            nextActionBreakdown: countBy(requiredFiles.map(\.nextAction) + ["collectAndValidateRealArtifacts"]),
            contractReadyDryRunPreviewIDs: readyPreviewIDs,
            blockedPreviewIDs: blockedPreviewIDs,
            requiredFiles: requiredFiles,
            previews: previews,
            gateLedger: gates,
            validatorCommands: [
                "python3 scripts/validate-koharu-artifacts.py --root test/koharu_artifacts --print-required-files",
                "python3 scripts/validate-koharu-artifacts.py --root test/koharu_artifacts --allow-missing"
            ],
            forbiddenActiveSources: forbiddenActiveSources,
            notes: [
                "koharuNativeArtifactContractDryRunReport maps v1.46 candidate export previews onto the four-file Koharu artifact contract without writing files.",
                "App-side artifact identity receipt is included so Agent C can compare runtime-visible source image and active artifact SHA256 values with ci-artifact-manifest.koharuArtifactValidationIdentitySummary.",
                "Active export remains false because native-lite/proxy previews are not real Koharu detector output.",
                "The report is intended to make the next real-artifact handoff mechanically verifiable by Agent C and GitHub Actions artifacts.",
                "No OCR, LLM, PNG, prompt/model, renderer, safeLayoutRect, glyphMaskFillRects, finalTextUsedForTranslation, blockPassed, failureCategory, currentBlockSource, or active test/koharu_artifacts behavior changes are made."
            ]
        )
    }

    private struct ExternalTextBoxShadowSelection {
        var textBox: MangaOverlayExternalTextBox
        var bubbleInstance: MangaOverlayExternalBubbleInstance?
        var iou: Double
        var centerContained: Bool
        var areaRatio: Double
        var bubbleAlignmentMatched: Bool
        var spatialGeometryVerdict: String
        var bubbleAlignmentVerdict: String
        var assignmentGeometryTrusted: Bool
        var riskFlags: [String]
        var rejectionReasons: [String]
        var score: Double
    }

    private struct ExternalTextBoxShadowMatching {
        var assignmentsByBlockIndex: [Int: ExternalTextBoxShadowSelection]
        var eligibleBlockIndexesByTextBoxID: [String: [Int]]
        var duplicateAssignmentLedgers: [MangaOverlayExternalTextBoxDuplicateAssignmentLedger]
    }

    private static func stableOneToOneExternalTextBoxShadowMatching(
        blocks: [MangaOverlayProbeBlock],
        textBoxes: [MangaOverlayExternalTextBox],
        bubbleInstances: [MangaOverlayExternalBubbleInstance],
        imageWidth: Int,
        imageHeight: Int
    ) -> ExternalTextBoxShadowMatching {
        let orderedBlocks = blocks.sorted { $0.index < $1.index }
        let eligibleByBlock = Dictionary(uniqueKeysWithValues: orderedBlocks.map { block in
            (
                block.index,
                eligibleExternalTextBoxShadowCandidates(
                    for: block,
                    textBoxes: textBoxes,
                    bubbleInstances: bubbleInstances,
                    imageWidth: imageWidth,
                    imageHeight: imageHeight
                )
            )
        })
        var eligibleBlockIndexesByTextBoxID: [String: [Int]] = [:]
        for block in orderedBlocks {
            for selection in eligibleByBlock[block.index] ?? [] {
                eligibleBlockIndexesByTextBoxID[selection.textBox.id, default: []].append(block.index)
            }
        }

        let preferencesByBlockIndex = eligibleByBlock.mapValues { selections in
            selections.map(\.textBox.id)
        }
        let assignedTextBoxIDByBlockIndex = MangaOverlayStableOneToOneTextBoxMatcher.assignments(
            preferencesByBlockIndex: preferencesByBlockIndex
        )
        let assignmentsByBlockIndex: [Int: ExternalTextBoxShadowSelection] = Dictionary(
            uniqueKeysWithValues: assignedTextBoxIDByBlockIndex.compactMap { blockIndex, textBoxID in
            guard let selection = eligibleByBlock[blockIndex]?.first(where: { $0.textBox.id == textBoxID }) else {
                return nil
            }
            return (blockIndex, selection)
            }
        )
        let ownerByTextBoxID = Dictionary(uniqueKeysWithValues: assignedTextBoxIDByBlockIndex.map { blockIndex, textBoxID in
            (textBoxID, blockIndex)
        })

        let ledgers = eligibleBlockIndexesByTextBoxID.compactMap { textBoxID, rawBlockIndexes -> MangaOverlayExternalTextBoxDuplicateAssignmentLedger? in
            let blockIndexes = Array(Set(rawBlockIndexes)).sorted()
            guard blockIndexes.count > 1 else { return nil }
            let selectedBlockIndex = ownerByTextBoxID[textBoxID]
            return MangaOverlayExternalTextBoxDuplicateAssignmentLedger(
                textBoxID: textBoxID,
                competingBlockIndexes: blockIndexes,
                selectedBlockIndex: selectedBlockIndex,
                rejectedBlockIndexes: blockIndexes.filter { $0 != selectedBlockIndex },
                resolutionVerdict: selectedBlockIndex == nil ? "unassignedAfterOneToOneMatching" : "resolvedByStableOneToOneMatching",
                decisionSignals: [
                    "maximumCardinalityAugmentingPath=true",
                    "blockOrder=ascendingBlockIndex",
                    "edgeOrder=centerContainment,iou,confidence,score,textBoxID"
                ]
            )
        }
        .sorted { $0.textBoxID < $1.textBoxID }

        return ExternalTextBoxShadowMatching(
            assignmentsByBlockIndex: assignmentsByBlockIndex,
            eligibleBlockIndexesByTextBoxID: eligibleBlockIndexesByTextBoxID,
            duplicateAssignmentLedgers: ledgers
        )
    }

    private static func eligibleExternalTextBoxShadowCandidates(
        for block: MangaOverlayProbeBlock,
        textBoxes: [MangaOverlayExternalTextBox],
        bubbleInstances: [MangaOverlayExternalBubbleInstance],
        imageWidth: Int,
        imageHeight: Int
    ) -> [ExternalTextBoxShadowSelection] {
        let imageBounds = CGRect(x: 0, y: 0, width: CGFloat(imageWidth), height: CGFloat(imageHeight))
        let blockRect = rect(from: block.bbox)
        let blockArea = max(blockRect.width * blockRect.height, 1)
        let blockCenter = CGPoint(x: blockRect.midX, y: blockRect.midY)
        let blockBubble = bestExternalBubble(for: blockRect, bubbleInstances: bubbleInstances)

        return textBoxes.compactMap { textBox -> ExternalTextBoxShadowSelection? in
            let textBoxRect = rect(from: textBox.bbox)
            var rejectionReasons: [String] = []
            var riskFlags: [String] = []
            guard textBoxRect.width >= 2,
                  textBoxRect.height >= 2,
                  textBoxRect.minX >= imageBounds.minX,
                  textBoxRect.minY >= imageBounds.minY,
                  textBoxRect.maxX <= imageBounds.maxX,
                  textBoxRect.maxY <= imageBounds.maxY else {
                return nil
            }
            let iou = rectIoU(blockRect, textBoxRect)
            let centerContained = textBoxRect.contains(blockCenter)
            if iou <= 0.01 && !centerContained {
                rejectionReasons.append("noBlockOverlapOrCenterContainment")
            }
            let areaRatio = (textBoxRect.width * textBoxRect.height) / blockArea
            if areaRatio > 5.0 {
                rejectionReasons.append("textBoxAreaTooLarge")
            }
            if areaRatio < 0.04 {
                rejectionReasons.append("textBoxAreaTooSmall")
            }
            let textBoxBubble = bestExternalBubble(for: textBoxRect, bubbleInstances: bubbleInstances)
            let geometry = MangaOverlayExternalTextBoxGeometryEvaluator.evaluate(
                iou: iou,
                centerContained: centerContained,
                blockBubbleID: blockBubble?.id,
                textBoxBubbleID: textBoxBubble?.id
            )
            let bubbleAlignmentMatched = geometry.bubbleAlignmentVerdict == "matched"
            if geometry.bubbleAlignmentVerdict == "conflict" {
                rejectionReasons.append("bubbleAlignmentMismatch")
            }
            if geometry.spatialGeometryVerdict == "weakIoUShadowOnly" {
                riskFlags.append("weakSpatialGeometryShadowOnly")
            }
            if geometry.bubbleAlignmentVerdict == "unknown" {
                riskFlags.append("bubbleAlignmentUnknown")
            }
            if textBox.linePolygons?.isEmpty == false {
                riskFlags.append("linePolygonsPresentRequiresWarp")
            }
            if let rotationDegrees = textBox.rotationDegrees, abs(rotationDegrees) > 0.001 {
                riskFlags.append("rotationRecordedRequiresOrientationPath")
            }
            guard rejectionReasons.isEmpty else { return nil }
            let confidence = textBox.confidence ?? 0
            let ratioScore = max(0, 1 - abs(log(max(areaRatio, 0.001))))
            let score = (centerContained ? 2.0 : 0)
                + iou * 4
                + confidence
                + ratioScore * 0.4
                + (bubbleAlignmentMatched ? 0.35 : 0)
            return ExternalTextBoxShadowSelection(
                textBox: textBox,
                bubbleInstance: textBoxBubble ?? blockBubble,
                iou: iou,
                centerContained: centerContained,
                areaRatio: areaRatio,
                bubbleAlignmentMatched: bubbleAlignmentMatched,
                spatialGeometryVerdict: geometry.spatialGeometryVerdict,
                bubbleAlignmentVerdict: geometry.bubbleAlignmentVerdict,
                assignmentGeometryTrusted: geometry.assignmentGeometryTrusted,
                riskFlags: Array(Set(riskFlags)).sorted(),
                rejectionReasons: [],
                score: score
            )
        }
        .sorted {
            if $0.centerContained != $1.centerContained {
                return $0.centerContained && !$1.centerContained
            }
            if abs($0.iou - $1.iou) > 0.0001 {
                return $0.iou > $1.iou
            }
            if ($0.textBox.confidence ?? 0) != ($1.textBox.confidence ?? 0) {
                return ($0.textBox.confidence ?? 0) > ($1.textBox.confidence ?? 0)
            }
            if abs($0.score - $1.score) > 0.0001 {
                return $0.score > $1.score
            }
            return $0.textBox.id < $1.textBox.id
        }
    }

    private static func bestExternalBubble(
        for rect: CGRect,
        bubbleInstances: [MangaOverlayExternalBubbleInstance]
    ) -> MangaOverlayExternalBubbleInstance? {
        bubbleInstances
            .map { ($0, rectIoU(rect, Self.rect(from: $0.bbox))) }
            .filter { $0.1 >= 0.05 }
            .max { $0.1 < $1.1 }?
            .0
    }

    private static func externalArtifactURL(
        named path: String?,
        fallback: String,
        artifactsDirectory: URL?,
        label: String,
        parseErrors: inout [String]
    ) -> URL? {
        guard let artifactsDirectory else { return nil }
        guard let path, !path.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            return artifactsDirectory.appendingPathComponent(fallback)
        }
        let pathParts = path.split(separator: "/").map(String.init)
        if path.hasPrefix("/") || pathParts.contains("..") {
            parseErrors.append("manifest:\(label):pathEscapesActiveArtifactRoot")
            return artifactsDirectory.appendingPathComponent(fallback)
        }
        return artifactsDirectory.appendingPathComponent(path)
    }

    private static func decodeExternalArtifact<T: Decodable>(
        _ type: T.Type,
        from url: URL?,
        label: String,
        parseErrors: inout [String]
    ) -> T? {
        guard let url, FileManager.default.fileExists(atPath: url.path) else { return nil }
        do {
            return try JSONDecoder().decode(type, from: Data(contentsOf: url))
        } catch {
            parseErrors.append("\(label): \(error.localizedDescription)")
            return nil
        }
    }

    private static func decodeExternalArtifactList<T: Decodable>(
        _ type: T.Type,
        from url: URL?,
        keys: [String],
        label: String,
        parseErrors: inout [String]
    ) -> [T] {
        guard let url, FileManager.default.fileExists(atPath: url.path) else { return [] }
        do {
            let data = try Data(contentsOf: url)
            if let values = try? JSONDecoder().decode([T].self, from: data) {
                return values
            }
            let object = try JSONSerialization.jsonObject(with: data)
            guard let dictionary = object as? [String: Any] else {
                parseErrors.append("\(label): expected array or keyed object")
                return []
            }
            for key in keys {
                guard let raw = dictionary[key] else { continue }
                let nestedData = try JSONSerialization.data(withJSONObject: raw)
                return try JSONDecoder().decode([T].self, from: nestedData)
            }
            parseErrors.append("\(label): missing supported list key \(keys.joined(separator: "/"))")
            return []
        } catch {
            parseErrors.append("\(label): \(error.localizedDescription)")
            return []
        }
    }

    private static func decodeExternalBubbleMaskPayload(
        from url: URL?,
        parseErrors: inout [String]
    ) -> (payload: MangaOverlayExternalBubbleMaskPayload?, instances: [MangaOverlayExternalBubbleInstance]) {
        guard let url, FileManager.default.fileExists(atPath: url.path) else { return (nil, []) }
        do {
            let data = try Data(contentsOf: url)
            if let payload = try? JSONDecoder().decode(MangaOverlayExternalBubbleMaskPayload.self, from: data) {
                return (payload, payload.bubbleInstances)
            }
            if let instances = try? JSONDecoder().decode([MangaOverlayExternalBubbleInstance].self, from: data) {
                return (nil, instances)
            }
            parseErrors.append("bubbleMask: expected array or keyed payload object")
            return (nil, [])
        } catch {
            parseErrors.append("bubbleMask: \(error.localizedDescription)")
            return (nil, [])
        }
    }

    private static func externalMissingArtifacts(
        manifestURL: URL?,
        textBoxesURL: URL?,
        bubbleMaskURL: URL?,
        segmentMaskURL: URL?
    ) -> [String] {
        var missing: [String] = []
        if !fileExists(manifestURL) { missing.append("manifest") }
        if !fileExists(textBoxesURL) { missing.append("TextBoxes") }
        if !fileExists(bubbleMaskURL) { missing.append("BubbleMask") }
        if !fileExists(segmentMaskURL) { missing.append("SegmentMask") }
        return missing
    }

    private static func fileExists(_ url: URL?) -> Bool {
        guard let url else { return false }
        return FileManager.default.fileExists(atPath: url.path)
    }

    private static func externalArtifactGeneratedByPolicyErrors(
        manifest: MangaOverlayExternalArtifactManifest?
    ) -> [String] {
        guard let manifest, manifest.contractExampleOnly == false else { return [] }
        guard let generatedBy = manifest.generatedBy?.trimmingCharacters(in: .whitespacesAndNewlines),
              !generatedBy.isEmpty else {
            return ["generatedByMissing"]
        }
        let normalized = generatedBy
            .lowercased()
            .replacingOccurrences(of: "_", with: "-")
        let forbiddenTerms = [
            "contract example",
            "fixture",
            "manual",
            "vision ocr",
            "visionocr",
            "pre-crop",
            "precrop",
            "line plan",
            "bubblemask proxy",
            "bubble mask proxy",
            "segmentmask proxy",
            "segment mask proxy",
            "ground truth",
            "handwritten"
        ]
        return forbiddenTerms
            .filter { normalized.contains($0) }
            .map { "forbiddenGeneratedBy:\($0)" }
    }

    private static func normalizedExternalSourceDirection(_ value: String) -> String {
        var normalized = value
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
            .replacingOccurrences(of: "_", with: "-")
            .replacingOccurrences(of: " ", with: "-")
        while normalized.contains("--") {
            normalized = normalized.replacingOccurrences(of: "--", with: "-")
        }
        return normalized
    }

    private static func isValidExternalSourceDirection(_ value: String) -> Bool {
        let allowed = Set(["horizontal", "horizontal-lr", "vertical", "vertical-rl", "vertical-lr", "unknown"])
        return allowed.contains(normalizedExternalSourceDirection(value))
    }

    private static func externalTextBoxOrientationCategory(_ textBox: MangaOverlayExternalTextBox) -> String {
        guard let sourceDirection = textBox.sourceDirection else { return "unspecified" }
        let normalized = normalizedExternalSourceDirection(sourceDirection)
        if normalized.hasPrefix("vertical") {
            return "vertical"
        }
        if normalized.hasPrefix("horizontal") {
            return "horizontal"
        }
        return normalized == "unknown" ? "unknown" : "invalid"
    }

    private static func externalTextBoxNeedsOrientationShadowPath(_ textBox: MangaOverlayExternalTextBox) -> Bool {
        if externalTextBoxOrientationCategory(textBox) == "vertical" {
            return true
        }
        if textBox.linePolygons?.isEmpty == false {
            return true
        }
        if let rotationDegrees = textBox.rotationDegrees, abs(rotationDegrees) > 0.001 {
            return true
        }
        return false
    }

    private static func externalTextBoxOrientationShadowOCRPlan(
        _ textBox: MangaOverlayExternalTextBox
    ) -> (rotationAngles: [Int], recognitionLanguages: [String]?, unsupportedReasons: [String]) {
        var rotationAngles = [0]
        var unsupportedReasons: [String] = []
        let normalizedDirection = textBox.sourceDirection.map(normalizedExternalSourceDirection)
        let orientationCategory = externalTextBoxOrientationCategory(textBox)
        if orientationCategory == "vertical" {
            if normalizedDirection == "vertical-lr" {
                rotationAngles.append(270)
            } else {
                rotationAngles.append(90)
            }
        }
        if let rotation = textBox.rotationDegrees, abs(rotation) > 0.001 {
            if let supportedRotation = nearestSupportedExternalTextBoxRotation(rotation) {
                if supportedRotation != 0 {
                    rotationAngles.append(supportedRotation)
                }
            } else {
                unsupportedReasons.append("arbitraryRotationUnsupported")
            }
        }
        var seen = Set<Int>()
        let uniqueAngles = rotationAngles.filter { angle in
            if seen.contains(angle) { return false }
            seen.insert(angle)
            return true
        }
        let recognitionLanguages = orientationCategory == "vertical" ? ["ja-JP", "ja", "en-US", "en"] : nil
        return (uniqueAngles, recognitionLanguages, Array(Set(unsupportedReasons)).sorted())
    }

    private static func nearestSupportedExternalTextBoxRotation(_ value: Double) -> Int? {
        let normalized = value.truncatingRemainder(dividingBy: 360)
        let positive = normalized < 0 ? normalized + 360 : normalized
        let supported = [0, 90, 180, 270, 360]
        let nearest = supported.min { lhs, rhs in
            abs(Double(lhs) - positive) < abs(Double(rhs) - positive)
        } ?? 0
        guard abs(Double(nearest) - positive) <= 7.5 else {
            return nil
        }
        return nearest == 360 ? 0 : nearest
    }

    private static func countStrings(_ values: [String]) -> [String: Int] {
        values.reduce(into: [:]) { partial, value in
            partial[value, default: 0] += 1
        }
    }

    private static func externalTextBoxMetadataErrors(
        textBox: MangaOverlayExternalTextBox,
        imageWidth: Int,
        imageHeight: Int
    ) -> [String] {
        var errors: [String] = []
        if let sourceDirection = textBox.sourceDirection,
           !isValidExternalSourceDirection(sourceDirection) {
            errors.append("sourceDirectionInvalid")
        }
        if let rotation = textBox.rotationDegrees {
            if !rotation.isFinite {
                errors.append("rotationDegreesInvalid")
            } else if rotation < -360 || rotation > 360 {
                errors.append("rotationDegreesOutOfRange")
            }
        }
        if let linePolygons = textBox.linePolygons {
            if linePolygons.isEmpty {
                errors.append("linePolygonsInvalid")
            }
            let bbox = rect(from: textBox.bbox)
            let bboxTolerance = min(
                8.0,
                max(2.0, min(bbox.width, bbox.height) * 0.02)
            )
            let toleratedBBox = bbox.insetBy(dx: -bboxTolerance, dy: -bboxTolerance)
            for (polygonIndex, polygon) in linePolygons.enumerated() {
                if polygon.count < 4 {
                    errors.append("linePolygonInvalid:\(polygonIndex)")
                    continue
                }
                for (pointIndex, point) in polygon.enumerated() {
                    if point.count != 2 {
                        errors.append("linePolygonPointInvalid:\(polygonIndex):\(pointIndex)")
                        continue
                    }
                    let x = point[0]
                    let y = point[1]
                    if !x.isFinite || !y.isFinite {
                        errors.append("linePolygonPointInvalid:\(polygonIndex):\(pointIndex)")
                    } else if x < 0 || y < 0 || x > Double(imageWidth) || y > Double(imageHeight) {
                        errors.append("linePolygonPointOutOfBounds:\(polygonIndex):\(pointIndex)")
                    } else if x < Double(toleratedBBox.minX)
                        || y < Double(toleratedBBox.minY)
                        || x > Double(toleratedBBox.maxX)
                        || y > Double(toleratedBBox.maxY) {
                        errors.append("linePolygonOutsideTextBoxBBox:\(polygonIndex):\(pointIndex)")
                    }
                }
            }
        }
        return errors
    }

    private static func validateExternalArtifactCoordinates(
        manifest: MangaOverlayExternalArtifactManifest?,
        textBoxes: [MangaOverlayExternalTextBox],
        bubbleInstances: [MangaOverlayExternalBubbleInstance],
        segmentMask: MangaOverlayExternalSegmentMaskSummary?,
        expectedSourceImageSHA256: String?,
        imageWidth: Int,
        imageHeight: Int
    ) -> MangaOverlayExternalArtifactCoordinateValidation {
        let supportedSchemaVersions = [
            "aitrans.koharu_artifact_contract.v1",
            "aitrans.koharu_artifact_contract.v2"
        ]
        let expectedSchemaVersion = manifest?.schemaVersion == supportedSchemaVersions[1]
            ? supportedSchemaVersions[1]
            : supportedSchemaVersions[0]
        let expected = "originalImageTopLeftPixels"
        let schemaVersion = manifest?.schemaVersion
        let schemaVersionMatches = schemaVersion.map(supportedSchemaVersions.contains) ?? false
        let coordinateSpace = manifest?.coordinateSpace
        let sourceImageMissing = manifest != nil && (manifest?.sourceImageFieldPresent != true || manifest?.sourceImage.isEmpty == true)
        let sourceImageMatches = manifest == nil || manifest?.sourceImage == "test/1.png"
        let sourceImageSHA256Declared = manifest?.sourceImageSHA256
        let sourceImageSHA256Normalized = Self.normalizedExternalArtifactSHA256(sourceImageSHA256Declared)
        let sourceImageSHA256FieldPresent = manifest?.sourceImageSHA256FieldPresent ?? false
        let sourceImageSHA256TypeValid = manifest?.sourceImageSHA256TypeValid ?? false
        let sourceImageSHA256Matches = sourceImageSHA256Normalized != nil
            && expectedSourceImageSHA256 != nil
            && sourceImageSHA256Normalized == expectedSourceImageSHA256
        let contractExampleOnlyMissing = manifest != nil && manifest?.contractExampleOnlyFieldPresent != true
        let contractExampleOnlyInvalid = manifest != nil && manifest?.contractExampleOnlyFieldPresent == true && manifest?.contractExampleOnlyTypeValid != true
        var errors: [String] = []
        if let schemaVersion, !supportedSchemaVersions.contains(schemaVersion) {
            errors.append("schemaVersionMismatch:\(schemaVersion)")
        } else if schemaVersion == nil {
            errors.append("schemaVersionMissing")
        }
        if let coordinateSpace, coordinateSpace != expected {
            errors.append("coordinateSpaceMismatch:\(coordinateSpace)")
        } else if coordinateSpace == nil {
            errors.append("coordinateSpaceMissing")
        }
        if sourceImageMissing {
            errors.append("sourceImageMissing")
        } else if !sourceImageMatches {
            errors.append("sourceImageMismatch:\(manifest?.sourceImage ?? "nil")")
        }
        if manifest != nil {
            if !sourceImageSHA256FieldPresent {
                errors.append("sourceImageSHA256Missing")
            } else if !sourceImageSHA256TypeValid || sourceImageSHA256Normalized == nil {
                errors.append("sourceImageSHA256Invalid:\(sourceImageSHA256Declared ?? "nil")")
            } else if !sourceImageSHA256Matches {
                errors.append("sourceImageSHA256Mismatch:\(sourceImageSHA256Declared ?? "nil")")
            }
        }
        let bounds = CGRect(x: 0, y: 0, width: imageWidth, height: imageHeight)
        var invalidTextBoxes: [String] = []
        var seenTextBoxIDs: Set<String> = []
        for (textBoxIndex, textBox) in textBoxes.enumerated() {
            let normalizedTextBoxID = textBox.id.trimmingCharacters(in: .whitespacesAndNewlines)
            let ledgerID = normalizedTextBoxID.isEmpty ? "index-\(textBoxIndex)" : normalizedTextBoxID
            if normalizedTextBoxID.isEmpty {
                invalidTextBoxes.append(ledgerID)
                errors.append("textBoxIDMissing:\(textBoxIndex)")
            } else if !seenTextBoxIDs.insert(normalizedTextBoxID).inserted {
                invalidTextBoxes.append(ledgerID)
                errors.append("duplicateTextBoxID:\(normalizedTextBoxID)")
            }
            let rect = rect(from: textBox.bbox)
            guard rect.width > 0, rect.height > 0, rect.minX >= 0, rect.minY >= 0,
                  rect.maxX <= bounds.maxX, rect.maxY <= bounds.maxY else {
                invalidTextBoxes.append(ledgerID)
                continue
            }
            if let confidence = textBox.confidence, !(0...1).contains(confidence) {
                invalidTextBoxes.append(ledgerID)
                continue
            }
            let metadataErrors = externalTextBoxMetadataErrors(
                textBox: textBox,
                imageWidth: imageWidth,
                imageHeight: imageHeight
            )
            if !metadataErrors.isEmpty {
                invalidTextBoxes.append(ledgerID)
                for metadataError in metadataErrors {
                    errors.append("textBox:\(ledgerID):\(metadataError)")
                }
            }
        }
        var invalidBubbles: [String] = []
        var seenBubbleIDs: Set<String> = []
        for (bubbleIndex, bubble) in bubbleInstances.enumerated() {
            let normalizedBubbleID = bubble.id.trimmingCharacters(in: .whitespacesAndNewlines)
            let ledgerID = normalizedBubbleID.isEmpty ? "index-\(bubbleIndex)" : normalizedBubbleID
            if normalizedBubbleID.isEmpty {
                invalidBubbles.append(ledgerID)
                errors.append("bubbleIDMissing:\(bubbleIndex)")
            } else if !seenBubbleIDs.insert(normalizedBubbleID).inserted {
                invalidBubbles.append(ledgerID)
                errors.append("duplicateBubbleID:\(normalizedBubbleID)")
            }
            let rect = rect(from: bubble.bbox)
            guard rect.width > 0, rect.height > 0, rect.minX >= 0, rect.minY >= 0,
                  rect.maxX <= bounds.maxX, rect.maxY <= bounds.maxY else {
                invalidBubbles.append(ledgerID)
                continue
            }
            if let confidence = bubble.confidence, !(0...1).contains(confidence) {
                invalidBubbles.append(ledgerID)
            }
        }
        invalidBubbles = Array(Set(invalidBubbles)).sorted()
        if !invalidTextBoxes.isEmpty {
            errors.append("invalidTextBoxes=\(Array(Set(invalidTextBoxes)).sorted().joined(separator: ","))")
        }
        if !invalidBubbles.isEmpty {
            errors.append("invalidBubbleBBoxes=\(invalidBubbles.joined(separator: ","))")
        }
        let segmentSizeMatches: Bool?
        if let width = segmentMask?.width, let height = segmentMask?.height {
            segmentSizeMatches = width == imageWidth && height == imageHeight
            if segmentSizeMatches == false {
                errors.append("segmentMaskSizeMismatch:\(width)x\(height)")
            }
        } else {
            segmentSizeMatches = nil
        }
        var notes = ["bbox convention is original image pixel coordinates with top-left origin"]
        if manifest?.contractExampleOnly == true {
            notes.append("contractExampleOnly=true")
        }
        if contractExampleOnlyMissing {
            errors.append("contractExampleOnlyMissing")
            notes.append("contractExampleOnlyMissing")
        } else if contractExampleOnlyInvalid {
            errors.append("contractExampleOnlyInvalid")
            notes.append("contractExampleOnlyInvalid")
        }
        let sourcePolicyErrors = Self.externalArtifactGeneratedByPolicyErrors(manifest: manifest)
        if !sourcePolicyErrors.isEmpty {
            errors.append(contentsOf: sourcePolicyErrors)
            notes.append("generatedBy source policy blocks active readiness unless it names a real detector/segmenter source")
        }
        return MangaOverlayExternalArtifactCoordinateValidation(
            schemaVersion: schemaVersion,
            expectedSchemaVersion: expectedSchemaVersion,
            schemaVersionMatches: schemaVersionMatches,
            coordinateSpace: coordinateSpace,
            expectedCoordinateSpace: expected,
            sourceImageMatches: sourceImageMatches,
            sourceImageSHA256: sourceImageSHA256Declared,
            expectedSourceImageSHA256: expectedSourceImageSHA256,
            sourceImageSHA256FieldPresent: sourceImageSHA256FieldPresent,
            sourceImageSHA256TypeValid: sourceImageSHA256TypeValid,
            sourceImageSHA256Matches: sourceImageSHA256Matches,
            imageWidth: imageWidth,
            imageHeight: imageHeight,
            bboxValidationPassed: invalidTextBoxes.isEmpty && invalidBubbles.isEmpty,
            invalidTextBoxIDs: invalidTextBoxes,
            invalidBubbleInstanceIDs: invalidBubbles,
            segmentMaskSizeMatches: segmentSizeMatches,
            errors: errors,
            notes: notes
        )
    }

    private static func externalMaskTopologyReport(
        blocks: [MangaOverlayProbeBlock],
        matching: ExternalTextBoxShadowMatching,
        validatedBubbleMask: KoharuValidatedBubbleMask?,
        validatedSegmentMask: KoharuValidatedSegmentMask?
    ) -> MangaOverlayExternalMaskTopologyReport {
        let allBlockIndexes = blocks.map(\.index).sorted()
        guard let validatedBubbleMask, let validatedSegmentMask else {
            return MangaOverlayExternalMaskTopologyReport(
                evaluated: false,
                assignmentSource: "stableOneToOneExternalTextBoxShadowMatching",
                totalBlockCount: blocks.count,
                assignedBlockIndexes: [],
                missingBlockIndexes: allBlockIndexes,
                totalGlyphPixelCount: 0,
                insideAssignedTextBoxGlyphPixelCount: 0,
                segmentPixelsInExpectedBubble: 0,
                foreignBubbleSegmentPixels: 0,
                noBubbleSegmentPixels: 0,
                orphanSegmentPixels: 0,
                multiplyAssignedSegmentPixels: 0,
                partitionPixelCount: 0,
                partitionConserved: false,
                duplicateBlockIndexes: [],
                duplicateAssignedTextBoxIDs: [],
                invalidExpectedBubbleBlockIndexes: [],
                crossBubbleComponentIndexes: [],
                orphanComponentIndexes: [],
                assignmentLedgers: [],
                componentLedgers: [],
                blockers: ["validatedMaskPayloadsRequired"],
                topologyVerdict: "notEvaluated",
                shadowOnly: true,
                notes: [
                    "v2 validated BubbleMask and SegmentMask payloads are required",
                    "topology evaluation never changes OCR, translation, rendering, blockPassed, or currentBlockSource"
                ]
            )
        }

        func pixelRect(_ bbox: [Double]) -> KoharuMaskPixelRect {
            guard bbox.count == 4 else { return KoharuMaskPixelRect(x: 0, y: 0, width: 0, height: 0) }
            let minX = Int(floor(bbox[0]))
            let minY = Int(floor(bbox[1]))
            let maxX = Int(ceil(bbox[0] + bbox[2]))
            let maxY = Int(ceil(bbox[1] + bbox[3]))
            return KoharuMaskPixelRect(
                x: minX,
                y: minY,
                width: max(0, maxX - minX),
                height: max(0, maxY - minY)
            )
        }

        let assignments = matching.assignmentsByBlockIndex.map { blockIndex, selection in
            KoharuMaskTopologyAssignment(
                blockIndex: blockIndex,
                textBoxID: selection.textBox.id,
                rect: pixelRect(selection.textBox.bbox),
                expectedBubbleLabel: selection.bubbleInstance?.maskValue ?? 0
            )
        }
        let assignedBlockIndexes = assignments.map(\.blockIndex).sorted()
        let assignedBlockSet = Set(assignedBlockIndexes)
        let missingBlockIndexes = allBlockIndexes.filter { !assignedBlockSet.contains($0) }

        do {
            let evaluation = try KoharuMaskPayloadEvaluator.evaluateTopology(
                segmentMask: validatedSegmentMask.mask,
                bubbleMask: validatedBubbleMask.mask,
                assignments: assignments
            )
            var blockers = evaluation.blockers.map(\.rawValue)
            if blocks.isEmpty { blockers.append("emptyBlockSet") }
            if !missingBlockIndexes.isEmpty { blockers.append("missingStableAssignment") }
            blockers = Array(Set(blockers)).sorted()
            let complete = blockers.isEmpty
            return MangaOverlayExternalMaskTopologyReport(
                evaluated: true,
                assignmentSource: "stableOneToOneExternalTextBoxShadowMatching",
                totalBlockCount: blocks.count,
                assignedBlockIndexes: assignedBlockIndexes,
                missingBlockIndexes: missingBlockIndexes,
                totalGlyphPixelCount: evaluation.totalGlyphPixelCount,
                insideAssignedTextBoxGlyphPixelCount: evaluation.insideAssignedBoxGlyphPixelCount,
                segmentPixelsInExpectedBubble: evaluation.expectedBubbleGlyphPixelCount,
                foreignBubbleSegmentPixels: evaluation.foreignBubbleGlyphPixelCount,
                noBubbleSegmentPixels: evaluation.noBubbleGlyphPixelCount,
                orphanSegmentPixels: evaluation.orphanGlyphPixelCount,
                multiplyAssignedSegmentPixels: evaluation.multiplyAssignedGlyphPixelCount,
                partitionPixelCount: evaluation.partitionPixelCount,
                partitionConserved: evaluation.partitionConserved,
                duplicateBlockIndexes: evaluation.duplicateBlockIndexes,
                duplicateAssignedTextBoxIDs: evaluation.duplicateTextBoxIDs,
                invalidExpectedBubbleBlockIndexes: evaluation.invalidExpectedBubbleBlockIndexes,
                crossBubbleComponentIndexes: evaluation.crossBubbleComponentIndexes,
                orphanComponentIndexes: evaluation.orphanComponentIndexes,
                assignmentLedgers: evaluation.assignmentLedgers.map {
                    MangaOverlayExternalMaskTopologyAssignmentLedger(
                        blockIndex: $0.blockIndex,
                        textBoxID: $0.textBoxID,
                        expectedBubbleMaskValue: $0.expectedBubbleLabel,
                        glyphPixelCount: $0.glyphPixelCount,
                        segmentPixelsInExpectedBubble: $0.expectedBubbleGlyphPixelCount,
                        foreignBubbleSegmentPixels: $0.foreignBubbleGlyphPixelCount,
                        noBubbleSegmentPixels: $0.noBubbleGlyphPixelCount,
                        componentIndexes: $0.componentIndexes,
                        partitionConserved: $0.partitionConserved
                    )
                },
                componentLedgers: evaluation.componentLedgers.map {
                    MangaOverlayExternalMaskTopologyComponentLedger(
                        componentIndex: $0.componentIndex,
                        bbox: [$0.bbox.x, $0.bbox.y, $0.bbox.width, $0.bbox.height],
                        pixelCount: $0.pixelCount,
                        assignedBlockIndexes: $0.assignedBlockIndexes,
                        assignedTextBoxIDs: $0.assignedTextBoxIDs,
                        bubbleMaskValues: $0.bubbleLabels,
                        segmentPixelsInExpectedBubble: $0.expectedBubbleGlyphPixelCount,
                        foreignBubbleSegmentPixels: $0.foreignBubbleGlyphPixelCount,
                        noBubbleSegmentPixels: $0.noBubbleGlyphPixelCount,
                        orphanSegmentPixels: $0.orphanGlyphPixelCount,
                        multiplyAssignedSegmentPixels: $0.multiplyAssignedGlyphPixelCount,
                        partitionConserved: $0.partitionConserved,
                        crossesBubble: $0.crossesBubble,
                        hasOrphanGlyph: $0.hasOrphanGlyph
                    )
                },
                blockers: blockers,
                topologyVerdict: complete ? "complete" : "blocked",
                shadowOnly: true,
                notes: [
                    "assignments reuse the external shadow OCR stable one-to-one matcher",
                    "component and pixel partitions are deterministic and ground-truth-free",
                    "topology evidence does not change OCR, translation, rendering, blockPassed, or currentBlockSource"
                ]
            )
        } catch {
            return MangaOverlayExternalMaskTopologyReport(
                evaluated: false,
                assignmentSource: "stableOneToOneExternalTextBoxShadowMatching",
                totalBlockCount: blocks.count,
                assignedBlockIndexes: assignedBlockIndexes,
                missingBlockIndexes: missingBlockIndexes,
                totalGlyphPixelCount: 0,
                insideAssignedTextBoxGlyphPixelCount: 0,
                segmentPixelsInExpectedBubble: 0,
                foreignBubbleSegmentPixels: 0,
                noBubbleSegmentPixels: 0,
                orphanSegmentPixels: 0,
                multiplyAssignedSegmentPixels: 0,
                partitionPixelCount: 0,
                partitionConserved: false,
                duplicateBlockIndexes: [],
                duplicateAssignedTextBoxIDs: [],
                invalidExpectedBubbleBlockIndexes: [],
                crossBubbleComponentIndexes: [],
                orphanComponentIndexes: [],
                assignmentLedgers: [],
                componentLedgers: [],
                blockers: ["topologyEvaluationFailed"],
                topologyVerdict: "evaluationFailed",
                shadowOnly: true,
                notes: ["topologyEvaluationError=\(error)"]
            )
        }
    }

    private static func externalArtifactBlockAlignment(
        blocks: [MangaOverlayProbeBlock],
        textBoxes: [MangaOverlayExternalTextBox],
        bubbleInstances: [MangaOverlayExternalBubbleInstance],
        segmentMask: MangaOverlayExternalSegmentMaskSummary?,
        segmentMaskReport: MangaOverlaySegmentMaskReport?,
        validatedBubbleMask: KoharuValidatedBubbleMask?,
        validatedSegmentMask: KoharuValidatedSegmentMask?,
        matching: ExternalTextBoxShadowMatching
    ) -> [MangaOverlayExternalArtifactBlockAlignment] {
        func pixelRect(_ rect: CGRect) -> KoharuMaskPixelRect {
            let minX = Int(floor(rect.minX))
            let minY = Int(floor(rect.minY))
            let maxX = Int(ceil(rect.maxX))
            let maxY = Int(ceil(rect.maxY))
            return KoharuMaskPixelRect(
                x: minX,
                y: minY,
                width: max(0, maxX - minX),
                height: max(0, maxY - minY)
            )
        }

        let internalSegmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentMaskReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        return blocks.map { block in
            let blockRect = rect(from: block.bbox)
            let stableAssignment = matching.assignmentsByBlockIndex[block.index]
            let assignedTextBox = stableAssignment?.textBox
            let assignedBubble = stableAssignment?.bubbleInstance
            let textBoxRect = assignedTextBox.map { rect(from: $0.bbox) }
            let centerContained = stableAssignment?.centerContained ?? false
            let bubbleStatistics = validatedBubbleMask?.mask.statistics(in: pixelRect(blockRect))
            let segmentStatistics = validatedSegmentMask?.mask.statistics(in: pixelRect(blockRect))
            let textBoxSegmentContainmentRatio: Double?
            if let textBoxRect,
               let segmentStatistics,
               segmentStatistics.nonzeroPixelCount > 0 {
                let intersection = blockRect.intersection(textBoxRect)
                let containedGlyphPixels = intersection.isNull
                    ? 0
                    : validatedSegmentMask?.mask.statistics(in: pixelRect(intersection)).nonzeroPixelCount ?? 0
                textBoxSegmentContainmentRatio = Double(containedGlyphPixels) / Double(segmentStatistics.nonzeroPixelCount)
            } else {
                textBoxSegmentContainmentRatio = nil
            }
            let segmentCoverageLevel: String
            if validatedSegmentMask != nil {
                segmentCoverageLevel = (segmentStatistics?.nonzeroPixelCount ?? 0) > 0
                    ? "pixelPayloadCovered"
                    : "pixelPayloadEmptyForBlock"
            } else if let segmentMask {
                let glyphPixels = segmentMask.glyphPixelCount ?? 0
                segmentCoverageLevel = glyphPixels > 0 ? "summaryAvailable" : "summaryEmpty"
            } else if let internalSegment = internalSegmentByBlock[block.index] {
                segmentCoverageLevel = internalSegment.usableForCropEvidence ? "internalProxyUsableOnly" : "internalProxyWeakOnly"
            } else {
                segmentCoverageLevel = "missing"
            }
            let hasTextBoxMatch = stableAssignment != nil
            let hasBubbleMatch = assignedBubble != nil
            let verdict: String
            if textBoxes.isEmpty && bubbleInstances.isEmpty {
                verdict = "notEvaluatedMissingArtifacts"
            } else if hasTextBoxMatch && hasBubbleMatch {
                verdict = "aligned"
            } else if hasTextBoxMatch {
                verdict = "textBoxOnly"
            } else if hasBubbleMatch {
                verdict = "bubbleOnly"
            } else {
                verdict = "unaligned"
            }
            return MangaOverlayExternalArtifactBlockAlignment(
                blockIndex: block.index,
                blockBBox: block.bbox,
                bestTextBoxID: hasTextBoxMatch ? assignedTextBox?.id : nil,
                bestTextBoxIoU: stableAssignment?.iou,
                textBoxCenterContained: centerContained,
                bestBubbleInstanceID: hasBubbleMatch ? assignedBubble?.id : nil,
                bestBubbleIoU: assignedBubble.map { rectIoU(blockRect, rect(from: $0.bbox)) },
                currentBubbleID: block.bubbleID,
                bestExternalBubbleMaskValue: hasBubbleMatch ? assignedBubble?.maskValue : nil,
                bubbleMajorityMaskValue: bubbleStatistics?.majorityNonzeroLabel,
                bubblePixelCoverageRatio: bubbleStatistics?.majorityNonzeroCoverageRatio,
                segmentPixelCoverageRatio: segmentStatistics?.nonzeroCoverageRatio,
                textBoxSegmentContainmentRatio: textBoxSegmentContainmentRatio,
                segmentCoverageLevel: segmentCoverageLevel,
                alignmentVerdict: verdict,
                notes: [
                    "alignment is shadow-only and reuses stableOneToOneExternalTextBoxShadowMatching without ground truth",
                    "pixel payload statistics do not change OCR, translation, rendering, blockPassed, or currentBlockSource"
                ]
            )
        }
    }

    private static func externalArtifactReadinessVerdict(
        manifestFound: Bool,
        textBoxes: [MangaOverlayExternalTextBox],
        bubbleInstances: [MangaOverlayExternalBubbleInstance],
        segmentMask: MangaOverlayExternalSegmentMaskSummary?,
        missingArtifacts: [String],
        parseErrors: [String],
        coordinateValidation: MangaOverlayExternalArtifactCoordinateValidation,
        maskPayloadRequired: Bool,
        maskPayloadGateReady: Bool
    ) -> String {
        if !manifestFound { return "manifestMissing" }
        if maskPayloadRequired && !maskPayloadGateReady { return "maskPayloadValidationFailed" }
        if !parseErrors.isEmpty { return "parseFailed" }
        if coordinateValidation.errors.contains("schemaVersionMissing") { return "schemaVersionMissing" }
        if coordinateValidation.errors.contains(where: { $0.hasPrefix("schemaVersionMismatch") }) {
            return "schemaVersionMismatch"
        }
        if coordinateValidation.errors.contains("coordinateSpaceMissing") { return "coordinateSpaceMissing" }
        if coordinateValidation.errors.contains(where: { $0.hasPrefix("coordinateSpaceMismatch") }) {
            return "coordinateSpaceMismatch"
        }
        if coordinateValidation.errors.contains("sourceImageMissing") {
            return "sourceImageMissing"
        }
        if coordinateValidation.errors.contains(where: { $0.hasPrefix("sourceImageMismatch") }) {
            return "sourceImageMismatch"
        }
        if coordinateValidation.errors.contains("sourceImageSHA256Missing") {
            return "sourceImageSHA256Missing"
        }
        if coordinateValidation.errors.contains(where: { $0.hasPrefix("sourceImageSHA256Invalid") }) {
            return "sourceImageSHA256Invalid"
        }
        if coordinateValidation.errors.contains(where: { $0.hasPrefix("sourceImageSHA256Mismatch") }) {
            return "sourceImageSHA256Mismatch"
        }
        if coordinateValidation.errors.contains("contractExampleOnlyMissing") {
            return "contractExampleOnlyMissing"
        }
        if coordinateValidation.errors.contains(where: { $0.hasPrefix("contractExampleOnlyInvalid") }) {
            return "contractExampleOnlyInvalid"
        }
        if coordinateValidation.errors.contains("generatedByMissing") {
            return "generatedByMissing"
        }
        if coordinateValidation.errors.contains(where: { $0.hasPrefix("forbiddenGeneratedBy") }) {
            return "forbiddenGeneratedBy"
        }
        if coordinateValidation.errors.contains(where: { $0.hasPrefix("invalidTextBoxBBoxes") || $0.hasPrefix("invalidBubbleBBoxes") || $0.hasPrefix("segmentMaskSizeMismatch") }) {
            return "coordinateValidationFailed"
        }
        if !coordinateValidation.errors.isEmpty { return "coordinateValidationFailed" }
        if !missingArtifacts.isEmpty { return "artifactFilesMissing" }
        if textBoxes.isEmpty { return "insufficientTextBoxCoverage" }
        if bubbleInstances.isEmpty { return "insufficientBubbleCoverage" }
        if segmentMask == nil { return "segmentMaskMissing" }
        if coordinateValidation.notes.contains("contractExampleOnly=true") { return "contractExampleOnly" }
        return "readyForShadowOCR"
    }

    private static func externalArtifactNextAction(
        verdict: String,
        textBoxes: [MangaOverlayExternalTextBox],
        bubbleInstances: [MangaOverlayExternalBubbleInstance],
        segmentMask: MangaOverlayExternalSegmentMaskSummary?
    ) -> String {
        switch verdict {
        case "readyForShadowOCR":
            if !textBoxes.isEmpty { return "continueWithExternalTextBoxesShadowOCR" }
            if !bubbleInstances.isEmpty { return "continueWithBubbleMaskComparison" }
            if segmentMask != nil { return "continueWithSegmentMaskComparison" }
            return "evaluateCoreMLConversion"
        case "parseFailed":
            return "stopUntilParserFixed"
        case "contractExampleOnly":
            return "stopBecauseFixtureIsNotDetectorOutput"
        case "contractExampleOnlyMissing", "contractExampleOnlyInvalid", "generatedByMissing", "forbiddenGeneratedBy":
            return "stopUntilRealDetectorSourceDeclared"
        case "schemaVersionMissing", "schemaVersionMismatch", "coordinateSpaceMissing", "coordinateSpaceMismatch", "sourceImageMissing", "sourceImageMismatch", "sourceImageSHA256Missing", "sourceImageSHA256Invalid", "sourceImageSHA256Mismatch", "coordinateValidationFailed", "maskPayloadValidationFailed":
            return "stopUntilArtifactContractFixed"
        default:
            return "stopUntilArtifactsProvided"
        }
    }

    private func makeMangaOverlayProbeDiagnostics(blocks: [MangaOverlayProbeBlock]) -> MangaOverlayProbeDiagnostics {
        var diagnostics = MangaOverlayProbeDiagnostics.empty
        diagnostics.passedBlocks = blocks.filter(\.blockPassed).count
        diagnostics.failedBlocks = blocks.count - diagnostics.passedBlocks
        diagnostics.bubbleAssignedBlocks = blocks.filter { $0.bubbleID != nil }.count
        diagnostics.bubbleUnassignedBlocks = blocks.count - diagnostics.bubbleAssignedBlocks
        let matchedBlocks = blocks.filter { $0.groundTruthMatch == "matched" }
        diagnostics.groundTruthMatchedBlocks = matchedBlocks.count
        diagnostics.groundTruthUnmatchedBlocks = blocks.count - matchedBlocks.count
        let ocrSimilarities = matchedBlocks.compactMap(\.ocrGroundTruthSimilarity)
        if !ocrSimilarities.isEmpty {
            diagnostics.averageOCRGroundTruthSimilarity = ocrSimilarities.reduce(0, +) / Double(ocrSimilarities.count)
        }
        let dialogueSimilarities = matchedBlocks
            .filter { $0.bestGroundTruthType == MangaGroundTruthEntry.dialogueType }
            .compactMap(\.ocrGroundTruthSimilarity)
        if !dialogueSimilarities.isEmpty {
            diagnostics.averageCoreDialogueOCRSimilarity = dialogueSimilarities.reduce(0, +) / Double(dialogueSimilarities.count)
        }
        let decorativeSimilarities = matchedBlocks
            .filter { $0.bestGroundTruthType == MangaGroundTruthEntry.decorativeType }
            .compactMap(\.ocrGroundTruthSimilarity)
        if !decorativeSimilarities.isEmpty {
            diagnostics.averageDecorativeOCRSimilarity = decorativeSimilarities.reduce(0, +) / Double(decorativeSimilarities.count)
        }
        let deterministicSimilarities = blocks.compactMap(\.deterministicCorrectionSimilarity)
        if !deterministicSimilarities.isEmpty {
            diagnostics.deterministicCorrectionAverageSimilarity = deterministicSimilarities.reduce(0, +) / Double(deterministicSimilarities.count)
        }

        for block in blocks {
            let candidate = block.translationCandidate.trimmingCharacters(in: .whitespacesAndNewlines)
            let rawOutput = block.rawOutput.trimmingCharacters(in: .whitespacesAndNewlines)
            if candidate.isEmpty {
                diagnostics.emptyTranslationCandidates += 1
            }
            if block.qualityNotes.contains("candidateExtractorDroppedRawOutput") {
                diagnostics.candidateExtractorDroppedRawOutputs += 1
            }
            switch block.rawOutputClassification {
            case "empty":
                diagnostics.rawOutputEmptyBlocks += 1
            case "placeholder":
                diagnostics.rawOutputPlaceholderBlocks += 1
            case "repeatedOriginal":
                diagnostics.rawOutputRepeatedOriginalBlocks += 1
            case "nonChinese", "symbolsOnly":
                diagnostics.rawOutputNonChineseBlocks += 1
            default:
                break
            }
            if Self.isPlaceholderTranslationOutput(candidate) || Self.isPlaceholderTranslationOutput(rawOutput) {
                diagnostics.placeholderTranslationCandidates += 1
            }
            if !candidate.isEmpty,
               candidate.localizedCaseInsensitiveCompare(block.finalTextUsedForTranslation.trimmingCharacters(in: .whitespacesAndNewlines)) == .orderedSame {
                diagnostics.repeatedOriginalCandidates += 1
            }
            if !candidate.isEmpty, !Self.containsCJK(candidate) {
                diagnostics.nonChineseCandidates += 1
            }
            let candidateHasUsableCJK = block.candidateClassification == "chinese"
                || block.candidateClassification == "mixedChineseAndEnglish"
            if candidateHasUsableCJK, !block.blockPassed {
                diagnostics.cjkButFailedCandidates += 1
                let cjkFailureKey = Self.cjkFailureDiagnosticKey(for: block)
                diagnostics.cjkFailureBreakdown[cjkFailureKey, default: 0] += 1
            }
            if block.translationDecisionTrace.contains("translationLanguageQualityPassed=true") {
                diagnostics.translationLanguageQualityPassedBlocks.append(block.index)
            } else {
                diagnostics.translationLanguageQualityFailedBlocks.append(block.index)
            }
            if block.failureCategory == "ruleFalseFailureSuspected" {
                diagnostics.likelyRuleFalseFailureBlocks.append(block.index)
            }
            if block.failureCategory == "translationUsableButOCRSuspect" {
                diagnostics.translationUsableButOCRSuspectBlocks.append(block.index)
            }
            if let similarity = block.ocrGroundTruthSimilarity, similarity < 0.72 {
                diagnostics.lowOCRSimilarityBlocks.append(block.index)
            }
            if block.wordOrderPreserved == false {
                diagnostics.wordOrderFailedBlocks.append(block.index)
            }
            if block.qualityNotes.contains("likelyOCRIssue") || block.failureCategory == "ocrInputSuspect" {
                diagnostics.likelyOCRIssueBlocks.append(block.index)
            }
            if block.failureCategory == "modelOutputFailure" {
                diagnostics.likelyModelOutputFailures += 1
            }
            if block.crossBubbleMergeRejected {
                diagnostics.crossBubbleMergeRejectedBlocks.append(block.index)
            }
            if block.safeLayoutRect != nil {
                diagnostics.safeLayoutRectBlocks += 1
            }
            if block.renderCollisionChecked {
                diagnostics.renderCollisionCheckedBlocks += 1
                if block.renderCollisionInitialOverflow {
                    diagnostics.renderCollisionInitialOverflowBlocks.append(block.index)
                }
                if block.renderCollisionResolved {
                    diagnostics.renderCollisionResolvedBlocks.append(block.index)
                } else {
                    diagnostics.renderCollisionUnresolvedBlocks.append(block.index)
                }
                if block.renderMinFontSizeReached {
                    diagnostics.renderMinFontSizeReachedBlocks.append(block.index)
                }
                if block.renderTextTruncated {
                    diagnostics.renderTextTruncatedBlocks.append(block.index)
                }
            }
            if block.glyphMaskPixelCount > 0 {
                diagnostics.glyphMaskBlocks += 1
            }
            if block.backgroundFillApplied {
                diagnostics.backgroundFillAppliedBlocks.append(block.index)
            } else if block.glyphMaskPixelCount > 0 {
                diagnostics.backgroundFillSkippedBlocks.append(block.index)
            }
            if block.blockPassed, Self.mangaProbePassedTranslationLooksSuspicious(block) {
                diagnostics.passedButSuspiciousTranslationBlocks.append(block.index)
            }
            if let correctedSimilarity = block.deterministicCorrectionSimilarity,
               let originalSimilarity = block.ocrGroundTruthSimilarity,
               correctedSimilarity > originalSimilarity + 0.02 {
                diagnostics.deterministicCorrectionImprovedBlocks.append(block.index)
            }
            if let correctionTranslationPassed = block.deterministicCorrectionTranslationPassed {
                diagnostics.deterministicCorrectionTranslationTestedBlocks.append(block.index)
                if correctionTranslationPassed {
                    diagnostics.deterministicCorrectionTranslationPassedBlocks.append(block.index)
                } else {
                    diagnostics.deterministicCorrectionTranslationFailedBlocks.append(block.index)
                }
            }
            if !block.blockPassed {
                diagnostics.translationFailureBreakdown[block.failureCategory, default: 0] += 1
            }
            diagnostics.ocrQualityProbe.append(
                Self.mangaOCRProbeSummaryLine(for: block)
            )
        }
        diagnostics.lowOCRSimilarityBlocks = Array(Set(diagnostics.lowOCRSimilarityBlocks)).sorted()
        diagnostics.wordOrderFailedBlocks = Array(Set(diagnostics.wordOrderFailedBlocks)).sorted()
        diagnostics.likelyOCRIssueBlocks = Array(Set(diagnostics.likelyOCRIssueBlocks)).sorted()
        diagnostics.likelyRuleFalseFailureBlocks = Array(Set(diagnostics.likelyRuleFalseFailureBlocks)).sorted()
        diagnostics.passedButSuspiciousTranslationBlocks = Array(Set(diagnostics.passedButSuspiciousTranslationBlocks)).sorted()
        diagnostics.translationLanguageQualityPassedBlocks = Array(Set(diagnostics.translationLanguageQualityPassedBlocks)).sorted()
        diagnostics.translationLanguageQualityFailedBlocks = Array(Set(diagnostics.translationLanguageQualityFailedBlocks)).sorted()
        diagnostics.translationUsableButOCRSuspectBlocks = Array(Set(diagnostics.translationUsableButOCRSuspectBlocks)).sorted()
        diagnostics.deterministicCorrectionImprovedBlocks = Array(Set(diagnostics.deterministicCorrectionImprovedBlocks)).sorted()
        diagnostics.deterministicCorrectionTranslationTestedBlocks = Array(Set(diagnostics.deterministicCorrectionTranslationTestedBlocks)).sorted()
        diagnostics.deterministicCorrectionTranslationPassedBlocks = Array(Set(diagnostics.deterministicCorrectionTranslationPassedBlocks)).sorted()
        diagnostics.deterministicCorrectionTranslationFailedBlocks = Array(Set(diagnostics.deterministicCorrectionTranslationFailedBlocks)).sorted()
        diagnostics.crossBubbleMergeRejectedBlocks = Array(Set(diagnostics.crossBubbleMergeRejectedBlocks)).sorted()
        diagnostics.backgroundFillAppliedBlocks = Array(Set(diagnostics.backgroundFillAppliedBlocks)).sorted()
        diagnostics.backgroundFillSkippedBlocks = Array(Set(diagnostics.backgroundFillSkippedBlocks)).sorted()
        diagnostics.repeatedKeywordFailures = Self.repeatedKeywordFailures(in: blocks)
        return diagnostics
    }

    private static func repeatedKeywordFailures(in blocks: [MangaOverlayProbeBlock]) -> [String: Int] {
        var failures: [String: Int] = [:]
        let trackedWords = ["senpai", "senpai's", "city", "battler", "tournament"]
        for word in trackedWords {
            let affected = blocks.filter { block in
                guard block.bestGroundTruthText?.lowercased().contains(word) == true else { return false }
                return !block.finalTextUsedForTranslation.lowercased().contains(word)
            }
            if affected.count >= 2 {
                failures[word] = affected.count
            }
        }
        return failures
    }

    private static func makeInternalStructureBottleneckReport(
        blocks: [MangaOverlayProbeBlock],
        textRegionCropReport: MangaOverlayTextRegionCropReport?,
        textBoxPlanFailureReport: MangaOverlayTextBoxPlanFailureReport?,
        bubbleMaskReport: MangaOverlayBubbleMaskReport?,
        bubbleAssignmentCorrectionReport: MangaOverlayBubbleAssignmentCorrectionReport?,
        bubbleSplitCandidateReport: MangaOverlayBubbleSplitCandidateReport?,
        postFusionCleanup: MangaOverlayPostFusionCleanupReport?,
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?
    ) -> MangaOverlayInternalStructureBottleneckReport {
        let cropByBlock = Dictionary(
            uniqueKeysWithValues: (textRegionCropReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let textBoxFailureByBlock = Dictionary(
            uniqueKeysWithValues: (textBoxPlanFailureReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let bubbleMaskByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleMaskReport?.blockDiagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let correctionByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleAssignmentCorrectionReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        var splitByBlock: [Int: MangaOverlayBubbleSplitCandidateDiagnostic] = [:]
        for diagnostic in bubbleSplitCandidateReport?.diagnostics ?? [] {
            for blockIndex in diagnostic.seedBlockIndexes where splitByBlock[blockIndex] == nil {
                splitByBlock[blockIndex] = diagnostic
            }
        }
        let postFusionRejectedDuplicateOriginalIndexes = Set(
            (postFusionCleanup?.rejectedBlocks ?? [])
                .filter { $0.reason == "duplicateOrFragment" || $0.reason.localizedCaseInsensitiveContains("fragment") || $0.reason.localizedCaseInsensitiveContains("duplicate") }
                .map(\.originalFusedBlockIndex)
        )
        let postFusionRelatedKeptOriginalIndexes = Set(
            (postFusionCleanup?.rejectedBlocks ?? [])
                .filter { $0.reason == "duplicateOrFragment" || $0.reason.localizedCaseInsensitiveContains("fragment") || $0.reason.localizedCaseInsensitiveContains("duplicate") }
                .compactMap(\.relatedFusedBlockIndex)
        )
        let optionalExternalMissing = externalArtifactReadinessReport?.readinessVerdict == "manifestMissing"
            || externalArtifactReadinessReport?.readinessVerdict == "artifactFilesMissing"

        let summaries = blocks.map { block -> MangaOverlayInternalStructureBottleneckBlock in
            let crop = cropByBlock[block.index]
            let textBoxFailure = textBoxFailureByBlock[block.index]
            let mask = bubbleMaskByBlock[block.index]
            let correction = correctionByBlock[block.index]
            let split = splitByBlock[block.index]

            var evidence: [String] = [
                "failureCategory=\(block.failureCategory)",
                "blockPassed=\(block.blockPassed)",
                "groundTruthMatch=\(block.groundTruthMatch)",
                "groundTruthType=\(block.bestGroundTruthType ?? "nil")",
                "bubbleID=\(block.bubbleID.map(String.init) ?? "nil")",
                "wordOrderPreserved=\(block.wordOrderPreserved.map(String.init) ?? "nil")",
                "externalArtifactOptionalMissing=\(optionalExternalMissing)"
            ]
            if let similarity = block.ocrGroundTruthSimilarity {
                evidence.append("ocrSimilarity=\(similarity.formatted(.number.precision(.fractionLength(3))))")
            }
            if let crop {
                evidence.append("cropSelection=\(crop.selectionReason)")
                evidence.append("cropRejections=\(crop.rejectionReasons.joined(separator: ","))")
                evidence.append("cropFailureAttribution=\(crop.failureAttribution.joined(separator: ","))")
            }
            if let textBoxFailure {
                evidence.append("textBoxPlanFailure=\(textBoxFailure.primaryFailureCategory)")
                evidence.append("promotionBlockers=\(textBoxFailure.promotionBlockers.joined(separator: ","))")
                evidence.append("planRecommendedAction=\(textBoxFailure.recommendedNextAction)")
            }
            if let mask {
                evidence.append("maskBubbleIDConsistent=\(mask.bubbleIDConsistent)")
                evidence.append("maskDominantBubbleID=\(mask.maskDominantBubbleID.map(String.init) ?? "nil")")
                evidence.append("maskDominantCoverage=\(mask.maskDominantCoverageRatio.formatted(.number.precision(.fractionLength(3))))")
            }
            if let correction {
                evidence.append("bubbleAssignmentCorrection=\(correction.decision)")
                evidence.append("correctionRecommended=\(correction.correctionRecommended)")
            }
            if let split {
                evidence.append("splitCandidateID=\(split.id)")
                evidence.append("splitClampEligible=\(split.clampEligible)")
                evidence.append("splitRejections=\(split.rejectionReasons.joined(separator: ","))")
            }
            if let originalFusedIndex = postFusionOriginalFusedBlockIndex(in: block) {
                evidence.append("postFusionCleanupOriginalFusedBlockIndex=\(originalFusedIndex)")
                if postFusionRelatedKeptOriginalIndexes.contains(originalFusedIndex) {
                    evidence.append("postFusionCleanupKeptRelatedDuplicateOrFragment=true")
                }
            }

            let secondary = internalSecondaryBottlenecks(
                block: block,
                crop: crop,
                textBoxFailure: textBoxFailure,
                mask: mask,
                correction: correction,
                split: split,
                optionalExternalMissing: optionalExternalMissing
            )
            let primary = internalPrimaryBottleneck(
                block: block,
                secondary: secondary,
                crop: crop,
                textBoxFailure: textBoxFailure
            )
            let action = internalRecommendedAction(for: primary)
            let mustNotPromote = internalMustNotPromoteReasons(
                block: block,
                crop: crop,
                textBoxFailure: textBoxFailure,
                optionalExternalMissing: optionalExternalMissing
            )

            return MangaOverlayInternalStructureBottleneckBlock(
                blockIndex: block.index,
                groundTruthMatch: block.groundTruthMatch,
                groundTruthType: block.bestGroundTruthType,
                ocrGroundTruthSimilarity: block.ocrGroundTruthSimilarity,
                wordOrderPreserved: block.wordOrderPreserved,
                bubbleID: block.bubbleID,
                bbox: block.bbox,
                finalTextUsedForTranslation: block.finalTextUsedForTranslation,
                failureCategory: block.failureCategory,
                blockPassed: block.blockPassed,
                primaryBottleneck: primary,
                secondaryBottlenecks: secondary.filter { $0 != primary },
                recommendedNextAction: action,
                evidence: evidence,
                mustNotPromoteReasons: mustNotPromote
            )
        }

        let primaryBreakdown = countBy(summaries.map(\.primaryBottleneck))
        let actionBreakdown = countBy(summaries.map(\.recommendedNextAction))
        let dialogueBreakdown = countBy(
            summaries
                .filter { $0.groundTruthType == MangaGroundTruthEntry.dialogueType }
                .map(\.primaryBottleneck)
        )
        let decorativeBreakdown = countBy(
            summaries
                .filter { $0.groundTruthType == MangaGroundTruthEntry.decorativeType }
                .map(\.primaryBottleneck)
        )

        return MangaOverlayInternalStructureBottleneckReport(
            enabled: true,
            evaluatedBlockCount: summaries.count,
            primaryBottleneckBreakdown: primaryBreakdown,
            recommendedActionBreakdown: actionBreakdown,
            dialogueBottleneckBreakdown: dialogueBreakdown,
            decorativeBottleneckBreakdown: decorativeBreakdown,
            ocrInputSuspectBlocks: summaries.filter { $0.failureCategory == "ocrInputSuspect" || $0.primaryBottleneck == "ocrCharacterDamage" }.map(\.blockIndex).sorted(),
            duplicateOrFragmentBlocks: summaries.filter { $0.primaryBottleneck == "duplicateOrFragment" || $0.secondaryBottlenecks.contains("duplicateOrFragment") }.map(\.blockIndex).sorted(),
            modelTranslationQualityBlocks: summaries.filter { $0.primaryBottleneck == "modelTranslationQuality" || $0.secondaryBottlenecks.contains("modelTranslationQuality") }.map(\.blockIndex).sorted(),
            cropCandidateBlockedBlocks: summaries.filter { $0.primaryBottleneck == "cropCandidateBlocked" || $0.secondaryBottlenecks.contains("cropCandidateBlocked") }.map(\.blockIndex).sorted(),
            bubbleSplitOrAssignmentBlocks: summaries.filter { $0.primaryBottleneck == "bubbleAssignmentOrSplit" || $0.secondaryBottlenecks.contains("bubbleAssignmentOrSplit") }.map(\.blockIndex).sorted(),
            renderOnlyBlocks: summaries.filter { $0.primaryBottleneck == "renderOnly" }.map(\.blockIndex).sorted(),
            passedBlocks: summaries.filter(\.blockPassed).map(\.blockIndex).sorted(),
            postFusionRejectedDuplicateOrFragmentBlocks: Array(postFusionRejectedDuplicateOriginalIndexes).sorted(),
            blockSummaries: summaries,
            notes: [
                "internalStructureBottleneckReport aggregates existing probe evidence and does not replace finalTextUsedForTranslation",
                "ground truth is used only for evaluation fields such as similarity and type, not for production candidate selection",
                "external artifact manifestMissing is treated as optional missing input and does not block the internal routing report"
            ]
        )
    }

    private static func internalSecondaryBottlenecks(
        block: MangaOverlayProbeBlock,
        crop: MangaOverlayTextRegionCropDiagnostic?,
        textBoxFailure: MangaOverlayTextBoxPlanFailureBlockSummary?,
        mask: MangaOverlayBubbleMaskBlockDiagnostic?,
        correction: MangaOverlayBubbleAssignmentCorrectionDiagnostic?,
        split: MangaOverlayBubbleSplitCandidateDiagnostic?,
        optionalExternalMissing: Bool
    ) -> [String] {
        var result: [String] = []
        if block.blockPassed {
            result.append("passed")
        }
        if looksLikeInternalDuplicateOrFragment(block) {
            result.append("duplicateOrFragment")
        }
        if block.failureCategory == "ocrInputSuspect"
            || (block.ocrGroundTruthSimilarity ?? 1) < 0.72
            || block.wordOrderPreserved == false
            || containsLikelyOCRError(in: block.finalTextUsedForTranslation) {
            result.append("ocrCharacterDamage")
        }
        if block.failureCategory == "modelOutputFailure"
            || block.failureCategory == "translationLanguageQualityFailure" {
            result.append("modelTranslationQuality")
        }
        if let textBoxFailure,
           textBoxFailure.bestShadowBetterThanControl || !textBoxFailure.promotionBlockers.isEmpty {
            result.append("cropCandidateBlocked")
        } else if let crop,
                  crop.rejectionReasons.contains(where: { ["rawWordsLost", "emptyCropText", "wordCountRegression", "introducedLikelyOCRError"].contains($0) }) {
            result.append("cropCandidateBlocked")
        }
        if mask?.bubbleIDConsistent == false
            || correction?.correctionRecommended == true
            || split?.clampEligible == true
            || block.crossBubbleMergeRejected {
            result.append("bubbleAssignmentOrSplit")
        }
        if block.blockPassed,
           block.renderCollisionChecked,
           block.renderCollisionResolved,
           !block.renderTextTruncated {
            result.append("renderOnly")
        }
        if optionalExternalMissing {
            result.append("externalArtifactOptionalMissing")
        }
        return Array(Set(result)).sorted()
    }

    private static func internalPrimaryBottleneck(
        block: MangaOverlayProbeBlock,
        secondary: [String],
        crop: MangaOverlayTextRegionCropDiagnostic?,
        textBoxFailure: MangaOverlayTextBoxPlanFailureBlockSummary?
    ) -> String {
        if block.blockPassed {
            if block.bestGroundTruthType == MangaGroundTruthEntry.decorativeType {
                return "passed"
            }
            return "passed"
        }
        if looksLikeInternalDuplicateOrFragment(block) {
            return "duplicateOrFragment"
        }
        if secondary.contains("modelTranslationQuality"),
           !(secondary.contains("ocrCharacterDamage") && block.failureCategory == "ocrInputSuspect") {
            return "modelTranslationQuality"
        }
        if let textBoxFailure,
           textBoxFailure.bestShadowBetterThanControl,
           textBoxFailure.promotionBlockers.contains(where: { ["qualityDeltaBelowOrEqual0.08", "wordPreservationRatioBelow0.80", "rawWordsLost"].contains($0) }) {
            return "cropCandidateBlocked"
        }
        if crop?.failureAttribution.contains("bubbleMaskConflict") == true || secondary.contains("bubbleAssignmentOrSplit") {
            return "bubbleAssignmentOrSplit"
        }
        if secondary.contains("ocrCharacterDamage") {
            return "ocrCharacterDamage"
        }
        if secondary.contains("cropCandidateBlocked") {
            return "cropCandidateBlocked"
        }
        return "unknown"
    }

    private static func internalRecommendedAction(for primary: String) -> String {
        switch primary {
        case "passed":
            "noActionPassed"
        case "duplicateOrFragment":
            "tryPostFusionFragmentSuppression"
        case "ocrCharacterDamage":
            "improveTextBoxOrSegmentEvidence"
        case "bubbleAssignmentOrSplit":
            "improveBubbleSplitOrAssignment"
        case "cropCandidateBlocked":
            "keepMainTextAndDoNotTuneGeometry"
        case "modelTranslationQuality":
            "tryPromptOrModelComparison"
        case "renderOnly":
            "renderNoAction"
        case "externalArtifactOptionalMissing":
            "noActionExternalArtifactOptional"
        default:
            "manualReview"
        }
    }

    private static func internalMustNotPromoteReasons(
        block: MangaOverlayProbeBlock,
        crop: MangaOverlayTextRegionCropDiagnostic?,
        textBoxFailure: MangaOverlayTextBoxPlanFailureBlockSummary?,
        optionalExternalMissing: Bool
    ) -> [String] {
        var reasons = [
            "groundTruthNotAllowedForSelection",
            "reportOnlyDoesNotChangeMainInput"
        ]
        if let crop, !crop.adopted {
            reasons.append(contentsOf: crop.rejectionReasons.map { "cropRejected:\($0)" })
        }
        if let textBoxFailure {
            reasons.append(contentsOf: textBoxFailure.promotionBlockers.map { "promotionBlocked:\($0)" })
        }
        if optionalExternalMissing {
            reasons.append("externalArtifactOptionalMissing")
        }
        if block.bestGroundTruthType == MangaGroundTruthEntry.decorativeType {
            reasons.append("decorativeTitleProtected")
        }
        return Array(Set(reasons)).sorted()
    }

    private func makeRoutingDrivenTranslationComparisonReport(
        blocks: [MangaOverlayProbeBlock],
        internalStructureBottleneckReport: MangaOverlayInternalStructureBottleneckReport
    ) async -> MangaRoutingDrivenTranslationComparisonReport {
        let variantID = "strictChineseOnlyV1"
        let routedByBlock = Dictionary(
            uniqueKeysWithValues: internalStructureBottleneckReport.blockSummaries.map { ($0.blockIndex, $0) }
        )
        let targets = blocks
            .filter { block in
                routedByBlock[block.index]?.primaryBottleneck == "modelTranslationQuality"
            }
            .sorted { lhs, rhs in
                let lhsPassed = lhs.blockPassed ? 1 : 0
                let rhsPassed = rhs.blockPassed ? 1 : 0
                if lhsPassed != rhsPassed { return lhsPassed < rhsPassed }
                return lhs.index < rhs.index
            }
            .prefix(5)

        var cases: [MangaRoutingDrivenTranslationComparisonCase] = []
        for block in targets {
            guard let routing = routedByBlock[block.index] else { continue }
            let prompt = Self.strictChineseOnlyPrompt(for: block.finalTextUsedForTranslation)
            let rawOutput: String
            let errorCode: String?
            if selectedEngine == .local {
                let probe = localService.rawProbe(prompt: prompt, maxTokens: min(max(96, block.finalTextUsedForTranslation.count * 2), 220))
                rawOutput = probe.output
                errorCode = probe.errorCode
            } else {
                let request = makeProbeRequest(source: .englishUS, target: .simplifiedChinese, input: prompt)
                do {
                    try await mockService.prepare()
                    let result = try await mockService.generate(request)
                    rawOutput = result.text
                    errorCode = nil
                } catch {
                    rawOutput = ""
                    errorCode = "\(type(of: error)): \(error.localizedDescription)"
                }
            }

            let extraction = Self.extractMangaProbeTranslationCandidate(rawOutput)
            let candidate = extraction.candidate
            let rawClassification = Self.classifyMangaProbeRawOutput(rawOutput, original: block.finalTextUsedForTranslation)
            let candidateClassification = Self.classifyMangaProbeCandidate(
                candidate,
                original: block.finalTextUsedForTranslation,
                rejectedPlaceholder: extraction.rejectedPlaceholder
            )
            let checks = mangaProbeChecks(
                original: block.finalTextUsedForTranslation,
                translation: candidate,
                errorCode: errorCode
            )
            let baseReasons = mangaProbeFailureReasons(
                checks: checks,
                errorCode: errorCode,
                original: block.finalTextUsedForTranslation,
                translation: candidate
            )
            let checksPassed = Self.mangaProbeBlockPassed(checks, errorCode: errorCode)
            let languageReason = checksPassed ? Self.mangaProbeTranslationLanguageQualityIssue(
                original: block.finalTextUsedForTranslation,
                candidate: candidate,
                rawOutput: rawOutput,
                rawClassification: rawClassification
            ) : nil
            let variantFailureReasons = baseReasons + [languageReason].compactMap { $0 }
            let variantPassed = checksPassed && languageReason == nil
            let latinLeakReduced = Self.latinLetterCount(in: candidate) < Self.latinLetterCount(in: block.translationCandidate)
            let emptyOutputFixed = block.candidateClassification == "empty" && !candidate.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            let controlWasPlaceholder = block.candidateClassification == "placeholder"
                || block.candidateClassification == "placeholderRejected"
            let placeholderFixed = controlWasPlaceholder
                && candidateClassification != "empty"
                && candidateClassification != "placeholder"
                && candidateClassification != "placeholderRejected"
            let shortChineseFixed = Self.isShortChineseFailure(block) && !Self.isShortChineseCandidate(candidate, original: block.finalTextUsedForTranslation)
            let improvement = Self.routingTranslationImprovementCategory(
                control: block,
                variantPassed: variantPassed,
                variantFailureReasons: variantFailureReasons,
                variantRawClassification: rawClassification,
                variantCandidateClassification: candidateClassification,
                latinLeakReduced: latinLeakReduced,
                emptyOutputFixed: emptyOutputFixed,
                placeholderFixed: placeholderFixed,
                shortChineseFixed: shortChineseFixed
            )
            var mustNotPromote = routing.mustNotPromoteReasons
            mustNotPromote.append("diagnosticOnlyStrictPromptDoesNotReplaceMainTranslation")
            mustNotPromote.append("mainProbePromptUnchanged")

            cases.append(MangaRoutingDrivenTranslationComparisonCase(
                blockIndex: block.index,
                routingPrimaryBottleneck: routing.primaryBottleneck,
                routingRecommendedAction: routing.recommendedNextAction,
                sourceText: block.finalTextUsedForTranslation,
                controlCandidate: block.translationCandidate,
                controlPassed: block.blockPassed,
                controlFailureCategory: block.failureCategory,
                controlFailureReasons: block.failureReasons,
                variantID: variantID,
                variantPrompt: prompt,
                variantRawOutput: rawOutput,
                variantCandidate: candidate,
                variantRawOutputClassification: rawClassification,
                variantCandidateClassification: candidateClassification,
                variantPassed: variantPassed,
                variantFailureReasons: variantFailureReasons,
                improvementCategory: improvement,
                latinLeakReduced: latinLeakReduced,
                emptyOutputFixed: emptyOutputFixed,
                placeholderFixed: placeholderFixed,
                shortChineseFixed: shortChineseFixed,
                diagnosticOnly: true,
                mustNotPromoteReasons: Array(Set(mustNotPromote)).sorted()
            ))
        }

        return MangaRoutingDrivenTranslationComparisonReport(
            enabled: true,
            decodingMode: selectedEngine == .local ? ModelDecodingProfile.deterministic.mode : "mock",
            decodingSeed: selectedEngine == .local ? ModelDecodingProfile.deterministic.seed : nil,
            variantID: variantID,
            candidateSelectionRule: "Select first five final blocks whose internalStructureBottleneckReport.primaryBottleneck == modelTranslationQuality; no ground truth is read for sample selection.",
            evaluatedCaseCount: cases.count,
            targetBlockIndexes: cases.map(\.blockIndex).sorted(),
            controlPassedCount: cases.filter(\.controlPassed).count,
            variantPassedCount: cases.filter(\.variantPassed).count,
            passedButControlFailedBlocks: cases.filter { !$0.controlPassed && $0.variantPassed }.map(\.blockIndex).sorted(),
            worseThanControlBlocks: cases.filter { $0.controlPassed && !$0.variantPassed }.map(\.blockIndex).sorted(),
            emptyOutputFixedBlocks: cases.filter(\.emptyOutputFixed).map(\.blockIndex).sorted(),
            placeholderFixedBlocks: cases.filter(\.placeholderFixed).map(\.blockIndex).sorted(),
            latinLeakReducedBlocks: cases.filter(\.latinLeakReduced).map(\.blockIndex).sorted(),
            improvementBreakdown: Self.countBy(cases.map(\.improvementCategory)),
            cases: cases,
            notes: [
                "report-only strict prompt comparison; main block translationCandidate, blockPassed, failureCategory, decision trace, and overlay are unchanged",
                "variant uses existing candidate extraction, raw/candidate classification, checks, failure reasons, and language quality gate"
            ]
        )
    }

    private static func strictChineseOnlyPrompt(for sourceText: String) -> String {
        """
        把以下英文漫画台词翻译成简体中文。
        只输出中文译文，不要解释，不要列点，不要重复英文原文。
        如果出现 Senpai、Ren、City Battler、Tournament 等专有名词，请用自然中文或音译处理，不要原样保留英文短语。
        原文：
        \(sourceText)
        """
    }

    private static func routingTranslationImprovementCategory(
        control: MangaOverlayProbeBlock,
        variantPassed: Bool,
        variantFailureReasons: [String],
        variantRawClassification: String,
        variantCandidateClassification: String,
        latinLeakReduced: Bool,
        emptyOutputFixed: Bool,
        placeholderFixed: Bool,
        shortChineseFixed: Bool
    ) -> String {
        if control.blockPassed && !variantPassed {
            return "worseThanControl"
        }
        if variantPassed && !control.blockPassed {
            return "passedButControlFailed"
        }
        if emptyOutputFixed {
            return "fixedEmptyOutput"
        }
        if placeholderFixed {
            return "fixedPlaceholder"
        }
        if latinLeakReduced {
            return "fixedLatinLeak"
        }
        if shortChineseFixed {
            return "fixedShortChinese"
        }
        if variantRawClassification == "empty" || variantCandidateClassification == "empty"
            || variantRawClassification == "placeholder"
            || variantCandidateClassification == "placeholder"
            || variantCandidateClassification == "placeholderRejected"
            || variantRawClassification == "repeatedOriginal"
            || variantCandidateClassification == "repeatedOriginal"
            || variantRawClassification == "nonChinese"
            || variantCandidateClassification == "nonChinese"
            || variantRawClassification == "symbolsOnly" {
            return "stillModelOutputFailure"
        }
        if !variantPassed,
           variantFailureReasons.contains(where: { $0.contains("过短") || $0.contains("拉丁") || $0.contains("英文") || $0.contains("解释") || $0.contains("泛化") }) {
            return "stillTranslationLanguageQualityFailure"
        }
        return "noChange"
    }

    private static func isShortChineseFailure(_ block: MangaOverlayProbeBlock) -> Bool {
        block.failureReasons.contains(where: { $0.contains("过短") })
            || block.translationFailureDetail?.contains("过短") == true
            || block.qualityNotes.contains(where: { $0.contains("translationLanguageQualityIssue=多词原文只得到过短中文候选") || $0.contains("translationLanguageQualityIssue=长原文只得到过短中文候选") })
    }

    private static func isShortChineseCandidate(_ candidate: String, original: String) -> Bool {
        let sourceWords = ocrCandidateWords(original).filter { $0.count >= 3 }
        let cjkCount = cjkCharacterCount(in: candidate)
        return (sourceWords.count >= 3 && cjkCount <= 2) || (sourceWords.count >= 5 && cjkCount <= 4)
    }

    private static func makeOCRCharacterDamageAuditReport(
        blocks: [MangaOverlayProbeBlock],
        internalStructureBottleneckReport: MangaOverlayInternalStructureBottleneckReport,
        textRegionCropReport: MangaOverlayTextRegionCropReport?,
        textBoxCandidateReport: MangaOverlayTextBoxCandidateReport?,
        segmentMaskReport: MangaOverlaySegmentMaskReport?,
        textBoxPlanFailureReport: MangaOverlayTextBoxPlanFailureReport?
    ) -> MangaOCRCharacterDamageAuditReport {
        let routedByBlock = Dictionary(
            uniqueKeysWithValues: internalStructureBottleneckReport.blockSummaries.map { ($0.blockIndex, $0) }
        )
        let textRegionByBlock = Dictionary(
            uniqueKeysWithValues: (textRegionCropReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let textBoxByBlock = Dictionary(
            uniqueKeysWithValues: (textBoxCandidateReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let segmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentMaskReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let failureByBlock = Dictionary(
            uniqueKeysWithValues: (textBoxPlanFailureReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )

        let cases = blocks
            .filter { block in
                routedByBlock[block.index]?.primaryBottleneck == "ocrCharacterDamage"
                    || block.failureCategory == "ocrInputSuspect"
                    || (block.ocrGroundTruthSimilarity ?? 1) < 0.72
            }
            .map { block -> MangaOCRCharacterDamageAuditCase in
                let audit = Self.ocrDamageTokenAudit(
                    ocrText: block.finalTextUsedForTranslation,
                    groundTruthText: block.bestGroundTruthText
                )
                let textRegion = textRegionByBlock[block.index]
                let textBox = textBoxByBlock[block.index]
                let segment = segmentByBlock[block.index]
                let failure = failureByBlock[block.index]
                let cropBlockers = Self.ocrDamageCropBlockers(textRegion: textRegion, textBoxFailure: failure)
                let action = Self.ocrDamageRecommendedAction(
                    block: block,
                    audit: audit,
                    cropBlockers: cropBlockers,
                    textBox: textBox,
                    segment: segment,
                    routing: routedByBlock[block.index]
                )
                var mustNotPromote = routedByBlock[block.index]?.mustNotPromoteReasons ?? []
                mustNotPromote.append("diagnosticOnlyDoesNotReplaceFinalTextUsedForTranslation")
                mustNotPromote.append("groundTruthUsedOnlyForDamageAudit")
                if action == "doNotTuneCropFurther" {
                    mustNotPromote.append("v20LineDeskewPathAlreadyStopped")
                }

                return MangaOCRCharacterDamageAuditCase(
                    blockIndex: block.index,
                    groundTruthMatch: block.groundTruthMatch,
                    groundTruthType: block.bestGroundTruthType,
                    ocrGroundTruthSimilarity: block.ocrGroundTruthSimilarity,
                    wordOrderPreserved: block.wordOrderPreserved,
                    finalTextUsedForTranslation: block.finalTextUsedForTranslation,
                    bestGroundTruthText: block.bestGroundTruthText,
                    damagedTokens: audit.damagedTokens,
                    missingGroundTruthTokens: audit.missingGroundTruthTokens,
                    extraOcrTokens: audit.extraOcrTokens,
                    suspectedSubstitutions: audit.suspectedSubstitutions,
                    repeatedKeywordDamage: audit.repeatedKeywordDamage,
                    lineBreakRisk: Self.ocrLineBreakRisk(block.finalTextUsedForTranslation),
                    bubbleID: block.bubbleID,
                    textBoxEvidenceSummary: Self.textBoxEvidenceSummary(textBox),
                    segmentMaskEvidenceSummary: Self.segmentMaskEvidenceSummary(segment),
                    cropBlockers: cropBlockers,
                    recommendedNextAction: action,
                    diagnosticOnly: true,
                    mustNotPromoteReasons: Array(Set(mustNotPromote)).sorted()
                )
            }

        return MangaOCRCharacterDamageAuditReport(
            enabled: true,
            evaluatedBlockCount: cases.count,
            targetBlockIndexes: cases.map(\.blockIndex).sorted(),
            damageTokenFrequency: Self.countFrequency(cases.flatMap(\.damagedTokens)),
            missingTokenFrequency: Self.countFrequency(cases.flatMap(\.missingGroundTruthTokens)),
            substitutionFrequency: Self.countFrequency(cases.flatMap(\.suspectedSubstitutions)),
            repeatedKeywordDamage: Self.countFrequency(cases.flatMap(\.repeatedKeywordDamage)),
            lineBreakRiskBlocks: cases.filter(\.lineBreakRisk).map(\.blockIndex).sorted(),
            cropBlockedBlocks: cases.filter { !$0.cropBlockers.isEmpty }.map(\.blockIndex).sorted(),
            textBoxOrSegmentEvidenceBlocks: cases.filter {
                ($0.textBoxEvidenceSummary?.isEmpty == false) || ($0.segmentMaskEvidenceSummary?.isEmpty == false)
            }.map(\.blockIndex).sorted(),
            recommendedActionBreakdown: Self.countBy(cases.map(\.recommendedNextAction)),
            cases: cases,
            notes: [
                "ground truth is used only for probe damage analysis, never for production OCR candidate selection or promotion",
                "audit explains token substitutions, missing tokens, extra OCR tokens, line break risk, crop blockers, and TextBox/SegmentMask proxy evidence"
            ]
        )
    }

    private struct OCRDamageTokenAudit {
        var damagedTokens: [String]
        var missingGroundTruthTokens: [String]
        var extraOcrTokens: [String]
        var suspectedSubstitutions: [String]
        var repeatedKeywordDamage: [String]
    }

    private static func ocrDamageTokenAudit(ocrText: String, groundTruthText: String?) -> OCRDamageTokenAudit {
        let ocrTokens = ocrCandidateWords(ocrText)
        let truthTokens = ocrCandidateWords(groundTruthText ?? "")
        let ocrSet = Set(ocrTokens)
        let truthSet = Set(truthTokens)
        let missing = truthTokens.filter { !ocrSet.contains($0) }
        let extra = ocrTokens.filter { !truthSet.contains($0) }
        var substitutions: [String] = []
        var damaged: [String] = []
        for ocrToken in extra {
            guard let truthToken = missing
                .filter({ abs($0.count - ocrToken.count) <= 3 })
                .max(by: { normalizedTextSimilarity(ocrToken, $0) < normalizedTextSimilarity(ocrToken, $1) }) else {
                continue
            }
            let similarity = normalizedTextSimilarity(ocrToken, truthToken)
            if similarity >= 0.34 {
                substitutions.append("\(ocrToken.uppercased())->\(truthToken.uppercased())")
                damaged.append(ocrToken.uppercased())
            }
        }
        let tracked = ["battler", "tournament", "few", "and", "training", "this", "gaming", "club", "being", "logic", "results"]
        let repeatedKeywordDamage = tracked.filter { keyword in
            truthSet.contains(keyword) && !ocrSet.contains(keyword)
        }
        return OCRDamageTokenAudit(
            damagedTokens: Array(Set(damaged)).sorted(),
            missingGroundTruthTokens: Array(Set(missing.map { $0.uppercased() })).sorted(),
            extraOcrTokens: Array(Set(extra.map { $0.uppercased() })).sorted(),
            suspectedSubstitutions: Array(Set(substitutions)).sorted(),
            repeatedKeywordDamage: repeatedKeywordDamage.map { $0.uppercased() }.sorted()
        )
    }

    private static func ocrDamageCropBlockers(
        textRegion: MangaOverlayTextRegionCropDiagnostic?,
        textBoxFailure: MangaOverlayTextBoxPlanFailureBlockSummary?
    ) -> [String] {
        var blockers: [String] = []
        if let textRegion {
            blockers.append(contentsOf: textRegion.rejectionReasons)
            blockers.append(contentsOf: textRegion.failureAttribution)
            if let cropMaskRejectedReason = textRegion.cropMaskRejectedReason {
                blockers.append(cropMaskRejectedReason)
            }
            if let assignmentCorrectionRejectedReason = textRegion.assignmentCorrectionRejectedReason {
                blockers.append(assignmentCorrectionRejectedReason)
            }
            if let splitCandidateRejectedReason = textRegion.splitCandidateRejectedReason {
                blockers.append(splitCandidateRejectedReason)
            }
        }
        if let textBoxFailure {
            blockers.append(contentsOf: textBoxFailure.promotionBlockers)
            blockers.append(textBoxFailure.primaryFailureCategory)
        }
        return Array(Set(blockers.filter { !$0.isEmpty })).sorted()
    }

    private static func ocrDamageRecommendedAction(
        block: MangaOverlayProbeBlock,
        audit: OCRDamageTokenAudit,
        cropBlockers: [String],
        textBox: MangaOverlayTextBoxCandidateDiagnostic?,
        segment: MangaOverlaySegmentMaskDiagnostic?,
        routing: MangaOverlayInternalStructureBottleneckBlock?
    ) -> String {
        if routing?.primaryBottleneck == "modelTranslationQuality" || block.failureCategory == "modelOutputFailure" {
            return "promptComparisonOnly"
        }
        if cropBlockers.contains(where: {
            ["qualityDeltaBelowOrEqual0.08", "wordPreservationRatioBelow0.80", "wordCountRegression", "rawWordsLost", "introducedLikelyOCRError"].contains($0)
        }) {
            return "doNotTuneCropFurther"
        }
        if textBox?.eligibleForCrop == true || segment?.usableForCropEvidence == true {
            return "needsBetterTextBoxOrSegmentEvidence"
        }
        if block.crossBubbleMergeRejected || block.bubbleID == nil {
            return "needsBubbleSplitOrAssignmentReview"
        }
        if !audit.suspectedSubstitutions.isEmpty || !audit.repeatedKeywordDamage.isEmpty {
            return "needsOCRModelOrEngineComparison"
        }
        return "manualReview"
    }

    private static func textBoxEvidenceSummary(_ diagnostic: MangaOverlayTextBoxCandidateDiagnostic?) -> String? {
        guard let diagnostic else { return nil }
        return "id=\(diagnostic.id) source=\(diagnostic.source) eligible=\(diagnostic.eligibleForCrop) score=\(diagnostic.evidenceScore.formatted(.number.precision(.fractionLength(3)))) rejections=\(diagnostic.rejectionReasons.joined(separator: ",")) risks=\(diagnostic.riskFlags.joined(separator: ","))"
    }

    private static func segmentMaskEvidenceSummary(_ diagnostic: MangaOverlaySegmentMaskDiagnostic?) -> String? {
        guard let diagnostic else { return nil }
        return "pixels=\(diagnostic.glyphMaskPixelCount) usableForCropEvidence=\(diagnostic.usableForCropEvidence) textBoxCoverage=\(diagnostic.textBoxCoverageRatio?.formatted(.number.precision(.fractionLength(3))) ?? "nil") bubbleCoverage=\(diagnostic.bubbleMaskCoverageRatio?.formatted(.number.precision(.fractionLength(3))) ?? "nil") rejections=\(diagnostic.rejectionReasons.joined(separator: ","))"
    }

    private static func ocrLineBreakRisk(_ text: String) -> Bool {
        let lines = text
            .split(separator: "\n", omittingEmptySubsequences: false)
            .map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        guard lines.count >= 3 else { return false }
        let shortLines = lines.filter { ocrCandidateWords($0).count <= 2 }.count
        return shortLines >= max(2, lines.count / 2)
    }

    private static func countFrequency(_ values: [String]) -> [String: Int] {
        values.reduce(into: [:]) { partial, value in
            partial[value, default: 0] += 1
        }
    }

    private static func makeReadingOrderStructureAuditReport(
        blocks: [MangaOverlayProbeBlock],
        bubbleMaskReport: MangaOverlayBubbleMaskReport?,
        bubbleAssignmentCorrectionReport: MangaOverlayBubbleAssignmentCorrectionReport?,
        bubbleSplitCandidateReport: MangaOverlayBubbleSplitCandidateReport?,
        textBoxCandidateReport: MangaOverlayTextBoxCandidateReport?,
        segmentMaskReport: MangaOverlaySegmentMaskReport?,
        textBoxPlanFailureReport: MangaOverlayTextBoxPlanFailureReport?,
        internalStructureBottleneckReport: MangaOverlayInternalStructureBottleneckReport?,
        postFusionCleanup: MangaOverlayPostFusionCleanupReport?
    ) -> MangaReadingOrderStructureAuditReport {
        let maskByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleMaskReport?.blockDiagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let correctionByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleAssignmentCorrectionReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        var splitByBlock: [Int: MangaOverlayBubbleSplitCandidateDiagnostic] = [:]
        for diagnostic in bubbleSplitCandidateReport?.diagnostics ?? [] {
            for blockIndex in diagnostic.seedBlockIndexes where splitByBlock[blockIndex] == nil {
                splitByBlock[blockIndex] = diagnostic
            }
        }
        let textBoxByBlock = Dictionary(
            uniqueKeysWithValues: (textBoxCandidateReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let segmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentMaskReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let failureByBlock = Dictionary(
            uniqueKeysWithValues: (textBoxPlanFailureReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let routingByBlock = Dictionary(
            uniqueKeysWithValues: (internalStructureBottleneckReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let rejectedOriginalIndexes = Set((postFusionCleanup?.rejectedBlocks ?? []).map(\.originalFusedBlockIndex))
        let relatedKeptOriginalIndexes = Set((postFusionCleanup?.rejectedBlocks ?? []).compactMap(\.relatedFusedBlockIndex))
        let proposedOrder = readingOrderSortedBlockIndexes(blocks)
        let proposedRankByBlock = Dictionary(uniqueKeysWithValues: proposedOrder.enumerated().map { ($0.element, $0.offset) })
        let groupIDsByBlock = Dictionary(uniqueKeysWithValues: blocks.map { block in
            (block.index, readingOrderBubbleGroupID(block: block, mask: maskByBlock[block.index]))
        })
        let groupMembers = Dictionary(grouping: blocks, by: { groupIDsByBlock[$0.index] ?? "unassigned:\($0.index)" })
            .mapValues { $0.map(\.index).sorted() }

        let cases = blocks.map { block -> MangaReadingOrderStructureAuditCase in
            let mask = maskByBlock[block.index]
            let correction = correctionByBlock[block.index]
            let split = splitByBlock[block.index]
            let textBox = textBoxByBlock[block.index]
            let segment = segmentByBlock[block.index]
            let failure = failureByBlock[block.index]
            let routing = routingByBlock[block.index]
            let groupID = groupIDsByBlock[block.index] ?? "unassigned:\(block.index)"
            let siblings = (groupMembers[groupID] ?? [])
                .filter { $0 != block.index }
            let currentOrderIndex = blocks.firstIndex(where: { $0.index == block.index }) ?? block.index
            let proposedIndex = proposedRankByBlock[block.index] ?? currentOrderIndex
            let bubbleRisk = readingOrderBubbleAssignmentRisk(block: block, mask: mask, correction: correction, split: split)
            let splitRisk = readingOrderSplitOrMergeRisk(block: block, siblingIndexes: siblings, split: split)
            let duplicateRisk = readingOrderDuplicateOrFragmentRisk(
                block: block,
                rejectedOriginalIndexes: rejectedOriginalIndexes,
                relatedKeptOriginalIndexes: relatedKeptOriginalIndexes
            )
            let decorativeProtected = block.bestGroundTruthType == MangaGroundTruthEntry.decorativeType
                || isPostFusionDecorativeTitleText(block.finalTextUsedForTranslation)
            let keyProtected = isProtectedShortPostFusionText(block.finalTextUsedForTranslation)
            let textBoxEvidence = readingOrderTextBoxEvidenceLevel(textBox, failure: failure)
            let segmentEvidence = readingOrderSegmentMaskEvidenceLevel(segment)
            let confidence = readingOrderConfidence(
                block: block,
                proposedOrderChanged: proposedIndex != currentOrderIndex,
                siblingIndexes: siblings,
                bubbleRisk: bubbleRisk,
                splitRisk: splitRisk,
                duplicateRisk: duplicateRisk,
                textBoxEvidence: textBoxEvidence,
                segmentEvidence: segmentEvidence,
                decorativeProtected: decorativeProtected
            )
            let riskFlags = readingOrderRiskFlags(
                orderChanged: proposedIndex != currentOrderIndex,
                confidence: confidence,
                bubbleRisk: bubbleRisk,
                splitRisk: splitRisk,
                duplicateRisk: duplicateRisk,
                textBoxEvidence: textBoxEvidence,
                segmentEvidence: segmentEvidence,
                decorativeProtected: decorativeProtected,
                keyProtected: keyProtected
            )
            let action = readingOrderRecommendedStructureAction(
                block: block,
                orderChanged: proposedIndex != currentOrderIndex,
                confidence: confidence,
                bubbleRisk: bubbleRisk,
                splitRisk: splitRisk,
                duplicateRisk: duplicateRisk,
                textBoxEvidence: textBoxEvidence,
                segmentEvidence: segmentEvidence,
                decorativeProtected: decorativeProtected,
                keyProtected: keyProtected
            )
            var mustNotPromote = routing?.mustNotPromoteReasons ?? []
            mustNotPromote.append("diagnosticOnlyDoesNotChangeBlockOrder")
            mustNotPromote.append("diagnosticOnlyDoesNotReplaceFinalTextUsedForTranslation")
            mustNotPromote.append("groundTruthUsedOnlyForEvaluationFields")
            if proposedIndex != currentOrderIndex {
                mustNotPromote.append("proposedReadingOrderNotAppliedToBlocks")
            }
            if decorativeProtected {
                mustNotPromote.append("decorativeTitleProtected")
            }
            if keyProtected {
                mustNotPromote.append("keyDialogueProtected")
            }

            return MangaReadingOrderStructureAuditCase(
                blockIndex: block.index,
                currentOrderIndex: currentOrderIndex,
                proposedReadingOrderIndex: proposedIndex,
                orderChanged: proposedIndex != currentOrderIndex,
                orderConfidence: confidence,
                orderRiskFlags: riskFlags,
                bubbleID: block.bubbleID,
                maskDominantBubbleID: mask?.maskDominantBubbleID,
                bubbleIDConsistent: mask?.bubbleIDConsistent ?? (block.bubbleID != nil),
                bubbleGroupID: groupID,
                sameBubbleSiblingBlockIndexes: siblings,
                bbox: block.bbox,
                safeLayoutRect: block.safeLayoutRect,
                groundTruthMatch: block.groundTruthMatch,
                groundTruthType: block.bestGroundTruthType,
                ocrGroundTruthSimilarity: block.ocrGroundTruthSimilarity,
                finalTextUsedForTranslation: block.finalTextUsedForTranslation,
                primaryBottleneck: routing?.primaryBottleneck,
                translationFailureCategory: block.failureCategory,
                textBoxEvidenceLevel: textBoxEvidence,
                segmentMaskEvidenceLevel: segmentEvidence,
                bubbleAssignmentRisk: bubbleRisk,
                splitOrMergeRisk: splitRisk,
                duplicateOrFragmentRisk: duplicateRisk,
                decorativeProtectionApplied: decorativeProtected,
                recommendedStructureAction: action,
                diagnosticOnly: true,
                mustNotPromoteReasons: Array(Set(mustNotPromote)).sorted()
            )
        }

        let multiGroups = groupMembers.filter { key, value in
            value.count > 1 && !key.hasPrefix("unassigned:")
        }

        return MangaReadingOrderStructureAuditReport(
            enabled: true,
            evaluatedBlockCount: cases.count,
            currentOrderRule: "Final blocks array order from fusedWholePageBubble/post-fusion cleanup; unchanged by this report.",
            proposedOrderRule: "Ground-truth-free visual order: centerY row bucketing, same row by centerX, same bubble/mask group kept local; only proposedReadingOrderIndex is reported.",
            orderChangedBlocks: cases.filter(\.orderChanged).map(\.blockIndex).sorted(),
            lowConfidenceOrderBlocks: cases.filter { $0.orderConfidence < 0.68 }.map(\.blockIndex).sorted(),
            bubbleGroupCount: groupMembers.count,
            multiBlockBubbleGroups: multiGroups,
            unassignedBlocks: cases.filter { $0.bubbleAssignmentRisk == "unassigned" }.map(\.blockIndex).sorted(),
            maskConflictBlocks: cases.filter { $0.bubbleAssignmentRisk == "maskConflict" || $0.bubbleAssignmentRisk == "lowMaskCoverage" }.map(\.blockIndex).sorted(),
            correctionRecommendedBlocks: cases.filter { $0.bubbleAssignmentRisk == "correctionRecommended" }.map(\.blockIndex).sorted(),
            splitRiskBlocks: cases.filter { $0.splitOrMergeRisk != "none" }.map(\.blockIndex).sorted(),
            duplicateOrFragmentRiskBlocks: cases.filter { $0.duplicateOrFragmentRisk != "none" && $0.duplicateOrFragmentRisk != "protectedTextDoNotDelete" }.map(\.blockIndex).sorted(),
            decorativeProtectedBlocks: cases.filter(\.decorativeProtectionApplied).map(\.blockIndex).sorted(),
            keyDialogueProtectedBlocks: cases.filter { $0.mustNotPromoteReasons.contains("keyDialogueProtected") }.map(\.blockIndex).sorted(),
            textBoxEvidenceBreakdown: countBy(cases.map(\.textBoxEvidenceLevel)),
            segmentMaskEvidenceBreakdown: countBy(cases.map(\.segmentMaskEvidenceLevel)),
            bubbleAssignmentRiskBreakdown: countBy(cases.map(\.bubbleAssignmentRisk)),
            splitOrMergeRiskBreakdown: countBy(cases.map(\.splitOrMergeRisk)),
            duplicateOrFragmentRiskBreakdown: countBy(cases.map(\.duplicateOrFragmentRisk)),
            recommendedStructureActionBreakdown: countBy(cases.map(\.recommendedStructureAction)),
            cases: cases,
            notes: [
                "readingOrderStructureAuditReport is report-only and does not reorder blocks, batch input, overlay drawing, translation, cleanup, or pass/fail decisions",
                "proposed reading order uses bbox and bubble/mask grouping signals only; ground truth fields remain diagnostic evaluation fields",
                "decorative titles and protected key dialogue can be marked protected or manual review but are not suggested as deletable"
            ]
        )
    }

    private static func makeStructureActionCandidateReport(
        blocks: [MangaOverlayProbeBlock],
        readingOrderStructureAuditReport: MangaReadingOrderStructureAuditReport?,
        internalStructureBottleneckReport: MangaOverlayInternalStructureBottleneckReport?,
        bubbleMaskReport: MangaOverlayBubbleMaskReport?,
        bubbleAssignmentCorrectionReport: MangaOverlayBubbleAssignmentCorrectionReport?,
        bubbleSplitCandidateReport: MangaOverlayBubbleSplitCandidateReport?,
        textBoxCandidateReport: MangaOverlayTextBoxCandidateReport?,
        segmentMaskReport: MangaOverlaySegmentMaskReport?,
        cropExperimentReport: MangaOverlayCropExperimentReport?,
        textBoxPlanFailureReport: MangaOverlayTextBoxPlanFailureReport?,
        lineCropExperimentReport: MangaOverlayLineCropExperimentReport?,
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?,
        externalTextBoxShadowOCRReport: MangaOverlayExternalTextBoxShadowOCRReport?
    ) -> MangaStructureActionCandidateReport {
        let readingByBlock = Dictionary(
            uniqueKeysWithValues: (readingOrderStructureAuditReport?.cases ?? []).map { ($0.blockIndex, $0) }
        )
        let routingByBlock = Dictionary(
            uniqueKeysWithValues: (internalStructureBottleneckReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let maskByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleMaskReport?.blockDiagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let correctionByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleAssignmentCorrectionReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        var splitByBlock: [Int: MangaOverlayBubbleSplitCandidateDiagnostic] = [:]
        for diagnostic in bubbleSplitCandidateReport?.diagnostics ?? [] {
            for blockIndex in diagnostic.seedBlockIndexes where splitByBlock[blockIndex] == nil {
                splitByBlock[blockIndex] = diagnostic
            }
        }
        let textBoxByBlock = Dictionary(
            uniqueKeysWithValues: (textBoxCandidateReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let segmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentMaskReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let failureByBlock = Dictionary(
            uniqueKeysWithValues: (textBoxPlanFailureReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let cropSummaryByBlock = Dictionary(
            uniqueKeysWithValues: (cropExperimentReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let cropCandidateByID = Dictionary(
            uniqueKeysWithValues: (cropExperimentReport?.candidates ?? []).map { ($0.candidateID, $0) }
        )
        let lineSummaryByBlock = Dictionary(
            uniqueKeysWithValues: (lineCropExperimentReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let lineCandidateByID = Dictionary(
            uniqueKeysWithValues: (lineCropExperimentReport?.candidates ?? []).map { ($0.candidateID, $0) }
        )
        let externalShadowByBlock = Dictionary(
            uniqueKeysWithValues: (externalTextBoxShadowOCRReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let realArtifactsMissing = externalArtifactReadinessReport?.externalTextBoxesShadowOCRAllowed != true
        let realArtifactBlocker = realArtifactsMissing
            ? (externalArtifactReadinessReport?.readinessVerdict ?? "missingRealArtifacts")
            : nil

        let cases = blocks.map { block -> MangaStructureActionCandidateCase in
            let reading = readingByBlock[block.index]
            let routing = routingByBlock[block.index]
            let mask = maskByBlock[block.index]
            let correction = correctionByBlock[block.index]
            let split = splitByBlock[block.index]
            let textBox = textBoxByBlock[block.index]
            let segment = segmentByBlock[block.index]
            let failure = failureByBlock[block.index]
            let cropSummary = cropSummaryByBlock[block.index]
            let cropBest = cropSummary?.bestShadowCandidateID.flatMap { cropCandidateByID[$0] }
            let lineSummary = lineSummaryByBlock[block.index]
            let lineBest = lineSummary?.bestShadowCandidateID.flatMap { lineCandidateByID[$0] }
            let externalShadow = externalShadowByBlock[block.index]
            var candidateTypes: [String] = []

            func appendCandidateType(_ candidateType: String) {
                candidateTypes.append(candidateType)
            }

            if reading?.orderChanged == true {
                appendCandidateType("readingOrderReindex")
            }
            if let risk = reading?.bubbleAssignmentRisk, risk != "none" {
                appendCandidateType("bubbleAssignmentReview")
            }
            if let splitRisk = reading?.splitOrMergeRisk,
               ["oversizedBubbleNeedsSplit", "sameBubblePotentialOverSplit", "crossBubbleMergeRejected"].contains(splitRisk) {
                appendCandidateType("bubbleSplitShadow")
            } else if reading?.sameBubbleSiblingBlockIndexes.isEmpty == false {
                appendCandidateType("sameBubbleSiblingLayout")
            }
            if let duplicateRisk = reading?.duplicateOrFragmentRisk, duplicateRisk != "none" {
                appendCandidateType("duplicateFragmentProtection")
            }
            if ["missing", "weak"].contains(reading?.textBoxEvidenceLevel ?? "") {
                appendCandidateType("textBoxEvidenceRequired")
            }
            if ["missing", "weak"].contains(reading?.segmentMaskEvidenceLevel ?? "") {
                appendCandidateType("segmentMaskEvidenceRequired")
            }
            if block.renderCollisionInitialOverflow || block.renderMaskOverflowPixelCount > 0 || block.renderTextTruncated {
                appendCandidateType("renderSafeAreaReflow")
            }
            if candidateTypes.isEmpty || reading?.recommendedStructureAction == "manualReview" {
                appendCandidateType("manualReviewOnly")
            }

            let candidates = candidateTypes.enumerated().map { ordinal, candidateType in
                structureActionCandidate(
                    ordinal: ordinal,
                    candidateType: candidateType,
                    block: block,
                    reading: reading,
                    routing: routing,
                    mask: mask,
                    correction: correction,
                    split: split,
                    textBox: textBox,
                    segment: segment,
                    failure: failure,
                    cropBest: cropBest,
                    lineBest: lineBest,
                    externalShadow: externalShadow,
                    realArtifactBlocker: realArtifactBlocker
                )
            }

            return MangaStructureActionCandidateCase(
                blockIndex: block.index,
                sourceRecommendedAction: reading?.recommendedStructureAction ?? "missingReadingOrderAudit",
                candidateCount: candidates.count,
                executedCandidateCount: candidates.filter(\.executed).count,
                skippedCandidateCount: candidates.filter { !$0.executed }.count,
                candidateTypes: Array(Set(candidates.map(\.candidateType))).sorted(),
                promotionVerdicts: Array(Set(candidates.map(\.promotionVerdict))).sorted(),
                recommendedNextSteps: Array(Set(candidates.map(\.recommendedNextStep))).sorted(),
                candidates: candidates
            )
        }

        let candidates = cases.flatMap(\.candidates)
        return MangaStructureActionCandidateReport(
            enabled: true,
            evaluatedBlockCount: cases.count,
            candidateCount: candidates.count,
            executedCandidateCount: candidates.filter(\.executed).count,
            skippedCandidateCount: candidates.filter { !$0.executed }.count,
            candidateTypeBreakdown: countBy(candidates.map(\.candidateType)),
            promotionVerdictBreakdown: countBy(candidates.map(\.promotionVerdict)),
            recommendedNextStepBreakdown: countBy(candidates.map(\.recommendedNextStep)),
            reportOnlyWouldImproveBlocks: Array(Set(candidates.filter { $0.promotionVerdict == "reportOnlyWouldImprove" }.map(\.blockIndex))).sorted(),
            blockedBlocks: Array(Set(candidates.filter { $0.promotionVerdict.hasPrefix("blockedBy") }.map(\.blockIndex))).sorted(),
            needsRealArtifactBlocks: Array(Set(candidates.filter { $0.recommendedNextStep == "provideRealKoharuArtifact" }.map(\.blockIndex))).sorted(),
            renderReflowCandidateBlocks: Array(Set(candidates.filter { $0.candidateType == "renderSafeAreaReflow" }.map(\.blockIndex))).sorted(),
            bubbleSplitCandidateBlocks: Array(Set(candidates.filter { $0.candidateType == "bubbleSplitShadow" }.map(\.blockIndex))).sorted(),
            bubbleAssignmentReviewBlocks: Array(Set(candidates.filter { $0.candidateType == "bubbleAssignmentReview" }.map(\.blockIndex))).sorted(),
            duplicateProtectionBlocks: Array(Set(candidates.filter { $0.candidateType == "duplicateFragmentProtection" }.map(\.blockIndex))).sorted(),
            manualReviewBlocks: Array(Set(candidates.filter { $0.candidateType == "manualReviewOnly" }.map(\.blockIndex))).sorted(),
            cases: cases,
            notes: [
                "structureActionCandidateReport is a shadow-only candidate matrix built from readingOrderStructureAuditReport and existing probe evidence",
                "it does not reorder blocks, change finalTextUsedForTranslation, change overlay rendering, change blockPassed, change failureCategory, or change post-fusion cleanup",
                "ground truth fields may be copied into evaluation metrics such as control OCR similarity, but are never used for planning, sorting, selecting, promotion, cleanup, or drawing",
                "missing real Koharu TextBoxes/BubbleMask/SegmentMask artifacts produce blocked/needsRealArtifact candidates; internal proxies are not promoted as detector output",
                "ci-fast uses only existing geometry, render diagnostics, and already-produced shadow OCR summaries; this report does not add new OCR or LLM calls"
            ]
        )
    }

    private static func makeKoharuArtifactDAGReport(
        blocks: [MangaOverlayProbeBlock],
        bubbleMaskReport: MangaOverlayBubbleMaskReport?,
        textBoxCandidateReport: MangaOverlayTextBoxCandidateReport?,
        segmentMaskReport: MangaOverlaySegmentMaskReport?,
        cropExperimentReport: MangaOverlayCropExperimentReport?,
        textBoxPlanFailureReport: MangaOverlayTextBoxPlanFailureReport?,
        lineCropExperimentReport: MangaOverlayLineCropExperimentReport?,
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?,
        externalTextBoxShadowOCRReport: MangaOverlayExternalTextBoxShadowOCRReport?,
        internalStructureBottleneckReport: MangaOverlayInternalStructureBottleneckReport?,
        readingOrderStructureAuditReport: MangaReadingOrderStructureAuditReport?,
        structureActionCandidateReport: MangaStructureActionCandidateReport?
    ) -> MangaKoharuArtifactDAGReport {
        let stageOrder = [
            "sourceImage",
            "contentCrop",
            "visionOCRCandidates",
            "bubbleCandidates",
            "bubbleMask",
            "textBoxes",
            "segmentMask",
            "ocrText",
            "ocrCropShadow",
            "lineTextBoxShadow",
            "externalArtifactGate",
            "externalTextBoxShadowOCR",
            "fusionAndCleanup",
            "translation",
            "cleanTextDiagnostic",
            "renderLayout",
            "structureActionCandidates",
            "finalOverlay"
        ]
        let maskByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleMaskReport?.blockDiagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let textBoxByBlock = Dictionary(
            uniqueKeysWithValues: (textBoxCandidateReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let segmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentMaskReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let cropSummaryByBlock = Dictionary(
            uniqueKeysWithValues: (cropExperimentReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let textBoxFailureByBlock = Dictionary(
            uniqueKeysWithValues: (textBoxPlanFailureReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let lineSummaryByBlock = Dictionary(
            uniqueKeysWithValues: (lineCropExperimentReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let externalAlignmentByBlock = Dictionary(
            uniqueKeysWithValues: (externalArtifactReadinessReport?.blockAlignment ?? []).map { ($0.blockIndex, $0) }
        )
        let externalShadowByBlock = Dictionary(
            uniqueKeysWithValues: (externalTextBoxShadowOCRReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let bottleneckByBlock = Dictionary(
            uniqueKeysWithValues: (internalStructureBottleneckReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let readingByBlock = Dictionary(
            uniqueKeysWithValues: (readingOrderStructureAuditReport?.cases ?? []).map { ($0.blockIndex, $0) }
        )
        let structureByBlock = Dictionary(
            uniqueKeysWithValues: (structureActionCandidateReport?.cases ?? []).map { ($0.blockIndex, $0) }
        )

        let realArtifactsAvailable = externalArtifactReadinessReport?.externalTextBoxesShadowOCRAllowed == true
        let realArtifactGateVerdict = externalArtifactReadinessReport?.readinessVerdict ?? "notEvaluated"
        let realArtifactGateNextAction = externalArtifactReadinessReport?.nextAction ?? "notEvaluated"

        func gate(
            _ name: String,
            passed: Bool,
            severity: String,
            evidence: [String],
            affectedBlocks: [Int],
            nextAction: String
        ) -> MangaKoharuArtifactGateCheck {
            MangaKoharuArtifactGateCheck(
                checkName: name,
                passed: passed,
                severity: severity,
                evidence: evidence,
                affectedBlocks: affectedBlocks.sorted(),
                recommendedNextAction: nextAction,
                groundTruthUsedForDecision: false
            )
        }

        func trace(
            stageName: String,
            status: String,
            artifactKind: String,
            sourceReport: String,
            sourceIDs: [String] = [],
            confidence: Double? = nil,
            gateChecks: [MangaKoharuArtifactGateCheck] = [],
            blockers: [String] = [],
            downstreamImpact: [String] = []
        ) -> MangaKoharuArtifactStageTrace {
            MangaKoharuArtifactStageTrace(
                stageName: stageName,
                status: status,
                artifactKind: artifactKind,
                sourceReport: sourceReport,
                sourceIDs: sourceIDs.sorted(),
                confidence: confidence,
                gateChecks: gateChecks,
                blockers: Array(Set(blockers)).sorted(),
                downstreamImpact: Array(Set(downstreamImpact)).sorted(),
                diagnosticOnly: true,
                wouldChangeMainFlow: false
            )
        }

        func requiredExternalArtifactMissing(_ candidateTypes: [String], _ target: String) -> Bool {
            guard !realArtifactsAvailable else { return false }
            switch target {
            case "textBoxes":
                return candidateTypes.contains("textBoxEvidenceRequired")
            case "bubbleMask":
                return candidateTypes.contains("bubbleAssignmentReview") || candidateTypes.contains("bubbleSplitShadow")
            case "segmentMask":
                return candidateTypes.contains("segmentMaskEvidenceRequired")
            default:
                return false
            }
        }

        func boolString(_ value: Bool?) -> String {
            guard let value else { return "nil" }
            return String(value)
        }

        let blockTraces = blocks.map { block -> MangaKoharuArtifactBlockTrace in
            let mask = maskByBlock[block.index]
            let textBox = textBoxByBlock[block.index]
            let segment = segmentByBlock[block.index]
            let crop = cropSummaryByBlock[block.index]
            let textBoxFailure = textBoxFailureByBlock[block.index]
            let line = lineSummaryByBlock[block.index]
            let externalAlignment = externalAlignmentByBlock[block.index]
            let externalShadow = externalShadowByBlock[block.index]
            let bottleneck = bottleneckByBlock[block.index]
            let reading = readingByBlock[block.index]
            let structure = structureByBlock[block.index]
            let candidateTypes = structure?.candidateTypes ?? []
            let candidateVerdicts = structure?.promotionVerdicts ?? []
            let recommendedSteps = structure?.recommendedNextSteps ?? []
            let needsTextBoxes = requiredExternalArtifactMissing(candidateTypes, "textBoxes")
            let needsBubbleMask = requiredExternalArtifactMissing(candidateTypes, "bubbleMask")
            let needsSegmentMask = requiredExternalArtifactMissing(candidateTypes, "segmentMask")
            let ocrLooksBlocked = block.failureCategory == "ocrInputSuspect"
                || block.wordOrderPreserved == false
                || block.qualityNotes.contains("likelyOCRIssue")
                || containsLikelyOCRError(in: block.finalTextUsedForTranslation)
            let translationLooksBlocked = block.failureCategory == "modelOutputFailure"
                || block.failureCategory == "translationLanguageQualityFailure"
            let renderLooksBlocked = block.renderCollisionInitialOverflow
                || block.renderMaskOverflowPixelCount > 0
                || block.renderTextTruncated

            var traces: [MangaKoharuArtifactStageTrace] = []
            traces.append(trace(
                stageName: "sourceImage",
                status: "ready",
                artifactKind: "aitransInternalArtifact",
                sourceReport: "bundleResource:test/1.png",
                sourceIDs: ["test/1.png"],
                confidence: 1,
                gateChecks: [gate("sourceImageLoaded", passed: true, severity: "info", evidence: ["sourceImage=test/1.png"], affectedBlocks: [block.index], nextAction: "continue")]
            ))
            traces.append(trace(
                stageName: "contentCrop",
                status: "ready",
                artifactKind: "aitransInternalArtifact",
                sourceReport: "MangaOverlayProbeConfiguration.cropping",
                confidence: 1,
                gateChecks: [gate("browserUiExcluded", passed: true, severity: "info", evidence: ["uses configured content crop before OCR"], affectedBlocks: [block.index], nextAction: "continue")]
            ))
            traces.append(trace(
                stageName: "visionOCRCandidates",
                status: block.rawOcrText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "blocked" : "ready",
                artifactKind: "aitransInternalArtifact",
                sourceReport: "VisionOCRCandidates",
                sourceIDs: ["block.\(block.index)"],
                gateChecks: [gate("rawOCRNotEmpty", passed: !block.rawOcrText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty, severity: "blocking", evidence: ["rawTextLength=\(block.rawOcrText.count)"], affectedBlocks: [block.index], nextAction: "improveVisionOCRInput")],
                blockers: block.rawOcrText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? ["rawOCRTextEmpty"] : [],
                downstreamImpact: block.rawOcrText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? ["ocrAccuracy", "translationFailureClassification"] : []
            ))
            traces.append(trace(
                stageName: "bubbleCandidates",
                status: block.bubbleID == nil ? "readyProxyOnly" : "ready",
                artifactKind: "aitransProxyArtifact",
                sourceReport: "bubbleGeometry",
                sourceIDs: block.bubbleID.map { ["bubble.\($0)"] } ?? ["unassigned"],
                confidence: block.bubbleID == nil ? 0.4 : 0.7,
                gateChecks: [gate("bubbleAssignmentPresent", passed: block.bubbleID != nil, severity: block.bubbleID == nil ? "warning" : "info", evidence: ["bubbleID=\(block.bubbleID.map(String.init) ?? "nil")"], affectedBlocks: [block.index], nextAction: block.bubbleID == nil ? "reviewBubbleAssignment" : "continue")],
                downstreamImpact: block.bubbleID == nil ? ["bubbleAssignment", "manualReview"] : []
            ))
            traces.append(trace(
                stageName: "bubbleMask",
                status: needsBubbleMask ? "missingRequiredArtifact" : (mask?.bubbleIDConsistent == false ? "blocked" : "readyProxyOnly"),
                artifactKind: needsBubbleMask ? "missingArtifact" : "aitransProxyArtifact",
                sourceReport: "bubbleMaskReport",
                sourceIDs: mask?.maskDominantBubbleID.map { ["maskBubble.\($0)"] } ?? [],
                confidence: mask?.maskDominantCoverageRatio,
                gateChecks: [gate("bubbleMaskConsistent", passed: mask?.bubbleIDConsistent != false && !needsBubbleMask, severity: needsBubbleMask || mask?.bubbleIDConsistent == false ? "blocking" : "info", evidence: ["maskConsistent=\(boolString(mask?.bubbleIDConsistent))", "realArtifactGate=\(realArtifactGateVerdict)"], affectedBlocks: [block.index], nextAction: needsBubbleMask ? "provideRealKoharuArtifact" : "reviewBubbleMaskEvidence")],
                blockers: needsBubbleMask ? [realArtifactGateVerdict] : (mask?.bubbleIDConsistent == false ? ["bubbleMaskConflict"] : []),
                downstreamImpact: needsBubbleMask || mask?.bubbleIDConsistent == false ? ["bubbleAssignment", "bubbleSegmentation", "artifactReadiness"] : []
            ))
            traces.append(trace(
                stageName: "textBoxes",
                status: needsTextBoxes ? "missingRequiredArtifact" : (textBox == nil ? "blocked" : "readyProxyOnly"),
                artifactKind: needsTextBoxes ? "missingArtifact" : "aitransProxyArtifact",
                sourceReport: "textBoxCandidateReport",
                sourceIDs: textBox.map { ["textBoxCandidate.\($0.id)"] } ?? [],
                confidence: textBox?.evidenceScore,
                gateChecks: [gate("textBoxEvidenceAvailable", passed: textBox != nil && !needsTextBoxes, severity: needsTextBoxes || textBox == nil ? "blocking" : "info", evidence: ["candidateTypes=\(candidateTypes.joined(separator: ","))", "realArtifactGate=\(realArtifactGateVerdict)"], affectedBlocks: [block.index], nextAction: needsTextBoxes ? "provideRealKoharuArtifact" : "keepProxyEvidenceReportOnly")],
                blockers: needsTextBoxes ? [realArtifactGateVerdict] : (textBox == nil ? ["textBoxProxyMissing"] : textBox?.rejectionReasons ?? []),
                downstreamImpact: needsTextBoxes || textBox == nil ? ["ocrAccuracy", "artifactReadiness", "manualReview"] : []
            ))
            traces.append(trace(
                stageName: "segmentMask",
                status: needsSegmentMask ? "missingRequiredArtifact" : (segment?.usableForCropEvidence == false ? "blocked" : "readyProxyOnly"),
                artifactKind: needsSegmentMask ? "missingArtifact" : "aitransProxyArtifact",
                sourceReport: "segmentMaskReport",
                sourceIDs: segment.map { ["segmentMask.block.\($0.blockIndex)"] } ?? [],
                confidence: segment?.textBoxCoverageRatio ?? segment?.bubbleMaskCoverageRatio,
                gateChecks: [gate("segmentMaskUsableForCropEvidence", passed: segment?.usableForCropEvidence != false && !needsSegmentMask, severity: needsSegmentMask || segment?.usableForCropEvidence == false ? "blocking" : "info", evidence: ["usable=\(boolString(segment?.usableForCropEvidence))", "realArtifactGate=\(realArtifactGateVerdict)"], affectedBlocks: [block.index], nextAction: needsSegmentMask ? "provideRealKoharuArtifact" : "keepProxyEvidenceReportOnly")],
                blockers: needsSegmentMask ? [realArtifactGateVerdict] : (segment?.usableForCropEvidence == false ? (segment?.rejectionReasons ?? ["segmentMaskWeak"]) : []),
                downstreamImpact: needsSegmentMask || segment?.usableForCropEvidence == false ? ["ocrAccuracy", "renderLayout", "artifactReadiness"] : []
            ))
            traces.append(trace(
                stageName: "ocrText",
                status: ocrLooksBlocked ? "blocked" : "ready",
                artifactKind: "aitransInternalArtifact",
                sourceReport: "finalTextUsedForTranslation",
                sourceIDs: ["block.\(block.index).finalTextUsedForTranslation"],
                confidence: block.ocrGroundTruthSimilarity,
                gateChecks: [gate("ocrInputUsableForTranslation", passed: !ocrLooksBlocked, severity: ocrLooksBlocked ? "blocking" : "info", evidence: ["failureCategory=\(block.failureCategory)", "wordOrderPreserved=\(boolString(block.wordOrderPreserved))"], affectedBlocks: [block.index], nextAction: ocrLooksBlocked ? "improveTextBoxOrSegmentEvidence" : "continue")],
                blockers: ocrLooksBlocked ? ["ocrInputSuspect"] : [],
                downstreamImpact: ocrLooksBlocked ? ["ocrAccuracy", "translationFailureClassification"] : []
            ))
            traces.append(trace(
                stageName: "ocrCropShadow",
                status: cropExperimentReport == nil ? "skippedFastMode" : (textBoxFailure?.promotionBlockers.isEmpty == false ? "blocked" : "shadowOnlyReady"),
                artifactKind: cropExperimentReport == nil ? "notApplicable" : "shadowOnlyArtifact",
                sourceReport: "cropExperimentReport",
                sourceIDs: crop?.bestShadowCandidateID.map { ["cropCandidate.\($0)"] } ?? [],
                gateChecks: [gate("cropShadowPromotionBlocked", passed: !(textBoxFailure?.promotionBlockers.isEmpty == false), severity: textBoxFailure?.promotionBlockers.isEmpty == false ? "blocking" : "info", evidence: textBoxFailure?.promotionBlockers ?? ["noPromotionBlockers"], affectedBlocks: [block.index], nextAction: textBoxFailure?.recommendedNextAction ?? "continue")],
                blockers: textBoxFailure?.promotionBlockers ?? [],
                downstreamImpact: textBoxFailure?.promotionBlockers.isEmpty == false ? ["ocrAccuracy", "manualReview"] : []
            ))
            traces.append(trace(
                stageName: "lineTextBoxShadow",
                status: lineCropExperimentReport == nil ? "skippedFastMode" : (line?.promotionVerdict == "promoted" ? "shadowOnlyReady" : "blocked"),
                artifactKind: lineCropExperimentReport == nil ? "notApplicable" : "shadowOnlyArtifact",
                sourceReport: "lineCropExperimentReport",
                sourceIDs: line?.bestShadowCandidateID.map { ["lineCropCandidate.\($0)"] } ?? [],
                gateChecks: [gate("lineShadowPromotable", passed: line?.promotionVerdict == "promoted", severity: lineCropExperimentReport == nil ? "info" : "warning", evidence: ["promotionVerdict=\(line?.promotionVerdict ?? "skipped")"], affectedBlocks: [block.index], nextAction: "stopLineDeskewTuning")],
                blockers: lineCropExperimentReport == nil ? [] : (line?.stopReasons ?? ["lineShadowNotPromoted"]),
                downstreamImpact: lineCropExperimentReport == nil ? [] : ["ocrAccuracy", "manualReview"]
            ))
            traces.append(trace(
                stageName: "externalArtifactGate",
                status: needsTextBoxes || needsBubbleMask || needsSegmentMask ? "missingRequiredArtifact" : "notApplicable",
                artifactKind: needsTextBoxes || needsBubbleMask || needsSegmentMask ? "missingArtifact" : "notApplicable",
                sourceReport: "externalArtifactReadinessReport",
                sourceIDs: externalAlignment.map { ["externalAlignment.block.\($0.blockIndex)"] } ?? [],
                gateChecks: [gate("realKoharuArtifactReady", passed: realArtifactsAvailable, severity: needsTextBoxes || needsBubbleMask || needsSegmentMask ? "blocking" : "info", evidence: ["readinessVerdict=\(realArtifactGateVerdict)", "nextAction=\(realArtifactGateNextAction)"], affectedBlocks: [block.index], nextAction: realArtifactGateNextAction)],
                blockers: needsTextBoxes || needsBubbleMask || needsSegmentMask ? [realArtifactGateVerdict] : [],
                downstreamImpact: needsTextBoxes || needsBubbleMask || needsSegmentMask ? ["artifactReadiness", "manualReview"] : []
            ))
            traces.append(trace(
                stageName: "externalTextBoxShadowOCR",
                status: externalTextBoxShadowOCRReport?.executed == true ? (externalShadow?.ocrSucceeded == true ? "shadowOnlyReady" : "blocked") : "notApplicable",
                artifactKind: externalTextBoxShadowOCRReport?.executed == true ? "shadowOnlyArtifact" : "notApplicable",
                sourceReport: "externalTextBoxShadowOCRReport",
                sourceIDs: externalShadow?.selectedCandidateID.map { ["externalTextBoxShadow.\($0)"] } ?? [],
                gateChecks: [gate("externalTextBoxShadowOCRExecuted", passed: externalShadow?.ocrSucceeded == true, severity: externalTextBoxShadowOCRReport?.executed == true ? "warning" : "info", evidence: ["executed=\(externalTextBoxShadowOCRReport?.executed ?? false)", "gateVerdict=\(externalTextBoxShadowOCRReport?.gateVerdict ?? "nil")"], affectedBlocks: [block.index], nextAction: externalShadow?.promotionVerdict == "promoted" ? "reviewShadowEvidence" : "provideRealKoharuArtifact")],
                blockers: externalShadow?.blockers ?? [],
                downstreamImpact: externalShadow?.ocrSucceeded == false ? ["ocrAccuracy", "artifactReadiness"] : []
            ))
            traces.append(trace(
                stageName: "fusionAndCleanup",
                status: "ready",
                artifactKind: "aitransInternalArtifact",
                sourceReport: "fusionComparison.postFusionCleanup",
                sourceIDs: ["block.\(block.index)"],
                gateChecks: [gate("finalBlockRetained", passed: true, severity: "info", evidence: ["currentBlockSource=fusedWholePageBubble"], affectedBlocks: [block.index], nextAction: "continue")]
            ))
            traces.append(trace(
                stageName: "translation",
                status: translationLooksBlocked ? "blocked" : "ready",
                artifactKind: "aitransInternalArtifact",
                sourceReport: "translationDecisionTrace",
                sourceIDs: ["block.\(block.index).translation"],
                gateChecks: [gate("translationQualityPassed", passed: !translationLooksBlocked && block.blockPassed, severity: translationLooksBlocked ? "blocking" : "info", evidence: ["failureCategory=\(block.failureCategory)", "blockPassed=\(block.blockPassed)"], affectedBlocks: [block.index], nextAction: translationLooksBlocked ? "tryPromptOrModelComparison" : "continue")],
                blockers: translationLooksBlocked ? block.failureReasons : [],
                downstreamImpact: translationLooksBlocked ? ["translationFailureClassification"] : []
            ))
            traces.append(trace(
                stageName: "cleanTextDiagnostic",
                status: "ready",
                artifactKind: "derivedReportArtifact",
                sourceReport: "clean_text_diagnostic.json",
                gateChecks: [gate("cleanTextDiagnosticReportOnly", passed: true, severity: "info", evidence: ["diagnosticOnly=true"], affectedBlocks: [block.index], nextAction: "compareWithOCRFailures")]
            ))
            traces.append(trace(
                stageName: "renderLayout",
                status: renderLooksBlocked ? "blocked" : "ready",
                artifactKind: "aitransInternalArtifact",
                sourceReport: "renderDiagnostics",
                sourceIDs: ["block.\(block.index).safeLayoutRect"],
                gateChecks: [gate("renderLayoutFits", passed: !renderLooksBlocked, severity: renderLooksBlocked ? "blocking" : "info", evidence: ["overflow=\(block.renderCollisionInitialOverflow)", "maskOverflowPixels=\(block.renderMaskOverflowPixelCount)", "truncated=\(block.renderTextTruncated)"], affectedBlocks: [block.index], nextAction: renderLooksBlocked ? "keepRenderSafeAreaReflowCandidate" : "continue")],
                blockers: renderLooksBlocked ? ["renderOverflowOrTruncation"] : [],
                downstreamImpact: renderLooksBlocked ? ["renderLayout"] : []
            ))
            traces.append(trace(
                stageName: "structureActionCandidates",
                status: candidateVerdicts.contains(where: { $0.hasPrefix("blockedBy") }) ? "blocked" : "ready",
                artifactKind: "derivedReportArtifact",
                sourceReport: "structureActionCandidateReport",
                sourceIDs: structure?.candidates.map { $0.candidateID } ?? [],
                gateChecks: [gate("structureActionsReportOnly", passed: !candidateVerdicts.contains(where: { $0.hasPrefix("blockedBy") }), severity: candidateVerdicts.contains(where: { $0.hasPrefix("blockedBy") }) ? "warning" : "info", evidence: ["verdicts=\(candidateVerdicts.joined(separator: ","))"], affectedBlocks: [block.index], nextAction: recommendedSteps.first ?? "manualReview")],
                blockers: candidateVerdicts.filter { $0.hasPrefix("blockedBy") },
                downstreamImpact: candidateVerdicts.contains(where: { $0.hasPrefix("blockedBy") }) ? ["artifactReadiness", "manualReview"] : []
            ))
            traces.append(trace(
                stageName: "finalOverlay",
                status: "ready",
                artifactKind: "aitransInternalArtifact",
                sourceReport: "1_translated_overlay.png",
                gateChecks: [gate("overlayDrawnForBlock", passed: true, severity: "info", evidence: ["failed blocks still render failure text"], affectedBlocks: [block.index], nextAction: "continue")]
            ))

            let blockingStages = traces.filter { $0.status == "blocked" || $0.status == "missingRequiredArtifact" }
            let firstBlocking = blockingStages.first
            let impacts = Array(Set(blockingStages.flatMap { $0.downstreamImpact })).sorted()
            let fallbackAction = bottleneck?.recommendedNextAction ?? reading?.recommendedStructureAction ?? recommendedSteps.first ?? "manualReview"
            return MangaKoharuArtifactBlockTrace(
                blockIndex: block.index,
                groundTruthMatch: block.groundTruthMatch,
                bestGroundTruthType: block.bestGroundTruthType,
                ocrSimilarityForEvaluation: block.ocrGroundTruthSimilarity,
                failureCategory: block.failureCategory,
                blockPassed: block.blockPassed,
                bubbleID: block.bubbleID,
                firstBlockingStage: firstBlocking?.stageName ?? "none",
                firstBlockingReason: firstBlocking?.blockers.first ?? "none",
                downstreamImpacts: impacts.isEmpty ? ["none"] : impacts,
                stageTraces: traces,
                structureActionCandidateVerdicts: candidateVerdicts,
                recommendedNextAction: firstBlocking?.gateChecks.first?.recommendedNextAction ?? fallbackAction
            )
        }

        let allStageTraces = blockTraces.flatMap { $0.stageTraces }
        func stageSummary(for stageName: String) -> MangaKoharuArtifactStageSummary {
            let traces = allStageTraces.filter { $0.stageName == stageName }
            let statuses = traces.map { $0.status }
            let status: String
            if statuses.contains("blocked") {
                status = "blocked"
            } else if statuses.contains("missingRequiredArtifact") {
                status = "missingRequiredArtifact"
            } else if statuses.contains("skippedFastMode") {
                status = "skippedFastMode"
            } else if statuses.contains("readyProxyOnly") {
                status = "readyProxyOnly"
            } else if statuses.contains("shadowOnlyReady") {
                status = "shadowOnlyReady"
            } else if statuses.contains("ready") {
                status = "ready"
            } else {
                status = "notApplicable"
            }
            let artifactKind = traces.map { $0.artifactKind }.first { $0 != "notApplicable" } ?? "notApplicable"
            let producedBy = Array(Set(traces.map { $0.sourceReport })).sorted()
            let consumedBy = Self.koharuArtifactConsumers(for: stageName)
            let stageBlocks = traces.flatMap { trace in
                trace.gateChecks.flatMap { $0.affectedBlocks }
            }
            let primaryGateChecks = Array(traces.flatMap { $0.gateChecks }.prefix(3))
            return MangaKoharuArtifactStageSummary(
                stageName: stageName,
                artifactKind: artifactKind,
                status: status,
                producedBy: producedBy,
                consumedBy: consumedBy,
                blockCount: blocks.count,
                readyBlockCount: traces.filter { $0.status == "ready" || $0.status == "shadowOnlyReady" }.count,
                blockedBlockCount: traces.filter { $0.status == "blocked" }.count,
                proxyOnlyBlockCount: traces.filter { $0.status == "readyProxyOnly" }.count,
                missingBlockCount: traces.filter { $0.status == "missingRequiredArtifact" }.count,
                primaryGateChecks: primaryGateChecks,
                notes: [
                    "stageTraceCount=\(traces.count)",
                    "affectedBlocks=\(Array(Set(stageBlocks)).sorted().map(String.init).joined(separator: ","))"
                ]
            )
        }
        let stageSummaries = stageOrder.map(stageSummary)
        let dependencyEdges = koharuArtifactDependencyEdges(realArtifactsAvailable: realArtifactsAvailable)
        let stageStatuses = stageSummaries.map { $0.status }
        let artifactKinds = allStageTraces.map { $0.artifactKind }
        let firstBlockingStages = blockTraces.map { $0.firstBlockingStage }
        let downstreamImpacts = blockTraces.flatMap { $0.downstreamImpacts }
        let readyStageSummaries = stageSummaries.filter { $0.status == "ready" || $0.status == "shadowOnlyReady" }
        let proxyOnlyStageSummaries = stageSummaries.filter { $0.status == "readyProxyOnly" }
        let missingRequiredStageSummaries = stageSummaries.filter { $0.status == "missingRequiredArtifact" }
        let blockedStageSummaries = stageSummaries.filter { $0.status == "blocked" }
        let readyStages = readyStageSummaries.map { $0.stageName }
        let proxyOnlyStages = proxyOnlyStageSummaries.map { $0.stageName }
        let missingRequiredStages = missingRequiredStageSummaries.map { $0.stageName }
        let blockedStages = blockedStageSummaries.map { $0.stageName }

        let textBoxMissingTraces = blockTraces.filter { trace in
            trace.stageTraces.contains { stageTrace in
                stageTrace.stageName == "textBoxes" && stageTrace.status == "missingRequiredArtifact"
            }
        }
        let bubbleMaskMissingTraces = blockTraces.filter { trace in
            trace.stageTraces.contains { stageTrace in
                stageTrace.stageName == "bubbleMask" && stageTrace.status == "missingRequiredArtifact"
            }
        }
        let segmentMaskMissingTraces = blockTraces.filter { trace in
            trace.stageTraces.contains { stageTrace in
                stageTrace.stageName == "segmentMask" && stageTrace.status == "missingRequiredArtifact"
            }
        }
        let blocksNeedingRealTextBoxes = textBoxMissingTraces.map { $0.blockIndex }.sorted()
        let blocksNeedingRealBubbleMask = bubbleMaskMissingTraces.map { $0.blockIndex }.sorted()
        let blocksNeedingRealSegmentMask = segmentMaskMissingTraces.map { $0.blockIndex }.sorted()
        let blocksStoppedByOCRCropEvidence = blockTraces.filter { trace in
            ["ocrText", "ocrCropShadow", "lineTextBoxShadow"].contains(trace.firstBlockingStage)
        }.map { $0.blockIndex }.sorted()
        let blocksStoppedByTranslationModelQuality = blockTraces.filter { trace in
            trace.firstBlockingStage == "translation"
        }.map { $0.blockIndex }.sorted()
        let blocksWithRenderOnlyIssues = blockTraces.filter { trace in
            trace.firstBlockingStage == "renderLayout"
        }.map { $0.blockIndex }.sorted()

        return MangaKoharuArtifactDAGReport(
            enabled: true,
            pipelineName: "AITRANS Manga Probe Koharu Artifact DAG",
            evaluatedBlockCount: blockTraces.count,
            stageCount: stageSummaries.count,
            edgeCount: dependencyEdges.count,
            stageStatusBreakdown: countBy(stageStatuses),
            artifactKindBreakdown: countBy(artifactKinds),
            firstBlockingStageBreakdown: countBy(firstBlockingStages),
            downstreamImpactBreakdown: countBy(downstreamImpacts),
            readyStages: readyStages,
            proxyOnlyStages: proxyOnlyStages,
            missingRequiredStages: missingRequiredStages,
            blockedStages: blockedStages,
            realArtifactGateVerdict: realArtifactGateVerdict,
            realArtifactGateNextAction: realArtifactGateNextAction,
            blocksNeedingRealTextBoxes: blocksNeedingRealTextBoxes,
            blocksNeedingRealBubbleMask: blocksNeedingRealBubbleMask,
            blocksNeedingRealSegmentMask: blocksNeedingRealSegmentMask,
            blocksStoppedByOCRCropEvidence: blocksStoppedByOCRCropEvidence,
            blocksStoppedByTranslationModelQuality: blocksStoppedByTranslationModelQuality,
            blocksWithRenderOnlyIssues: blocksWithRenderOnlyIssues,
            dependencyEdges: dependencyEdges,
            stageSummaries: stageSummaries,
            blockTraces: blockTraces,
            notes: [
                "koharuArtifactDAGReport is report-only and does not change OCR, translation input, overlay drawing, blockPassed, failureCategory, cleanup, or candidate selection",
                "realKoharuArtifact is only reported when externalArtifactReadinessReport allows shadow OCR; internal proxy reports remain aitransProxyArtifact or derivedReportArtifact",
                "ground truth similarity is copied only into ocrSimilarityForEvaluation and is not used for gate pass/fail, planning, sorting, promotion, cleanup, or rendering"
            ]
        )
    }

    private static func makeKoharuStageGapReplicationReport(
        blocks: [MangaOverlayProbeBlock],
        koharuArtifactDAGReport: MangaKoharuArtifactDAGReport?,
        structureActionCandidateReport: MangaStructureActionCandidateReport?,
        readingOrderStructureAuditReport: MangaReadingOrderStructureAuditReport?,
        internalStructureBottleneckReport: MangaOverlayInternalStructureBottleneckReport?,
        ocrCharacterDamageAuditReport: MangaOCRCharacterDamageAuditReport?,
        textBoxPlanFailureReport: MangaOverlayTextBoxPlanFailureReport?,
        lineCropExperimentReport: MangaOverlayLineCropExperimentReport?,
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?,
        externalTextBoxShadowOCRReport: MangaOverlayExternalTextBoxShadowOCRReport?,
        cleanTextDiagnostic: MangaCleanTextDiagnosticReport?
    ) -> MangaKoharuStageGapReplicationReport {
        let allBlockIndexes = blocks.map(\.index).sorted()
        let dagBlockByIndex = Dictionary(
            uniqueKeysWithValues: (koharuArtifactDAGReport?.blockTraces ?? []).map { ($0.blockIndex, $0) }
        )
        let structureByBlock = Dictionary(
            uniqueKeysWithValues: (structureActionCandidateReport?.cases ?? []).map { ($0.blockIndex, $0) }
        )
        let bottleneckByBlock = Dictionary(
            uniqueKeysWithValues: (internalStructureBottleneckReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let ocrDamageByBlock = Dictionary(
            uniqueKeysWithValues: (ocrCharacterDamageAuditReport?.cases ?? []).map { ($0.blockIndex, $0) }
        )
        let missingArtifactNames = externalArtifactReadinessReport?.missingArtifacts.sorted() ?? ["manifest", "TextBoxes", "BubbleMask", "SegmentMask"]
        let realArtifactReady = externalArtifactReadinessReport?.externalTextBoxesShadowOCRAllowed == true
        let realArtifactVerdict = externalArtifactReadinessReport?.readinessVerdict ?? "notEvaluated"
        let realArtifactNextAction = externalArtifactReadinessReport?.nextAction ?? "notEvaluated"
        let cleanPassRate = cleanTextDiagnostic?.passRate ?? 0
        let cleanTextLow = cleanTextDiagnostic.map { $0.passRate < 0.80 } ?? true

        func uniqueSorted(_ values: [Int]) -> [Int] {
            Array(Set(values)).sorted()
        }

        func blockIndexes(firstBlockedBy stages: Set<String>) -> [Int] {
            uniqueSorted((koharuArtifactDAGReport?.blockTraces ?? [])
                .filter { stages.contains($0.firstBlockingStage) }
                .map(\.blockIndex))
        }

        func gate(
            _ name: String,
            scope: String,
            required: Bool = true,
            status: String,
            evidence: [String],
            threshold: String,
            affected: [Int],
            failureMeans: String
        ) -> MangaKoharuPromotionGate {
            MangaKoharuPromotionGate(
                gateName: name,
                scope: scope,
                requiredForPromotion: required,
                currentStatus: status,
                evidence: evidence,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                failureMeans: failureMeans,
                groundTruthUsedForDecision: false
            )
        }

        func check(
            _ name: String,
            passed: Bool,
            evidence: [String],
            required: Bool = true
        ) -> MangaKoharuStageConformanceCheck {
            MangaKoharuStageConformanceCheck(
                checkName: name,
                passed: passed,
                evidence: evidence,
                requiredForPromotion: required,
                groundTruthUsedForDecision: false
            )
        }

        let noMainFlowMutationGate = gate(
            "noMainFlowMutation",
            scope: "allStages",
            status: "passed",
            evidence: ["report-only builder writes JSON/TXT fields only"],
            threshold: "finalTextUsedForTranslation, blockPassed, cleanup, overlay, prompt unchanged",
            affected: allBlockIndexes,
            failureMeans: "Do not promote report output into main OCR, translation, cleanup, or render selection."
        )
        let noGroundTruthPlanningGate = gate(
            "noGroundTruthPlanning",
            scope: "allStages",
            status: "passed",
            evidence: ["groundTruth is copied only as ocrSimilarityForEvaluation"],
            threshold: "no candidate generation, sorting, cleanup, promotion, or render choice may read ground truth",
            affected: allBlockIndexes,
            failureMeans: "Planning or promotion would be invalid if ground truth changes any decision."
        )
        let realArtifactReadinessGate = gate(
            "realArtifactReadiness",
            scope: "externalArtifacts",
            status: realArtifactReady ? "passed" : "blocked",
            evidence: [
                "readinessVerdict=\(realArtifactVerdict)",
                "nextAction=\(realArtifactNextAction)",
                "missing=\(missingArtifactNames.joined(separator: ","))"
            ],
            threshold: "active artifact directory with manifest, TextBoxes, BubbleMask, SegmentMask; contractExampleOnly=false",
            affected: allBlockIndexes,
            failureMeans: "TextBoxes, BubbleMask, and SegmentMask cannot advance beyond proxy/report-only evidence."
        )
        let protectedTextGate = gate(
            "protectedTextRetained",
            scope: "fusionAndCleanup",
            status: "passed",
            evidence: ["post-fusion cleanup keeps final blocks and protected decorative/dialogue text"],
            threshold: "key dialogue and decorative title must remain in final blocks",
            affected: allBlockIndexes,
            failureMeans: "Cleanup must be reverted if protected content disappears."
        )
        let wordPreservationGate = gate(
            "wordPreservationGuardrail",
            scope: "ocrShadowCandidates",
            status: (textBoxPlanFailureReport?.candidatePromotionBlockedBlocks.isEmpty == false) ? "blocked" : "passed",
            evidence: [
                "candidatePromotionBlockedBlocks=\(textBoxPlanFailureReport?.candidatePromotionBlockedBlocks.map(String.init).joined(separator: ",") ?? "nil")",
                "lineStoppedBlocks=\(lineCropExperimentReport?.stoppedAfterLineResearchBlocks.map(String.init).joined(separator: ",") ?? "nil")"
            ],
            threshold: "shadow OCR must preserve raw keywords and avoid likely OCR regressions before promotion",
            affected: uniqueSorted((textBoxPlanFailureReport?.candidatePromotionBlockedBlocks ?? []) + (lineCropExperimentReport?.stoppedAfterLineResearchBlocks ?? [])),
            failureMeans: "Do not promote crop, line, deskew, or external OCR text."
        )
        let bubbleConflictGate = gate(
            "bubbleConflictResolved",
            scope: "bubbleMask",
            status: (readingOrderStructureAuditReport?.maskConflictBlocks.isEmpty == false) ? "blocked" : "passed",
            evidence: ["maskConflictBlocks=\(readingOrderStructureAuditReport?.maskConflictBlocks.map(String.init).joined(separator: ",") ?? "nil")"],
            threshold: "no cross-bubble merge or unresolved mask conflict for promoted assignment",
            affected: readingOrderStructureAuditReport?.maskConflictBlocks ?? [],
            failureMeans: "Bubble assignment/split changes remain report-only."
        )
        let segmentInsideBubbleGate = gate(
            "segmentInsideBubble",
            scope: "segmentMask",
            status: realArtifactReady ? "readyForShadow" : "blocked",
            evidence: ["externalSegmentMaskAllowed=\(realArtifactReady)", "missing=\(missingArtifactNames.joined(separator: ","))"],
            threshold: "glyph/segment evidence must stay inside owning bubble and satisfy coverage checks",
            affected: koharuArtifactDAGReport?.blocksNeedingRealSegmentMask ?? allBlockIndexes,
            failureMeans: "SegmentMask evidence cannot drive crop or erase promotion."
        )
        let renderNoOverflowGate = gate(
            "renderNoOverflow",
            scope: "renderedSprites",
            status: (koharuArtifactDAGReport?.blocksWithRenderOnlyIssues.isEmpty == false) ? "blocked" : "passed",
            evidence: ["renderOnlyIssueBlocks=\(koharuArtifactDAGReport?.blocksWithRenderOnlyIssues.map(String.init).joined(separator: ",") ?? "nil")"],
            threshold: "all success and failure blocks draw forward, visible, and non-truncated",
            affected: koharuArtifactDAGReport?.blocksWithRenderOnlyIssues ?? [],
            failureMeans: "Keep render safe-area reflow as report-only until overflow is resolved."
        )
        let cleanTextGate = gate(
            "cleanTextModelFloor",
            scope: "translations",
            status: cleanTextLow ? "blocked" : "passed",
            evidence: ["cleanTextPassRate=\(cleanPassRate.formatted(.number.precision(.fractionLength(4))))"],
            threshold: "clean text pass rate >= 0.80 before assigning most end-to-end failure solely to OCR",
            affected: blocks.filter { !$0.blockPassed }.map(\.index),
            failureMeans: "Run model/prompt comparison before claiming OCR-only gains."
        )

        let textBoxBlocks = uniqueSorted((koharuArtifactDAGReport?.blocksNeedingRealTextBoxes ?? []) + blockIndexes(firstBlockedBy: ["textBoxes", "externalArtifactGate"]))
        let bubbleBlocks = uniqueSorted((koharuArtifactDAGReport?.blocksNeedingRealBubbleMask ?? []) + (readingOrderStructureAuditReport?.maskConflictBlocks ?? []))
        let segmentBlocks = uniqueSorted((koharuArtifactDAGReport?.blocksNeedingRealSegmentMask ?? []))
        let ocrBlocks = uniqueSorted((koharuArtifactDAGReport?.blocksStoppedByOCRCropEvidence ?? []) + blocks.filter { $0.failureCategory == "ocrInputSuspect" }.map { $0.index })
        let translationBlocks = uniqueSorted((koharuArtifactDAGReport?.blocksStoppedByTranslationModelQuality ?? []) + blocks.filter { $0.failureCategory == "modelOutputFailure" || $0.failureCategory == "translationLanguageQualityFailure" }.map { $0.index })
        let renderBlocks = uniqueSorted(koharuArtifactDAGReport?.blocksWithRenderOnlyIssues ?? [])
        let cropStopBlocks = uniqueSorted((textBoxPlanFailureReport?.stopRecommendedBlocks ?? []) + (lineCropExperimentReport?.stoppedAfterLineResearchBlocks ?? []))

