        func targetStage(for firstBlockingStage: String) -> String {
            switch firstBlockingStage {
            case "textBoxes", "externalArtifactGate", "externalTextBoxShadowOCR":
                return "textBoxes"
            case "bubbleMask", "bubbleCandidates":
                return "bubbleMask"
            case "segmentMask":
                return "segmentMask"
            case "ocrText", "ocrCropShadow", "lineTextBoxShadow", "visionOCRCandidates":
                return "ocrText"
            case "translation":
                return "translations"
            case "renderLayout", "finalOverlay":
                return "renderedSprites"
            default:
                return "ocrText"
            }
        }

        func gapCategory(for stage: String, block: MangaOverlayProbeBlock) -> String {
            switch stage {
            case "textBoxes":
                return realArtifactReady ? "proxyNeedsValidation" : "externalArtifactRequired"
            case "bubbleMask":
                return "bubbleAssignmentOrSplit"
            case "segmentMask":
                return "segmentMaskWeak"
            case "translations":
                return "translationModelQuality"
            case "renderedSprites":
                return "renderLayoutOnly"
            default:
                if block.failureCategory == "ocrInputSuspect" {
                    return "ocrInputQuality"
                }
                return cropStopBlocks.contains(block.index) ? "lineDeskewStopped" : "ocrInputQuality"
            }
        }

        func workPackageID(for stage: String, gapCategory: String) -> String {
            switch gapCategory {
            case "externalArtifactRequired":
                return "WP-textboxes-real-artifact-gate"
            case "bubbleAssignmentOrSplit":
                return "WP-bubblemask-instance-validation"
            case "segmentMaskWeak":
                return "WP-segmentmask-glyph-coverage-gate"
            case "translationModelQuality":
                return "WP-translation-model-comparison"
            case "renderLayoutOnly", "manualReviewRequired":
                return "WP-render-safe-area-retain"
            default:
                if stage == "segmentMask" {
                    return "WP-segmentmask-glyph-coverage-gate"
                }
                return "WP-ocr-crop-stoplist"
            }
        }

        let blockPlans: [MangaKoharuBlockReplicationPlan] = blocks.map { block -> MangaKoharuBlockReplicationPlan in
            let dagTrace = dagBlockByIndex[block.index]
            let firstBlocking = dagTrace?.firstBlockingStage ?? "notAvailable"
            let targetStage = targetStage(for: firstBlocking)
            let primaryGap = gapCategory(for: targetStage, block: block)
            let packageID = workPackageID(for: targetStage, gapCategory: primaryGap)
            let requiresReal = primaryGap == "externalArtifactRequired"
                || ["textBoxes", "bubbleMask", "segmentMask"].contains(targetStage) && !realArtifactReady
                || dagTrace?.recommendedNextAction == "provideRealKoharuArtifact"
            let requiresFull = firstBlocking == "ocrCropShadow" || firstBlocking == "lineTextBoxShadow"
            let structureMustNotPromote = structureByBlock[block.index]?.candidates.flatMap(\.mustNotPromoteReasons) ?? []
            let bottleneckMustNotPromote = bottleneckByBlock[block.index]?.mustNotPromoteReasons ?? []
            let ocrDamageMustNotPromote = ocrDamageByBlock[block.index]?.mustNotPromoteReasons ?? []
            let traceBlockers = dagTrace?.stageTraces.flatMap(\.blockers) ?? []
            let minimumEvidence: [String]
            if requiresReal {
                minimumEvidence = ["active Koharu artifact files", "readinessVerdict=readyForShadowOCR", "block alignment for block \(block.index)"]
            } else if targetStage == "translations" {
                minimumEvidence = ["clean text diagnostic", "raw output classification", "candidate classification"]
            } else if targetStage == "renderedSprites" {
                minimumEvidence = ["safeLayoutRect", "render overflow diagnostics", "translated overlay PNG"]
            } else {
                minimumEvidence = ["word preservation", "no introduced likely OCR error", "bubble/segment blocker summary"]
            }
            return MangaKoharuBlockReplicationPlan(
                blockIndex: block.index,
                groundTruthMatch: block.groundTruthMatch,
                bestGroundTruthType: block.bestGroundTruthType,
                ocrSimilarityForEvaluation: block.ocrGroundTruthSimilarity,
                blockPassed: block.blockPassed,
                failureCategory: block.failureCategory,
                bubbleID: block.bubbleID,
                firstBlockingStageFromDAG: firstBlocking,
                primaryGapCategory: primaryGap,
                targetCanonicalStage: targetStage,
                recommendedWorkPackageID: packageID,
                minimumEvidenceToCollect: minimumEvidence,
                mustNotPromoteReasons: Array(Set(structureMustNotPromote + bottleneckMustNotPromote + ocrDamageMustNotPromote + traceBlockers + ["noMainFlowMutation", "noGroundTruthPlanning"])).sorted(),
                canBeEvaluatedInCIFast: !requiresFull,
                requiresFullProbe: requiresFull,
                requiresRealExternalArtifact: requiresReal,
                nextAction: requiresReal ? "provideRealKoharuArtifact" : (dagTrace?.recommendedNextAction ?? "reviewStageGapReport")
            )
        }

        let stageCapabilityBreakdown = countBy(stageGaps.map { $0.currentCapability })
        let gapCategoryBreakdown = countBy(stageGaps.map { $0.gapCategory })
        let replicationReadinessBreakdown = countBy(stageGaps.map { $0.replicationReadiness })
        let promotionGateStatuses = stageGaps.flatMap { gap in
            gap.promotionGates.map { gate in gate.currentStatus }
        }
        let promotionGateBreakdown = countBy(promotionGateStatuses)
        let gapCount = stageGaps.filter { $0.gapCategory != "noGapForCurrentScope" }.count
        let blockedByRealArtifactStages = stageGaps.filter { $0.replicationReadiness == "needsRealKoharuArtifact" }.map { $0.canonicalStage }
        let blockedByOCRStages = stageGaps.filter { ["ocrInputQuality", "cropPromotionBlocked", "lineDeskewStopped"].contains($0.gapCategory) }.map { $0.canonicalStage }
        let blockedByBubbleStages = stageGaps.filter { $0.gapCategory == "bubbleAssignmentOrSplit" }.map { $0.canonicalStage }
        let blockedBySegmentStages = stageGaps.filter { gap in
            gap.gapCategory == "segmentMaskWeak" || gap.canonicalStage == "segmentMask"
        }.map { $0.canonicalStage }
        let blockedByTranslationStages = stageGaps.filter { $0.gapCategory == "translationModelQuality" }.map { $0.canonicalStage }
        let renderReadyStages = stageGaps.filter { gap in
            ["renderedSprites", "finalRender"].contains(gap.canonicalStage)
                && gap.replicationReadiness == "readyForReportOnly"
        }.map { $0.canonicalStage }
        let stopTuningStages = stageGaps.filter { $0.replicationReadiness == "stopLocalHeuristicTuning" }.map { $0.canonicalStage }
        let readyForShadowOnlyStages = stageGaps.filter { $0.replicationReadiness == "readyForShadowOnly" }.map { $0.canonicalStage }
        let mustWaitForExternalArtifactStages = stageGaps.filter { $0.replicationReadiness == "needsRealKoharuArtifact" }.map { $0.canonicalStage }

        return MangaKoharuStageGapReplicationReport(
            enabled: true,
            referencePipeline: "Koharu",
            evaluatedBlockCount: blocks.count,
            canonicalStageCount: stageGaps.count,
            gapCount: gapCount,
            workPackageCount: workPackages.count,
            stageCapabilityBreakdown: stageCapabilityBreakdown,
            gapCategoryBreakdown: gapCategoryBreakdown,
            replicationReadinessBreakdown: replicationReadinessBreakdown,
            promotionGateBreakdown: promotionGateBreakdown,
            blockedByRealArtifactStages: blockedByRealArtifactStages.sorted(),
            blockedByOCRStages: blockedByOCRStages.sorted(),
            blockedByBubbleSegmentationStages: blockedByBubbleStages.sorted(),
            blockedBySegmentMaskStages: blockedBySegmentStages.sorted(),
            blockedByTranslationModelStages: blockedByTranslationStages.sorted(),
            renderReadyStages: renderReadyStages.sorted(),
            stopTuningStages: stopTuningStages.sorted(),
            readyForShadowOnlyStages: readyForShadowOnlyStages.sorted(),
            mustWaitForExternalArtifactStages: mustWaitForExternalArtifactStages.sorted(),
            stageGaps: stageGaps,
            workPackages: workPackages,
            blockPlans: blockPlans,
            notes: [
                "koharuStageGapReplicationReport converts the v1.22 DAG into canonical Koharu stage gaps, work packages, promotion gates, and per-block replication plans",
                "report-only: does not run OCR or LLM, does not change finalTextUsedForTranslation, blockPassed, failureCategory, cleanup, overlay, prompt, or currentBlockSource",
                "ground truth similarity is evaluation-only; all planning and promotion gates set groundTruthUsedForDecision=false",
                "real TextBoxes/BubbleMask/SegmentMask remain blocked until active external artifact readiness passes; proxy reports are not renamed as real Koharu artifacts"
            ]
        )
    }

    private static func koharuArtifactConsumers(for stageName: String) -> [String] {
        let edges = koharuArtifactDependencyEdges(realArtifactsAvailable: false)
        return edges.filter { $0.fromStage == stageName }.map { $0.toStage }.sorted()
    }

    private static func makeKoharuNativeReplicationScoreboardReport(
        blocks: [MangaOverlayProbeBlock],
        diagnostics: MangaOverlayProbeDiagnostics,
        textRegionCropReport: MangaOverlayTextRegionCropReport?,
        textBoxPlanFailureReport: MangaOverlayTextBoxPlanFailureReport?,
        lineCropExperimentReport: MangaOverlayLineCropExperimentReport?,
        bubbleMaskReport: MangaOverlayBubbleMaskReport?,
        bubbleAssignmentCorrectionReport: MangaOverlayBubbleAssignmentCorrectionReport?,
        bubbleSplitCandidateReport: MangaOverlayBubbleSplitCandidateReport?,
        segmentMaskReport: MangaOverlaySegmentMaskReport?,
        readingOrderStructureAuditReport: MangaReadingOrderStructureAuditReport?,
        structureActionCandidateReport: MangaStructureActionCandidateReport?,
        internalStructureBottleneckReport: MangaOverlayInternalStructureBottleneckReport?,
        ocrCharacterDamageAuditReport: MangaOCRCharacterDamageAuditReport?,
        koharuArtifactDAGReport: MangaKoharuArtifactDAGReport?,
        koharuStageGapReplicationReport: MangaKoharuStageGapReplicationReport?,
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?,
        externalTextBoxShadowOCRReport: MangaOverlayExternalTextBoxShadowOCRReport?,
        cleanTextDiagnostic: MangaCleanTextDiagnosticReport?
    ) -> MangaKoharuNativeReplicationScoreboardReport {
        func uniqueSorted(_ values: [Int]) -> [Int] {
            Array(Set(values)).sorted()
        }
        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaKoharuNativeMetricSignal {
            MangaKoharuNativeMetricSignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }
        func joined(_ values: [Int]) -> String {
            values.map(String.init).joined(separator: ",")
        }
        func countBy(_ values: [String]) -> [String: Int] {
            values.reduce(into: [:]) { partial, value in
                partial[value, default: 0] += 1
            }
        }

        let allBlockIndexes = blocks.map(\.index).sorted()
        let cleanPassRate = cleanTextDiagnostic?.passRate ?? 0
        let cleanTextModelFloorLow = cleanTextDiagnostic.map { $0.passRate < 0.80 } ?? true
        let textBoxStopBlocks = textBoxPlanFailureReport?.stopRecommendedBlocks ?? []
        let lineStopBlocks = lineCropExperimentReport?.stoppedAfterLineResearchBlocks ?? []
        let stopLocalTuningBlocks = uniqueSorted(textBoxStopBlocks + lineStopBlocks)
        let bubbleConflictBlocks = uniqueSorted(
            (bubbleMaskReport?.inconsistentBubbleAssignmentBlocks ?? [])
                + (readingOrderStructureAuditReport?.maskConflictBlocks ?? [])
                + (bubbleAssignmentCorrectionReport?.recommendedCorrectionBlocks ?? [])
        )
        let bubbleSplitBlocks = uniqueSorted(readingOrderStructureAuditReport?.splitRiskBlocks ?? [])
        let segmentWeakBlocks = uniqueSorted(segmentMaskReport?.weakSegmentBlocks ?? [])
        let renderIssueBlocks = uniqueSorted(
            diagnostics.renderCollisionUnresolvedBlocks
                + diagnostics.renderTextTruncatedBlocks
                + blocks.filter { $0.renderMaskOverflowPixelCount > 0 }.map(\.index)
        )
        let translationModelBlocks = uniqueSorted(
            blocks
                .filter { $0.failureCategory == "modelOutputFailure" || $0.failureCategory == "translationLanguageQualityFailure" }
                .map(\.index)
        )
        let ocrInputBlocks = uniqueSorted(blocks.filter { $0.failureCategory == "ocrInputSuspect" }.map(\.index))
        let externalArtifactReady = externalArtifactReadinessReport?.externalTextBoxesShadowOCRAllowed == true
        let externalStatus = externalArtifactReady ? "passed" : "externalOptionalMissing"

        let textBoxFailureByBlock = Dictionary(
            uniqueKeysWithValues: (textBoxPlanFailureReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let lineFailureByBlock = Dictionary(
            uniqueKeysWithValues: (lineCropExperimentReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let segmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentMaskReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let bottleneckByBlock = Dictionary(
            uniqueKeysWithValues: (internalStructureBottleneckReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let damageByBlock = Dictionary(
            uniqueKeysWithValues: (ocrCharacterDamageAuditReport?.cases ?? []).map { ($0.blockIndex, $0) }
        )
        let dagByBlock = Dictionary(
            uniqueKeysWithValues: (koharuArtifactDAGReport?.blockTraces ?? []).map { ($0.blockIndex, $0) }
        )
        let stageGapByBlock = Dictionary(
            uniqueKeysWithValues: (koharuStageGapReplicationReport?.blockPlans ?? []).map { ($0.blockIndex, $0) }
        )

        let blockScorecards: [MangaKoharuNativeBlockScorecard] = blocks.map { block in
            var stopEvidence: [String] = []
            if textBoxStopBlocks.contains(block.index) {
                stopEvidence.append("textBoxPlanFailureReport.stopRecommendedBlocks")
            }
            if lineStopBlocks.contains(block.index) {
                stopEvidence.append("lineCropExperimentReport.stoppedAfterLineResearchBlocks")
            }
            let textBoxFailure = textBoxFailureByBlock[block.index]
            if textBoxFailure?.promotionBlockers.contains(where: { $0.contains("rawWordsLost") || $0.contains("wordPreservation") }) == true {
                stopEvidence.append("wordPreservationGuardrail")
            }
            if textBoxFailure?.promotionBlockers.contains(where: { $0.contains("rawWordsLost") }) == true {
                stopEvidence.append("rawWordsLost")
            }

            let segment = segmentByBlock[block.index]
            let renderGateStatus = renderIssueBlocks.contains(block.index) ? "blocked" : "passed"
            let bubbleGateStatus = bubbleConflictBlocks.contains(block.index) || bubbleSplitBlocks.contains(block.index) || block.bubbleID == nil ? "warning" : "passed"
            let segmentGateStatus = segmentWeakBlocks.contains(block.index) || segment?.glyphEscapesBubble == true ? "warning" : "passed"
            let stopLocal = !stopEvidence.isEmpty
            let ocrGateStatus: String
            if stopLocal {
                ocrGateStatus = "stop"
            } else if block.failureCategory == "ocrInputSuspect" {
                ocrGateStatus = "blocked"
            } else if block.wordOrderPreserved == false {
                ocrGateStatus = "warning"
            } else {
                ocrGateStatus = "passed"
            }
            let translationGateStatus: String
            if translationModelBlocks.contains(block.index), cleanTextModelFloorLow {
                translationGateStatus = "warning"
            } else if translationModelBlocks.contains(block.index) {
                translationGateStatus = "blocked"
            } else if block.blockPassed {
                translationGateStatus = "passed"
            } else {
                translationGateStatus = "warning"
            }

            let primaryStage: String
            let primaryBottleneck: String
            let priority: String
            let workItemID: String
            let nextAction: String
            if translationModelBlocks.contains(block.index), cleanTextModelFloorLow {
                primaryStage = "translations"
                primaryBottleneck = "translationModelQuality"
                priority = "P1"
                workItemID = "WI-translation-model-floor-comparison"
                nextAction = "compareModelOrPromptWithoutChangingMainPrompt"
            } else if stopLocal {
                primaryStage = "nativeTextBoxes"
                primaryBottleneck = "cropLineDeskewStoplist"
                priority = "stop"
                workItemID = "WI-native-textbox-artifact-scorecard"
                nextAction = "stopLocalCropLineDeskewTuningAndScoreNativeTextBoxEvidence"
            } else if block.failureCategory == "ocrInputSuspect" {
                primaryStage = "ocrText"
                primaryBottleneck = "ocrInputQuality"
                priority = "P1"
                workItemID = "WI-native-textbox-artifact-scorecard"
                nextAction = "moveToNativeTextBoxAndBubbleEvidenceScorecard"
            } else if bubbleGateStatus == "warning" {
                primaryStage = "nativeBubbleMask"
                primaryBottleneck = "bubbleAssignmentOrSplit"
                priority = "P1"
                workItemID = "WI-bubblemask-assignment-split-scorecard"
                nextAction = "reviewBubbleAssignmentAndSplitScorecard"
            } else if segmentGateStatus == "warning" {
                primaryStage = "nativeSegmentMask"
                primaryBottleneck = "segmentMaskProxyCoverage"
                priority = "P2"
                workItemID = "WI-segmentmask-proxy-coverage-scorecard"
                nextAction = "keepSegmentMaskProxyReportOnlyAndAuditCoverage"
            } else if renderGateStatus != "passed" {
                primaryStage = "finalRender"
                primaryBottleneck = "renderLayout"
                priority = "P2"
                workItemID = "WI-render-regression-lock"
                nextAction = "lockRenderSafeAreaAndFailureOverlayRegression"
            } else {
                primaryStage = block.blockPassed ? "finalRender" : "ocrText"
                primaryBottleneck = bottleneckByBlock[block.index]?.primaryBottleneck ?? "reportOnlyReview"
                priority = block.blockPassed ? "P3" : "manualReview"
                workItemID = block.blockPassed ? "WI-render-regression-lock" : "WI-native-textbox-artifact-scorecard"
                nextAction = block.blockPassed ? "retainRenderRegressionLock" : "manualReviewNativeScorecard"
            }

            let prioritySignals = [
                "failureCategory=\(block.failureCategory)",
                "cleanTextPassRate=\(cleanPassRate.formatted(.number.precision(.fractionLength(4))))",
                "ocrGate=\(ocrGateStatus)",
                "bubbleGate=\(bubbleGateStatus)",
                "segmentGate=\(segmentGateStatus)",
                "translationGate=\(translationGateStatus)",
                "renderGate=\(renderGateStatus)"
            ]
            var mustNotPromote = [
                "diagnosticOnly=true",
                "wouldChangeMainFlow=false",
                "groundTruthUsedForDecision=false"
            ]
            mustNotPromote += textBoxFailure?.promotionBlockers ?? []
            mustNotPromote += lineFailureByBlock[block.index]?.stopReasons ?? []
            mustNotPromote += bottleneckByBlock[block.index]?.mustNotPromoteReasons ?? []
            mustNotPromote += damageByBlock[block.index]?.mustNotPromoteReasons ?? []
            mustNotPromote += dagByBlock[block.index]?.stageTraces.flatMap(\.blockers) ?? []
            mustNotPromote += stageGapByBlock[block.index]?.mustNotPromoteReasons ?? []

            return MangaKoharuNativeBlockScorecard(
                blockIndex: block.index,
                groundTruthMatch: block.groundTruthMatch,
                bestGroundTruthType: block.bestGroundTruthType,
                ocrSimilarityForEvaluation: block.ocrGroundTruthSimilarity,
                blockPassed: block.blockPassed,
                failureCategory: block.failureCategory,
                bubbleID: block.bubbleID,
                primaryNativeStage: primaryStage,
                primaryBottleneck: primaryBottleneck,
                recommendedPriority: priority,
                prioritySignals: prioritySignals,
                priorityUsedGroundTruth: false,
                ocrGateStatus: ocrGateStatus,
                bubbleGateStatus: bubbleGateStatus,
                segmentGateStatus: segmentGateStatus,
                translationGateStatus: translationGateStatus,
                renderGateStatus: renderGateStatus,
                stopLocalCropOrLineTuning: stopLocal,
                stopEvidence: Array(Set(stopEvidence)).sorted(),
                mustNotPromoteReasons: Array(Set(mustNotPromote)).sorted(),
                recommendedWorkItemID: workItemID,
                nextAction: nextAction
            )
        }

        func stage(
            _ name: String,
            artifact: String,
            status: String,
            gateStatus: String,
            bottleneck: String,
            affected: [Int],
            stop: Bool,
            workItem: String,
            decisions: [MangaKoharuNativeMetricSignal],
            evaluations: [MangaKoharuNativeMetricSignal] = []
        ) -> MangaKoharuNativeStageScorecard {
            MangaKoharuNativeStageScorecard(
                stageName: name,
                referenceKoharuArtifact: artifact,
                nativeStatus: status,
                decisionSignals: decisions,
                evaluationSignals: evaluations,
                primaryGateStatus: gateStatus,
                primaryBottleneck: bottleneck,
                affectedBlocks: uniqueSorted(affected),
                stopLocalTuning: stop,
                nextWorkItemID: workItem,
                groundTruthUsedForEvaluationOnly: !evaluations.isEmpty,
                groundTruthUsedForDecision: false,
                diagnosticOnly: true,
                wouldChangeMainFlow: false
            )
        }

        let evaluationSignals = [
            signal("averageCoreDialogueOCRSimilarity", diagnostics.averageCoreDialogueOCRSimilarity.formatted(.number.precision(.fractionLength(4))), source: "probe_report.diagnostics", decision: false, evaluation: true),
            signal("averageDecorativeOCRSimilarity", diagnostics.averageDecorativeOCRSimilarity.formatted(.number.precision(.fractionLength(4))), source: "probe_report.diagnostics", decision: false, evaluation: true),
            signal("groundTruthMatchedBlocks", String(diagnostics.groundTruthMatchedBlocks), source: "probe_report.diagnostics", decision: false, evaluation: true),
            signal("groundTruthUnmatchedBlocks", String(diagnostics.groundTruthUnmatchedBlocks), source: "probe_report.diagnostics", decision: false, evaluation: true)
        ]
        let stageScorecards: [MangaKoharuNativeStageScorecard] = [
            stage("sourceImage", artifact: "SourceImage", status: "nativeReady", gateStatus: "passed", bottleneck: "none", affected: [], stop: false, workItem: "WI-render-regression-lock", decisions: [signal("sourceImage", "test/1.png", source: "MangaOverlayProbeConfiguration")]),
            stage("contentCrop", artifact: "ContentCrop", status: "nativeReady", gateStatus: "passed", bottleneck: "none", affected: [], stop: false, workItem: "WI-render-regression-lock", decisions: [signal("contentCropBeforeOCR", "true", source: "MangaOverlayProbeConfiguration")]),
            stage("nativeTextBoxes", artifact: "TextBoxes", status: stopLocalTuningBlocks.isEmpty ? "nativeProxyReady" : "nativeStopTuning", gateStatus: stopLocalTuningBlocks.isEmpty ? "warning" : "stop", bottleneck: "cropLineDeskewStoplist", affected: stopLocalTuningBlocks, stop: !stopLocalTuningBlocks.isEmpty, workItem: "WI-native-textbox-artifact-scorecard", decisions: [
                signal("textRegionCropAdoptedCount", String(textRegionCropReport?.adoptedCount ?? 0), source: "textRegionCropReport"),
                signal("textBoxStopBlocks", joined(stopLocalTuningBlocks), source: "textBoxPlanFailureReport,lineCropExperimentReport")
            ], evaluations: evaluationSignals),
            stage("nativeBubbleMask", artifact: "BubbleMask", status: "nativeProxyReady", gateStatus: bubbleConflictBlocks.isEmpty ? "passed" : "warning", bottleneck: "bubbleAssignmentOrSplit", affected: uniqueSorted(bubbleConflictBlocks + bubbleSplitBlocks), stop: false, workItem: "WI-bubblemask-assignment-split-scorecard", decisions: [
                signal("bubbleConflictBlocks", joined(bubbleConflictBlocks), source: "bubbleMaskReport,readingOrderStructureAuditReport"),
                signal("splitRiskBlocks", joined(bubbleSplitBlocks), source: "readingOrderStructureAuditReport")
            ]),
            stage("nativeSegmentMask", artifact: "SegmentMask", status: "nativeProxyReady", gateStatus: segmentWeakBlocks.isEmpty ? "passed" : "warning", bottleneck: "segmentMaskProxyCoverage", affected: segmentWeakBlocks, stop: false, workItem: "WI-segmentmask-proxy-coverage-scorecard", decisions: [
                signal("weakSegmentBlocks", joined(segmentWeakBlocks), source: "segmentMaskReport"),
                signal("usableForCropEvidenceBlocks", joined(segmentMaskReport?.usableForCropEvidenceBlocks ?? []), source: "segmentMaskReport")
            ]),
            stage("ocrText", artifact: "OcrText", status: stopLocalTuningBlocks.isEmpty ? "shadowBlocked" : "nativeStopTuning", gateStatus: stopLocalTuningBlocks.isEmpty ? "blocked" : "stop", bottleneck: "ocrInputQuality", affected: uniqueSorted(ocrInputBlocks + stopLocalTuningBlocks), stop: !stopLocalTuningBlocks.isEmpty, workItem: "WI-native-textbox-artifact-scorecard", decisions: [
                signal("ocrInputSuspectBlocks", joined(ocrInputBlocks), source: "blocks.failureCategory"),
                signal("textBoxPlanPromotedShadowBlockCount", String(textBoxPlanFailureReport?.promotedShadowBlockCount ?? 0), source: "textBoxPlanFailureReport")
            ], evaluations: evaluationSignals),
            stage("translations", artifact: "Translations", status: cleanTextModelFloorLow ? "modelLimited" : "nativeReady", gateStatus: cleanTextModelFloorLow ? "warning" : "passed", bottleneck: "translationModelQuality", affected: translationModelBlocks, stop: false, workItem: "WI-translation-model-floor-comparison", decisions: [
                signal("cleanTextPassRate", cleanPassRate.formatted(.number.precision(.fractionLength(4))), source: "clean_text_diagnostic.json"),
                signal("translationFailureBreakdown", diagnostics.translationFailureBreakdown.map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ","), source: "probe_report.diagnostics")
            ]),
            stage("glyphEraseOrInpaintProxy", artifact: "Inpainted", status: "nativeProxyReady", gateStatus: segmentWeakBlocks.isEmpty ? "passed" : "warning", bottleneck: "segmentMaskProxyOnly", affected: segmentWeakBlocks, stop: false, workItem: "WI-segmentmask-proxy-coverage-scorecard", decisions: [
                signal("glyphMaskBlocks", String(diagnostics.glyphMaskBlocks), source: "probe_report.diagnostics"),
                signal("proxyNotRealSegmentMask", "true", source: "segmentMaskReport")
            ]),
            stage("renderedSprites", artifact: "RenderedSprites", status: renderIssueBlocks.isEmpty ? "renderStable" : "shadowBlocked", gateStatus: renderIssueBlocks.isEmpty ? "passed" : "blocked", bottleneck: "renderLayout", affected: renderIssueBlocks, stop: false, workItem: "WI-render-regression-lock", decisions: [
                signal("renderIssueBlocks", joined(renderIssueBlocks), source: "renderDiagnostics")
            ]),
            stage("finalRender", artifact: "FinalRender", status: renderIssueBlocks.isEmpty ? "renderStable" : "shadowBlocked", gateStatus: renderIssueBlocks.isEmpty ? "passed" : "blocked", bottleneck: "finalOverlay", affected: renderIssueBlocks, stop: false, workItem: "WI-render-regression-lock", decisions: [
                signal("failedBlocksStillRendered", "true", source: "1_translated_overlay.png"),
                signal("outputOverlayRequired", "true", source: "MangaOverlayProbeService.drawTranslatedOverlay")
            ])
        ]

        func gate(
            id: String,
            name: String,
            scope: String,
            status: String,
            affected: [Int],
            failureMeans: String,
            action: String,
            threshold: String,
            decisions: [MangaKoharuNativeMetricSignal],
            evaluations: [MangaKoharuNativeMetricSignal] = []
        ) -> MangaKoharuNativeGateLedgerEntry {
            MangaKoharuNativeGateLedgerEntry(
                gateID: id,
                gateName: name,
                scope: scope,
                status: status,
                requiredForMainFlowPromotion: true,
                decisionSignals: decisions,
                evaluationSignals: evaluations,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                failureMeans: failureMeans,
                recommendedAction: action,
                groundTruthUsedForDecision: false
            )
        }

        let gateLedger: [MangaKoharuNativeGateLedgerEntry] = [
            gate(id: "G-no-main-flow-mutation", name: "No main flow mutation", scope: "report", status: "passed", affected: [], failureMeans: "scoreboard changed OCR, translation, cleanup, overlay, or blockPassed", action: "revertBehavioralChange", threshold: "all report-only flags true", decisions: [signal("wouldChangeMainFlow", "false", source: "koharuNativeReplicationScoreboardReport")]),
            gate(id: "G-no-ground-truth-decision", name: "No ground truth decision", scope: "report", status: "passed", affected: [], failureMeans: "ground truth influenced candidate generation, ordering, promotion, cleanup, or priority", action: "removeGroundTruthFromDecisionPath", threshold: "groundTruthUsedForDecision=false", decisions: [signal("groundTruthUsedForDecision", "false", source: "koharuNativeReplicationScoreboardReport")], evaluations: evaluationSignals),
            gate(id: "G-native-textbox-word-preservation", name: "Native TextBox word preservation", scope: "nativeTextBoxes", status: stopLocalTuningBlocks.isEmpty ? "warning" : "stop", affected: stopLocalTuningBlocks, failureMeans: "crop, TextBox, or line shadow loses raw keywords", action: "freezeLocalCropLineDeskewTuning", threshold: "no rawWordsLost and word preservation guardrail passes", decisions: [signal("stopLocalTuningBlocks", joined(stopLocalTuningBlocks), source: "textBoxPlanFailureReport,lineCropExperimentReport")]),
            gate(id: "G-native-textbox-stoplist", name: "Native TextBox stoplist", scope: "nativeTextBoxes", status: stopLocalTuningBlocks.isEmpty ? "passed" : "stop", affected: stopLocalTuningBlocks, failureMeans: "known failed crop, line, or deskew local tuning is recommended again", action: "routeToNativeScoreboardOrModelFloor", threshold: "stoplist blocks are not recommended for more local tuning", decisions: [signal("textBoxStopBlocks", joined(textBoxStopBlocks), source: "textBoxPlanFailureReport"), signal("lineStopBlocks", joined(lineStopBlocks), source: "lineCropExperimentReport")]),
            gate(id: "G-bubble-assignment-conflict", name: "Bubble assignment conflict", scope: "nativeBubbleMask", status: bubbleConflictBlocks.isEmpty ? "passed" : "warning", affected: uniqueSorted(bubbleConflictBlocks + bubbleSplitBlocks), failureMeans: "cross-bubble merge or proxy conflict is promoted into main flow", action: "keepBubbleConflictReportOnly", threshold: "conflicts remain shadow/report-only", decisions: [signal("bubbleConflictBlocks", joined(bubbleConflictBlocks), source: "bubbleMaskReport,readingOrderStructureAuditReport")]),
            gate(id: "G-segment-mask-inside-bubble", name: "Segment mask inside bubble", scope: "nativeSegmentMask", status: segmentWeakBlocks.isEmpty ? "passed" : "warning", affected: segmentWeakBlocks, failureMeans: "glyph or segment proxy escapes bubble or is treated as real Koharu SegmentMask", action: "keepSegmentProxyForRenderAndReportsOnly", threshold: "no glyph escape and proxy label retained", decisions: [signal("weakSegmentBlocks", joined(segmentWeakBlocks), source: "segmentMaskReport")]),
            gate(id: "G-clean-text-model-floor", name: "Clean text model floor", scope: "translations", status: cleanTextModelFloorLow ? "warning" : "passed", affected: translationModelBlocks, failureMeans: "translation failure is misattributed only to OCR while clean text pass rate is low", action: "keepModelLimitedClassification", threshold: "cleanTextDiagnostic.passRate >= 0.80", decisions: [signal("cleanTextPassRate", cleanPassRate.formatted(.number.precision(.fractionLength(4))), source: "clean_text_diagnostic.json")]),
            gate(id: "G-render-failure-overlay", name: "Render failure overlay", scope: "finalRender", status: "passed", affected: [], failureMeans: "failed block is silently skipped", action: "retainFailureOverlayContract", threshold: "failed blocks draw failure text plus OCR source", decisions: [signal("failedBlocks", String(diagnostics.failedBlocks), source: "probe_report.diagnostics")]),
            gate(id: "G-render-no-overflow", name: "Render no overflow", scope: "finalRender", status: renderIssueBlocks.isEmpty ? "passed" : "blocked", affected: renderIssueBlocks, failureMeans: "overlay is inverted, mirrored, truncated, or out of bounds", action: "lockRenderSafeAreaBeforeOCRChanges", threshold: "no unresolved overflow or truncation", decisions: [signal("renderIssueBlocks", joined(renderIssueBlocks), source: "renderDiagnostics")]),
            gate(id: "G-external-artifact-optional", name: "External artifact optional", scope: "externalArtifacts", status: externalStatus, affected: externalArtifactReady ? [] : allBlockIndexes, failureMeans: "missing external artifact blocks the native scoreboard or proxy is renamed real Koharu artifact", action: "recordOptionalExternalPathOnly", threshold: "externalArtifactsRequiredForThisReport=false", decisions: [signal("readinessVerdict", externalArtifactReadinessReport?.readinessVerdict ?? "missing", source: "externalArtifactReadinessReport")])
        ]

        func workItem(
            _ id: String,
            title: String,
            priority: String,
            stages: [String],
            blocks: [Int],
            why: String,
            decisions: [MangaKoharuNativeMetricSignal],
            evaluations: [MangaKoharuNativeMetricSignal] = [],
            ciFast: Bool,
            full: Bool,
            external: Bool,
            metrics: [String],
            blockedBy: [String],
            stops: [String],
            nonGoals: [String],
            branch: String
        ) -> MangaKoharuNativeWorkItem {
            MangaKoharuNativeWorkItem(
                workItemID: id,
                title: title,
                priority: priority,
                targetStages: stages,
                targetBlocks: uniqueSorted(blocks),
                whyNow: why,
                decisionSignals: decisions,
                evaluationSignals: evaluations,
                canRunInCIFast: ciFast,
                requiresFullProbe: full,
                requiresExternalArtifact: external,
                expectedMetricMovement: metrics,
                blockedByGates: blockedBy,
                stopConditions: stops,
                nonGoals: nonGoals,
                suggestedBranchName: branch
            )
        }

        let recommendedNextWorkItems: [MangaKoharuNativeWorkItem] = [
            workItem("WI-native-textbox-artifact-scorecard", title: "Score native TextBox proxy evidence and freeze failed crop/line/deskew tuning", priority: "P0", stages: ["nativeTextBoxes", "ocrText"], blocks: uniqueSorted(stopLocalTuningBlocks + ocrInputBlocks), why: "Existing crop and line shadow reports have stop evidence; next work should score native structure evidence instead of more local parameter tuning.", decisions: [signal("stopLocalTuningBlocks", joined(stopLocalTuningBlocks), source: "textBoxPlanFailureReport,lineCropExperimentReport")], evaluations: evaluationSignals, ciFast: true, full: false, external: false, metrics: ["stoplist stability", "word preservation guardrail", "OCR similarity evaluation-only"], blockedBy: ["G-native-textbox-stoplist"], stops: ["stop if proposed work changes finalTextUsedForTranslation", "stop if priority uses ground truth"], nonGoals: ["do not run more crop/line/deskew tuning", "do not promote shadow OCR"], branch: "codeb/vNEXT-native-textbox-scorecard"),
            workItem("WI-bubblemask-assignment-split-scorecard", title: "Score BubbleMask assignment, split risk, and sibling layout", priority: "P1", stages: ["nativeBubbleMask"], blocks: uniqueSorted(bubbleConflictBlocks + bubbleSplitBlocks), why: "Bubble conflicts and split risks are structural evidence that can be scored without external artifacts.", decisions: [signal("bubbleConflictBlocks", joined(bubbleConflictBlocks), source: "bubbleMaskReport,readingOrderStructureAuditReport")], ciFast: true, full: false, external: false, metrics: ["conflict blocks", "split risk blocks", "same-bubble sibling count"], blockedBy: ["G-bubble-assignment-conflict"], stops: ["stop if any proposal crosses bubble boundaries"], nonGoals: ["do not call proxy mask real Koharu BubbleMask"], branch: "codeb/vNEXT-bubblemask-scorecard"),
            workItem("WI-segmentmask-proxy-coverage-scorecard", title: "Score SegmentMask proxy coverage for render/report-only use", priority: "P2", stages: ["nativeSegmentMask", "glyphEraseOrInpaintProxy"], blocks: segmentWeakBlocks, why: "Glyph and connected-component evidence is useful for coverage and rendering, but must stay proxy-only.", decisions: [signal("weakSegmentBlocks", joined(segmentWeakBlocks), source: "segmentMaskReport")], ciFast: true, full: false, external: false, metrics: ["weak segment blocks", "inside bubble coverage", "render collision"], blockedBy: ["G-segment-mask-inside-bubble"], stops: ["stop if proxy is used as real SegmentMask"], nonGoals: ["do not implement inpainting", "do not change OCR input"], branch: "codeb/vNEXT-segmentmask-proxy-scorecard"),
            workItem("WI-translation-model-floor-comparison", title: "Compare model or prompt floor without changing the main prompt", priority: "P1", stages: ["translations"], blocks: translationModelBlocks, why: "Clean text pass rate is the model floor; failures should not be treated as pure OCR work.", decisions: [signal("cleanTextPassRate", cleanPassRate.formatted(.number.precision(.fractionLength(4))), source: "clean_text_diagnostic.json")], ciFast: true, full: false, external: false, metrics: ["clean text pass rate", "model output failure count", "translation language quality failure count"], blockedBy: ["G-clean-text-model-floor"], stops: ["stop if comparison changes main prompt or model"], nonGoals: ["do not swap model", "do not loosen quality rules"], branch: "codeb/vNEXT-translation-floor-comparison"),
            workItem("WI-render-regression-lock", title: "Lock safe layout, failure overlay, and no-overflow render invariants", priority: "P2", stages: ["renderedSprites", "finalRender"], blocks: renderIssueBlocks, why: "Rendering is stable when no overflow/truncation is present; keep it protected while structure reports evolve.", decisions: [signal("renderIssueBlocks", joined(renderIssueBlocks), source: "renderDiagnostics")], ciFast: true, full: false, external: false, metrics: ["unresolved overflow blocks", "truncated blocks", "failure overlay retained"], blockedBy: ["G-render-failure-overlay", "G-render-no-overflow"], stops: ["stop if failed blocks disappear from overlay"], nonGoals: ["do not implement true sprite rendering"], branch: "codeb/vNEXT-render-regression-lock"),
            workItem("WI-external-artifact-optional-handoff", title: "Record optional external artifact handoff state", priority: "P3", stages: ["nativeTextBoxes", "nativeBubbleMask", "nativeSegmentMask"], blocks: externalArtifactReady ? [] : allBlockIndexes, why: "Real Koharu artifacts are optional for this native scoreboard but the handoff state must remain explicit.", decisions: [signal("readinessVerdict", externalArtifactReadinessReport?.readinessVerdict ?? "missing", source: "externalArtifactReadinessReport")], ciFast: true, full: false, external: true, metrics: ["readiness verdict", "required files", "alignment status"], blockedBy: ["G-external-artifact-optional"], stops: ["stop if proxy evidence is renamed real artifact"], nonGoals: ["do not create active artifacts", "do not block native scoreboard"], branch: "codeb/vNEXT-external-artifact-optional-handoff")
        ]

        let stageStatusBreakdown = countBy(stageScorecards.map(\.nativeStatus))
        let gateStatusBreakdown = countBy(gateLedger.map(\.status))
        let blockPrimaryBottleneckBreakdown = countBy(blockScorecards.map(\.primaryBottleneck))
        let recommendedPriorityBreakdown = countBy(blockScorecards.map(\.recommendedPriority))

        return MangaKoharuNativeReplicationScoreboardReport(
            enabled: true,
            source: "AITRANSProbe",
            referencePipeline: "Koharu",
            evaluatedBlockCount: blocks.count,
            stageScorecardCount: stageScorecards.count,
            gateCount: gateLedger.count,
            workItemCount: recommendedNextWorkItems.count,
            externalArtifactsRequiredForThisReport: false,
            groundTruthUsedForEvaluationOnly: true,
            groundTruthUsedForDecision: false,
            stageStatusBreakdown: stageStatusBreakdown,
            gateStatusBreakdown: gateStatusBreakdown,
            blockPrimaryBottleneckBreakdown: blockPrimaryBottleneckBreakdown,
            recommendedPriorityBreakdown: recommendedPriorityBreakdown,
            stopLocalTuningBlocks: stopLocalTuningBlocks,
            nativeReadyStages: stageScorecards.filter { $0.nativeStatus == "nativeReady" }.map(\.stageName).sorted(),
            nativeProxyReadyStages: stageScorecards.filter { $0.nativeStatus == "nativeProxyReady" }.map(\.stageName).sorted(),
            shadowBlockedStages: stageScorecards.filter { $0.nativeStatus == "shadowBlocked" }.map(\.stageName).sorted(),
            modelLimitedStages: stageScorecards.filter { $0.nativeStatus == "modelLimited" }.map(\.stageName).sorted(),
            renderStableStages: stageScorecards.filter { $0.nativeStatus == "renderStable" }.map(\.stageName).sorted(),
            stageScorecards: stageScorecards,
            gateLedger: gateLedger,
            blockScorecards: blockScorecards,
            recommendedNextWorkItems: recommendedNextWorkItems,
            notes: [
                "koharuNativeReplicationScoreboardReport is report-only and uses AITRANS probe outputs to score local Koharu-style replication stages.",
                "externalArtifactsRequiredForThisReport=false; missing test/koharu_artifacts is recorded as optional external path state, not native scoreboard blockage.",
                "decision and gate signals are ground-truth-free; OCR ground truth metrics are evaluation-only and never used for priority or nextAction.",
                "crop, line, and deskew local tuning stoplist is explicit so later work moves to native structure scoring or model floor comparison.",
                "does not run OCR or LLM and does not change main OCR, translation input, overlay drawing, blockPassed, failureCategory, cleanup, candidate selection, or currentBlockSource."
            ]
        )
    }

    private static func makeNativeTextBoxProxyLedgerReport(
        blocks: [MangaOverlayProbeBlock],
        diagnostics: MangaOverlayProbeDiagnostics,
        textRegionCropReport: MangaOverlayTextRegionCropReport?,
        preCropTextBoxPlanReport: MangaOverlayPreCropTextBoxPlanReport?,
        cropExperimentReport: MangaOverlayCropExperimentReport?,
        textBoxPlanFailureReport: MangaOverlayTextBoxPlanFailureReport?,
        lineTextBoxPlanReport: MangaOverlayLineTextBoxPlanReport?,
        lineCropExperimentReport: MangaOverlayLineCropExperimentReport?,
        bubbleMaskReport: MangaOverlayBubbleMaskReport?,
        segmentMaskReport: MangaOverlaySegmentMaskReport?,
        internalStructureBottleneckReport: MangaOverlayInternalStructureBottleneckReport?,
        ocrCharacterDamageAuditReport: MangaOCRCharacterDamageAuditReport?,
        koharuNativeReplicationScoreboardReport: MangaKoharuNativeReplicationScoreboardReport?,
        cleanTextDiagnostic: MangaCleanTextDiagnosticReport?
    ) -> MangaNativeTextBoxProxyLedgerReport {
        func uniqueSorted(_ values: [Int]) -> [Int] {
            Array(Set(values)).sorted()
        }
        func countBy(_ values: [String]) -> [String: Int] {
            values.reduce(into: [:]) { partial, value in
                partial[value, default: 0] += 1
            }
        }
        func joined(_ values: [Int]) -> String {
            values.map(String.init).joined(separator: ",")
        }
        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaNativeTextBoxProxySignal {
            MangaNativeTextBoxProxySignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }
        func containsAny(_ values: [String], needles: [String]) -> Bool {
            values.contains { value in
                needles.contains { value.localizedCaseInsensitiveContains($0) }
            }
        }
        func preview(_ text: String?) -> String? {
            guard let text, !text.isEmpty else { return nil }
            let flat = text.replacing("\n", with: " ")
            return flat.count > 96 ? String(flat.prefix(96)) : flat
        }

        let textRegionByBlock = Dictionary(
            uniqueKeysWithValues: (textRegionCropReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let preCropPlansByBlock = Dictionary(grouping: preCropTextBoxPlanReport?.plans ?? [], by: \.blockIndex)
        let cropCandidatesByBlock = Dictionary(grouping: cropExperimentReport?.candidates ?? [], by: \.blockIndex)
        let linePlansByBlock = Dictionary(grouping: lineTextBoxPlanReport?.plans ?? [], by: \.blockIndex)
        let lineCandidatesByBlock = Dictionary(grouping: lineCropExperimentReport?.candidates ?? [], by: \.blockIndex)
        let textBoxFailureByBlock = Dictionary(
            uniqueKeysWithValues: (textBoxPlanFailureReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let lineFailureByBlock = Dictionary(
            uniqueKeysWithValues: (lineCropExperimentReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let segmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentMaskReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let bottleneckByBlock = Dictionary(
            uniqueKeysWithValues: (internalStructureBottleneckReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let damageByBlock = Dictionary(
            uniqueKeysWithValues: (ocrCharacterDamageAuditReport?.cases ?? []).map { ($0.blockIndex, $0) }
        )
        let nativeScorecardByBlock = Dictionary(
            uniqueKeysWithValues: (koharuNativeReplicationScoreboardReport?.blockScorecards ?? []).map { ($0.blockIndex, $0) }
        )

        var candidateLedgers: [MangaNativeTextBoxProxyCandidateLedger] = []
        for block in blocks {
            var rank = 0
            func appendCandidate(
                id: String,
                source: String,
                bbox: [Double],
                clampSource: String?,
                bubbleID: Int?,
                text: String?,
                rawWordsPreserved: Bool?,
                protectedKeywordsPreserved: Bool?,
                wordCountDelta: Int?,
                bubbleContained: Bool?,
                segmentMaskSupported: Bool?,
                introducedLikelyOCRError: Bool,
                promotionVerdict: String,
                blockers: [String]
            ) {
                rank += 1
                candidateLedgers.append(
                    MangaNativeTextBoxProxyCandidateLedger(
                        candidateID: id,
                        blockIndex: block.index,
                        source: source,
                        bbox: bbox,
                        clampSource: clampSource,
                        bubbleID: bubbleID,
                        textPreview: preview(text),
                        rawWordsPreserved: rawWordsPreserved,
                        protectedKeywordsPreserved: protectedKeywordsPreserved,
                        wordCountDelta: wordCountDelta,
                        bubbleContained: bubbleContained,
                        segmentMaskSupported: segmentMaskSupported,
                        introducedLikelyOCRError: introducedLikelyOCRError,
                        promotionVerdict: promotionVerdict,
                        promotionBlockers: Array(Set(blockers)).sorted(),
                        reportOnlyRank: rank,
                        groundTruthUsedForDecision: false,
                        wouldChangeMainFlow: false
                    )
                )
            }

            appendCandidate(
                id: "fusedSeedBBox.\(block.index)",
                source: "fusedSeedBBox",
                bbox: block.bbox,
                clampSource: "fusedWholePageBubble",
                bubbleID: block.bubbleID,
                text: block.finalTextUsedForTranslation,
                rawWordsPreserved: true,
                protectedKeywordsPreserved: true,
                wordCountDelta: 0,
                bubbleContained: block.bubbleID != nil,
                segmentMaskSupported: segmentByBlock[block.index]?.usableForCropEvidence,
                introducedLikelyOCRError: false,
                promotionVerdict: "control",
                blockers: ["controlCandidateNotPromotion"]
            )
            if let crop = textRegionByBlock[block.index] {
                appendCandidate(
                    id: "textRegionCropControl.\(block.index)",
                    source: "textRegionCropControl",
                    bbox: crop.cropBBox,
                    clampSource: crop.clampSource,
                    bubbleID: block.bubbleID,
                    text: crop.selectedText,
                    rawWordsPreserved: crop.rawWordPreservationRatio >= 0.72,
                    protectedKeywordsPreserved: !containsAny(crop.failureAttribution + crop.rejectionReasons, needles: ["protected", "keyword"]),
                    wordCountDelta: nil,
                    bubbleContained: crop.cropClampedByBubble,
                    segmentMaskSupported: segmentByBlock[block.index]?.usableForCropEvidence,
                    introducedLikelyOCRError: crop.failureAttribution.contains("introducedLikelyOCRError"),
                    promotionVerdict: crop.adopted ? "adoptedByExistingGuardrail" : "rejectedByExistingGuardrail",
                    blockers: crop.rejectionReasons + crop.failureAttribution
                )
            }
            for plan in preCropPlansByBlock[block.index] ?? [] {
                appendCandidate(
                    id: "preCropTextBoxPlan.\(plan.planID)",
                    source: "preCropTextBoxPlan",
                    bbox: plan.bbox,
                    clampSource: "preCropPlan",
                    bubbleID: plan.bubbleID,
                    text: nil,
                    rawWordsPreserved: nil,
                    protectedKeywordsPreserved: !containsAny(plan.riskFlags + plan.rejectionReasons, needles: ["protected", "keyword"]),
                    wordCountDelta: nil,
                    bubbleContained: plan.bubbleCoverageRatio.map { $0 >= 0.50 },
                    segmentMaskSupported: plan.glyphCoverageRatio.map { $0 > 0 },
                    introducedLikelyOCRError: containsAny(plan.riskFlags + plan.rejectionReasons, needles: ["ocrError", "wordLoss"]),
                    promotionVerdict: plan.eligibleForShadowOCR ? "shadowOnlyEligible" : "reportOnlyRejected",
                    blockers: plan.riskFlags + plan.rejectionReasons
                )
            }
            for candidate in cropCandidatesByBlock[block.index] ?? [] {
                appendCandidate(
                    id: "cropExperimentShadow.\(candidate.candidateID)",
                    source: candidate.sourcePlanID == nil ? "textRegionCropControl" : "cropExperimentShadow",
                    bbox: candidate.bboxAfterClamp,
                    clampSource: candidate.clampSource,
                    bubbleID: block.bubbleID,
                    text: candidate.ocrText,
                    rawWordsPreserved: candidate.wordPreservationRatio >= 0.72,
                    protectedKeywordsPreserved: !containsAny(candidate.riskFlags + candidate.rejectionReasons, needles: ["protected", "keyword"]),
                    wordCountDelta: candidate.lineCountDelta,
                    bubbleContained: !containsAny(candidate.riskFlags + candidate.rejectionReasons, needles: ["bubbleConflict", "outsideBubble"]),
                    segmentMaskSupported: segmentByBlock[block.index]?.usableForCropEvidence,
                    introducedLikelyOCRError: containsAny(candidate.riskFlags + candidate.rejectionReasons, needles: ["introducedLikelyOCRError", "rawWordsLost"]),
                    promotionVerdict: candidate.betterThanControl ? "reportOnlyWouldImprove" : "reportOnlyNoImprovement",
                    blockers: candidate.riskFlags + candidate.rejectionReasons
                )
            }
            for plan in linePlansByBlock[block.index] ?? [] {
                appendCandidate(
                    id: "lineTextBoxPlan.\(plan.planID)",
                    source: "lineTextBoxPlan",
                    bbox: plan.bbox,
                    clampSource: "lineTextBoxPlan",
                    bubbleID: plan.bubbleID,
                    text: nil,
                    rawWordsPreserved: nil,
                    protectedKeywordsPreserved: !containsAny(plan.riskFlags + plan.rejectionReasons, needles: ["protected", "keyword"]),
                    wordCountDelta: nil,
                    bubbleContained: plan.bubbleCoverageRatio.map { $0 >= 0.50 },
                    segmentMaskSupported: plan.glyphCoverageRatio.map { $0 > 0 },
                    introducedLikelyOCRError: containsAny(plan.riskFlags + plan.rejectionReasons, needles: ["ocrError", "wordLoss"]),
                    promotionVerdict: plan.eligibleForShadowOCR ? "shadowOnlyEligible" : "reportOnlyRejected",
                    blockers: plan.riskFlags + plan.rejectionReasons
                )
            }
            for candidate in lineCandidatesByBlock[block.index] ?? [] {
                appendCandidate(
                    id: "lineCropShadow.\(candidate.candidateID)",
                    source: "lineCropShadow",
                    bbox: candidate.bboxAfterClamp,
                    clampSource: candidate.clampSource,
                    bubbleID: block.bubbleID,
                    text: candidate.ocrText,
                    rawWordsPreserved: candidate.wordPreservationRatio >= 0.72,
                    protectedKeywordsPreserved: !containsAny(candidate.riskFlags + candidate.rejectionReasons, needles: ["protected", "keyword"]),
                    wordCountDelta: candidate.lineCountDelta,
                    bubbleContained: !containsAny(candidate.riskFlags + candidate.rejectionReasons, needles: ["bubbleConflict", "outsideBubble"]),
                    segmentMaskSupported: segmentByBlock[block.index]?.usableForCropEvidence,
                    introducedLikelyOCRError: containsAny(candidate.riskFlags + candidate.rejectionReasons, needles: ["introducedLikelyOCRError", "rawWordsLost"]),
                    promotionVerdict: candidate.betterThanControl ? "reportOnlyWouldImprove" : "reportOnlyNoImprovement",
                    blockers: candidate.riskFlags + candidate.rejectionReasons
                )
            }
        }

        let textBoxStopBlocks = textBoxPlanFailureReport?.stopRecommendedBlocks ?? []
        let lineStopBlocks = lineCropExperimentReport?.stoppedAfterLineResearchBlocks ?? []
        var stopReasonsByBlock: [Int: [String]] = [:]
        for blockIndex in textBoxStopBlocks {
            stopReasonsByBlock[blockIndex, default: []].append("textBoxPlanFailureReport.stopRecommendedBlocks")
        }
        for blockIndex in lineStopBlocks {
            stopReasonsByBlock[blockIndex, default: []].append("lineCropExperimentReport.stoppedAfterLineResearchBlocks")
        }
        for scorecard in koharuNativeReplicationScoreboardReport?.blockScorecards ?? [] where scorecard.stopLocalCropOrLineTuning {
            stopReasonsByBlock[scorecard.blockIndex, default: []].append(contentsOf: scorecard.stopEvidence)
        }
        for summary in textBoxPlanFailureReport?.blockSummaries ?? [] {
            if containsAny(summary.promotionBlockers, needles: ["rawWordsLost", "wordPreservation", "introducedLikelyOCRError", "weakSegment", "bubbleConflict"]) {
                stopReasonsByBlock[summary.blockIndex, default: []].append(contentsOf: summary.promotionBlockers)
            }
        }

        let cleanPassRate = cleanTextDiagnostic?.passRate ?? 0
        let cleanTextModelFloorLow = cleanTextDiagnostic.map { $0.passRate < 0.80 } ?? true
        let bubbleConflictBlocks = uniqueSorted(bubbleMaskReport?.inconsistentBubbleAssignmentBlocks ?? [])
        let segmentWeakBlocks = uniqueSorted(segmentMaskReport?.weakSegmentBlocks ?? [])
        let translationModelBlocks = uniqueSorted(
            blocks
                .filter { $0.failureCategory == "modelOutputFailure" || $0.failureCategory == "translationLanguageQualityFailure" }
                .map(\.index)
        )
        let renderIssueBlocks = uniqueSorted(
            diagnostics.renderCollisionUnresolvedBlocks
                + diagnostics.renderTextTruncatedBlocks
                + blocks.filter { $0.renderMaskOverflowPixelCount > 0 }.map(\.index)
        )
        let candidateSourcesByBlock: [Int: [MangaNativeTextBoxProxyCandidateLedger]] = Dictionary(grouping: candidateLedgers, by: \.blockIndex)

        func sortedUniqueStrings(_ values: [String]) -> [String] {
            Array(Set(values)).sorted()
        }
        func promotionBlockers(for blockIndex: Int) -> [String] {
            var blockers: [String] = []
            blockers.append(contentsOf: textBoxFailureByBlock[blockIndex]?.promotionBlockers ?? [])
            blockers.append(contentsOf: lineFailureByBlock[blockIndex]?.stopReasons ?? [])
            blockers.append(contentsOf: bottleneckByBlock[blockIndex]?.mustNotPromoteReasons ?? [])
            blockers.append(contentsOf: damageByBlock[blockIndex]?.mustNotPromoteReasons ?? [])
            blockers.append(contentsOf: nativeScorecardByBlock[blockIndex]?.mustNotPromoteReasons ?? [])
            return sortedUniqueStrings(blockers)
        }
        func qualityDecision(
            stopReasons: [String],
            wordBlocked: Bool,
            bubbleBlocked: Bool,
            segmentBlocked: Bool,
            damageBlocked: Bool,
            modelBlocked: Bool,
            renderBlocked: Bool,
            hasShadowOnlyEligibleCandidate: Bool,
            blockPassed: Bool
        ) -> (qualityStatus: String, primaryFreezeReason: String?, nextAction: String) {
            if !stopReasons.isEmpty {
                return ("frozenByStoplist", stopReasons.first, "freezeLocalCropLineDeskew")
            }
            if wordBlocked {
                return ("blockedByWordPreservation", "wordPreservation", "freezeLocalCropLineDeskew")
            }
            if bubbleBlocked {
                return ("blockedByBubbleMaskConflict", "bubbleMaskConflict", "collectBubbleMaskEvidence")
            }
            if segmentBlocked {
                return ("blockedByWeakSegmentMask", "weakSegmentMask", "collectSegmentMaskEvidence")
            }
            if damageBlocked {
                return ("blockedByOCRDamage", "ocrDamage", "keepReportOnly")
            }
            if modelBlocked {
                return ("modelLimited", "translationModelFloor", "routeToTranslationModelFloor")
            }
            if hasShadowOnlyEligibleCandidate {
                return ("shadowOnlyEligible", nil, "eligibleForFutureShadowReview")
            }
            if blockPassed && !renderBlocked {
                return ("reportOnlyStable", nil, "keepReportOnly")
            }
            return ("manualReviewOnly", "insufficientCandidateDetail", "manualReviewOnly")
        }
        func decisionSignals(
            for block: MangaOverlayProbeBlock,
            candidateSources: [String],
            stopReasons: [String],
            blockers: [String]
        ) -> [MangaNativeTextBoxProxySignal] {
            [
                signal("failureCategory", block.failureCategory, source: "blocks.failureCategory"),
                signal("candidateSources", candidateSources.joined(separator: ","), source: "nativeTextBoxProxyLedgerReport.candidateLedgers"),
                signal("stoplistReasons", stopReasons.joined(separator: ","), source: "textBoxPlanFailureReport,lineCropExperimentReport,koharuNativeReplicationScoreboardReport"),
                signal("promotionBlockers", blockers.joined(separator: ","), source: "textBoxPlanFailureReport,lineCropExperimentReport"),
                signal("cleanTextPassRate", cleanPassRate.formatted(.number.precision(.fractionLength(4))), source: "clean_text_diagnostic.json")
            ]
        }
        func evaluationSignals(for block: MangaOverlayProbeBlock) -> [MangaNativeTextBoxProxySignal] {
            [
                signal("ocrGroundTruthSimilarity", block.ocrGroundTruthSimilarity?.formatted(.number.precision(.fractionLength(4))) ?? "nil", source: "blocks.ocrGroundTruthSimilarity", decision: false, evaluation: true),
                signal("bestGroundTruthType", block.bestGroundTruthType ?? "nil", source: "blocks.bestGroundTruthType", decision: false, evaluation: true),
                signal("groundTruthMatch", block.groundTruthMatch, source: "blocks.groundTruthMatch", decision: false, evaluation: true),
                signal("wordOrderPreserved", block.wordOrderPreserved.map(String.init) ?? "nil", source: "blocks.wordOrderPreserved", decision: false, evaluation: true)
            ]
        }
        func makeBlockLedger(for block: MangaOverlayProbeBlock) -> MangaNativeTextBoxProxyBlockLedger {
            let blockIndex = block.index
            let candidates: [MangaNativeTextBoxProxyCandidateLedger] = candidateSourcesByBlock[blockIndex] ?? []
            let candidateSources: [String] = sortedUniqueStrings(candidates.map(\.source))
            let blockers: [String] = promotionBlockers(for: blockIndex)
            let stopReasons: [String] = sortedUniqueStrings(stopReasonsByBlock[blockIndex] ?? [])
            let gateInputs: [String] = stopReasons + blockers
            let wordBlocked: Bool = containsAny(gateInputs, needles: ["rawWordsLost", "wordPreservation"])
            let protectedBlocked: Bool = containsAny(gateInputs, needles: ["protected", "keyword"])
            let bubbleBlocked: Bool = bubbleConflictBlocks.contains(blockIndex)
                || containsAny(gateInputs, needles: ["bubbleConflict", "outsideBubble"])
            let segmentBlocked: Bool = segmentWeakBlocks.contains(blockIndex)
                || segmentByBlock[blockIndex]?.glyphEscapesBubble == true
                || containsAny(gateInputs, needles: ["weakSegment"])
            let damageBlocked: Bool = damageByBlock[blockIndex] != nil || block.failureCategory == "ocrInputSuspect"
            let modelBlocked: Bool = translationModelBlocks.contains(blockIndex) && cleanTextModelFloorLow
            let renderBlocked: Bool = renderIssueBlocks.contains(blockIndex)
            let hasShadowOnlyEligibleCandidate: Bool = candidates.contains { candidate in
                candidate.promotionVerdict == "shadowOnlyEligible"
            }
            let decision = qualityDecision(
                stopReasons: stopReasons,
                wordBlocked: wordBlocked,
                bubbleBlocked: bubbleBlocked,
                segmentBlocked: segmentBlocked,
                damageBlocked: damageBlocked,
                modelBlocked: modelBlocked,
                renderBlocked: renderBlocked,
                hasShadowOnlyEligibleCandidate: hasShadowOnlyEligibleCandidate,
                blockPassed: block.blockPassed
            )
            let bestCandidateID = candidates.first { candidate in
                candidate.promotionVerdict == "shadowOnlyEligible" || candidate.promotionVerdict == "reportOnlyWouldImprove"
            }?.candidateID
            return MangaNativeTextBoxProxyBlockLedger(
                blockIndex: block.index,
                bubbleID: block.bubbleID,
                failureCategory: block.failureCategory,
                blockPassed: block.blockPassed,
                qualityStatus: decision.qualityStatus,
                primaryFreezeReason: decision.primaryFreezeReason,
                candidateSources: candidateSources,
                candidateCount: candidates.count,
                bestReportOnlyCandidateID: bestCandidateID,
                rawWordPreservationStatus: wordBlocked ? "blocked" : "preservedOrNotApplicable",
                protectedKeywordStatus: protectedBlocked ? "blocked" : "preservedOrNotApplicable",
                wordOrderStatus: block.wordOrderPreserved == false ? "evaluationWarning" : "preservedOrUnknown",
                bubbleConstraintStatus: bubbleBlocked ? "blocked" : "containedOrNotApplicable",
                segmentMaskConstraintStatus: segmentBlocked ? "blocked" : "supportedOrNotApplicable",
                ocrDamageStatus: damageBlocked ? "blockedOrSuspect" : "notFlagged",
                translationModelFloorStatus: modelBlocked ? "modelLimited" : "notPrimaryBlocker",
                renderStatus: renderBlocked ? "blocked" : "stable",
                stoplistHit: !stopReasons.isEmpty,
                stoplistReasons: stopReasons,
                decisionSignals: decisionSignals(for: block, candidateSources: candidateSources, stopReasons: stopReasons, blockers: blockers),
                evaluationSignals: evaluationSignals(for: block),
                mustNotPromoteReasons: blockers,
                nextAction: decision.nextAction,
                groundTruthUsedForDecision: false,
                diagnosticOnly: true,
                wouldChangeMainFlow: false
            )
        }
        var blockLedgers: [MangaNativeTextBoxProxyBlockLedger] = []
        blockLedgers.reserveCapacity(blocks.count)
        for block in blocks {
            blockLedgers.append(makeBlockLedger(for: block))
        }

        let stoplistBlocks = uniqueSorted(blockLedgers.filter(\.stoplistHit).map(\.blockIndex))
        let shadowOnlyEligibleBlocks = uniqueSorted(blockLedgers.filter { $0.qualityStatus == "shadowOnlyEligible" }.map(\.blockIndex))
        let manualReviewBlocks = uniqueSorted(blockLedgers.filter { $0.qualityStatus == "manualReviewOnly" }.map(\.blockIndex))
        let blockedByWordBlocks = uniqueSorted(blockLedgers.filter { $0.qualityStatus == "blockedByWordPreservation" || $0.rawWordPreservationStatus == "blocked" }.map(\.blockIndex))
        let blockedByBubbleBlocks = uniqueSorted(blockLedgers.filter { $0.qualityStatus == "blockedByBubbleMaskConflict" }.map(\.blockIndex))
        let blockedBySegmentBlocks = uniqueSorted(blockLedgers.filter { $0.qualityStatus == "blockedByWeakSegmentMask" }.map(\.blockIndex))
        let blockedByModelBlocks = uniqueSorted(blockLedgers.filter { $0.qualityStatus == "modelLimited" }.map(\.blockIndex))
        let freezeReasonBreakdown = countBy(blockLedgers.compactMap(\.primaryFreezeReason))
        let stoplist = stoplistBlocks.map { blockIndex in
            MangaNativeTextBoxProxyStoplistEntry(
                blockIndex: blockIndex,
                scope: "nativeTextBoxes",
                reason: blockLedgers.first { $0.blockIndex == blockIndex }?.primaryFreezeReason ?? "stoplist",
                sourceReports: ["textBoxPlanFailureReport", "lineCropExperimentReport", "koharuNativeReplicationScoreboardReport"],
                evidence: blockLedgers.first { $0.blockIndex == blockIndex }?.stoplistReasons ?? [],
                expiresWhen: "wordPreservationGatePassesInShadowOnly",
                nextAllowedAction: "eligibleForFutureShadowReview"
            )
        }
        func gate(
            _ id: String,
            name: String,
            scope: String,
            status: String,
            threshold: String,
            affected: [Int],
            failureMeans: String,
            action: String,
            signals: [MangaNativeTextBoxProxySignal]
        ) -> MangaNativeTextBoxProxyGate {
            MangaNativeTextBoxProxyGate(
                gateID: id,
                gateName: name,
                scope: scope,
                status: status,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                decisionSignals: signals,
                failureMeans: failureMeans,
                recommendedAction: action,
                groundTruthUsedForDecision: false
            )
        }
        let gateLedger = [
            gate("G-native-textbox-no-main-flow-mutation", name: "No main flow mutation", scope: "report", status: "passed", threshold: "wouldChangeMainFlow=false", affected: [], failureMeans: "ledger mutates OCR, translation, overlay, cleanup, or blockPassed", action: "revertBehavioralChange", signals: [signal("wouldChangeMainFlow", "false", source: "nativeTextBoxProxyLedgerReport")]),
            gate("G-native-textbox-no-ground-truth-decision", name: "No ground truth decision", scope: "report", status: "passed", threshold: "groundTruthUsedForDecision=false", affected: [], failureMeans: "ground truth influences candidate sorting, freeze, or promotion", action: "removeGroundTruthFromDecisionPath", signals: [signal("groundTruthUsedForDecision", "false", source: "nativeTextBoxProxyLedgerReport")]),
            gate("G-native-textbox-word-preservation", name: "Native TextBox word preservation", scope: "nativeTextBoxes", status: blockedByWordBlocks.isEmpty ? "passed" : "blocked", threshold: "raw words preserved by any future shadow candidate", affected: blockedByWordBlocks, failureMeans: "candidate loses raw OCR words or protected terms", action: "freezeLocalCropLineDeskew", signals: [signal("blockedByWordPreservationBlocks", joined(blockedByWordBlocks), source: "nativeTextBoxProxyLedgerReport")]),
            gate("G-native-textbox-protected-keywords", name: "Protected keywords", scope: "nativeTextBoxes", status: blockedByWordBlocks.isEmpty ? "passed" : "blocked", threshold: "protected keywords not damaged", affected: blockedByWordBlocks, failureMeans: "candidate damages protected keyword evidence", action: "freezeCandidateUntilProtectedTermsPreserved", signals: [signal("protectedKeywordBlocks", joined(blockedByWordBlocks), source: "nativeTextBoxProxyLedgerReport")]),
            gate("G-native-textbox-stoplist-freeze", name: "Stoplist freeze", scope: "nativeTextBoxes", status: stoplistBlocks.isEmpty ? "passed" : "stop", threshold: "known failed crop/line/deskew blocks not tuned again", affected: stoplistBlocks, failureMeans: "known failed local tuning is recommended again", action: "freezeLocalCropLineDeskew", signals: [signal("stoplistBlocks", joined(stoplistBlocks), source: "nativeTextBoxProxyLedgerReport")]),
            gate("G-native-textbox-bubble-containment", name: "Bubble containment", scope: "nativeBubbleMask", status: blockedByBubbleBlocks.isEmpty ? "passed" : "blocked", threshold: "candidate remains in assigned bubble", affected: blockedByBubbleBlocks, failureMeans: "candidate crosses or conflicts with bubble mask", action: "collectBubbleMaskEvidence", signals: [signal("blockedByBubbleMaskBlocks", joined(blockedByBubbleBlocks), source: "bubbleMaskReport")]),
            gate("G-native-textbox-segment-support", name: "Segment support", scope: "nativeSegmentMask", status: blockedBySegmentBlocks.isEmpty ? "passed" : "warning", threshold: "segment/glyph proxy supports candidate", affected: blockedBySegmentBlocks, failureMeans: "weak SegmentMask proxy or glyph escape", action: "collectSegmentMaskEvidence", signals: [signal("blockedBySegmentMaskBlocks", joined(blockedBySegmentBlocks), source: "segmentMaskReport")]),
            gate("G-native-textbox-ocr-damage", name: "OCR damage", scope: "ocrText", status: "warning", threshold: "OCR damage stays report-only", affected: uniqueSorted(blockLedgers.filter { $0.ocrDamageStatus == "blockedOrSuspect" }.map(\.blockIndex)), failureMeans: "OCR damage is hidden behind crop tuning", action: "keepReportOnly", signals: [signal("ocrInputSuspectBlocks", joined(blocks.filter { $0.failureCategory == "ocrInputSuspect" }.map(\.index)), source: "blocks.failureCategory")]),
            gate("G-native-textbox-model-floor", name: "Model floor", scope: "translations", status: blockedByModelBlocks.isEmpty ? "passed" : "warning", threshold: "cleanTextDiagnostic.passRate >= 0.80 before blaming only OCR", affected: blockedByModelBlocks, failureMeans: "translation model floor is misattributed to TextBox candidate quality", action: "routeToTranslationModelFloor", signals: [signal("cleanTextPassRate", cleanPassRate.formatted(.number.precision(.fractionLength(4))), source: "clean_text_diagnostic.json")]),
            gate("G-native-textbox-render-stability", name: "Render stability", scope: "finalRender", status: renderIssueBlocks.isEmpty ? "passed" : "blocked", threshold: "no unresolved render overflow or truncation", affected: renderIssueBlocks, failureMeans: "ledger work destabilizes overlay render", action: "keepReportOnly", signals: [signal("renderIssueBlocks", joined(renderIssueBlocks), source: "probe_report.diagnostics")])
        ]

        return MangaNativeTextBoxProxyLedgerReport(
            enabled: true,
            source: "AITRANSProbe",
            referenceWorkItemID: "WI-native-textbox-artifact-scorecard",
            evaluatedBlockCount: blocks.count,
            candidateLedgerCount: candidateLedgers.count,
            gateCount: gateLedger.count,
            stoplistCount: stoplist.count,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            qualityStatusBreakdown: countBy(blockLedgers.map(\.qualityStatus)),
            candidateSourceBreakdown: countBy(candidateLedgers.map(\.source)),
            freezeReasonBreakdown: freezeReasonBreakdown,
            nextActionBreakdown: countBy(blockLedgers.map(\.nextAction)),
            stoplistBlocks: stoplistBlocks,
            shadowOnlyEligibleBlocks: shadowOnlyEligibleBlocks,
            manualReviewBlocks: manualReviewBlocks,
            blockedByWordPreservationBlocks: blockedByWordBlocks,
            blockedByBubbleMaskBlocks: blockedByBubbleBlocks,
            blockedBySegmentMaskBlocks: blockedBySegmentBlocks,
            blockedByTranslationModelBlocks: blockedByModelBlocks,
            blockLedgers: blockLedgers,
            candidateLedgers: candidateLedgers,
            gateLedger: gateLedger,
            stoplist: stoplist,
            notes: [
                "nativeTextBoxProxyLedgerReport executes WI-native-textbox-artifact-scorecard as report-only quality ledger.",
                "candidateLedgers aggregate existing TextBox, crop, line, BubbleMask, SegmentMask, OCR damage, and v1.24 scoreboard evidence without new OCR or LLM calls.",
                "ground-truth-free signals decide qualityStatus, freeze reasons, candidate ordering, and nextAction; ground truth metrics are evaluationSignals only.",
                "crop, line, and deskew candidates that hit stoplist or word preservation blockers remain frozen until future shadow-only evidence satisfies the listed expiresWhen conditions.",
                "does not change finalTextUsedForTranslation, blockPassed, failureCategory, overlay rendering, post-fusion cleanup, candidate selection, or currentBlockSource."
            ]
        )
    }

    private static func makeBubbleMaskAssignmentSplitScoreboardReport(
        blocks: [MangaOverlayProbeBlock],
        diagnostics: MangaOverlayProbeDiagnostics,
        bubbleMaskReport: MangaOverlayBubbleMaskReport?,
        bubbleAssignmentCorrectionReport: MangaOverlayBubbleAssignmentCorrectionReport?,
        bubbleSplitCandidateReport: MangaOverlayBubbleSplitCandidateReport?,
        readingOrderStructureAuditReport: MangaReadingOrderStructureAuditReport?,
        structureActionCandidateReport: MangaStructureActionCandidateReport?,
        koharuNativeReplicationScoreboardReport: MangaKoharuNativeReplicationScoreboardReport?,
        nativeTextBoxProxyLedgerReport: MangaNativeTextBoxProxyLedgerReport?
    ) -> MangaBubbleMaskAssignmentSplitScoreboardReport {
        func uniqueSorted(_ values: [Int]) -> [Int] {
            Array(Set(values)).sorted()
        }
        func countBy(_ values: [String]) -> [String: Int] {
            values.reduce(into: [:]) { partial, value in
                partial[value, default: 0] += 1
            }
        }
        func joined(_ values: [Int]) -> String {
            values.map(String.init).joined(separator: ",")
        }
        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaBubbleMaskDecisionSignal {
            MangaBubbleMaskDecisionSignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }
        func sortedUniqueStrings(_ values: [String]) -> [String] {
            Array(Set(values)).sorted()
        }

        let maskByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleMaskReport?.blockDiagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let correctionByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleAssignmentCorrectionReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let readingByBlock = Dictionary(
            uniqueKeysWithValues: (readingOrderStructureAuditReport?.cases ?? []).map { ($0.blockIndex, $0) }
        )
        let structureByBlock = Dictionary(
            uniqueKeysWithValues: (structureActionCandidateReport?.cases ?? []).map { ($0.blockIndex, $0) }
        )
        let nativeScorecardByBlock = Dictionary(
            uniqueKeysWithValues: (koharuNativeReplicationScoreboardReport?.blockScorecards ?? []).map { ($0.blockIndex, $0) }
        )
        let textBoxLedgerByBlock = Dictionary(
            uniqueKeysWithValues: (nativeTextBoxProxyLedgerReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        var splitCandidatesByBlock: [Int: [MangaOverlayBubbleSplitCandidateDiagnostic]] = [:]
        for candidate in bubbleSplitCandidateReport?.diagnostics ?? [] {
            for blockIndex in candidate.seedBlockIndexes {
                splitCandidatesByBlock[blockIndex, default: []].append(candidate)
            }
        }
        let blocksByBubble = Dictionary(grouping: blocks.compactMap { block -> (Int, Int)? in
            guard let bubbleID = block.bubbleID else { return nil }
            return (bubbleID, block.index)
        }) { $0.0 }
            .mapValues { pairs in pairs.map(\.1).sorted() }

        func blockAssignmentStatus(
            block: MangaOverlayProbeBlock,
            mask: MangaOverlayBubbleMaskBlockDiagnostic?,
            correction: MangaOverlayBubbleAssignmentCorrectionDiagnostic?,
            reading: MangaReadingOrderStructureAuditCase?
        ) -> String {
            if block.bubbleID == nil {
                return "unassignedNeedsManualReview"
            }
            if correction?.correctionAppliedToCropClamp == true {
                return "correctionAppliedToCropClampOnly"
            }
            if correction?.correctionRecommended == true {
                return "correctionRecommendedReportOnly"
            }
            if correction?.riskFlags.contains("protectedShortText") == true {
                return "protectedShortTextNoCorrection"
            }
            if correction?.riskFlags.contains("decorativeTitle") == true || reading?.decorativeProtectionApplied == true {
                return "decorativeTitleNoCorrection"
            }
            if mask == nil {
                return "missingMaskEvidence"
            }
            if mask?.bubbleIDConsistent == false || reading?.bubbleAssignmentRisk == "maskConflict" {
                return "maskConflict"
            }
            return "consistent"
        }

        func blockSplitRisk(
            block: MangaOverlayProbeBlock,
            splits: [MangaOverlayBubbleSplitCandidateDiagnostic],
            reading: MangaReadingOrderStructureAuditCase?
        ) -> String {
            if block.crossBubbleMergeRejected {
                return "crossBubbleMergeRejected"
            }
            if let readingRisk = reading?.splitOrMergeRisk, readingRisk != "none" {
                return readingRisk
            }
            if splits.contains(where: \.clampEligible) {
                return "splitCandidateEligibleReportOnly"
            }
            if !splits.isEmpty {
                return "splitCandidateRejected"
            }
            if reading?.sameBubbleSiblingBlockIndexes.isEmpty == false {
                return "sameBubblePotentialOverSplit"
            }
            return "none"
        }

        func siblingLayoutStatus(
            block: MangaOverlayProbeBlock,
            siblings: [Int],
            splits: [MangaOverlayBubbleSplitCandidateDiagnostic],
            reading: MangaReadingOrderStructureAuditCase?
        ) -> String {
            if siblings.isEmpty {
                return "singleBlockBubble"
            }
            if splits.contains(where: { $0.siblingOverlapRatio >= 0.36 }) {
                return "siblingOverlapTooHigh"
            }
            if reading?.recommendedStructureAction == "provideRealKoharuArtifact" {
                return "needsRealBubbleMask"
            }
            if block.safeLayoutRect != nil {
                return "partitionedSafeRectStable"
            }
            if reading?.splitOrMergeRisk == "none" || reading?.splitOrMergeRisk == nil {
                return "sameBubbleSiblingLayoutStable"
            }
            return "sameBubbleSiblingLayoutRisk"
        }

        func renderMaskStatus(block: MangaOverlayProbeBlock, mask: MangaOverlayBubbleMaskBlockDiagnostic?) -> String {
            if block.renderMaskOverflowPixelCount > 0 {
                return "renderMaskOverflow"
            }
            if block.renderMaskCollisionChecked && block.renderMaskCollisionResolved {
                return "renderMaskStable"
            }
            if mask?.renderMaskCollisionChecked == true {
                return mask?.renderMaskCollisionResolved == true ? "renderMaskStable" : "renderMaskUnresolved"
            }
            return "notChecked"
        }

        func nextAction(
            assignmentStatus: String,
            splitRisk: String,
            siblingStatus: String,
            renderStatus: String,
            correction: MangaOverlayBubbleAssignmentCorrectionDiagnostic?,
            reading: MangaReadingOrderStructureAuditCase?
        ) -> String {
            if renderStatus == "renderMaskStable" && siblingStatus == "singleBlockBubble" && assignmentStatus == "consistent" {
                return "lockRenderSafeArea"
            }
            if assignmentStatus == "correctionAppliedToCropClampOnly" || correction?.correctionAppliedToCropClamp == true {
                return "keepCorrectionCropClampOnly"
            }
            if assignmentStatus == "protectedShortTextNoCorrection" || assignmentStatus == "decorativeTitleNoCorrection" {
                return "protectShortOrDecorativeText"
            }
            if siblingStatus == "needsRealBubbleMask" || reading?.recommendedStructureAction == "provideRealKoharuArtifact" {
                return "collectRealBubbleMaskArtifact"
            }
            if splitRisk != "none" && splitRisk != "sameBubblePotentialOverSplit" {
                return "evaluateSplitShadowOnly"
            }
            if assignmentStatus == "unassignedNeedsManualReview" || splitRisk == "manualReviewOnly" {
                return "manualReviewOnly"
            }
            return "keepReportOnly"
        }

        func evaluationSignals(for block: MangaOverlayProbeBlock) -> [MangaBubbleMaskDecisionSignal] {
            [
                signal("ocrGroundTruthSimilarity", block.ocrGroundTruthSimilarity?.formatted(.number.precision(.fractionLength(4))) ?? "nil", source: "blocks.ocrGroundTruthSimilarity", decision: false, evaluation: true),
                signal("bestGroundTruthType", block.bestGroundTruthType ?? "nil", source: "blocks.bestGroundTruthType", decision: false, evaluation: true),
                signal("groundTruthMatch", block.groundTruthMatch, source: "blocks.groundTruthMatch", decision: false, evaluation: true),
                signal("wordOrderPreserved", block.wordOrderPreserved.map(String.init) ?? "nil", source: "blocks.wordOrderPreserved", decision: false, evaluation: true)
            ]
        }

        var blockScorecards: [MangaBubbleMaskAssignmentSplitBlockScorecard] = []
        blockScorecards.reserveCapacity(blocks.count)
        for block in blocks {
            let mask = maskByBlock[block.index]
            let correction = correctionByBlock[block.index]
            let reading = readingByBlock[block.index]
            let structure = structureByBlock[block.index]
            let native = nativeScorecardByBlock[block.index]
            let textBoxLedger = textBoxLedgerByBlock[block.index]
            let splits = splitCandidatesByBlock[block.index] ?? []
            let siblings = reading?.sameBubbleSiblingBlockIndexes ?? block.bubbleID.flatMap { blocksByBubble[$0] }?.filter { $0 != block.index } ?? []
            let assignment = blockAssignmentStatus(block: block, mask: mask, correction: correction, reading: reading)
            let splitRisk = blockSplitRisk(block: block, splits: splits, reading: reading)
            let siblingStatus = siblingLayoutStatus(block: block, siblings: siblings, splits: splits, reading: reading)
            let renderStatus = renderMaskStatus(block: block, mask: mask)
            let action = nextAction(
                assignmentStatus: assignment,
                splitRisk: splitRisk,
                siblingStatus: siblingStatus,
                renderStatus: renderStatus,
                correction: correction,
                reading: reading
            )
            var mustNotPromote = reading?.mustNotPromoteReasons ?? []
            mustNotPromote.append(contentsOf: structure?.candidates.flatMap(\.mustNotPromoteReasons) ?? [])
            mustNotPromote.append(contentsOf: native?.mustNotPromoteReasons ?? [])
            mustNotPromote.append(contentsOf: textBoxLedger?.mustNotPromoteReasons ?? [])
            mustNotPromote.append("bubbleMaskScoreboardReportOnly")
            mustNotPromote.append("doesNotChangeSafeLayoutRect")
            mustNotPromote.append("groundTruthUsedOnlyForEvaluationSignals")
            let decisionSignals = [
                signal("bubbleIDConsistent", mask.map { String($0.bubbleIDConsistent) } ?? "nil", source: "bubbleMaskReport.blockDiagnostics"),
                signal("maskDominantCoverageRatio", mask?.maskDominantCoverageRatio.formatted(.number.precision(.fractionLength(4))) ?? "nil", source: "bubbleMaskReport.blockDiagnostics"),
                signal("cropMaskCoverageRatio", mask?.cropMaskCoverageRatio?.formatted(.number.precision(.fractionLength(4))) ?? "nil", source: "bubbleMaskReport.blockDiagnostics"),
                signal("assignmentDecision", correction?.decision ?? "nil", source: "bubbleAssignmentCorrectionReport.diagnostics"),
                signal("splitCandidateIDs", splits.map(\.id).map(String.init).joined(separator: ","), source: "bubbleSplitCandidateReport.diagnostics"),
                signal("sameBubbleSiblings", joined(siblings), source: "readingOrderStructureAuditReport.cases"),
                signal("candidateTypes", structure?.candidateTypes.joined(separator: ",") ?? "nil", source: "structureActionCandidateReport.cases"),
                signal("textBoxBubbleConstraint", textBoxLedger?.bubbleConstraintStatus ?? "nil", source: "nativeTextBoxProxyLedgerReport.blockLedgers"),
                signal("renderMaskStatus", renderStatus, source: "blocks.renderMaskDiagnostics")
            ]
            blockScorecards.append(
                MangaBubbleMaskAssignmentSplitBlockScorecard(
                    blockIndex: block.index,
                    bubbleID: block.bubbleID,
                    maskDominantBubbleID: mask?.maskDominantBubbleID,
                    maskDominantCoverageRatio: mask?.maskDominantCoverageRatio ?? 0,
                    maskIDsUnderSeed: mask?.maskIDsUnderSeed ?? [:],
                    assignmentStatus: assignment,
                    assignmentDecision: correction?.decision ?? "notEvaluated",
                    correctionRecommended: correction?.correctionRecommended ?? false,
                    correctionAppliedToCropClamp: correction?.correctionAppliedToCropClamp ?? false,
                    correctionAppliedToSafeLayout: correction?.correctionAppliedToSafeLayout ?? false,
                    splitRisk: splitRisk,
                    splitCandidateIDs: splits.map(\.id).sorted(),
                    splitCandidateClampEligible: splits.contains(where: \.clampEligible),
                    siblingBlockIndexes: siblings.sorted(),
                    siblingLayoutStatus: siblingStatus,
                    safeLayoutSourceBeforeMask: mask?.safeLayoutSourceBeforeMask ?? block.safeLayoutSourceBeforeMask,
                    safeLayoutSourceAfterMask: mask?.safeLayoutSourceAfterMask ?? block.safeLayoutSource,
                    maskSafeRect: mask?.maskSafeRect ?? block.maskSafeRect,
                    cropMaskCoverageRatio: mask?.cropMaskCoverageRatio,
                    renderMaskCollisionChecked: mask?.renderMaskCollisionChecked ?? block.renderMaskCollisionChecked,
                    renderMaskCollisionResolved: mask?.renderMaskCollisionResolved ?? block.renderMaskCollisionResolved,
                    renderMaskOverflowPixelCount: mask?.renderMaskOverflowPixelCount ?? block.renderMaskOverflowPixelCount,
                    renderMaskStatus: renderStatus,
                    textBoxLedgerStatus: textBoxLedger?.qualityStatus,
                    primaryBubbleBottleneck: native?.bubbleGateStatus ?? reading?.bubbleAssignmentRisk ?? "notEvaluated",
                    decisionSignals: decisionSignals,
                    evaluationSignals: evaluationSignals(for: block),
                    mustNotPromoteReasons: sortedUniqueStrings(mustNotPromote),
                    nextAction: action,
                    groundTruthUsedForDecision: false,
                    diagnosticOnly: true,
                    wouldChangeMainFlow: false
                )
            )
        }

        let blockScorecardByIndex = Dictionary(uniqueKeysWithValues: blockScorecards.map { ($0.blockIndex, $0) })
        let splitCandidateLedgers = (bubbleSplitCandidateReport?.diagnostics ?? []).map { candidate in
            let blockers = candidate.rejectionReasons + candidate.riskFlags
            let verdict: String
            if candidate.clampEligible {
                verdict = "reportOnlyEligible"
            } else if candidate.siblingOverlapRatio >= 0.36 {
                verdict = "rejectedSiblingOverlap"
            } else if candidate.seedCoverageRatio < 0.94 {
                verdict = "rejectedSeedCoverage"
            } else if blockers.contains("protectedShortText") {
                verdict = "rejectedProtectedText"
            } else if blockers.contains("decorativeTitle") {
                verdict = "rejectedDecorativeTitle"
            } else {
                verdict = "manualReviewOnly"
            }
            return MangaBubbleMaskSplitCandidateLedger(
                candidateID: candidate.id,
                parentBubbleID: candidate.parentBubbleID,
                seedBlockIndexes: candidate.seedBlockIndexes,
                bbox: candidate.bbox,
                safeRect: candidate.safeRect,
                parentMaskCoverageRatio: candidate.parentMaskCoverageRatio,
                seedCoverageRatio: candidate.seedCoverageRatio,
                siblingOverlapRatio: candidate.siblingOverlapRatio,
                clampEligible: candidate.clampEligible,
                appliedToCropClampBlocks: candidate.appliedToBlockIndexes,
                promotionVerdict: verdict,
                promotionBlockers: sortedUniqueStrings(blockers + ["reportOnlyDoesNotChangeTextRegionCropGuardrail"]),
                decisionSignals: [
                    signal("parentMaskCoverageRatio", candidate.parentMaskCoverageRatio.formatted(.number.precision(.fractionLength(4))), source: "bubbleSplitCandidateReport.diagnostics"),
                    signal("seedCoverageRatio", candidate.seedCoverageRatio.formatted(.number.precision(.fractionLength(4))), source: "bubbleSplitCandidateReport.diagnostics"),
                    signal("siblingOverlapRatio", candidate.siblingOverlapRatio.formatted(.number.precision(.fractionLength(4))), source: "bubbleSplitCandidateReport.diagnostics"),
                    signal("clampEligible", String(candidate.clampEligible), source: "bubbleSplitCandidateReport.diagnostics")
                ],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false
            )
        }

        var siblingLayoutScorecards: [MangaBubbleMaskSiblingLayoutScorecard] = []
        for (bubbleID, indexes) in blocksByBubble.sorted(by: { $0.key < $1.key }) where indexes.count > 1 {
            let cards = indexes.compactMap { blockScorecardByIndex[$0] }
            let readingIndexes = indexes.compactMap { readingByBlock[$0]?.proposedReadingOrderIndex }
            let safeRects = cards.compactMap(\.maskSafeRect)
            let maxOverlap = splitCandidateLedgers
                .filter { $0.parentBubbleID == bubbleID }
                .map(\.siblingOverlapRatio)
                .max() ?? 0
            let renderBlocked = cards.contains { $0.renderMaskStatus != "renderMaskStable" && $0.renderMaskStatus != "notChecked" }
            let layoutStatus: String
            if cards.contains(where: { $0.siblingLayoutStatus == "siblingOverlapTooHigh" }) {
                layoutStatus = "siblingOverlapTooHigh"
            } else if cards.contains(where: { $0.siblingLayoutStatus == "needsRealBubbleMask" }) {
                layoutStatus = "needsRealBubbleMask"
            } else if !safeRects.isEmpty {
                layoutStatus = "partitionedSafeRectStable"
            } else {
                layoutStatus = "sameBubbleSiblingLayoutStable"
            }
            var risks: [String] = []
            if maxOverlap >= 0.36 { risks.append("siblingOverlapTooHigh") }
            if renderBlocked { risks.append("renderMaskIssue") }
            if splitCandidateLedgers.contains(where: { $0.parentBubbleID == bubbleID }) { risks.append("splitCandidatePresent") }
            siblingLayoutScorecards.append(
                MangaBubbleMaskSiblingLayoutScorecard(
                    bubbleID: bubbleID,
                    blockIndexes: indexes,
                    proposedReadingOrderIndexes: readingIndexes,
                    safeRects: safeRects,
                    siblingOverlapSummary: maxOverlap.formatted(.number.precision(.fractionLength(4))),
                    layoutStatus: layoutStatus,
                    layoutRiskFlags: sortedUniqueStrings(risks),
                    renderStatus: renderBlocked ? "renderMaskIssue" : "renderStable",
                    decisionSignals: [
                        signal("blockIndexes", joined(indexes), source: "blocks.bubbleID"),
                        signal("maxSiblingOverlapRatio", maxOverlap.formatted(.number.precision(.fractionLength(4))), source: "bubbleSplitCandidateReport.diagnostics"),
                        signal("safeRectCount", String(safeRects.count), source: "bubbleMaskReport.blockDiagnostics")
                    ],
                    mustNotPromoteReasons: ["sameBubbleSiblingLayoutReportOnly", "doesNotReorderBlocks", "doesNotChangeSafeLayoutRect"],
                    nextAction: layoutStatus == "needsRealBubbleMask" ? "collectRealBubbleMaskArtifact" : "keepReportOnly"
                )
            )
        }

        let siblingGroups = siblingLayoutScorecards.map(\.blockIndexes)
        let bubbleScorecards = (bubbleMaskReport?.instances ?? []).map { instance in
            let indexes = blocksByBubble[instance.bubbleID] ?? []
            let cards = indexes.compactMap { blockScorecardByIndex[$0] }
            let splitLedgers = splitCandidateLedgers.filter { $0.parentBubbleID == instance.bubbleID }
            let conflictIndexes = cards.filter { $0.assignmentStatus == "maskConflict" }.map(\.blockIndex)
            let correctionIndexes = cards.filter(\.correctionRecommended).map(\.blockIndex)
            let overflowIndexes = cards.filter { $0.renderMaskOverflowPixelCount > 0 }.map(\.blockIndex)
            let splitEligible = splitLedgers.filter(\.clampEligible).flatMap(\.seedBlockIndexes)
            let instanceStatus: String
            if !conflictIndexes.isEmpty {
                instanceStatus = "assignmentConflict"
            } else if !splitLedgers.isEmpty && splitEligible.isEmpty {
                instanceStatus = "oversizedNeedsSplitReview"
            } else if !splitEligible.isEmpty {
                instanceStatus = "splitCandidateReportOnly"
            } else if indexes.count > 1 {
                instanceStatus = "stableMultiBlock"
            } else if !overflowIndexes.isEmpty {
                instanceStatus = "manualReviewOnly"
            } else {
                instanceStatus = "stableSingleBlock"
            }
            let primaryRisk: String
            if !conflictIndexes.isEmpty {
                primaryRisk = "assignmentConflict"
            } else if !splitLedgers.isEmpty {
                primaryRisk = "splitCandidateReportOnly"
            } else if !overflowIndexes.isEmpty {
                primaryRisk = "renderMaskOverflow"
            } else {
                primaryRisk = "none"
            }
            return MangaBubbleMaskInstanceScorecard(
                bubbleID: instance.bubbleID,
                bbox: instance.bbox,
                maskPixelCount: instance.maskPixelCount,
                maskCoverageRatio: instance.maskCoverageRatio,
                safeRect: instance.safeRect,
                safeRectCoverageRatio: instance.safeRectCoverageRatio,
                blockIndexes: indexes,
                conflictBlockIndexes: conflictIndexes,
                correctionRecommendedBlockIndexes: correctionIndexes,
                splitCandidateIDs: splitLedgers.map(\.candidateID).sorted(),
                splitEligibleBlockIndexes: uniqueSorted(splitEligible),
                sameBubbleSiblingGroups: siblingGroups.filter { group in !Set(group).isDisjoint(with: indexes) },
                renderOverflowBlockIndexes: overflowIndexes,
                instanceStatus: instanceStatus,
                primaryRisk: primaryRisk,
                decisionSignals: [
                    signal("maskCoverageRatio", instance.maskCoverageRatio.formatted(.number.precision(.fractionLength(4))), source: "bubbleMaskReport.instances"),
                    signal("safeRectCoverageRatio", instance.safeRectCoverageRatio.formatted(.number.precision(.fractionLength(4))), source: "bubbleMaskReport.instances"),
                    signal("riskFlags", instance.riskFlags.joined(separator: ","), source: "bubbleMaskReport.instances"),
                    signal("blockIndexes", joined(indexes), source: "blocks.bubbleID")
                ],
                mustNotPromoteReasons: sortedUniqueStrings(instance.riskFlags + ["approximateBubbleMaskProxy", "realKoharuBubbleMaskRequiredForPromotion"]),
                nextAction: instanceStatus == "assignmentConflict" || instanceStatus == "oversizedNeedsSplitReview" ? "collectRealBubbleMaskArtifact" : "keepReportOnly"
            )
        }

        let conflictBlocks = uniqueSorted((bubbleMaskReport?.inconsistentBubbleAssignmentBlocks ?? []) + blockScorecards.filter { $0.assignmentStatus == "maskConflict" }.map(\.blockIndex))
        let correctionRecommendedBlocks = uniqueSorted(bubbleAssignmentCorrectionReport?.recommendedCorrectionBlocks ?? [])
        let splitRiskBlocks = uniqueSorted((readingOrderStructureAuditReport?.splitRiskBlocks ?? []) + blockScorecards.filter { $0.splitRisk != "none" }.map(\.blockIndex))
        let sameBubbleSiblingBlocks = uniqueSorted(blockScorecards.filter { !$0.siblingBlockIndexes.isEmpty }.map(\.blockIndex))
        let maskSafeLayoutBlocks = uniqueSorted(blockScorecards.filter { ($0.safeLayoutSourceAfterMask ?? "").hasPrefix("maskSafe") || $0.maskSafeRect != nil }.map(\.blockIndex))
        let renderBlockedBlocks = uniqueSorted(blockScorecards.filter { $0.renderMaskStatus == "renderMaskOverflow" || $0.renderMaskStatus == "renderMaskUnresolved" }.map(\.blockIndex))
        let needsRealBubbleMaskBlocks = uniqueSorted(blockScorecards.filter { $0.nextAction == "collectRealBubbleMaskArtifact" || $0.siblingLayoutStatus == "needsRealBubbleMask" }.map(\.blockIndex))
        let manualReviewBlocks = uniqueSorted(blockScorecards.filter { $0.nextAction == "manualReviewOnly" || $0.assignmentStatus == "unassignedNeedsManualReview" }.map(\.blockIndex))

        func gate(
            _ id: String,
            name: String,
            scope: String,
            status: String,
            threshold: String,
            affected: [Int],
            failureMeans: String,
            action: String,
            signals: [MangaBubbleMaskDecisionSignal]
        ) -> MangaBubbleMaskAssignmentGate {
            MangaBubbleMaskAssignmentGate(
                gateID: id,
                gateName: name,
                scope: scope,
                status: status,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                decisionSignals: signals,
                failureMeans: failureMeans,
                recommendedAction: action,
                groundTruthUsedForDecision: false
            )
        }
        let protectedBlocks = uniqueSorted(blockScorecards.filter { $0.assignmentStatus == "protectedShortTextNoCorrection" || $0.assignmentStatus == "decorativeTitleNoCorrection" }.map(\.blockIndex))
        let splitEligibleBlocks = uniqueSorted(splitCandidateLedgers.filter(\.clampEligible).flatMap(\.seedBlockIndexes))
        let gateLedger = [
            gate("G-bubblemask-no-main-flow-mutation", name: "No main flow mutation", scope: "report", status: "passed", threshold: "wouldChangeMainFlow=false", affected: [], failureMeans: "scoreboard mutates OCR, translation, overlay, cleanup, safeLayoutRect, or blockPassed", action: "revertBehavioralChange", signals: [signal("wouldChangeMainFlow", "false", source: "bubbleMaskAssignmentSplitScoreboardReport")]),
            gate("G-bubblemask-no-ground-truth-decision", name: "No ground truth decision", scope: "report", status: "passed", threshold: "groundTruthUsedForDecision=false", affected: [], failureMeans: "ground truth influences assignment, split, sibling layout, or promotion", action: "removeGroundTruthFromDecisionPath", signals: [signal("groundTruthUsedForDecision", "false", source: "bubbleMaskAssignmentSplitScoreboardReport")]),
            gate("G-bubblemask-assignment-consistency", name: "Assignment consistency", scope: "BubbleMask", status: conflictBlocks.isEmpty ? "passed" : "warning", threshold: "bubbleID matches dominant mask ID", affected: conflictBlocks, failureMeans: "bubble assignment conflict is silently promoted", action: "keepReportOnlyOrCollectRealBubbleMaskArtifact", signals: [signal("conflictBlocks", joined(conflictBlocks), source: "bubbleMaskReport")]),
            gate("G-bubblemask-correction-report-only", name: "Correction report only", scope: "BubbleMask", status: correctionRecommendedBlocks.isEmpty ? "passed" : "reportOnly", threshold: "assignment corrections stay diagnostic or crop-clamp-only", affected: correctionRecommendedBlocks, failureMeans: "assignment correction changes safe layout, block order, or final OCR text", action: "keepCorrectionCropClampOnly", signals: [signal("correctionRecommendedBlocks", joined(correctionRecommendedBlocks), source: "bubbleAssignmentCorrectionReport")]),
            gate("G-bubblemask-split-report-only", name: "Split report only", scope: "BubbleMask", status: splitEligibleBlocks.isEmpty ? "passed" : "reportOnly", threshold: "split candidates do not create/delete blocks or loosen crop guardrails", affected: splitEligibleBlocks, failureMeans: "split candidate mutates main OCR or crop adoption", action: "evaluateSplitShadowOnly", signals: [signal("splitEligibleBlocks", joined(splitEligibleBlocks), source: "bubbleSplitCandidateReport")]),
            gate("G-bubblemask-sibling-layout", name: "Sibling layout", scope: "renderLayout", status: sameBubbleSiblingBlocks.isEmpty ? "passed" : "reportOnly", threshold: "same-bubble siblings are audited without reordering blocks", affected: sameBubbleSiblingBlocks, failureMeans: "sibling layout changes block order or safeLayoutRect", action: "keepReportOnly", signals: [signal("sameBubbleSiblingBlocks", joined(sameBubbleSiblingBlocks), source: "readingOrderStructureAuditReport")]),
            gate("G-bubblemask-render-mask-collision", name: "Render mask collision", scope: "finalRender", status: renderBlockedBlocks.isEmpty ? "passed" : "blocked", threshold: "no unresolved mask overflow", affected: renderBlockedBlocks, failureMeans: "render overflow is ignored or hidden", action: "lockRenderSafeArea", signals: [signal("renderBlockedBlocks", joined(renderBlockedBlocks), source: "blocks.renderMaskDiagnostics")]),
            gate("G-bubblemask-protected-text", name: "Protected text", scope: "BubbleMask", status: protectedBlocks.isEmpty ? "passed" : "reportOnly", threshold: "decorative and protected short text cannot be auto-corrected or deleted", affected: protectedBlocks, failureMeans: "protected content is promoted into split/delete/correction", action: "protectShortOrDecorativeText", signals: [signal("protectedBlocks", joined(protectedBlocks), source: "bubbleAssignmentCorrectionReport,readingOrderStructureAuditReport")]),
            gate("G-bubblemask-textbox-ledger-boundary", name: "TextBox ledger boundary", scope: "nativeTextBoxes", status: "passed", threshold: "BubbleMask scorecard can read TextBox ledger but cannot thaw crop/line stoplist", affected: nativeTextBoxProxyLedgerReport?.stoplistBlocks ?? [], failureMeans: "BubbleMask work reopens frozen crop/line/deskew tuning", action: "respectNativeTextBoxProxyLedgerStoplist", signals: [signal("nativeTextBoxStoplistBlocks", joined(nativeTextBoxProxyLedgerReport?.stoplistBlocks ?? []), source: "nativeTextBoxProxyLedgerReport")]),
            gate("G-bubblemask-real-artifact-boundary", name: "Real BubbleMask artifact boundary", scope: "externalArtifacts", status: needsRealBubbleMaskBlocks.isEmpty ? "reportOnly" : "needsRealArtifact", threshold: "AITRANS proxy BubbleMask is not promoted as real Koharu BubbleMask", affected: needsRealBubbleMaskBlocks, failureMeans: "proxy mask is mislabeled as real Koharu artifact", action: "collectRealBubbleMaskArtifact", signals: [signal("referenceKoharuArtifact", "BubbleMask", source: "bubbleMaskAssignmentSplitScoreboardReport"), signal("proxySource", "AITRANS roundedRectApproximation", source: "bubbleMaskReport.instances")])
        ]

        return MangaBubbleMaskAssignmentSplitScoreboardReport(
            enabled: true,
            source: "AITRANSProbe",
            referenceWorkItemID: "WI-bubblemask-assignment-split-scorecard",
            referenceKoharuArtifact: "BubbleMask",
            evaluatedBlockCount: blocks.count,
            evaluatedBubbleCount: bubbleMaskReport?.instanceCount ?? bubbleScorecards.count,
            splitCandidateCount: splitCandidateLedgers.count,
            siblingGroupCount: siblingLayoutScorecards.count,
            gateCount: gateLedger.count,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            assignmentStatusBreakdown: countBy(blockScorecards.map(\.assignmentStatus)),
            splitRiskBreakdown: countBy(blockScorecards.map(\.splitRisk)),
            siblingLayoutStatusBreakdown: countBy(blockScorecards.map(\.siblingLayoutStatus)),
            renderMaskStatusBreakdown: countBy(blockScorecards.map(\.renderMaskStatus)),
            nextActionBreakdown: countBy(blockScorecards.map(\.nextAction)),
            conflictBlocks: conflictBlocks,
            correctionRecommendedBlocks: correctionRecommendedBlocks,
            splitRiskBlocks: splitRiskBlocks,
            sameBubbleSiblingBlocks: sameBubbleSiblingBlocks,
            maskSafeLayoutBlocks: maskSafeLayoutBlocks,
            renderBlockedBlocks: renderBlockedBlocks,
            needsRealBubbleMaskBlocks: needsRealBubbleMaskBlocks,
            manualReviewBlocks: manualReviewBlocks,
            blockScorecards: blockScorecards,
            bubbleScorecards: bubbleScorecards,
            splitCandidateLedgers: splitCandidateLedgers,
            siblingLayoutScorecards: siblingLayoutScorecards,
            gateLedger: gateLedger,
            notes: [
                "bubbleMaskAssignmentSplitScoreboardReport executes WI-bubblemask-assignment-split-scorecard as report-only scoreboard.",
                "It aggregates existing BubbleMask proxy, assignment correction, split candidate, reading order, structure action, native scoreboard, and TextBox ledger evidence without new OCR or LLM calls.",
                "Assignment, split, sibling layout, nextAction, and promotion blockers use ground-truth-free decision signals only; OCR ground truth metrics appear only in evaluationSignals.",
                "AITRANS BubbleMask is an internal proxy derived from existing bubble geometry, not a real Koharu BubbleMask artifact.",
                "This report does not change finalTextUsedForTranslation, blockPassed, failureCategory, safeLayoutRect, overlay rendering, post-fusion cleanup, candidate selection, or currentBlockSource."
            ]
        )
    }

    private static func makeSegmentMaskProxyCoverageScoreboardReport(
        blocks: [MangaOverlayProbeBlock],
        diagnostics: MangaOverlayProbeDiagnostics,
        segmentMaskReport: MangaOverlaySegmentMaskReport?,
        textBoxCandidateReport: MangaOverlayTextBoxCandidateReport?,
        bubbleMaskReport: MangaOverlayBubbleMaskReport?,
        koharuNativeReplicationScoreboardReport: MangaKoharuNativeReplicationScoreboardReport?,
        nativeTextBoxProxyLedgerReport: MangaNativeTextBoxProxyLedgerReport?,
        bubbleMaskAssignmentSplitScoreboardReport: MangaBubbleMaskAssignmentSplitScoreboardReport?
    ) -> MangaSegmentMaskProxyCoverageScoreboardReport {
        func uniqueSorted(_ values: [Int]) -> [Int] {
            Array(Set(values)).sorted()
        }
        func sortedUniqueStrings(_ values: [String]) -> [String] {
            Array(Set(values)).sorted()
        }
        func countBy(_ values: [String]) -> [String: Int] {
            values.reduce(into: [:]) { partial, value in
                partial[value, default: 0] += 1
            }
        }
        func joined(_ values: [Int]) -> String {
            values.map(String.init).joined(separator: ",")
        }
        func ratioString(_ value: Double?) -> String {
            value?.formatted(.number.precision(.fractionLength(4))) ?? "nil"
        }
        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaSegmentMaskProxyDecisionSignal {
            MangaSegmentMaskProxyDecisionSignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }

        let segmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentMaskReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let textBoxByBlock = Dictionary(
            uniqueKeysWithValues: (textBoxCandidateReport?.diagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let maskByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleMaskReport?.blockDiagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let nativeScorecardByBlock = Dictionary(
            uniqueKeysWithValues: (koharuNativeReplicationScoreboardReport?.blockScorecards ?? []).map { ($0.blockIndex, $0) }
        )
        let textBoxLedgerByBlock = Dictionary(
            uniqueKeysWithValues: (nativeTextBoxProxyLedgerReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let bubbleScoreboardByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleMaskAssignmentSplitScoreboardReport?.blockScorecards ?? []).map { ($0.blockIndex, $0) }
        )

        func fallbackSegment(for block: MangaOverlayProbeBlock) -> MangaOverlaySegmentMaskDiagnostic {
            MangaOverlaySegmentMaskDiagnostic(
                blockIndex: block.index,
                textBoxCandidateID: textBoxByBlock[block.index]?.id,
                glyphMaskPixelCount: block.glyphMaskPixelCount,
                glyphMaskRect: block.glyphMaskRect,
                glyphMaskFillRectCount: block.glyphMaskFillRects.count,
                textBoxCoverageRatio: textBoxByBlock[block.index]?.glyphOverlapRatio,
                bubbleMaskCoverageRatio: maskByBlock[block.index]?.cropMaskCoverageRatio,
                safeRectCoverageRatio: textBoxByBlock[block.index]?.safeRectOverlapRatio,
                glyphEscapesBubble: false,
                glyphEscapesTextBox: false,
                usableForCleanup: block.glyphMaskPixelCount > 0,
                usableForCropEvidence: false,
                rejectionReasons: block.glyphMaskPixelCount > 0 ? [] : ["missingGlyphMask"],
                riskFlags: ["segmentMaskReportMissing"],
                notes: ["fallbackDiagnosticForSegmentMaskProxyCoverageScoreboard"]
            )
        }

        func isDecorativeProxyCase(block: MangaOverlayProbeBlock, segment: MangaOverlaySegmentMaskDiagnostic) -> Bool {
            if segment.riskFlags.contains("decorativeTitle") || segment.rejectionReasons.contains("decorativeTitleDiagnosticOnly") {
                return true
            }
            guard block.bubbleID == nil else { return false }
            let normalized = block.finalTextUsedForTranslation.lowercased()
            return normalized.contains("city battler") || normalized.contains("offline tournament")
        }

        func coverageStatus(block: MangaOverlayProbeBlock, segment: MangaOverlaySegmentMaskDiagnostic) -> String {
            if segment.glyphMaskPixelCount <= 0 {
                return "weakMissingGlyphMask"
            }
            if isDecorativeProxyCase(block: block, segment: segment) {
                return "decorativeDiagnosticOnly"
            }
            if block.bubbleID == nil {
                return "unassignedDiagnosticOnly"
            }
            if segment.glyphEscapesTextBox || (segment.textBoxCoverageRatio ?? 1) < 0.42 {
                return "weakTextBoxCoverageLow"
            }
            if segment.glyphEscapesBubble || (segment.bubbleMaskCoverageRatio ?? 1) < 0.45 {
                return "weakBubbleCoverageLow"
            }
            if (segment.safeRectCoverageRatio ?? 1) < 0.38 {
                return "weakSafeRectCoverageLow"
            }
            if segment.usableForCropEvidence {
                return "usableProxyCoverage"
            }
            if segment.usableForCleanup {
                return "usableForCleanupOnly"
            }
            return "needsRealSegmentMask"
        }

        func cleanupStatus(block: MangaOverlayProbeBlock, segment: MangaOverlaySegmentMaskDiagnostic, coverage: String) -> String {
            if segment.glyphMaskPixelCount <= 0 {
                return "glyphMaskMissing"
            }
            if segment.glyphEscapesTextBox {
                return "glyphMaskEscapesTextBox"
            }
            if segment.glyphEscapesBubble {
                return "glyphMaskEscapesBubble"
            }
            if block.backgroundFillApplied {
                return "backgroundFillApplied"
            }
            if let stdDev = block.backgroundColorStdDev, stdDev > 34 {
                return "backgroundTooComplex"
            }
            if coverage == "needsRealSegmentMask" || coverage == "unassignedDiagnosticOnly" || coverage == "decorativeDiagnosticOnly" {
                return "cleanupBlockedProxyOnly"
            }
            return "cleanupEvidenceStable"
        }

        func renderMaskStatus(block: MangaOverlayProbeBlock) -> String {
            if block.renderTextTruncated {
                return "renderTruncated"
            }
            if block.renderMaskOverflowPixelCount > 0 {
                return "renderMaskOverflow"
            }
            if block.renderMaskCollisionChecked {
                return block.renderMaskCollisionResolved ? "renderMaskStable" : "renderMaskUnresolved"
            }
            return "renderNotChecked"
        }

        func backgroundFillStatus(card: MangaSegmentMaskProxyBlockScorecard) -> String {
            if card.backgroundFillApplied {
                return "backgroundFillApplied"
            }
            if card.cleanupStatus == "backgroundTooComplex" {
                return "backgroundFillGuardedComplex"
            }
            if card.glyphMaskPixelCount <= 0 {
                return "backgroundFillBlockedMissingGlyph"
            }
            return "backgroundFillNotApplied"
        }

        func primaryBottleneck(
            coverage: String,
            cleanup: String,
            render: String,
            textBoxStatus: String?,
            bubbleStatus: String?
        ) -> String {
            if coverage == "weakMissingGlyphMask" {
                return "glyphMaskMissing"
            }
            if coverage == "weakTextBoxCoverageLow" || cleanup == "glyphMaskEscapesTextBox" {
                return "textBoxCoverageLow"
            }
            if coverage == "weakBubbleCoverageLow" || cleanup == "glyphMaskEscapesBubble" {
                return "bubbleMaskCoverageLow"
            }
            if coverage == "weakSafeRectCoverageLow" {
                return "safeRectCoverageLow"
            }
            if render == "renderMaskOverflow" || render == "renderMaskUnresolved" || render == "renderTruncated" {
                return "renderMaskCollision"
            }
            if textBoxStatus == "blockedByWeakSegmentMask" {
                return "nativeTextBoxSegmentBoundary"
            }
            if bubbleStatus == "needsRealBubbleMask" {
                return "bubbleMaskBoundary"
            }
            if coverage == "needsRealSegmentMask" {
                return "needsRealSegmentMask"
            }
            return "proxyCoverageStable"
        }

        func nextAction(coverage: String, cleanup: String, render: String, block: MangaOverlayProbeBlock) -> String {
            if render == "renderMaskOverflow" || render == "renderMaskUnresolved" || render == "renderTruncated" {
                return "routeToRenderRegressionLock"
            }
            if block.backgroundFillApplied || cleanup == "backgroundTooComplex" {
                return "keepBackgroundFillGuardrail"
            }
            if coverage == "usableProxyCoverage" && cleanup == "cleanupEvidenceStable" {
                return "lockRenderCleanupBoundary"
            }
            if coverage == "weakMissingGlyphMask" || coverage == "needsRealSegmentMask" {
                return "collectRealSegmentMaskArtifact"
            }
            if coverage == "unassignedDiagnosticOnly" || coverage == "decorativeDiagnosticOnly" {
                return "manualReviewOnly"
            }
            if coverage == "usableForCleanupOnly" {
                return "doNotUseForCropPromotion"
            }
            return "keepReportOnly"
        }

        func evaluationSignals(for block: MangaOverlayProbeBlock) -> [MangaSegmentMaskProxyDecisionSignal] {
            [
                signal("ocrGroundTruthSimilarity", ratioString(block.ocrGroundTruthSimilarity), source: "blocks.ocrGroundTruthSimilarity", decision: false, evaluation: true),
                signal("bestGroundTruthType", block.bestGroundTruthType ?? "nil", source: "blocks.bestGroundTruthType", decision: false, evaluation: true),
                signal("groundTruthMatch", block.groundTruthMatch, source: "blocks.groundTruthMatch", decision: false, evaluation: true),
                signal("wordOrderPreserved", block.wordOrderPreserved.map(String.init) ?? "nil", source: "blocks.wordOrderPreserved", decision: false, evaluation: true)
            ]
        }

        var blockScorecards: [MangaSegmentMaskProxyBlockScorecard] = []
        blockScorecards.reserveCapacity(blocks.count)
        for block in blocks {
            let segment = segmentByBlock[block.index] ?? fallbackSegment(for: block)
            let nativeScorecard = nativeScorecardByBlock[block.index]
            let textBoxLedger = textBoxLedgerByBlock[block.index]
            let bubbleScoreboard = bubbleScoreboardByBlock[block.index]
            let coverage = coverageStatus(block: block, segment: segment)
            let cleanup = cleanupStatus(block: block, segment: segment, coverage: coverage)
            let render = renderMaskStatus(block: block)
            let bottleneck = primaryBottleneck(
                coverage: coverage,
                cleanup: cleanup,
                render: render,
                textBoxStatus: textBoxLedger?.qualityStatus,
                bubbleStatus: bubbleScoreboard?.siblingLayoutStatus
            )
            let action = nextAction(coverage: coverage, cleanup: cleanup, render: render, block: block)
            var mustNotPromote = [
                "segmentMaskProxyReportOnly",
                "proxyNotRealSegmentMask",
                "doesNotChangeGlyphMaskFillRects",
                "doesNotChangeBackgroundFillBehavior",
                "doesNotChangeSafeLayoutRect",
                "doesNotChangeTextRegionCropAdoptedCount",
                "groundTruthUsedOnlyForEvaluationSignals"
            ]
            mustNotPromote.append(contentsOf: segment.rejectionReasons)
            mustNotPromote.append(contentsOf: segment.riskFlags)
            mustNotPromote.append(contentsOf: nativeScorecard?.mustNotPromoteReasons ?? [])
            mustNotPromote.append(contentsOf: textBoxLedger?.mustNotPromoteReasons ?? [])
            mustNotPromote.append(contentsOf: bubbleScoreboard?.mustNotPromoteReasons ?? [])
            let decisionSignals = [
                signal("glyphMaskPixelCount", String(segment.glyphMaskPixelCount), source: "segmentMaskReport.diagnostics"),
                signal("glyphMaskFillRectCount", String(segment.glyphMaskFillRectCount), source: "segmentMaskReport.diagnostics"),
                signal("textBoxCoverageRatio", ratioString(segment.textBoxCoverageRatio), source: "segmentMaskReport.diagnostics"),
                signal("bubbleMaskCoverageRatio", ratioString(segment.bubbleMaskCoverageRatio), source: "segmentMaskReport.diagnostics"),
                signal("safeRectCoverageRatio", ratioString(segment.safeRectCoverageRatio), source: "segmentMaskReport.diagnostics"),
                signal("usableForCleanup", String(segment.usableForCleanup), source: "segmentMaskReport.diagnostics"),
                signal("usableForCropEvidence", String(segment.usableForCropEvidence), source: "segmentMaskReport.diagnostics"),
                signal("backgroundFillApplied", String(block.backgroundFillApplied), source: "blocks.backgroundFillApplied"),
                signal("backgroundColorStdDev", ratioString(block.backgroundColorStdDev), source: "blocks.backgroundColorStdDev"),
                signal("renderMaskOverflowPixelCount", String(block.renderMaskOverflowPixelCount), source: "blocks.renderMaskDiagnostics"),
                signal("nativeTextBoxLedgerStatus", textBoxLedger?.qualityStatus ?? "nil", source: "nativeTextBoxProxyLedgerReport.blockLedgers"),
                signal("bubbleMaskRenderStatus", bubbleScoreboard?.renderMaskStatus ?? "nil", source: "bubbleMaskAssignmentSplitScoreboardReport.blockScorecards")
            ]
            blockScorecards.append(
                MangaSegmentMaskProxyBlockScorecard(
                    blockIndex: block.index,
                    bubbleID: block.bubbleID,
                    textBoxCandidateID: segment.textBoxCandidateID,
                    glyphMaskPixelCount: segment.glyphMaskPixelCount,
                    glyphMaskRect: segment.glyphMaskRect,
                    glyphMaskFillRectCount: segment.glyphMaskFillRectCount,
                    textBoxCoverageRatio: segment.textBoxCoverageRatio,
                    bubbleMaskCoverageRatio: segment.bubbleMaskCoverageRatio,
                    safeRectCoverageRatio: segment.safeRectCoverageRatio,
                    glyphEscapesTextBox: segment.glyphEscapesTextBox,
                    glyphEscapesBubble: segment.glyphEscapesBubble,
                    usableForCleanup: segment.usableForCleanup,
                    usableForCropEvidence: segment.usableForCropEvidence,
                    segmentRejectionReasons: segment.rejectionReasons,
                    segmentRiskFlags: segment.riskFlags,
                    coverageStatus: coverage,
                    cleanupStatus: cleanup,
                    renderMaskStatus: render,
                    backgroundFillApplied: block.backgroundFillApplied,
                    backgroundColorStdDev: block.backgroundColorStdDev,
                    renderMaskCollisionChecked: block.renderMaskCollisionChecked,
                    renderMaskCollisionResolved: block.renderMaskCollisionResolved,
                    renderMaskOverflowPixelCount: block.renderMaskOverflowPixelCount,
                    renderCollisionResolved: block.renderCollisionResolved,
                    renderTextTruncated: block.renderTextTruncated,
                    textBoxLedgerStatus: textBoxLedger?.qualityStatus,
                    bubbleMaskScoreboardStatus: bubbleScoreboard?.renderMaskStatus,
                    primarySegmentBottleneck: bottleneck,
                    decisionSignals: decisionSignals,
                    evaluationSignals: evaluationSignals(for: block),
                    mustNotPromoteReasons: sortedUniqueStrings(mustNotPromote),
                    nextAction: action,
                    groundTruthUsedForDecision: false,
                    diagnosticOnly: true,
                    wouldChangeMainFlow: false
                )
            )
        }

        let glyphMaskBlocks = uniqueSorted(blockScorecards.filter { $0.glyphMaskPixelCount > 0 }.map(\.blockIndex))
        let usableForCleanupBlocks = uniqueSorted(segmentMaskReport?.usableForCleanupBlocks ?? blockScorecards.filter(\.usableForCleanup).map(\.blockIndex))
        let usableForCropEvidenceBlocks = uniqueSorted(segmentMaskReport?.usableForCropEvidenceBlocks ?? blockScorecards.filter(\.usableForCropEvidence).map(\.blockIndex))
        let weakSegmentBlocks = uniqueSorted(segmentMaskReport?.weakSegmentBlocks ?? blockScorecards.filter { !$0.usableForCropEvidence }.map(\.blockIndex))
        let glyphEscapesTextBoxBlocks = uniqueSorted(blockScorecards.filter(\.glyphEscapesTextBox).map(\.blockIndex))
        let glyphEscapesBubbleBlocks = uniqueSorted(blockScorecards.filter(\.glyphEscapesBubble).map(\.blockIndex))
        let safeRectCoverageLowBlocks = uniqueSorted(blockScorecards.filter { ($0.safeRectCoverageRatio ?? 1) < 0.38 }.map(\.blockIndex))
        let backgroundFillAppliedBlocks = uniqueSorted(blockScorecards.filter(\.backgroundFillApplied).map(\.blockIndex))
        let renderBlockedBlocks = uniqueSorted(blockScorecards.filter {
            $0.renderMaskStatus == "renderMaskOverflow"
                || $0.renderMaskStatus == "renderMaskUnresolved"
                || $0.renderMaskStatus == "renderTruncated"
        }.map(\.blockIndex))
        let needsRealSegmentMaskBlocks = uniqueSorted(blockScorecards.filter { $0.nextAction == "collectRealSegmentMaskArtifact" || $0.coverageStatus == "needsRealSegmentMask" }.map(\.blockIndex))
        let manualReviewBlocks = uniqueSorted(blockScorecards.filter { $0.nextAction == "manualReviewOnly" }.map(\.blockIndex))

        func backgroundGuardrailStatus(block: MangaSegmentMaskProxyBlockScorecard) -> String {
            if block.backgroundFillApplied {
                return "appliedByExistingGuardrail"
            }
            if block.cleanupStatus == "backgroundTooComplex" {
                return "blockedByComplexBackground"
            }
            return "notApplied"
        }

        let cleanupLedgers = blockScorecards.map { card -> MangaSegmentMaskProxyCleanupLedger in
            let glyphAvailable = card.glyphMaskPixelCount > 0
            var blocked: [String] = []
            if !glyphAvailable { blocked.append("missingGlyphMask") }
            if card.glyphEscapesTextBox { blocked.append("glyphMaskEscapesTextBox") }
            if card.glyphEscapesBubble { blocked.append("glyphMaskEscapesBubble") }
            if card.cleanupStatus == "backgroundTooComplex" { blocked.append("backgroundTooComplex") }
            if card.coverageStatus == "needsRealSegmentMask" { blocked.append("needsRealSegmentMask") }
            if card.coverageStatus == "unassignedDiagnosticOnly" { blocked.append("unassignedDiagnosticOnly") }
            if card.coverageStatus == "decorativeDiagnosticOnly" { blocked.append("decorativeDiagnosticOnly") }
            let allowedUse: String
            if card.backgroundFillApplied {
                allowedUse = "backgroundFillAlreadyApplied"
            } else if !glyphAvailable {
                allowedUse = "blockedMissingGlyphMask"
            } else if card.cleanupStatus == "backgroundTooComplex" {
                allowedUse = "blockedComplexBackground"
            } else if card.cleanupStatus == "cleanupBlockedProxyOnly" || card.coverageStatus == "needsRealSegmentMask" {
                allowedUse = "blockedNeedsRealSegmentMask"
            } else if card.renderMaskStatus == "renderMaskStable" {
                allowedUse = "renderBoundaryEvidence"
            } else {
                allowedUse = "reportOnlyGlyphBoundary"
            }
            return MangaSegmentMaskProxyCleanupLedger(
                blockIndex: card.blockIndex,
                cleanupLedgerID: "segmentMaskProxyCleanup-\(card.blockIndex)",
                glyphMaskAvailable: glyphAvailable,
                glyphMaskPixelCount: card.glyphMaskPixelCount,
                fillRectCount: card.glyphMaskFillRectCount,
                backgroundFillApplied: card.backgroundFillApplied,
                backgroundFillGuardrailStatus: backgroundGuardrailStatus(block: card),
                backgroundStdDev: card.backgroundColorStdDev,
                cleanupCoverageStatus: card.cleanupStatus,
                allowedCleanupUse: allowedUse,
                blockedCleanupReasons: sortedUniqueStrings(blocked + card.segmentRejectionReasons),
                wouldNeedInpainting: allowedUse == "blockedNeedsRealSegmentMask" || card.cleanupStatus == "backgroundTooComplex",
                inpaintingImplemented: false,
                proxyOnly: true,
                sourceReports: ["segmentMaskReport", "blocks.glyphMask", "blocks.backgroundFill", "renderDiagnostics"],
                decisionSignals: card.decisionSignals.filter(\.groundTruthFreeDecisionSignal),
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false
            )
        }

        func gate(
            _ id: String,
            name: String,
            scope: String,
            status: String,
            threshold: String,
            affected: [Int],
            failureMeans: String,
            action: String,
            signals: [MangaSegmentMaskProxyDecisionSignal]
        ) -> MangaSegmentMaskProxyGate {
            MangaSegmentMaskProxyGate(
                gateID: id,
                gateName: name,
                scope: scope,
                status: status,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                decisionSignals: signals,
                failureMeans: failureMeans,
                recommendedAction: action,
                groundTruthUsedForDecision: false
            )
        }

        let gateLedger = [
            gate("G-segmentmask-no-main-flow-mutation", name: "No main flow mutation", scope: "report", status: "passed", threshold: "wouldChangeMainFlow=false", affected: [], failureMeans: "scoreboard mutates OCR, translation, overlay, cleanup, safeLayoutRect, blockPassed, or currentBlockSource", action: "revertBehavioralChange", signals: [signal("wouldChangeMainFlow", "false", source: "segmentMaskProxyCoverageScoreboardReport")]),
            gate("G-segmentmask-no-ground-truth-decision", name: "No ground truth decision", scope: "report", status: "passed", threshold: "groundTruthUsedForDecision=false", affected: [], failureMeans: "ground truth influences coverage, cleanup, nextAction, or gate status", action: "removeGroundTruthFromDecisionPath", signals: [signal("groundTruthUsedForDecision", "false", source: "segmentMaskProxyCoverageScoreboardReport")]),
            gate("G-segmentmask-proxy-boundary", name: "Proxy boundary", scope: "SegmentMask", status: "proxyOnly", threshold: "proxyNotRealSegmentMask=true", affected: blocks.map(\.index), failureMeans: "AITRANS glyph proxy is mislabeled as real Koharu SegmentMask", action: "keepProxyLabelOrCollectRealSegmentMaskArtifact", signals: [signal("proxyNotRealSegmentMask", "true", source: "segmentMaskProxyCoverageScoreboardReport")]),
            gate("G-segmentmask-glyph-available", name: "Glyph mask available", scope: "glyphCleanup", status: glyphMaskBlocks.count == blocks.count ? "passed" : "warning", threshold: "glyphMaskPixelCount > 0", affected: uniqueSorted(blocks.map(\.index).filter { !glyphMaskBlocks.contains($0) }), failureMeans: "cleanup boundary is assumed without glyph evidence", action: "collectRealSegmentMaskArtifact", signals: [signal("glyphMaskBlocks", joined(glyphMaskBlocks), source: "segmentMaskReport")]),
            gate("G-segmentmask-textbox-coverage", name: "TextBox coverage", scope: "nativeTextBoxes", status: glyphEscapesTextBoxBlocks.isEmpty ? "passed" : "warning", threshold: "glyph remains inside TextBox proxy", affected: glyphEscapesTextBoxBlocks, failureMeans: "glyph cleanup crosses TextBox boundary", action: "keepReportOnly", signals: [signal("glyphEscapesTextBoxBlocks", joined(glyphEscapesTextBoxBlocks), source: "segmentMaskReport")]),
            gate("G-segmentmask-bubble-coverage", name: "Bubble coverage", scope: "BubbleMask", status: glyphEscapesBubbleBlocks.isEmpty ? "passed" : "warning", threshold: "glyph remains inside BubbleMask proxy", affected: glyphEscapesBubbleBlocks, failureMeans: "glyph cleanup crosses bubble mask", action: "collectRealSegmentMaskArtifact", signals: [signal("glyphEscapesBubbleBlocks", joined(glyphEscapesBubbleBlocks), source: "segmentMaskReport")]),
            gate("G-segmentmask-safe-rect-coverage", name: "Safe rect coverage", scope: "renderLayout", status: safeRectCoverageLowBlocks.isEmpty ? "passed" : "warning", threshold: "safeRectCoverageRatio >= 0.38", affected: safeRectCoverageLowBlocks, failureMeans: "render cleanup boundary is outside safe text area", action: "routeToRenderRegressionLock", signals: [signal("safeRectCoverageLowBlocks", joined(safeRectCoverageLowBlocks), source: "segmentMaskReport")]),
            gate("G-segmentmask-background-fill-guardrail", name: "Background fill guardrail", scope: "glyphCleanup", status: backgroundFillAppliedBlocks.isEmpty ? "reportOnly" : "passed", threshold: "existing background fill behavior only", affected: backgroundFillAppliedBlocks, failureMeans: "scoreboard changes background fill threshold or behavior", action: "keepBackgroundFillGuardrail", signals: [signal("backgroundFillAppliedBlocks", joined(backgroundFillAppliedBlocks), source: "blocks.backgroundFillApplied")]),
            gate("G-segmentmask-render-mask-collision", name: "Render mask collision", scope: "finalRender", status: renderBlockedBlocks.isEmpty ? "passed" : "blocked", threshold: "no unresolved mask overflow or truncation", affected: renderBlockedBlocks, failureMeans: "render overflow is hidden or ignored", action: "routeToRenderRegressionLock", signals: [signal("renderBlockedBlocks", joined(renderBlockedBlocks), source: "blocks.renderMaskDiagnostics")]),
            gate("G-segmentmask-textbox-ledger-boundary", name: "TextBox ledger boundary", scope: "nativeTextBoxes", status: "passed", threshold: "SegmentMask scorecard cannot thaw crop/line stoplist", affected: nativeTextBoxProxyLedgerReport?.stoplistBlocks ?? [], failureMeans: "SegmentMask proxy work reopens frozen crop/line/deskew tuning", action: "respectNativeTextBoxProxyLedgerStoplist", signals: [signal("nativeTextBoxStoplistBlocks", joined(nativeTextBoxProxyLedgerReport?.stoplistBlocks ?? []), source: "nativeTextBoxProxyLedgerReport")]),
            gate("G-segmentmask-bubblemask-boundary", name: "BubbleMask boundary", scope: "BubbleMask", status: (bubbleMaskAssignmentSplitScoreboardReport?.needsRealBubbleMaskBlocks.isEmpty ?? true) ? "passed" : "warning", threshold: "SegmentMask proxy cannot override BubbleMask scorecard", affected: bubbleMaskAssignmentSplitScoreboardReport?.needsRealBubbleMaskBlocks ?? [], failureMeans: "SegmentMask cleanup bypasses BubbleMask assignment or split blockers", action: "respectBubbleMaskScoreboardBoundary", signals: [signal("needsRealBubbleMaskBlocks", joined(bubbleMaskAssignmentSplitScoreboardReport?.needsRealBubbleMaskBlocks ?? []), source: "bubbleMaskAssignmentSplitScoreboardReport")]),
            gate("G-segmentmask-real-artifact-boundary", name: "Real SegmentMask artifact boundary", scope: "externalArtifacts", status: needsRealSegmentMaskBlocks.isEmpty ? "reportOnly" : "needsRealArtifact", threshold: "proxy evidence is not a real Koharu SegmentMask", affected: needsRealSegmentMaskBlocks, failureMeans: "internal glyph proxy is promoted as learned segmentation", action: "collectRealSegmentMaskArtifact", signals: [signal("referenceKoharuArtifact", "SegmentMask", source: "segmentMaskProxyCoverageScoreboardReport"), signal("needsRealSegmentMaskBlocks", joined(needsRealSegmentMaskBlocks), source: "segmentMaskProxyCoverageScoreboardReport")])
        ]

        return MangaSegmentMaskProxyCoverageScoreboardReport(
            enabled: true,
            source: "AITRANSProbe",
            referenceWorkItemID: "WI-segmentmask-proxy-coverage-scorecard",
            referenceKoharuArtifact: "SegmentMask",
            evaluatedBlockCount: blocks.count,
            glyphMaskBlockCount: segmentMaskReport?.glyphMaskBlocks ?? glyphMaskBlocks.count,
            usableForCleanupBlockCount: usableForCleanupBlocks.count,
            usableForCropEvidenceBlockCount: usableForCropEvidenceBlocks.count,
            weakSegmentBlockCount: weakSegmentBlocks.count,
            cleanupLedgerCount: cleanupLedgers.count,
            gateCount: gateLedger.count,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            proxyNotRealSegmentMask: true,
            coverageStatusBreakdown: countBy(blockScorecards.map(\.coverageStatus)),
            cleanupStatusBreakdown: countBy(blockScorecards.map(\.cleanupStatus)),
            renderMaskStatusBreakdown: countBy(blockScorecards.map(\.renderMaskStatus)),
            backgroundFillStatusBreakdown: countBy(blockScorecards.map { backgroundFillStatus(card: $0) }),
            nextActionBreakdown: countBy(blockScorecards.map(\.nextAction)),
            glyphMaskBlocks: glyphMaskBlocks,
            usableForCleanupBlocks: usableForCleanupBlocks,
            usableForCropEvidenceBlocks: usableForCropEvidenceBlocks,
            weakSegmentBlocks: weakSegmentBlocks,
            glyphEscapesTextBoxBlocks: glyphEscapesTextBoxBlocks,
            glyphEscapesBubbleBlocks: glyphEscapesBubbleBlocks,
            safeRectCoverageLowBlocks: safeRectCoverageLowBlocks,
            backgroundFillAppliedBlocks: backgroundFillAppliedBlocks,
            renderBlockedBlocks: renderBlockedBlocks,
            needsRealSegmentMaskBlocks: needsRealSegmentMaskBlocks,
            manualReviewBlocks: manualReviewBlocks,
            blockScorecards: blockScorecards.sorted { $0.blockIndex < $1.blockIndex },
            cleanupLedgers: cleanupLedgers.sorted { $0.blockIndex < $1.blockIndex },
            gateLedger: gateLedger,
            notes: [
                "segmentMaskProxyCoverageScoreboardReport executes WI-segmentmask-proxy-coverage-scorecard as report-only SegmentMask proxy scoreboard.",
                "cleanupLedgers use one ledger per final block so cleanupLedgerCount is stable and always >= glyphMaskBlockCount.",
                "It aggregates existing glyph mask, SegmentMask proxy, TextBox, BubbleMask, native ledger, background fill, and render collision evidence without new OCR or LLM calls.",
                "coverageStatus, cleanupStatus, renderMaskStatus, nextAction, and gates use ground-truth-free decision signals only; OCR ground truth metrics appear only in evaluationSignals.",
                "AITRANS SegmentMask is a glyph-mask proxy, not a real Koharu SegmentMask artifact.",
                "This report does not change finalTextUsedForTranslation, blockPassed, failureCategory, overlay rendering, safeLayoutRect, glyphMaskFillRects, background fill behavior, post-fusion cleanup, candidate selection, textRegionCropReport.adoptedCount, or currentBlockSource."
            ]
        )
    }

    private static func makeKoharuRenderRegressionLockReport(
        blocks: [MangaOverlayProbeBlock],
        diagnostics: MangaOverlayProbeDiagnostics,
        outputFiles: MangaOverlayProbeOutputFiles,
        outputDirectory: URL,
        bubbleMaskReport: MangaOverlayBubbleMaskReport?,
        segmentMaskProxyCoverageScoreboardReport: MangaSegmentMaskProxyCoverageScoreboardReport?
    ) -> MangaKoharuRenderRegressionLockReport {
        func uniqueSorted(_ values: [Int]) -> [Int] {
            Array(Set(values)).sorted()
        }

        func joined(_ values: [Int]) -> String {
            uniqueSorted(values).map(String.init).joined(separator: ",")
        }

        func joinedBreakdown(_ values: [String: Int]) -> String {
            values.map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ",")
        }

        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaKoharuRenderSignal {
            MangaKoharuRenderSignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }

        let retainedFiles = retainedProbeOutputFiles(from: outputFiles)
        let existingFiles = currentProbeOutputFileNames(in: outputDirectory)
        let retainedSet = Set(retainedFiles + existingFiles)
        let bubbleMaskByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleMaskReport?.blockDiagnostics ?? []).map { ($0.blockIndex, $0) }
        )
        let segmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentMaskProxyCoverageScoreboardReport?.blockScorecards ?? []).map { ($0.blockIndex, $0) }
        )

        func outputPath(for fileName: String) -> String {
            switch fileName {
            case "probe_report.json":
                return outputDirectory.appendingPathComponent(fileName).path
            case "clean_text_diagnostic.json":
                return outputFiles.cleanTextDiagnosticFile ?? outputDirectory.appendingPathComponent(fileName).path
            case "1_ocr_probe_text.txt":
                return outputFiles.ocrProbeTextFile ?? outputDirectory.appendingPathComponent(fileName).path
            case "1_debug_boxes.png":
                return outputFiles.debugBoxesImage
            case "1_translated_overlay.png":
                return outputFiles.overlayImage
            case "manga_probe_progress.json":
                return outputDirectory.appendingPathComponent(fileName).path
            default:
                return outputDirectory.appendingPathComponent(fileName).path
            }
        }

        func outputCheck(
            _ fileName: String,
            requiredInCIFast: Bool,
            requiredInFull: Bool,
            source: String
        ) -> MangaKoharuRenderOutputFileCheck {
            let path = outputPath(for: fileName)
            // The final probe report and OCR text ledger are written after this
            // report is assembled. Treat both as planned writes here so the
            // lock does not snapshot the short pre-rewrite window as an empty
            // required artifact. A failed final write aborts the probe before
            // this report can be persisted, so this remains an output contract
            // rather than a claim that an absent file is usable.
            let plannedFinalWrite = fileName == "probe_report.json"
                || fileName == "1_ocr_probe_text.txt"
            let retained = retainedSet.contains(fileName) || plannedFinalWrite
            let nonEmpty = fileIsNonEmpty(path: path) || plannedFinalWrite
            let status: String
            if plannedFinalWrite && !fileIsNonEmpty(path: path) {
                status = fileName == "probe_report.json"
                    ? "plannedFinalReportWrite"
                    : "plannedFinalOCRTextRewrite"
            } else if retained && nonEmpty {
                status = "presentNonEmpty"
            } else if retained {
                status = "presentButEmptyOrUnchecked"
            } else if fileName == "manga_probe_progress.json" {
                status = "notCheckedInApp"
            } else {
                status = "missing"
            }
            // Planned final writes are the expected post-assembly state for
            // the probe report and OCR text ledger. Keep their action aligned
            // with present, non-empty artifacts; only missing or unchecked
            // output should ask for render/export inspection.
            let recommendedAction = status == "presentNonEmpty" || plannedFinalWrite
                ? "keepReportOnly"
                : "inspectRenderOutputExport"
            return MangaKoharuRenderOutputFileCheck(
                fileName: fileName,
                requiredInCIFast: requiredInCIFast,
                requiredInFull: requiredInFull,
                presentInRetainedOutputFiles: retained,
                nonEmpty: nonEmpty,
                source: source,
                status: status,
                failureMeans: "CI artifact or App sandbox output is missing \(fileName)",
                recommendedAction: recommendedAction
            )
        }

        func renderStatus(for block: MangaOverlayProbeBlock, failureOverlayLocked: Bool) -> String {
            if block.renderTextTruncated {
                return "textTruncated"
            }
            if block.renderMaskOverflowPixelCount > 0 {
                return "maskOverflowUnresolved"
            }
            if block.safeLayoutRect == nil {
                return "safeLayoutMissing"
            }
            if block.renderCollisionChecked && !block.renderCollisionResolved {
                return "renderCollisionUnresolved"
            }
            if !block.blockPassed && failureOverlayLocked {
                return "failureOverlayStable"
            }
            if block.glyphMaskPixelCount <= 0 {
                return "glyphMaskMissingButAllowed"
            }
            if block.backgroundFillApplied {
                return "backgroundFillGuarded"
            }
            return "renderStable"
        }

        func primaryRisk(for block: MangaOverlayProbeBlock, failureOverlayLocked: Bool) -> String {
            if block.renderTextTruncated { return "textTruncated" }
            if block.renderMaskOverflowPixelCount > 0 { return "maskOverflowUnresolved" }
            if block.renderCollisionChecked && !block.renderCollisionResolved { return "renderCollisionUnresolved" }
            if block.safeLayoutRect == nil { return "safeLayoutMissing" }
            if !block.blockPassed && !failureOverlayLocked { return "failureOverlayMissing" }
            if block.glyphMaskPixelCount <= 0 { return "glyphMaskMissingAllowed" }
            return "none"
        }

        var blockLocks: [MangaKoharuRenderBlockLock] = []
        blockLocks.reserveCapacity(blocks.count)
        for block in blocks {
            let mask = bubbleMaskByBlock[block.index]
            let segment = segmentByBlock[block.index]
            let failureOverlayRequired = !block.blockPassed
            let expectedFallback = "翻译失败\n\(block.finalTextUsedForTranslation)"
            let failureOverlayLocked = !failureOverlayRequired
                || block.translatedText.trimmingCharacters(in: .whitespacesAndNewlines) == expectedFallback
            let status = renderStatus(for: block, failureOverlayLocked: failureOverlayLocked)
            let risk = primaryRisk(for: block, failureOverlayLocked: failureOverlayLocked)
            let nextAction = risk == "none" || risk == "glyphMaskMissingAllowed"
                ? "keepRenderLockReportOnly"
                : "inspectRenderLockGateLedger"
            blockLocks.append(
                MangaKoharuRenderBlockLock(
                    blockIndex: block.index,
                    bubbleID: block.bubbleID,
                    blockPassed: block.blockPassed,
                    failureCategory: block.failureCategory,
                    failureReasons: block.failureReasons,
                    safeLayoutRect: block.safeLayoutRect,
                    safeLayoutSource: block.safeLayoutSource,
                    maskSafeRect: block.maskSafeRect ?? mask?.maskSafeRect,
                    maskDominantBubbleID: mask?.maskDominantBubbleID,
                    maskDominantCoverage: mask?.maskDominantCoverageRatio,
                    maskBubbleIDConsistent: mask?.bubbleIDConsistent,
                    renderCollisionChecked: block.renderCollisionChecked,
                    renderCollisionInitialOverflow: block.renderCollisionInitialOverflow,
                    renderCollisionResolved: block.renderCollisionResolved,
                    renderMaskCollisionChecked: block.renderMaskCollisionChecked,
                    renderMaskCollisionResolved: block.renderMaskCollisionResolved,
                    renderMaskOverflowPixelCount: block.renderMaskOverflowPixelCount,
                    renderFontSize: block.renderFontSize,
                    renderMinFontSizeReached: block.renderMinFontSizeReached,
                    renderTextTruncated: block.renderTextTruncated,
                    renderNonTransparentBounds: block.renderNonTransparentBounds,
                    glyphMaskPixelCount: block.glyphMaskPixelCount,
                    glyphMaskFillRectCount: block.glyphMaskFillRects.count,
                    backgroundFillApplied: block.backgroundFillApplied,
                    backgroundFillColor: block.backgroundFillColor,
                    failureOverlayRequired: failureOverlayRequired,
                    failureOverlayLocked: failureOverlayLocked,
                    translationCandidateForRender: block.translationCandidate,
                    fallbackTextForRender: expectedFallback,
                    renderStatus: status,
                    primaryRenderRisk: risk,
                    recommendedNextAction: nextAction,
                    decisionSignals: [
                        signal("safeLayoutSource", block.safeLayoutSource ?? "nil", source: "blocks.safeLayoutSource"),
                        signal("renderCollisionResolved", String(block.renderCollisionResolved), source: "blocks.renderDiagnostics"),
                        signal("renderMaskOverflowPixelCount", String(block.renderMaskOverflowPixelCount), source: "blocks.renderDiagnostics"),
                        signal("renderMinFontSizeReached", String(block.renderMinFontSizeReached), source: "blocks.renderDiagnostics"),
                        signal("failureOverlayLocked", String(failureOverlayLocked), source: "blocks.translatedText"),
                        signal("segmentRenderMaskStatus", segment?.renderMaskStatus ?? "nil", source: "segmentMaskProxyCoverageScoreboardReport.blockScorecards")
                    ],
                    evaluationSignals: [
                        signal("groundTruthMatch", block.groundTruthMatch, source: "blocks.groundTruthMatch", decision: false, evaluation: true),
                        signal("bestGroundTruthType", block.bestGroundTruthType ?? "nil", source: "blocks.bestGroundTruthType", decision: false, evaluation: true),
                        signal("ocrSimilarityForEvaluation", block.ocrGroundTruthSimilarity?.formatted(.number.precision(.fractionLength(4))) ?? "nil", source: "blocks.ocrGroundTruthSimilarity", decision: false, evaluation: true)
                    ],
                    groundTruthUsedForDecision: false,
                    diagnosticOnly: true,
                    wouldChangeMainFlow: false
                )
            )
        }

        let outputChecks = [
            outputCheck("probe_report.json", requiredInCIFast: true, requiredInFull: true, source: "probeReportWrite"),
            outputCheck("clean_text_diagnostic.json", requiredInCIFast: true, requiredInFull: true, source: "cleanTextDiagnosticWrite"),
            outputCheck("1_ocr_probe_text.txt", requiredInCIFast: true, requiredInFull: true, source: "renderOutputs.writeOCRProbeText"),
            outputCheck("1_debug_boxes.png", requiredInCIFast: true, requiredInFull: true, source: "renderOutputs.debugBoxesImage"),
            outputCheck("1_translated_overlay.png", requiredInCIFast: true, requiredInFull: true, source: "renderOutputs.overlayImage"),
            outputCheck("manga_probe_progress.json", requiredInCIFast: false, requiredInFull: false, source: "writeMangaProbeProgress")
        ]

        let renderCollisionCheckedBlocks = uniqueSorted(blockLocks.filter(\.renderCollisionChecked).map(\.blockIndex))
        let renderCollisionResolvedBlocks = uniqueSorted(blockLocks.filter { $0.renderCollisionChecked && $0.renderCollisionResolved }.map(\.blockIndex))
        let renderCollisionUnresolvedBlocks = uniqueSorted(blockLocks.filter { $0.renderCollisionChecked && !$0.renderCollisionResolved }.map(\.blockIndex))
        let renderMaskCollisionCheckedBlocks = uniqueSorted(blockLocks.filter(\.renderMaskCollisionChecked).map(\.blockIndex))
        let renderMaskCollisionResolvedBlocks = uniqueSorted(blockLocks.filter { $0.renderMaskCollisionChecked && $0.renderMaskCollisionResolved }.map(\.blockIndex))
        let renderMaskOverflowBlocks = uniqueSorted(blockLocks.filter { $0.renderMaskOverflowPixelCount > 0 }.map(\.blockIndex))
        let renderMinFontSizeReachedBlocks = uniqueSorted(blockLocks.filter(\.renderMinFontSizeReached).map(\.blockIndex))
        let renderTextTruncatedBlocks = uniqueSorted(blockLocks.filter(\.renderTextTruncated).map(\.blockIndex))
        let failureOverlayRequiredBlocks = uniqueSorted(blockLocks.filter(\.failureOverlayRequired).map(\.blockIndex))
        let failureOverlayLockedBlocks = uniqueSorted(blockLocks.filter { $0.failureOverlayRequired && $0.failureOverlayLocked }.map(\.blockIndex))
        let safeLayoutRectBlocks = uniqueSorted(blockLocks.filter { $0.safeLayoutRect != nil }.map(\.blockIndex))
        let maskSafeRectBlocks = uniqueSorted(blockLocks.filter { $0.maskSafeRect != nil }.map(\.blockIndex))
        let glyphMaskBlocks = uniqueSorted(blockLocks.filter { $0.glyphMaskPixelCount > 0 }.map(\.blockIndex))
        let backgroundFillAppliedBlocks = uniqueSorted(blockLocks.filter(\.backgroundFillApplied).map(\.blockIndex))
        let outputRequiredFailures = outputChecks.filter { $0.requiredInCIFast && !$0.nonEmpty }.map(\.fileName)
        let renderIssueBlocks = uniqueSorted(blockLocks.filter { lock in
            lock.renderTextTruncated
                || lock.renderMaskOverflowPixelCount > 0
                || (lock.renderCollisionChecked && !lock.renderCollisionResolved)
                || lock.safeLayoutRect == nil
                || (lock.failureOverlayRequired && !lock.failureOverlayLocked)
        }.map(\.blockIndex))
        let coreOutputFilesPresent = outputChecks
            .filter(\.requiredInCIFast)
            .allSatisfy(\.presentInRetainedOutputFiles)
        let coreOutputFilesNonEmpty = outputChecks
            .filter(\.requiredInCIFast)
            .allSatisfy(\.nonEmpty)
        // A retained, non-empty core output set is already the report-only
        // success state. Keep the gate action aligned with each output check;
        // only a missing/empty required artifact should send diagnostics to
        // render/export inspection.
        let coreOutputRecommendedAction = coreOutputFilesNonEmpty
            ? "keepReportOnly"
            : "inspectRenderOutputExport"

        let renderLockVerdict: String
        if !coreOutputFilesPresent || !coreOutputFilesNonEmpty {
            renderLockVerdict = "blockedByMissingOutputFile"
        } else if renderCollisionCheckedBlocks.isEmpty && !blocks.isEmpty {
            renderLockVerdict = "blockedByMissingRenderDiagnostics"
        } else if !renderIssueBlocks.isEmpty {
            renderLockVerdict = "openRenderIssueDetected"
        } else if glyphMaskBlocks.count < blocks.count || backgroundFillAppliedBlocks.isEmpty {
            renderLockVerdict = "renderStableWithProxyBoundaries"
        } else {
            renderLockVerdict = "renderLockedReportOnly"
        }

        func stage(
            _ name: String,
            artifact: String,
            current: String,
            status: String,
            proxyOnly: Bool,
            realAvailable: Bool,
            reports: [String],
            affected: [Int],
            missing: [String],
            locked: [String],
            mustNot: [String],
            decisions: [MangaKoharuRenderSignal],
            evaluations: [MangaKoharuRenderSignal] = []
        ) -> MangaKoharuRenderArtifactStage {
            MangaKoharuRenderArtifactStage(
                stageName: name,
                referenceKoharuArtifact: artifact,
                currentAITRANSArtifact: current,
                stageStatus: status,
                proxyOnly: proxyOnly,
                realArtifactAvailable: realAvailable,
                sourceReports: reports,
                affectedBlocks: uniqueSorted(affected),
                decisionSignals: decisions,
                evaluationSignals: evaluations,
                missingKoharuCapabilities: missing,
