        ]

        func gate(
            _ id: String,
            name: String,
            scope: String,
            status: String,
            threshold: String,
            affected: [Int],
            failureMeans: String,
            action: String,
            decisions: [MangaKoharuRenderSignal]
        ) -> MangaKoharuRenderGate {
            MangaKoharuRenderGate(
                gateID: id,
                gateName: name,
                scope: scope,
                status: status,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                decisionSignals: decisions,
                failureMeans: failureMeans,
                recommendedAction: action,
                groundTruthUsedForDecision: false
