            node("renderedSpritesProxy", stage: "RenderedSpritesProxy", artifact: "RenderedSprites", current: "safeLayoutRect text drawing lock", needs: ["translations", "glyphEraseProxy"], produces: ["renderedSpritesProxy"], reports: ["koharuRenderRegressionLockReport"], status: renderIssueBlocks.isEmpty ? "availableReportOnly" : "blockedByRenderIssue", availability: "reportOnlyArtifact", executable: true, ciFast: true, requiresFull: false, requiresExternal: false, blockedBy: renderIssueBlocks.isEmpty ? [] : ["translations"], downstream: ["finalRender"], affected: renderIssueBlocks.isEmpty ? renderLockedBlocks : renderIssueBlocks, nextAction: renderIssueBlocks.isEmpty ? "keepRenderLockReportOnly" : "inspectRenderLockGateLedger", decisions: [signal("renderIssueBlocks", joined(renderIssueBlocks), source: "koharuRenderRegressionLockReport")], missing: ["real Koharu RenderedSprites artifact"], mustNot: ["doNotPromoteAITRANSRendererAsKoharuRenderer"]),
            node("finalRender", stage: "FinalRender", artifact: "FinalRender", current: "debug boxes and translated overlay PNG", needs: ["renderedSpritesProxy"], produces: ["finalRender"], reports: ["koharuRenderRegressionLockReport", "outputFiles"], status: renderIssueBlocks.isEmpty ? "availableReportOnly" : "blockedByRenderIssue", availability: "reportOnlyArtifact", executable: true, ciFast: true, requiresFull: false, requiresExternal: false, blockedBy: renderIssueBlocks.isEmpty ? [] : ["renderedSpritesProxy"], downstream: [], affected: renderIssueBlocks.isEmpty ? renderLockedBlocks : renderIssueBlocks, nextAction: renderIssueBlocks.isEmpty ? "keepFinalRenderLocked" : "inspectRenderLockGateLedger", decisions: [signal("renderLockVerdict", koharuRenderRegressionLockReport?.renderLockVerdict ?? "nil", source: "koharuRenderRegressionLockReport")], missing: ["real Koharu FinalRender artifact"], mustNot: ["doNotChangePNGRenderingInResolver"]),
            node("externalArtifacts", stage: "ExternalArtifacts", artifact: "TextBoxes/BubbleMask/SegmentMask", current: "test/koharu_artifacts readiness gate", needs: ["sourceImage"], produces: ["realTextBoxes", "realBubbleMask", "realSegmentMask"], reports: ["externalArtifactReadinessReport"], status: externalReady ? "availableNative" : "blockedMissingArtifact", availability: externalReady ? "nativeArtifact" : "missingExternalArtifact", executable: externalReady, ciFast: true, requiresFull: false, requiresExternal: true, blockedBy: externalReady ? [] : ["sourceImage"], downstream: ["bubbleMaskProxy", "textBoxProxy", "segmentMaskProxy"], affected: needsRealArtifactBlocks, nextAction: externalReady ? "keepExternalArtifactGateReady" : "collectRealKoharuArtifact", decisions: [signal("readinessVerdict", externalVerdict, source: "externalArtifactReadinessReport")], missing: externalReady ? [] : ["manifest", "TextBoxes", "BubbleMask", "SegmentMask"], mustNot: ["doNotCreateOrCopyActiveExternalArtifact", "doNotTreatContractExamplesAsActiveArtifacts"])
        ]

        func edge(_ from: String, _ to: String, artifact: String, required: Bool, status: String, reason: String?, affected: [Int]) -> MangaKoharuPipelineResolverEdge {
            MangaKoharuPipelineResolverEdge(
                fromNodeID: from,
                toNodeID: to,
                artifactName: artifact,
                required: required,
                edgeStatus: status,
                blockedReason: reason,
                affectedBlocks: uniqueSorted(affected),
                decisionSignals: [signal("edgeStatus", status, source: "koharuPipelineResolverReport.edges")],
                groundTruthUsedForDecision: false
            )
        }

        let edges = [
            edge("sourceImage", "contentCrop", artifact: "sourceImage", required: true, status: "satisfied", reason: nil, affected: allBlockIndexes),
            edge("contentCrop", "visionOCRCandidates", artifact: "contentCropImage", required: true, status: "satisfied", reason: nil, affected: allBlockIndexes),
            edge("visionOCRCandidates", "bubbleCandidates", artifact: "visionOCRCandidates", required: true, status: "satisfied", reason: nil, affected: allBlockIndexes),
            edge("bubbleCandidates", "bubbleMaskProxy", artifact: "bubbleCandidates", required: true, status: "satisfiedByProxy", reason: nil, affected: allBlockIndexes),
            edge("externalArtifacts", "bubbleMaskProxy", artifact: "realBubbleMask", required: false, status: externalReady ? "satisfied" : "blockedMissingArtifact", reason: externalReady ? nil : externalVerdict, affected: needsRealBubbleBlocks),
            edge("externalArtifacts", "textBoxProxy", artifact: "realTextBoxes", required: false, status: externalReady ? "satisfied" : "blockedMissingArtifact", reason: externalReady ? nil : externalVerdict, affected: stoplistBlocks),
            edge("externalArtifacts", "segmentMaskProxy", artifact: "realSegmentMask", required: false, status: externalReady ? "satisfied" : "blockedMissingArtifact", reason: externalReady ? nil : externalVerdict, affected: needsRealSegmentBlocks),
            edge("bubbleMaskProxy", "textBoxProxy", artifact: "bubbleMaskProxy", required: true, status: "satisfiedByProxy", reason: nil, affected: allBlockIndexes),
            edge("textBoxProxy", "ocrText", artifact: "textBoxProxy", required: true, status: stoplistBlocks.isEmpty ? "satisfiedReportOnly" : "stoplisted", reason: stoplistBlocks.isEmpty ? nil : "local crop/line/deskew tuning stoplisted", affected: stoplistBlocks),
            edge("segmentMaskProxy", "glyphEraseProxy", artifact: "segmentMaskProxy", required: false, status: "satisfiedByProxy", reason: nil, affected: allBlockIndexes),
            edge("ocrText", "fusionCleanup", artifact: "ocrText", required: true, status: "satisfiedReportOnly", reason: nil, affected: allBlockIndexes),
            edge("fusionCleanup", "translations", artifact: "cleanedBlocks", required: true, status: modelFloorBlocks.isEmpty ? "satisfied" : "blockedByUpstream", reason: modelFloorBlocks.isEmpty ? nil : "translation model floor or language quality failure", affected: modelFloorBlocks),
            edge("translations", "renderedSpritesProxy", artifact: "translations", required: true, status: modelFloorBlocks.isEmpty ? "satisfied" : "satisfiedReportOnly", reason: modelFloorBlocks.isEmpty ? nil : "content quality risk propagates to render output but renderer is not blamed", affected: modelFloorBlocks),
            edge("glyphEraseProxy", "renderedSpritesProxy", artifact: "glyphEraseProxy", required: false, status: "satisfiedByProxy", reason: nil, affected: allBlockIndexes),
            edge("renderedSpritesProxy", "finalRender", artifact: "renderedSpritesProxy", required: true, status: renderIssueBlocks.isEmpty ? "satisfiedReportOnly" : "blockedByUpstream", reason: renderIssueBlocks.isEmpty ? nil : "render issue blocks present", affected: renderIssueBlocks)
        ]

        func downstream(from nodeID: String) -> [String] {
            var seen: Set<String> = []
            var queue = edges.filter { $0.fromNodeID == nodeID }.map(\.toNodeID)
            while let next = queue.first {
                queue.removeFirst()
                guard seen.insert(next).inserted else { continue }
                queue.append(contentsOf: edges.filter { $0.fromNodeID == next }.map(\.toNodeID))
            }
            return Array(seen).sorted()
        }

        func firstBlockedNode(for block: MangaOverlayProbeBlock) -> (id: String, stage: String, reason: String, nextAction: String, execution: String, external: Bool, stoplisted: Bool) {
            if renderIssueBlocks.contains(block.index) {
                return ("finalRender", "FinalRender", "render issue reported by v1.30 lock", "inspectRenderLockGateLedger", "EX-resolver-render-lock-linked", false, false)
            }
            if modelFloorBlocks.contains(block.index) {
                return ("translations", "Translations", "translation model floor or language quality failure", "routeToTranslationModelFloor", "EX-resolver-translation-floor-linked", false, false)
            }
            if stoplistBlocks.contains(block.index) {
                return ("textBoxProxy", "TextBoxProxy", "local crop/line/deskew tuning stoplisted", externalReady ? "manualReviewOnly" : "collectRealKoharuArtifact", "EX-resolver-stop-crop-line-deskew", !externalReady, true)
            }
            if needsRealArtifactBlocks.contains(block.index) {
                return ("externalArtifacts", "ExternalArtifacts", "real Koharu artifacts missing: \(externalVerdict)", "collectRealKoharuArtifact", "EX-resolver-external-artifact-handoff", true, false)
            }
            if block.failureCategory == "ocrInputSuspect" || diagnostics.likelyOCRIssueBlocks.contains(block.index) {
                return ("ocrText", "OcrText", "OCR input suspect without promotable local tuning", externalReady ? "manualReviewOnly" : "collectRealKoharuArtifact", "EX-resolver-next-real-textboxes-needed", !externalReady, false)
            }
            if block.blockPassed {
                return ("none", "None", "no resolver blocker for report-only run", "keepReportOnly", "EX-resolver-native-proxy-scoreboards-closed", false, false)
            }
            return ("manualReview", "ManualReview", "unclassified failure in existing probe evidence", "manualReviewOnly", "EX-resolver-native-proxy-scoreboards-closed", false, false)
        }

        let criticalPath = ["sourceImage", "contentCrop", "visionOCRCandidates", "bubbleCandidates", "bubbleMaskProxy", "textBoxProxy", "segmentMaskProxy", "ocrText", "fusionCleanup", "translations", "glyphEraseProxy", "renderedSpritesProxy", "finalRender"]
        let nodeByID = Dictionary(uniqueKeysWithValues: nodes.map { ($0.nodeID, $0) })
        let blockTraces = blocks.map { block -> MangaKoharuPipelineResolverBlockTrace in
            let first = firstBlockedNode(for: block)
            let downstreamNodes = first.id == "none" || first.id == "manualReview" ? [] : downstream(from: first.id)
            let nodeStates = criticalPath.compactMap { nodeID -> MangaKoharuPipelineResolverBlockNodeState? in
                guard let node = nodeByID[nodeID] else { return nil }
                return MangaKoharuPipelineResolverBlockNodeState(
                    nodeID: node.nodeID,
                    status: node.nodeStatus,
                    artifactAvailability: node.artifactAvailability,
                    blockedReason: node.nodeID == first.id ? first.reason : nil,
                    sourceReports: node.sourceReports,
                    decisionSignals: [signal("nodeStatus", node.nodeStatus, source: "koharuPipelineResolverReport.nodes")],
                    evaluationSignals: [signal("groundTruthMatch", block.groundTruthMatch, source: "blocks.groundTruthMatch", decision: false, evaluation: true)]
                )
            }
            return MangaKoharuPipelineResolverBlockTrace(
                blockIndex: block.index,
                bubbleID: block.bubbleID,
                blockPassed: block.blockPassed,
                failureCategory: block.failureCategory,
                groundTruthMatch: block.groundTruthMatch,
                bestGroundTruthType: block.bestGroundTruthType,
                ocrSimilarityForEvaluation: block.ocrGroundTruthSimilarity,
                nodeStates: nodeStates,
                criticalPathNodeIDs: criticalPath,
                firstBlockedNodeID: first.id,
                firstBlockedStage: first.stage,
                firstBlockedReason: first.reason,
                downstreamBlockedNodeIDs: downstreamNodes,
                primaryBottleneck: koharuArtifactConvergenceReport?.blockPaths.first { $0.blockIndex == block.index }?.primaryStructuralBottleneck ?? first.stage,
                recommendedExecutionItemID: first.execution,
                recommendedNextAction: first.nextAction,
                canRunInCIFast: true,
                requiresFullProbe: false,
                requiresExternalArtifact: first.external,
                stoplistedLocalTuning: first.stoplisted,
                mustNotPromoteReasons: ["resolverDiagnosticOnly", "groundTruthUsedOnlyForEvaluationSignals"],
                decisionSignals: [
                    signal("failureCategory", block.failureCategory, source: "blocks.failureCategory"),
                    signal("firstBlockedNodeID", first.id, source: "koharuPipelineResolverReport")
                ],
                evaluationSignals: [
                    signal("groundTruthMatch", block.groundTruthMatch, source: "blocks.groundTruthMatch", decision: false, evaluation: true),
                    signal("bestGroundTruthType", block.bestGroundTruthType ?? "nil", source: "blocks.bestGroundTruthType", decision: false, evaluation: true),
                    signal("ocrSimilarityForEvaluation", block.ocrGroundTruthSimilarity?.formatted(.number.precision(.fractionLength(4))) ?? "nil", source: "blocks.ocrGroundTruthSimilarity", decision: false, evaluation: true)
                ],
                groundTruthUsedForDecision: false,
                diagnosticOnly: true,
                wouldChangeMainFlow: false
            )
        }

        func item(_ id: String, title: String, nodeID: String, stages: [String], targetBlocks: [Int], status: String, priority: String, reports: [String], blockers: [String] = [], external: Bool = false, action: String) -> MangaKoharuPipelineResolverExecutionItem {
            MangaKoharuPipelineResolverExecutionItem(
                executionItemID: id,
                title: title,
                targetNodeID: nodeID,
                targetStages: stages,
                targetBlocks: uniqueSorted(targetBlocks),
                status: status,
                priority: priority,
                sourceReports: reports,
                blockedByExecutionItemIDs: [],
                remainingBlockers: sortedUniqueStrings(blockers),
                canRunInCIFast: true,
                requiresFullProbe: false,
                requiresExternalArtifact: external,
                wouldChangeMainFlow: false,
                groundTruthUsedForDecision: false,
                recommendedNextAction: action
            )
        }

        let executionQueue = [
            item("EX-resolver-native-proxy-scoreboards-closed", title: "Close native proxy scoreboard inputs", nodeID: "textBoxProxy", stages: ["TextBoxProxy", "BubbleMaskProxy", "SegmentMaskProxy"], targetBlocks: allBlockIndexes, status: "closedReportOnly", priority: "P1", reports: ["nativeTextBoxProxyLedgerReport", "bubbleMaskAssignmentSplitScoreboardReport", "segmentMaskProxyCoverageScoreboardReport"], action: "keepResolverReportOnly"),
            item("EX-resolver-translation-floor-linked", title: "Link translation model floor", nodeID: "translations", stages: ["Translations"], targetBlocks: modelFloorBlocks, status: modelFloorBlocks.isEmpty ? "closedReportOnly" : "blockedByModelFloor", priority: modelFloorBlocks.isEmpty ? "P2" : "P0", reports: ["translationModelFloorComparisonReport", "cleanTextDiagnostic"], blockers: modelFloorBlocks.isEmpty ? [] : ["current small model floor remains open"], action: modelFloorBlocks.isEmpty ? "keepTranslationLedger" : "evaluateBetterSmallModelLater"),
            item("EX-resolver-render-lock-linked", title: "Link render regression lock", nodeID: "finalRender", stages: ["RenderedSpritesProxy", "FinalRender"], targetBlocks: renderIssueBlocks.isEmpty ? renderLockedBlocks : renderIssueBlocks, status: renderIssueBlocks.isEmpty ? "closedReportOnly" : "blockedByRenderIssue", priority: renderIssueBlocks.isEmpty ? "P2" : "P0", reports: ["koharuRenderRegressionLockReport"], blockers: renderIssueBlocks.isEmpty ? [] : ["render issue blocks present"], action: renderIssueBlocks.isEmpty ? "keepRenderLockReportOnly" : "inspectRenderLockGateLedger"),
            item("EX-resolver-external-artifact-handoff", title: "Record external artifact handoff", nodeID: "externalArtifacts", stages: ["ExternalArtifacts"], targetBlocks: needsRealArtifactBlocks, status: externalReady ? "readyReportOnly" : "blockedMissingExternalArtifact", priority: "P0", reports: ["externalArtifactReadinessReport"], blockers: externalReady ? [] : ["test/koharu_artifacts not ready: \(externalVerdict)"], external: true, action: externalReady ? "keepExternalArtifactGateReady" : "collectRealKoharuArtifact"),
            item("EX-resolver-stop-crop-line-deskew", title: "Stop local crop/line/deskew tuning", nodeID: "textBoxProxy", stages: ["TextBoxProxy", "OcrText"], targetBlocks: stoplistBlocks, status: stoplistBlocks.isEmpty ? "closedReportOnly" : "stoplisted", priority: "P0", reports: ["nativeTextBoxProxyLedgerReport"], blockers: stoplistBlocks.isEmpty ? [] : ["v20/v1.25 stoplist blocks must not be tuned again"], action: "stopLocalCropLineDeskewTuning"),
            item("EX-resolver-next-real-textboxes-needed", title: "Request real TextBoxes artifact", nodeID: "textBoxProxy", stages: ["TextBoxes"], targetBlocks: uniqueSorted(stoplistBlocks + diagnostics.likelyOCRIssueBlocks), status: externalReady ? "readyReportOnly" : "blockedMissingExternalArtifact", priority: "P0", reports: ["externalArtifactReadinessReport", "nativeTextBoxProxyLedgerReport"], blockers: externalReady ? [] : ["real TextBoxes missing"], external: true, action: "collectRealKoharuArtifact"),
            item("EX-resolver-next-real-bubblemask-needed", title: "Request real BubbleMask artifact", nodeID: "bubbleMaskProxy", stages: ["BubbleMask"], targetBlocks: needsRealBubbleBlocks, status: needsRealBubbleBlocks.isEmpty ? "closedReportOnly" : "blockedMissingExternalArtifact", priority: "P1", reports: ["bubbleMaskAssignmentSplitScoreboardReport"], blockers: needsRealBubbleBlocks.isEmpty ? [] : ["real BubbleMask missing"], external: true, action: needsRealBubbleBlocks.isEmpty ? "keepBubbleMaskProxyReportOnly" : "collectRealKoharuArtifact"),
            item("EX-resolver-next-real-segmentmask-needed", title: "Request real SegmentMask artifact", nodeID: "segmentMaskProxy", stages: ["SegmentMask"], targetBlocks: needsRealSegmentBlocks, status: needsRealSegmentBlocks.isEmpty ? "closedReportOnly" : "blockedMissingExternalArtifact", priority: "P1", reports: ["segmentMaskProxyCoverageScoreboardReport"], blockers: needsRealSegmentBlocks.isEmpty ? [] : ["real SegmentMask missing"], external: true, action: needsRealSegmentBlocks.isEmpty ? "keepSegmentMaskProxyReportOnly" : "collectRealKoharuArtifact")
        ]

        func op(_ id: String, kind: String, artifact: String, targetBlocks: [Int], blocked: String, source: String) -> MangaKoharuPipelineResolverOpPreview {
            MangaKoharuPipelineResolverOpPreview(opID: id, opKind: kind, targetArtifact: artifact, targetBlocks: uniqueSorted(targetBlocks), wouldApply: false, applyBlockedReason: blocked, sourceExecutionItemID: source, previewOnly: true, groundTruthUsedForDecision: false)
        }

        let opPreviews = [
            op("OP-resolver-record-report-only-artifact", kind: "recordReportOnlyArtifact", artifact: "PipelineResolverReport", targetBlocks: allBlockIndexes, blocked: "previewOnlyReportDoesNotApplyOps", source: "EX-resolver-native-proxy-scoreboards-closed"),
            op("OP-resolver-record-blocked-external-artifact", kind: "recordBlockedArtifact", artifact: "ExternalArtifacts", targetBlocks: needsRealArtifactBlocks, blocked: externalReady ? "externalArtifactGateReadyButPreviewOnly" : externalVerdict, source: "EX-resolver-external-artifact-handoff"),
            op("OP-resolver-record-stoplist", kind: "recordStoplist", artifact: "TextBoxes", targetBlocks: stoplistBlocks, blocked: "stoplistRecordedOnlyNoCropLineDeskewTuning", source: "EX-resolver-stop-crop-line-deskew"),
            op("OP-resolver-record-external-request", kind: "recordExternalArtifactRequest", artifact: "TextBoxes/BubbleMask/SegmentMask", targetBlocks: needsRealArtifactBlocks, blocked: "requiresHumanProvidedRealKoharuArtifact", source: "EX-resolver-external-artifact-handoff"),
            op("OP-resolver-record-model-floor", kind: "recordModelFloor", artifact: "Translations", targetBlocks: modelFloorBlocks, blocked: "modelNotChangedInResolver", source: "EX-resolver-translation-floor-linked"),
            op("OP-resolver-record-render-lock", kind: "recordRenderLock", artifact: "FinalRender", targetBlocks: renderIssueBlocks.isEmpty ? renderLockedBlocks : renderIssueBlocks, blocked: "rendererNotChangedInResolver", source: "EX-resolver-render-lock-linked")
        ]

        func gate(_ id: String, name: String, scope: String, status: String, threshold: String, affected: [Int], failureMeans: String, action: String) -> MangaKoharuPipelineResolverGate {
            MangaKoharuPipelineResolverGate(gateID: id, gateName: name, scope: scope, status: status, threshold: threshold, affectedBlocks: uniqueSorted(affected), decisionSignals: [signal("status", status, source: "koharuPipelineResolverReport.gateLedger")], failureMeans: failureMeans, recommendedAction: action, groundTruthUsedForDecision: false)
        }

        let missingReports = [
            koharuArtifactDAGReport == nil ? "koharuArtifactDAGReport" : nil,
            koharuStageGapReplicationReport == nil ? "koharuStageGapReplicationReport" : nil,
            koharuNativeReplicationScoreboardReport == nil ? "koharuNativeReplicationScoreboardReport" : nil,
            nativeTextBoxProxyLedgerReport == nil ? "nativeTextBoxProxyLedgerReport" : nil,
            bubbleMaskAssignmentSplitScoreboardReport == nil ? "bubbleMaskAssignmentSplitScoreboardReport" : nil,
            segmentMaskProxyCoverageScoreboardReport == nil ? "segmentMaskProxyCoverageScoreboardReport" : nil,
            translationModelFloorComparisonReport == nil ? "translationModelFloorComparisonReport" : nil,
            koharuRenderRegressionLockReport == nil ? "koharuRenderRegressionLockReport" : nil
        ].compactMap { $0 }

        let gateLedger = [
            gate("G-resolver-no-main-flow-mutation", name: "No main flow mutation", scope: "report", status: "passed", threshold: "wouldChangeMainFlow=false", affected: [], failureMeans: "resolver changes OCR, fusion, translation, render, blockPassed, or candidate selection", action: "revertBehavioralChange"),
            gate("G-resolver-no-ground-truth-decision", name: "No ground truth decision", scope: "report", status: "passed", threshold: "groundTruthUsedForDecision=false", affected: [], failureMeans: "ground truth drives node status, first blocked node, queue, or op preview", action: "moveGroundTruthToEvaluationSignalsOnly"),
            gate("G-resolver-node-count", name: "Resolver node count", scope: "DAGResolver", status: nodes.count >= 12 ? "passed" : "warning", threshold: "nodeCount>=12", affected: allBlockIndexes, failureMeans: "resolver DAG is incomplete", action: "restoreCanonicalResolverNodes"),
            gate("G-resolver-edge-count", name: "Resolver edge count", scope: "DAGResolver", status: edges.count >= 12 ? "passed" : "warning", threshold: "edgeCount>=12", affected: allBlockIndexes, failureMeans: "dependency propagation cannot be inspected", action: "restoreResolverEdges"),
            gate("G-resolver-block-trace-count", name: "Resolver block trace count", scope: "blocks", status: blockTraces.count == blocks.count ? "passed" : "warning", threshold: "blockTraceCount==totalBlocksDetected", affected: allBlockIndexes, failureMeans: "not every final block has a trace", action: "restorePerBlockResolverTrace"),
            gate("G-resolver-external-artifact-boundary", name: "External artifact boundary", scope: "ExternalArtifacts", status: externalReady ? "ready" : "blocked", threshold: "missing active artifacts never become fake detector output", affected: needsRealArtifactBlocks, failureMeans: "resolver promotes proxies as real Koharu artifacts", action: "collectRealKoharuArtifact"),
            gate("G-resolver-stoplist-respected", name: "Stoplist respected", scope: "TextBoxProxy", status: stoplistBlocks.isEmpty ? "passed" : "stop", threshold: "stoplist blocks are not tuned again", affected: stoplistBlocks, failureMeans: "resolver reopens known failed crop/line/deskew tuning", action: "stopLocalCropLineDeskewTuning"),
            gate("G-resolver-model-floor-boundary", name: "Model floor boundary", scope: "Translations", status: modelFloorBlocks.isEmpty ? "passed" : "warning", threshold: "model floor routes to Translations", affected: modelFloorBlocks, failureMeans: "model quality failure is misattributed to geometry", action: "routeToTranslationModelFloor"),
            gate("G-resolver-render-lock-boundary", name: "Render lock boundary", scope: "FinalRender", status: renderIssueBlocks.isEmpty ? "passed" : "warning", threshold: "render issue blocks route to render lock only", affected: renderIssueBlocks, failureMeans: "resolver changes overlay renderer", action: "inspectRenderLockGateLedger"),
            gate("G-resolver-ci-fast-availability", name: "CI fast availability", scope: "reportInputs", status: missingReports.isEmpty ? "passed" : "warning", threshold: "resolver degrades gracefully with missing full-only reports", affected: allBlockIndexes, failureMeans: "resolver crashes or hides missing upstream reports", action: "keepGeneratingWithWarningAndRestoreMissingReport")
        ]

        let manualReviewBlocks = uniqueSorted(blockTraces.filter { $0.recommendedNextAction == "manualReviewOnly" }.map(\.blockIndex))
        let resolverVerdict: String
        if !missingReports.isEmpty {
            resolverVerdict = "insufficientUpstreamReports"
        } else if !renderIssueBlocks.isEmpty {
            resolverVerdict = "blockedByRenderIssue"
        } else if !modelFloorBlocks.isEmpty {
            resolverVerdict = "blockedByModelFloor"
        } else if !needsRealArtifactBlocks.isEmpty {
            resolverVerdict = stoplistBlocks.isEmpty ? "blockedByMissingRealArtifacts" : "stopLocalTuningAndWaitForArtifact"
        } else if !manualReviewBlocks.isEmpty {
            resolverVerdict = "manualReviewOnly"
        } else {
            resolverVerdict = "resolverReadyWithProxyBoundaries"
        }

        return MangaKoharuPipelineResolverReport(
            enabled: true,
            source: "AITRANSProbe",
            referencePipeline: "Koharu",
            referenceConcept: "EngineInfo.needsProduces.DAGResolver.OpPreview",
            evaluatedBlockCount: blocks.count,
            nodeCount: nodes.count,
            edgeCount: edges.count,
            blockTraceCount: blockTraces.count,
            executionQueueCount: executionQueue.count,
            opPreviewCount: opPreviews.count,
            gateCount: gateLedger.count,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            externalArtifactsRequiredForThisReport: false,
            resolverVerdict: resolverVerdict,
            resolverVerdictBreakdown: countBy([resolverVerdict]),
            nodeStatusBreakdown: countBy(nodes.map(\.nodeStatus)),
            artifactAvailabilityBreakdown: countBy(nodes.map(\.artifactAvailability)),
            firstBlockedNodeBreakdown: countBy(blockTraces.map(\.firstBlockedNodeID)),
            executionItemStatusBreakdown: countBy(executionQueue.map(\.status)),
            nextActionBreakdown: countBy(blockTraces.map(\.recommendedNextAction)),
            blockedByMissingRealArtifactBlocks: needsRealArtifactBlocks,
            stoplistedLocalTuningBlocks: stoplistBlocks,
            modelFloorLimitedBlocks: modelFloorBlocks,
            renderLockedBlocks: renderLockedBlocks,
            manualReviewBlocks: manualReviewBlocks,
            nodes: nodes,
            edges: edges,
            blockTraces: blockTraces.sorted { $0.blockIndex < $1.blockIndex },
            executionQueue: executionQueue,
            opPreviews: opPreviews,
            gateLedger: gateLedger,
            notes: [
                "koharuPipelineResolverReport is a report-only shadow DAG inspired by Koharu EngineInfo.needs/produces, DAG resolver, and Op preview structure.",
                "It consumes existing AITRANS probe reports only and does not add OCR or LLM calls.",
                "Ground truth appears only in evaluationSignals and never selects node status, firstBlockedNodeID, executionQueue, opPreview, or recommendedNextAction.",
                "Proxy BubbleMask/TextBoxes/SegmentMask/renderer artifacts remain explicitly labeled as proxy or report-only."
            ]
        )
    }

    private static func makeKoharuWorkOrderRouterReport(
        blocks: [MangaOverlayProbeBlock],
        diagnostics: MangaOverlayProbeDiagnostics,
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?,
        nativeTextBoxProxyLedgerReport: MangaNativeTextBoxProxyLedgerReport?,
        bubbleMaskAssignmentSplitScoreboardReport: MangaBubbleMaskAssignmentSplitScoreboardReport?,
        segmentMaskProxyCoverageScoreboardReport: MangaSegmentMaskProxyCoverageScoreboardReport?,
        koharuArtifactConvergenceReport: MangaKoharuArtifactConvergenceReport?,
        koharuPipelineResolverReport: MangaKoharuPipelineResolverReport?,
        translationModelFloorComparisonReport: MangaTranslationModelFloorComparisonReport?,
        koharuRenderRegressionLockReport: MangaKoharuRenderRegressionLockReport?
    ) -> MangaKoharuWorkOrderRouterReport {
        func uniqueSorted(_ values: [Int]) -> [Int] {
            Array(Set(values)).sorted()
        }

        func sortedUniqueStrings(_ values: [String]) -> [String] {
            Array(Set(values)).sorted()
        }

        func joined(_ values: [Int]) -> String {
            uniqueSorted(values).map(String.init).joined(separator: ",")
        }

        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaKoharuWorkOrderSignal {
            MangaKoharuWorkOrderSignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }

        func gate(
            _ id: String,
            name: String,
            scope: String,
            status: String,
            threshold: String,
            affected: [Int],
            failureMeans: String,
            action: String,
            signals: [MangaKoharuWorkOrderSignal]
        ) -> MangaKoharuWorkOrderGate {
            MangaKoharuWorkOrderGate(
                gateID: id,
                gateName: name,
                scope: scope,
                status: status,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                decisionSignals: signals,
                failureMeans: failureMeans,
                recommendedAction: action,
                groundTruthUsedForDecision: false
            )
        }

        let allBlockIndexes = blocks.map(\.index)
        let resolverByBlock = Dictionary(
            uniqueKeysWithValues: (koharuPipelineResolverReport?.blockTraces ?? []).map { ($0.blockIndex, $0) }
        )
        let convergenceByBlock = Dictionary(
            uniqueKeysWithValues: (koharuArtifactConvergenceReport?.blockPaths ?? []).map { ($0.blockIndex, $0) }
        )
        let textBoxByBlock = Dictionary(
            uniqueKeysWithValues: (nativeTextBoxProxyLedgerReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let bubbleByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleMaskAssignmentSplitScoreboardReport?.blockScorecards ?? []).map { ($0.blockIndex, $0) }
        )
        let segmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentMaskProxyCoverageScoreboardReport?.blockScorecards ?? []).map { ($0.blockIndex, $0) }
        )
        let translationFloorByBlock = Dictionary(
            uniqueKeysWithValues: (translationModelFloorComparisonReport?.noisyBlockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let renderLockByBlock = Dictionary(
            uniqueKeysWithValues: (koharuRenderRegressionLockReport?.blockLocks ?? []).map { ($0.blockIndex, $0) }
        )

        let externalReady = externalArtifactReadinessReport?.externalTextBoxesShadowOCRAllowed == true
        let externalVerdict = externalArtifactReadinessReport?.readinessVerdict ?? "manifestMissing"
        let resolverInputPresent = koharuPipelineResolverReport?.enabled == true
        let stoplistBlocks = uniqueSorted(
            (koharuPipelineResolverReport?.stoplistedLocalTuningBlocks ?? []) +
            (nativeTextBoxProxyLedgerReport?.stoplistBlocks ?? [])
        )
        let modelFloorBlocks = uniqueSorted(
            (koharuPipelineResolverReport?.modelFloorLimitedBlocks ?? []) +
            (translationModelFloorComparisonReport?.noisyModelFloorBlocks ?? []) +
            blocks.filter { $0.failureCategory == "modelOutputFailure" || $0.failureCategory == "translationLanguageQualityFailure" }.map(\.index)
        )
        let renderIssueBlocks = uniqueSorted(koharuRenderRegressionLockReport?.renderIssueBlocks ?? [])
        let renderLockedBlocks = uniqueSorted(
            (koharuRenderRegressionLockReport?.blockLocks ?? [])
                .filter { !renderIssueBlocks.contains($0.blockIndex) }
                .map(\.blockIndex)
        )
        let needsRealTextBoxBlocks = uniqueSorted(
            stoplistBlocks +
            diagnostics.likelyOCRIssueBlocks +
            (nativeTextBoxProxyLedgerReport?.blockLedgers ?? [])
                .filter { $0.nextAction == "collectRealTextBoxArtifact" }
                .map(\.blockIndex)
        )
        let needsRealBubbleMaskBlocks = uniqueSorted(bubbleMaskAssignmentSplitScoreboardReport?.needsRealBubbleMaskBlocks ?? [])
        let needsRealSegmentMaskBlocks = uniqueSorted(segmentMaskProxyCoverageScoreboardReport?.needsRealSegmentMaskBlocks ?? [])
        let externalBlockedBlocks = externalReady ? [] : uniqueSorted(needsRealTextBoxBlocks + needsRealBubbleMaskBlocks + needsRealSegmentMaskBlocks)

        func route(for block: MangaOverlayProbeBlock) -> MangaKoharuWorkOrderBlockRoute {
            let resolver = resolverByBlock[block.index]
            let convergence = convergenceByBlock[block.index]
            let textBox = textBoxByBlock[block.index]
            let bubble = bubbleByBlock[block.index]
            let segment = segmentByBlock[block.index]
            let floor = translationFloorByBlock[block.index]
            let render = renderLockByBlock[block.index]
            let renderIssue = renderIssueBlocks.contains(block.index)
            let modelLimited = modelFloorBlocks.contains(block.index) || floor?.modelFloorLimited == true
            let stoplisted = stoplistBlocks.contains(block.index) || resolver?.stoplistedLocalTuning == true || textBox?.stoplistHit == true
            let needsTextBoxes = needsRealTextBoxBlocks.contains(block.index)
            let needsBubbleMask = needsRealBubbleMaskBlocks.contains(block.index)
                || bubble?.nextAction == "collectRealBubbleMaskArtifact"
                || bubble?.assignmentStatus == "maskConflict"
            let needsSegmentMask = needsRealSegmentMaskBlocks.contains(block.index)
                || segment?.nextAction == "collectRealSegmentMaskArtifact"
                || segment?.coverageStatus == "needsRealSegmentMask"
            let renderLocked = renderLockedBlocks.contains(block.index)
                || render?.renderStatus == "renderLocked"
                || convergence?.renderLocked == true
            let requiresExternal = !externalReady && (needsTextBoxes || needsBubbleMask || needsSegmentMask)

            let primary: String
            var secondary: [String] = []
            let budget: String
            let nextAction: String
            if renderIssue {
                primary = "WO-v132-keep-render-lock"
                budget = "ciFastReportOnly"
                nextAction = "inspectRenderLockGateLedger"
            } else if modelLimited {
                primary = "WO-v132-translation-model-floor-handoff"
                budget = "futureModelComparison"
                nextAction = "considerFutureModelComparison"
            } else if stoplisted || needsTextBoxes || block.failureCategory == "ocrInputSuspect" {
                primary = "WO-v132-request-real-textboxes"
                budget = requiresExternal ? "externalArtifactRequired" : "ciFastReportOnly"
                nextAction = requiresExternal ? "collectRealKoharuArtifact" : "keepTextBoxRequestReportOnly"
                if stoplisted {
                    secondary.append("WO-v132-stop-local-crop-line-deskew")
                }
            } else if needsBubbleMask {
                primary = "WO-v132-request-real-bubblemask"
                budget = requiresExternal ? "externalArtifactRequired" : "ciFastReportOnly"
                nextAction = requiresExternal ? "collectRealKoharuArtifact" : "keepBubbleMaskRequestReportOnly"
            } else if needsSegmentMask {
                primary = "WO-v132-request-real-segmentmask"
                budget = requiresExternal ? "externalArtifactRequired" : "ciFastReportOnly"
                nextAction = requiresExternal ? "collectRealKoharuArtifact" : "keepSegmentMaskRequestReportOnly"
            } else if block.blockPassed && renderLocked {
                primary = "WO-v132-close-resolver-ledger"
                secondary.append("WO-v132-keep-render-lock")
                budget = "ciFastReportOnly"
                nextAction = "keepResolverAndRenderLockReportOnly"
            } else if resolverInputPresent {
                primary = "WO-v132-close-resolver-ledger"
                budget = "ciFastReportOnly"
                nextAction = "keepResolverReportOnly"
            } else {
                primary = "WO-v132-manual-review-unclassified"
                budget = "manualReview"
                nextAction = "manualReviewOnly"
            }
            if requiresExternal && primary != "WO-v132-external-artifact-package-handoff" {
                secondary.append("WO-v132-external-artifact-package-handoff")
            }
            if !resolverInputPresent && !secondary.contains("WO-v132-manual-review-unclassified") {
                secondary.append("WO-v132-manual-review-unclassified")
            }

            let primaryBottleneck = convergence?.primaryStructuralBottleneck
                ?? resolver?.primaryBottleneck
                ?? textBox?.qualityStatus
                ?? bubble?.primaryBubbleBottleneck
                ?? segment?.primarySegmentBottleneck
                ?? block.failureCategory
            let resolverFirstBlockedNodeID = resolver?.firstBlockedNodeID ?? "missingResolverInput"
            let resolverRecommendedExecutionItemID = resolver?.recommendedExecutionItemID ?? "missingResolverInput"
            let secondaryWorkOrderIDs = sortedUniqueStrings(secondary)
            let decisionSignals: [MangaKoharuWorkOrderSignal] = [
                signal("failureCategory", block.failureCategory, source: "blocks.failureCategory"),
                signal("resolverFirstBlockedNodeID", resolver?.firstBlockedNodeID ?? "nil", source: "koharuPipelineResolverReport"),
                signal("stoplistedLocalTuning", String(stoplisted), source: "nativeTextBoxProxyLedgerReport,koharuPipelineResolverReport"),
                signal("modelFloorLimited", String(modelLimited), source: "translationModelFloorComparisonReport"),
                signal("requiresExternalArtifact", String(requiresExternal), source: "externalArtifactReadinessReport")
            ]
            let ocrSimilarityForEvaluation = block.ocrGroundTruthSimilarity
            let ocrSimilaritySignalValue = ocrSimilarityForEvaluation?.formatted(.number.precision(.fractionLength(4))) ?? "nil"
            let evaluationSignals: [MangaKoharuWorkOrderSignal] = [
                signal("groundTruthMatch", block.groundTruthMatch, source: "blocks.groundTruthMatch", decision: false, evaluation: true),
                signal("bestGroundTruthType", block.bestGroundTruthType ?? "nil", source: "blocks.bestGroundTruthType", decision: false, evaluation: true),
                signal("ocrSimilarityForEvaluation", ocrSimilaritySignalValue, source: "blocks.ocrGroundTruthSimilarity", decision: false, evaluation: true)
            ]
            var mustNotPromoteReasons = [
                "workOrderRouterDiagnosticOnly",
                "groundTruthUsedOnlyForEvaluationSignals",
                "doNotChangeMainOCRTranslationOverlayOrFailureClassification"
            ]
            mustNotPromoteReasons.append(contentsOf: resolver?.mustNotPromoteReasons ?? [])
            mustNotPromoteReasons.append(contentsOf: textBox?.mustNotPromoteReasons ?? [])
            mustNotPromoteReasons.append(contentsOf: bubble?.mustNotPromoteReasons ?? [])
            mustNotPromoteReasons.append(contentsOf: segment?.mustNotPromoteReasons ?? [])
            let uniqueMustNotPromoteReasons = sortedUniqueStrings(mustNotPromoteReasons)

            return MangaKoharuWorkOrderBlockRoute(
                blockIndex: block.index,
                bubbleID: block.bubbleID,
                blockPassed: block.blockPassed,
                failureCategory: block.failureCategory,
                groundTruthMatch: block.groundTruthMatch,
                bestGroundTruthType: block.bestGroundTruthType,
                ocrSimilarityForEvaluation: ocrSimilarityForEvaluation,
                resolverFirstBlockedNodeID: resolverFirstBlockedNodeID,
                resolverRecommendedExecutionItemID: resolverRecommendedExecutionItemID,
                primaryWorkOrderID: primary,
                secondaryWorkOrderIDs: secondaryWorkOrderIDs,
                primaryBottleneck: primaryBottleneck,
                modelFloorLimited: modelLimited,
                renderLocked: renderLocked,
                stoplistedLocalTuning: stoplisted,
                requiresRealTextBoxes: needsTextBoxes,
                requiresRealBubbleMask: needsBubbleMask,
                requiresRealSegmentMask: needsSegmentMask,
                requiresExternalArtifact: requiresExternal,
                canRunInCIFast: true,
                requiresFullProbe: false,
                budgetClass: budget,
                recommendedNextAction: nextAction,
                decisionSignals: decisionSignals,
                evaluationSignals: evaluationSignals,
                mustNotPromoteReasons: uniqueMustNotPromoteReasons,
                groundTruthUsedForDecision: false,
                diagnosticOnly: true,
                wouldChangeMainFlow: false
            )
        }

        let blockRoutes = blocks.map(route(for:)).sorted { $0.blockIndex < $1.blockIndex }
        let manualReviewBlocks = uniqueSorted(blockRoutes.filter { $0.primaryWorkOrderID == "WO-v132-manual-review-unclassified" }.map(\.blockIndex))

        func workOrder(
            _ id: String,
            title: String,
            stage: String,
            artifact: String,
            sourceExecutionItems: [String],
            sourceReports: [String],
            priority: String,
            status: String,
            budget: String,
            blocks targetBlocks: [Int],
            blockers: [String],
            ciFast: Bool,
            full: Bool,
            external: Bool,
            modelChange: Bool = false,
            allowed: Bool = true,
            forbidden: [String],
            action: String
        ) -> MangaKoharuWorkOrder {
            let gates = [
                gate("G-\(id)-report-only", name: "Report-only work order", scope: id, status: "passed", threshold: "wouldChangeMainFlow=false", affected: targetBlocks, failureMeans: "work order mutates OCR, translation, overlay, blockPassed, or candidate selection", action: "revertBehavioralChange", signals: [signal("wouldChangeMainFlow", "false", source: "koharuWorkOrderRouterReport")]),
                gate("G-\(id)-no-ground-truth-decision", name: "No ground truth decision", scope: id, status: "passed", threshold: "groundTruthUsedForDecision=false", affected: targetBlocks, failureMeans: "ground truth changes priority, status, budget, or next action", action: "moveGroundTruthToEvaluationSignalsOnly", signals: [signal("groundTruthUsedForDecision", "false", source: "koharuWorkOrderRouterReport")])
            ]
            return MangaKoharuWorkOrder(
                workOrderID: id,
                title: title,
                targetStage: stage,
                targetKoharuArtifact: artifact,
                sourceExecutionItemIDs: sourceExecutionItems,
                sourceReports: sourceReports,
                priority: priority,
                status: status,
                budgetClass: budget,
                targetBlocks: uniqueSorted(targetBlocks),
                blockedByWorkOrderIDs: [],
                remainingBlockers: sortedUniqueStrings(blockers),
                canRunInCIFast: ciFast,
                requiresFullProbe: full,
                requiresExternalArtifact: external,
                requiresModelChange: modelChange,
                requiresMainFlowChange: false,
                allowedInThisVersion: allowed,
                forbiddenActions: forbidden,
                promotionGates: gates,
                decisionSignals: [
                    signal("status", status, source: "koharuWorkOrderRouterReport.workOrders"),
                    signal("budgetClass", budget, source: "koharuWorkOrderRouterReport.workOrders"),
                    signal("targetBlocks", joined(targetBlocks), source: "koharuWorkOrderRouterReport.workOrders")
                ],
                evaluationSignals: [],
                recommendedNextAction: action,
                groundTruthUsedForDecision: false,
                diagnosticOnly: true,
                wouldChangeMainFlow: false
            )
        }

        let resolverStatus = resolverInputPresent ? "closedReportOnly" : "manualReviewOnly"
        let textBoxStatus = needsRealTextBoxBlocks.isEmpty ? "closedReportOnly" : (externalReady ? "readyReportOnly" : "blockedMissingExternalArtifact")
        let bubbleStatus = needsRealBubbleMaskBlocks.isEmpty ? "closedReportOnly" : (externalReady ? "readyReportOnly" : "blockedMissingExternalArtifact")
        let segmentStatus = needsRealSegmentMaskBlocks.isEmpty ? "closedReportOnly" : (externalReady ? "readyReportOnly" : "blockedMissingExternalArtifact")
        let renderStatus = renderIssueBlocks.isEmpty ? "closedReportOnly" : "blockedByRenderIssue"
        let modelStatus = modelFloorBlocks.isEmpty ? "closedReportOnly" : "blockedByModelFloor"
        let externalStatus = externalReady ? "readyReportOnly" : "blockedMissingExternalArtifact"
        let workOrders = [
            workOrder("WO-v132-close-resolver-ledger", title: "Close resolver ledger", stage: "DAGResolver", artifact: "PipelineResolverReport", sourceExecutionItems: ["EX-resolver-native-proxy-scoreboards-closed"], sourceReports: ["koharuPipelineResolverReport"], priority: "P1", status: resolverStatus, budget: "ciFastReportOnly", blocks: allBlockIndexes, blockers: resolverInputPresent ? [] : ["koharuPipelineResolverReport missing"], ciFast: true, full: false, external: false, forbidden: ["doNotChangeResolverDecisions"], action: resolverInputPresent ? "keepResolverReportOnly" : "restoreKoharuPipelineResolverReport"),
            workOrder("WO-v132-stop-local-crop-line-deskew", title: "Stop local crop line deskew tuning", stage: "TextBoxes", artifact: "TextBoxes", sourceExecutionItems: ["EX-resolver-stop-crop-line-deskew"], sourceReports: ["nativeTextBoxProxyLedgerReport", "textBoxPlanFailureReport", "lineCropExperimentReport"], priority: "P0", status: stoplistBlocks.isEmpty ? "closedReportOnly" : "closedStoplist", budget: "stoplistDoNotRun", blocks: stoplistBlocks, blockers: stoplistBlocks.isEmpty ? [] : ["v20/v1.25 stoplist blocks must not be tuned locally"], ciFast: true, full: false, external: false, forbidden: ["doNotTuneCropLineDeskewAgain", "doNotPromoteShadowOCR"], action: "stopLocalCropLineDeskewTuning"),
            workOrder("WO-v132-request-real-textboxes", title: "Request real TextBoxes", stage: "TextBoxes", artifact: "TextBoxes", sourceExecutionItems: ["EX-resolver-next-real-textboxes-needed"], sourceReports: ["externalArtifactReadinessReport", "nativeTextBoxProxyLedgerReport", "koharuPipelineResolverReport"], priority: "P0", status: textBoxStatus, budget: needsRealTextBoxBlocks.isEmpty ? "ciFastReportOnly" : "externalArtifactRequired", blocks: needsRealTextBoxBlocks, blockers: externalReady || needsRealTextBoxBlocks.isEmpty ? [] : ["real TextBoxes missing: \(externalVerdict)"], ciFast: true, full: false, external: !needsRealTextBoxBlocks.isEmpty, forbidden: ["doNotUseVisionOCRAsRealTextBoxes", "doNotUseGroundTruthForTextBoxRouting"], action: needsRealTextBoxBlocks.isEmpty ? "keepTextBoxRequestReportOnly" : "collectRealKoharuArtifact"),
            workOrder("WO-v132-request-real-bubblemask", title: "Request real BubbleMask", stage: "BubbleMask", artifact: "BubbleMask", sourceExecutionItems: ["EX-resolver-next-real-bubblemask-needed"], sourceReports: ["bubbleMaskAssignmentSplitScoreboardReport", "externalArtifactReadinessReport"], priority: "P1", status: bubbleStatus, budget: needsRealBubbleMaskBlocks.isEmpty ? "ciFastReportOnly" : "externalArtifactRequired", blocks: needsRealBubbleMaskBlocks, blockers: externalReady || needsRealBubbleMaskBlocks.isEmpty ? [] : ["real BubbleMask missing: \(externalVerdict)"], ciFast: true, full: false, external: !needsRealBubbleMaskBlocks.isEmpty, forbidden: ["doNotPromoteBubbleMaskProxyAsRealBubbleMask"], action: needsRealBubbleMaskBlocks.isEmpty ? "keepBubbleMaskProxyReportOnly" : "collectRealKoharuArtifact"),
            workOrder("WO-v132-request-real-segmentmask", title: "Request real SegmentMask", stage: "SegmentMask", artifact: "SegmentMask", sourceExecutionItems: ["EX-resolver-next-real-segmentmask-needed"], sourceReports: ["segmentMaskProxyCoverageScoreboardReport", "externalArtifactReadinessReport"], priority: "P1", status: segmentStatus, budget: needsRealSegmentMaskBlocks.isEmpty ? "ciFastReportOnly" : "externalArtifactRequired", blocks: needsRealSegmentMaskBlocks, blockers: externalReady || needsRealSegmentMaskBlocks.isEmpty ? [] : ["real SegmentMask missing: \(externalVerdict)"], ciFast: true, full: false, external: !needsRealSegmentMaskBlocks.isEmpty, forbidden: ["doNotPromoteGlyphMaskAsRealSegmentMask"], action: needsRealSegmentMaskBlocks.isEmpty ? "keepSegmentMaskProxyReportOnly" : "collectRealKoharuArtifact"),
            workOrder("WO-v132-keep-render-lock", title: "Keep render lock", stage: "FinalRender", artifact: "RenderedSprites/FinalRender", sourceExecutionItems: ["EX-resolver-render-lock-linked"], sourceReports: ["koharuRenderRegressionLockReport"], priority: renderIssueBlocks.isEmpty ? "P2" : "P0", status: renderStatus, budget: "ciFastReportOnly", blocks: renderIssueBlocks.isEmpty ? renderLockedBlocks : renderIssueBlocks, blockers: renderIssueBlocks.isEmpty ? [] : ["render issue blocks present"], ciFast: true, full: false, external: false, forbidden: ["doNotChangeOverlayRendererInRouter"], action: renderIssueBlocks.isEmpty ? "keepRenderLockReportOnly" : "inspectRenderLockGateLedger"),
            workOrder("WO-v132-translation-model-floor-handoff", title: "Translation model floor handoff", stage: "Translations", artifact: "Translations", sourceExecutionItems: ["EX-resolver-translation-floor-linked"], sourceReports: ["translationModelFloorComparisonReport", "cleanTextDiagnostic"], priority: modelFloorBlocks.isEmpty ? "P2" : "P0", status: modelStatus, budget: modelFloorBlocks.isEmpty ? "ciFastReportOnly" : "futureModelComparison", blocks: modelFloorBlocks, blockers: modelFloorBlocks.isEmpty ? [] : ["current model floor remains open"], ciFast: true, full: false, external: false, modelChange: !modelFloorBlocks.isEmpty, allowed: modelFloorBlocks.isEmpty, forbidden: ["doNotChangeModelOrPromptInRouter"], action: modelFloorBlocks.isEmpty ? "keepTranslationLedger" : "considerFutureModelComparison"),
            workOrder("WO-v132-external-artifact-package-handoff", title: "External artifact package handoff", stage: "ExternalArtifacts", artifact: "test/koharu_artifacts", sourceExecutionItems: ["EX-resolver-external-artifact-handoff"], sourceReports: ["externalArtifactReadinessReport"], priority: "P0", status: externalStatus, budget: "externalArtifactRequired", blocks: externalBlockedBlocks, blockers: externalReady ? [] : ["test/koharu_artifacts not ready: \(externalVerdict)"], ciFast: true, full: false, external: true, forbidden: ["doNotCreateCopyOrModifyActiveKoharuArtifacts", "doNotUseContractExamplesAsActiveArtifacts"], action: externalReady ? "keepExternalArtifactGateReady" : "collectRealKoharuArtifact"),
            workOrder("WO-v132-manual-review-unclassified", title: "Manual review unclassified", stage: "ManualReview", artifact: "ManualReview", sourceExecutionItems: [], sourceReports: ["blocks", "koharuWorkOrderRouterReport"], priority: manualReviewBlocks.isEmpty ? "P3" : "P1", status: manualReviewBlocks.isEmpty ? "closedReportOnly" : "manualReviewOnly", budget: manualReviewBlocks.isEmpty ? "ciFastReportOnly" : "manualReview", blocks: manualReviewBlocks, blockers: manualReviewBlocks.isEmpty ? [] : ["unclassified failure blocks need human review"], ciFast: true, full: false, external: false, forbidden: ["doNotHideUnclassifiedBlocks"], action: manualReviewBlocks.isEmpty ? "noManualReviewNeeded" : "manualReviewOnly")
        ]

        let ciFastRunnable = workOrders.filter { $0.canRunInCIFast && !$0.requiresExternalArtifact && $0.budgetClass != "futureModelComparison" }.map(\.workOrderID).sorted()
        let fullRequired = workOrders.filter(\.requiresFullProbe).map(\.workOrderID).sorted()
        let externalRequired = workOrders.filter(\.requiresExternalArtifact).map(\.workOrderID).sorted()
        let modelComparison = workOrders.filter { $0.budgetClass == "futureModelComparison" }.map(\.workOrderID).sorted()
        let stoplistWorkOrders = workOrders.filter { $0.budgetClass == "stoplistDoNotRun" }.map(\.workOrderID).sorted()
        let manualReviewWorkOrders = workOrders.filter { $0.budgetClass == "manualReview" }.map(\.workOrderID).sorted()
        let budgetLedger = MangaKoharuWorkOrderBudgetLedger(
            ciFastRunnableWorkOrderIDs: ciFastRunnable,
            fullProbeRequiredWorkOrderIDs: fullRequired,
            externalArtifactRequiredWorkOrderIDs: externalRequired,
            modelComparisonFutureWorkOrderIDs: modelComparison,
            stoplistWorkOrderIDs: stoplistWorkOrders,
            manualReviewWorkOrderIDs: manualReviewWorkOrders,
            ciFastRunnableBlockCount: uniqueSorted(blockRoutes.filter(\.canRunInCIFast).map(\.blockIndex)).count,
            externalArtifactBlockedBlockCount: externalBlockedBlocks.count,
            stoplistedBlockCount: stoplistBlocks.count,
            modelFloorLimitedBlockCount: modelFloorBlocks.count,
            renderLockedBlockCount: renderLockedBlocks.count,
            notes: [
                "ci-fast can validate router JSON/TXT consistency but cannot satisfy missing real external artifacts.",
                "stoplistDoNotRun records local crop/line/deskew paths that should not be tuned again.",
                "futureModelComparison records model floor handoff only; v1.32 does not change model or prompt."
            ]
        )

        let gateLedger = [
            gate("G-workorder-no-main-flow-mutation", name: "No main flow mutation", scope: "report", status: "passed", threshold: "wouldChangeMainFlow=false", affected: [], failureMeans: "router changes OCR, translation, overlay, blockPassed, failureCategory, cleanup, candidate selection, or rendering", action: "revertBehavioralChange", signals: [signal("wouldChangeMainFlow", "false", source: "koharuWorkOrderRouterReport")]),
            gate("G-workorder-no-ground-truth-decision", name: "No ground truth decision", scope: "report", status: "passed", threshold: "groundTruthUsedForDecision=false", affected: allBlockIndexes, failureMeans: "ground truth selects work order, priority, budget, or next action", action: "moveGroundTruthToEvaluationSignalsOnly", signals: [signal("groundTruthUsedForDecision", "false", source: "koharuWorkOrderRouterReport")]),
            gate("G-workorder-resolver-input-present", name: "Resolver input present", scope: "DAGResolver", status: resolverInputPresent ? "passed" : "warning", threshold: "koharuPipelineResolverReport.enabled=true", affected: allBlockIndexes, failureMeans: "router cannot derive execution queue and must degrade", action: "restoreKoharuPipelineResolverReport", signals: [signal("resolverInputPresent", String(resolverInputPresent), source: "koharuPipelineResolverReport")]),
            gate("G-workorder-block-route-count", name: "Block route count", scope: "blocks", status: blockRoutes.count == blocks.count ? "passed" : "warning", threshold: "blockRouteCount==totalBlocksDetected", affected: allBlockIndexes, failureMeans: "not every final block has a work order route", action: "restorePerBlockRoutes", signals: [signal("blockRouteCount", String(blockRoutes.count), source: "koharuWorkOrderRouterReport")]),
            gate("G-workorder-stoplist-respected", name: "Stoplist respected", scope: "TextBoxes", status: stoplistBlocks.isEmpty ? "passed" : "stop", threshold: "stoplist blocks route away from local crop/line/deskew tuning", affected: stoplistBlocks, failureMeans: "router reopens known failed local tuning", action: "stopLocalCropLineDeskewTuning", signals: [signal("stoplistedBlocks", joined(stoplistBlocks), source: "nativeTextBoxProxyLedgerReport,koharuPipelineResolverReport")]),
            gate("G-workorder-external-artifact-boundary", name: "External artifact boundary", scope: "ExternalArtifacts", status: externalReady ? "ready" : "blocked", threshold: "missing active artifacts stay blocked and are not faked by proxies", affected: externalBlockedBlocks, failureMeans: "router promotes proxy Vision/TextBox/BubbleMask/SegmentMask as real Koharu artifact", action: "collectRealKoharuArtifact", signals: [signal("readinessVerdict", externalVerdict, source: "externalArtifactReadinessReport")]),
            gate("G-workorder-model-floor-boundary", name: "Model floor boundary", scope: "Translations", status: modelFloorBlocks.isEmpty ? "passed" : "warning", threshold: "translation/model failures route to model floor handoff", affected: modelFloorBlocks, failureMeans: "model quality failure is misattributed to OCR geometry", action: "considerFutureModelComparison", signals: [signal("modelFloorLimitedBlocks", joined(modelFloorBlocks), source: "translationModelFloorComparisonReport")]),
            gate("G-workorder-render-lock-boundary", name: "Render lock boundary", scope: "FinalRender", status: renderIssueBlocks.isEmpty ? "passed" : "warning", threshold: "render stable blocks stay locked; render issues route only to render lock", affected: renderIssueBlocks, failureMeans: "router changes overlay renderer or treats render lock as OCR gain", action: renderIssueBlocks.isEmpty ? "keepRenderLockReportOnly" : "inspectRenderLockGateLedger", signals: [signal("renderIssueBlocks", joined(renderIssueBlocks), source: "koharuRenderRegressionLockReport")]),
            gate("G-workorder-ci-fast-budget", name: "CI fast budget", scope: "budget", status: ciFastRunnable.isEmpty ? "warning" : "passed", threshold: "at least one report-only work order can run in ci-fast", affected: allBlockIndexes, failureMeans: "router requires full/local tuning for every action", action: "restoreReportOnlyCIFastBudget", signals: [signal("ciFastRunnableWorkOrders", ciFastRunnable.joined(separator: ","), source: "koharuWorkOrderRouterReport.budgetLedger")]),
            gate("G-workorder-convergence-linked", name: "Convergence linked", scope: "convergence", status: "passed", threshold: "WI-koharu-workorder-router and G-koharu-workorder-router-executed are emitted in refreshed convergence", affected: allBlockIndexes, failureMeans: "v1.32 router is not traceable from convergence", action: "refreshConvergenceAfterRouter", signals: [signal("referenceReport", "koharuWorkOrderRouterReport", source: "koharuArtifactConvergenceReport")]
            )
        ]

        let routerVerdict: String
        if !resolverInputPresent {
            routerVerdict = "insufficientResolverInput"
        } else if !renderIssueBlocks.isEmpty {
            routerVerdict = "blockedByRenderIssue"
        } else if !modelFloorBlocks.isEmpty {
            routerVerdict = "blockedByModelFloor"
        } else if !externalBlockedBlocks.isEmpty {
            routerVerdict = stoplistBlocks.isEmpty ? "blockedByMissingRealArtifacts" : "stopLocalTuningAndWaitForArtifact"
        } else if !manualReviewBlocks.isEmpty {
            routerVerdict = "manualReviewOnly"
        } else {
            routerVerdict = "readyReportOnlyWorkOrders"
        }

        return MangaKoharuWorkOrderRouterReport(
            enabled: true,
            source: "AITRANSProbe",
            referencePipeline: "Koharu",
            referenceConcept: "ResolverExecutionQueue.WorkOrderRouter.BudgetGate",
            evaluatedBlockCount: blocks.count,
            workOrderCount: workOrders.count,
            blockRouteCount: blockRoutes.count,
            gateCount: gateLedger.count,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            externalArtifactsRequiredForThisReport: false,
            routerVerdict: routerVerdict,
            routerVerdictBreakdown: countBy([routerVerdict]),
            workOrderStatusBreakdown: countBy(workOrders.map(\.status)),
            workOrderPriorityBreakdown: countBy(workOrders.map(\.priority)),
            targetStageBreakdown: countBy(workOrders.map(\.targetStage)),
            nextActionBreakdown: countBy(blockRoutes.map(\.recommendedNextAction)),
            budgetClassBreakdown: countBy(workOrders.map(\.budgetClass)),
            blockedByMissingRealArtifactBlocks: externalBlockedBlocks,
            stoplistedLocalTuningBlocks: stoplistBlocks,
            modelFloorLimitedBlocks: modelFloorBlocks,
            renderLockedBlocks: renderLockedBlocks,
            manualReviewBlocks: manualReviewBlocks,
            ciFastRunnableWorkOrders: ciFastRunnable,
            fullProbeRequiredWorkOrders: fullRequired,
            externalArtifactRequiredWorkOrders: externalRequired,
            mustNotRunLocalTuningWorkOrders: stoplistWorkOrders,
            workOrders: workOrders,
            blockRoutes: blockRoutes,
            budgetLedger: budgetLedger,
            gateLedger: gateLedger,
            notes: [
                "koharuWorkOrderRouterReport derives report-only work orders from v1.31 resolver, convergence, model floor, render lock, external artifact gate, and final blocks.",
                "It does not add OCR or LLM calls and does not change OCR, translation prompt, model, overlay, blockPassed, failureCategory, cleanup, candidate selection, safe layout, glyph mask, or currentBlockSource.",
                "Ground truth appears only in evaluationSignals and never selects work order, priority, status, budget, gate, or next action.",
                "Missing test/koharu_artifacts remains an external artifact handoff; proxy Vision/TextBox/BubbleMask/SegmentMask evidence is not promoted as real Koharu artifact."
            ]
        )
    }

    private static func makeKoharuExternalArtifactRequestPacketReport(
        blocks: [MangaOverlayProbeBlock],
        diagnostics: MangaOverlayProbeDiagnostics,
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?,
        externalTextBoxShadowOCRReport: MangaOverlayExternalTextBoxShadowOCRReport?,
        nativeTextBoxProxyLedgerReport: MangaNativeTextBoxProxyLedgerReport?,
        bubbleMaskAssignmentSplitScoreboardReport: MangaBubbleMaskAssignmentSplitScoreboardReport?,
        segmentMaskProxyCoverageScoreboardReport: MangaSegmentMaskProxyCoverageScoreboardReport?,
        koharuArtifactConvergenceReport: MangaKoharuArtifactConvergenceReport?,
        koharuWorkOrderRouterReport: MangaKoharuWorkOrderRouterReport?,
        translationModelFloorComparisonReport: MangaTranslationModelFloorComparisonReport?,
        koharuRenderRegressionLockReport: MangaKoharuRenderRegressionLockReport?
    ) -> MangaKoharuExternalArtifactRequestPacketReport {
        func uniqueSorted(_ values: [Int]) -> [Int] {
            Array(Set(values)).sorted()
        }

        func sortedUniqueStrings(_ values: [String]) -> [String] {
            Array(Set(values)).sorted()
        }

        func joined(_ values: [Int]) -> String {
            uniqueSorted(values).map(String.init).joined(separator: ",")
        }

        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaKoharuExternalArtifactRequestSignal {
            MangaKoharuExternalArtifactRequestSignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }

        func gate(
            _ id: String,
            name: String,
            scope: String,
            status: String,
            threshold: String,
            affected: [Int],
            failureMeans: String,
            action: String,
            signals: [MangaKoharuExternalArtifactRequestSignal]
        ) -> MangaKoharuExternalArtifactRequestGate {
            MangaKoharuExternalArtifactRequestGate(
                gateID: id,
                gateName: name,
                scope: scope,
                status: status,
                threshold: threshold,
                affectedBlocks: uniqueSorted(affected),
                failureMeans: failureMeans,
                nextAction: action,
                decisionSignals: signals,
                groundTruthUsedForDecision: false
            )
        }

        let allBlockIndexes = blocks.map(\.index)
        let readiness = externalArtifactReadinessReport
        let routerInputPresent = koharuWorkOrderRouterReport?.enabled == true
        let readinessVerdict = readiness?.readinessVerdict ?? "manifestMissing"
        let activeArtifactsDirectory = readiness?.activeArtifactsDirectory ?? false
        let contractExampleOnly = readiness?.contractExampleOnly ?? false
        let shadowAllowed = readiness?.externalTextBoxesShadowOCRAllowed == true
        let shadowExecuted = externalTextBoxShadowOCRReport?.executed == true
        let manifestFound = readiness?.manifestFound ?? false
        let textBoxesFound = readiness?.textBoxesFound ?? false
        let bubbleMaskFound = readiness?.bubbleMaskFound ?? false
        let segmentMaskFound = readiness?.segmentMaskFound ?? false
        let parseErrors = readiness?.parseErrors ?? []

        let forbiddenActiveSources = [
            "md/koharu研究/artifact_contract/examples",
            "Vision OCR blocks",
            "preCropTextBoxPlanReport",
            "lineTextBoxPlanReport",
            "BubbleMask proxy",
            "SegmentMask proxy",
            "test/1.ground_truth.json",
            "handwritten ideal boxes"
        ]
        let validatorCommands = [
            "python3 scripts/validate-koharu-artifacts.py --root test/koharu_artifacts --print-required-files",
            "python3 scripts/validate-koharu-artifacts.py --root test/koharu_artifacts --allow-missing",
            "python3 scripts/validate-koharu-artifacts.py --root md/koharu研究/artifact_contract/examples/valid"
        ]

        func requiredFile(
            path: String,
            kind: String,
            present: Bool,
            fields: [String],
            optional: [String]
        ) -> MangaKoharuExternalArtifactRequiredFile {
            let parseStatus: String
            if !present {
                parseStatus = "missing"
            } else if parseErrors.isEmpty {
                parseStatus = "parsed"
            } else {
                parseStatus = "blockedInvalid"
            }
            let contractStatus: String
            if !present {
                contractStatus = "requiredMissing"
            } else if contractExampleOnly {
                contractStatus = "blockedExampleOnly"
            } else if parseErrors.isEmpty && readiness?.coordinateValidation.bboxValidationPassed != false {
                contractStatus = "requiredReady"
            } else {
                contractStatus = "blockedInvalid"
            }
            return MangaKoharuExternalArtifactRequiredFile(
                path: path,
                artifactKind: kind,
                required: true,
                present: present,
                parseStatus: parseStatus,
                contractStatus: contractStatus,
                requiredFields: fields,
                optionalFields: optional,
                coordinateSpace: "originalImageTopLeftPixels",
                expectedSourceImage: "test/1.png",
                currentBlocker: contractStatus == "requiredReady" ? nil : readinessVerdict,
                nextAction: contractStatus == "requiredReady" ? "runValidator" : "collectRealKoharuArtifact",
                validatorCommand: "python3 scripts/validate-koharu-artifacts.py --root test/koharu_artifacts --allow-missing",
                forbiddenSources: forbiddenActiveSources
            )
        }

        let requiredFiles = [
            requiredFile(
                path: "test/koharu_artifacts/1.manifest.json",
                kind: "Manifest",
                present: manifestFound,
                fields: ["schemaVersion", "sourceImage", "coordinateSpace", "contractExampleOnly", "textBoxesPath", "bubbleMaskPath", "segmentMaskPath"],
                optional: ["generatedBy", "generatedAt", "notes"]
            ),
            requiredFile(
                path: "test/koharu_artifacts/1.textboxes.json",
                kind: "TextBoxes",
                present: textBoxesFound,
                fields: ["id", "bbox"],
                optional: ["confidence", "detector", "linePolygons", "sourceDirection", "rotationDegrees", "detectedFontSizePx", "notes"]
            ),
            requiredFile(
                path: "test/koharu_artifacts/1.bubbles.json",
                kind: "BubbleMask",
                present: bubbleMaskFound,
                fields: ["id", "bbox"],
                optional: ["confidence", "pixelCount", "maskValue", "notes"]
            ),
            requiredFile(
                path: "test/koharu_artifacts/1.segment_mask.json",
                kind: "SegmentMask",
                present: segmentMaskFound,
                fields: ["sourcePath", "width", "height"],
                optional: ["glyphPixelCount", "connectedComponentCount", "notes"]
            )
        ]

        let routeByBlock = Dictionary(
            uniqueKeysWithValues: (koharuWorkOrderRouterReport?.blockRoutes ?? []).map { ($0.blockIndex, $0) }
        )
        let textBoxByBlock = Dictionary(
            uniqueKeysWithValues: (nativeTextBoxProxyLedgerReport?.blockLedgers ?? []).map { ($0.blockIndex, $0) }
        )
        let bubbleByBlock = Dictionary(
            uniqueKeysWithValues: (bubbleMaskAssignmentSplitScoreboardReport?.blockScorecards ?? []).map { ($0.blockIndex, $0) }
        )
        let segmentByBlock = Dictionary(
            uniqueKeysWithValues: (segmentMaskProxyCoverageScoreboardReport?.blockScorecards ?? []).map { ($0.blockIndex, $0) }
        )
        let convergenceByBlock = Dictionary(
            uniqueKeysWithValues: (koharuArtifactConvergenceReport?.blockPaths ?? []).map { ($0.blockIndex, $0) }
        )
        let floorByBlock = Dictionary(
            uniqueKeysWithValues: (translationModelFloorComparisonReport?.noisyBlockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let renderByBlock = Dictionary(
            uniqueKeysWithValues: (koharuRenderRegressionLockReport?.blockLocks ?? []).map { ($0.blockIndex, $0) }
        )
        let shadowSummaryByBlock = Dictionary(
            uniqueKeysWithValues: (externalTextBoxShadowOCRReport?.blockSummaries ?? []).map { ($0.blockIndex, $0) }
        )
        let alignmentByBlock = Dictionary(
            uniqueKeysWithValues: (readiness?.blockAlignment ?? []).map { ($0.blockIndex, $0) }
        )

        let textBoxBlocks = uniqueSorted((koharuWorkOrderRouterReport?.blockRoutes ?? []).filter(\.requiresRealTextBoxes).map(\.blockIndex))
        let bubbleBlocks = uniqueSorted((koharuWorkOrderRouterReport?.blockRoutes ?? []).filter(\.requiresRealBubbleMask).map(\.blockIndex))
        let segmentBlocks = uniqueSorted((koharuWorkOrderRouterReport?.blockRoutes ?? []).filter(\.requiresRealSegmentMask).map(\.blockIndex))
        let blockedByMissingRealArtifactBlocks = shadowAllowed ? [] : uniqueSorted(textBoxBlocks + bubbleBlocks + segmentBlocks)
        let readyForExternalShadowOCRBlocks = shadowAllowed ? allBlockIndexes : []
        let stoplistedLocalTuningBlocks = uniqueSorted(koharuWorkOrderRouterReport?.stoplistedLocalTuningBlocks ?? [])
        let modelFloorLimitedBlocks = uniqueSorted(koharuWorkOrderRouterReport?.modelFloorLimitedBlocks ?? [])
        let renderLockedBlocks = uniqueSorted(koharuWorkOrderRouterReport?.renderLockedBlocks ?? [])
        let manualReviewBlocks = uniqueSorted(koharuWorkOrderRouterReport?.manualReviewBlocks ?? [])

        func requirement(
            kind: String,
            filePath: String,
            targetBlocks: [Int],
            workOrders: [String],
            proxySignals: [MangaKoharuExternalArtifactRequestSignal],
            missingCapabilities: [String],
            requiredForShadow: Bool
        ) -> MangaKoharuExternalArtifactRequirement {
            let present = requiredFiles.first { $0.artifactKind == kind }?.present == true
            let status: String
            if !present {
                status = "requiredMissing"
            } else if contractExampleOnly {
                status = "blockedExampleOnly"
            } else if !parseErrors.isEmpty {
                status = "blockedInvalid"
            } else if shadowAllowed || !requiredForShadow {
                status = "readyForShadowOnlyUse"
            } else {
                status = "requiredReady"
            }
            return MangaKoharuExternalArtifactRequirement(
                artifactKind: kind,
                referenceKoharuArtifact: kind,
                requiredFilePath: filePath,
                requiredForShadowOCR: requiredForShadow,
                requiredForMainFlowPromotion: true,
                status: targetBlocks.isEmpty && !requiredForShadow ? "notRequiredForCurrentBlock" : status,
                targetBlocks: uniqueSorted(targetBlocks),
                sourceWorkOrderIDs: workOrders,
                sourceReports: ["koharuWorkOrderRouterReport", "externalArtifactReadinessReport", "koharuExternalArtifactRequestPacketReport"],
                schemaVersion: readiness?.coordinateValidation.coordinateSpace == nil ? "v1" : "v1",
                coordinateSpace: "originalImageTopLeftPixels",
                expectedImageWidth: 576,
                expectedImageHeight: 1280,
                requiredFields: requiredFiles.first { $0.artifactKind == kind }?.requiredFields ?? [],
                optionalFields: requiredFiles.first { $0.artifactKind == kind }?.optionalFields ?? [],
                acceptanceGates: [
                    "manifest sourceImage == test/1.png",
                    "coordinateSpace == originalImageTopLeftPixels",
                    "bbox values are inside 576x1280 image",
                    "contractExampleOnly == false",
                    "forbidden active sources absent"
                ],
                currentProxySignals: proxySignals,
                missingCapabilities: missingCapabilities,
                blockedReasons: status.hasPrefix("ready") ? [] : ["real \(kind) artifact not ready: \(readinessVerdict)", "proxyNotRealArtifact"],
                nextAction: status.hasPrefix("ready") ? "runExternalTextBoxShadowOCR" : "collectRealKoharuArtifact",
                groundTruthUsedForDecision: false,
                diagnosticOnly: true,
                wouldChangeMainFlow: false
            )
        }

        let artifactRequirements = [
            requirement(
                kind: "TextBoxes",
                filePath: "test/koharu_artifacts/1.textboxes.json",
                targetBlocks: textBoxBlocks,
                workOrders: ["WO-v132-request-real-textboxes", "WO-v132-external-artifact-package-handoff"],
                proxySignals: [
                    signal("proxyQualityStatusBreakdown", nativeTextBoxProxyLedgerReport?.qualityStatusBreakdown.map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ",") ?? "nil", source: "nativeTextBoxProxyLedgerReport"),
                    signal("stoplistBlocks", joined(stoplistedLocalTuningBlocks), source: "koharuWorkOrderRouterReport")
                ],
                missingCapabilities: ["real detector TextBoxes", "line polygons from detector", "confidence independent of Vision OCR/pre-crop/line plans"],
                requiredForShadow: true
            ),
            requirement(
                kind: "BubbleMask",
                filePath: "test/koharu_artifacts/1.bubbles.json",
                targetBlocks: bubbleBlocks,
                workOrders: ["WO-v132-request-real-bubblemask", "WO-v132-external-artifact-package-handoff"],
                proxySignals: [
                    signal("assignmentStatusBreakdown", bubbleMaskAssignmentSplitScoreboardReport?.assignmentStatusBreakdown.map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ",") ?? "nil", source: "bubbleMaskAssignmentSplitScoreboardReport"),
                    signal("needsRealBubbleMaskBlocks", joined(bubbleBlocks), source: "koharuWorkOrderRouterReport")
                ],
                missingCapabilities: ["real bubble instance IDs", "per-instance bbox", "mask values not derived from AITRANS proxy"],
                requiredForShadow: false
            ),
            requirement(
                kind: "SegmentMask",
                filePath: "test/koharu_artifacts/1.segment_mask.json",
                targetBlocks: segmentBlocks,
                workOrders: ["WO-v132-request-real-segmentmask", "WO-v132-external-artifact-package-handoff"],
                proxySignals: [
                    signal("coverageStatusBreakdown", segmentMaskProxyCoverageScoreboardReport?.coverageStatusBreakdown.map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ",") ?? "nil", source: "segmentMaskProxyCoverageScoreboardReport"),
                    signal("needsRealSegmentMaskBlocks", joined(segmentBlocks), source: "koharuWorkOrderRouterReport")
                ],
                missingCapabilities: ["real segment mask summary", "mask size matching 576x1280 source image", "mask not derived from glyph mask proxy"],
                requiredForShadow: false
            )
        ]

        let blockRequests = blocks.map { block -> MangaKoharuExternalArtifactBlockRequest in
            let route = routeByBlock[block.index]
            let textBox = textBoxByBlock[block.index]
            let bubble = bubbleByBlock[block.index]
            let segment = segmentByBlock[block.index]
            let convergence = convergenceByBlock[block.index]
            let floor = floorByBlock[block.index]
            let render = renderByBlock[block.index]
            let shadow = shadowSummaryByBlock[block.index]
            let alignment = alignmentByBlock[block.index]
            let needsTextBoxes = route?.requiresRealTextBoxes ?? (block.failureCategory == "ocrInputSuspect")
            let needsBubbleMask = route?.requiresRealBubbleMask ?? false
            let needsSegmentMask = route?.requiresRealSegmentMask ?? false
            let requiresExternal = route?.requiresExternalArtifact ?? (!shadowAllowed && (needsTextBoxes || needsBubbleMask || needsSegmentMask))
            let modelLimited = route?.modelFloorLimited ?? floor?.modelFloorLimited ?? false
            let renderLocked = route?.renderLocked ?? (render?.renderStatus == "renderLocked")
            let stoplisted = route?.stoplistedLocalTuning ?? textBox?.stoplistHit ?? false
            let primaryWorkOrder = route?.primaryWorkOrderID ?? "WO-v132-manual-review-unclassified"
            let nextAction: String
            if shadowAllowed && needsTextBoxes {
                nextAction = shadowExecuted ? "keepExternalShadowOCRReportOnly" : "runExternalTextBoxShadowOCR"
            } else if stoplisted {
                nextAction = "stopLocalCropLineDeskewTuning"
            } else if requiresExternal {
                nextAction = "collectRealKoharuArtifact"
            } else if modelLimited {
                nextAction = "manualReviewOnly"
            } else {
                nextAction = route?.recommendedNextAction ?? "keepReportOnlyBlocked"
            }
            var missingReasons: [String] = []
            if needsTextBoxes && !textBoxesFound { missingReasons.append("missing real TextBoxes") }
            if needsBubbleMask && !bubbleMaskFound { missingReasons.append("missing real BubbleMask") }
            if needsSegmentMask && !segmentMaskFound { missingReasons.append("missing real SegmentMask") }
            if !manifestFound { missingReasons.append("missing manifest") }
            if contractExampleOnly { missingReasons.append("contract example cannot be active artifact") }
            if !parseErrors.isEmpty { missingReasons.append("artifact parse/contract errors: \(parseErrors.joined(separator: ","))") }

            return MangaKoharuExternalArtifactBlockRequest(
                blockIndex: block.index,
                bbox: block.bbox,
                bubbleID: block.bubbleID,
                finalTextUsedForTranslation: block.finalTextUsedForTranslation,
                failureCategory: block.failureCategory,
                blockPassed: block.blockPassed,
                primaryWorkOrderID: primaryWorkOrder,
                primaryBottleneck: route?.primaryBottleneck ?? convergence?.primaryStructuralBottleneck ?? block.failureCategory,
                needsTextBoxes: needsTextBoxes,
                needsBubbleMask: needsBubbleMask,
                needsSegmentMask: needsSegmentMask,
                requiresExternalArtifact: requiresExternal,
                externalArtifactReadinessVerdict: readinessVerdict,
                externalTextBoxShadowOCRStatus: shadow?.promotionVerdict ?? externalTextBoxShadowOCRReport?.gateVerdict ?? "notExecuted",
                stoplistedLocalTuning: stoplisted,
                modelFloorLimited: modelLimited,
                renderLocked: renderLocked,
                manualReviewRequired: manualReviewBlocks.contains(block.index) || primaryWorkOrder == "WO-v132-manual-review-unclassified",
                currentProxyEvidence: [
                    signal("blockBBox", block.bbox.map { String(Int($0.rounded())) }.joined(separator: ","), source: "blocks"),
                    signal("bubbleID", block.bubbleID.map(String.init) ?? "nil", source: "blocks"),
                    signal("textBoxQualityStatus", textBox?.qualityStatus ?? "nil", source: "nativeTextBoxProxyLedgerReport"),
                    signal("textBoxFreezeReason", textBox?.primaryFreezeReason ?? "nil", source: "nativeTextBoxProxyLedgerReport"),
                    signal("bubbleAssignmentStatus", bubble?.assignmentStatus ?? "nil", source: "bubbleMaskAssignmentSplitScoreboardReport"),
                    signal("bubbleSplitRisk", bubble?.splitRisk ?? "nil", source: "bubbleMaskAssignmentSplitScoreboardReport"),
                    signal("segmentCoverageStatus", segment?.coverageStatus ?? "nil", source: "segmentMaskProxyCoverageScoreboardReport"),
                    signal("externalAlignmentVerdict", alignment?.alignmentVerdict ?? "notEvaluatedMissingArtifacts", source: "externalArtifactReadinessReport")
                ],
                missingRealArtifactReasons: sortedUniqueStrings(missingReasons),
                forbiddenLocalActions: sortedUniqueStrings(["doNotTuneCropLineDeskewAgain", "doNotPromoteShadowOCR", "doNotUseGroundTruthForArtifactRouting", "doNotGenerateActiveKoharuArtifacts"] + forbiddenActiveSources),
                nextAction: nextAction,
                decisionSignals: [
                    signal("primaryWorkOrderID", primaryWorkOrder, source: "koharuWorkOrderRouterReport"),
                    signal("requiresExternalArtifact", String(requiresExternal), source: "koharuWorkOrderRouterReport"),
                    signal("readinessVerdict", readinessVerdict, source: "externalArtifactReadinessReport"),
                    signal("externalTextBoxesShadowOCRAllowed", String(shadowAllowed), source: "externalArtifactReadinessReport")
                ],
                evaluationSignals: [
                    signal("groundTruthMatch", block.groundTruthMatch, source: "blocks.groundTruthMatch", decision: false, evaluation: true),
                    signal("bestGroundTruthType", block.bestGroundTruthType ?? "nil", source: "blocks.bestGroundTruthType", decision: false, evaluation: true),
                    signal("ocrSimilarityForEvaluation", block.ocrGroundTruthSimilarity?.formatted(.number.precision(.fractionLength(4))) ?? "nil", source: "blocks.ocrGroundTruthSimilarity", decision: false, evaluation: true),
                    signal("translationCandidateClassification", block.candidateClassification, source: "blocks.candidateClassification", decision: false, evaluation: true)
                ],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            )
        }.sorted { $0.blockIndex < $1.blockIndex }

        let requestPacketVerdict: String
        if !routerInputPresent {
            requestPacketVerdict = "insufficientRouterInput"
        } else if contractExampleOnly {
            requestPacketVerdict = "blockedContractExampleOnly"
        } else if !manifestFound {
            requestPacketVerdict = "blockedMissingManifest"
        } else if !(textBoxesFound && bubbleMaskFound && segmentMaskFound) {
            requestPacketVerdict = "blockedMissingRequiredFiles"
        } else if !parseErrors.isEmpty || readiness?.coordinateValidation.bboxValidationPassed == false {
            requestPacketVerdict = "blockedInvalidContract"
        } else if shadowExecuted {
            requestPacketVerdict = "externalShadowOCRExecuted"
        } else if shadowAllowed {
            requestPacketVerdict = "readyForExternalShadowOCR"
        } else {
            requestPacketVerdict = "waitingForRealExternalArtifacts"
        }

        let gateLedger = [
            gate("G-v133-report-only", name: "Report only", scope: "report", status: "passed", threshold: "wouldChangeMainFlow=false", affected: [], failureMeans: "request packet changes OCR, translation, overlay, blockPassed, failure classification, safe layout, glyph mask, or output PNG", action: "revertBehavioralChange", signals: [signal("wouldChangeMainFlow", "false", source: "koharuExternalArtifactRequestPacketReport")]),
            gate("G-v133-no-ground-truth-decision", name: "No ground truth decision", scope: "report", status: "passed", threshold: "groundTruthUsedForDecision=false", affected: allBlockIndexes, failureMeans: "ground truth changes request priority, artifact requirement, nextAction, or promotion", action: "moveGroundTruthToEvaluationSignalsOnly", signals: [signal("groundTruthUsedForDecision", "false", source: "koharuExternalArtifactRequestPacketReport")]),
            gate("G-v133-router-input-present", name: "Router input present", scope: "WorkOrderRouter", status: routerInputPresent ? "passed" : "warning", threshold: "koharuWorkOrderRouterReport.enabled=true", affected: allBlockIndexes, failureMeans: "request packet cannot inherit v1.32 work order routing", action: "restoreKoharuWorkOrderRouterReport", signals: [signal("routerInputPresent", String(routerInputPresent), source: "koharuWorkOrderRouterReport")]),
            gate("G-v133-required-files-enumerated", name: "Required files enumerated", scope: "ExternalArtifacts", status: requiredFiles.count >= 4 ? "passed" : "warning", threshold: "manifest/TextBoxes/BubbleMask/SegmentMask files listed", affected: allBlockIndexes, failureMeans: "external provider cannot know the active artifact package contract", action: "restoreRequiredFileLedger", signals: [signal("requiredFileCount", String(requiredFiles.count), source: "koharuExternalArtifactRequestPacketReport")]),
            gate("G-v133-active-examples-blocked", name: "Active examples blocked", scope: "ExternalArtifacts", status: contractExampleOnly ? "blocked" : "passed", threshold: "contractExampleOnly=false for active artifacts", affected: allBlockIndexes, failureMeans: "example fixtures are treated as real detector output", action: "removeContractExamplesFromActiveDirectory", signals: [signal("contractExampleOnly", String(contractExampleOnly), source: "externalArtifactReadinessReport")]),
            gate("G-v133-coordinate-space-fixed", name: "Coordinate space fixed", scope: "Contract", status: readiness?.coordinateValidation.coordinateSpace == nil ? "missing" : (readiness?.coordinateValidation.coordinateSpace == "originalImageTopLeftPixels" ? "passed" : "blocked"), threshold: "coordinateSpace == originalImageTopLeftPixels", affected: allBlockIndexes, failureMeans: "bbox alignment cannot be interpreted against test/1.png", action: "fixContractCoordinates", signals: [signal("coordinateSpace", readiness?.coordinateValidation.coordinateSpace ?? "nil", source: "externalArtifactReadinessReport")]),
            gate("G-v133-textboxes-real-artifact-required", name: "TextBoxes real artifact required", scope: "TextBoxes", status: textBoxesFound ? "ready" : "missing", threshold: "1.textboxes.json comes from real external detector", affected: textBoxBlocks, failureMeans: "Vision OCR, crop plans, line plans, ground truth, or handwritten boxes are promoted as real TextBoxes", action: "collectRealKoharuArtifact", signals: [signal("textBoxesFound", String(textBoxesFound), source: "externalArtifactReadinessReport")]),
            gate("G-v133-bubblemask-real-artifact-required", name: "BubbleMask real artifact required", scope: "BubbleMask", status: bubbleMaskFound ? "ready" : "missing", threshold: "1.bubbles.json contains real instance summary", affected: bubbleBlocks, failureMeans: "AITRANS BubbleMask proxy is promoted as real mask", action: "collectRealKoharuArtifact", signals: [signal("bubbleMaskFound", String(bubbleMaskFound), source: "externalArtifactReadinessReport")]),
            gate("G-v133-segmentmask-real-artifact-required", name: "SegmentMask real artifact required", scope: "SegmentMask", status: segmentMaskFound ? "ready" : "missing", threshold: "1.segment_mask.json matches 576x1280 source image", affected: segmentBlocks, failureMeans: "glyph mask/SegmentMask proxy is promoted as real SegmentMask", action: "collectRealKoharuArtifact", signals: [signal("segmentMaskFound", String(segmentMaskFound), source: "externalArtifactReadinessReport")]),
            gate("G-v133-block-request-count", name: "Block request count", scope: "blocks", status: blockRequests.count == blocks.count ? "passed" : "warning", threshold: "blockRequestCount==totalBlocksDetected", affected: allBlockIndexes, failureMeans: "some final OCR blocks lack external artifact request entries", action: "restorePerBlockRequestLedger", signals: [signal("blockRequestCount", String(blockRequests.count), source: "koharuExternalArtifactRequestPacketReport")]),
            gate("G-v133-stoplist-respected", name: "Stoplist respected", scope: "TextBoxes", status: stoplistedLocalTuningBlocks.isEmpty ? "passed" : "stop", threshold: "stoplisted blocks do not reopen crop/line/deskew tuning", affected: stoplistedLocalTuningBlocks, failureMeans: "known failed local tuning line is reopened instead of requesting real artifact", action: "stopLocalCropLineDeskewTuning", signals: [signal("stoplistedLocalTuningBlocks", joined(stoplistedLocalTuningBlocks), source: "koharuWorkOrderRouterReport")]),
            gate("G-v133-external-shadow-ocr-gated", name: "External shadow OCR gated", scope: "ExternalTextBoxShadowOCR", status: shadowAllowed ? "ready" : "blocked", threshold: "externalTextBoxesShadowOCRAllowed gates execution", affected: allBlockIndexes, failureMeans: "external shadow OCR runs without ready active artifact package", action: shadowAllowed ? "runExternalTextBoxShadowOCR" : "collectRealKoharuArtifact", signals: [signal("externalTextBoxesShadowOCRAllowed", String(shadowAllowed), source: "externalArtifactReadinessReport"), signal("shadowExecuted", String(shadowExecuted), source: "externalTextBoxShadowOCRReport")]),
            gate("G-v133-convergence-linked", name: "Convergence linked", scope: "convergence", status: "passed", threshold: "WI-koharu-external-artifact-request-packet and G-koharu-external-artifact-request-packet-executed emitted in refreshed convergence", affected: allBlockIndexes, failureMeans: "v1.33 request packet is not traceable from convergence", action: "refreshConvergenceAfterRequestPacket", signals: [signal("referenceReport", "koharuExternalArtifactRequestPacketReport", source: "koharuArtifactConvergenceReport")])
        ]

        return MangaKoharuExternalArtifactRequestPacketReport(
            enabled: true,
            source: "AITRANSProbe",
            referencePipeline: "Koharu",
            referenceConcept: "ExternalArtifacts.ContractReadiness.RequestPacket",
            evaluatedBlockCount: blocks.count,
            requiredFileCount: requiredFiles.count,
            artifactRequirementCount: artifactRequirements.count,
            blockRequestCount: blockRequests.count,
            gateCount: gateLedger.count,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            externalArtifactsRequiredForThisReport: false,
            requestPacketVerdict: requestPacketVerdict,
            requestPacketVerdictBreakdown: countBy([requestPacketVerdict]),
            readinessVerdict: readinessVerdict,
            activeArtifactsDirectory: activeArtifactsDirectory,
            contractExampleOnly: contractExampleOnly,
            externalTextBoxesShadowOCRAllowed: shadowAllowed,
            requiredFileStatusBreakdown: countBy(requiredFiles.map(\.contractStatus)),
            artifactRequirementStatusBreakdown: countBy(artifactRequirements.map(\.status)),
            targetArtifactBreakdown: countBy(artifactRequirements.map(\.artifactKind)),
            nextActionBreakdown: countBy(blockRequests.map(\.nextAction)),
            blockedByMissingRealArtifactBlocks: blockedByMissingRealArtifactBlocks,
            readyForExternalShadowOCRBlocks: readyForExternalShadowOCRBlocks,
            stoplistedLocalTuningBlocks: stoplistedLocalTuningBlocks,
            modelFloorLimitedBlocks: modelFloorLimitedBlocks,
            renderLockedBlocks: renderLockedBlocks,
            manualReviewBlocks: manualReviewBlocks,
            requiredFiles: requiredFiles,
            artifactRequirements: artifactRequirements,
            blockRequests: blockRequests,
            gateLedger: gateLedger,
            validatorCommands: validatorCommands,
            forbiddenActiveSources: forbiddenActiveSources,
            notes: [
                "koharuExternalArtifactRequestPacketReport is the v1.33 report-only handoff from v1.32 work orders to a real Koharu external artifact package.",
                "It does not create, copy, modify, or validate by inventing active test/koharu_artifacts files.",
                "Proxy TextBoxes/BubbleMask/SegmentMask evidence is only why-needed context and never promoted as real detector output.",
                "Ground truth is recorded only in evaluationSignals and never decides requirements, gates, nextAction, or promotion."
            ]
        )
    }

    private static func makeKoharuNativeAlgorithmReplayMatrixReport(
        blocks: [MangaOverlayProbeBlock],
        diagnostics: MangaOverlayProbeDiagnostics,
        frameworkComparison: MangaOverlayFrameworkComparison?,
        fusionComparison: MangaOverlayFusionComparison?,
        textRegionCropReport: MangaOverlayTextRegionCropReport?,
        textBoxPlanFailureReport: MangaOverlayTextBoxPlanFailureReport?,
        lineCropExperimentReport: MangaOverlayLineCropExperimentReport?,
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?,
        nativeTextBoxProxyLedgerReport: MangaNativeTextBoxProxyLedgerReport?,
        bubbleMaskAssignmentSplitScoreboardReport: MangaBubbleMaskAssignmentSplitScoreboardReport?,
        segmentMaskProxyCoverageScoreboardReport: MangaSegmentMaskProxyCoverageScoreboardReport?,
        koharuArtifactConvergenceReport: MangaKoharuArtifactConvergenceReport?,
        koharuPipelineResolverReport: MangaKoharuPipelineResolverReport?,
        koharuWorkOrderRouterReport: MangaKoharuWorkOrderRouterReport?,
        koharuExternalArtifactRequestPacketReport: MangaKoharuExternalArtifactRequestPacketReport?,
        translationModelFloorComparisonReport: MangaTranslationModelFloorComparisonReport?,
        koharuRenderRegressionLockReport: MangaKoharuRenderRegressionLockReport?
    ) -> MangaKoharuNativeAlgorithmReplayMatrixReport {
        func uniqueSorted(_ values: [Int]) -> [Int] { Array(Set(values)).sorted() }
        func joined(_ values: [Int]) -> String { uniqueSorted(values).map(String.init).joined(separator: ",") }
        func countBy(_ values: [String]) -> [String: Int] { values.reduce(into: [:]) { $0[$1, default: 0] += 1 } }
        func signal(_ name: String, _ value: String, source: String, decision: Bool = true, evaluation: Bool = false) -> MangaKoharuNativeReplaySignal {
            MangaKoharuNativeReplaySignal(name: name, value: value, sourceReport: source, groundTruthFreeDecisionSignal: decision, groundTruthUsedForEvaluationOnly: evaluation)
        }

        let allBlocks = blocks.map(\.index)
        let failedBlocks = blocks.filter { !$0.blockPassed }.map(\.index)
        let ocrBlocks = uniqueSorted(translationModelFloorComparisonReport?.noisyOCRSuspectBlocks ?? diagnostics.likelyOCRIssueBlocks)
        let modelBlocks = uniqueSorted(translationModelFloorComparisonReport?.noisyModelFloorBlocks ?? blocks.filter { $0.failureCategory == "modelOutputFailure" || $0.failureCategory == "translationLanguageQualityFailure" }.map(\.index))
        let stopBlocks = uniqueSorted((koharuWorkOrderRouterReport?.stoplistedLocalTuningBlocks ?? []) + (nativeTextBoxProxyLedgerReport?.stoplistBlocks ?? []) + (textBoxPlanFailureReport?.stopRecommendedBlocks ?? []) + (lineCropExperimentReport?.stoppedAfterLineResearchBlocks ?? []))
        let externalBlocks = uniqueSorted((koharuExternalArtifactRequestPacketReport?.blockedByMissingRealArtifactBlocks ?? []) + (koharuWorkOrderRouterReport?.blockedByMissingRealArtifactBlocks ?? []) + (koharuArtifactConvergenceReport?.needsRealArtifactBlocks ?? []))
        let bubbleBlocks = uniqueSorted((bubbleMaskAssignmentSplitScoreboardReport?.conflictBlocks ?? []) + (bubbleMaskAssignmentSplitScoreboardReport?.splitRiskBlocks ?? []) + (bubbleMaskAssignmentSplitScoreboardReport?.sameBubbleSiblingBlocks ?? []))
        let segmentBlocks = uniqueSorted((segmentMaskProxyCoverageScoreboardReport?.usableForCleanupBlocks ?? []) + (segmentMaskProxyCoverageScoreboardReport?.weakSegmentBlocks ?? []) + (segmentMaskProxyCoverageScoreboardReport?.needsRealSegmentMaskBlocks ?? []))
        let renderIssues = uniqueSorted(koharuRenderRegressionLockReport?.renderIssueBlocks ?? diagnostics.renderCollisionUnresolvedBlocks + diagnostics.renderTextTruncatedBlocks)
        let renderLocked = uniqueSorted(koharuRenderRegressionLockReport?.blockLocks.filter { $0.renderStatus == "renderLocked" }.map(\.blockIndex) ?? koharuWorkOrderRouterReport?.renderLockedBlocks ?? [])
        let manualBlocks = uniqueSorted((koharuWorkOrderRouterReport?.manualReviewBlocks ?? []) + (nativeTextBoxProxyLedgerReport?.manualReviewBlocks ?? []))
        let readiness = externalArtifactReadinessReport?.readinessVerdict ?? "manifestMissing"
        let resolverPresent = koharuPipelineResolverReport?.enabled == true
        let routerPresent = koharuWorkOrderRouterReport?.enabled == true
        let requestPresent = koharuExternalArtifactRequestPacketReport?.enabled == true
        let convergencePresent = koharuArtifactConvergenceReport?.enabled == true
        let mustNot = ["doNotChangeMainOCR", "doNotChangeFinalTextUsedForTranslation", "doNotChangeTranslationPrompt", "doNotChangeBlockPassed", "doNotChangeFailureCategory", "doNotChangeOverlayRenderer", "doNotCreateActiveKoharuArtifacts"]

        func candidate(_ id: String, _ type: String, _ title: String, _ status: String, _ stage: String, _ blocks: [Int], _ reports: [String], _ impact: [String], _ budget: String, _ gateStatus: String, _ blockers: [String], _ action: String, control: [MangaKoharuNativeReplaySignal], evidence: [MangaKoharuNativeReplaySignal], risk: [String] = []) -> MangaKoharuNativeReplayCandidate {
            MangaKoharuNativeReplayCandidate(
                candidateID: id,
                candidateType: type,
                title: title,
                status: status,
                targetStage: stage,
                targetBlocks: uniqueSorted(blocks),
                sourceReports: reports,
                controlEvidence: control,
                candidateEvidence: evidence,
                expectedMetricImpact: impact,
                risk: risk,
                budgetClass: budget,
                promotionGate: ["noMainFlowMutation", "groundTruthFreeGate", "proxyBoundaryRespected"],
                promotionGateStatus: gateStatus,
                blockers: Array(Set(blockers)).sorted(),
                nextAction: action,
                mustNotChange: mustNot,
                decisionSignals: [signal("status", status, source: "koharuNativeAlgorithmReplayMatrixReport"), signal("budgetClass", budget, source: "koharuNativeAlgorithmReplayMatrixReport")],
                evaluationSignals: [signal("targetBlockCount", String(uniqueSorted(blocks).count), source: "blocks", decision: false, evaluation: true)],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            )
        }

        let candidates = [
            candidate("C-v134-preserve-fused-mainflow-audit", "fusionCleanupAudit", "Preserve fused whole-page and bubble-first mainflow audit", "nativeExecutableNow", "OcrText", allBlocks, ["frameworkComparison", "fusionComparison", "fusionResults"], ["ocrSimilarityPotential", "noMainMetricImpactReportOnly"], "ciFastReportOnly", "passed", [], "keepFusedMainflowAndAuditOnly", control: [signal("currentBlockSource", "fusedWholePageBubble", source: "configuration")], evidence: [signal("fusionConsistency", String(fusionComparison?.consistencyPassed ?? false), source: "fusionComparison"), signal("frameworkConsistency", String(frameworkComparison?.consistencyPassed ?? false), source: "frameworkComparison")]),
            candidate("C-v134-stop-local-crop-line-deskew", "nativeTextBoxProxyReplay", "Respect local crop line deskew stoplist", "stoplisted", "TextBoxes", stopBlocks, ["textBoxPlanFailureReport", "lineCropExperimentReport", "nativeTextBoxProxyLedgerReport"], ["externalReadinessClarity", "noMainMetricImpactReportOnly"], "ciFastReportOnly", stopBlocks.isEmpty ? "warning" : "stop", stopBlocks.isEmpty ? ["stoplist inputs empty"] : ["local crop/line/deskew tuning is frozen"], "stopLocalCropLineDeskewTuning", control: [signal("textRegionAdoptedCount", String(textRegionCropReport?.adoptedCount ?? 0), source: "textRegionCropReport")], evidence: [signal("stoplistedBlocks", joined(stopBlocks), source: "koharuWorkOrderRouterReport,nativeTextBoxProxyLedgerReport")], risk: ["reopeningKnownFailedLocalTuning"]),
            candidate("C-v134-textbox-proxy-replay-ledger", "nativeTextBoxProxyReplay", "Native TextBox proxy replay ledger", stopBlocks.isEmpty ? "shadowOnly" : "stoplisted", "TextBoxes", uniqueSorted(ocrBlocks + stopBlocks), ["nativeTextBoxProxyLedgerReport", "koharuWorkOrderRouterReport"], ["ocrSimilarityPotential", "externalReadinessClarity"], "ciFastReportOnly", nativeTextBoxProxyLedgerReport == nil ? "warning" : "passed", nativeTextBoxProxyLedgerReport == nil ? ["nativeTextBoxProxyLedgerReport missing"] : ["proxyNotRealTextBoxes"], stopBlocks.isEmpty ? "keepTextBoxProxyReplayShadowOnly" : "stopLocalCropLineDeskewTuning", control: [signal("qualityStatusBreakdown", nativeTextBoxProxyLedgerReport?.qualityStatusBreakdown.map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ",") ?? "nil", source: "nativeTextBoxProxyLedgerReport")], evidence: [signal("shadowOnlyEligibleBlocks", joined(nativeTextBoxProxyLedgerReport?.shadowOnlyEligibleBlocks ?? []), source: "nativeTextBoxProxyLedgerReport")], risk: ["proxyNotRealTextBoxes"]),
            candidate("C-v134-bubblemask-assignment-split-replay", "bubbleAssignmentSplitReplay", "BubbleMask assignment split sibling replay", "shadowOnly", "BubbleMask", bubbleBlocks, ["bubbleMaskAssignmentSplitScoreboardReport"], ["bubbleAssignmentClarity", "splitRiskReduction"], "ciFastReportOnly", bubbleMaskAssignmentSplitScoreboardReport == nil ? "warning" : "passed", bubbleMaskAssignmentSplitScoreboardReport == nil ? ["bubbleMaskAssignmentSplitScoreboardReport missing"] : ["real BubbleMask required before promotion"], "keepBubbleMaskReplayReportOnly", control: [signal("assignmentStatusBreakdown", bubbleMaskAssignmentSplitScoreboardReport?.assignmentStatusBreakdown.map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ",") ?? "nil", source: "bubbleMaskAssignmentSplitScoreboardReport")], evidence: [signal("splitRiskBlocks", joined(bubbleMaskAssignmentSplitScoreboardReport?.splitRiskBlocks ?? []), source: "bubbleMaskAssignmentSplitScoreboardReport")], risk: ["proxyNotRealBubbleMask"]),
            candidate("C-v134-segmentmask-coverage-replay", "segmentMaskCoverageReplay", "SegmentMask proxy coverage cleanup replay", "shadowOnly", "SegmentMask", segmentBlocks, ["segmentMaskProxyCoverageScoreboardReport"], ["renderRegressionProtection", "externalReadinessClarity"], "ciFastReportOnly", segmentMaskProxyCoverageScoreboardReport == nil ? "warning" : "passed", segmentMaskProxyCoverageScoreboardReport == nil ? ["segmentMaskProxyCoverageScoreboardReport missing"] : ["real SegmentMask required before promotion"], "keepSegmentMaskReplayReportOnly", control: [signal("glyphMaskBlocks", String(segmentMaskProxyCoverageScoreboardReport?.glyphMaskBlockCount ?? diagnostics.glyphMaskBlocks), source: "segmentMaskProxyCoverageScoreboardReport,diagnostics")], evidence: [signal("coverageStatusBreakdown", segmentMaskProxyCoverageScoreboardReport?.coverageStatusBreakdown.map { "\($0.key)=\($0.value)" }.sorted().joined(separator: ",") ?? "nil", source: "segmentMaskProxyCoverageScoreboardReport")], risk: ["proxyNotRealSegmentMask"]),
            candidate("C-v134-ocr-quality-bottleneck-replay", "ocrTextQualityReplay", "OCR quality bottleneck route replay", externalBlocks.isEmpty ? "shadowOnly" : "externalArtifactBlocked", "OcrText", ocrBlocks, ["diagnostics", "translationModelFloorComparisonReport", "koharuExternalArtifactRequestPacketReport"], ["ocrSimilarityPotential", "translationFailureAttribution"], externalBlocks.isEmpty ? "ciFastReportOnly" : "externalArtifactRequired", externalBlocks.isEmpty ? "passed" : "blocked", externalBlocks.isEmpty ? [] : ["real TextBoxes/BubbleMask/SegmentMask missing"], externalBlocks.isEmpty ? "keepOCRBottleneckReplayReportOnly" : "collectRealKoharuArtifact", control: [signal("likelyOCRIssueBlocks", joined(diagnostics.likelyOCRIssueBlocks), source: "diagnostics")], evidence: [signal("noisyOCRSuspectBlocks", joined(translationModelFloorComparisonReport?.noisyOCRSuspectBlocks ?? []), source: "translationModelFloorComparisonReport")], risk: ["groundTruthEvaluationOnly"]),
            candidate("C-v134-translation-floor-replay", "translationFloorReplay", "Translation model floor handoff replay", "modelFloorBlocked", "Translations", modelBlocks, ["cleanTextDiagnostic", "translationModelFloorComparisonReport"], ["translationFailureAttribution"], "modelComparisonRequired", translationModelFloorComparisonReport == nil ? "warning" : "passed", ["current Gemma 270M floor remains model-limited"], "keepModelFloorSeparatedFromOCR", control: [signal("cleanTextPassRate", translationModelFloorComparisonReport.map { $0.baselinePassRate.formatted(.number.precision(.fractionLength(4))) } ?? "nil", source: "translationModelFloorComparisonReport")], evidence: [signal("floorVerdict", translationModelFloorComparisonReport?.floorVerdict ?? "nil", source: "translationModelFloorComparisonReport")], risk: ["modelChangeOutOfScope"]),
            candidate("C-v134-render-lock-replay", "renderRegressionReplay", "Render regression lock replay", renderIssues.isEmpty ? "renderLocked" : "manualReviewOnly", "FinalRender", renderIssues.isEmpty ? renderLocked : renderIssues, ["koharuRenderRegressionLockReport", "outputFiles"], ["renderRegressionProtection"], "ciFastReportOnly", koharuRenderRegressionLockReport == nil ? "warning" : (renderIssues.isEmpty ? "passed" : "warning"), renderIssues.isEmpty ? [] : ["render issue blocks present: \(joined(renderIssues))"], renderIssues.isEmpty ? "keepRenderLocked" : "inspectRenderLockGateLedger", control: [signal("coreOutputFilesPresent", String(koharuRenderRegressionLockReport?.coreOutputFilesPresent ?? false), source: "koharuRenderRegressionLockReport")], evidence: [signal("coreOutputFilesNonEmpty", String(koharuRenderRegressionLockReport?.coreOutputFilesNonEmpty ?? false), source: "koharuRenderRegressionLockReport")], risk: ["pixelProofOutOfScope"]),
            candidate("C-v134-external-artifact-handoff-replay", "externalArtifactHandoffReplay", "External artifact blocked handoff replay", requestPresent && readiness == "readyForShadowOCR" ? "shadowOnly" : "externalArtifactBlocked", "ExternalArtifacts", externalBlocks.isEmpty ? allBlocks : externalBlocks, ["externalArtifactReadinessReport", "koharuExternalArtifactRequestPacketReport"], ["externalReadinessClarity"], "externalArtifactRequired", requestPresent ? "blocked" : "warning", requestPresent ? ["active test/koharu_artifacts not ready: \(readiness)"] : ["koharuExternalArtifactRequestPacketReport missing"], requestPresent ? "collectRealKoharuArtifact" : "restoreExternalArtifactRequestPacketReport", control: [signal("readinessVerdict", readiness, source: "externalArtifactReadinessReport")], evidence: [signal("requiredFileCount", String(koharuExternalArtifactRequestPacketReport?.requiredFileCount ?? 0), source: "koharuExternalArtifactRequestPacketReport")], risk: ["activeArtifactMustRemainMissingUntilProvided"])
        ]
        let candidateByID = Dictionary(uniqueKeysWithValues: candidates.map { ($0.candidateID, $0) })

        func stage(_ name: String, _ artifact: String, _ current: String, _ status: String, _ ids: [String], _ affected: [Int], _ metric: String, _ value: String, _ direction: String, _ reports: [String], _ blocked: [String], _ action: String) -> MangaKoharuNativeReplayStage {
            MangaKoharuNativeReplayStage(stageName: name, referenceKoharuArtifact: artifact, aitransCurrentEvidence: current, sourceReports: reports, status: status, candidateIDs: ids, affectedBlocks: uniqueSorted(affected), primaryMetric: metric, currentMetricValue: value, desiredDirection: direction, decisionSignals: [signal("stageStatus", status, source: "koharuNativeAlgorithmReplayMatrixReport")], evaluationSignals: [signal("affectedBlockCount", String(uniqueSorted(affected).count), source: "blocks", decision: false, evaluation: true)], blockedReasons: Array(Set(blocked)).sorted(), nextAction: action, groundTruthUsedForDecision: false, wouldChangeMainFlow: false, diagnosticOnly: true)
        }
        let stages = [
            stage("SourceImage", "SourceImage", "test/1.png bundle input", "nativeExecutableNow", ["C-v134-preserve-fused-mainflow-audit"], allBlocks, "sourceImageAvailable", "true", "keepStable", ["configuration"], [], "keepSourceImageStable"),
            stage("ContentCrop", "ContentCrop", "fixed content crop and 2x preprocessing", "nativeExecutableNow", ["C-v134-preserve-fused-mainflow-audit"], allBlocks, "browserUIExcluded", "reportOnly", "keepStable", ["configuration", "frameworkComparison"], [], "keepContentCropAuditOnly"),
            stage("TextBoxes", "TextBoxes", "TextBox proxy/crop/line/deskew ledgers", stopBlocks.isEmpty ? "shadowOnly" : "stoplisted", ["C-v134-stop-local-crop-line-deskew", "C-v134-textbox-proxy-replay-ledger"], uniqueSorted(ocrBlocks + stopBlocks), "stoplistBlocks", String(stopBlocks.count), "doNotReopenLocalTuning", ["nativeTextBoxProxyLedgerReport", "textBoxPlanFailureReport", "lineCropExperimentReport"], stopBlocks.isEmpty ? [] : ["crop/line/deskew local tuning stoplisted"], stopBlocks.isEmpty ? "keepTextBoxReplayShadowOnly" : "stopLocalCropLineDeskewTuning"),
            stage("BubbleMask", "BubbleMask", "BubbleMask proxy assignment/split/sibling layout scoreboard", "shadowOnly", ["C-v134-bubblemask-assignment-split-replay"], bubbleBlocks, "assignmentConflictBlocks", String(bubbleMaskAssignmentSplitScoreboardReport?.conflictBlocks.count ?? 0), "increaseAssignmentClarity", ["bubbleMaskAssignmentSplitScoreboardReport"], ["proxyNotRealBubbleMask"], "keepBubbleMaskReplayReportOnly"),
            stage("SegmentMask", "SegmentMask", "glyph mask and SegmentMask proxy coverage scoreboard", "shadowOnly", ["C-v134-segmentmask-coverage-replay"], segmentBlocks, "glyphMaskBlocks", String(segmentMaskProxyCoverageScoreboardReport?.glyphMaskBlockCount ?? diagnostics.glyphMaskBlocks), "protectCleanupBoundary", ["segmentMaskProxyCoverageScoreboardReport"], ["proxyNotRealSegmentMask"], "keepSegmentMaskReplayReportOnly"),
            stage("OcrText", "OcrText", "fused whole-page and bubble-first OCR blocks", externalBlocks.isEmpty ? "shadowOnly" : "externalArtifactBlocked", ["C-v134-preserve-fused-mainflow-audit", "C-v134-ocr-quality-bottleneck-replay"], ocrBlocks, "averageCoreDialogueOCRSimilarity", diagnostics.averageCoreDialogueOCRSimilarity.formatted(.number.precision(.fractionLength(4))), "evaluationOnlyIncrease", ["diagnostics", "translationModelFloorComparisonReport"], externalBlocks.isEmpty ? [] : ["real external TextBoxes/BubbleMask/SegmentMask missing"], externalBlocks.isEmpty ? "keepOCRReplayReportOnly" : "collectRealKoharuArtifact"),
            stage("Translations", "Translations", "clean text diagnostic and translation model floor comparison", "modelFloorBlocked", ["C-v134-translation-floor-replay"], modelBlocks, "cleanTextPassRate", translationModelFloorComparisonReport.map { $0.baselinePassRate.formatted(.number.precision(.fractionLength(4))) } ?? "nil", "separateModelFloorFromOCR", ["cleanTextDiagnostic", "translationModelFloorComparisonReport"], ["model comparison or prompt promotion is out of scope for v1.34"], "keepModelFloorSeparatedFromOCR"),
            stage("RenderedSprites", "RenderedSprites", "AITRANS overlay renderer plus render lock proxy", renderIssues.isEmpty ? "renderLocked" : "manualReviewOnly", ["C-v134-render-lock-replay"], renderIssues.isEmpty ? renderLocked : renderIssues, "renderIssueBlocks", String(renderIssues.count), "keepLocked", ["koharuRenderRegressionLockReport"], renderIssues.isEmpty ? [] : ["render issues require inspection"], renderIssues.isEmpty ? "keepRenderLocked" : "inspectRenderLockGateLedger"),
            stage("FinalRender", "FinalRender", "debug boxes and translated overlay PNG output files", koharuRenderRegressionLockReport?.coreOutputFilesNonEmpty == true ? "renderLocked" : "manualReviewOnly", ["C-v134-render-lock-replay"], failedBlocks, "coreOutputFilesNonEmpty", String(koharuRenderRegressionLockReport?.coreOutputFilesNonEmpty ?? false), "keepCoreOutputsPresent", ["koharuRenderRegressionLockReport", "outputFiles"], koharuRenderRegressionLockReport?.coreOutputFilesNonEmpty == true ? [] : ["core output file check missing or failed"], koharuRenderRegressionLockReport?.coreOutputFilesNonEmpty == true ? "keepFinalRenderLocked" : "inspectOutputFileChecks"),
            stage("ExternalArtifacts", "ExternalArtifacts", "v1.33 request packet for real TextBoxes/BubbleMask/SegmentMask", readiness == "readyForShadowOCR" ? "shadowOnly" : "externalArtifactBlocked", ["C-v134-external-artifact-handoff-replay"], externalBlocks.isEmpty ? allBlocks : externalBlocks, "readinessVerdict", readiness, "waitForRealArtifact", ["externalArtifactReadinessReport", "koharuExternalArtifactRequestPacketReport"], readiness == "readyForShadowOCR" ? [] : ["active test/koharu_artifacts missing or blocked"], readiness == "readyForShadowOCR" ? "runExternalTextBoxShadowOCR" : "collectRealKoharuArtifact")
        ]

        let routerByBlock = Dictionary(uniqueKeysWithValues: (koharuWorkOrderRouterReport?.blockRoutes ?? []).map { ($0.blockIndex, $0) })
        let requestByBlock = Dictionary(uniqueKeysWithValues: (koharuExternalArtifactRequestPacketReport?.blockRequests ?? []).map { ($0.blockIndex, $0) })
        let convergenceByBlock = Dictionary(uniqueKeysWithValues: (koharuArtifactConvergenceReport?.blockPaths ?? []).map { ($0.blockIndex, $0) })
        let floorByBlock = Dictionary(uniqueKeysWithValues: (translationModelFloorComparisonReport?.noisyBlockSummaries ?? []).map { ($0.blockIndex, $0) })
        let renderByBlock = Dictionary(uniqueKeysWithValues: (koharuRenderRegressionLockReport?.blockLocks ?? []).map { ($0.blockIndex, $0) })
        let blockRoutes = blocks.map { block -> MangaKoharuNativeReplayBlockRoute in
            let router = routerByBlock[block.index]
            let request = requestByBlock[block.index]
            let convergence = convergenceByBlock[block.index]
            let floor = floorByBlock[block.index]
            let render = renderByBlock[block.index]
            let modelLimited = router?.modelFloorLimited ?? floor?.modelFloorLimited ?? modelBlocks.contains(block.index)
            let stoplisted = router?.stoplistedLocalTuning ?? stopBlocks.contains(block.index)
            let requiresExternal = request?.requiresExternalArtifact ?? router?.requiresExternalArtifact ?? externalBlocks.contains(block.index)
            let renderStatusLocked = render.map { $0.renderStatus == "renderLocked" }
            let isRenderLocked = router?.renderLocked ?? renderStatusLocked ?? renderLocked.contains(block.index)
            let primary: (candidate: String, stage: String, action: String)
            if modelLimited || block.failureCategory == "modelOutputFailure" || block.failureCategory == "translationLanguageQualityFailure" {
                primary = ("C-v134-translation-floor-replay", "Translations", "keepModelFloorSeparatedFromOCR")
            } else if stoplisted {
                primary = ("C-v134-stop-local-crop-line-deskew", "TextBoxes", "stopLocalCropLineDeskewTuning")
            } else if requiresExternal {
                primary = ("C-v134-external-artifact-handoff-replay", "ExternalArtifacts", "collectRealKoharuArtifact")
            } else if isRenderLocked {
                primary = ("C-v134-render-lock-replay", "FinalRender", "keepRenderLocked")
            } else if block.failureCategory == "ocrInputSuspect" {
                primary = ("C-v134-ocr-quality-bottleneck-replay", "OcrText", "keepOCRBottleneckReplayReportOnly")
            } else {
                primary = ("C-v134-preserve-fused-mainflow-audit", "OcrText", "keepFusedMainflowAndAuditOnly")
            }
            let secondary = candidates.filter { $0.candidateID != primary.candidate && $0.targetBlocks.contains(block.index) }.map(\.candidateID)
            return MangaKoharuNativeReplayBlockRoute(
                blockIndex: block.index,
                bubbleID: block.bubbleID,
                bbox: block.bbox,
                blockPassed: block.blockPassed,
                failureCategory: block.failureCategory,
                groundTruthMatch: block.groundTruthMatch,
                bestGroundTruthType: block.bestGroundTruthType,
                ocrSimilarityForEvaluation: block.ocrGroundTruthSimilarity,
                primaryReplayCandidateID: primary.candidate,
                secondaryReplayCandidateIDs: secondary,
                primaryKoharuStage: primary.stage,
                primaryBottleneck: router?.primaryBottleneck ?? convergence?.primaryStructuralBottleneck ?? floor?.primaryBottleneckFromConvergence ?? block.failureCategory,
                nativeReplayAllowed: candidateByID[primary.candidate]?.status == "nativeExecutableNow",
                shadowOnlyAllowed: candidateByID[primary.candidate]?.status == "shadowOnly",
                requiresExternalArtifact: requiresExternal,
                modelFloorLimited: modelLimited,
                renderLocked: isRenderLocked,
                stoplistedLocalTuning: stoplisted,
                manualReviewRequired: manualBlocks.contains(block.index) || renderIssues.contains(block.index),
                nextAction: primary.action,
                decisionSignals: [signal("primaryReplayCandidateID", primary.candidate, source: "koharuNativeAlgorithmReplayMatrixReport"), signal("routerPrimaryWorkOrderID", router?.primaryWorkOrderID ?? "nil", source: "koharuWorkOrderRouterReport")],
                evaluationSignals: [signal("ocrSimilarityForEvaluation", block.ocrGroundTruthSimilarity.map { $0.formatted(.number.precision(.fractionLength(4))) } ?? "nil", source: "blocks", decision: false, evaluation: true), signal("bestGroundTruthType", block.bestGroundTruthType ?? "nil", source: "blocks", decision: false, evaluation: true)],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            )
        }

        func gate(_ id: String, _ name: String, _ scope: String, _ status: String, _ threshold: String, _ affected: [Int], _ failure: String, _ action: String, _ signals: [MangaKoharuNativeReplaySignal]) -> MangaKoharuNativeReplayGate {
            MangaKoharuNativeReplayGate(gateID: id, name: name, scope: scope, status: status, threshold: threshold, affectedBlocks: uniqueSorted(affected), failureMeans: failure, nextAction: action, decisionSignals: signals, groundTruthUsedForDecision: false)
        }
        let gateLedger = [
            gate("G-v134-report-only", "Report only", "report", "passed", "wouldChangeMainFlow=false", [], "replay matrix changes main behavior", "revertBehavioralChange", [signal("wouldChangeMainFlow", "false", source: "koharuNativeAlgorithmReplayMatrixReport")]),
            gate("G-v134-no-ground-truth-decision", "No ground truth decision", "report", "passed", "groundTruthUsedForDecision=false", allBlocks, "ground truth changes candidate, route, gate, or nextAction", "moveGroundTruthToEvaluationSignalsOnly", [signal("groundTruthUsedForDecision", "false", source: "koharuNativeAlgorithmReplayMatrixReport")]),
            gate("G-v134-resolver-input-present", "Resolver input present", "PipelineResolver", resolverPresent ? "passed" : "warning", "koharuPipelineResolverReport.enabled=true", allBlocks, "v1.31 DAG evidence missing", "restoreKoharuPipelineResolverReport", [signal("resolverInputPresent", String(resolverPresent), source: "koharuPipelineResolverReport")]),
            gate("G-v134-router-input-present", "Router input present", "WorkOrderRouter", routerPresent ? "passed" : "warning", "koharuWorkOrderRouterReport.enabled=true", allBlocks, "v1.32 router evidence missing", "restoreKoharuWorkOrderRouterReport", [signal("routerInputPresent", String(routerPresent), source: "koharuWorkOrderRouterReport")]),
            gate("G-v134-request-packet-input-present", "Request packet input present", "ExternalArtifacts", requestPresent ? "passed" : "warning", "koharuExternalArtifactRequestPacketReport.enabled=true", allBlocks, "v1.33 request packet missing", "restoreKoharuExternalArtifactRequestPacketReport", [signal("requestPacketInputPresent", String(requestPresent), source: "koharuExternalArtifactRequestPacketReport")]),
            gate("G-v134-convergence-input-present", "Convergence input present", "Convergence", convergencePresent ? "passed" : "warning", "koharuArtifactConvergenceReport.enabled=true", allBlocks, "convergence input missing", "restoreKoharuArtifactConvergenceReport", [signal("convergenceInputPresent", String(convergencePresent), source: "koharuArtifactConvergenceReport")]),
            gate("G-v134-candidate-count", "Candidate count", "candidates", candidates.count >= 9 ? "passed" : "warning", "candidateCount>=9", allBlocks, "fixed replay candidate queue incomplete", "restoreFixedCandidateQueue", [signal("candidateCount", String(candidates.count), source: "koharuNativeAlgorithmReplayMatrixReport")]),
            gate("G-v134-block-route-count", "Block route count", "blocks", blockRoutes.count == blocks.count ? "passed" : "warning", "blockRouteCount==totalBlocksDetected", allBlocks, "some final blocks lack replay routes", "restorePerBlockReplayRoutes", [signal("blockRouteCount", String(blockRoutes.count), source: "koharuNativeAlgorithmReplayMatrixReport")]),
            gate("G-v134-stoplist-respected", "Stoplist respected", "TextBoxes", stopBlocks.isEmpty ? "passed" : "stop", "crop/line/deskew stoplist remains closed", stopBlocks, "known failed local tuning reopened", "stopLocalCropLineDeskewTuning", [signal("stoplistedBlocks", joined(stopBlocks), source: "nativeTextBoxProxyLedgerReport,koharuWorkOrderRouterReport")]),
            gate("G-v134-proxy-boundary-respected", "Proxy boundary respected", "proxyBoundary", "passed", "proxy is not real Koharu artifact", uniqueSorted(stopBlocks + bubbleBlocks + segmentBlocks), "proxy promoted as real Koharu artifact", "keepProxyBoundaryOrCollectRealArtifact", [signal("proxyNotRealSegmentMask", "true", source: "segmentMaskProxyCoverageScoreboardReport")]),
            gate("G-v134-translation-floor-separated", "Translation floor separated", "Translations", translationModelFloorComparisonReport == nil ? "warning" : "passed", "model floor blocks route to Translations", modelBlocks, "model floor blamed on OCR/TextBoxes", "keepModelFloorSeparatedFromOCR", [signal("modelFloorBlocks", joined(modelBlocks), source: "translationModelFloorComparisonReport")]),
            gate("G-v134-render-lock-respected", "Render lock respected", "FinalRender", koharuRenderRegressionLockReport == nil ? "warning" : "passed", "render lock report present and renderer unchanged", renderIssues.isEmpty ? renderLocked : renderIssues, "renderer changed or output file ledger ignored", "keepRenderLockReportOnly", [signal("renderLockVerdict", koharuRenderRegressionLockReport?.renderLockVerdict ?? "nil", source: "koharuRenderRegressionLockReport")]),
            gate("G-v134-external-artifact-gated", "External artifact gated", "ExternalArtifacts", readiness == "readyForShadowOCR" ? "ready" : "blocked", "missing active artifacts stay blocked until provided", externalBlocks, "missing external artifact treated as ready or fabricated", readiness == "readyForShadowOCR" ? "runExternalTextBoxShadowOCR" : "collectRealKoharuArtifact", [signal("readinessVerdict", readiness, source: "externalArtifactReadinessReport")]),
            gate("G-v134-convergence-linked", "Convergence linked", "Convergence", "passed", "refreshed convergence references v1.34 report", allBlocks, "v1.34 work item missing from convergence", "refreshConvergenceAfterReplayMatrix", [signal("referenceReport", "koharuNativeAlgorithmReplayMatrixReport", source: "koharuArtifactConvergenceReport")])
        ]

        let matrixVerdict: String
        if !resolverPresent {
            matrixVerdict = "blockedByMissingResolverInputs"
        } else if !requestPresent {
            matrixVerdict = "blockedByMissingRequestPacket"
        } else if !convergencePresent {
            matrixVerdict = "blockedByMissingConvergence"
        } else if !externalBlocks.isEmpty && modelBlocks.count < externalBlocks.count {
            matrixVerdict = "externalArtifactBlocked"
        } else if modelBlocks.count >= max(1, failedBlocks.count / 2) {
            matrixVerdict = "modelFloorDominant"
        } else {
            matrixVerdict = "reportOnlyReplayMatrixReady"
        }
        return MangaKoharuNativeAlgorithmReplayMatrixReport(
            enabled: true,
            source: "AITRANSProbe",
            referencePipeline: "Koharu",
            referenceConcept: "NativeAlgorithmReplayMatrix.ProbeEvidenceBudgetGate",
            evaluatedBlockCount: blocks.count,
            stageCount: stages.count,
            candidateCount: candidates.count,
            blockRouteCount: blockRoutes.count,
            gateCount: gateLedger.count,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            externalArtifactsRequiredForThisReport: false,
            matrixVerdict: matrixVerdict,
            matrixVerdictBreakdown: [matrixVerdict: 1],
            stageStatusBreakdown: countBy(stages.map(\.status)),
            candidateTypeBreakdown: countBy(candidates.map(\.candidateType)),
            candidateStatusBreakdown: countBy(candidates.map(\.status)),
            budgetClassBreakdown: countBy(candidates.map(\.budgetClass)),
            promotionGateBreakdown: countBy(candidates.map(\.promotionGateStatus)),
            nextActionBreakdown: countBy(blockRoutes.map(\.nextAction)),
            nativeExecutableNowCandidates: candidates.filter { $0.status == "nativeExecutableNow" }.map(\.candidateID),
            shadowOnlyCandidates: candidates.filter { $0.status == "shadowOnly" }.map(\.candidateID),
            stoplistedCandidates: candidates.filter { $0.status == "stoplisted" }.map(\.candidateID),
            externalArtifactBlockedCandidates: candidates.filter { $0.status == "externalArtifactBlocked" }.map(\.candidateID),
            modelFloorBlockedCandidates: candidates.filter { $0.status == "modelFloorBlocked" }.map(\.candidateID),
            renderLockedCandidates: candidates.filter { $0.status == "renderLocked" }.map(\.candidateID),
            stages: stages,
            candidates: candidates,
            blockRoutes: blockRoutes,
            gateLedger: gateLedger,
            notes: [
                "koharuNativeAlgorithmReplayMatrixReport is report-only and aggregates existing AITRANS probe evidence into a Koharu-style local replay matrix.",
                "Candidate status, budget, promotion gates, nextAction, and block routes use ground-truth-free signals only; OCR similarity and ground truth type remain evaluationSignals.",
                "The report does not add OCR or LLM calls and does not change OCR, translation input, blockPassed, failureCategory, overlay rendering, safe layout, cleanup, candidate selection, active artifacts, currentBlockSource, or metrics history."
            ]
        )
    }

    private static func makeKoharuBubbleIndexShadowLedgerReport(
        blocks: [MangaOverlayProbeBlock],
        bubbleMaskReport: MangaOverlayBubbleMaskReport?,
        bubbleAssignmentCorrectionReport: MangaOverlayBubbleAssignmentCorrectionReport?,
        bubbleSplitCandidateReport: MangaOverlayBubbleSplitCandidateReport?,
        readingOrderStructureAuditReport: MangaReadingOrderStructureAuditReport?,
        bubbleMaskAssignmentSplitScoreboardReport: MangaBubbleMaskAssignmentSplitScoreboardReport?,
        koharuRenderRegressionLockReport: MangaKoharuRenderRegressionLockReport?,
        koharuNativeAlgorithmReplayMatrixReport: MangaKoharuNativeAlgorithmReplayMatrixReport?
    ) -> MangaKoharuBubbleIndexShadowLedgerReport {
        func uniqueSorted(_ values: [Int]) -> [Int] { Array(Set(values)).sorted() }
        func joined(_ values: [Int]) -> String { uniqueSorted(values).map(String.init).joined(separator: ",") }
        func countBy(_ values: [String]) -> [String: Int] { values.reduce(into: [:]) { $0[$1, default: 0] += 1 } }
        func signal(_ name: String, _ value: String, source: String, decision: Bool = true, evaluation: Bool = false) -> MangaKoharuBubbleIndexSignal {
            MangaKoharuBubbleIndexSignal(name: name, value: value, sourceReport: source, groundTruthFreeDecisionSignal: decision, groundTruthUsedForEvaluationOnly: evaluation)
        }

        func rectIoU(_ lhs: [Double]?, _ rhs: [Double]?) -> Double? {
            guard let lhs, let rhs else { return nil }
            let lhsRect = rect(from: lhs)
            let rhsRect = rect(from: rhs)
            guard area(of: lhsRect) > 0, area(of: rhsRect) > 0 else { return nil }
            let intersection = lhsRect.intersection(rhsRect)
            let intersectionArea = area(of: intersection)
            let unionArea = area(of: lhsRect) + area(of: rhsRect) - intersectionArea
            guard unionArea > 0 else { return nil }
            return intersectionArea / unionArea
        }

        func overlapRatio(_ lhs: [Double], _ rhs: [Double]) -> Double {
            let lhsRect = rect(from: lhs)
            let rhsRect = rect(from: rhs)
            guard area(of: lhsRect) > 0, area(of: rhsRect) > 0 else { return 0 }
            let intersection = lhsRect.intersection(rhsRect)
            return area(of: intersection) / max(min(area(of: lhsRect), area(of: rhsRect)), 1)
        }

        func maxOverlap(_ rects: [[Double]]) -> Double {
            guard rects.count > 1 else { return 0 }
            var result = 0.0
            for lhsIndex in 0..<rects.count {
                for rhsIndex in (lhsIndex + 1)..<rects.count {
                    result = max(result, overlapRatio(rects[lhsIndex], rects[rhsIndex]))
                }
            }
            return result
        }

        let allBlocks = blocks.map(\.index)
        let maskByBlock = Dictionary(uniqueKeysWithValues: (bubbleMaskReport?.blockDiagnostics ?? []).map { ($0.blockIndex, $0) })
        let correctionByBlock = Dictionary(uniqueKeysWithValues: (bubbleAssignmentCorrectionReport?.diagnostics ?? []).map { ($0.blockIndex, $0) })
        let readingByBlock = Dictionary(uniqueKeysWithValues: (readingOrderStructureAuditReport?.cases ?? []).map { ($0.blockIndex, $0) })
        let scoreboardByBlock = Dictionary(uniqueKeysWithValues: (bubbleMaskAssignmentSplitScoreboardReport?.blockScorecards ?? []).map { ($0.blockIndex, $0) })
        let renderByBlock = Dictionary(uniqueKeysWithValues: (koharuRenderRegressionLockReport?.blockLocks ?? []).map { ($0.blockIndex, $0) })
        let replayByBlock = Dictionary(uniqueKeysWithValues: (koharuNativeAlgorithmReplayMatrixReport?.blockRoutes ?? []).map { ($0.blockIndex, $0) })
        let splitCandidates = bubbleSplitCandidateReport?.diagnostics ?? []
        let splitCandidatesByBlock = Dictionary(grouping: splitCandidates.flatMap { candidate in
            candidate.seedBlockIndexes.map { (blockIndex: $0, candidate: candidate) }
        }) { $0.blockIndex }

        let groupedByBubble = Dictionary(grouping: blocks) { block in
            block.bubbleID
        }
        let siblingGroups = groupedByBubble.compactMap { bubbleID, group -> (bubbleID: Int, blocks: [MangaOverlayProbeBlock])? in
            guard let bubbleID, group.count > 1 else { return nil }
            return (bubbleID, group.sorted { $0.index < $1.index })
        }.sorted { $0.bubbleID < $1.bubbleID }

        func siblingIndexes(for block: MangaOverlayProbeBlock) -> [Int] {
            guard let bubbleID = block.bubbleID else { return [] }
            return (groupedByBubble[bubbleID] ?? [])
                .map(\.index)
                .filter { $0 != block.index }
                .sorted()
        }

        func assignmentVerdict(block: MangaOverlayProbeBlock, mask: MangaOverlayBubbleMaskBlockDiagnostic?, correction: MangaOverlayBubbleAssignmentCorrectionDiagnostic?, scoreboard: MangaBubbleMaskAssignmentSplitBlockScorecard?) -> String {
            let normalized = block.finalTextUsedForTranslation.lowercased()
            if normalized.contains("city battler") || normalized.contains("offline") || normalized.contains("tournament") {
                return "decorativeTitleNoCorrection"
            }
            if normalized.contains("let") && normalized.contains("battler") {
                return "protectedTextNoCorrection"
            }
            if block.bubbleID == nil { return "unassignedNeedsManualReview" }
            if scoreboard?.splitRisk == "splitReviewNeeded" || scoreboard?.splitRisk == "splitCandidatePresent" {
                return "splitCandidateNeedsReview"
            }
            if correction?.correctionRecommended == true || mask?.bubbleIDConsistent == false {
                return "dominantProxyBubbleConflict"
            }
            if let mask, mask.maskDominantBubbleID == block.bubbleID, mask.maskDominantCoverageRatio >= 0.70 {
                return "dominantProxyBubbleAgrees"
            }
            if mask == nil || bubbleMaskReport == nil {
                return "needsRealBubbleMask"
            }
            return "stableCurrentBubbleID"
        }

        func safeAreaVerdict(block: MangaOverlayProbeBlock, shadowRect: [Double]?, iou: Double?, render: MangaKoharuRenderBlockLock?) -> String {
            if render?.renderStatus == "textTruncated" || render?.renderStatus == "maskOverflowUnresolved" || render?.renderStatus == "renderCollisionUnresolved" {
                return "renderLockOwnsDecision"
            }
            if block.safeLayoutRect == nil { return "safeAreaMissing" }
            if shadowRect == nil {
                return bubbleMaskReport == nil ? "needsRealBubbleMask" : "maskSafeRectMissing"
            }
            if let iou, iou < 0.72 {
                return "shadowSafeAreaDiffersReportOnly"
            }
            if block.safeLayoutSource?.hasPrefix("maskSafe") == true {
                return "currentSafeAreaStable"
            }
            return "shadowSafeAreaComparable"
        }

        func siblingVerdict(block: MangaOverlayProbeBlock, siblings: [Int], splitIDs: [Int], render: MangaKoharuRenderBlockLock?) -> String {
            if siblings.isEmpty { return "singleBlockBubble" }
            if render?.renderStatus == "textTruncated" || render?.renderStatus == "maskOverflowUnresolved" {
                return "manualReviewOnly"
            }
            if !splitIDs.isEmpty { return "splitCandidatePresent" }
            if bubbleMaskReport == nil { return "needsRealBubbleMask" }
            let groupRects = (groupedByBubble[block.bubbleID] ?? []).compactMap(\.safeLayoutRect)
            if maxOverlap(groupRects) >= 0.18 {
                return "partitionOverlapRisk"
            }
            return "partitionStable"
        }

        func nextAction(assignment: String, safeArea: String, sibling: String, render: String) -> String {
            if render == "renderIssueOpen" || safeArea == "renderLockOwnsDecision" { return "inspectRenderLockGateLedger" }
            if assignment == "dominantProxyBubbleConflict" || assignment == "splitCandidateNeedsReview" || sibling == "splitCandidatePresent" { return "reviewBubbleIndexAssignmentAndSplit" }
            if assignment == "needsRealBubbleMask" || safeArea == "needsRealBubbleMask" || sibling == "needsRealBubbleMask" { return "collectRealBubbleMaskArtifact" }
            if assignment == "unassignedNeedsManualReview" || sibling == "manualReviewOnly" { return "manualReviewOnly" }
            if safeArea == "shadowSafeAreaDiffersReportOnly" || sibling == "partitionOverlapRisk" { return "keepBubbleIndexShadowLedgerReportOnly" }
            return "keepBubbleIndexLedgerReportOnly"
        }

        var blockLedgers: [MangaKoharuBubbleIndexBlockLedger] = []
        blockLedgers.reserveCapacity(blocks.count)
        for block in blocks {
            let mask = maskByBlock[block.index]
            let correction = correctionByBlock[block.index]
            let scoreboard = scoreboardByBlock[block.index]
            let render = renderByBlock[block.index]
            let replay = replayByBlock[block.index]
            let splitIDs = uniqueSorted((splitCandidatesByBlock[block.index] ?? []).map { $0.candidate.id })
            let shadowBubbleID = mask?.maskDominantBubbleID ?? scoreboard?.maskDominantBubbleID
            let shadowBubbleSource = mask?.maskDominantBubbleID != nil ? "bubbleMaskReport.majoritySeed" : (scoreboard?.maskDominantBubbleID != nil ? "bubbleMaskAssignmentSplitScoreboardReport" : "unassigned")
            let shadowSafeRect = mask?.maskSafeRect ?? block.maskSafeRect ?? render?.maskSafeRect
            let safeIoU = rectIoU(block.safeLayoutRect, shadowSafeRect)
            let siblings = siblingIndexes(for: block)
            let assignment = assignmentVerdict(block: block, mask: mask, correction: correction, scoreboard: scoreboard)
            let safeArea = safeAreaVerdict(block: block, shadowRect: shadowSafeRect, iou: safeIoU, render: render)
            let sibling = siblingVerdict(block: block, siblings: siblings, splitIDs: splitIDs, render: render)
            let renderVerdict = render?.renderStatus == "textTruncated" || render?.renderStatus == "maskOverflowUnresolved" || render?.renderStatus == "renderCollisionUnresolved"
                ? "renderIssueOpen"
                : "renderLocked"
            let action = nextAction(assignment: assignment, safeArea: safeArea, sibling: sibling, render: renderVerdict)
            let shadowSafeLayoutSource = shadowSafeRect == nil ? "missing" : "bubbleMaskReport.maskSafeRect"
            let siblingPartitionID = block.bubbleID.map { "BI-\($0)" }
            let primaryBottleneck = replay?.primaryBottleneck ?? scoreboard?.primaryBubbleBottleneck ?? block.failureCategory
            let assignmentSignals: [MangaKoharuBubbleIndexSignal] = [
                signal("currentBubbleID", block.bubbleID.map(String.init) ?? "nil", source: "blocks.bubbleID"),
                signal("maskDominantBubbleID", shadowBubbleID.map(String.init) ?? "nil", source: shadowBubbleSource),
                signal("correctionRecommended", String(correction?.correctionRecommended ?? false), source: "bubbleAssignmentCorrectionReport")
            ]
            let safeAreaSignals: [MangaKoharuBubbleIndexSignal] = [
                signal("currentSafeLayoutSource", block.safeLayoutSource ?? "nil", source: "blocks.safeLayoutSource"),
                signal("currentVsShadowSafeRectIoU", safeIoU?.formatted(.number.precision(.fractionLength(4))) ?? "nil", source: "koharuBubbleIndexShadowLedgerReport"),
                signal("renderStatus", render?.renderStatus ?? "nil", source: "koharuRenderRegressionLockReport")
            ]
            let decisionSignals: [MangaKoharuBubbleIndexSignal] = [
                signal("assignmentVerdict", assignment, source: "koharuBubbleIndexShadowLedgerReport"),
                signal("safeAreaVerdict", safeArea, source: "koharuBubbleIndexShadowLedgerReport"),
                signal("siblingPartitionVerdict", sibling, source: "koharuBubbleIndexShadowLedgerReport"),
                signal("nextAction", action, source: "koharuBubbleIndexShadowLedgerReport")
            ]
            let ocrSimilaritySignalValue = block.ocrGroundTruthSimilarity?.formatted(.number.precision(.fractionLength(4))) ?? "nil"
            let evaluationSignals: [MangaKoharuBubbleIndexSignal] = [
                signal("groundTruthMatch", block.groundTruthMatch, source: "blocks.groundTruthMatch", decision: false, evaluation: true),
                signal("bestGroundTruthType", block.bestGroundTruthType ?? "nil", source: "blocks.bestGroundTruthType", decision: false, evaluation: true),
                signal("ocrSimilarityForEvaluation", ocrSimilaritySignalValue, source: "blocks.ocrGroundTruthSimilarity", decision: false, evaluation: true)
            ]
            blockLedgers.append(
                MangaKoharuBubbleIndexBlockLedger(
                    blockIndex: block.index,
                    bubbleID: block.bubbleID,
                    bbox: block.bbox,
                    blockPassed: block.blockPassed,
                    failureCategory: block.failureCategory,
                    groundTruthMatch: block.groundTruthMatch,
                    bestGroundTruthType: block.bestGroundTruthType,
                    ocrSimilarityForEvaluation: block.ocrGroundTruthSimilarity,
                    currentSafeLayoutRect: block.safeLayoutRect,
                    currentSafeLayoutSource: block.safeLayoutSource,
                    shadowBubbleID: shadowBubbleID,
                    shadowBubbleSource: shadowBubbleSource,
                    shadowAssignmentConfidence: mask?.maskDominantCoverageRatio ?? scoreboard?.maskDominantCoverageRatio,
                    assignmentVerdict: assignment,
                    assignmentSignals: assignmentSignals,
                    shadowSafeLayoutRect: shadowSafeRect,
                    shadowSafeLayoutSource: shadowSafeLayoutSource,
                    currentVsShadowSafeRectIoU: safeIoU,
                    safeAreaVerdict: safeArea,
                    safeAreaSignals: safeAreaSignals,
                    siblingBubbleID: block.bubbleID,
                    siblingBlockIndexes: siblings,
                    siblingPartitionID: siblingPartitionID,
                    siblingPartitionVerdict: sibling,
                    splitCandidateIDs: splitIDs,
                    renderLockVerdict: renderVerdict,
                    primaryBottleneck: primaryBottleneck,
                    nextAction: action,
                    decisionSignals: decisionSignals,
                    evaluationSignals: evaluationSignals,
                    groundTruthUsedForDecision: false,
                    wouldChangeMainFlow: false,
                    diagnosticOnly: true
                )
            )
        }

        let blockLedgerByIndex = Dictionary(uniqueKeysWithValues: blockLedgers.map { ($0.blockIndex, $0) })
        let siblingLedgers: [MangaKoharuBubbleIndexSiblingLedger] = siblingGroups.map { group in
            let blockIndexes = group.blocks.map(\.index)
            let currentRects = group.blocks.compactMap(\.safeLayoutRect)
            let shadowRects = group.blocks.compactMap { blockLedgerByIndex[$0.index]?.shadowSafeLayoutRect ?? $0.safeLayoutRect }
            let splitIDs = uniqueSorted(blockIndexes.flatMap { blockIndex in
                (splitCandidatesByBlock[blockIndex] ?? []).map { $0.candidate.id }
            })
            let readingIndexes = group.blocks.map { readingByBlock[$0.index]?.proposedReadingOrderIndex ?? $0.index }
            let currentOverlap = maxOverlap(currentRects)
            let shadowOverlap = maxOverlap(shadowRects)
            let renderIssue = group.blocks.contains { block in
                let status = renderByBlock[block.index]?.renderStatus
                return status == "textTruncated" || status == "maskOverflowUnresolved" || status == "renderCollisionUnresolved"
            }
            let verdict: String
            if renderIssue {
                verdict = "manualReviewOnly"
            } else if !splitIDs.isEmpty {
                verdict = "splitCandidatePresent"
            } else if bubbleMaskReport == nil {
                verdict = "needsRealBubbleMask"
            } else if currentOverlap >= 0.18 || shadowOverlap >= 0.18 {
                verdict = "partitionOverlapRisk"
            } else {
                verdict = "partitionStable"
            }
            let action = verdict == "partitionStable" ? "keepSiblingPartitionReportOnly" : (verdict == "needsRealBubbleMask" ? "collectRealBubbleMaskArtifact" : "reviewBubbleIndexSiblingPartition")
            return MangaKoharuBubbleIndexSiblingLedger(
                siblingGroupID: "BI-\(group.bubbleID)",
                bubbleID: group.bubbleID,
                blockIndexes: blockIndexes,
                readingOrderIndexes: readingIndexes,
                currentSafeLayoutRects: currentRects,
                shadowPartitionRects: shadowRects,
                maxCurrentSafeRectOverlapRatio: currentOverlap,
                maxShadowPartitionOverlapRatio: shadowOverlap,
                partitionVerdict: verdict,
                splitCandidateIDs: splitIDs,
                renderLockVerdict: renderIssue ? "renderIssueOpen" : "renderLocked",
                nextAction: action,
                decisionSignals: [
                    signal("maxCurrentSafeRectOverlapRatio", currentOverlap.formatted(.number.precision(.fractionLength(4))), source: "blocks.safeLayoutRect"),
                    signal("splitCandidateIDs", splitIDs.map(String.init).joined(separator: ","), source: "bubbleSplitCandidateReport")
                ],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            )
        }

        let siblingGroupIDsByBubble = Dictionary(grouping: siblingLedgers, by: \.bubbleID).mapValues { ledgers in
            ledgers.map(\.siblingGroupID).sorted()
        }
        let bubbleLedgers: [MangaKoharuBubbleIndexBubbleLedger] = (bubbleMaskReport?.instances ?? []).map { instance in
            let blockIndexes = blockLedgers.filter { ($0.shadowBubbleID ?? $0.bubbleID) == instance.bubbleID }.map(\.blockIndex).sorted()
            let conflictBlocks = blockLedgers.filter { ($0.shadowBubbleID ?? $0.bubbleID) == instance.bubbleID && $0.assignmentVerdict == "dominantProxyBubbleConflict" }.map(\.blockIndex)
            let correctionBlocks = uniqueSorted((bubbleAssignmentCorrectionReport?.diagnostics ?? []).filter { $0.correctedBubbleID == instance.bubbleID && $0.correctionRecommended }.map(\.blockIndex))
            let splitIDs = uniqueSorted(splitCandidates.filter { $0.parentBubbleID == instance.bubbleID }.map(\.id))
            let renderLockedBlocks = blockLedgers.filter { ($0.shadowBubbleID ?? $0.bubbleID) == instance.bubbleID && $0.renderLockVerdict == "renderLocked" }.map(\.blockIndex)
            let layoutVerdict: String
            if blockIndexes.count <= 1, conflictBlocks.isEmpty, splitIDs.isEmpty {
                layoutVerdict = "stableSingleBlockBubble"
            } else if !conflictBlocks.isEmpty {
                layoutVerdict = "assignmentConflict"
            } else if !splitIDs.isEmpty {
                layoutVerdict = "splitReviewNeeded"
            } else if siblingLedgers.contains(where: { $0.bubbleID == instance.bubbleID && $0.partitionVerdict == "partitionStable" }) {
                layoutVerdict = "siblingPartitionStable"
            } else if bubbleMaskReport == nil {
                layoutVerdict = "needsRealBubbleMask"
            } else if blockIndexes.count > 1 {
                layoutVerdict = "stableMultiBlockBubble"
            } else {
                layoutVerdict = "manualReviewOnly"
            }
            let primaryRisk = !conflictBlocks.isEmpty ? "assignmentConflict" : (!splitIDs.isEmpty ? "splitRisk" : (layoutVerdict == "needsRealBubbleMask" ? "proxyOnly" : "none"))
            let action = layoutVerdict == "assignmentConflict" || layoutVerdict == "splitReviewNeeded"
                ? "reviewBubbleIndexAssignmentAndSplit"
                : (layoutVerdict == "needsRealBubbleMask" ? "collectRealBubbleMaskArtifact" : "keepBubbleIndexLedgerReportOnly")
            return MangaKoharuBubbleIndexBubbleLedger(
                bubbleID: instance.bubbleID,
                bbox: instance.bbox,
                maskPixelCount: instance.maskPixelCount,
                maskCoverageRatio: instance.maskCoverageRatio,
                safeRect: instance.safeRect,
                safeRectCoverageRatio: instance.safeRectCoverageRatio,
                blockIndexes: blockIndexes,
                siblingGroupIDs: siblingGroupIDsByBubble[instance.bubbleID] ?? [],
                splitCandidateIDs: splitIDs,
                assignmentConflictBlocks: uniqueSorted(conflictBlocks),
                correctionRecommendedBlocks: correctionBlocks,
                renderLockedBlocks: uniqueSorted(renderLockedBlocks),
                layoutVerdict: layoutVerdict,
                primaryRisk: primaryRisk,
                nextAction: action,
                decisionSignals: [
                    signal("maskCoverageRatio", instance.maskCoverageRatio.formatted(.number.precision(.fractionLength(4))), source: "bubbleMaskReport.instances"),
                    signal("blockIndexes", joined(blockIndexes), source: "koharuBubbleIndexShadowLedgerReport.blockLedgers")
                ],
                evaluationSignals: [
                    signal("dialogueBlockCount", String(blocks.filter { blockIndexes.contains($0.index) && $0.bestGroundTruthType == "dialogue" }.count), source: "blocks.bestGroundTruthType", decision: false, evaluation: true)
                ],
                groundTruthUsedForDecision: false,
                wouldChangeMainFlow: false,
                diagnosticOnly: true
            )
        }.sorted { $0.bubbleID < $1.bubbleID }

        let conflictBlocks = uniqueSorted(blockLedgers.filter { $0.assignmentVerdict == "dominantProxyBubbleConflict" }.map(\.blockIndex))
        let splitReviewBlocks = uniqueSorted(blockLedgers.filter { $0.assignmentVerdict == "splitCandidateNeedsReview" || $0.siblingPartitionVerdict == "splitCandidatePresent" }.map(\.blockIndex))
        let sameBubbleSiblingBlocks = uniqueSorted(blockLedgers.filter { !$0.siblingBlockIndexes.isEmpty }.map(\.blockIndex))
        let safeAreaCompareBlocks = uniqueSorted(blockLedgers.filter { $0.currentVsShadowSafeRectIoU != nil }.map(\.blockIndex))
        let needsRealBubbleMaskBlocks = uniqueSorted(blockLedgers.filter { $0.assignmentVerdict == "needsRealBubbleMask" || $0.safeAreaVerdict == "needsRealBubbleMask" || $0.siblingPartitionVerdict == "needsRealBubbleMask" }.map(\.blockIndex))
        let renderLockedBlocks = uniqueSorted(blockLedgers.filter { $0.renderLockVerdict == "renderLocked" }.map(\.blockIndex))
        let manualReviewBlocks = uniqueSorted(blockLedgers.filter { $0.nextAction == "manualReviewOnly" || $0.siblingPartitionVerdict == "manualReviewOnly" }.map(\.blockIndex))

        func gate(_ id: String, _ name: String, _ scope: String, _ status: String, _ threshold: String, _ affected: [Int], _ failure: String, _ action: String, _ signals: [MangaKoharuBubbleIndexSignal]) -> MangaKoharuBubbleIndexGate {
            MangaKoharuBubbleIndexGate(gateID: id, gateName: name, scope: scope, status: status, threshold: threshold, affectedBlocks: uniqueSorted(affected), decisionSignals: signals, failureMeans: failure, recommendedAction: action, groundTruthUsedForDecision: false)
        }

        let gateLedger = [
            gate("G-bubble-index-report-only", "Report only", "report", "passed", "wouldChangeMainFlow=false", [], "BubbleIndex ledger mutates OCR, translation, safeLayoutRect, render, or block pass state", "revertBehavioralChange", [signal("wouldChangeMainFlow", "false", source: "koharuBubbleIndexShadowLedgerReport")]),
            gate("G-bubble-index-no-ground-truth-decision", "No ground truth decision", "report", "passed", "groundTruthUsedForDecision=false", allBlocks, "ground truth changes assignment, safe-area, sibling, or next action decisions", "moveGroundTruthToEvaluationSignalsOnly", [signal("groundTruthUsedForDecision", "false", source: "koharuBubbleIndexShadowLedgerReport")]),
            gate("G-bubble-index-block-ledger-count", "Block ledger count", "blocks", blockLedgers.count == blocks.count ? "passed" : "warning", "blockLedgerCount==totalBlocksDetected", allBlocks, "some final blocks lack BubbleIndex ledger rows", "restorePerBlockBubbleIndexLedger", [signal("blockLedgerCount", String(blockLedgers.count), source: "koharuBubbleIndexShadowLedgerReport")]),
            gate("G-bubble-index-bubble-ledger-count", "Bubble ledger count", "BubbleMask", bubbleLedgers.count == (bubbleMaskReport?.instanceCount ?? 0) ? "passed" : "warning", "bubbleLedgerCount==bubbleMaskReport.instanceCount", allBlocks, "BubbleMask instance ledger count does not match upstream proxy instances", "inspectBubbleMaskReportInputs", [signal("bubbleLedgerCount", String(bubbleLedgers.count), source: "koharuBubbleIndexShadowLedgerReport")]),
            gate("G-bubble-index-proxy-boundary", "Proxy boundary", "BubbleMask", "passed", "proxyNotRealBubbleMask=true", allBlocks, "BubbleMask proxy is promoted as real Koharu BubbleMask or BubbleIndex", "keepProxyBoundaryOrCollectRealArtifact", [signal("proxyNotRealBubbleMask", "true", source: "koharuBubbleIndexShadowLedgerReport")]),
            gate("G-bubble-index-assignment-audited", "Assignment audited", "BubbleIndex", conflictBlocks.isEmpty ? "passed" : "warning", "assignment conflicts explicitly listed", conflictBlocks, "dominant bubble conflicts are hidden or silently corrected", "reviewBubbleIndexAssignmentAndSplit", [signal("conflictBlocks", joined(conflictBlocks), source: "koharuBubbleIndexShadowLedgerReport")]),
            gate("G-bubble-index-safe-area-compared", "Safe area compared", "BubbleIndex", safeAreaCompareBlocks.isEmpty && !blocks.isEmpty ? "warning" : "passed", "current safeLayoutRect compared against shadow mask-safe rect where available", safeAreaCompareBlocks, "safe-area shadow ledger cannot compare existing and mask-safe geometry", "inspectMaskSafeRectInputs", [signal("safeAreaCompareBlocks", joined(safeAreaCompareBlocks), source: "koharuBubbleIndexShadowLedgerReport")]),
            gate("G-bubble-index-sibling-partition-audited", "Sibling partition audited", "BubbleIndex", siblingLedgers.isEmpty && !sameBubbleSiblingBlocks.isEmpty ? "warning" : "passed", "same-bubble sibling groups have ledgers", sameBubbleSiblingBlocks, "multi-block bubble sibling partition is missing", "restoreSiblingPartitionLedgers", [signal("siblingLedgerCount", String(siblingLedgers.count), source: "koharuBubbleIndexShadowLedgerReport")]),
            gate("G-bubble-index-split-review-preserved", "Split review preserved", "BubbleIndex", splitReviewBlocks.isEmpty ? "passed" : "warning", "split candidates remain report-only review", splitReviewBlocks, "split candidate mutates block grouping or safeLayoutRect", "keepSplitReviewReportOnly", [signal("splitReviewBlocks", joined(splitReviewBlocks), source: "koharuBubbleIndexShadowLedgerReport")]),
            gate("G-bubble-index-render-lock-respected", "Render lock respected", "FinalRender", koharuRenderRegressionLockReport == nil ? "warning" : "passed", "render lock report remains upstream evidence only", koharuRenderRegressionLockReport?.renderIssueBlocks ?? [], "BubbleIndex ledger changes overlay renderer or ignores render lock", "inspectRenderLockGateLedger", [signal("renderLockVerdict", koharuRenderRegressionLockReport?.renderLockVerdict ?? "nil", source: "koharuRenderRegressionLockReport")]),
            gate("G-bubble-index-real-artifact-gated", "Real artifact gated", "ExternalArtifacts", needsRealBubbleMaskBlocks.isEmpty ? "passed" : "warning", "real BubbleMask needs are explicit and not fabricated", needsRealBubbleMaskBlocks, "missing real BubbleMask is treated as ready or generated locally", "collectRealBubbleMaskArtifact", [signal("needsRealBubbleMaskBlocks", joined(needsRealBubbleMaskBlocks), source: "koharuBubbleIndexShadowLedgerReport")]),
            gate("G-bubble-index-ci-fast-ready", "CI fast ready", "ci-fast", "passed", "ledger uses existing reports only", allBlocks, "BubbleIndex ledger adds OCR/LLM or full-only dependency", "keepCIFastReportOnly", [signal("inputReports", "blocks,bubbleMaskReport,bubbleScoreboard,renderLock,nativeReplay", source: "koharuBubbleIndexShadowLedgerReport")])
        ]

        let ledgerVerdict: String
        if bubbleMaskReport == nil {
            ledgerVerdict = "blockedByMissingBubbleMaskProxy"
        } else if bubbleMaskAssignmentSplitScoreboardReport == nil {
            ledgerVerdict = "blockedByMissingBubbleScoreboard"
        } else if !needsRealBubbleMaskBlocks.isEmpty {
            ledgerVerdict = "needsRealBubbleMaskArtifact"
        } else if !manualReviewBlocks.isEmpty {
            ledgerVerdict = "manualReviewOnly"
        } else if !splitReviewBlocks.isEmpty || !conflictBlocks.isEmpty {
            ledgerVerdict = "reportOnlyBubbleIndexReady"
        } else {
            ledgerVerdict = "bubbleIndexShadowLedgerReady"
        }

        return MangaKoharuBubbleIndexShadowLedgerReport(
            enabled: true,
            source: "AITRANSProbe",
            referencePipeline: "Koharu",
            referenceConcept: "BubbleIndex.MajorityMaskSafeAreaSiblingPartition",
            evaluatedBlockCount: blocks.count,
            evaluatedBubbleCount: bubbleMaskReport?.instanceCount ?? 0,
            blockLedgerCount: blockLedgers.count,
            bubbleLedgerCount: bubbleLedgers.count,
            siblingLedgerCount: siblingLedgers.count,
            gateCount: gateLedger.count,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            proxyNotRealBubbleMask: true,
            externalArtifactsRequiredForThisReport: false,
            ledgerVerdict: ledgerVerdict,
            assignmentVerdictBreakdown: countBy(blockLedgers.map(\.assignmentVerdict)),
            safeAreaVerdictBreakdown: countBy(blockLedgers.map(\.safeAreaVerdict)),
            siblingPartitionVerdictBreakdown: countBy(blockLedgers.map(\.siblingPartitionVerdict)),
            renderLockVerdictBreakdown: countBy(blockLedgers.map(\.renderLockVerdict)),
            bubbleLayoutVerdictBreakdown: countBy(bubbleLedgers.map(\.layoutVerdict)),
            nextActionBreakdown: countBy(blockLedgers.map(\.nextAction)),
            conflictBlocks: conflictBlocks,
            splitReviewBlocks: splitReviewBlocks,
            sameBubbleSiblingBlocks: sameBubbleSiblingBlocks,
            safeAreaCompareBlocks: safeAreaCompareBlocks,
            needsRealBubbleMaskBlocks: needsRealBubbleMaskBlocks,
            renderLockedBlocks: renderLockedBlocks,
            manualReviewBlocks: manualReviewBlocks,
            blockLedgers: blockLedgers.sorted { $0.blockIndex < $1.blockIndex },
            bubbleLedgers: bubbleLedgers,
            siblingLedgers: siblingLedgers,
            gateLedger: gateLedger,
            notes: [
                "koharuBubbleIndexShadowLedgerReport is a report-only Koharu BubbleIndex shadow ledger built from existing AITRANS probe evidence.",
                "It audits majority mask assignment, mask-safe area comparison, same-bubble sibling partition, split risk, and render lock without writing back to safeLayoutRect or overlay rendering.",
                "Ground truth appears only in evaluationSignals; assignmentVerdict, safeAreaVerdict, siblingPartitionVerdict, gate status, and nextAction use ground-truth-free signals.",
                "proxyNotRealBubbleMask=true: AITRANS BubbleMask is a proxy and must not be promoted as real Koharu BubbleMask/BubbleIndex without external artifacts.",
                "The report does not add OCR or LLM calls and does not change OCR, translation input, blockPassed, failureCategory, cleanup, safeLayoutRect, glyphMaskFillRects, background fill, active artifacts, currentBlockSource, or PNG output behavior."
            ]
        )
    }

    private static func makeKoharuArtifactIdentityReconciliationReport(
        blocks: [MangaOverlayProbeBlock],
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?,
        koharuNativeArtifactContractDryRunReport: MangaKoharuNativeArtifactContractDryRunReport?
    ) -> MangaKoharuArtifactIdentityReconciliationReport {
        func signal(
            _ name: String,
            _ value: String,
            source: String,
            decision: Bool = true,
            evaluation: Bool = false
        ) -> MangaKoharuArtifactIdentityReconciliationSignal {
            MangaKoharuArtifactIdentityReconciliationSignal(
                name: name,
                value: value,
                sourceReport: source,
                groundTruthFreeDecisionSignal: decision,
                groundTruthUsedForEvaluationOnly: evaluation
            )
        }

        func gate(
            _ id: String,
            _ name: String,
            _ status: String,
            _ scope: String,
            _ threshold: String,
            _ affected: [Int],
            _ failureMeans: String,
            _ action: String,
            _ decisions: [MangaKoharuArtifactIdentityReconciliationSignal]
        ) -> MangaKoharuArtifactIdentityReconciliationGate {
            MangaKoharuArtifactIdentityReconciliationGate(
                gateID: id,
                name: name,
                status: status,
                scope: scope,
                threshold: threshold,
                affectedBlocks: Array(Set(affected)).sorted(),
                failureMeans: failureMeans,
                recommendedAction: action,
                decisionSignals: decisions
            )
        }

        let receipt = externalArtifactReadinessReport?.artifactIdentityReceipt
        var contractFilesByKind: [String: MangaKoharuNativeArtifactContractDryRunFile] = [:]
        for file in koharuNativeArtifactContractDryRunReport?.requiredFiles ?? [] {
            let key = file.artifactKind.lowercased()
            if contractFilesByKind[key] == nil {
                contractFilesByKind[key] = file
            }
        }
        var receiptFilesByKind: [String: MangaOverlayExternalArtifactFileIdentityReceipt] = [:]
        for file in receipt?.files ?? [] {
            let key = file.artifactKind.lowercased()
            if receiptFilesByKind[key] == nil {
                receiptFilesByKind[key] = file
            }
        }

        struct FileSpec {
            let kind: String
            let receiptKey: String
            let ciSizePath: String
            let ciSHAPath: String
        }

        let fileSpecs = [
            FileSpec(
                kind: "SourceImage",
                receiptKey: "sourceimage",
                ciSizePath: "ci-artifact-manifest.koharuArtifactValidationIdentitySummary.sourceImage.sizeBytes",
                ciSHAPath: "ci-artifact-manifest.koharuArtifactValidationIdentitySummary.sourceImage.sha256"
            ),
            FileSpec(
                kind: "manifest",
                receiptKey: "manifest",
                ciSizePath: "ci-artifact-manifest.koharuArtifactValidationIdentitySummary.artifactFiles.manifest.sizeBytes",
                ciSHAPath: "ci-artifact-manifest.koharuArtifactValidationIdentitySummary.artifactFiles.manifest.sha256"
            ),
            FileSpec(
                kind: "TextBoxes",
                receiptKey: "textboxes",
                ciSizePath: "ci-artifact-manifest.koharuArtifactValidationIdentitySummary.artifactFiles.TextBoxes.sizeBytes",
                ciSHAPath: "ci-artifact-manifest.koharuArtifactValidationIdentitySummary.artifactFiles.TextBoxes.sha256"
            ),
            FileSpec(
                kind: "BubbleMask",
                receiptKey: "bubblemask",
                ciSizePath: "ci-artifact-manifest.koharuArtifactValidationIdentitySummary.artifactFiles.BubbleMask.sizeBytes",
                ciSHAPath: "ci-artifact-manifest.koharuArtifactValidationIdentitySummary.artifactFiles.BubbleMask.sha256"
            ),
            FileSpec(
                kind: "SegmentMask",
                receiptKey: "segmentmask",
                ciSizePath: "ci-artifact-manifest.koharuArtifactValidationIdentitySummary.artifactFiles.SegmentMask.sizeBytes",
                ciSHAPath: "ci-artifact-manifest.koharuArtifactValidationIdentitySummary.artifactFiles.SegmentMask.sha256"
            )
        ]

        let rows = fileSpecs.map { spec -> MangaKoharuArtifactIdentityReconciliationFileRow in
            let fileReceipt = receiptFilesByKind[spec.receiptKey]
            let contractFile = contractFilesByKind[spec.receiptKey]
            let appIdentityStatus: String
            if receipt == nil {
                appIdentityStatus = "artifactIdentityReceiptMissing"
            } else if fileReceipt == nil {
                appIdentityStatus = "appReceiptFileRowMissing"
            } else if fileReceipt?.exists != true {
                appIdentityStatus = "appReceiptFileMissing"
            } else if fileReceipt?.sha256?.isEmpty != false {
                appIdentityStatus = "appReceiptHashMissing"
            } else if fileReceipt?.sizeBytes == nil {
                appIdentityStatus = "appReceiptSizeMissing"
            } else {
                appIdentityStatus = "appReceiptReady"
            }
            let comparisonStatus: String
            switch appIdentityStatus {
            case "appReceiptReady":
                comparisonStatus = "appReceiptReady"
            case "artifactIdentityReceiptMissing", "appReceiptFileRowMissing", "appReceiptFileMissing":
                comparisonStatus = "appReceiptMissing"
            case "appReceiptHashMissing":
                comparisonStatus = "appHashMissing"
            case "appReceiptSizeMissing":
                comparisonStatus = "appSizeMissing"
            default:
                comparisonStatus = "awaitingCIManifest"
            }
            let nextAction = comparisonStatus == "appReceiptReady"
                ? "compareWithCIManifestIdentitySummary"
                : "runProbeWithActiveKoharuArtifactsAndAppSideIdentityReceipt"
            return MangaKoharuArtifactIdentityReconciliationFileRow(
                artifactKind: spec.kind,
                appReceiptPath: fileReceipt?.path,
                appRequired: fileReceipt?.required ?? true,
                appExists: fileReceipt?.exists ?? false,
                appSizeBytes: fileReceipt?.sizeBytes,
                appSHA256: fileReceipt?.sha256,
                appIdentityStatus: appIdentityStatus,
                contractDryRunStatus: contractFile?.identityStatus,
                ciManifestFieldPathForSize: spec.ciSizePath,
                ciManifestFieldPathForSHA256: spec.ciSHAPath,
                comparisonStatus: comparisonStatus,
                nextAction: nextAction,
                decisionSignals: [
                    signal("artifactKind", spec.kind, source: "externalArtifactReadinessReport.artifactIdentityReceipt"),
                    signal("appExists", String(fileReceipt?.exists == true), source: "externalArtifactReadinessReport.artifactIdentityReceipt"),
                    signal("appSizeBytesPresent", String(fileReceipt?.sizeBytes != nil), source: "externalArtifactReadinessReport.artifactIdentityReceipt"),
                    signal("appSHA256Present", String(fileReceipt?.sha256?.isEmpty == false), source: "externalArtifactReadinessReport.artifactIdentityReceipt"),
                    signal("ciManifestFieldPathForSHA256", spec.ciSHAPath, source: "ci-artifact-manifest.koharuArtifactValidationIdentitySummary")
                ]
            )
        }

        let allBlockIndexes = blocks.map(\.index)
        let allRowsReady = rows.allSatisfy { $0.comparisonStatus == "appReceiptReady" }
        let appReceiptVerdict = receipt?.identityVerdict ?? "notRecorded"
        let contractVerdict = koharuNativeArtifactContractDryRunReport?.contractDryRunVerdict ?? "notExecuted"
        let sourceImageSHA256Declared = receipt?.sourceImageSHA256Declared
        let sourceImageSHA256Expected = receipt?.sourceImageSHA256Expected
        let sourceImageSHA256Matches = receipt?.sourceImageSHA256Matches ?? false
        let readyForCIManifestComparison = appReceiptVerdict == "activeArtifactIdentityRecorded"
            && allRowsReady
            && sourceImageSHA256Matches
            && koharuNativeArtifactContractDryRunReport?.appSideArtifactIdentityFilesPresent == true
            && koharuNativeArtifactContractDryRunReport?.appSideArtifactIdentityHashesPresent == true
        let identityReconciliationVerdict: String
        if readyForCIManifestComparison {
            identityReconciliationVerdict = "readyForCIManifestComparison"
        } else if receipt == nil {
            identityReconciliationVerdict = "appReceiptMissing"
        } else if !allRowsReady {
            identityReconciliationVerdict = "appReceiptIncomplete"
        } else if appReceiptVerdict != "activeArtifactIdentityRecorded" {
            identityReconciliationVerdict = "appReceiptNotActiveArtifactIdentityRecorded"
        } else {
            identityReconciliationVerdict = "awaitingCIManifestComparison"
        }
        let gates = [
            gate(
                "G-koharu-artifact-identity-reconciliation-report-only",
                "Report only",
                "passed",
                "policy",
                "does not read CI manifest, mutate active artifacts, or alter OCR/translation/render flow",
                [],
                "identity reconciliation changes production candidate selection or writes active artifacts",
                "keepIdentityReconciliationReportOnly",
                [signal("wouldChangeMainFlow", "false", source: "koharuArtifactIdentityReconciliationReport")]
            ),
            gate(
                "G-koharu-artifact-identity-reconciliation-app-receipt",
                "App receipt ready",
                readyForCIManifestComparison ? "passed" : "blocked",
                "ExternalArtifacts",
                "App runtime receipt has SourceImage plus four required artifact size/SHA256 rows",
                allBlockIndexes,
                "Agent C cannot prove App consumed the same files validated by CI",
                "runProbeWithActiveKoharuArtifactsAndAppSideIdentityReceipt",
                [
                    signal("appReceiptVerdict", appReceiptVerdict, source: "externalArtifactReadinessReport.artifactIdentityReceipt"),
                    signal("allRowsReady", String(allRowsReady), source: "koharuArtifactIdentityReconciliationReport"),
                    signal("sourceImageSHA256Matches", String(sourceImageSHA256Matches), source: "externalArtifactReadinessReport.artifactIdentityReceipt"),
                    signal("contractDryRunVerdict", contractVerdict, source: "koharuNativeArtifactContractDryRunReport")
                ]
            ),
            gate(
                "G-koharu-artifact-identity-reconciliation-ready",
                "Ready for CI manifest comparison",
                readyForCIManifestComparison ? "passed" : "blocked",
                "CIReview",
                "fileRows expose ci-artifact-manifest.koharuArtifactValidationIdentitySummary field paths for size and SHA256 comparison",
                allBlockIndexes,
                "CI manifest identity and App runtime receipt cannot be compared mechanically",
                readyForCIManifestComparison ? "compareAppReceiptWithCIManifestIdentitySummary" : "restoreAppSideArtifactIdentityReceipt",
                [
                    signal("readyForCIManifestComparison", String(readyForCIManifestComparison), source: "koharuArtifactIdentityReconciliationReport"),
                    signal("sourceImageSHA256Declared", sourceImageSHA256Declared ?? "nil", source: "externalArtifactReadinessReport.artifactIdentityReceipt"),
                    signal("sourceImageSHA256Expected", sourceImageSHA256Expected ?? "nil", source: "externalArtifactReadinessReport.artifactIdentityReceipt"),
                    signal("sourceImageSHA256Matches", String(sourceImageSHA256Matches), source: "externalArtifactReadinessReport.artifactIdentityReceipt"),
                    signal("manualCIComparisonRequired", "true", source: "koharuArtifactIdentityReconciliationReport")
                ]
            )
        ]
        return MangaKoharuArtifactIdentityReconciliationReport(
            enabled: true,
            source: "AITRANSProbe",
            referencePipeline: "Koharu",
            referenceConcept: "ArtifactIdentityReconciliation.CIManifestAppReceipt",
            referenceWorkItemID: "WI-koharu-artifact-identity-reconciliation",
            evaluatedBlockCount: blocks.count,
            fileRowCount: rows.count,
            gateCount: gates.count,
            sourceImage: receipt?.sourceImage ?? "test/1.png",
            sourceImageSHA256Declared: sourceImageSHA256Declared,
            sourceImageSHA256Expected: sourceImageSHA256Expected,
            sourceImageSHA256Matches: sourceImageSHA256Matches,
            activeInputDirectory: "test/koharu_artifacts",
            appReceiptVerdict: appReceiptVerdict,
            contractDryRunVerdict: contractVerdict,
            identityReconciliationVerdict: identityReconciliationVerdict,
            readyForCIManifestComparison: readyForCIManifestComparison,
            manualCIComparisonRequired: true,
            groundTruthUsedForDecision: false,
            groundTruthUsedForEvaluationOnly: true,
            wouldChangeMainFlow: false,
            diagnosticOnly: true,
            dryRunOnly: true,
            activeExportAllowed: false,
            externalArtifactsRequiredForThisReport: false,
            appReceiptStatusBreakdown: countBy(rows.map(\.appIdentityStatus)),
            comparisonStatusBreakdown: countBy(rows.map(\.comparisonStatus)),
            nextActionBreakdown: countBy(rows.map(\.nextAction)),
            readyFileKinds: rows.filter { $0.comparisonStatus == "appReceiptReady" }.map(\.artifactKind),
            missingFileKinds: rows.filter { $0.comparisonStatus == "appReceiptMissing" }.map(\.artifactKind),
            hashMissingFileKinds: rows.filter { $0.comparisonStatus == "appHashMissing" || $0.comparisonStatus == "appSizeMissing" }.map(\.artifactKind),
            fileRows: rows,
            gateLedger: gates,
            notes: [
                "koharuArtifactIdentityReconciliationReport converts the App-side runtime artifactIdentityReceipt into a stable Agent C / CI comparison ledger.",
                "The report intentionally does not read ci-artifact-manifest.json; GitHub Actions or Agent C compare the listed field paths against App receipt size/SHA256 values after export.",
                "Manifest sourceImageSHA256 must match the App runtime source image SHA256 before readyForCIManifestComparison can become true.",
                "SourceImage plus manifest, TextBoxes, BubbleMask, and SegmentMask are all required before readyForCIManifestComparison can become true.",
                "This is a P0 real-artifact handoff evidence gate, not a detector, OCR, translation, renderer, or active artifact promotion.",
                "No OCR, LLM, PNG, prompt/model, renderer, safeLayoutRect, glyphMaskFillRects, finalTextUsedForTranslation, blockPassed, failureCategory, currentBlockSource, or active test/koharu_artifacts behavior changes are made."
            ]
        )
    }

    private static func makeKoharuArtifactConvergenceReport(
        blocks: [MangaOverlayProbeBlock],
        diagnostics: MangaOverlayProbeDiagnostics,
        koharuArtifactDAGReport: MangaKoharuArtifactDAGReport?,
        koharuStageGapReplicationReport: MangaKoharuStageGapReplicationReport?,
        koharuNativeReplicationScoreboardReport: MangaKoharuNativeReplicationScoreboardReport?,
        nativeTextBoxProxyLedgerReport: MangaNativeTextBoxProxyLedgerReport?,
        bubbleMaskAssignmentSplitScoreboardReport: MangaBubbleMaskAssignmentSplitScoreboardReport?,
        segmentMaskProxyCoverageScoreboardReport: MangaSegmentMaskProxyCoverageScoreboardReport?,
        externalArtifactReadinessReport: MangaOverlayExternalArtifactReadinessReport?,
        externalTextBoxShadowOCRReport: MangaOverlayExternalTextBoxShadowOCRReport?,
        cleanTextDiagnostic: MangaCleanTextDiagnosticReport?,
        translationModelFloorComparisonReport: MangaTranslationModelFloorComparisonReport?,
        koharuRenderRegressionLockReport: MangaKoharuRenderRegressionLockReport?,
        koharuPipelineResolverReport: MangaKoharuPipelineResolverReport?,
        koharuWorkOrderRouterReport: MangaKoharuWorkOrderRouterReport?,
        koharuExternalArtifactRequestPacketReport: MangaKoharuExternalArtifactRequestPacketReport?,
        koharuNativeAlgorithmReplayMatrixReport: MangaKoharuNativeAlgorithmReplayMatrixReport? = nil,
        koharuBubbleIndexShadowLedgerReport: MangaKoharuBubbleIndexShadowLedgerReport? = nil,
        koharuDistanceFieldSafeAreaReport: MangaKoharuDistanceFieldSafeAreaReport? = nil,
        koharuBubbleAdjacencySeamReport: MangaKoharuBubbleAdjacencySeamReport? = nil,
        koharuRenderSpriteFitPlannerReport: MangaKoharuRenderSpriteFitPlannerReport? = nil,
        koharuNativeTextBoxDetectorLiteReport: MangaKoharuNativeTextBoxDetectorLiteReport? = nil,
        koharuNativeTextBoxDetectorLiteShadowOCRReport: MangaKoharuNativeTextBoxDetectorLiteShadowOCRReport? = nil,
        koharuNativeTextBoxDetectorLiteRefinementReport: MangaKoharuNativeTextBoxDetectorLiteRefinementReport? = nil,
        koharuNativeTextBoxDetectorLiteClosedLoopReport: MangaKoharuNativeTextBoxDetectorLiteClosedLoopReport? = nil,
        koharuNativeBubbleMaskInstanceLiteReport: MangaKoharuNativeBubbleMaskInstanceLiteReport? = nil,
        koharuNativeSegmentMaskRefinementLiteReport: MangaKoharuNativeSegmentMaskRefinementLiteReport? = nil,
        koharuNativeArtifactBundleLiteReport: MangaKoharuNativeArtifactBundleLiteReport? = nil,
        koharuNativePromotionGateLiteReport: MangaKoharuNativePromotionGateLiteReport? = nil,
        koharuNativeArtifactContractDryRunReport: MangaKoharuNativeArtifactContractDryRunReport? = nil,
        koharuArtifactIdentityReconciliationReport: MangaKoharuArtifactIdentityReconciliationReport? = nil
    ) -> MangaKoharuArtifactConvergenceReport {
        func uniqueSorted(_ values: [Int]) -> [Int] {
            Array(Set(values)).sorted()
        }

        func sortedUniqueStrings(_ values: [String]) -> [String] {
            Array(Set(values)).sorted()
        }

        func joined(_ values: [Int]) -> String {
            uniqueSorted(values).map(String.init).joined(separator: ",")
        }

