        source: SupportedLanguage,
        target: SupportedLanguage,
        input: String
    ) -> ModelGenerationRequest {
        ModelGenerationRequest(
            task: .translation,
            mode: .translate,
            inputText: input,
            transcriptContext: [],
            sourceLanguage: source,
            targetLanguage: target,
            prompt: selectedPrompt,
            sampling: sampling,
            translationProfile: .standard
        )
    }

    private func translationProbeVerdict(
        source: SupportedLanguage,
        target: SupportedLanguage,
        input: String,
        output: String
    ) -> String {
        let trimSet = CharacterSet.whitespacesAndNewlines.union(.punctuationCharacters)
        let cleanInput = input.trimmingCharacters(in: trimSet)
        let cleanOutput = output.trimmingCharacters(in: trimSet)

        if cleanOutput.isEmpty {
            return "失败：空输出"
        }
        if cleanOutput.localizedCaseInsensitiveCompare(cleanInput) == .orderedSame {
            return "失败：输出等于原文"
        }
        if cleanOutput.localizedCaseInsensitiveContains(cleanInput) || cleanInput.localizedCaseInsensitiveContains(cleanOutput) {
            return "失败：输出包含原文"
        }
        if Self.isPlaceholderTranslationOutput(output) {
            return "失败：输出是占位答复"
        }
        switch target {
        case .simplifiedChinese:
            return Self.containsCJK(output) ? "通过：真实 Local raw 输出像中文" : "失败：输出不像中文"
        case .englishUS:
            return Self.containsLatinLetter(output) && !Self.containsCJK(output)
                ? "通过：真实 Local raw 输出像英文"
                : "失败：输出不像英文"
        default:
            return source == target ? "通过：同语种未严格校验" : "通过：非中英目标只校验非空"
        }
    }

    private func updateModelDownloadStateFromDisk() {
        if isLocalModelInstalled {
            modelDownload = installedDownloadProgress(message: "已安装")
        } else {
            cleanupPartialModelDownload()
            modelDownload = ModelDownloadProgress.idle
        }
    }

    private func installedDownloadProgress(message: String) -> ModelDownloadProgress {
        let modelURL = localModelDirectory.appendingPathComponent(localModelFilename)
        let size = localModelSize(at: modelURL) ?? builtInModel.expectedSizeBytes
        return ModelDownloadProgress(
            phase: .installed,
            bytesReceived: size,
            totalBytes: max(size, builtInModel.expectedSizeBytes),
            speedBytesPerSecond: 0,
            message: message
        )
    }

    private func localModelSize(at url: URL) -> Int64? {
        guard let attributes = try? FileManager.default.attributesOfItem(atPath: url.path),
              let fileSize = attributes[.size] as? NSNumber else {
            return nil
        }
        return fileSize.int64Value
    }

    private func cleanupPartialModelDownload() {
        let temporaryURL = localModelDirectory
            .appendingPathComponent(localModelFilename)
            .appendingPathExtension("download")
        if FileManager.default.fileExists(atPath: temporaryURL.path) {
            try? FileManager.default.removeItem(at: temporaryURL)
        }
    }

    nonisolated private static func loadSecurityScopedData(from url: URL) async throws -> Data {
        let task = Task.detached(priority: .userInitiated) {
            let didAccess = url.startAccessingSecurityScopedResource()
            defer {
                if didAccess {
                    url.stopAccessingSecurityScopedResource()
                }
            }

            return try Data(contentsOf: url)
        }

        return try await task.value
    }

    nonisolated private static func sanitizedImageFilename(from url: URL) -> String {
        sanitizedImageFilename(url.lastPathComponent)
    }

    nonisolated private static func sanitizedImageFilename(_ filename: String) -> String {
        let fallback = "image-input.png"
        let rawName = filename.isEmpty ? fallback : filename
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "._-"))
        let sanitized = rawName.unicodeScalars.map { allowed.contains($0) ? Character($0) : "_" }
        let name = String(sanitized).trimmingCharacters(in: CharacterSet(charactersIn: "._-"))
        return name.isEmpty ? fallback : name
    }

    nonisolated private static func renderImageTranslationOverlay(
        imageData: Data,
        blocks: [ImageTranslationBlock],
        filename: String,
        directory: URL,
        mode: ImageTranslationOverlayMode,
        renderID: UUID
    ) async throws -> URL {
        try await Task.detached(priority: .userInitiated) {
            guard let image = UIImage(data: imageData),
                  image.size.width > 0,
                  image.size.height > 0 else {
                throw VisionOCRServiceError.imageDecodeFailed
            }

            let canvas = CGRect(origin: .zero, size: image.size)
            let format = UIGraphicsImageRendererFormat()
            format.scale = 1
            format.opaque = false
            let renderer = UIGraphicsImageRenderer(size: image.size, format: format)
            let outputData = renderer.pngData { rendererContext in
                image.draw(in: canvas)

                for block in blocks {
                    let sourceRect = imageTranslationPixelRect(
                        block.boundingBox,
                        canvas: canvas
                    )
                    let overlayRect = imageTranslationOverlayRect(
                        sourceRect: sourceRect,
                        canvas: canvas,
                        mode: mode
                    )
                    guard !overlayRect.isEmpty else { continue }

                    let context = rendererContext.cgContext
                    context.setFillColor(
                        mode == .adjacent
                            ? UIColor.black.withAlphaComponent(0.88).cgColor
                            : UIColor.systemTeal.withAlphaComponent(0.94).cgColor
                    )
                    context.fill(overlayRect)
                    context.setStrokeColor(UIColor.systemTeal.cgColor)
                    context.setLineWidth(max(canvas.width * 0.002, 2))
                    context.stroke(overlayRect)

                    let translation = (block.translation.isEmpty ? block.original : block.translation)
                        .trimmingCharacters(in: .whitespacesAndNewlines)
                    guard !translation.isEmpty else { continue }
                    let text = mode == .adjacent && translation != block.original
                        ? "\(translation)\n\(block.original)"
                        : translation
                    let usesVerticalWriting = mode == .replace && block.prefersVerticalWriting
                    let fontSize = usesVerticalWriting
                        ? max(min(overlayRect.width * 0.72, canvas.width * 0.034), 9)
                        : max(min(overlayRect.height * 0.30, canvas.width * 0.034), 11)
                    let paragraph = NSMutableParagraphStyle()
                    paragraph.alignment = usesVerticalWriting || mode == .replace ? .center : .left
                    let attributes: [NSAttributedString.Key: Any] = [
                        .font: UIFont.systemFont(ofSize: fontSize, weight: .bold),
                        .foregroundColor: UIColor.white,
                        .paragraphStyle: paragraph
                    ]
                    Self.drawImageTranslationText(
                        text,
                        in: overlayRect.insetBy(
                            dx: max(canvas.width * 0.009, 6),
                            dy: max(canvas.height * 0.005, 5)
                        ),
                        attributes: attributes,
                        vertical: usesVerticalWriting
                    )
                }
            }

            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            let baseName = filename.isEmpty ? "image-translation" : (filename as NSString).deletingPathExtension
            let stagingURL = directory.appendingPathComponent(
                ".\(baseName)-translated-\(renderID.uuidString).staging.png"
            )
            try outputData.write(to: stagingURL, options: .atomic)
            return stagingURL
        }.value
    }

    /// Draws CJK replacement text in bounded right-to-left columns, matching
    /// Koharu's VerticalRl writing mode while keeping Latin output horizontal.
    nonisolated private static func drawImageTranslationText(
        _ text: String,
        in rect: CGRect,
        attributes: [NSAttributedString.Key: Any],
        vertical: Bool
    ) {
        guard vertical else {
            NSAttributedString(string: text, attributes: attributes).draw(
                with: rect,
                options: [.usesLineFragmentOrigin, .usesFontLeading, .truncatesLastVisibleLine],
                context: nil
            )
            return
        }

        let characters = ImageTranslationVerticalTextLayout.normalizedCharacters(in: text)
        guard !characters.isEmpty,
              rect.width > 0,
              rect.height > 0,
              let sourceFont = attributes[.font] as? UIFont else {
            return
        }

        let minimumFontSize: CGFloat = 7
        var fontSize = max(min(sourceFont.pointSize, rect.width * 0.82), minimumFontSize)
        for _ in 0..<3 {
            let font = sourceFont.withSize(fontSize)
            let rowHeight = max(font.lineHeight, 1)
            let columnWidth = max(rowHeight * 0.9, 1)
            let columns = max(Int(floor(rect.width / columnWidth)), 1)
            let requiredRows = max(Int(ceil(Double(characters.count) / Double(columns))), 1)
            let fittedSize = min(
                fontSize,
                min(
                    rect.height / CGFloat(requiredRows) * 0.88,
                    rect.width / CGFloat(columns) * 0.84
                )
            )
            guard fittedSize < fontSize - 0.1 else { break }
            fontSize = max(fittedSize, minimumFontSize)
        }

        let font = sourceFont.withSize(fontSize)
        let rowHeight = max(font.lineHeight, 1)
        let rowCapacity = max(Int(floor(rect.height / rowHeight)), 1)
        let columnCapacity = max(Int(floor(rect.width / max(rowHeight * 0.9, 1))), 1)
        let maximumCharacters = max(rowCapacity * columnCapacity, 1)
        let drawableCharacters: [String]
        if characters.count > maximumCharacters {
            let prefixCount = max(maximumCharacters - 1, 1)
            drawableCharacters = Array(characters.prefix(prefixCount)) + ["…"]
        } else {
            drawableCharacters = characters
        }

        let columnCount = max(Int(ceil(Double(drawableCharacters.count) / Double(rowCapacity))), 1)
        let actualColumnWidth = rect.width / CGFloat(columnCount)
        var adjustedAttributes = attributes
        adjustedAttributes[.font] = font
        for (index, character) in drawableCharacters.enumerated() {
            let column = index / rowCapacity
            let row = index % rowCapacity
            let glyph = ImageTranslationVerticalTextLayout.verticalGlyph(for: character)
            let cell = CGRect(
                x: rect.maxX - CGFloat(column + 1) * actualColumnWidth,
                y: rect.minY + CGFloat(row) * rowHeight,
                width: actualColumnWidth,
                height: rowHeight
            )
            let glyphSize = NSString(string: glyph).size(withAttributes: adjustedAttributes)
            let centeredGlyphRect = Self.centeredVerticalGlyphRect(
                glyphSize: glyphSize,
                in: cell,
                fullwidthPunctuation: ImageTranslationVerticalTextLayout.isFullwidthPunctuation(character)
            )
            NSAttributedString(string: glyph, attributes: adjustedAttributes).draw(
                at: centeredGlyphRect.origin
            )
        }
    }

    nonisolated private static func centeredVerticalGlyphRect(
        glyphSize: CGSize,
        in cell: CGRect,
        fullwidthPunctuation: Bool
    ) -> CGRect {
        let centeredY = cell.midY - glyphSize.height / 2
        let baselineAwareY = cell.minY + max((cell.height - glyphSize.height) / 2, 0)
        return CGRect(
            x: cell.midX - glyphSize.width / 2,
            y: fullwidthPunctuation ? centeredY : baselineAwareY,
            width: glyphSize.width,
            height: glyphSize.height
        )
    }

    nonisolated private static func publishImageTranslationOverlay(
        stagedURL: URL,
        filename: String,
        directory: URL,
        renderID: UUID
    ) throws -> URL {
        let baseName = filename.isEmpty ? "image-translation" : (filename as NSString).deletingPathExtension
        let outputURL = directory.appendingPathComponent(
            "aitrans-export-\(renderID.uuidString)-\(baseName)-translated.png"
        )
        let fileManager = FileManager.default
        if fileManager.fileExists(atPath: outputURL.path) {
            _ = try fileManager.replaceItemAt(outputURL, withItemAt: stagedURL)
        } else {
            try fileManager.moveItem(at: stagedURL, to: outputURL)
        }
        return outputURL
    }

    @discardableResult
    private func removeImageTranslationStagingFile(
        _ url: URL?,
        directory: URL
    ) -> Bool {
        removeImageTranslationRuntimeFile(url, directory: directory, kind: .staging)
    }

    @discardableResult
    private func removeImageTranslationInputFile(
        _ url: URL?,
        directory: URL
    ) -> Bool {
        removeImageTranslationRuntimeFile(url, directory: directory, kind: .input)
    }

    private func removeImageTranslationRuntimeFile(
        _ url: URL?,
        directory: URL,
        kind: ImageTranslationManagedFileKind
    ) -> Bool {
        guard let url else { return true }
        let managedDirectory = directory.standardizedFileURL
        let managedFile = url.standardizedFileURL
        let removed = Self.removeImageTranslationManagedFile(
            managedFile,
            directory: managedDirectory,
            kind: kind
        )
        if removed {
            imageTranslationOwnedOrphanURLs.remove(managedFile)
        } else if managedFile.deletingLastPathComponent() == managedDirectory,
                  Self.isImageTranslationManagedFilename(managedFile.lastPathComponent, kind: kind) {
            imageTranslationOwnedOrphanURLs.insert(managedFile)
        }
        return removed
    }

    private func publishImageTranslationExport(_ url: URL) {
        let standardizedURL = url.standardizedFileURL
        imageTranslationOwnedExportURLs.insert(standardizedURL)
        imageTranslationExportURL = standardizedURL
    }

    private func reconcileOrphanedImageTranslationWorkspaceAtStartup() {
        let directory = imageTranslationDirectory.standardizedFileURL
        let restoredInputURL = imageTranslationSourceURL?.standardizedFileURL
        guard let candidates = try? FileManager.default.contentsOfDirectory(
            at: directory,
            includingPropertiesForKeys: nil
        ) else {
            return
        }
        for candidate in candidates {
            let managedFile = candidate.standardizedFileURL
            let filename = managedFile.lastPathComponent
            if Self.isImageTranslationStableExportFilename(filename) {
                imageTranslationOwnedExportURLs.insert(managedFile)
            } else if Self.isImageTranslationInputFilename(filename) ||
                        Self.isImageTranslationStagingFilename(filename),
                        managedFile != restoredInputURL {
                imageTranslationOwnedOrphanURLs.insert(managedFile)
            }
        }
        discardImageTranslationExport()
    }

    private func discardImageTranslationExport() {
        discardImageTranslationShareCopies()
        imageTranslationExportURL = nil
        let directory = imageTranslationDirectory
        for url in Array(imageTranslationOwnedExportURLs) {
            if Self.removeImageTranslationManagedExport(url, directory: directory) {
                imageTranslationOwnedExportURLs.remove(url)
            }
        }
        discardImageTranslationWorkspaceOrphans(directory: directory)
    }

    private func reconcileOrphanedImageTranslationSharesAtStartup() {
        let root = imageTranslationShareDirectory.standardizedFileURL
        guard let candidates = try? FileManager.default.contentsOfDirectory(
            at: root,
            includingPropertiesForKeys: nil
        ) else {
            return
        }
        for candidate in candidates {
            let directory = candidate.standardizedFileURL
            guard directory.deletingLastPathComponent() == root,
                  UUID(uuidString: directory.lastPathComponent) != nil else {
                continue
            }
            imageTranslationOwnedShareDirectories.insert(directory)
        }
        discardImageTranslationShareCopies()
    }

    private func discardImageTranslationShareCopies() {
        imageTranslationShareRequestID = UUID()
        imageTranslationShareState = .idle
        let root = imageTranslationShareDirectory
        for directory in Array(imageTranslationOwnedShareDirectories) {
            if Self.removeImageTranslationShareDirectory(directory, root: root) {
                imageTranslationOwnedShareDirectories.remove(directory)
            }
        }
    }

    private func retainImageTranslationShareDirectoryIfCleanupFails(
        _ directory: URL,
        root: URL
    ) {
        let managedDirectory = directory.standardizedFileURL
        if !Self.removeImageTranslationShareDirectory(managedDirectory, root: root) {
            imageTranslationOwnedShareDirectories.insert(managedDirectory)
        }
    }

    nonisolated private static func removeImageTranslationShareDirectory(
        _ directory: URL,
        root: URL
    ) -> Bool {
        let managedRoot = root.standardizedFileURL
        let managedDirectory = directory.standardizedFileURL
        guard managedDirectory.deletingLastPathComponent() == managedRoot,
              UUID(uuidString: managedDirectory.lastPathComponent) != nil else {
            return false
        }

        let fileManager = FileManager.default
        guard (try? fileManager.destinationOfSymbolicLink(atPath: managedDirectory.path)) == nil else {
            return false
        }
        guard fileManager.fileExists(atPath: managedDirectory.path) else { return true }
        guard let values = try? managedDirectory.resourceValues(
            forKeys: [.isDirectoryKey, .isSymbolicLinkKey]
        ),
        values.isDirectory == true,
        values.isSymbolicLink != true else {
            return false
        }
        do {
            try fileManager.removeItem(at: managedDirectory)
            return !fileManager.fileExists(atPath: managedDirectory.path)
        } catch {
            return false
        }
    }

    private func discardImageTranslationWorkspaceOrphans(directory: URL) {
        for url in Array(imageTranslationOwnedOrphanURLs) {
            let filename = url.standardizedFileURL.lastPathComponent
            let kind: ImageTranslationManagedFileKind = Self.isImageTranslationInputFilename(filename)
                ? .input
                : .staging
            if Self.removeImageTranslationManagedFile(url, directory: directory, kind: kind) {
                imageTranslationOwnedOrphanURLs.remove(url)
            }
        }
    }

    nonisolated private static func removeImageTranslationManagedExport(
        _ url: URL,
        directory: URL
    ) -> Bool {
        removeImageTranslationManagedFile(url, directory: directory, kind: .stableExport)
    }

    nonisolated private static func removeImageTranslationManagedFile(
        _ url: URL,
        directory: URL,
        kind: ImageTranslationManagedFileKind
    ) -> Bool {
        let managedDirectory = directory.standardizedFileURL
        let managedFile = url.standardizedFileURL
        let filename = managedFile.lastPathComponent
        guard managedFile.deletingLastPathComponent() == managedDirectory,
              isImageTranslationManagedFilename(filename, kind: kind) else {
            return false
        }

        let fileManager = FileManager.default
        guard (try? fileManager.destinationOfSymbolicLink(atPath: managedFile.path)) == nil else {
            return false
        }
        guard fileManager.fileExists(atPath: managedFile.path) else { return true }
        guard let values = try? managedFile.resourceValues(forKeys: [.isRegularFileKey, .isSymbolicLinkKey]),
              values.isRegularFile == true,
              values.isSymbolicLink != true else {
            return false
        }
        do {
            try fileManager.removeItem(at: managedFile)
            return !fileManager.fileExists(atPath: managedFile.path)
        } catch {
            return false
        }
    }

    nonisolated private static func isImageTranslationManagedFilename(
        _ filename: String,
        kind: ImageTranslationManagedFileKind
    ) -> Bool {
        switch kind {
        case .input:
            return isImageTranslationInputFilename(filename)
        case .staging:
            return isImageTranslationStagingFilename(filename)
        case .stableExport:
            return isImageTranslationStableExportFilename(filename)
        }
    }

    nonisolated private static func isImageTranslationInputFilename(_ filename: String) -> Bool {
        guard !filename.hasPrefix("."), filename.count > 37 else { return false }
        let uuidEnd = filename.index(filename.startIndex, offsetBy: 36)
        let separator = filename[uuidEnd]
        let uuid = String(filename[..<uuidEnd])
        let remainder = filename[filename.index(after: uuidEnd)...]
        return separator == "-" && UUID(uuidString: uuid) != nil && !remainder.isEmpty
    }

    nonisolated private static func isImageTranslationStagingFilename(_ filename: String) -> Bool {
        let suffix = ".staging.png"
        guard filename.hasPrefix("."), filename.hasSuffix(suffix) else { return false }
        let stem = String(filename.dropLast(suffix.count))
        guard stem.count > 48 else { return false }
        let uuid = String(stem.suffix(36))
        let prefix = String(stem.dropLast(36))
        return UUID(uuidString: uuid) != nil && prefix.hasSuffix("-translated-")
    }

    nonisolated private static func isImageTranslationStableExportFilename(_ filename: String) -> Bool {
        let prefix = "aitrans-export-"
        let suffix = "-translated.png"
        guard filename.hasPrefix(prefix), filename.hasSuffix(suffix) else { return false }
        let remainder = String(filename.dropFirst(prefix.count))
        guard remainder.count > 36 + 1 + suffix.count else { return false }
        let uuidEnd = remainder.index(remainder.startIndex, offsetBy: 36)
        let uuid = String(remainder[..<uuidEnd])
        let separator = remainder[uuidEnd]
        let baseAndSuffix = remainder[remainder.index(after: uuidEnd)...]
        return separator == "-" &&
            UUID(uuidString: uuid) != nil &&
            baseAndSuffix.count > suffix.count &&
            baseAndSuffix.hasSuffix(suffix)
    }

    nonisolated private static func imageTranslationPixelRect(
        _ box: NormalizedImageRect,
        canvas: CGRect
    ) -> CGRect {
        guard let box = box.normalizedToUnit() else { return .zero }
        return CGRect(
            x: canvas.width * box.x,
            y: canvas.height * box.y,
            width: canvas.width * box.width,
            height: canvas.height * box.height
        )
        .insetBy(dx: -max(canvas.width * 0.004, 3), dy: -max(canvas.height * 0.004, 3))
        .intersection(canvas)
    }

    nonisolated private static func imageTranslationOverlayRect(
        sourceRect: CGRect,
        canvas: CGRect,
        mode: ImageTranslationOverlayMode
    ) -> CGRect {
        guard mode == .adjacent else { return sourceRect }

        let gap = max(canvas.width * 0.008, 4)
        let bubbleWidth = min(
            max(sourceRect.width * 1.45, canvas.width * 0.16),
            canvas.width * 0.46
        )
        let bubbleHeight = min(
            max(sourceRect.height * 1.65, canvas.height * 0.075),
            canvas.height * 0.32
        )
        let rightX = sourceRect.maxX + gap
        let x = rightX + bubbleWidth <= canvas.maxX
            ? rightX
            : max(canvas.minX, sourceRect.minX - gap - bubbleWidth)
        let y = min(
            max(canvas.minY, sourceRect.midY - bubbleHeight / 2),
            canvas.maxY - bubbleHeight
        )
        return CGRect(x: x, y: y, width: bubbleWidth, height: bubbleHeight)
            .intersection(canvas)
    }

    private func currentSessionRecord() -> TranslationSessionRecord {
        TranslationSessionRecord(
            id: activeSessionID,
            title: currentSessionTitle,
            createdAt: activeCreatedAt,
            updatedAt: Date(),
            mode: mode,
            sourceLanguage: sourceLanguage,
            targetLanguage: targetLanguage,
            selectedPromptID: selectedPromptID,
            selectedEngine: selectedEngine,
            durationSeconds: elapsedSeconds,
            transcript: transcript,
            summary: summary
        )
    }

    private func upsertHistory(_ record: TranslationSessionRecord) {
        history.removeAll { $0.id == record.id }
        history.insert(record, at: 0)
        history.sort { $0.updatedAt > $1.updatedAt }
        if history.count > 60 {
            history = Array(history.prefix(60))
        }
    }

    private func sanitizeTranscript(
        _ lines: [TranscriptLine],
        sourceLanguage: SupportedLanguage,
        targetLanguage: SupportedLanguage
    ) -> [TranscriptLine] {
        guard sourceLanguage != targetLanguage else { return lines }
        return lines.filter { line in
            !Self.isInvalidTranslation(
                original: line.original,
                translation: line.translation,
                targetLanguage: targetLanguage
            )
        }
    }

    private static func isInvalidTranslation(
        original: String,
        translation: String,
        targetLanguage: SupportedLanguage
    ) -> Bool {
        if isSameText(original, translation) {
            return true
        }

        let trimSet = CharacterSet.whitespacesAndNewlines.union(.punctuationCharacters)
        let cleanOriginal = original.trimmingCharacters(in: trimSet)
        let cleanTranslation = translation.trimmingCharacters(in: trimSet)
        if !cleanOriginal.isEmpty,
           !cleanTranslation.isEmpty,
           cleanTranslation.localizedCaseInsensitiveContains(cleanOriginal) {
            return true
        }

        if isPlaceholderTranslationOutput(translation) {
            return true
        }

        let promptLeakMarkers = [
            "<start_of_turn>",
            "<end_of_turn>",
            "Translate the following text",
            "Output only the translation",
            "You are a translation engine",
            "Hard rules:",
            "User instruction:",
            "Based on \"",
            "actionable notes",
            "technical plan, timeline, and risks",
            "先确认目标",
            "技术方案、时间线",
            "风险整理成可以执行的清单"
        ]
        if promptLeakMarkers.contains(where: { translation.localizedCaseInsensitiveContains($0) }) {
            return true
        }

        if targetLanguage == .simplifiedChinese {
            return !translation.unicodeScalars.contains { scalar in
                (0x4E00...0x9FFF).contains(Int(scalar.value))
            }
        }

        return false
    }

    private static func isSameText(_ lhs: String, _ rhs: String) -> Bool {
        let trimSet = CharacterSet.whitespacesAndNewlines.union(.punctuationCharacters)
        let left = lhs.trimmingCharacters(in: trimSet)
        let right = rhs.trimmingCharacters(in: trimSet)
        guard !left.isEmpty, !right.isEmpty else { return false }
        return left.localizedCaseInsensitiveCompare(right) == ComparisonResult.orderedSame
    }

    private static func translationTermKey(_ source: String) -> String {
        source
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .folding(options: [.caseInsensitive, .widthInsensitive], locale: .current)
    }

    private func makeImageTranslationPersistenceSnapshot() -> ImageTranslationPersistenceSnapshot? {
        guard imageTranslationState == .translated || imageTranslationState == .failed,
              let sourceURL = imageTranslationSourceURL?.standardizedFileURL,
              let sourceData = imageTranslationData,
              let sourceLanguage = imageTranslationContentSourceLanguage,
              let targetLanguage = imageTranslationContentTargetLanguage,
              !imageTranslationFilename.isEmpty else {
            return nil
        }

        let directory = imageTranslationDirectory.standardizedFileURL
        guard sourceData.isEmpty == false,
              sourceURL.deletingLastPathComponent() == directory,
              Self.isImageTranslationInputFilename(sourceURL.lastPathComponent),
              sourceURL.lastPathComponent == URL(fileURLWithPath: sourceURL.lastPathComponent).lastPathComponent else {
            return nil
        }

        let ignoredSnapshots = imageTranslationIgnoredBlockSnapshots.values
            .sorted { lhs, rhs in
                if lhs.originalOrder == rhs.originalOrder {
                    return lhs.block.id.uuidString < rhs.block.id.uuidString
                }
                return lhs.originalOrder < rhs.originalOrder
            }
            .map { snapshot in
                ImageTranslationIgnoredBlockPersistenceSnapshot(
                    block: snapshot.block,
                    originalOrder: snapshot.originalOrder,
                    visionOriginalBlock: snapshot.visionOriginalBlock,
                    wasManuallyCorrected: snapshot.wasManuallyCorrected
                )
            }
        let activeBlockIDs = imageTranslationBlocks.map(\.id)
        let ignoredBlockIDs = ignoredSnapshots.map { $0.block.id }
        let allBlockIDs = activeBlockIDs + ignoredBlockIDs
        guard !allBlockIDs.isEmpty else { return nil }
        let activeBlockIDSet = Set(activeBlockIDs)
        let visionOriginalBlocks = imageTranslationVisionOriginalBlocks
            .filter { activeBlockIDSet.contains($0.key) }
            .sorted { lhs, rhs in lhs.key.uuidString < rhs.key.uuidString }
            .map(\.value)

        var originalBlockOrder = imageTranslationOriginalBlockOrder
            .sorted { lhs, rhs in
                if lhs.value == rhs.value {
                    return lhs.key.uuidString < rhs.key.uuidString
                }
                return lhs.value < rhs.value
            }
            .map(\.key)
        for blockID in allBlockIDs where !originalBlockOrder.contains(blockID) {
            originalBlockOrder.append(blockID)
        }

        let transcriptLineID = imageTranslationTranscriptLineID.flatMap { lineID in
            transcript.contains(where: { $0.id == lineID }) ? lineID : nil
        }
        return ImageTranslationPersistenceSnapshot(
            sourceFileRelativePath: sourceURL.lastPathComponent,
            sourceFileSHA256: Self.sha256Hex(sourceData),
            sourceFileByteCount: Int64(sourceData.count),
            filename: imageTranslationFilename,
            state: imageTranslationState,
            sourceLanguage: sourceLanguage,
            targetLanguage: targetLanguage,
            blocks: imageTranslationBlocks,
            ignoredBlockSnapshots: ignoredSnapshots,
            visionOriginalBlocks: visionOriginalBlocks,
            reviewedBlockIDs: imageTranslationReviewedBlockIDs.sorted { $0.uuidString < $1.uuidString },
            correctedBlockIDs: imageTranslationCorrectedBlockIDs.sorted { $0.uuidString < $1.uuidString },
            ignoredBlockIDs: ignoredBlockIDs,
            originalBlockOrder: originalBlockOrder,
            overlayMode: imageOverlayMode,
            transcriptLineID: transcriptLineID
        )
    }

    private func restoreImageTranslationPersistenceSnapshot(
        _ snapshot: ImageTranslationPersistenceSnapshot,
        transcript: [TranscriptLine]
    ) -> Bool {
        guard Self.isValidImageTranslationPersistenceSnapshot(snapshot),
              snapshot.sourceFileByteCount <= Int64(Int.max) else {
            return false
        }

        let directory = imageTranslationDirectory.standardizedFileURL
        let sourceURL = directory.appendingPathComponent(
            snapshot.sourceFileRelativePath,
            isDirectory: false
        ).standardizedFileURL
        guard sourceURL.deletingLastPathComponent() == directory,
              sourceURL.lastPathComponent == snapshot.sourceFileRelativePath,
              (try? FileManager.default.destinationOfSymbolicLink(atPath: sourceURL.path)) == nil,
              let values = try? sourceURL.resourceValues(
                  forKeys: [.isRegularFileKey, .isSymbolicLinkKey, .fileSizeKey]
              ),
              values.isRegularFile == true,
              values.isSymbolicLink != true,
              let fileSize = values.fileSize,
              Int64(fileSize) == snapshot.sourceFileByteCount,
              let data = try? Data(contentsOf: sourceURL),
              data.count == Int(snapshot.sourceFileByteCount),
              Self.sha256Hex(data) == snapshot.sourceFileSHA256.lowercased() else {
            return false
        }

        imageTranslationTaskID = UUID()
        imageTranslationContentSourceLanguage = snapshot.sourceLanguage
        imageTranslationContentTargetLanguage = snapshot.targetLanguage
        imageTranslationRetrySourceLanguage = nil
        imageTranslationRetryTargetLanguage = nil
        imageTranslationState = snapshot.state
        imageTranslationMessage = snapshot.state == .translated
            ? "已恢复上次图片翻译会话"
            : "已恢复上次图片翻译结果，可重试未完成文字块"
        imageTranslationData = data
        imageTranslationFilename = snapshot.filename
        imageTranslationSourceURL = sourceURL
        imageTranslationBlocks = snapshot.blocks
        imageTranslationCorrectedBlockIDs = Set(snapshot.correctedBlockIDs)
        imageTranslationReviewedBlockIDs = Set(snapshot.reviewedBlockIDs)
        imageTranslationOriginalBlockOrder = Dictionary(
            uniqueKeysWithValues: snapshot.originalBlockOrder.enumerated().map { index, blockID in
                (blockID, index)
            }
        )
        // Batch membership is intentionally transient and is reconstructed on
        // demand from the authenticated active/ignored block set after restore.
        imageTranslationJapaneseBatchPlan = []
        imageTranslationIgnoredBlockSnapshots = Dictionary(
            uniqueKeysWithValues: snapshot.ignoredBlockSnapshots.map { persisted in
                (
                    persisted.block.id,
                    ImageTranslationIgnoredBlockSnapshot(
                        block: persisted.block,
                        originalOrder: persisted.originalOrder,
                        visionOriginalBlock: persisted.visionOriginalBlock,
                        wasManuallyCorrected: persisted.wasManuallyCorrected
                    )
                )
            }
        )
        imageTranslationVisionOriginalBlocks = Dictionary(
            uniqueKeysWithValues: snapshot.visionOriginalBlocks.map { block in (block.id, block) }
        )
        for persisted in snapshot.ignoredBlockSnapshots {
            guard let originalBlock = persisted.visionOriginalBlock else { continue }
            imageTranslationVisionOriginalBlocks[persisted.block.id] = originalBlock
        }
        imageTranslationIgnoredBlocks = []
        imageOverlayMode = snapshot.overlayMode
        imageTranslationTranscriptLineID = snapshot.transcriptLineID.flatMap { lineID in
            transcript.contains(where: { $0.id == lineID }) ? lineID : nil
        }
        imageTranslationRevision += 1
        imageTranslationBlockRerecognitionCompletedBlockID = nil
        isProcessing = false
        refreshImageTranslationIgnoredBlocks()
        return true
    }

    private static func isValidImageTranslationPersistenceSnapshot(
        _ snapshot: ImageTranslationPersistenceSnapshot
    ) -> Bool {
        let hexCharacters = CharacterSet(charactersIn: "0123456789abcdefABCDEF")
        guard snapshot.schemaVersion == ImageTranslationPersistenceSnapshot.currentSchemaVersion,
              snapshot.sourceFileByteCount > 0,
              snapshot.sourceFileRelativePath == URL(fileURLWithPath: snapshot.sourceFileRelativePath).lastPathComponent,
              !snapshot.sourceFileRelativePath.isEmpty,
              isImageTranslationInputFilename(snapshot.sourceFileRelativePath),
              !snapshot.filename.isEmpty,
              sanitizedImageFilename(snapshot.filename) == snapshot.filename,
              snapshot.state == .translated || snapshot.state == .failed,
              snapshot.sourceFileSHA256.count == 64,
              snapshot.sourceFileSHA256.unicodeScalars.allSatisfy({ hexCharacters.contains($0) }) else {
            return false
        }

        let activeIDs = snapshot.blocks.map(\.id)
        let ignoredIDs = snapshot.ignoredBlockSnapshots.map { $0.block.id }
        let allIDs = activeIDs + ignoredIDs
        let activeIDSet = Set(activeIDs)
        let ignoredIDSet = Set(ignoredIDs)
        let visionOriginalIDs = snapshot.visionOriginalBlocks.map(\.id)
        guard !allIDs.isEmpty,
              Set(activeIDs).count == activeIDs.count,
              Set(ignoredIDs).count == ignoredIDs.count,
              activeIDSet.isDisjoint(with: ignoredIDSet),
              Set(snapshot.ignoredBlockIDs) == ignoredIDSet,
              snapshot.ignoredBlockIDs.count == ignoredIDSet.count,
              Set(snapshot.originalBlockOrder) == Set(allIDs),
              snapshot.originalBlockOrder.count == allIDs.count,
              Set(visionOriginalIDs).count == visionOriginalIDs.count,
              Set(visionOriginalIDs).isSubset(of: activeIDSet),
              Set(snapshot.reviewedBlockIDs).count == snapshot.reviewedBlockIDs.count,
              Set(snapshot.correctedBlockIDs).count == snapshot.correctedBlockIDs.count,
              Set(snapshot.reviewedBlockIDs).isSubset(of: activeIDSet),
              Set(snapshot.correctedBlockIDs).isSubset(of: activeIDSet) else {
            return false
        }

        let allBlocks = snapshot.blocks
            + snapshot.ignoredBlockSnapshots.map(\.block)
            + snapshot.visionOriginalBlocks
        guard allBlocks.allSatisfy({ block in
            !block.original.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                && block.boundingBox.normalizedToUnit() != nil
                && (block.automaticBoundingBox == nil || block.automaticBoundingBox?.normalizedToUnit() != nil)
        }) else {
            return false
        }

        for ignored in snapshot.ignoredBlockSnapshots {
            guard snapshot.originalBlockOrder.firstIndex(of: ignored.block.id) == ignored.originalOrder else {
                return false
            }
        }
        return true
    }

    private static func sha256Hex(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }

    private func restoreSnapshot() {
        isRestoring = true
        defer { isRestoring = false }

        guard let snapshot = Self.loadSnapshot(from: persistenceURL) else {
            applySeedSession(settings: .defaultValue)
            prompts = PromptTemplate.defaultPrompts
            return
        }

        prompts = Self.mergeDefaultPrompts(with: snapshot.prompts)
        translationTermMemory = snapshot.translationTerms
        history = snapshot.history.map { record in
            var sanitizedRecord = record
            sanitizedRecord.transcript = sanitizeTranscript(
                record.transcript,
                sourceLanguage: record.sourceLanguage,
                targetLanguage: record.targetLanguage
            )
            return sanitizedRecord
        }
        applySettings(snapshot.settings)

        if let activeSession = snapshot.activeSession {
            activeSessionID = activeSession.id
            activeCreatedAt = activeSession.createdAt
            elapsedSeconds = activeSession.durationSeconds
            transcript = sanitizeTranscript(
                activeSession.transcript,
                sourceLanguage: activeSession.sourceLanguage,
                targetLanguage: activeSession.targetLanguage
            )
            summary = activeSession.summary
        } else {
            applySeedSession(settings: snapshot.settings)
        }

        if let imageSnapshot = snapshot.imageTranslationSession {
            _ = restoreImageTranslationPersistenceSnapshot(
                imageSnapshot,
                transcript: transcript
            )
        }

        if !prompts.contains(where: { $0.id == selectedPromptID }) {
            selectedPromptID = PromptTemplate.translatorID
        }
    }

    private func applySettings(_ settings: AppSettings) {
        mode = settings.mode
        sourceLanguage = settings.sourceLanguage
        targetLanguage = settings.targetLanguage
        selectedPromptID = settings.selectedPromptID
        selectedEngine = settings.selectedEngine
        sampling = settings.sampling
        isProUnlocked = settings.isProUnlocked
        isDeveloperModeEnabled = settings.isDeveloperModeEnabled
        if !canUseLanguage(targetLanguage) {
            targetLanguage = .simplifiedChinese
        }
    }

    private func applySeedSession(settings: AppSettings) {
        applySettings(settings)
        activeSessionID = UUID()
        activeCreatedAt = Date()
        elapsedSeconds = 0
        transcript = [
            TranscriptLine(
                speaker: "Speaker A",
                original: "And then I'm thinking there are some things we should care about.",
                translation: "然后我在想，有些事情我们应该重点关注。",
                time: "11:54",
                isFinal: true
            ),
            TranscriptLine(
                speaker: "Speaker B",
                original: "But for the stuff that you can do today, can we summarize the key decisions?",
                translation: "但对于你今天能做的事情，我们可以先总结关键决策吗？",
                time: "11:55",
                isFinal: true
            )
        ]
        summary = AISummary(
            bullets: [
                "当前为离线 AI 翻译工作台原型。",
                "录音、翻译和总结流程已使用 Mock 数据串联。",
                "当前会话、历史记录、提示词和设置都会写入本地 JSON。"
            ],
            actions: [
                "点击录音按钮开始模拟实时转录。",
                "输入自定义文本后点击发送，触发当前引擎翻译。",
                "到提示词页面切换或创建提示词，生成请求会立即使用新设置。"
            ],
            title: "实时总结"
        )
    }

    private func persist() {
        guard !isRestoring else { return }
        let snapshot = AppPersistenceSnapshot(
            activeSession: shouldArchiveCurrentSession ? currentSessionRecord() : nil,
            history: history,
            prompts: prompts,
            settings: AppSettings(
                mode: mode,
                sourceLanguage: sourceLanguage,
                targetLanguage: targetLanguage,
                selectedPromptID: selectedPromptID,
                selectedEngine: selectedEngine,
                sampling: sampling,
                isProUnlocked: isProUnlocked,
                isDeveloperModeEnabled: isDeveloperModeEnabled
            ),
            translationTerms: translationTermMemory,
            imageTranslationSession: makeImageTranslationPersistenceSnapshot()
        )
        Self.save(snapshot, to: persistenceURL)
    }

    private func makeSessionTitle(from lines: [TranscriptLine]) -> String {
        guard let first = lines.first else { return "新同传会话" }
        let base = first.original.isEmpty ? first.translation : first.original
        let trimmed = base.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return "新同传会话" }
        return trimmed.count > 22 ? "\(trimmed.prefix(22))..." : trimmed
    }

    private static func makePersistenceURL() -> URL {
        let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        return base
            .appendingPathComponent("AITRANS", isDirectory: true)
            .appendingPathComponent("state.json")
    }

    private static func loadSnapshot(from url: URL) -> AppPersistenceSnapshot? {
        guard FileManager.default.fileExists(atPath: url.path) else { return nil }
        do {
            let data = try Data(contentsOf: url)
            let decoder = JSONDecoder()
            decoder.dateDecodingStrategy = .iso8601
            return try decoder.decode(AppPersistenceSnapshot.self, from: data)
        } catch {
            return nil
        }
    }

    private static func save(_ snapshot: AppPersistenceSnapshot, to url: URL) {
        do {
            try write(snapshot, to: url)
        } catch {
            assertionFailure("Failed to persist AITRANS state: \(error.localizedDescription)")
        }
    }

    private static func write(_ snapshot: AppPersistenceSnapshot, to url: URL) throws {
        let directory = url.deletingLastPathComponent()
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        let data = try encoder.encode(snapshot)
        try data.write(to: url, options: .atomic)
    }

    private static func mergeDefaultPrompts(with savedPrompts: [PromptTemplate]) -> [PromptTemplate] {
        var merged = PromptTemplate.defaultPrompts
        for prompt in savedPrompts where !merged.contains(where: { $0.id == prompt.id }) {
            merged.append(prompt)
        }
        return merged
    }

    private static func containsCJK(_ text: String) -> Bool {
        text.unicodeScalars.contains { scalar in
            (0x4E00...0x9FFF).contains(Int(scalar.value))
        }
    }

    private static func cjkCharacterCount(in text: String) -> Int {
        text.unicodeScalars.count { scalar in
            (0x4E00...0x9FFF).contains(Int(scalar.value))
        }
    }

    private static func containsLatinLetter(_ text: String) -> Bool {
        text.unicodeScalars.contains { scalar in
            (0x41...0x5A).contains(Int(scalar.value)) || (0x61...0x7A).contains(Int(scalar.value))
        }
    }

    private static func latinLetterCount(in text: String) -> Int {
        text.unicodeScalars.count { scalar in
            (0x41...0x5A).contains(Int(scalar.value)) || (0x61...0x7A).contains(Int(scalar.value))
        }
    }

    private static func containsLikelyOCRError(in text: String) -> Bool {
        let upper = text.uppercased()
        let suspiciousTokens = [
            "RATTLER",
            "PEN DAYS",
            "TRANINS",
            "WOLLD",
            "ONLING",
            "PESULTE",
            "SAMING",
            "POOM",
            "BENG",
            "SUGSESTION",
            "LOSIC",
            "THOUSH",
            "SENPARS",
            "-O2",
            "02 AT"
        ]
        if suspiciousTokens.contains(where: { upper.contains($0) }) {
            return true
        }

        let words = upper
            .components(separatedBy: CharacterSet.alphanumerics.inverted)
            .filter { $0.count >= 3 }
        guard words.count >= 4 else { return false }

        let repeatedWords = zip(words, words.dropFirst()).filter { $0 == $1 }.count
        if repeatedWords > 0 {
            return true
        }

        let veryShortWords = words.filter { $0.count <= 2 }.count
        return words.count >= 8 && veryShortWords >= words.count / 3
    }

    private static func ocrQualityLabel(for similarity: Double) -> String {
        if similarity >= 0.9 {
            return "good"
        }
        if similarity >= 0.72 {
            return "usable"
        }
        if similarity > 0 {
            return "lowSimilarity"
        }
        return "noGroundTruthMatch"
    }

    private static func isPlaceholderTranslationOutput(_ output: String) -> Bool {
        TranslationOutputPolicy.isPlaceholderResponse(output)
    }

    private func logLaunchLLMSmokeTestResult(_ test: LLMInterfaceSmokeTest) {
#if DEBUG
        guard Self.shouldRunLLMSmokeTestFromLaunchEnvironment else { return }
        let output = test.output.replacing("\n", with: "\\n")
        writeLaunchLLMSmokeProbe(
            "result state=\(test.state.rawValue) engine=\(test.engineName) output=\(output) message=\(test.message)"
        )
        print(
            "AITRANS_LLM_SMOKE_RESULT state=\(test.state.rawValue) " +
            "engine=\(test.engineName) " +
            "input=\(test.input) " +
            "output=\(output) " +
            "message=\(test.message)"
        )
#endif
    }

    private func writeLaunchLLMSmokeProbe(_ message: String) {
#if DEBUG
        guard Self.shouldRunLLMSmokeTestFromLaunchEnvironment else { return }
        let directory = persistenceURL.deletingLastPathComponent()
        let url = directory.appendingPathComponent("llm-smoke-result.log")
        let line = "\(Date.now.ISO8601Format()) \(message)\n"
        try? FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        if FileManager.default.fileExists(atPath: url.path),
           let handle = try? FileHandle(forWritingTo: url) {
            handle.seekToEndOfFile()
            handle.write(Data(line.utf8))
            try? handle.close()
        } else {
            try? Data(line.utf8).write(to: url, options: .atomic)
        }
#endif
    }

